INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgündeki Bir Kadına', 'surgundeki-bir-kadina-turgay-uceren-0elz1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(M. Vurgun''a) 

karanfillerin öldüğü zamanlardı

kevgir gibi gök, yüzümüzde acı

bir gülümseyişten kalma bıçak izi

yaylım ateşinde kurşunlanmış 

bakışlarla

-pişmanlık katılmış bir diriliş için 

ölümü beklemek haramdı bize-

ölürken şarkı söyledik hep

yarın yarın, yarınlara

hep çıkmaz sokaklarda bitti duvarlar

kan izi ve kurşun yarası taşıyan

şimdi yangınlar sonrası

aydınlanıyor karanlık tarih

hiç olmayan mezartaşlarının gölgelerinde

kararmış halkımın yüzü

çok uzaktan duyuyorum seni

haykırıya tırmanan 

-hep aynı-

bilirim

hiç değişmez acının sesi

senin şiirlerinde unutuş yok

şimdi de çünki ölüm

ve tünek olmuş martılara

kimi dizelerin

binlerce yürek, bir yürekte

senin yüreğinde toplanıp

bir sel gibi akıp

sürüklenmişlerin sesi

boğdurulmuşlar denizinden

esen bir yel gibi

bir şarkı söyler gibi

yarın yarın, yarınlara

kuşunların ıslık seslerinden kalma 

acı bir ezgi

-paslanmıyor aslında

yüreklerimize saplanan

mermi çekirdekleri-

isli gaz lambalarında hatıranın alevi

hala söylediğimiz yangın türkülerinde

düşük omuzlarında taşıdığın ağır yük

arkadaş cenazelerinden kalma

şimdi pasın olgunluğunda

konuşur eski tüfek anılar

ah...sen, uzak bir ülkede

başka gökler altında

sen, vurgun kızı sürgünün

çocukluk göklerinden uzak

ülkenin dağlarında kekikler ıslak

şimdi, sabah bir yalnızlık bekler gibi

uzak bir ülkede şafağa durmuş gözlerin

yarınıları beklemekte

gün doğarken sisler içinden', '(M. Vurgun''a)  karanfillerin öldüğü zamanlardı kevgir gibi gök, yüzümüzde acı bir gülümseyişten kalma bıçak izi yaylım ateşinde kurşunlanmış...', ARRAY['Türk Edebiyatı','Şiir','Turgay Uçeren']::text[], 8.5, '{"poet":"Turgay Uçeren","poet_slug":"turgay-uceren","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/surgundeki-bir-kadina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardın...Yoksun...', 'vardin-yoksun-turgay-kadiroglu-444rz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne vakit kazdın sineme

bir yüreklik mezarı? 

ne vakit üşüdü sıcaklığın elimde

kefensiz kaldı kalbim, 

sevmelerin, kılıfıydı yüreğimin.

kalem silkelendi, aktı kelam, 

acıdıkça kuytular

sızladı dizdiğim mısralar...

kefenim beyaz, 

defterim beyaz, 

yüreğime koyduğum ellerim

titrektir, ürkektir, 

sıcaktır, 

yed-i beyzadır, 

soyunduğu vakit geceler aydınlanır

zifiri vakitlerde çöller ısınır...

vardın.

vardım.

yüreğime yardın, 

sen gir diye

yüreğimi yardım, 

bilinmeze kanatlandın, 

ötelere vardın, 

gel hüzün vadime, 

yakıyor sensizlik, 

acıyor kalbim, 

gel ey yar, insaf et

yüreğime yardım...

yoksun.

yokum.

nefes alan beden, 

canından yoksun.

yokluğuna alışmak zor-aki, 

gelmeyeceğini bilmesem, 

seni beklemek kolay

gonca yaprağı kadar ümit beslesem.

yine şubat 

yayılmış kışın ortasına, 

çiçek getirmiyorum artık şubat buluşmalarına, 

seni beklediğim her gün için, 

bir gül dikiyorum tepelerine bu şehrin, 

istanbul kanatlıyor

sana adanmış

bilmediğin, 

senden bihaber 

bahçesini çamlıcanın...

ben senden ne vakit geçerim, 

sen söyle minik serçe, 

nasıl ki ölüm seçilmez, 

nasıl ki adanmaz geçmişe adak, 

sen söyle ey serçe, 

sezen aksu sen söyle, 

yanarken içilir mi aşk şerbeti, 

yanarken geçilir mi dicleden, 

yanarken geçilir mi sevgiden...', 'ne vakit kazdın sineme bir yüreklik mezarı?  ne vakit üşüdü sıcaklığın elimde kefensiz kaldı kalbim,  sevmelerin, kılıfıydı yüreğimin. kalem...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/vardin-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüme Gel', 'dusume-gel-bekir-mutlu-gokcesu-6n08s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Işığı yakma

Sesime gel

Soyun hüznü

Soyun usulca

Sarın gecenin tülünü

Ardına bakma

Düşüme gel', 'Işığı yakma Sesime gel Soyun hüznü Soyun usulca Sarın gecenin tülünü Ardına bakma Düşüme gel...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dusume-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreksiz', 'yureksiz-nilay-aksu-awa4b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kanımda dolaşan bir zehirdi bu gece sensizlik 

Bir cinnet anının tek kurşunuyla vurulmuştum 

Intiharımdı geceyi kanıma boyayan 

Sonrası karanlıktı 

Ne sabaha umutlu 

Ne geceyle dost 

Bir savaş alanıydı yüreğim 

Dipçiği kendi böğrüne saplamış 

Bir şaşkın askerdim 

Yokluğun mu en çok kanadı 

Mahçubiyetim mi 

Bilemedim 

Sudan korkup karada boğulan bir acemiydim belki 

Kendi boğazıma sımsıkı yapışmıştı ellerim 

Bırakın öleyim diyecek kadar 

Yürekliydim belki 

Koşun yetişin diyemeyecek kadar 

Yüreksiz 

Kendi yüreğine bir dinamit koyup 

Enkazinda ağlayan bir aptaldım belki 

Düşlerin altında can vermek nedir bilen var mı 

Çiçeğe durmuş bir bahar dalının 

Don vurmuş tomurcukları için için ağlar mı 

Düş kırıkları batmasa yüreğime 

Ağlamazdım yine de 

Geceye küssem canım yanmazdı 

Ellerime küsmüştüm en çok 

Yüreğimi söküp çıkartan onlardı 

Yüreksiz kalmak mı canımı yakandı 

„Yüreksiz“ acemi bir şaşkın olmak mı 

Hayat damarımı ellerimle kestim ben 

Tek hamlede 

Kendi suyunda boğulmak neydi bu katliamın yanında 

Acemi şaşkın yüreksiz bir asker gibi 

Kendi ellerimde can verdim', 'Kanımda dolaşan bir zehirdi bu gece sensizlik  Bir cinnet anının tek kurşunuyla vurulmuştum  Intiharımdı geceyi kanıma boyayan  Sonrası kara...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yureksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasat', 'hasat-ahmet-aksoy-ov8er', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamana ırgattır her insan

ki çalışır yaşamak için

bir ölümlük ömürde

savaşır kendi için

lakin ne çalışmak

ne de savaşmak erdirir sonsuza

dünya için yapılan

toz olur karışır rüzgara

ki verilir doğumla, bir tarla, 

ekilmek için, her insana, 

iki bölümlü, iki parça, 

kazanmak için iki dünyada

lakin kimi eker, zevki sefa

kimi eker inanç ve

hasat vakti gelir, ayrılır, 

çürük çürüğe sağlam sağlama', 'zamana ırgattır her insan ki çalışır yaşamak için bir ölümlük ömürde savaşır kendi için lakin ne çalışmak ne de savaşmak erdirir sonsuza dün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çın', 'cin-ahmet-aksoy-mgilw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sobaasız bir ev gibi sensizliğim

''Soğuk''

Ki bir çiğ gibi damlarken

Çıplak bedenime umut

''Sensizim''

Ve gidenim

Sen giderken boşalttın içimi

Terk edilmiş bir ev gibi

Ki sanki

Nokta düşse çın-la-ya-cak.', 'Sobaasız bir ev gibi sensizliğim ''Soğuk'' Ki bir çiğ gibi damlarken Çıplak bedenime umut ''Sensizim'' Ve gidenim Sen giderken boşalttın içimi T...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katliam', 'katliam-oguzkan-bolukbasi-3rn91', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yaşamın ölmeyen bir yeriyim

Sevgiye dönüşmüş  enerjiyim

Bu sevgi yeniden enerjiye dönerse

Yüreklerde patlayacağım

Katliam olacak', 'Ben yaşamın ölmeyen bir yeriyim Sevgiye dönüşmüş  enerjiyim Bu sevgi yeniden enerjiye dönerse Yüreklerde patlayacağım Katliam olacak...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/katliam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler mi Oluyor Buralarda?', 'neler-mi-oluyor-buralarda-ali-osman-yilmaz-oee97', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neler oluyor demişti oralarda, Merak içinde, 

Dedim; bir güzel ava çıkmış, elinde kocaman olta, 

Bir aşık dolanır ortalarda, kos kocaman bir alık, 

Etrafı dört duvar, hapishanesinde atmakta volta.

Oltanın ucuna takmış / bembeyaz bir Mine/

Kocaman bir balık / zokayı yutmuş mu ne? 

Çok büyük bir balık / Balina mı / Koca Adam mı ne? 

Çeker keyifle sudan / Başlar def çalıp  eğlenmeye.

Aşığın cezasını kesmiş hakim / hücrede müebbed, 

Suçu / aşık olmak / karşılıksız sevmek bir güzeli, 

İnanmak  safiyane gönlüyle, sarılmak bir kızıl güle, 

Kanıyor şimdi yüreği, sarılınca o kızıl gülün dikenine.

Ah demez aşık, yansada ateşinde sevdanın, 

Hangi aşık ödememiş bedelini / karşılıksız sevmenin, 

Sevmek güzel şey, hepiniz sevin /sevilin, amma! ! ! 

Sevecekseniz adam gibi sevin/sevenlerle asla alay etmeyin.

Bursa  05.Kasım.2003   Veda etmeden önce.', 'Neler oluyor demişti oralarda, Merak içinde,  Dedim; bir güzel ava çıkmış, elinde kocaman olta,  Bir aşık dolanır ortalarda, kos kocaman bir...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/neler-mi-oluyor-buralarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimde Çizdim Resmini', 'duslerimde-cizdim-resmini-ali-osman-yilmaz-0c1b4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerimde çizdim en güzel resmini, 

Duvarıma asmıştım şiirlerinde seni, 

Tuttum duvardan indirdim bu gün seni, 

İnan güzelim, duvar ağlamaya başladı, 

Hıçkırıklar içinde duvar, şimdi yanıyor, 

Mızrak olmuş sevdan, parçalamış bak, 

Koca adamın yüreği, Oluk, oluk kanıyor.

Bursa  05.Kasım.2003 Duvarla Karşı Karşıya', 'Düşlerimde çizdim en güzel resmini,  Duvarıma asmıştım şiirlerinde seni,  Tuttum duvardan indirdim bu gün seni,  İnan güzelim, duvar ağlamay...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duslerimde-cizdim-resmini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Benim Hakkımdır.', 'sevmek-benim-hakkimdir-ali-osman-yilmaz-j8grt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suyun öte yakasından gelen güzel, 

Bırak sevdamla baş başa beni, 

Gönül bu, dilediğim gibi seveyim seni, 

Sevmek eğer suçsa, lütfen bağışla beni, 

Sevmiyorsan sevme, kızıl saçlı güzelim, 

Ne zaman istedim, senden beni sevmeni? 

Bursa.Kasım.2003', 'Suyun öte yakasından gelen güzel,  Bırak sevdamla baş başa beni,  Gönül bu, dilediğim gibi seveyim seni,  Sevmek eğer suçsa, lütfen bağışla ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevmek-benim-hakkimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bursa''nın ipeğinden gibi', 'bursa-nin-ipeginden-gibi-huseyin-cayikli-xftxc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bursa''nın ipeği gibi dokundum ellerine...biçimsiz sevdim seni..

Tayyare''de bir oyun vardır şimdi birisinin hayatından parçadır...bu edebiyat ikimizi yakınlaştırır belki.Bursa''nın ipeği gibi dokundu sevgin bana dokudum onu ipek halı gibi taşıdım ağırlıgıni...bir oyun oynanıyor Tayyare''de belki benim oyunumdur...sahnede iki pandomim ustası senin bana uzaklığını anlatır...ne kadar uzaksan bana ben yinede sana bir oyun yazıyorum bursanın ipeğinden sevgi yumağı sararak...Bursa''nın ipeği gibi dokundum ellerine sevdim galiba seni Tayyare''nin içinde oynanan oyun gibi...', 'Bursa''nın ipeği gibi dokundum ellerine...biçimsiz sevdim seni.. Tayyare''de bir oyun vardır şimdi birisinin hayatından parçadır...bu edebiyat...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bursa-nin-ipeginden-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-refik-yildiz-qk8p4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlemin kor oldu dudaklarımda

Dertli dertli çalan kaval sesimdir

Bir taşınmaz sırra olmuşken hamal

Lal dilli ney, ney nefesimdir

Yalnızlığın dile geldiği beste

Gurbeti anlatan şarkı sesimdir

Hissederim söyleyemem derdimi

Akan gözyaşları, kor nefesimdir

Issız gecelerde mahzun muzdarip

Ağlarım inlerim dua sesimdir

El açarım reddedilmez divana

İçimde hissettiğim ''dost nefesin''dir', 'Özlemin kor oldu dudaklarımda Dertli dertli çalan kaval sesimdir Bir taşınmaz sırra olmuşken hamal Lal dilli ney, ney nefesimdir Yalnızlığın...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Yanıyor Yüreğim?', 'neden-yaniyor-yuregim-hikmet-karakus-wjlep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bahar oynaşırken rüzgarla 

                            yeşil yeşil, 

Kuşlar sevinç çığlıklarıyla 

                    cilveleşirken, 

Sevginin çiçeğe durduğu, 

Öfkelerin dindiği yer burası, 

Sakın bir şey söyleme, 

Yalnızlığıma düşeceğim 

     neden yanıyor yüreğim? 

(Ank.2002)

Hikmet Karakuş', 'Bahar oynaşırken rüzgarla                              yeşil yeşil,  Kuşlar sevinç çığlıklarıyla                      cilveleşirken,  Sevgin...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/neden-yaniyor-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsarlık', 'karamsarlik-refik-yildiz-8yj3j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ışık ararım karanlık gecelerde

Yeisin güneşleri batırdığı demlerde

Işıklı sokaklar içimi ışıldatmaz

Çıkıversem dağlara, içim dağlara sığmaz

Bu halin adı ne, bu ızdırap nedendir

Elem dolu her yanım, herşey zaten elemdir

Dünyaya ne beğlar beni, dünya nedir

Döner durur akılda, akıl cevap bulamaz

Bir kaval sesi duysam tenim sese dönüşse

O ses beni alıp başka ile götürse

Biliyorum nafile

Gönlüm huzur bulamaz...', 'Bir ışık ararım karanlık gecelerde Yeisin güneşleri batırdığı demlerde Işıklı sokaklar içimi ışıldatmaz Çıkıversem dağlara, içim dağlara sığ...', ARRAY['Türk Edebiyatı','Şiir','Refik Yıldız']::text[], 8.5, '{"poet":"Refik Yıldız","poet_slug":"refik-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karamsarlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk Ömürler,', 'arabesk-omurler-caglar-akarsu-gzp42', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...

Genç çocuk, dalgın gözlerini, 

Önünde uzayıp giden, yollara

Bin bir düşünce yükledi aklına, 

Ezilmişti  bir anda her şey, 

Virajı alamayan tekerlerler  gibi, 

Kaydı önünde düşünceler, sanki, 

..

Bazen derin bir sevda oldu

Yüreğini sardı ateşi, yangın yeri

Aldı tutuştu, her şeylerini, 

Geceleri elindeki direksiyon, 

Gündüzleri, içindeki hüzün, 

Yanı başında eski bir radyo, 

Arabesk  müziğini çalıyordu, 

...

Tahta kalenin ücra yokuşlarını, 

Tırmanırken, günler boyu, 

Bir yanda emek kavgası, 

Bir yanda sevda yüklü yüreği, 

İçi ve dışı, her yeri arabesk olmuştu, 

...

Bağırdı, kahveciye, “bir çay”

Yanında bir de arabesk türkü, 

Paylaştı dertlerini, içini çekerek, 

Sildi, gözyaşlarını, kol ucu ile, 

Birinci sigarası dudağında, 

Sallanırken, duman acı doldu, 

Yangın yeri olan yüreğine, 

...

Arabeskli ömür seçmişti, 

Figan dolu sözlerin kavgası, 

Yaşam çizgisini, hiç değişmedi

Şimdi gurbet yollarında, 

Teybinde  acılı bir kaset, 

Bağıra-bağıra yoluna gidiyordu, 

Artık “umurumda değil dünya! ””

..

4/kasım/2003', '... Genç çocuk, dalgın gözlerini,  Önünde uzayıp giden, yollara Bin bir düşünce yükledi aklına,  Ezilmişti  bir anda her şey,  Virajı alamay...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/arabesk-omurler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımak,', 'tanimak-caglar-akarsu-05fds', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanımak, 

..

Bir tanım bulmak için uğraştım, 

Yıllar nasıl da akıp gitmişti, 

İnsanları anlamak için, 

Her sözü yorumlamak lazımsa, 

Elimde bir “ sözlük” baka –baka

Dolaştım durdum, çevrelerinde, 

..

Burası “ er meydanı” ise, 

Kırk pınar ağaları, bir nara attı, 

“lan  teker –teker gelin”

“erkeklik  yerde kalmasın” dedi, 

Bir güreş orta yerde, kıran kırana, 

İnsan bu, eğer çözülmezse, 

Güç bazen  elinde kalır, 

Kuvvet kullanmak her çare değil! 

Güç bazen sözünde olur, 

Dilini bıçak gibi kullanan kimse.

İnsan bu, homojen bir yapıda, 

Her şekle bir anda dönüşür, 

Zemin kaypaksa  bir an, 

Ayaklarındaki karpuz kabuğu, 

Kayar da alır götürür, 

Kendini  tanıyan bir kişi, 

Meydanda çıkış kapısını, 

Ne kadar söz, ne kadar güç, 

Sarf etmek  istese bile, 

Azmi ile bir gün doğruyu bulur.

...

2003-11-05

cağlar akarsu', 'Tanımak,  .. Bir tanım bulmak için uğraştım,  Yıllar nasıl da akıp gitmişti,  İnsanları anlamak için,  Her sözü yorumlamak lazımsa,  Elimde ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tanimak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olgun Yaştayım', 'olgun-yastayim-muammer-celik-5l9rv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazanda güz oldu 

yaş tam doldu 

gündüzler kısalıyor 

olgunlaşıyor kişilik 

geceler daha da uzun artık

Ömrun kısa dönemi başlıyor 

yapraklar dökülüyor birer birer 

üzümler, narlar da 

yeni yeni toplanıyor oysa

Her güzelliğin ifade edildiği 

Kırktepeler

kırkpınarlar 

kırkhaneler 

kırkbir maşaallah''lar 

bu mevsimde bozulur bağlar 

pekmezler de kaynatırlar 

ve

tarlalar yeni yeni 

ekilmeye başlanıyor oysa…! 

BirDeli

1 eylul 2000', 'Hazanda güz oldu  yaş tam doldu  gündüzler kısalıyor  olgunlaşıyor kişilik  geceler daha da uzun artık Ömrun kısa dönemi başlıyor  yapraklar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olgun-yastayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yararız', 'neye-yarariz-muammer-celik-0crgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yapamayiz

