INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla Gelen Kadın', 'yagmurla-gelen-kadin-yasemin-kaplan-3v811', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmurla gelen kadın

bir yanı hüzne bakan

güne bakan

sana bakan

hangisi yanılttı 

aklım mı yüreğim mi...

herkesin bir bilge yanı, 

iyi bilirdik diyen dostları

''merhume'' yi nasıl bilirdiniz.

''merhume'' kendini nasıl bilirdi

tanrı aşkına

''merhume'' sizi nasıl severdi

sahi ne zaman gitti?', 'yağmurla gelen kadın bir yanı hüzne bakan güne bakan sana bakan hangisi yanılttı  aklım mı yüreğim mi... herkesin bir bilge yanı,  iyi bilir...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kaplan']::text[], 8.5, '{"poet":"Yasemin Kaplan","poet_slug":"yasemin-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmurla-gelen-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarı Deli, Yarı Aşık', 'yari-deli-yari-asik-orcun-oruc-aykac-vgbw9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca zaman içimde bir sen taşıdım

Bir yanım deli, bir yanım aşıktı

Aşkımı delilik sandın, 

Deliliğimi aşka sıvadın

Oysa ben sadece delicesine aşıktım

Ve seninle ölümüne yaşadım.', 'Bunca zaman içimde bir sen taşıdım Bir yanım deli, bir yanım aşıktı Aşkımı delilik sandın,  Deliliğimi aşka sıvadın Oysa ben sadece delicesi...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yari-deli-yari-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör Beni Beni', 'gor-beni-beni-salim-solmazgul-b62x8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimden haberin olsun

Yanarım aşkınla gör beni beni

Ben neler çekerim eller ne bilsin

Zalim gecelere sor beni beni

Halden anlamadı sevdi yüreğim

Farkım kalmadı ki Mecnunla benim

İnan yalnızlıktan üşür bedenim

Ne olursun güzel sar beni beni

Güvenme zamana çabucak geçer

İhtiyar oluruz bu gençlik biter

Solmazgül ün gözü açık mı gider

Eğer sever isen bir beni beni', 'Seni sevdiğimden haberin olsun Yanarım aşkınla gör beni beni Ben neler çekerim eller ne bilsin Zalim gecelere sor beni beni Halden anlamadı ...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gor-beni-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Ol, Ya Olma', 'ya-ol-ya-olma-hakki-hakan-kaya-02je8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya geceye ay ol, ya gündüze güneş, 

Ya derdime ilaç ol, ya derdime sırdaş, 

Bir yol var yürünmesi gereken, 

Ya yoluma ortak ol, ya yolumda yoldaş.

Ya ışığıma gündüz ol, ya karanlığıma gece, 

Ya geçmişimde kaybol, ya anımda andaş, 

Çözülmez bir anagramsın belki bir bilmece, 

Ya yanıma hayal ol, ya yanımda yandaş.

Çözemedim seni ne amaçlısın, 

Bazen anlayışlı bazen alaycısın, 

Vücudumda yaşayan bir yabancısın, 

Ya kanıma zehir ol, ya kanımda dolaş.', 'Ya geceye ay ol, ya gündüze güneş,  Ya derdime ilaç ol, ya derdime sırdaş,  Bir yol var yürünmesi gereken,  Ya yoluma ortak ol, ya yolumda y...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ya-ol-ya-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni bende yaşıyorum', 'ben-seni-bende-yasiyorum-muammer-celik-qfv6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirlerde yazıyorum

şiirlerde boğuşuyorum

kavga ediyorum 

tartışıyorum

ve 

döğüşüyorum seninle…

Şiirlerde seviyorum yüreğini

şiirlerde okşuyorum hayalini

şiirlerde yaşıyorum varlığını

ve 

şiirlerde sevişiyorum seninle...

Hepsi sana bu coşkularım

hepsi sana bu duygularım

birde sen sevebilsen ahhh

birde sen sevebilsen beni…

Ben bende seviyorum seni

ben şiirde okşuyorum seni

Ben şiirim

Ben duyguyum

Ben hep sana doluyum

Anadolu’yum ben

BirDeli

07.11.2003

(Anadolu =  TUTKU''nun, SEVDA''nin simgesi)', 'Şiirlerde yazıyorum şiirlerde boğuşuyorum kavga ediyorum  tartışıyorum ve  döğüşüyorum seninle… Şiirlerde seviyorum yüreğini şiirlerde okşuy...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-seni-bende-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapanma!', 'kapanma-derin-deniz-3y857', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Büyük bir kapanmaya doğru gidiyorsun.

Her sözde, her davranışta canında halkalanan bir geri çekilme bu.

‘İnsan, zaaflarıyla, içindeki kötülükle insandır’ düşüncesinin, giderek bir aşağılanma hazzına dönüştüğü sürekli bir incinme hali. 

Bir yakınlık ve güven malûlüsün.

Bütün özgürlüğün, iyileşmez bir sorumluluk duygusu. 

Kalbin, sınırına geldi. 

Sevgi bile ruhunu daraltıyor artık.

 Gösterilen her ilgiyi, başkalarına kurduğun her cümleyi kayıp zaman sayıyorsun. 

Yalnızlığın o gizli çekirdeği büyüdü, büyüdü, her şeyi yutmaya başladı. 

Söz yordu. 

Hayal güçsüz düşürdü.

Gerçek çoktan bencil. 

Herkes konuşarak onardı kendini. 

Sen, konuştukça yetersizlik duygusuna döndün. 

Söylenen her doğru seni küçük düşürdü. 

Korkularını bir ahlâk, bir içtenlik gibi sundular sana. 

Her gün unutup her gün öğrenmenin huzuruydular. 

Biribirlerinden başka doğruları yoktu. 

Mutsuzluğunu bedeniyle ölçen koroya, bunun bir çürüme olduğunu söyleyen aptaldın. 

Hayata bir kenarından iliştirilmiş evlerin güven duygusunu küçümsedin. 

Kendine tapınmanın tek harfli cümlesine, ölümden harfler eklemeye kalktın. 

Tutkuyla vazgeçişin geçişimli halkasını, bir yaşama nişanı olarak sundun insanlara. 

Uzağı gösterdin. 

Her güzelliğin, yakınlıkla ödenen acı bir kaderi var, dedin. 

Eşiğini akla döndermiş insanlara, suların coğrafyasını anlatmaya çalıştın. 

Yaşama gücünün, başkalarının hayalleri olduğuna inanan budala... 

Yoksul ruhlara geleceğin erdeminden söz ettin; eşyaların kefeninden. 

Herkesin cehennemini içtenlik ateşiyle besledin. 

Aşka, özgürlükten ömürler biçtin de payına bir köpek sadakati düştü. 

İlk hecede caziptin, ikinci hecede zavallı... 

Gecikmiş yalnız... 

Bir alın kırışığına bin sebep buldun. 

Sonra elinde, herkesten yapılmış bir cevap — Kalbini geç keşfettin. 

Git. Kapan. 

Yeterince yol biriktirdin. 

Küçük kasabalardan akşamların var. 

Sabah indiğin şehirlerin buğulu kalbi senin. 

Her çaresizlikten binlerce dalgınlık edindin. 

Bir gölge bilgisi olduysan, ışıkları unutma. 

Hayal için, acı verdiğin kadınların kirpikleri yeter. 

Güzel pişmanlıkların var. 

Sevinçlerini azımsama. 

Kaç çocuk, hayatına boşluk olarak ekledi seni. 

Kaç hayattan yalnızlığın var, ömrünü büyütecek. 

Ne kadar acı verirse versin, seni doğuran bir kalabalığın oldu. 

Dersini tenha çalıştın. 

İncinmek için kimse gerekmiyor sana. 

Zehir yüzüğün göğüs kafesinde. 

Yılan ıslıkları kılavuzun olsun. 

Git... 

Yanlışı olmayandan koru kendini. 

Dağ kovuklarının rüyasını uyu. 

Gecenin sahibi korku değil her zaman. 

Üstünü örtecek bir yurtsuz bulunur elbet. 

Mahşerini sev. Onu sen kurdun. 

Taş bile yalnız kendisi değil. 

Git. 

Kapan... 

Gör, yalnızlığın yatışmaz kalabalığını...', 'Büyük bir kapanmaya doğru gidiyorsun. Her sözde, her davranışta canında halkalanan bir geri çekilme bu. ‘İnsan, zaaflarıyla, içindeki kötülü...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/kapanma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya da Tersi', 'ya-da-tersi-cumhur-turan-mt0wp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tüller ardındasın

belki

oynaştıkca tüller

rüzgarımda

bir gelip

bir gidiyorum

belki

belki bir hesabın içindesin

artık sayı kalmadan

bölmek için yaşamı

uygun bölen peşindesin

belki

günü eğirirken kirmanında zamanın

kopmaya yazgılı ipin telaşındasın

ya da tersi', 'tüller ardındasın belki oynaştıkca tüller rüzgarımda bir gelip bir gidiyorum belki belki bir hesabın içindesin artık sayı kalmadan bölmek iç...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ya-da-tersi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen, Ben ve O', 'sen-ben-ve-o-ali-kadioglu-myu1f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen hiç ağlamaksızın yürüdün mü yağmurda

Yem olmaktan korktun mu dağlarda kuşa kurda? 

Gözünün her değdiği yerde gördün mü ''sen''i

Kuşandın mı ruhuna benmbeyaz bir kefeni? 

Senin de karşına, güneşin battığı bir an

Geçip de ''ümidi kes'' dedi mi hiç Nagehan? 

Azık gibi derdini götürürken her yana

İçtin mi ızdırabın suyunu kana kana? 

Ağlayarak öderken aşka vefa borcunu

Kardın mı yüreğinle bir sevdanın harcını? 

Aynada başkasını gördün mü hiç Süeda

Seni de uzaklara uçurdu mu bir sevda? 

Hissetmeden bunları, beni nasıl anlarsın

Gülme bana Süeda, alevimde yanarsın! 

Bir tek ümidim vardı, hayalimde yaşayan

Sensizliği sen gibi omuzlarda taşıyan! .

O bir ince iplikti, kesiverdi Nagehan

Latif olan Allah''ım, bu ne ağır imtihan! 

Herkes güle aşıktır, benimkisi nergizdir

Her adımı huriler kıskandıran bir izdir..

Ne olursun ver geri nergizimi Sultanım

Harap etme çöllerde; hayrandır ona canım! 

O bir minik bebektir, beşiksiz koma onu

Nemrud''a İbrahim der, Musa bilir Firavn''u

Dikenlere sarılsa, rahmetinle al onu

Yüreğimden su alan lalezara sal onu! ..

Ümitsizliğe salma en narin aşığını

Susuz bırakma Rabbim, nazenin balığını! 

Aslanlara yem etme o zavallı balığı

Gönderme üzerine vahşi kalabalığı! 

Nergizime ilham et, güzel olan ne varsa

Eğer yad eller ona benim gibi bakarsa; 

O onları bilemez, herkesi bir ben sanar

Bahçıvansız gül olur, ateşlerinde yanar! ..

Lütfedip koru onu ilhamınla Allah''ım

Yoksa kor ateş olur, yakar gökleri ''ah''ım! 

Nergizimle beraber fethedelim cihanı

Ne olur haksız çıkar bir sefer Nagehan''ı

Yanmak ne zormuş Rabbim, bir nergizin ardında

Onu bensiz bırakma, bu gariplik yurdunda! 

Paylaşalım süruru gökteki meleklerle

Uçalım sonsuzluğa, özgür kelebeklerle! ..', 'Sen hiç ağlamaksızın yürüdün mü yağmurda Yem olmaktan korktun mu dağlarda kuşa kurda?  Gözünün her değdiği yerde gördün mü ''sen''i Kuşandın m...', ARRAY['Türk Edebiyatı','Şiir','Ali Kadıoğlu']::text[], 8.5, '{"poet":"Ali Kadıoğlu","poet_slug":"ali-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-ben-ve-o-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Ne Sevdalar', 'yureginde-ne-sevdalar-zeki-ergin-iyn7q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşksız sevdasız

sevgiden yana

kısmetsiz büyüyen çocuklar

ana kucağı 

baba ocağı görmeden büyüyen

ve sokaklarda solucan gibi yürüyen

biliyorum 

seninde sıcacık bir yüreğin var

erişilmezliğini bilsen de

yüreğin dünyalar kadar

yüreğinde ne sevdalar  var

_kadıköy 7kas03

_sevgiliye isyan yt:haz04', 'aşksız sevdasız sevgiden yana kısmetsiz büyüyen çocuklar ana kucağı  baba ocağı görmeden büyüyen ve sokaklarda solucan gibi yürüyen biliyoru...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yureginde-ne-sevdalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutsuz Gökyüzü Gibi', 'bulutsuz-gokyuzu-gibi-cumhur-turan-9tlzc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'o

şu

bu

say

sayabildiğin kadar

o denli çoktular

her biri çekerek gölgeyi

araladılar perdeyi

artık ışıyor

iplik

iplik

güneşin elleri

ama biri

biri var ki

en çok bizden olan

bırakarak çekmeyi

elinde dev makası

gölgede koca bir oyuk açan

dinle geliyor oyuktan sesi

yakın

yakın

güneşi zaptedeceğiz

güneşin zaptı yakın

derken

o vurgulu tok sesinde

nasılda bakıyor

üstelik yüz yaşında

bulutsuz bir gökyüzü gibi', 'o şu bu say sayabildiğin kadar o denli çoktular her biri çekerek gölgeyi araladılar perdeyi artık ışıyor iplik iplik güneşin elleri ama biri...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bulutsuz-gokyuzu-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Bir Bayrakça', 'huzunlu-bir-bayrakca-cumhur-turan-0r885', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'savaş

binbir ölüm her iklimden

dönendi zamanın ormanında

hiç bitmeden

kılığını değiştirdi

görünmez oldu

rüzgarın ellerince geliyor artık

görüntüsü olmayan cellatlarını yetiştirdin

bir vuruşta binlerce can alan

barışsa

hüzünlü bir bayrakça sallanıyor hala

onca ölümüne inat savaşların', 'savaş binbir ölüm her iklimden dönendi zamanın ormanında hiç bitmeden kılığını değiştirdi görünmez oldu rüzgarın ellerince geliyor artık gör...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzunlu-bir-bayrakca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikmiş güzellik', 'gecikmis-guzellik-murat-tali-on52q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güzel olan şeyler 

insanların karşısına 

hep geç çıkarmış

sabırsız davrandıklarının 

cezasını 

çekmeleri için', 'güzel olan şeyler  insanların karşısına  hep geç çıkarmış sabırsız davrandıklarının  cezasını  çekmeleri için...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gecikmis-guzellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para-doks', 'para-doks-ahmet-aksoy-yezyj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'soluk alırken meltem, 

yaz günü, insan bekler, 

ne olur biraz daha essin diye, 

havadan gelen para gibi, 

ve depardayken kuzey rüzgarı, 

güz günü, insan isyan eder, 

neden durmaz diye, 

ödemesi gereken faturalar gibi.', 'soluk alırken meltem,  yaz günü, insan bekler,  ne olur biraz daha essin diye,  havadan gelen para gibi,  ve depardayken kuzey rüzgarı,  güz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/para-doks-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Yakomoz ve Yağmur', 'deniz-yakomoz-ve-yagmur-ahmet-aksoy-a4c5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ay yetmez 

................seni anlatmaya

Bir yağmur yetmez

Ne de bir deniz 

........anlatabilir tek başına

................yakamozdaki yağmur.', 'Bir ay yetmez  ................seni anlatmaya Bir yağmur yetmez Ne de bir deniz  ........anlatabilir tek başına ................yakamozdaki ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/deniz-yakomoz-ve-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''nın Taşına Bak', 'ankara-nin-tasina-bak-i-brahim-bayraktar-buhrz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Altındağ’ın çetrefilli sokakları dikine, 

Dilimizdeki türkü Ankara’nın haline, 

Kalenin yamaçlarına dizili eski evler, 

Geçmişten günümüze maniler söyler.

Bir de bu evlerin afilisi konaklar, 

Geçmişe özendirip, geleceği kucaklar, 

Cebeci, Samanpazarı,  Pursaklar, 

Kendine uzanacak sihirli eli bekler.

Ulus’un, Kızılay’ın çehresine bir bakın, 

Her gelen göbek bozup, göbek düzdü, 

Sokaklara bakıp da aldanmayın sakın, 

Kaldırımlar yap boz tahtasına döndü.

Yenimahalle varoşlara ayrılmış, 

Çankaya ezelden beri kayrılmış, 

Keçiören yoksulluktan sıyrılmış, 

Dikmen sırtlarında geçiyor zaman.

Karakış yüzünü gösterdi gayrı, 

Güzel Ankara hala toz duman, 

Mamak’taki koşuşturma apayrı, 

Gelecek baharı bekliyor Sincan.

07.11.2003', 'Altındağ’ın çetrefilli sokakları dikine,  Dilimizdeki türkü Ankara’nın haline,  Kalenin yamaçlarına dizili eski evler,  Geçmişten günümüze m...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ankara-nin-tasina-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olma!', 'olma-refik-recep-pelit-ksxku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostun gözünde yegane ol, 

Sakın ahbabına el olma 

Şaşırıpta güzergahtan

Nahoş diline  emsal olma 

Doru at üstünde iken

Eşşek sırtına semer olma.

Çıkar peşinde koşupta 

Kötü karşısında lal olma 

İçi geçmiş ahşabın, 

Mesnetine mıh olma 

Tezvir ile uğraşanın, 

Yalanına tellal olma 

Sevildiğini bil her yerde

Yapışıpta kasnı  olma

Gayretliye ter olda, 

Züğürt diline  mal olma

Kurnaz görünüp herkese 

Durduk yere  hin olma.

Eşiklerde  sürün!  çul olda 

Tutunca kırılan dal olma.', 'Dostun gözünde yegane ol,  Sakın ahbabına el olma  Şaşırıpta güzergahtan Nahoş diline  emsal olma  Doru at üstünde iken Eşşek sırtına semer ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Seni Düşünsem', 'ne-zaman-seni-dusunsem-k-muran-esen-plr6u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni düşünsem / ne zaman, 

Ne zaman sen gelsen aklıma, 

İçimden havalanıyor kanadı kırık bir martı, 

Gelip konuyor uzaklarıma.

Soluyor yaprakları saksıdaki çiçeğin.

Ve ardından

Susuyor keman, 

Bir ağacın yaprakları

Düşüyor ayaklarıma.

Ne zaman seni düşünsem

Ne zaman sen gelsen aklıma, 

Acı bir tebessüm

Gelip konuyor dudaklarıma.

Notası kırılmış melodilerin

Buruk sesi geliyor kulaklarıma.

Bir kuş düşüyor 

Daldaki yuvasından / çırpınarak

Sıcak avuçlarıma.

Ne zaman seni düşünsem, 

Ne zaman sen gelsen aklıma, 

Dalıyorum dipsiz bir kuyuya

Yalnız başıma.

Ve ardından

Boğuluyorum

İçine düştüğüm denizlerimde, 

Yeniliyorum

Kendi denizimin dalgalarına.

Ne zaman seni düşünsem, 

Ne zaman sen gelsen aklıma, 

Kaldıramayacağım bir ağırlık

Çöküyor yapraklarıma.

Umutlarıma  taş basıyor yokluğun, 

Kar düşüyor, 

Henüz tomurcuk umutlarıma.

Seni düşünmek istemiyorum  artık, 

Çölde yalnız başına  yaşayan  kaktüs gibi, 

Tüketmek istiyorum ömrümü / bir başıma.

Alıştım nasıl olsa yıllardır, 

Hem yokluğuna

Hem yalnızlığıma.', 'Ne zaman seni düşünsem / ne zaman,  Ne zaman sen gelsen aklıma,  İçimden havalanıyor kanadı kırık bir martı,  Gelip konuyor uzaklarıma. Solu...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ne-zaman-seni-dusunsem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İllegal', 'i-llegal-omer-faruk-cakir-e6qje', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşler kurardım

Gündüzleri görmek yasak, 

Bütün illegal gün ışığında

Uykularına alan korkardı

Düşler kurardım usumun dışında

Uslu sevgiler sevmezdi sevmemi

Düşler kurardım

Bir geceye uyardı, 

Gece uyurdu herkes

Düşler kurardım', 'Düşler kurardım Gündüzleri görmek yasak,  Bütün illegal gün ışığında Uykularına alan korkardı Düşler kurardım usumun dışında Uslu sevgiler s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/illegal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-omer-faruk-cakir-z0g1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün çok uzağa gitti

Yalnızlığını bıraktı,

Yalnız gölgesini aldı,

Bazen öylesi istekliydi, 

Koşarak önünden yürüdü, 

Yetişmesini bekledi bazen,

Bazen ardına düştü, 

Durdu, düşündü,

Sanki isteksizdi gitmeye, 

Sokak lambaları birden söndü, 

Bir tek gölgesi terketti O''nu, 

Oysa O gibiydi eli, 

Onun gibi yürürdü, 

Bir gün çok uzağa gitti

Yalnız bir adama

Emanet bıraktı, yalnızlığı!', 'Bir gün çok uzağa gitti Yalnızlığını bıraktı, Yalnız gölgesini aldı, Bazen öylesi istekliydi,  Koşarak önünden yürüdü,  Yetişmesini bekledi ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emanet-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Döndü', 'ay-dondu-umut-ulbegi-owyij', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ataşehir

Üsküdar

Üsküdar 

Ataşehir

Yollar

Gündüz ve gece

gibi birleşiyor

Yollar ayrı kalınmayan iki ayrılığı

anlatıyor

Sözlerin yankılanıyor kulaklarımda 

Gözlerin gözlerimdeyken

İstanbul''da yalın yürek doğar insan

İzmir''de alevlenir

Tutku denizinde insan

yaşamayı öğrenir

Öğrendik birlikte

Yandık

Döndük cehennem kapılarından

İki yarısıyken gecenin

ve inadına yaralıyken

ay döndü

Tamamlandık

Üsküdar 

Ataşehir

Ataşehir 

Üsküdar

İki sıcak ten gibi

bizim gibi

birleşiyor', 'Ataşehir Üsküdar Üsküdar  Ataşehir Yollar Gündüz ve gece gibi birleşiyor Yollar ayrı kalınmayan iki ayrılığı anlatıyor Sözlerin yankılanıyor...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ay-dondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker oğluma', 'asker-ogluma-tuncay-akdeniz-sxbs1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Askerlik kutsaldır ettin yemini

Yeminine sadık kalasın oğul

Sen vatanı ben beklerim evini

Gidip güle güle gelesin oğul

Peygamberler ocağıdır orası

Şerefli şanlıdır.Türk''ün ordusu

Sizlersiniz bu vatanın varisi

Bilirim yıkılmaz kalesin oğul

Atamdan mirasdır bu vatan bize

Her karış toprağı emanet size

Sahip olun kara hava denize

Vatansız yurt olmaz bilesin oğul

Düşmanlar göz diker şehir''e köye

Sakın nişan alma yanlış hedefe

Gerekirse canın ver seve seve

Rabbimizden ihsan bulasın oğul

Tuncayım emanet verdim birine

Kusur etme komutana erine

Aldığın görevi getir yerine

Şerefinle terhis olasın oğul', 'Askerlik kutsaldır ettin yemini Yeminine sadık kalasın oğul Sen vatanı ben beklerim evini Gidip güle güle gelesin oğul Peygamberler ocağıdır...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asker-ogluma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Zamanı', 'hesap-zamani-ahmet-kurt-2aeyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne derlerse kabul, kul karşı durmaz, 

Hiçbir emrin sonu, ayıp; sorulmaz, 

Tafrasından yanlarına varılmaz, 

Davranın yiğitler, hesap zamanı.

Nezaket diz boyu hayayı aşmış, 

Necaset paçadan dışarı taşmış, 

Beyinler kilitli, akıllar şaşmış, 

Davranın yiğitler, hesap zamanı.

En zelil zamandan daha aşağı, 

Sırtlarına değen gümüş kaşağı, 

Hilalin tüccarı, haçın uşağı, 

Davranın yiğitler, hesap zamanı.

Adı senden benden, aslı karışık, 

Birkaç yerden belki daha karışık, 

Bal küpü, pekmeze, çanağa aşık, 

Davranın yiğitler, hesap zamanı.

Demokratız güya, bizden olana, 

Geçit yok demiştik, hortum talana, 

Bir de bizler taktık kuyruk yalana, 

Davranın yiğitler, hesap zamanı.

Her köşe başında yalanır itler, 

Olanı gördükçe inler şehitler, 

Görenden vaz geçtik körler şahitler, 

Davranın yiğitler, hesap zamanı.

Mazluma zulmedip, aslan kesilir, 

Beyine el açar, döner kasılır, 

Bir eğri bakışta sesi kısılır, 

Davranın yiğitler, hesap zamanı.

İkizler doğurdu hala yetmedi, 

Sırada neler var daha bitmedi, 

Beşyüz elli güruh, bir tek etmedi, 

Davranın yiğitler, hesap zamanı.

Oyunlar ki kıvrak, müzik aheste, 

Kulaklar alışık, bilinen beste, 

Keramet kalmamış beklenen seste, 

Davranın yiğitler, hesap zamanı.

Şatafat, saltanat, vuruldunuz mu

Erkeklik kayboldu, buruldunuz mu, 

Yoksa saat gibi kuruldunuz mu, 

Davranın yiğitler, hesap zamanı.

Gık diyene çaktı haşin şimşekler, 

Envai türünden icat kötekler, 

Tilkiler, yılanlar ve köstebekler, 

Davranın yiğitler, hesap zamanı.

Ey sessiz bekleyen büyük çoğunluk, 

Aşınız, suyunuz birkaç öğünlük, 

Varlığında kitli bütün yoğunluk, 

Davranın yiğitler, hesap zamanı.

Şöyle bir düşünün, Çin’den beriye, 

Söyleyin ne kaldı şimdi geriye, 

Ümit mi bağlarsın cinle, periye, 

Davranın yiğitler, hesap zamanı.

Büyük geldi bakın bir avuç vatan, 

Boşa mı savaştı deden ve atan, 

Bedeli bilmeden, bedava satan, 

Davranın yiğitler, hesap zamanı.

İşletmeler gitti, sıra ormanda, 

Tarihler silindi, müze talanda, 

Keramet bulunur, her tür yalanda, 

Davranın yiğitler, hesap zamanı.

Tarihte talan var dedim ya demin, 

Kullanılır oldu, her türlü zemin, 

Sormadan bu tezgah, nerden ve kimin, 

Davranın yiğitler, hesap zamanı.

Devletten köylere modası yeni, 

Hapseder evinde, düşünce seni, 

Ufkunda hesapla boy ile eni, 

Davranın yiğitler, hesap zamanı.

Bölücü revaçta, hain başa taç, 

Zehirler verilir, sanırsın ilaç, 

Kurdoğlu tek sana, Türklüğe muhtaç, 

Davranın yiğitler, hesap zamanı.', 'Ne derlerse kabul, kul karşı durmaz,  Hiçbir emrin sonu, ayıp; sorulmaz,  Tafrasından yanlarına varılmaz,  Davranın yiğitler, hesap zamanı. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/hesap-zamani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılsa Ekim''dir.', 'kizilsa-ekim-dir-selcuk-vurgun-pkek9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu hafif soğuk, yarı hüzünlü sonbahar akşamında, omuzlarımdan dökülen ayışıklarına anlatıyorum seni.

Dudağımda taze bir şarap lekesi, bulutların arasında bazen sen; yakamozun gözbebeklerimde.

Bu yarı hüzünlü, yalancı sonbahar akşamında tenim sana hasret.

Yüreğimin ucunda yanan bir kibrit çöpü...

İkinci kez keşfederken ateşi gölgem yanıyor bu taze yağmış sonbahar toprağında.', 'Bu hafif soğuk, yarı hüzünlü sonbahar akşamında, omuzlarımdan dökülen ayışıklarına anlatıyorum seni. Dudağımda taze bir şarap lekesi, bulutl...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Vurgun']::text[], 8.5, '{"poet":"Selçuk Vurgun","poet_slug":"selcuk-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kizilsa-ekim-dir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Miydin?', 'sen-miydin-murat-sarikaya-3hi3e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEN MIYDIN? 

Sen miydin? 

Bu kara yazgini sebebi. 

Sen miydin? 

Acilarimin basmimari. 

Sen miydin? 

Derdimin dermani. 

Sen miydin? 

Genclik cagimin celladi. 

Sen miydin? 

Hayatimin zehirli yilani 

Sen miydin? 

Omrumun son noktasi... 

SEN MIYDIN? ? ?', 'SEN MIYDIN?  Sen miydin?  Bu kara yazgini sebebi.  Sen miydin?  Acilarimin basmimari.  Sen miydin?  Derdimin dermani.  Sen miydin?  Genclik ...', ARRAY['Türk Edebiyatı','Şiir','Murat Sarikaya']::text[], 8.5, '{"poet":"Murat Sarikaya","poet_slug":"murat-sarikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-miydin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şahikadır ölüm', 'bir-sahikadir-olum-ahmet-aksoy-o0pul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kesif yalnızlıklar bilirim, 

insan çabalar sıyrılmak için, 

ki sonucu çoğu zaman, 

azmi belirler adamın, 

lakin bir yalnızlık bilirim, 

kurtuluşu yoktur insan elinden, 

ışık aydınlıkta yok olmuştur, 

o ki ölümdür yalnızlıklar şahikası.', 'kesif yalnızlıklar bilirim,  insan çabalar sıyrılmak için,  ki sonucu çoğu zaman,  azmi belirler adamın,  lakin bir yalnızlık bilirim,  kurt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-sahikadir-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Üzere', 'olmek-uzere-ahmet-aksoy-um7ot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şu son bir kaç gündür ard arda, 

beni terk edişini yaşıyorum, 

ki krize tutulmuş gibi kalbim, 

neredeyse ölmek üzereyim, 

hani derler ya, sıcağı sıcağına

acıtmaz herhangi bir yara, 

işte öyle, yeni yeni vuruyor sanki, 

onulmazlığın işleyişleri, 

kaç gündür gözlerimde asılı, 

kirpiklerimin esaretinden kurtulup da, 

bir türlü, akmayan bir damla, 

ve sanki, neredeyse çatlayacağım, 

ki ben yıllardır, ağır bir tabut gibi

iki elim kanda taşıyorum seni, 

lakin bir türlü öldüğüne, 

inanıp da gömemiyorum seni, 

ah eski sevildiğim, 

şimdi gitmemiş olsaydın eğer, 

ellerin avuçlarımda olurdu, 

ve saçlarını koklardım bahtiyar, 

hüznün koridorlarında esir olmazdım, 

nicedir unuttuğum gülmekten kopmazdım, 

ve bir nehir gibi çağlayıp çoşardım, 

ölmek bile, başka türlü olurdu anlayacağın.', 'şu son bir kaç gündür ard arda,  beni terk edişini yaşıyorum,  ki krize tutulmuş gibi kalbim,  neredeyse ölmek üzereyim,  hani derler ya, sı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olmek-uzere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Sevgilim', 'dinle-sevgilim-i-smail-erkan-tolay-psv8a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gece vakti bunaltısıdır içimde bir ti sesi

bilinmeli ki her gece kendi örtüsünü örer

her gece bir cenaze evi

gecelerin sürüklediği yek perde blue es''im

trapezinde uyku girmez düşlerin

yine de düşlerim...

dinle sevgilim

menevişim dinle

ben sevdim mi pazara kadar severim

geç git bulutundan es''imin

ne notalar düşecek solfejine

bu gün varım yokum yarın

gece bu yerine konulmaz

gece bu bitişi ti nin

geç git bu gün varım

yarın misafirim

dinle sevgilim

dinle dinlenecek kaldıysa neyim

menevişim

ben bitişim

yorgun kağnılar kesiyor yolumu

gündüzüm gecem yorgun

kasımsız bir pazar güruhu

gürültüsüz bu ruhum

yorgunum

yolun sonu

dinle sevgilim dinle

sevdim mi ben

pazara kadar severim

(Kasım 2003)', 'gece vakti bunaltısıdır içimde bir ti sesi bilinmeli ki her gece kendi örtüsünü örer her gece bir cenaze evi gecelerin sürüklediği yek perde...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dinle-sevgilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S Harfi', 's-harfi-i-smail-erkan-tolay-54wry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl durur

beyaz karın üzerinde esmer bir s harfi

ama yorgun ama yaralı ama ürkek

boyarken teri kankızıla

bir s harfi

nasıl durur

kızıl suların yortusunda

göverirmi kardelen çiçeği

kar beyazında 

o bir s harfi

gölgeli latin yeknesak

kıvrım kıvrım asabi

nasıl durur bir s harfi

yere düşerse o yürek

paslı metal hançereden

s harfi

kızgın engerek

zehir ve dokunuş

nasıl durur esmer biri 

gölgesiz kar gibi', 'Nasıl durur beyaz karın üzerinde esmer bir s harfi ama yorgun ama yaralı ama ürkek boyarken teri kankızıla bir s harfi nasıl durur kızıl sul...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/s-harfi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farketmez', 'farketmez-fatih-konuk-7lqgu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Madem çekip gideceksin sebebini

Bilsemde farketmez bilmesemde

Artık başkasının olacaksın mutluluğunu

Görsemde farketmez görmesemde

Şu açtığın gönül yarama ilacı

Versende farketmez vermesende

Şu kanayan yarama melhemi

Sürsende farketmez sürmesende

Buraları bırakıp gittiğin yerden geri

Dönsende farketmez dönmesende

Kollarını açıp boynuma sıkı sıkı

Sarılsanda farketmez sarılmasanda

Solmuş resimlerini, mektuplarını

Alsanda farketmez almasanda

Yaşanmış mazimizi, aşkımızı bir daha

Yaşatsanda farketmez yaşatmasanda

Terkedip geri dönüpte beni yine

Sevsende farketmez sevmesende

Pişmanlığını anlayıp bana tekrar

Gelsende farketmez gelmsende', 'Madem çekip gideceksin sebebini Bilsemde farketmez bilmesemde Artık başkasının olacaksın mutluluğunu Görsemde farketmez görmesemde Şu açtığı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/farketmez-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Olunca', 'aksam-olunca-fatih-konuk-nph53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş batar çöker karanlıklar

Perdelerin çekilir akşam olunca

Bense sokaklarda kalırım bir başıma

Acılarım başlar akşam olunca

Dizlerim çöker kaldırımlara

Yıldızlar kayar gökyüzünden

Ellerim cebimde dolaşırım

Şehrin ışıkları yanar akşam olunca

Yüreğimde ızdıraplar, ellerimde resimler

Karşımda hayalin, dilimde şarkılar

Yanaklarımdan akan gözyaşları

Sel olur akar akşam olunca 

Gökyüzünde süzlen kuşlar uçar gider

Güzdendan sonra gelen kışlar gelir geçer

Şehrin ışıkları durmadan yanar söner

Gözlerim ağlar akşam olunca', 'Güneş batar çöker karanlıklar Perdelerin çekilir akşam olunca Bense sokaklarda kalırım bir başıma Acılarım başlar akşam olunca Dizlerim çöke...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aksam-olunca-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evleniyormuşsun', 'evleniyormussun-fatih-konuk-3w8q3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyordum

Hayalinle geziyordum

Yüzüm gülüyor, 

Içim içime sığmıyordu

Ve birden dostum evlendiğini söyledi

Inanamadım

Inanmak istemedim

O sözü duyunca

Sanki üzerime bombalar yağdı 

Ayaklarım yerden kesildi, 

Olduğum yere çöktüm

Bir yalan, bir şaka ve bir rüya sandım

Sandım ama aldandım

Demek evleniyormuşsun

Mutlu bir yuvan, 

Kolunda kocan, 

Kucağında çocuğun olacakmış

Beni beklemek zormu geldi sana

Beni severek evlenmen mutlumu edecek seni sanki

Etmeyecek ne seni ne de beni

Karnında çocuğunu, 

Kalbinde beni, 

Gönlünde bu sevdayı taşıyacaksın

Bunlar sana zor gelecek zor

Her kadın gibi sende pencere önünde

Kocanın gelişini bekleyecek, 

Yollara bakacaksın

Evleniyormuşsun

Bir başkasının olacakmışsın

Senin bu mutlu hayalin 

Benim ölümüme sebeb olacak

Evleniyormuşsun

Beyaz gelinlik giyecek, 

Düğünün yapılacak

Bir heves uğruna gideceksin

O kurulan hayalleri unutup

Bir başka dünyaya gideceksin

Evleniyormuşsun

Ellerin olacaksın

Beni düşünmedinmi hiç

Aklına gelmedin mi

Ben şimdi nasıl dayanacağım bu acıya

Nasıl katlanacağım bilemiyorum

Seni bir başkasıya görmek ve düşünmek

Çıldırtıyor bi bilsen

Belki bir başkasının kolları arasında karşılaşağız

Ben geçmişe dalıp gideceğim her zaman olduğu gibi

Ama bu sefer gözyaşı dökerek

Dayanmak zorda olsa dayanmalıyım

Alışmalıyım sensizliğe kabullenmeliyim

Mecburen, çaresiz bir şekilde

Benim en zoruma giden şey gidişine sessiz kalmak

Elimde birşeylerin gelmemesi çook zoruma gidiyor

Alışmalıyım alışmalıyım

Bu acıyada alışmalıyım her acıya alıştığım gibi

Ama şunu bilki hiç bir acı hiç bu kadar acıtmadı yüreğimi

Hiç bir acı bu kadar bu kadar uzun sürmedi ve sürmeyecek

Ölene kadar bu acı yüreğimde devem edeceğini adım gibi biliyorum

Içimdeki sevdayı derinlere gömerek sana saddet dilemeye geldim

Seni yanaklarından değil alnından öpmeye geldim

Dünyandan, hayatından çıkmaya geldim

Artık beni yar değil kardeşin, abin gibi bak

Yoksa dayanamaz bu kalbim 

Neyse HOŞÇAKAL

Mutluklar seninle olsun.....', 'Seni düşünüyordum Hayalinle geziyordum Yüzüm gülüyor,  Içim içime sığmıyordu Ve birden dostum evlendiğini söyledi Inanamadım Inanmak istemed...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/evleniyormussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılacağım', 'ayrilacagim-fatih-konuk-vlkz3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle yaşadığım yıllara bir sünger çekip

Ondan sonra senden ayrılacağım

Resimlerini, mektuplarını yüzüne vurup

Ondan sonra senden ayrılacağım

Senden ayrılmak zorda olsa

Yüreğime düşen korda olsa

Kalbimi yakanateşte olsa

Senden ayrılacağım

Toprağa gömer gibi seni kalbime gömüp

Herkesin önünde seni seviyorum deyip

Yaşadağımız o aşkı orada bitirip

Ondan sonra senden ayrılacağım

Seninle son defa konuşup

Gözlerine gözlerimle bakıp

Maziyi sana hatırlatıp

Ondan sonra senden ayrılacağım', 'Seninle yaşadığım yıllara bir sünger çekip Ondan sonra senden ayrılacağım Resimlerini, mektuplarını yüzüne vurup Ondan sonra senden ayrılaca...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Yeter', 'bil-yeter-fatih-konuk-398ej', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi ellere gelin oldun ellerinsin artık

Seni seviyorum bunu bil yeter

Şimdi mutlu musun bilmiyorum ama

Seni seveceğim bunu bil yeter

Seni unutmak kolay olmadı hatta olmayacak

Bir seni sevdi bu gönlüm başkasını sevmeyecek

Ölene kadar inan ölene kadar bu aşk bitmeyecek

Sevdamızı içimde yaşatacağım bunu bil yeter

Biliyorum dönülmez yola saplandın

Sanki şu sineme bıçağı sapladın

Nasıl oldu da beni başkasına değiştin

Aşkımızı gönlümde saklayacağım bunu bil yeter

Dudakların gibi kalbinde mutluyum diyor mu? 

Söyle sevgilim bu aşkımız bur da bitiyor mu? 

Sor şu kalbime bu ayrılığı kabulleniyor mu? 

Düşlerimizi bir başıma gerçekleştireceğim bunu bil yeter

Nasıl olurda bu aşkı bir anda düşünmeden bitirdin

Avunduğum resmini, mektuplarını bakmadan yırttın

Nasıl olur nasıl olurda beni bir kalemle silip attın

Ben bu ayrılığa hala inanmadım bunu bil yeter', 'Şimdi ellere gelin oldun ellerinsin artık Seni seviyorum bunu bil yeter Şimdi mutlu musun bilmiyorum ama Seni seveceğim bunu bil yeter Seni ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bil-yeter-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Sevdin Beni', 'neden-sevdin-beni-fatih-konuk-khrgw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Madem benden ayrılacaktın

O zaman neden sevdin beni? 

Madem başkasının olacaktın

O zaman neden sevdin beni? 

Madem yarı yolda bırakacaktın

Boynu bükük, öksüz koyacaktın

Madem ellere gelin olacaktın

O zaman neden sevdin beni? 

Peşimde dolansın diyemi sevdirdin

Kulum, kölem olsun diyemi sevdirdin

Uğruma herşeyi yapsın diyemi sevdirdin

O zaman neden sevdin beni? 

Herkese kendini birşey sandırmak içinmi? 

Gün geçirip, alay edip eğlenmek içinmi? 

Seviyor gibi görünüp kandırmak içinmi? 

Sevdin beni neden sevdin beni? 

Aşkı, sevgiyi bana tanıtmak içinmi? 

Herşeyin yalan olduğunu anlatmak içinmi? 

Gün gelip beni sevmediğini söylemek içinmi? 

Sevdin beni neden sevdin beni?', 'Madem benden ayrılacaktın O zaman neden sevdin beni?  Madem başkasının olacaktın O zaman neden sevdin beni?  Madem yarı yolda bırakacaktın B...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neden-sevdin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş', 'bir-dus-hikmet-karakus-cb1ws', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün denizleri gök mavisine sarıp

          yüreğimin kıyısında dinleniyorum, 

Sevdam paramparça

          kayalara çarpan dalgalar gibi, 

Dalıyorum serin duruşlarıma, 

Nerde yitirdim gülmelerimi? 

Savaş alanlarını 

          maviye boyasam mı  acaba? 

Kor olmuş bedenlerin

          gülen gözlerinde bulur muyum

          güleç yüzümü? 

Üşüyorum; 

          gözgöze geldiğimde bir çocukla, 

Utanıyorum; 

          ateşin kan renginden, 

Yangına veriyorum

          geçmişe dair ne varsa, 

Ve bir yokoluşun çığlıklarını 

hapsediyorum duygularımın zaferine, 

Yeniden doğuyorum

          kendi küllerimden Hirojima''da, 

Dağ esintisiyle kuşatıyorum bütün şehirleri, 

Donatıyorum sevgiyle

           bütün gözleri uyku mahmurluğunda, 

Ve öpüyorum o gözleri bir bir

           Yunus aşkıyla...

Bu bir düş; 

   ama birgün  mutlaka... 

(Ank.2001)', 'Bütün denizleri gök mavisine sarıp           yüreğimin kıyısında dinleniyorum,  Sevdam paramparça           kayalara çarpan dalgalar gibi,  ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-dus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesim Geliyor', 'olesim-geliyor-fatih-konuk-0e10e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canımı canına katasım geliyor

Herşeyimi uğruna seresim geliyor

Sevgilim, canım, aşkım

Senin uğruna ölesim geliyor

Seni seviyorum diye bağırasım geliyor

Herkesin önünde sevdiğimi haykırasım geliyor

Umudum, gülüm, herşeyim

Sen gidince benimde gidesim geliyor

Yere, göğe adını yazasım geliyor

Varımı, yoğumu sana veresim geliyor

Sevdam, bir tanem, çarem

Senin adına türküler yakasım geliyor

Ferhat gibi dağları delesim geliyor

Mecnun gibi çölleri aşasım geliyor

Can özüm, iki gözüm, kalbim

Bana açtığın kollarına koşasım geliyor', 'Canımı canına katasım geliyor Herşeyimi uğruna seresim geliyor Sevgilim, canım, aşkım Senin uğruna ölesim geliyor Seni seviyorum diye bağıra...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olesim-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heves Uğruna', 'heves-ugruna-fatih-konuk-1ju9s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir heves uğruna kendini yaktığından

Haberin bile yok

Sen sanıyorsun beni unutmak kolay olacak

Ölene kadar sen ölene kadar beni unutamazsın

Sen evlenmeyi beyaz gelinlikler içinde 

Mutlu olacağını sanıyorsun

Sen evlenmeyi mutlu bir yuvan olup

Çoluk çocuk sahibi olmayı sanıyorsun

Yıllar sonra pişman olacağını düşünmüyormusun? 

Bir heves uğruna kendini harcıyorsun

Gün geip terkedileceksin

Kapıma gelip benden af dileneceksin

Yaramaz bir eşya gibi sokağa atılacak

Pişman, perişan olacaksın

Geçte olsa yaptığın hatayı anlayacaksın

Yüzüme bakacak yüzün olmayacak

Dizlerimin önünde gözyaşlarına boğulacaksın

Utancından ellerini kapatıp

Benden bir şans daha isteyeceksin

Pişmanlığına kelimeler yetmeyecek

Ne desen ne desen fayda etmeyecek

Fazla yalvarma, fazla dil dökme

Bu kalbim sana bir daha yer vermeyecek

Gel etme sevgilim vazgeç bu sevdadan

Gözlerimize yaşlar dolmadan

Bir başkasına ait olmadan

Beni böyle terketmeden vazgeç bu sevdadan

Vakit geç olmadan 

Sonra pişman olmadan

Senden umudumu kesmeden vazgeç bu sevdadan

Gel etme sevgilim severek ayrılmayalım

Gel etme sevgilim gel gitme sevgilim

Bir heves uğruna kendini yakmadan

Vazgeç bu sevdadan vazgeç sevgilim', 'Bir heves uğruna kendini yaktığından Haberin bile yok Sen sanıyorsun beni unutmak kolay olacak Ölene kadar sen ölene kadar beni unutamazsın ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/heves-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam Sakızı Çoban Armağanı', 'cam-sakizi-coban-armagani-bekir-mutlu-gokcesu-f6ots', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çam sakızı

Çoban armağanı

Bu sabah

Mutluluğun adı

Baba bir çam ağacı

Bir kuş cıvıltısı

İki nefes havası

Ellerime bulaşan

Sakızı ve rayihası

Kozalakları da cabası

07/11/03', 'Çam sakızı Çoban armağanı Bu sabah Mutluluğun adı Baba bir çam ağacı Bir kuş cıvıltısı İki nefes havası Ellerime bulaşan Sakızı ve rayihası ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cam-sakizi-coban-armagani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmem Seni', 'affetmem-seni-fatih-konuk-fa197', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gece bardaktan boşalırcasına 

Yağmur yağıyordu

Gök gürlüyor, şimşekler çakıyordu

Bense ateşin başında resimlere bakıyordum

Ve birden kapım çalındı

Kapıda sevgilim olacağı aklıma bile gezmezdi

Kapıyı açmıştım karşımda duran oydu

Benim taptığım benim canım

Bir zamanlar sevgilim duruyordu karşımda

Sırılsıklam olmuş bitkin bir şekilde

Içeri girebilirmiyim dedi

Tabi tabi dedim

Oturdu karşıma benden af dilendi

Kucağında ağlayan çocuğuda vardı

Pişmanlığını anlattı beni affet dedi

Bende ona

Hatırlıyormusun yıllar önce

Evlenmekten, beni terketmekten vazgeç demiştim

Şimdi af dile benden affetmem seni

Evimin kapısını açarım ama

Kalbimin kapısını asla açmam sana

Bir zamanlar kalbimin kapısına kilidi vuran sendin

Şimdi anahtarı olsa bile açamazsın o kilidi

Affetmem seni affetmem

Herşeye kaldığımız yerden devam edelim

Desen bile devam edemeyiz

Geçmişte yaşadığımız aşkı

Bir daha, yeniden yaşayamayız

Yanlış yaptın sevgiim en büyük hatayı yaptın

Şimdi utanmadan benden af diliyorsun

Beni yeniden sev diyorsun

Kucağındaki çocuğu ve seni 

Kendime kabul edemem

Affetmem seni affedemem

Şimdi seni evime aldıysam

Tanrı misafiri, şu yağan yağmurlarda, sokakta

Kalmayasın diye aldım içeri

Yoksa bende bir tekme atmasını bilirdim

Ama yılların hatrına, yağmurun yağışına dua et

Işte ben başımın çaresine bakmayı bildim

Işte bak yılların izleri saçlarımda

Yağmurda dindi, rüzgarın sesi kesildi

Gökyüzü açıldı, güneşte doğdu

Seninde gitme vaktinde geldi

Kimseler görmeden güle güle sevgilim

Ister vardığın insana dön

Isterse başının çaresine bak

Benden uzak ol bir daha karşıma çıkma', 'Bir gece bardaktan boşalırcasına  Yağmur yağıyordu Gök gürlüyor, şimşekler çakıyordu Bense ateşin başında resimlere bakıyordum Ve birden kap...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/affetmem-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Ha', 'sakin-ha-fatih-konuk-3lwki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün senin uğruna ölürsem

Sakın sakın ha mezarıma gelme

Ellerindeki gülleri toprağıma koyma

Kirli ellerinle tertemiz toprağımı okşama

Sakın sakın ha mezar taşımı temizleme

Gelme mezarıma hiçbir zaman gelme

Sakın sakın ha affet beni deme

Ölmeden önce aklın neredeydi

Şimdi bağışla beni diyorsun

Sevabına bir dua bile etme

Gözyaşını toprağımın üzerine bile dökme

O pis ellerinle dağılmış toprağımı, taşlarımı toplama

Sakı sakın ha toprağımdaki dikenleri yolma

Istemiyorum istemiyorum bir daha gelme mezarıma

Artık daha fazla konuşma

Mezarımın yakınlarından bile geçme

Sakın sakın ha bir fatiha bile okuma

Uzak dursun benden sevabında, günahında, hayrında

Suçluyum, hatalıyım deme

Artık daha fazla konuşma

Zaten konuşsan bile duymam seni

Duysam bile duymak istemem seni

Daha ne duruyorsun git be git git

Uzaklaş benden getirdiğin gülleride götür

Sakın sakın ha bir daha gelme', 'Birgün senin uğruna ölürsem Sakın sakın ha mezarıma gelme Ellerindeki gülleri toprağıma koyma Kirli ellerinle tertemiz toprağımı okşama Sakı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakin-ha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarmısın', 'aglarmisin-fatih-konuk-o73pv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim ölüm haberimi duyunca ağlarmısın? 

Kendini yerden yere vurup gözyaşıdökermisin uğruma? 

Benim sensiz seni yaşattığım gibi

Sende bensiz beni kalbinde yaşatırmısın? 

Benim ölüm haberimi duyunca ağlarmısın? 

Sende beni kabre koymaya gelirmisin düşünmeden? 

Toprağım kazıldığında sende bir kürek toprak atarmısın üzerime? 

Sende son yolculuğuma uğurlarmısın beni? 

Herkesin dağıldığı o anda bir tek sen kalıp

Toprağıma sarılırmısın? dünyada sarıldığın gibi

Senin yokluğunda resimlerine baktığım gibi

Sende benim yokluğumda resimlerime bakarmısın? 

Benim senin resimlerine seni sevdiğimi anlattığım gibi

Sende benim resimlerime beni sevdiğini anlatırmısın? 

Yılda bir kere olsun kabrime gelip bir dua okurmusun? 

Bir kırmızıgül getirip toprağıma koyarmısın? 

Yaşadığımız aşktan, maziden, geçmişten bahsedermisin? 

Yokluğumda uykusuz kaldığın

Gözyaşlarına boğulduğun günleri anlatırmısın? 

Ağlarmısın sevgilim ölüm haberimi duyunca

Ağlarmısın sevgilim gecelerce, günlerce', 'Benim ölüm haberimi duyunca ağlarmısın?  Kendini yerden yere vurup gözyaşıdökermisin uğruma?  Benim sensiz seni yaşattığım gibi Sende bensiz...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aglarmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken', 'sen-yokken-fatih-konuk-vqrco', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarlar üstüme üstüme geldi

Karanlık beni içinde boğdu

Şarkılar hep seni anlattı

Sen yokken sen yokken

İçimde fırtınalar koptu

Sensizlik boynumu büktü

Kalbimde çarpmaz oldu

Sen yokken sen yokken

Dağlar üstüme üstüme geldi

Gökyüzü üzerime üzerime çöktü

Toprak beni beni çağırdı

Sen yokken sen yokken

Dağlardan atılmış gibi oldum

Yokluğunda vurulmuş gibi oldum

Ateşlerden çıkmış gibi oldum

Sen yokken sen yokken', 'Duvarlar üstüme üstüme geldi Karanlık beni içinde boğdu Şarkılar hep seni anlattı Sen yokken sen yokken İçimde fırtınalar koptu Sensizlik bo...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-yokken-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fayda Etmez Ki', 'fayda-etmez-ki-fatih-konuk-9txky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağların ardından güneş gibi doğsam

Sana karşı fayda etmez ki

Dağların üstünden taş gibi atılsam

Sana karşı fayda etmez ki

Yusuf gibi kuyuda kalsam

Ferhat gibi dağları delsem

Mecnun gibi çölleri aşsam

Sana karşı fayda etmez ki

Yağmur gibi dünyaya yağsam

Fırtına gibi delicesine essem

Kara bulutlarla çarpışsam

Sana karşı fayda etmez ki

Balıklar gibi sulara dalsam

Kuşlar gibi gökyüzünde uçsam

Karıncalar gibi yükler taşısam

Sana karşı fayda etmez ki

Akşamları yıldızlar gibi parlasam

Umutsuzlara umut saçsam

Aşkı anlatan şarkı gibi çalsam

Sana karşı fayda etmez ki

Ağaçlar gibi yapraklar açsam

Çiçekler gibi topraklarda bitsem

Çocuklar gibi günlerce ağlasam

Sana karşı fayda etmez ki

Çıkılmayan yokuşları çıksam

Yıkılmayan duvarları yıksam

Yaşanmayan günleri yaşasam

Sana karşı fayda etmez ki

Evlerde duman gibi tütsem

Ocakta ateş gibi yansam

Ağzımla kuş tutsam

Sana karşı fayda etmez ki

Yılanlar gibi yerlerde sürünsem

Arılar gibi ballar yapsam

Caylanlar gibi avcılardan vurulsam

Sana karşı fayda etmez k

Yakılsam, yıkılsam

Bir kurşun gibi sıkılsam

Yağmurlar altında hıçkırsam

Sana karşı fayda etmez ki', 'Dağların ardından güneş gibi doğsam Sana karşı fayda etmez ki Dağların üstünden taş gibi atılsam Sana karşı fayda etmez ki Yusuf gibi kuyuda...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/fayda-etmez-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiştim Sana', 'demistim-sana-fatih-konuk-p0va8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar önce demiştim sana

Bir heves uğruna kendini yakma diye

Demiştim ama sen beni dinlemedin

Bana değil başkasına gelin olmuştun

Demiştim sana yıllar sonra pişman olacaksın

Perişan olacaksın diye demiştim sana

Ne oldu sevgilim şimdi ne geçti eline

Kendini de yaktın benide yaktın

Gelinliğin beyazlığına kapıldın

Işte böyle sokağa atıldın

Senin beni terkettğin gibi başkasıda seni terketti

Şimdi söyle haline güleyim mi? ağlayayım mı? söyle

Demiştim sana benden başkasıyla mutlu olamazsın

Sen bensiz, ben sensiz yapamayız diye demiştim sana

Ama nerde sen beni dinlemedin

Üstüne üstlük beni de davet ettin düğününe

Demiştim sana vazgeç evlenmekten diye demiştim 

Vakit geç olmadan, pişman, perişan olmadan

Gözlerimize yaşlar dolmadan, ikimizi yakmadan

Vazgeç bu sevdadan diye demiştim sana

Şimdi ne olacak sevgilim uçup giden yıllarım gerimi gelecek

Bembeyaz saçlarım geri simsiyah mı olacak

Söyle sevgilim, cevap ver, yüzüme bak

Elinin elime dokunuşuyla

Kalbim eskisi gibi atacakmı

Eskisi gibi gözlerim gözlerine

Sevdiğini söyleyebilcek mi sana sevgilim

Bu suskunluğunla, 

Bu sessizliğinle kendini acındırıyorsun

Seni bir daha seveceğimimi sanıyorsun

Yok yok sevgilim seni eskisi gibi sevmemem

Bu kalbimi, bu gönlümü sana bir daha veremem

Seni ölene kadar, dünyadan göçene kadar affedemem

Yok yok sevgilim uçup giden yılları geri getiremem

Artık sana benim ol diyemem sevilim diyemem

Sakın aklına sana kin, nefret duyduğumu sanma

Istesemde duyamam ki kini, nefreti sana

Sana el kaldıramam, vuramam

Incitimem, kıramam

Başkası terkettiği gibi bende terkedemem

Demiştim sana mutlu olamayacaksın diye

Demiştim demiştim ama sen beni dinlemedin', 'Yıllar önce demiştim sana Bir heves uğruna kendini yakma diye Demiştim ama sen beni dinlemedin Bana değil başkasına gelin olmuştun Demiştim ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/demistim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-adnan-ferit-wl9q7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sürgüne gittinizmi hiç, 

evinizin dört duvarı arasında. 

Burnunuzda dağ laleleri kokusu, 

gözünüzde denizin mavisi, 

ufkunuz oldumu. 

Denizin bittiği yere kadar ama, 

varsa yoksa o kadar. 

Gözün gidebildiği yere kadar. 

Uçsuz bucaksız dedikleri hayaller deniziniz oldumu, 

ateşleriniz, mide ağrılarınız, 

ağız kurumalarınız, kaşıntılarınız sürekli 

olur olmadık yerlerinizde, 

oldumu panik ataklarınız 

ter bırakan ensenize 

sürekli soğuk ya da sıcak, 

bir gece yarısı zoraki kelimeler 

döküldümü satırlara 

Tanrıya mahçup 

kendine saygısız 

bakakaldınızmı hiç 

her gün her gece 

ya da her an 

bir son nokta koyma yalanıyla kandırdınızmı kendinizi 

ve koymaya cesaretiniz olmadı değilmi 

hiçbir zaman 

ne bekliyordunuzki. 

Tanrı her an yanınızda 

yaptıklarınızın değil 

yapmadıklarınızın farkında.', 'Sürgüne gittinizmi hiç,  evinizin dört duvarı arasında.  Burnunuzda dağ laleleri kokusu,  gözünüzde denizin mavisi,  ufkunuz oldumu.  Denizi...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/surgun-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-adnan-ferit-0yahl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Köklrini saran toprağın kokusu rahatsız etmemeli seni 

tiksinme aralarına sızan solucanlardan da 

yıllarca sendin yaşıyan koyun koyuna 

kafanı çıkarıp görünce semayı 

nankör olma bu kadar 

unutma onları 

havanın güzelliğine aldanma 

şimdi bahar 

bunun sonu 

ve birde kışı var 

sanmaki sert rüzgarlar hiç esmiyecek 

karlar yağmayıp seni üşütmiyecek 

dallarına eller uzanacak 

yavrularını koparıp alacak 

karşı koyamıyacaksın 

koyarsan kopardıkları sen olacaksın 

ve işte o zaman 

geç olmasın köküne sarılman 

nankör olma 

sana fayda sadece 

toprağından', 'Köklrini saran toprağın kokusu rahatsız etmemeli seni  tiksinme aralarına sızan solucanlardan da  yıllarca sendin yaşıyan koyun koyuna  kafa...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/toprak-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-adnan-ferit-33qdi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyama doğan gökkuşağıma, eşim BURCU ‘ya)

GÖKKUŞAĞI 

Saklı birkentte mutlu bir prenses vardı 

Sadece prenses değil 

Tanrının dünyadaki sevdiği evlatlarındandı 

O kadar severdiki tanrı onu 

Hep gülsün mutlu olsun isterdi 

Ve tanrı ona sen benim dünyadaki en güzel en temiz renklerimin dili 

O güzelliklerin yansımasıın derdi.... 

Günler gelip geçiyordu 

Prenses sadece tanrının verdiğigörevi yerine getirmeyi düşünerek, 

İnsanlara yardım ederek, onları mutlu ederek, yaşamaya devam ediyordu. 

Yüzünde gülücük, yanaklarında al 

Eteklerinde regarenk tohumlar yeryüzünü geziyordu 

Sevgi, iyilik ve tanrının renklerini ekiyordu. 

İnsanlara dağıttığı mutluluklarla birlikte. 

Kıraç bir dağ başına geldi bir gün, 

Soluklanmak istedi. 

Dağın bir yamacında tek başına kalmış ağacın gölgesine oturdu. 

Yorgundu uykusu geldi, 

Tam uykuya dalacakken diğer yamacın köşesinden 

kemikleri sayılan üç koyunla beraber 

Yorgun, bitkin, bir o kadar da mutsuz gözüken bir çoban belirdi. 

Zorlukla doğruldu, 

Çobana gülümsiyerek sordu. 

Nedir bu halin? 

Koyunların da neden bu kadar bitkin. 

Sanki günlerdir aç susuz kalmış gibisin.. 

Çoban derin bir nefes çekti ve.. 

_ Haklısın ben ve senin koyun diye gördüğün o üç yoldaşım 

günlerdir aç ve suya hasretiz dedi. 

yoldaşmı dedi prenses 

Evet, dedi adam 

Şu, beyaz postu şimdi simsiyah olan, hayallerimi taşıyan yoldaşım. 

Şu, postu kararmak üzere olan, içimden dışarıya taşan insan sevgisini taşıyan yoldaşım. 

Sonuncusuysa, sararmaya yüz tutmuş olan umutlarımın hamalı yoldaşım... 

Neden. dedi prenses neden bu kadar kötü görüyorsun herşeyi.. 

Nasıl görmiyeyim dedi çoban 

yıllar önce saklı kentte yaşardım, 

hayallerim vardı taşıyamadığım, 

sevgi doluydu kalbim 

ve umutlarım vardı bitmiyicek gibi paylaşmama rağmen. 

Peki ne oldu dedi preses? 

Çok sevmiştim dünya güzeli bir kızı dedi adam 

evlenip çocuklarımı büyütmekti amacım 

Bütün hayallerim onunlaydı 

Çekip gitti bir gün, bulamadım. 

Bir derviş oldum, içimdeki sevgiyi insanlığa taşıyayım dedim. 

Ama insanlar hep bir karşılık bekledi, 

Sevgilerimi alıp beni yüzüstü bıraktı. 

Yinede yılmadım tanrıya yakarıp dağlarda dolaşıp nefes alan tüm canlılara sarıldım 

Ama onlarda bir prensesin ardına takılmış 

Sana ihtiyacımızyok dediler beni terslediler. 

Bende bu kıraç topraklara gelip prenses gelmeden bir faydam olurmu diye bir canlı aradım. 

Uzaklardan bu ağacı görünce heyecanla bu tarafa yöneldim. 

Senide görünce son bir umut belki sana da faydalı olurum dedim. 

Haydi söyle bana derdin nedir çok bitkinsin sende. 

Sana bari bir faydam olsun..... 

Derdim yok. diyiverdi prenses farkına bile varmadan 

O anda yığıldı kaldı çoban oracığa. 

Umutlarını taşıyan yoldaşı simsiyah oluverdi 

Diğer yoldlaşrıyla birlikte. 

Nefesleri kesildi, 

Gözlerinin ışığı sönüverdi, 

Prenses aman Allahım ne yaptım dedi. 

Yalvarmaya başladı Allah’a 

Ne olur bir şeyler yap ne olur.. 

Ben artık yaşıyamam, 

Yapmam gerekenin aksine bir insanın umutlarını tükettim 

Bir değil dört cana kıydım. 

Beni cezalandır onu yaşat ne olur dedi. 

Birden gökgürüldedi. 

Önce hafif, sonra sağanak bir yağmur iniverdi 

Canlandı adeta tepe, koktu umut koktu mutluluk doğa. 

Çoban kendine gelirken, 

Postlar yıkanırcasına siyahlarını akıtırken, 

Prenses ayaklarının yerden kesildiğini hissetti. 

Rahatsızlık duymadı, korkmadı. 

Aksine mutluydu, al aldı yanakları rengarenkti etekleri. 

Mutluydu hemde çok, anlatılmazcasına 

birden asılı kaldığını hissetti boşlukta, 

baktığında aşşağılara, tepeye doğru 

Çobanı gördü, 

gayet sağlıklı 

bakıyordu şaşkınlıkla yukarılara 

Anlam veremedi yinede gülümsemeye devam etti. 

yağmur dinmişti 

bir melek beliriverdi yanıbaşında. 

Neden bakıyor öyle. dedi meleğe 

Melek gülümsedi 

o şimdi gökyüzünde dünyanın tüm güzel renklerini görüyorda ondan. 

nasıl dedi prenses. 

Sen şimdi bir kuşaksın gökyüzünde. dedi melek 

Tüm güzel renkleri yansıtan, 

Dünya var oldukça umutları tükenmek üzere olan insanlara adanmış, 

Bir Gökkuşağısın......', 'Dünyama doğan gökkuşağıma, eşim BURCU ‘ya) GÖKKUŞAĞI  Saklı birkentte mutlu bir prenses vardı  Sadece prenses değil  Tanrının dünyadaki sevd...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/gokkusagi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya', 'eskiya-adnan-ferit-w45lr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben dost aradım 

köşe bucak 

aş aradım dumanı tüten, sıcak 

anadan geçtim 

yar bilemedim 

dağlara vurdum kendimi 

gezenler hep çakalmış bu garip ne bilirdiki 

sürü gördüm sığınmaya 

karasın dediler koydular dışarıya 

eşkiya oldum sonunda bu dağlara 

dosta hasret 

anaya mahçup 

elimde çakaralmaz 

aklımdan sevdalarım çıkmaz 

ben derimki biçare 

kim koyacak bu kahpe dünyayı hale 

eşkıya olmak zor 

bu dağlarda 

nerde anam 

nerde yoldaşım 

çakallarmı masum 

yoksa benmi yanlışım.', 'ben dost aradım  köşe bucak  aş aradım dumanı tüten, sıcak  anadan geçtim  yar bilemedim  dağlara vurdum kendimi  gezenler hep çakalmış bu g...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eskiya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşer', 'mahser-ahmet-aksoy-u6v0i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüsnünü yitirmiş vakit, bu yüzden

esaret gibi çökmüş karmaşa

''geçilecek tümsekler düzelmiş''

aşamasız yaşam

insanla hayvan arasındaki, ince tül

''us'' korkudan buz kesmiş

neyseki urganlar çözülüyor

son bulacak bekleyiş.', 'hüsnünü yitirmiş vakit, bu yüzden esaret gibi çökmüş karmaşa ''geçilecek tümsekler düzelmiş'' aşamasız yaşam insanla hayvan arasındaki, ince t...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mahser-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maşuk', 'masuk-ahmet-aksoy-riw30', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vecdini kaybetmiş maşuk gibiyim

sevilenine karşı umarsız mahçup

ki o çiçekler verip güller derdiğim

ki o peşinden ölüme gittiğim

aşkıyla coşup gözlerimi kör ettiğim

lakin gözlerim, görmüyorsa artık, dünyevi aşkı, 

Leyla'' yı Şirin''i Aslı'' yı ne edeyim

ilahi aşkla kuşanmışsa yüreğim', 'Vecdini kaybetmiş maşuk gibiyim sevilenine karşı umarsız mahçup ki o çiçekler verip güller derdiğim ki o peşinden ölüme gittiğim aşkıyla coş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/masuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntikam Mukaderdir O Vakit', 'i-ntikam-mukaderdir-o-vakit-ahmet-aksoy-x5x0d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sigara gibi yakacaksam seni, 

ve çekeceksem alabildiğine içime, 

razıyım zehrine, 

lakin beni aldatıp, 

gireceksen kanıma

bir yılan gibi, 

işte o vakit

lanetlerim seni, 

ki son olarak, 

şunu da bil ki, 

intikamdır 

bu zehrin

tek panzehiri...', 'sigara gibi yakacaksam seni,  ve çekeceksem alabildiğine içime,  razıyım zehrine,  lakin beni aldatıp,  gireceksen kanıma bir yılan gibi,  i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/intikam-mukaderdir-o-vakit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Gül’e', 'kizil-gul-e-ali-osman-yilmaz-hbv1z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl sıkılıyorum nasıl? Bir bilseniz, 

Güz ayazında çıktım kırlara, 

Ömrümün güzünü yaşadığım şu anda.

Mevsim güz, vakit güz, öğleden sonra, 

Dolaşıyorum kırlarda, kendimle baş başa, 

Ortalıkta kır çiçekleri, birde ben yalnız, 

Bir çiçek kıpkızıl bakmakta bana, 

Tam da kır çiçeklerinin durur ortasında, 

Kim bilir kim? düşürdü seni, 

Bu parka kır çiçeklerinin arasına? 

Yağmur yağıp, güneş vurdukça, 

Belli ki köklerini salmışsın toprağa.

Evet dedi sessizce, kimse duymasın der gibi; 

Bir güzelin elinde geldim buraya, 

Beklediği sevgilisi gelmeyince o güzel, 

Savurup attı beni, işte bu toprağa, 

Ağlıyordu hıçkırarak, gözlerinden yaşlar akıyordu, 

Sanki dağlardan, pınarlar çağlıyordu, 

Fırlattı attı beni, kır çiçeklerinin arasına, 

Koşuyordu çılgın gibi, bakmadan arkasına.

Yapraklarını okşadım, parmaklarımla, 

Kokusunu içime çektim, doyasıya, 

Değişik bir gül, kıpkızıl rengiyle, 

Kadife elbise giymiş gibi yapraklarıyla.

Bu ülkeden değilmiş, söylediğine göre, 

Suyun öte yakasındanmış ataları, 

Yine bir sevdanın çiçeği olarak, 

Getirmişler yurdundan, bu topraklara.

İşte o an içimde yanmaya başladı bir ateş, 

Sinemde belirdi bir alev, yakmakta yüreğimi, 

Ateşler içinde ben, sevgiyle bakarken güle, 

Bilmeden sevdalandım galiba o güzele, 

Dudaklarımda bir sevda türküsü, başladım, 

Bağıra, bağıra kır çiçeklerine söylemeye.

Hayalimde canlandı birden, baktım güzele, 

Sevdalandım ona, bilmeden kim olduğunu bile, 

Saçlarını benzettim, elimdeki bu kıpkızıl güle, 

Ya gözleri? biraz gri-mavilikler içinde, 

Tıpkı gökyüzü maviliğindeki, gri bulut gibi, 

Bir boy tanrım, sırım gibi, uzun mu? Uzun, 

Rahvan adımlarla yürürken titretir yerleri, 

Gül dile geldi seslendi bana bir an, 

Neler oluyor, kendine gel şaşkın adam, 

Dinle bir, hayali güzele vurulmadan, 

Bilmediğin, görmediğin o güzele aşık olmadan, 

Kendine gel, aşk acısı sana koymadan, 

Ömrünün güzüne geldiğin tam bu an, 

Geçmişe bir bak, neler çektin be koca adam? 

Aşka aşığım ben dedim, kızıl güle, 

Aşık olamadım bu güne kadar bir güzele, 

Sevdim ben bu güzeli, kavuşamasam bile, 

Senden bir dileğim var ey kızıl gül; 

Öldüğümde, mezarımda açmanı isterim senden, 

Bu sevda benim sevdamdır sende biliyorsun, 

Dinlesinler aşkımı, mezarımı ziyarete her gelen, 

Haydi hoşça kal, suyun öte yakasından gelen gül, 

Asma sakın yüzünü, sevdalı gördünmü? bir gül, 

Son dileğim, senin gibi bir güle olmak bülbül, 

Yakışacaksın kızıl renginle sevdalı ellere, 

Anlat benim sevdamı, tüm sevenlere! ! ! ! ! ! 

İzmir 07.Kasım.2003 Kordon sahili', 'Nasıl sıkılıyorum nasıl? Bir bilseniz,  Güz ayazında çıktım kırlara,  Ömrümün güzünü yaşadığım şu anda. Mevsim güz, vakit güz, öğleden sonra...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/kizil-gul-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Adam..!', 'adam-gibi-adam-umut-gul-qifxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim ela

Boyum uzunca

Namım koca adam

Şiir yazarım

Efkarlanırım türkü söylerim

Keyiflenir İki kadeh içerim                     

Duygusalım, çabuk dolarım

bazen küçük bir çocuk gibi ağlarım

Yanlardan biraz açılmıştır saçlarım

geriye tararım 

Bolca da  kırlaşmıştır

asabiyim birazcık 

Kolay kabarmaz damarım

Ama kızarsam da tam kızarım

Hani derler ya pire için yorgan yakarım

Yakışıklı sayılmam 

Ama çirkinde değilim

Latifeyi severim

Şakayı tadında yaparım

ciddi ağırbaşlı adamım                          

Üzerinize afiyet dostlar

Çok ağır sevdalıyım

O güzelin gözlerinde kaybolmaktayım

Başıma her türlü bela 

Sevdadan geldi bilmekteyim

Karadeniz’in orta kısmındanım

Büyükçedir biraz burnum

Her dem sevdaya bulaşırım

Birazcık da deli sayılırım

Sevmesini

Sevdalanmasını

Sevda için ölmesini bilirim

Daha ne diyeyim dostlar

Kısacası adam gibi adamım..!', 'Gözlerim ela Boyum uzunca Namım koca adam Şiir yazarım Efkarlanırım türkü söylerim Keyiflenir İki kadeh içerim                      Duygusal...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/adam-gibi-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isyan ediyorum!', 'isyan-ediyorum-emine-cosgun-tpjrt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her geçen güne isyan ediyorum, 

                  Varligina dua, yokluguna isyan ediyorum.

Uzaklara düsse yolum, 

                  Olüm bile olsa sonum, 

             Yinede seni.........

                         

             SEVIYORUM....', 'Her geçen güne isyan ediyorum,                    Varligina dua, yokluguna isyan ediyorum. Uzaklara düsse yolum,                    Olüm bil...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/isyan-ediyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi agaci.', 'sevgi-agaci-emine-cosgun-64c14', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi için adadigim adak, 

                  Senin için diledigim dilek

Gelecegim için verdigim ümitleri, 

                  Herseyi sevgi agacina adadim.

Seninle olmayi istedim, 

                  Sevginle yanmayi arzuladim

Gelecegimi seninle kurmayi düsledim, 

                  Beyazlar içinde senin olmayi....

                          ISTEDIM...', 'Sevgi için adadigim adak,                    Senin için diledigim dilek Gelecegim için verdigim ümitleri,                    Herseyi sevgi a...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgi-agaci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim için yaparmisin?', 'benim-icin-yaparmisin-emine-cosgun-kuhd3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana canimi versem, 

           Bana kalbini verirmisin? 

Sana ömrümü versem, 

           Beni yine severmisin? 

Sana içimde kalmis olan sözlerimi, 

                       Kalbimden gelen seslerini, 

Aklimdan gecen tüm hayallerimizi, 

                       Birde geçmisin tüm nefretini

                           YOLUYORUM...

Beni anarken, 

             Bunlari benim için

                           Saklarmisin  SEVGILIM? ? ?', 'Sana canimi versem,             Bana kalbini verirmisin?  Sana ömrümü versem,             Beni yine severmisin?  Sana içimde kalmis olan söz...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-icin-yaparmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ertan-kargitug-socli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıktayım

Rüzgarın söylediklerini anlıyorum artık

Ağaçların kökleri inliyor

Mezartaşları derin derin düşünüyor

Nicelerinin gözlerinde hasret gözyaşları

Damladıkça yere

Yer gök inliyor

Yer gök dinliyor

Ruhlar sanki gezinmiyor artık

Yumruklarımı sıkamıyorum

Ağlayamıyorum

Gülemiyorum

Bir merdiven, bir ışık, bir yol arıyorum

Rabbin nuruna

Başımın tacı, kaderimin yazarı

Hasretimin yoluna

Bu alemden kopuyorum

Benliğim yolunu özlüyor

Bilmiyorum

Varlığın bana neler fısıldıyor

Karanlıktayım

Şimdi geriye kalan

Senin sevgin, benim sevgim

Sevgiler diyarına hoşgeldin

Diye seslen bana

Canımın cananı Rabbim', 'Karanlıktayım Rüzgarın söylediklerini anlıyorum artık Ağaçların kökleri inliyor Mezartaşları derin derin düşünüyor Nicelerinin gözlerinde ha...', ARRAY['Türk Edebiyatı','Şiir','Ertan Kargıtuğ']::text[], 8.5, '{"poet":"Ertan Kargıtuğ","poet_slug":"ertan-kargitug","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olum-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takdir', 'takdir-sule-aydemir-dy977', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sanatcı emek veriyor 

belki aylarca

sergisi sıkışıyor küçük bir ana

kulağa çalınan hoş minik melodi

yıllarda saklı bestesinin teri 

daha nice farkedilmeyen

takdire şayan

küçüklüğünde büyüklerin izi

narin bir sevgi gizi', 'sanatcı emek veriyor  belki aylarca sergisi sıkışıyor küçük bir ana kulağa çalınan hoş minik melodi yıllarda saklı bestesinin teri  daha nic...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/takdir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim için...', 'kalbim-icin-emine-cosgun-gx2tg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey sevgi sen nasil birseysin? 

                       Bana sevgi degil acilar tattirdin, 

Sevdigimi benden insafsizca aldin, 

                        Geriye hüzünlü bir kalp biraktin.

Ey kalbim, sense kösende usulcacik, 

                   Aci ve akan kanlar içindesin.

Bense sevdaya kanmisim, 

                   Bilmeden seni''de yakmisim.

Simdi ise sevgimi ariyorum, 

                   Yarali kalbimin acisini ben biliyorum.

Bunu simdi senden istiyorum

                   Bana sevgimi geri vermeni diliyorum.

Hersey kalbim için degil

                   Benim çektigim acilari senin''de çekmen için

Benim neler hissetigimi bilmen için

                   En sonunda beni anlayacagin için...

                    Sevgimi Istiyorum...', 'Ey sevgi sen nasil birseysin?                         Bana sevgi degil acilar tattirdin,  Sevdigimi benden insafsizca aldin,                ...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saadet olmaz.', 'saadet-olmaz-emine-cosgun-ygxv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum diyorsun, 

                    Yalan söylüyorsun.

Özlüyorum diyorsun, 

                     hiç gözükmüyorsun

                

                      Oysa ben.....

Sevginde yalanlarini, 

                  Özlemlerinde iftiralarini, 

Sözlerinde hatalarini

                  Birde gözlerinde baskasini

        

                      Görüyorum.......

Bana saadet''den konusma, 

                     Sevgisiz saadet olmaz, 

                                     Kalpsiz sevgi olmaz

Birde sevginin olmadigi yerde, 

                         

                            Sen asla olmazsin! ! ! .', 'Seviyorum diyorsun,                      Yalan söylüyorsun. Özlüyorum diyorsun,                       hiç gözükmüyorsun                     ...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/saadet-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Çeker', 'can-ceker-oguzkan-bolukbasi-nbhix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tükenmez akşamı yaşamın

Beklenen sabahlar bulutlara gizlenir

Can bu çeker ya

Aşk her mevsimde istenir

Göğüs kafesinde kilitlenir bir hayat

Nefesin hapistir çıkamazsın içinden

Oysa her şey sendedir

Ama düşünceler çıkar şirazesinden

Önüne set çekemezsin

Düşünce dediğin nedir ki

Aşktır aslında

Çünkü tüm sebepler aşka bağlanır

Tarifi imkansız şimdilerde aşk

Ne olduğunu bir bilen olsa

Yürekler kör

Dudaklar hissiz

Dokunduğu teni tarif eden yok

Söylenen hep hayal

Söyleten hayal 

Kelimeler sınırlı

Ama yine de

Can bu çeker ya

Aşk her mevsimde istenir', 'Tükenmez akşamı yaşamın Beklenen sabahlar bulutlara gizlenir Can bu çeker ya Aşk her mevsimde istenir Göğüs kafesinde kilitlenir bir hayat N...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/can-ceker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Böyle Olmayacak', 'bu-boyle-olmayacak-ayfer-ersoy-0fceh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu böyle olmayacak 

Bir yerelerde yokluğunun sonu elbet vardır

elbet vazgeçecek 

elbet hasret bitecek

bu böyle olmayacak

yanık izleri gibi taşıyorum içimde seni

ateşte ısınmış demir cubuk gibi 

demircinin ellerinde kaderim

bu böyle olmayacak

beklemek kaderde ihtimal olarak kalmalı

çağlayanlar suni sulardan çıkmalı

doğaya karışmalı kar suyu

dereler akmalı denize ulaşmalı

suya inmeli ceylanlar

sonra sen gelmelisin

gün ışığı gözlerin gülmeli

bu böyle olmayacak

özlemin delirtti beni

yollar ardı kesilmeyen sel; bulanık

toz duman heryer

karanlıkmı karanlık sensiz ev

bu böyle olmayacak

ya sen gel

ya izinver ben geleyim', 'Bu böyle olmayacak  Bir yerelerde yokluğunun sonu elbet vardır elbet vazgeçecek  elbet hasret bitecek bu böyle olmayacak yanık izleri gibi t...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-boyle-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudret-Kuvvet', 'kudret-kuvvet-refik-recep-pelit-1xfp8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çilem erkenden uyanır, uyandırır beni 

Yar etmez uyuduğum, altımdaki minderi

Rüyamda gördüğüm, serap gibi yerdi

Kalk artık hakikatle  yüzleş dedi.

Elimde tutamam yakar, ifna eder beni 

Toparlayamam, var sandığım düzeni

Bir karmaç karıştırarak, bulanık zihnimi 

Davran artık zaman ile güreş dedi.

Pençesindeki, beni öldürecek silah belki 

Zihnimi kemirir müptezel bir tilki

Alnımda, yıllanmış harab olmuş bir çizgi

Harakete geç artık, ufuktaki güneş dedi 

Bilemem nasıl silinir, kaderdeki bu yazgı

Ruhumda dolanır durur bir cin fikirli, 

Beyazlar giymiş bir gelin, söyler bir ezgi, 

Kudret ile kuvvet, birbirine özdeş dedi.', 'Çilem erkenden uyanır, uyandırır beni  Yar etmez uyuduğum, altımdaki minderi Rüyamda gördüğüm, serap gibi yerdi Kalk artık hakikatle  yüzleş...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kudret-kuvvet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Ben', 'seninle-ben-mehmet-ali-cibikli-2jfd2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimdeki kadehte, 

Seni görür gibiyim.

Şimdi sensiz bu yerde, 

Sanki deli biriyim.

Neden bilmem kaderim, 

Yazılmış kara kara.

Bir an olsun gülseydi, 

Talihim ara sıra.

Belki beni severdin, 

Koşardık mutluluğa.

Birlikte yaklaşırdık, 

İkimiz yarınlara.

Yarını yaşayalım, 

Seninle ben ikimiz.

Aşkımız hiç bitmesin, 

Hep yeşersin sevgimiz.', 'Elimdeki kadehte,  Seni görür gibiyim. Şimdi sensiz bu yerde,  Sanki deli biriyim. Neden bilmem kaderim,  Yazılmış kara kara. Bir an olsun g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kalmış Korku', 'gec-kalmis-korku-orcun-oruc-aykac-o2isr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir korku düştü içime

Yoksa akıp giden sen misin? 

Tam seni seviyorum diyecekken

Belki çoktan yalnızım zaten.', 'Bir korku düştü içime Yoksa akıp giden sen misin?  Tam seni seviyorum diyecekken Belki çoktan yalnızım zaten....', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gec-kalmis-korku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyumlama', 'doyumlama-serhat-kiciklar-qo5zp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim sana doyamamış

İnkar eder mi gördüklerini

Ellerim kıyamamış dokunmaya

İnkar eder mi sensiz

Kalbim seni sevmiş

İnkar eder mi dilim

Sen inkar edebildin mi? 

Sen inkar etmezken

Benden bekleme yanılırsın

Varlığım gibi hiç inkar etmez

Ruhumun sana aitliğini

Aynısını benimle yaşarken

Seninle yaşamak istemez mi

Bu aşık gönlüm, 

Yanında yanmak istemez mi 

Taş yürek dayanmaz, 

Erir sevgin önünde

Bu kalp durmaz mı sensiz

           (30.06.2003)', 'Gözlerim sana doyamamış İnkar eder mi gördüklerini Ellerim kıyamamış dokunmaya İnkar eder mi sensiz Kalbim seni sevmiş İnkar eder mi dilim S...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/doyumlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onların Yürekleri', 'onlarin-yurekleri-nevzat-bayramoglu-hurdemi-hsc83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiye, muhabbete atar onların yürekleri, 

Hasretliği, sevdayı ve aşkı getirirken dile.

Kardeşlikten, barıştan yanadır bütün dilekleri, 

Uzundur ömrü şairlerin, erken ölseler bile.

28 Eylül 2002 - Ankara', 'Sevgiye, muhabbete atar onların yürekleri,  Hasretliği, sevdayı ve aşkı getirirken dile. Kardeşlikten, barıştan yanadır bütün dilekleri,  Uz...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/onlarin-yurekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde', 'sahilde-serhat-kiciklar-ho68g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün sahildeki parktaydım

Özlediğim dalga sesleri, 

Motorların, martıların sesleri, 

Huzur veriyordu bana 

Huzurun asıl sebebi bir çiçekti

Sesler bahanesi.

Evet huzur vardı o sahilde

Bir anlıkta olsa yetti bana

Bugün sahildeki parktaydım

Özlemlerimin dışında sesler vardı, 

Duymak istemediğim.

Acı veriyordu bana, 

Evet acı vardı orada

Tedirginlikle yaşanan bir

Sevgi vardı orada

Çileğim tedirgindi orada', 'Bugün sahildeki parktaydım Özlediğim dalga sesleri,  Motorların, martıların sesleri,  Huzur veriyordu bana  Huzurun asıl sebebi bir çiçekti ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahilde-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Dediler', 'hos-dediler-nevzat-bayramoglu-hurdemi-em89v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalansız, 

yavan olmayan sohbetlerle yaşadık,

en sıcak dost muhabbetlerimizi.

En güzel günlerimizi çıkarsız çabalarla süsledik; 

onur ve gurur dolu yarınlar yaşatmak için. 

Şöyle bir baktılar da bize... 

"Bu yaptıklarınız ne güzel iş" dediler.

Hep beraber sevindik,

birlikte neşelendik.

Dost yüzler gördükçe yanımızda

gülmelerimizin arasına gizledik,

en masum hüzünlerimizi.

Kimi dost bildiklerimiz anlamadılar da bizi...

"Bu çabalarınızın çoğu boş" dediler.

Oysa yüreklerimiz bir attı,

yarınların umutlarını yarattık.

Göz ardı edilmiş 

gönül yükünü sırtlanırken de iki tek attık...

Anlamadılar da bizi...

"Bunların hepsi sarhoş" dediler

Kimler umutlarımızı ne kadar sevdiyse, 

biz onları daha fazla sevdik... 

Ve tek hedef için tek yürek olduk. 

Nihayet görenler de oldu bizi... 

"Boşa gitmez bu gayret, hepsi pek hoş" dediler.

07 Haziran 2002 - Dışkapı', 'Yalansız,  yavan olmayan sohbetlerle yaşadık, en sıcak dost muhabbetlerimizi. En güzel günlerimizi çıkarsız çabalarla süsledik;  onur ve gur...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hos-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sonbahardı', 'mevsim-sonbahardi-nevzat-bayramoglu-hurdemi-9s7hp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son buluştuğumuzda yar mevsim sonbahardı

Bende hicran şarkısı sende göz yaşı vardı

Hatırlıyorsan verdiğin karar bir anlıktı

O Eylül akşamı ne kadar da karanlıktı

Ayrılık ahengiyle ayrılmaktayken eller

Gözyaşı misali dökülüyordu gazeller

Dalgın ve yaşlı gözlerle bakarken peşinden

Bana kalan bir sıcak buseydi gidişinden

Uzaklaşırken sen gözyaşlarım aşikardı

Son görüştüğümüzde yar mevsim sonbahardı

05 Haziran 2000 – Batıkent', 'Son buluştuğumuzda yar mevsim sonbahardı Bende hicran şarkısı sende göz yaşı vardı Hatırlıyorsan verdiğin karar bir anlıktı O Eylül akşamı n...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mevsim-sonbahardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim', 'severim-mehmet-ali-cibikli-r31yf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykusuz her gece, seni yaşadım, 

Dolaştım çaresiz, kaldırımları.

Hasretinden yandım, sensiz yıkıldım, 

İçimizde büyüdü, aşk yangınları.

Sabah olmuyor ki, sıkıntım bitsin, 

Karanlık geceler, üstüme gelmiş.

Arzum, hayalim sen, ümidim sensin, 

Seni hayal etmek bile güzelmiş.

Seni sevdiğimi, şimdi anladım, 

İsterim ki her gün, yanımda olsan.

Hayalleri sensiz, yaşayamadım, 

Güneş gibi gelip, gönlüme dolsan.

Koş gel artık bana, sarıl, sev beni, 

Arzularım gerçek olsun isterim.

Her an, her dakika özlerim seni, 

Seni bin yıl sevdim, bin yıl severim.', 'Uykusuz her gece, seni yaşadım,  Dolaştım çaresiz, kaldırımları. Hasretinden yandım, sensiz yıkıldım,  İçimizde büyüdü, aşk yangınları. Saba...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/severim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamal', 'hamal-refik-recep-pelit-rsjad', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sayrılık varki benim başımda, 

Bırakmaz peşimi hep bir adım önümde, 

Aklımdadır her attığım adımda 

Marazlı olan ben değilim aslında.

Sirayet etti birden, olamadım farkında, 

Dört yanımı çevreledi, kalakaldım bir anda, 

Birt türlü görmedim, burnumun''da ucunda 

Körebe oynayan ben değilim aslında.

Bir sağda bir solda, bilmiyorum ne yanda,

Sattığı para etmez, aklını oymuş bir tafra,

Luzumsuz kahırlar oluvermiş safra,

Hamallık yapan ben değilim aslında.', 'Bir sayrılık varki benim başımda,  Bırakmaz peşimi hep bir adım önümde,  Aklımdadır her attığım adımda  Marazlı olan ben değilim aslında. Si...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hamal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksen', 'eksen-hakki-teke-rum3a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görürüm bu sevda sarsar, yıpratır pek seni, 

Sen bir dairesin bende onun ekseni, 

Uzun ince bir yolda yaş geçse de sekseni, 

Sen bir dairesin ben de onun ekseni.', 'Görürüm bu sevda sarsar, yıpratır pek seni,  Sen bir dairesin bende onun ekseni,  Uzun ince bir yolda yaş geçse de sekseni,  Sen bir dairesi...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli Ve Kırılgan Çocuk', 'kirli-ve-kirilgan-cocuk-nevzat-bayramoglu-hurdemi-rbghp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Altı Mart akşamıydı, 

Ankara Metrosunda; 

Bir şairin kafası biraz çakırdı.

Ve aynı zamanda

Ve aynı vagonda 

Ve kontrplak zulasında, 

Bir çocuk yatmaktaydı.

Çocuk kirli ve kırılgandı, 

Kirli ve kırılgan çocuk, 

Her şeyden ve herkesten habersiz uyumaktaydı.

Ve oradakiler, 

Kirli ve kırılgan çocuğa, 

Şaşkın ve tuhaf bakmaktaydı.

Çünkü kirlilerin yani öylelerin, 

Orada oturması bile yasaktı.

Hareket ettiğinde tren, 

Çocuktan bihaberdi götüren.

Minik elleri başının altındaydı.

Ve biçare bir beden, 

Öylece uyuklamaktaydı.

Meraklı gözler hâlâ şaşkın,

Belki de hiçbir ressamın 

Çizmek istemeyeceği bu tabloya, 

Hâlâ bakmaktaydı.

Aynı zamanda şair; 

Kırçıl sakallı bir başka şairin, 

Kitabını okumaktaydı.

Aslında okur gibi yapmaktaydı.

Çünkü aklı o çocuktaydı.

Minik ve kirli elleri çocuğun, 

Terk ederken ağır ve terli alnını...

Kalktı yerinden şair, 

Duramadı.

Başa bela yüreği, 

Yüreğe isyan gözleri, 

Buna engel olamadı.

Çöktü ve dokundu yavaşça, 

Minik ve kirli bedene...

Hemen uyandı çocuk, 

Ve ürkek

Ve korkak baktı çevresine.

Şair:

“ne haber dedi

bu ne hal böyle

karnın açtır senin 

hadi doğruyu söyle”

“Karnım aç Amca”

Dayanamadı şair bu bitkin sesi duyunca.

Cebinde yedi buçuk milyonu vardı.

Hatırladı evdeki iki çocuğunu

Ve verdi parasının iki buçuğunu.

Kirli parmakların o an için hakkı oydu.

Otururken yerine şair, 

Sevecen bir ses duydu.

“al yavrum şu ekmeği ye”

Yaşlı bir teyze iki somundan birini

çocuğun kucağına usulca koydu.

Üç beş kuruş daha verdi ötekiler...

Çocuk masumdu, 

Çocuk suskundu

Ve öylece bakıyordu en beyaz yerinden

Şaşkınlık belli oluyordu gözlerinden.

Kapıya yanaşırken Şair, 

Çocuğun durdu yanında.

Eğildi kulağına ve sordu.

“gece nerede kalacaksın”

“terminalde Amca”

Yüreği yeniden buruldu. 

Yüreğe isyan gözleri dalmışken

Kirli ve kırılgan bedene, 

Şairin şu sözleri duyuldu.

“kaldırımda görsek seni 

yanından geçiyoruz 

ve dönüp bakmıyoruz bile. 

İçimizde görünce de böyle

iç çekip kendimizden geçiyoruz.

aslında günlük bu yardımlar nafile.

utansın be yavrum utansın, 

seni getirenler bu hale.”

Şaire bakarken vagondakiler, 

Kapılar açıldı.

Ve bir mart akşamında.

Bir şairin kafası biraz çakırdı.

(06 Mart 2003 - Ankara Metrosu)', 'Altı Mart akşamıydı,  Ankara Metrosunda;  Bir şairin kafası biraz çakırdı. Ve aynı zamanda Ve aynı vagonda  Ve kontrplak zulasında,  Bir çoc...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/kirli-ve-kirilgan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuramadım+', 'kuramadim-bayram-tunca-9167k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuramadım anlatılanla gerçekler arasında bir denge

Bana anlatılanlar nerede, görüp duyduklarım nerede

Anlayamadım dünya mı değişti yoksa kul mu değişti

Neredeyse kafayı yiyecektim, imdadıma iman yetişti

23.10.2003-10:23

Aşk Ateşten Gömlek', 'Kuramadım anlatılanla gerçekler arasında bir denge Bana anlatılanlar nerede, görüp duyduklarım nerede Anlayamadım dünya mı değişti yoksa kul...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kuramadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Oralar Eskiden', 'bizim-oralar-eskiden-nevzat-bayramoglu-hurdemi-56i7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün erken inerdi 

Bizim oralara eskiden

Kendi kendime mesela 

Hiç uyanamazdım

Tembellikten değil be gardaş

Dünden kalma yorgunluktan

Bizim oraların dağları var ya 

Fecir seyrinin heybeti dağlar

Ne kadar serindir bir bilsen

Sabahın seherinde onlar

Uyku semesindeyken 

Soğuk kuyu lastik içinde

Çobanlığa yürüyen

Küçük ve çıplak ayaklar

Ne kadar serindir bir bilsen

Dağların böğrüne çıkardık gardaş

Hem de güneşten önce çıkardık

Yamaçlarda birbirimizi arardık

Buluşurduk çoban çobana 

Gütmelerimizi birbirine katardık

Gütmeler çayır çimene 

Bizler oyuna dalardık

Yerde yuvalanıp tepişirken bile 

Azığımızı indirmezdik dalımızdan

Bu yüzden işte gardaş 

Bir de fukaralıktan

Hiç eksik olmazdı yamalık donumuzdan

Kararmış değneklerimizi 

Hiç düşürmezdik elimizden

Yani küçük ve kirli ellerimizden

Kirli dediysek el kiri sanma gardaş

Bulaşmadır o kara ellerimize

Üç gün evvel aşırdığımız

Yeşil kabuk süt cevizlerimizden

Çayır ışkınlarından yaratırdık

Öyle her çocuğun

Bilmediği oyuncaklarımızı

Kuru ağaç gövdesinden yapardık

En şaheser yapıtlarımızı

Heykeltıraşlar görse

Vallahi kıskanırdı

Hoplar zıplar takla atıp coştukça coşardık

Sakin ve gafil bir anımızda

Birden deli gibi koşardık

Delilikten değil gardaş büvelekten

Büvelekler gütmelerimizi kovalardı

Biz arkalarından koşardık

Bazen atışır itişir dövüşürdük

Ama uzatmazdık

Saatine kalmaz barışır

Aynı ekmeği bölüşürdük

Bazen de birimizin bulduğu

Sahipsiz ve ezik

İzmaritsiz ve eksik

Cigaraya üşüşürdük 

Yağmur yağardı 

Hep beraber ıslanır

Eski gübre naylonları altında 

Hep beraber üşürdük

Biz dağlardayken

Yani çocukken

Yani çobanken

Hiç cüzdanımız olmazdı bizim

Olmasını da istemezdik

Paranın bu yüzden bilemezdik

Sarısını yeşilini grisini

Bu yüzden severdik

Azık torbamızdaki 

Sarı bazlamayı yeşil soğanı

Bir de...

Sen anla gayrı gerisini

Bizim oralarda tele-nin ne fonu 

Ne vizyonu vardı

Anlayacağın gardaş

Şerden  şeherden haberimiz olmazdı

Biz dağlarındık dağlar bizimdi

Belki de bu yüzden o zamanlar

Her şey daha bir güzeldi

Köydeyken biz

Yani çobanken 

Yani çocukken

Akşam çabuk inerdi 

Bizim oralara eskiden

Ve yatıp uyurduk erkenden

Tembellikten değil gardaş

Yorgunluktan... Yorgunluktan.	

(04 Mart 2002 – Göğüsün Pınar, Demirci Köyü)', 'Gün erken inerdi  Bizim oralara eskiden Kendi kendime mesela  Hiç uyanamazdım Tembellikten değil be gardaş Dünden kalma yorgunluktan Bizim o...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/bizim-oralar-eskiden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-serhat-kiciklar-98wmu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklıkları aştığım güne ihtiyacına, 

Sevgini yaklaştırırmısın? 

Beni hayatının içine alırmısın? 

Yoksa dışlarmısın? 

Yanında olmaya başladığım gün

Heyecana kapılıp, inanmayıp uzaklaşırmısın? 

Yoksa sarmalarmısın kalp kollarında

Yoksa sensizliğe mahkum edip, 

Ölümümü hazırlarmısın? 

Törenime gelip toprağı pike edip, 

Üşümemem için üstümü örtermisin? 

Hiç olmazsa sıcaklığını

Topraktan almamı istermisin? 

Eğer istersen gel aşkım

Uzaklık yok aramızda, 

Ben heryerde alırım verdiklerini

İçimde öyle izole etmişim ki sevgini

Senin sıcaklığın cehennemim olsun

Ama dilim seni inkar edemesin

Kalbim bir olsun dilimle, 

Seni çok seviyorum desin.

Geride bıraktıklarım kalbinde anıt olsun

Her an saygıyla anasın beni

Geride bırakacağım sevgim ders olsun

Üzemesinler, hiç üzemediğim tatlı kalbini

Arkamdan edeceğin duaların

Sevgi sözcüklerin, kalbindeki içtenlik olup

Ruhuma aksın

          (04.06.2003)', 'Uzaklıkları aştığım güne ihtiyacına,  Sevgini yaklaştırırmısın?  Beni hayatının içine alırmısın?  Yoksa dışlarmısın?  Yanında olmaya başladı...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dua-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Aşık', 'saf-asik-nevzat-bayramoglu-hurdemi-h5zac', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah! saf aşık ah

Böylesine sevmek senin neyine

Bak gözlerini diktin 

Daldın derinlere yine

Bilmez misin adam gibi sevmenin zor olduğunu

Hiç görmedin mi 

İçten sevenlerin ne çok yorulduğunu

Ah! Saf aşık kamçılıyor değil mi

Nasılda kamçılıyor çıplak yüreğini

Kafandaki o malum düşünceler

Daha dur 

Eğer böyle giderse sevmelerin 

Yani O, yani sevdiğin

Senin sevdiğinden bihaber

Neler gelir başına daha neler

Söyleyim mesela saf aşık 

Gizinde beselediğin o bahaneler var ya

Bir gün gizli aşkına kanayan yaran olacak

Feryat edecek yüreğin o zaman ve

En olmadık yerde gözlerin yavaş yavaş dolacak

Ah! saf aşık ah 

Böylesine sevmek senin neyine

(17.Ekim.2003 - Hasköy)', 'Ah! saf aşık ah Böylesine sevmek senin neyine Bak gözlerini diktin  Daldın derinlere yine Bilmez misin adam gibi sevmenin zor olduğunu Hiç g...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/saf-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakma', 'birakma-serhat-kiciklar-tm5q0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerime, 

Kalbin kalbime kenetlenmişken

Bırakma beni

Düşüncelerin sevgime

Varlığın aşkıma kenetlenmişken

Çözme beni

Ellerim ellerinde

Aşkım yanında olsun

Ruhunun, beni yakarışları durmazken

Durdurma bu aşkı

Gerçeklerin doğru diyorsa

Yanlıştan bitirme beni

Anla artık

Delicesine seviyorum seni

               (27.05.2003)', 'Gözlerin gözlerime,  Kalbin kalbime kenetlenmişken Bırakma beni Düşüncelerin sevgime Varlığın aşkıma kenetlenmişken Çözme beni Ellerim eller...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birakma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Ateşi', 'sensizlik-atesi-mehmet-ali-cibikli-ntjxp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç yıl oldu, seni görmedim, 

Yokluğun içimde, yaralar açtı.

Bu geçen günlerde, hergün özledim, 

Gecemle gündüzüm, yine karıştı.

Hiçbir zaman dinmez, fırtınalarım, 

Taşkın seller gibi, içimde hisler.

Dur desem durmuyor, ona yanarım, 

Yokluğun acısı, kalbimi süsler.

Hani nerde sende, o eski vefa? 

İnsan çektirir mi, insana böyle? 

Sen beni düşünmez, sürersin sefa, 

Günahlarım neymiş, gel bana söyle.

Hani sen de beni, çok seviyordun? 

Söyle, sensiz hayat, geçer mi dersin? 

Sevgimiz azalmaz, artar diyordun, 

Niçin benden böyle, kaçıp gidersin? 

Bu bitimsiz sevi, böyle mi biter? 

Yokluğun çekilmez, yaşanmaz oldu.

Şimdi sensiz olmak, ölümden beter, 

Sensizlik ateşi, gönlüme doldu.', 'Bilmem kaç yıl oldu, seni görmedim,  Yokluğun içimde, yaralar açtı. Bu geçen günlerde, hergün özledim,  Gecemle gündüzüm, yine karıştı. Hiçb...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensizlik-atesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bardak Ve Sürahi', 'bardak-ve-surahi-nevzat-bayramoglu-hurdemi-0exyx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendini beğenmek ve kibir           

yarasaydı eğer işe

eğilir miydi koca sürahi

küçücük bardağın önünde

Dimdik  dururken  bardak

kesilir miydi ayakları 

sürahinin yerden

Bundan  buluyor  yerini  demek

insanoğlunun gözünde ki adalet

Hoyratça bırakılırken sürahi yere

kutlanıyor bardak alnından öpülerek.

(18 Haziran 1999 - Kızılay)', 'Kendini beğenmek ve kibir            yarasaydı eğer işe eğilir miydi koca sürahi küçücük bardağın önünde Dimdik  dururken  bardak kesilir mi...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bardak-ve-surahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Otuzbeşlik Hikayesi', 'bir-otuzbeslik-hikayesi-nevzat-bayramoglu-hurdemi-gm350', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR OTUZBEŞLİK

HİKAYESİ

Mart ayının içinde

Çok sıradan bir gündü

“Otuzbeşlik” açıldı

Ne bayram ne düğündü

İlk yudum genzim yaktı

Allah’tan mezem çoktu

Gözüm şişeye baktı

Vallah fazla göründü

İkinci kadeh doldu

İçim biraz hoş oldu

Dedim ya mezem boldu

Hepsi güzel üründü

Üçüncüye bir baktım

Hemen namertlik çaktım

Onu yavaşça çektim

Şişenin forsu söndü

Dördüncü çok bekledi

Gönlüme gam yükledi

Bir de duygu ekledi

Sözüm şiire büründü

O şişenin ta kendi

Beşinci de tükendi

Bilmem kim kimi yendi

Benimde başım döndü

Bu anlatılan ne mi

Bizim bildik Hürdemi

Bulmuş güzel bir demi

Her hal biraz övündü

(26 Mart 1998 - Hasköy)', 'BİR OTUZBEŞLİK HİKAYESİ Mart ayının içinde Çok sıradan bir gündü “Otuzbeşlik” açıldı Ne bayram ne düğündü İlk yudum genzim yaktı Allah’tan m...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-otuzbeslik-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-serhat-kiciklar-1rkcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özleminle yanacak olsa kalbim, 

Sensizlikle kavrulacak olsa

Aşkın su olur söndürür kor ateşimi

Gözlerin yaksa gözlerimi

Delip geçse odağımı

Aklım çıkacak olsa yerinden

Aşkın mantığım olur, sabırla bekler

Gücünle mani olurum.

Tenin içimi yaksa, terin tenimi

İçim içinde birleşse, sevgin sevgimde

Dağları önüme koysalar

Dağlar yüreğim 

Vazgeçmez sevdasından

Gerçek sevgilin

         (27.05.2003)', 'Özleminle yanacak olsa kalbim,  Sensizlikle kavrulacak olsa Aşkın su olur söndürür kor ateşimi Gözlerin yaksa gözlerimi Delip geçse odağımı ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/daglar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-nevzat-bayramoglu-hurdemi-n5lg2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi biliyorsun			

Yüreğimde kalıp gitme		

Yere niye bakıyorsun			

Öyle masum dalıp gitme		

Hayatıma can katmışken		

Aşkı seninle tatmışken		

Beni çok mutlu etmişken		

Şimdi derde salıp gitme

		

Bizdik gününü gün eden			

Şimdi gidiyorsun neden 

Neye yarar sensiz beden

Seni benden alıp gitme

Verin hele kalem kâğıt 

Sevenlere olsun öğüt 

Hürdemiyim eyler ağıt

Yıllarımı çalıp gitme

 			

(11.Ekim.1992-Sakarya Cad.)', 'Sevdiğimi biliyorsun			 Yüreğimde kalıp gitme		 Yere niye bakıyorsun			 Öyle masum dalıp gitme		 Hayatıma can katmışken		 Aşkı seninle tatmı...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitme-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapar mı Sapar', 'sapar-mi-sapar-nevzat-bayramoglu-hurdemi-49opz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kamiller tükenip yoz biriktikçe

Kıyamet bu yüzden kopar mı kopar

Dürüstler kendini göstermedikçe

Düzenbaz paraya tapar mı tapar

Cehalet bedene zincir vurdukça

Başa gelenleri hayra yordukça

Hain düzenini böyle kurdukça

Zalim dediğini yapar mı yapar

Riyakâr olanlar önde gittikçe

Yalanla dolanla ömür bittikçe

Hacılar hocalar haram yuttukça

Cahiller el etek öper mi öper

Sömürüp yiyene bey denildikçe

Şükür yeter benim pay denildikçe

İş işten geçip de vay denildikçe

Eşekler adamı teper mi teper

Hürdemi bu devran böyle giderse

Garibanlar canla  bedel öderse

Madrabaz mazlumla alay ederse

Doğru da yolundan sapar mı sapar

(23.Kasım.2002  Hasköy)', 'Kamiller tükenip yoz biriktikçe Kıyamet bu yüzden kopar mı kopar Dürüstler kendini göstermedikçe Düzenbaz paraya tapar mı tapar Cehalet bede...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sapar-mi-sapar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Nefes', 'i-lk-nefes-serhat-kiciklar-n9lh5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçinden aldığım o ilk nefesin

Tattığım o ilk kokun

Dudaklarımda sonum olsun

Kalbin kalbimde son bulsun

Senden aldığım o ilk nefes

Son nefesimde alacak olsun

Seni gören gözlerim

Aynada kendimi görmez olsun

Utansız sensiz kalmaya

Kırılsın yüzüm aynada

Gördüğüm gözleri aratmasın, eksiltmesin

      (26.04.2003)', 'İçinden aldığım o ilk nefesin Tattığım o ilk kokun Dudaklarımda sonum olsun Kalbin kalbimde son bulsun Senden aldığım o ilk nefes Son nefesi...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilk-nefes-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Sesleri', 'su-sesleri-halim-yazici-uqbrf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hey yağmurun kaytanı yağmurun kaytanı

dünyayı al menekşe çocuk gözlerinle

sicim olup  topaç çevirme

su gölgesiyle büyür büyürse

bildiğin ne varsa alıp gider karışır denizlere

bunu ne ustalar söyler ne kürekleri mahkumların

duru göğsüyle kucaklar deli nehirleri

anıları saklarken göğsünde su sesleri

          - hey su sesleri su sesleri

             anılarımı yazsam üstüne

             saklar mısın ölümleri

             su sesleri hey su sesleri.', 'hey yağmurun kaytanı yağmurun kaytanı dünyayı al menekşe çocuk gözlerinle sicim olup  topaç çevirme su gölgesiyle büyür büyürse bildiğin ne ...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-gulay-atilay-7w5pm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Simdi bir an dönerek gerilere, hani

Bir zamanlar beni ölesiye yaşatan

Ellerimi tutup sevecen ellerinle..

Çevremi sımsıcak bir sevgiyle kuşatan

Seni arıyorum...

Bir deniz hıçkırıyor ta içimde, dinle

Giderek yalçın kayalar, kumlar eriyor

Simdi baş başayım bir kıyıda kendimle

Ve bende var ettiğin o ben can veriyor

Seni arıyorum...

Gülerdim bir zamanlar güneş batmazdı

Baştan başa bir gül bahçesiydi ortalık

Renkler ya mavi, ya pembe, ya beyazdı

Oysa şimdi ne yana baksam karanlık

Seni arıyorum...

Varsın ama yoksun, yanımdasın, değilsin

Gözlerim boşuna deliyor geceleri

Tek seni bir kez daha görebilmek için

Daldırıp ellerimi benden içeri

Seni arıyorum...

Ellerim içimde bir kan gölüne batıyor

Bağırıyorum kimseler duymuyor sesimi

Dişlerim hırsla dudaklarımı kanatıyor

Ve senden uzakta verirken son nefesimi

Seni arıyorum...

Bu son aldanışım, son yıkılışım olacak

Gel sende boş artık gelmesen de, ben yokum

Yinede son bir ümit kırıntısıyla, bak

O her şeyi yitirdiğim anda bulduğum

SENİ ARIYORUM! ! ! 

Ümit Yaşar Oğuzcan', 'Simdi bir an dönerek gerilere, hani Bir zamanlar beni ölesiye yaşatan Ellerimi tutup sevecen ellerinle.. Çevremi sımsıcak bir sevgiyle kuşat...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-ariyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlatmanı bekliyorum', 'aydinlatmani-bekliyorum-yildiz-bilgin-k156l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizin sonsuz maviliğine umut bağladım, 

Kıyılarda tükettim bekleyişlerimi, 

Hep sensiz geçti gemiler limandan, 

Gözümden bir tek damla yaş akmadı.

Onlar sana aitti sana kalmalıydı.

Kimselere söyleyemedim acılarımı, 

Bekleyişimin öyküsünü kimselere anlatamadım, 

Nice fırtınalar koptu yüreğimde, 

Dalgalar dövdü hayallerimi, 

Sığınacak bir liman, 

Yaslanacak bir omuz aradım, 

Her gece ay paramparça oldu, 

Her gece yıldızlar, birer birer düştü sokaklara, 

Yıldızları saçlarına takıp gelmeni

Ve bir güneş gibi doğup, aydınlatmanı bekliyorum, 

Sensiz bu zifir karası dünyamı.', 'Denizin sonsuz maviliğine umut bağladım,  Kıyılarda tükettim bekleyişlerimi,  Hep sensiz geçti gemiler limandan,  Gözümden bir tek damla yaş...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Bilgin']::text[], 8.5, '{"poet":"Yıldız Bilgin","poet_slug":"yildiz-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aydinlatmani-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Sonu', 'gecenin-sonu-alptekin-biber-ei1d1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine kurşunlar deliyor karanlığı

Kulaklarım ısrarla sessizliğini aramakta gecenin

Kan kokusu gelmekte karşıdaki Cudi’den

Kurşun yiyenlerin, yere düşenlerin

.                 acı feryatlı suluetleri karışıyor manzarama

Yüreğimde katmer katmer kabarıyor sancılar

Çıldırıyorum dakikaların ilerlemeyişine

Kulaklarımı kapattım artık

Şimdi sadece gözlerim açık

Tüm benliğimle şafaktayım

.                    ta ki onu bulanadek

Ama biryandanda biliyorum ki şafak

.                    kanlı cesetlerle lekelenecek.! 

			12 HAZİRAN 1995 /Şırnak', 'Yine kurşunlar deliyor karanlığı Kulaklarım ısrarla sessizliğini aramakta gecenin Kan kokusu gelmekte karşıdaki Cudi’den Kurşun yiyenlerin, ...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gecenin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlı Sabah', 'kanli-sabah-alptekin-biber-pk81e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şafakla karardı günleri

Kana boyandı gönülleri

Doğan güne gülemedi 

Morarmış yüzleri

Ölü gözlerinde garip bir çelişki

Yamru, yumru vücutlarında 

Ölümün acı izleri

Ve kahrolası kurşun delikleri

Kana boyadı koca günü

Ve akan kan

Üzerlerine acımasızca bakan

Gözlere ve ellere inatla

Birleşip düğümlenmekte

Ölmün başucunda

Ama artık

Sevdalı düşler olmayacak

Cahil dünyalarında

Vede görmemişliğin kabalığı

Vede geri kalmışlığın çirkinliği

Elleri silah tutmayacak artık

Korkuya karşı

Ölümleri getirmedi, 

Getirmeyecekte barışı...

			10 HAZİRAN 1992/ Şırnak', 'Şafakla karardı günleri Kana boyandı gönülleri Doğan güne gülemedi  Morarmış yüzleri Ölü gözlerinde garip bir çelişki Yamru, yumru vücutları...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kanli-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledim', 'bekledim-alptekin-biber-gisrk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şehir alacasında 

Güneşin doğduğu yerden 

Bekledim sevdayı

Binbir umutla 

           Umut kara 

		Umut zından yüreği

Doğuşun karşısında

		Eritiyor seviyi, 

Eriyen sevda 

 		Akıyor kanayana, 

Kanayan yol alıyor 		

		Adım adım yarına...

(Sevda umuda kestiğinde, 

umut ışığa dönecek bu şiirde) 

				10 HAZİRAN 1994', 'Bir şehir alacasında  Güneşin doğduğu yerden  Bekledim sevdayı Binbir umutla             Umut kara  		Umut zından yüreği Doğuşun karşısında ...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bekledim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun', 'suskun-alptekin-biber-3rin2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susmaktasın, görüyorum.

Etrafında yanlızlık duvarı, 

Sanki korkuyor dumanlı gözlerin, 

Apansız inen akşamdan.

Susma canım

Ellerini kapama yüzüne.

Düşünki ılık bir rüzgardır akşam

Aydınlığa uzanan bir köprü

Yanlızlıktan kurtaracak seni sabahın sesi.

Uzaklarda aklın biliyorum, 

Lanet olası karanlıkta değil.

Düşlerde gezmek güzeldir canan, 

Islanmak güzeldir sevda yağmurlarında.

Teslim olma yanlızlığa, korkma.

Izdırabın sona ersin, 

Konuş artık bebek

Mutluluk uzak değil kapımızda.

                                             21 HAZİRAN 1991', 'Susmaktasın, görüyorum. Etrafında yanlızlık duvarı,  Sanki korkuyor dumanlı gözlerin,  Apansız inen akşamdan. Susma canım Ellerini kapama yü...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/suskun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-alptekin-biber-up4gj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızım a dostlar 

Üşüşün başıma

Dırdır edin, 

Vır-vır edin, 

Çekip çekiştirin, 

Kavga edin, 

Bağırıp çağırın, 

Öpüp koklayın, 

Sövüp sayın, 

Beni yanlız bırakmayın...

                   07 ARALIK 1990', 'Yalnızım a dostlar  Üşüşün başıma Dırdır edin,  Vır-vır edin,  Çekip çekiştirin,  Kavga edin,  Bağırıp çağırın,  Öpüp koklayın,  Sövüp sayın...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-alptekin-biber-rg9jk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen sevgiyle büyümelisin yavrum...

Barışla, umutla büyümelisin.

O pırıl-pırıl yüreğin hep öyle kalmalı canım; 

Hep sevecen, 

                 hep umut dolu

                                   ve hep barıştan yana.

Yüreğinde sevda gülleri açsın birtanem

Katmer-katmer...

Hep insandan yana olmanı isterim, 

Barıştan, umuttan yana.

Hep sevmeni isterim; benim sevdiğim gibi.

Hep güzeli isterim senin için, 

Canım EZGİSU’M benim...

                                      (Yeğenime) 25 EYLÜL 1990', 'Sen sevgiyle büyümelisin yavrum... Barışla, umutla büyümelisin. O pırıl-pırıl yüreğin hep öyle kalmalı canım;  Hep sevecen,                 ...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istek-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikrimin İnce Gülüne', 'fikrimin-i-nce-gulune-alptekin-biber-5rpnu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay dolunaydı, seni düşündüğüm gece

Sevda çaresiz, gönül yıldızlarda asılıydı

Seninle dolu, sensizliği yaşıyordu yüreğim

Bir filizin yeşerişindeki umut oldu sevi

İşte o gece ben; 

     aklımın ve mantığımın çok uzaklarındaydım

Ve delice seni sevdiğimi düşünüyordum

Vede düşlerde yarını bekliyordum

...

Sıcak bir öpücükle; 

“Gün ışıdı sevgilim”

	diyen sevdalı sesin, 

Ve o tatlı sabaha gözümü aralayan

		sıcak nefesin

İşte buda benim düşüm, 

Çünki; 

	sevdalarıyla, 

		birikmişliğiyle, 

			tüm sıcaklığıyla

 sana vurgun yüreğim.

Şimdi ezik bir dize mırıldanıyor sessizce:

	“Sevdiğimizce sevilelim, 

	 Seviyi yüce bilelim.

	 Sevdamızla övünelim, 

	 Sevdasızı hiçe bilelim.”

			3 TEMMUZ 1993', 'Ay dolunaydı, seni düşündüğüm gece Sevda çaresiz, gönül yıldızlarda asılıydı Seninle dolu, sensizliği yaşıyordu yüreğim Bir filizin yeşerişi...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/fikrimin-ince-gulune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-alptekin-biber-rdz0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey dağlar

Yorgun dağlar

Emekçi dağlar

Gün boyunca

Yükleyip özgürlüğü rüzgarın sırtına

Bıkmadan usanmadan şehre taşırlar

Şehirde ne şehir ama; 

Polis orda, 

	Asker orda, 

		Mahpus orda, 

			İşkence orda

Direnip durur özgür olana.

İçinde kıpırdayanı göremez şehir.

Rüzgarın getirdiği onca yük boşa değil

Eğilmeler, baş eğmeler geride artık

Her kavağın yanında bir çınar belirdi

İzin yok bundan böyle eğilmelere

Her kökte bin umut

Çıkarıyor çınarı göklere.

			17 ARALIK 1991', 'Hey dağlar Yorgun dağlar Emekçi dağlar Gün boyunca Yükleyip özgürlüğü rüzgarın sırtına Bıkmadan usanmadan şehre taşırlar Şehirde ne şehir am...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozgurluk-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapmam Gerekenler', 'yapmam-gerekenler-sahin-yenilmez-6pmbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutsuzluğa düştüğümde 

Başkalarından yardım dilemeyi

Sahte gözyaşı dökmeyi

Ve duygu sömürüsü yapmayı hiç düşünmedim

Eğer kendim düştüysem bu duruma

Kendim çıkmalıyım

Gözyaşını ben döktüysem

Silmesini de bilmeliyim.

Yalnız kaldığımda

Laubali davranıp etrafa

Herkesin dikkatini çekmek değil amacım

Yalnızlığımı kucaklayıp

Kaybettiklerimi düşünmeliyim

Eğer yalnız kaldıysam

Eğer sorumlusu bensem

Kendi yalnızlığımı kendim çekmeliyim.

Çaresiz kaldığımda

Başkalarının ümitlerini çalıp

Kendi yolum yerine

Başkalarının düşlerinde yürüyüp

Ve hayallerini uçuruma atmak değil amacım

Eğer gerekiyorsa kendi çaresizliğimle başbaşa kalmalıyım

Bir sorunun parçası olup kendimi kandırmaktansa

Ölene kadar kendi kendimi teselli etmeliyim.

Eğer çok seviyorsam

Yada bu güne kadar hiç sevmediysem

Önce sevginin değer yargılarını bilmeliyim

Herkes sevemez biliyorum

Ama herkes en azından bir kere adam gibi sever birisini

Eğer ben sevipte kaybettiysem

Onun yolunu kesip çıkmazlara sokacağıma

Daha çok yolundan çekilip yeni ufuklara yeni mutluluklara itmeliyim

Eğer ben şu ana kadar sevmediysem

Ya geçip giden zamana kafa tutarım akılsızca

Yada önümde çok güzel bir mutluluk var diye 

Her geçen güne yeni umutlar katarım mantıksızca.

Herşeyin bir mantığı vardır ama

Sevginin asla.', 'Umutsuzluğa düştüğümde  Başkalarından yardım dilemeyi Sahte gözyaşı dökmeyi Ve duygu sömürüsü yapmayı hiç düşünmedim Eğer kendim düştüysem b...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yapmam-gerekenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlattım', 'anlattim-sahin-yenilmez-c7yog', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acılar sarar bazen insanın etrafını

Çoğu zaman gece olunca tutamayız göz yaşlarımızı

Gurur sandığımız bazen çaresizliğimiz olur

Ve zaman öyle hızlı akar ki

Trenle bile gitsek yetişemeyiz.

Ağır duygular kaplar bazen havayı

Oksijen yerine

Sevgi tüketiyoruz sürekli

Her teneffüs edişimizde

Yine en başa dönüyoruz.

Bir hayat merdiveni koymuşlar önümüze

Çıkın diyorlar

Biter mi bu basamaklar diye kimse sormuyor.

Cesaret duygumuzu da yavaş yavaş yitiriyoruz

Aslında her şeyden korkmaya başladık

Bazen gece uyandığım zaman

Karanlık korkutuyor beni

Belki karanlık değil ama

Gizli saklı yapılan şeyler

Karanlıkta yapılan işkenceler geliyor aklıma.

Hayatı anlamaya başladıkça yalanlar çıkmaya başlar karşımıza

İşte o zaman gerçekten hayatı anlarız

Öyle bir şeydir ki

Kimin doğru kimin yalan söylediğini anlayamazsın çoğu zaman

Sonra sende başlarsın

Ve bir bütün olursun artık hayatla.

Yaşamak kolay değildir 

Yaşamak en büyük düşmanına

Kendine karşı direnmektir

Kolay olan pes etmektir.', 'Acılar sarar bazen insanın etrafını Çoğu zaman gece olunca tutamayız göz yaşlarımızı Gurur sandığımız bazen çaresizliğimiz olur Ve zaman öyl...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/anlattim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emin İnsanlar', 'emin-i-nsanlar-engin-namli-fjxp7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yabancılaşan sevgiler 

İnsanı özünden etmiş 

En güzel körpe duygular 

Daha tadılmadan bitmiş 

Gizli aşikar kalmamış

Çizili sınır aşılmış 

Yanlışa kucak açılmış

İnsan doğru insan değil

Sonsuz sayılmış şu dünya

Oysa bir uykuluk rüya 

Aldanılmış bu sevdaya

Gaflet sarmış insanları

Hangi emanet ehlinde

Yarı yolda yad elinde 

Emin insanlar içinde

Kala kala kaçı kalmış', 'Yabancılaşan sevgiler  İnsanı özünden etmiş  En güzel körpe duygular  Daha tadılmadan bitmiş  Gizli aşikar kalmamış Çizili sınır aşılmış  Ya...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emin-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennette Buluşacağız.', 'cennette-bulusacagiz-ali-osman-yilmaz-t078g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer; cennet ve cehennem varsa gerçekten, 

Gideceğim seninde günahlarını yanıma alarak, 

Sana yalnız iyiliklerle dolu bir dünya kalacak, 

Yeni bir sevda göreceksin, kızıl gül  gibi açacak.

Varınca o yere, yanacağım cehennemde, 

Yandım nasılsa bu dünyada, senin cehenneminde, 

Alıştım yanmaya, acı bile duymayacağım, 

Ama aşk bahçelerindeki çiçekler artık, 

Acının gülleri, karanfilleri olarak açacak, 

Ellerinde hiçbir çiçek, bil ki mutlu olmayacak, 

Ama üzülme sevdiğim, Bitecek cezam bir gün, 

Sona erecek cehennemdeki mahkum  günlerim, 

Cennete alacaklar beni, tamam diye çektiğim, 

Cennete varınca, ayıracağım sana da bir yer, 

Muhteşem bir köşede, çiçekler içinde bahçede, 

Ortasında mutluluklar sarayı, içinde sen ve ben, 

Bursa 08.Kasım.2003.M.....ye', 'Eğer; cennet ve cehennem varsa gerçekten,  Gideceğim seninde günahlarını yanıma alarak,  Sana yalnız iyiliklerle dolu bir dünya kalacak,  Ye...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cennette-bulusacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamam', 'yasayamam-mustafa-dinler-ireha', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşayamam canım

	sensiz gönlümü avutmasam, 

Yaşayamam canım

	son sözlerimi unutmasam.

Umutlarım, 

	sevda denizinin 

aşk gözenekleri; 

o gözlerin var ya senin

	unutamam o gözleri.

Anılarım

	Şiirlerimdir; 

sevdalarım

	özlemlerimdir

	sana duyduğum, 

	şiirlerimde yazdığım, 

	ve aşk romanlarında okuduğum.

Acılarım

	üstünde oturduğum kırık sandalye, 

hüzünlerim

	sana şiirler uydurduğum masam; 

yaşayamam canım 

	sensiz gönlümü şiirlerimle avutmasam.

Mutluluğum

	Senli günlerde yüreğimde bulduğum

	Nesnelerin silinmiş izi, 

Hasretin

	Dibi delik gemi

	-seni aramak için kat edecek AKDENİZ’i

göz yaşlarım

kan

	yüreğimden akan…

AH! Sevgilim yaşayamam

	Sensiz gönlümü şiirlerimle avutmasam.', 'Yaşayamam canım 	sensiz gönlümü avutmasam,  Yaşayamam canım 	son sözlerimi unutmasam. Umutlarım,  	sevda denizinin  aşk gözenekleri;  o gözl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dinler']::text[], 8.5, '{"poet":"Mustafa Dinler","poet_slug":"mustafa-dinler","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yasayamam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sevgi Gönderdim', 'sana-sevgi-gonderdim-kamil-aydemir-q2827', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana sevgi gönderdim çocuk

yüreğinin tellerine konan kuşlarla

al yaralarını sar

yaralı sesinde umut var

yine fırtına yine kar

koru kendini çocuk

kırılmasın içindeki hiç bir dal

terk etme çocuk sana bir başka yakışan gülmeyi

emeklerin en büyüyğü ana emeği

başaran çıkmadı daha bedelini ödemeyi

hiç bir çocuk

ve hiç bir sevgi hak etmiyor kirlenmeyi

gözlere bağlanan kara bağ gibidir cahillik

önündeki güzellkleri bile göremesin

acılarda mastırlısın çocuk

yürek tezgahında kini nefreti öremesin

ve unutma ki 

bugüne yarın dönemesin

umutlarına sahıp çık

sahıp çık yarınlarına çocuk

sönmesin gözlerindeki ışık

için kararır dünyan dararır

yolların uçuruma varır

ve arkanda kocaman bir acı kalır

memleketimizi bu bataklıktan kim çıkarır

varoşlarda kordur

  ve kördür hayta hayat

düşlerini koynuna al da yat

üstüne yıldızları ört üşütürsün

ne zaman yanımdan geçsen çocuk

gözyaşlarını yüreğime

başımı önüme düşürtürsün

sevinçlerini düşürürsün

günün kanayan yerine

kocaman hüzün geçse de küçücük ellerine

şifasın çocuk memleketin dertlerine

sokaklarda  bir karanfil gibi büyürsün

sana sevgi gönderdim 

    karanlıkları aydınlatan

        göbeğinde güzel günler yatan ışıkla

yanlışlıkla geri itme

sakın gitme

           ve kirlenme çocuk

memleketimiz gülsün

gülsün dünya

sanmaki çocuk

bu bir rüya', 'sana sevgi gönderdim çocuk yüreğinin tellerine konan kuşlarla al yaralarını sar yaralı sesinde umut var yine fırtına yine kar koru kendini ç...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sana-sevgi-gonderdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun Bitti', 'oyun-bitti-kenan-soyalp-m50qy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şamdanda bilinçaltı tutkular, yanarken..

uçuruma itilmiş gözbebekleri, 

dumanlı ak…

mezar kazıyordu, 

gramofonda boşa dönen plak…

ölümü seçmemek değildi, 

yaşamak…

ne kadardı, kendisinden kalan..

ikili intiharlardaki 

güven duygusuydu..

aldatılan…', 'şamdanda bilinçaltı tutkular, yanarken.. uçuruma itilmiş gözbebekleri,  dumanlı ak… mezar kazıyordu,  gramofonda boşa dönen plak… ölümü seçm...', ARRAY['Türk Edebiyatı','Şiir','Kenan Soyalp']::text[], 8.5, '{"poet":"Kenan Soyalp","poet_slug":"kenan-soyalp","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oyun-bitti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan-dı-rıl-mak', 'kan-di-ril-mak-ahmet-aksoy-pvyvl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırsal bir metropoldü yüreğim

kalabalığından kırsallığı küskün

yalnızlığından metropollüğü kırık

çaresiz sadece yürek olduğundan

oysa öyle değildi elbet

kullanma kulavuzuna bakarsan

aşk olmalıydı mutluluk olmalıydı

çalınmış sayfalar olmamalıydı

uyum vadeden başlangıç

ahenksizliklere mahkum olmamalıydı

seçilenin verilmediği seçimler olmamalıydı

bir akıl bir yürekle aldatılmamalıydı.', 'Kırsal bir metropoldü yüreğim kalabalığından kırsallığı küskün yalnızlığından metropollüğü kırık çaresiz sadece yürek olduğundan oysa öyle d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kan-di-ril-mak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aheste,', 'aheste-caglar-akarsu-mrrdy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...

Kapılar yüzüme kapanırken, 

Çarparsan eğer hoyratça, 

Karşındaki bir insan dır bilesin, 

Duvarlar bile, ses getirirse, 

Bir an da geriye baktığın zaman, 

Yüzlerin çizgileri aşağıya gerilir, 

..

Kapıları kapatırken hafifçe gülümse, 

Dudaklarına hoşça bir sözcük ekle, 

Yavaşça çekerken kapı sapını, 

Kapıyı kaparken, yüreği açarsın, 

..

Toplumda insanlar müsamahasız, 

Her yere izinsiz, girip çıkarken, 

Hoş görü yitirilmiş sabırsız, 

...

Aheste yaptık biz  işlerimizi, 

Bir başka tebessüm gülleri açtı, 

Neyzen elinde ki çalgıyı çaldı, 

Hafifçe bir nefes kulağımda, 

Dost bir ayrılık geldi, arkamızdan, 

Bugün de  aheste” hoşça kalınız”

...

2003-11-06', '... Kapılar yüzüme kapanırken,  Çarparsan eğer hoyratça,  Karşındaki bir insan dır bilesin,  Duvarlar bile, ses getirirse,  Bir an da geriye...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aheste-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''sen ve sahil', 'gul-sen-ve-sahil-ali-osman-yilmaz-lnt7z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün, yorgun güneşin ardından, 

Akşama kavuşuyordu, 

Kordonda, sahilde bir akşam vakti, 

Gün batışını izliyordum sessizce.

Ve seni düşünüyordum, 

Gün akşama varırken, 

Sana varmak için dua ederken, 

Sana kavuşmak, seni sarmak, 

Sende ısınmak, sarılmak doyasıya, 

Kanatlanıp uçmak, kordondan, 

Sana, uzaktaki İstanbul’a

Çiçekçi kız geçerken, 

Kırmızı gül verdi elime, 

Kırmızı gül’e bakıp, bakıp, 

Düşündüm gözlerimi kapatıp, 

Ne yapar şimdi Gülsen’im, 

Kırmızı gülden duygularımı

Yollasam bir kuş kanadında

Varır mı? bilmem sana.

Derken sahilden bir martı havalandı, 

Kırmızı gülden duygularımı, 

Gamzeli yanaklarına kondurman için, 

Kanatlarına bağladım, 

Sabah Maltepe’den sahile inersen, 

Gül’den duygularımı o martı getirecek sana, 

Martıyı bulamazsan, iskeledeki

Balıkçı çolak mustafa’yı bul, 

Gecikirsen ona bırakacaktı, 

Çünkü kanatlarına, 

Başka sevdalarda yüklenmiş, 

Başka aşıklara da götürecekti.

 Kordon  07.Kasım.2003', 'Gün, yorgun güneşin ardından,  Akşama kavuşuyordu,  Kordonda, sahilde bir akşam vakti,  Gün batışını izliyordum sessizce. Ve seni düşünüyord...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gul-sen-ve-sahil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Artık....', 'don-artik-adem-tetik-i9umy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen yoksun yalnızım yapayalnız

Gülmez bu yüzüm hayatı restler yine gönlüm

Bir isyan dalgası bir hüzün tufanı

Eser bu şehir üstüne sen yine yoksun 

Bilmem kaç mevsim geçti 

Sayamıyorum sensiz geçen zalim günleri

Başım yerde ey sevgili yüzüm gülmez  gayri

Gönül sevmez artık kimseyi sen yine  yoksun

Dön artık yeter feryadım çıkmaz oldu

Ağlaya ağlaya göz yaşlarım kurudu

Ayrıldığımız o gün benim ölüm fermanım  oldu

Sensiz her gün bağrıma saplanan bir kurşun 

Dön artık ne olur hayatım gidişinle 

Karabasan bir cehennem oldu', 'Sen yoksun yalnızım yapayalnız Gülmez bu yüzüm hayatı restler yine gönlüm Bir isyan dalgası bir hüzün tufanı Eser bu şehir üstüne sen yine y...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/don-artik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-ahmet-aksoy-zqrc2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni her ne zaman düşünsem

kurşun gibi dökülüyorsun yüreğime

hıçkırıklarla döküyorsun göz yaşlarımı

bedenimi ısrarlarla sarsarak

her ne zaman gölgen vursa hatırama

katran gibi iniyorsun boğazımdan

içimde ne varsa yakarak

kan gibi sarıyorsun bedenimi

seni unutmayı istememek ve 

yalvarmamak köpekler gibi

benim için birk lüks aslında

fakat ya-pa-mı-yo-rum

öyle bir işlemişsin ki beynim ve 

yüreğimde ki her bir hücreye, 

gardiyanlar dikilmiş sanki, 

içeriye herhangi bir ses koymamaya

işte aşk diyor aşıklar aşığı, 

hem de katran gibi siyahı, 

aşk denilen sefalet vadedeni sevmekse eğer, 

sen diyor, bahtiyarlar bahtiyarı, 

ki aslında kanmak gelmiyor artık içimden, 

lakin kilitlenmişim zincirlerle yüreğine, 

işte bu yüzden kaçış yok çileden

ne kaçmak geliyor ne durmak elimden.

işte aşk, işte aşk, işte aşk.', 'seni her ne zaman düşünsem kurşun gibi dökülüyorsun yüreğime hıçkırıklarla döküyorsun göz yaşlarımı bedenimi ısrarlarla sarsarak her ne zama...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mahkum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar', 'bulutlar-hakki-teke-8a2wr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BULUTLAR	

Çökünce ayrılık acısı, 

Üstüne bulutların, 

Ağırlaşırlar, 

Gidemezler uzaklara, 

Boşalmak bin bir sorun.

Ey insanlar, 

Gitmeyin, durun, 

Görün, dinleyin, acıyın, 

Derdiniz  nedir.?  diye sorun.

Onlar sessiz, onlar garip, 

Bilmezler çaresini dertlerinin, 

Var mıdır.! İlacı, 

Yoksa esiri midirler.? 

Bir meçhul zorun.

Siz dinlemezseniz.! 

Bakacaklar başlarının çaresine, 

Var mıdır başka çaresi, NE.? 

Ufuk da görünür, 

Bir başka boşluk, 

Bilmezler, olur mu, 

Onlara hoşluk, 

Gece olmazsa, gün doğarken, 

Ya da bir kuşluk.

Bülbülün ahüzar vakti, 

Gönüllerin taştığı zaman, 

Ellerin duada, 

Başların semada olduğu zaman, 

Can yanarken, ten duymazken, 

Ağır ağır, yavaş yavaş, 

Gözler nemli, gönüller yaslı, 

Kalbler hisli, zihinler puslu, 

Görünen meçhule doğru, 

Yol almaya başlarlar, 

Yükleri ağırdır, çekemezler, 

Boşaltırlar bir kısmını, 

Üzerine, ya bir dağın, 

Ya da bir kırın.

Şifa için bekler, 

Onların dertlerini, dağlar kırlar.

Aşarlar, 

Hiç gelir onlara bendler, sınırlar

Boşaldıkça daha da ağırlaşır, 

Gibi gelir yükleri, 

İyice boşalmak, 

Büsbütün ağırlaşmak ister, 

Haykırırlar.

Bazan ağlarlar ince ince, 

Bazan dolu olur, 

Kırarlar kanadı kolu, 

Bazan da özlenen kar.

Nerdesin Ey Sevgili, 

SEVGİLİ YAR.', 'BULUTLAR	 Çökünce ayrılık acısı,  Üstüne bulutların,  Ağırlaşırlar,  Gidemezler uzaklara,  Boşalmak bin bir sorun. Ey insanlar,  Gitmeyin, d...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/bulutlar-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükret Haline...', 'sukret-haline-adem-tetik-jwjaf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzün dağı olmuş umutlarım birer birer solmuş

Ne yaparsın be kardeşim kaderimiz böylesine

Böylesine acıya boyun büker olmuş

Her gidenin ardından ağlamak bizim için bir talih olmuş

Umutlarımız hep hüzünlerle solmuş

Dinle dostum birde birde beni dinle

Ne görmüşsün hayatta şükret haline 

Bilirmisin sen ölmek nasıldır yaşadınmı 

Hiç hak etmeden kahbeliğede 

Dost dediğin sattımı seni en kötü günüde

Ne yiğitler gördüm bir bilsen bu alemde

Hepside nankör çıktı sırtımdan vurdu

Ölümü özleti yaşadığım bu şehirde 

Ayrılmak kaderdir dostum boyun bükmek  gerekmesede

Çek git sen boşver şükret Allah aşkına hadi haline', 'Hüzün dağı olmuş umutlarım birer birer solmuş Ne yaparsın be kardeşim kaderimiz böylesine Böylesine acıya boyun büker olmuş Her gidenin ardı...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sukret-haline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek Eşittir Hayat(Bir Denklem)', 'ekmek-esittir-hayat-bir-denklem-ahmet-aksoy-t8eqt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ekmeğini kazandığın zaman

............................................Emek

Ekmeğini böldüğün zaman

............................................Sevgi

Ekmeğini sevdiğin zaman

...........................................Mutluluk

Ekmeğini karşılıksız sunduğun zaman

...........................................................Aşk

Ekmeğini bitirdiğin zaman

.......................................Ölüm

İşte bu yüzden

............Ekmek eşittir hayat...

(Denklemin Çözümü Açık

Yerdeğiştirmek Yeterli Sonuç İçin)', 'Ekmeğini kazandığın zaman ............................................Emek Ekmeğini böldüğün zaman ............................................', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ekmek-esittir-hayat-bir-denklem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bendim', 'bir-bendim-orhan-ates-f0vr1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bendim boşvermişliği aldıran 

Bir bendim elimdekilerini bir an için  bitirmeye çalışan

Yorgun bir gecenin  hüzünlü sabahında

Bir  bendim  yolları  gözü yaşlı bekleyen 

Yaşama yenik  düşmeyip,  beklerdim o umut  meleğini 

Bir  an için karşıma  çıkıp, haykır değişini 

Bir bendim  hiç bıkmadan   bekleyen

Unutulmuş aşk mektupları arasındaki sevgi  sözcüklerini, 

Bir bendim hiç unutmayan

Anlatır   bu sensizlik kabusu her  gece 

Yıkar karanlığın   en ağır  yükünü üzerime 

Bu zifiri karanlıklarda bir bendim ayın   yanlızlığına ortak olan

Bir bendim  uzaklardaki  yıldızlarla  arkadaş olan 

Sana  umutlu olmakta  gelmiyor artık içimden

Bir  bendim umutsuzluğu hayal ile  kapatan 

Haykırışları  içimde  zincire vura  vura 

Suskun  bir bakış kaldı gözlerimin  en güzel yılları

Bir bendim gençlik  maskesi altında  ihtiyarlığı  yaşayan

Özlem duymadım hiç, pembe  dünyaları yaşamayı

Umursamadım hiçte sıkılmadım, yokluğun  ezdiren haline

Bir benmiyim? kalbimi sevgiye  hınca hınç  dolduran

Bir benmiyim?  gülücükler aleminde yaşayıpta yüzü hiç gülmeyen

Bir  benmiyim?  dünyada  yaşayıpta yaşadığım  ve  gördüğüm  kötülüklerden

Utanan...

Söyleyin  bir ben miyim?', 'Bir bendim boşvermişliği aldıran  Bir bendim elimdekilerini bir an için  bitirmeye çalışan Yorgun bir gecenin  hüzünlü sabahında Bir  bendim...', ARRAY['Türk Edebiyatı','Şiir','Orhan Ateş']::text[], 8.5, '{"poet":"Orhan Ateş","poet_slug":"orhan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Oluyor', 'aksam-oluyor-oguzkan-bolukbasi-v32i2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam oluyor

Şehrin ışıkları yanıyor bir bir

Kar geldi gelmek üzere

Beyaz, 

Kış günlerinde pek sevimlidir

Aşk damlasa üzerine görünür

Aşk damlamaz

Akar boydan boya ömürleri

Ne güneş

Ne de başka bir şey siler izleri

Akşam oluyor

Bir hengame sokaklar

Kalabalık saatler bu akşam üstleri

Bir otobüs gelse doluşacaklar

Akıllarında kim varsa buluşacaklar bilemezsin

Aşk içinde midir

Düşüncelerin yorgun olduğu anlarda

Aşk hiç çıkmaz

Yapışır zarına hücrelerinin

Bir ölüm yok eder

Üzerinde belki aşk kokan ne otlar biter

Akşam oluyor

Şehrin ışıkları yanıyor birer birer

Uzaktan kımıldıyor gibi görünürler

Sanki göç edecekler camları açarsan

Işıklar aşık olur mu karşı binadaki pırıltıya

Eğer aşıksalar

Ne konuşurlar

Işıklar

Söndüklerinde susarlar mı

Yürek söndüğünde

Ne olur

Akşam oluyor

Şehrin ışıkları yanıyor', 'Akşam oluyor Şehrin ışıkları yanıyor bir bir Kar geldi gelmek üzere Beyaz,  Kış günlerinde pek sevimlidir Aşk damlasa üzerine görünür Aşk da...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aksam-oluyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum (hadi gelsene)', 'bekliyorum-hadi-gelsene-turgut-baki-djdjz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmurun bozduğu bir sessizlikte

insansız bir gece yarısı

pencere önünde ben

dudağımda bir sigara

sigaramın dumanında tüten sen

daha kaç gece geçireceğim 

böyle sensiz

oysa ben

insanların sevdalara inandığı bir kentten

seslenmek isterdim sana

şimdi sevdaların tartıyla satıldığı

güzelliklerin pazarlandığı bir yerdeyim

sensiz

daha ne duruyorsun

hadi gelsene açarak kapısını yalnızlığımın 

bekliyorum', 'yağmurun bozduğu bir sessizlikte insansız bir gece yarısı pencere önünde ben dudağımda bir sigara sigaramın dumanında tüten sen daha kaç gec...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekliyorum-hadi-gelsene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Ateşi', 'sevdanin-atesi-turgut-baki-jr9fi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tıpkı

yapraklarında

rüzgarın türküsünü çoğaltmaya çalışan

kavak ağacı gibi

içimde kopan fırtınalarla

her gün yüreğimde 

sevdanın 

ateşini körüklüyorum', 'tıpkı yapraklarında rüzgarın türküsünü çoğaltmaya çalışan kavak ağacı gibi içimde kopan fırtınalarla her gün yüreğimde  sevdanın  ateşini kö...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdanin-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-turgut-baki-qr75l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içimdeki

sonsuza uzanan bozkırın 

bilinmez gizemin de

yankılanan

bir ses

neyi

ve neyin anlamını

ararsa arasın

arayışı

ayrılıklarla başlarmış

diyor 

insanın

ah ayrılık

ayrılık ki

köklerini süremediği sevdalardan

düşleri kuruyan ağacın derin yası', 'içimdeki sonsuza uzanan bozkırın  bilinmez gizemin de yankılanan bir ses neyi ve neyin anlamını ararsa arasın arayışı ayrılıklarla başlarmış...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Yine', 'yalnizim-yine-turgut-baki-ccsug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işte her zaman olduğu gibi

yalnızım yine

odamın kız kulesine bakan

penceresinde

seni düşlüyorum

şimdi yıldızlar

yağan yağmurla inerken yere

gece

ulaşılmaz olana

ulaşmak kadar güzel

birden 

bir umut kıpırdıyor içimde

hala sonuna kadar acık gönül kapım

ne olur

şimdi çıplak bedenine

tüm sevdanı kuşanıp pelerin diye

karanlığı yararak gel ansızın

bekliyorum', 'işte her zaman olduğu gibi yalnızım yine odamın kız kulesine bakan penceresinde seni düşlüyorum şimdi yıldızlar yağan yağmurla inerken yere ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalnizim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Bir Yarısı', 'gecenin-bir-yarisi-turgut-baki-kb4dl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gecenin bir yarısı

yine aklımda sen

dudaklarımda sigara

sana olan sevdamı

dökmek için oturmuştum 

masaya

şimdi

kalemimin kağıtla olan

tutkulu sevişmesine 

kitlenmiş gözlerim

kulağım

radyodan süzülen

eski bir melodide

neden saçların beyazlamış 

diye soruyor

bir sevdanın hayali ile

ömür tüketenler için

ağartmak onurdur saçları

diyorum

nerden  mi biliyorum

ağarmış saçlarıma bak anlarsın

çünkü hala seni seviyorum', 'gecenin bir yarısı yine aklımda sen dudaklarımda sigara sana olan sevdamı dökmek için oturmuştum  masaya şimdi kalemimin kağıtla olan tutkul...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecenin-bir-yarisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetme', 'zannetme-hakki-teke-wnqau', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sövgüyü  sevgiden, 

Yergiyi övgüden, 

Süngüyü törpüden, 

Zannetme kanarsın.

Şarkıyı türkünden, 

Tilkiyi kürkünden, 

Altmışı kırkından, 

Zannetme kanarsın.

Islağı donmuşdan, 

Tazeyi kokmuşdan, 

İnişi yokuşdan, 

Zannetme kanarsın.', 'Sövgüyü  sevgiden,  Yergiyi övgüden,  Süngüyü törpüden,  Zannetme kanarsın. Şarkıyı türkünden,  Tilkiyi kürkünden,  Altmışı kırkından,  Zann...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zannetme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-hakki-teke-wgflu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olur mu hiç böyle ayrılık selamsız, 

Tahta mıdır, taş mıdır yüreğin senin, 

Aşk daim yaşar, aşıklar ölür bayramsız, 

Dolu mudur, boş mudur, yüreğin senin.', 'Olur mu hiç böyle ayrılık selamsız,  Tahta mıdır, taş mıdır yüreğin senin,  Aşk daim yaşar, aşıklar ölür bayramsız,  Dolu mudur, boş mudur, ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayrilik-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Sesi', 'su-sesi-ahmet-ozdemir-vv0de', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzünden yansıyan acı gülüştü, 

Dinlerken “elveda” diyen bu sesi.

Sana kalmak, bana ayrılık düştü; 

İstemedim senden veda busesi.

Şimdi anladım ki, sensiz geçen an

Gurbetmiş; içinde sen yoksan her yan.

Kendimi gurbete attığım zaman, 

Duyduğum bir kaval, bir kuzu sesi.

Diyorlar, bülbülün aşkı gül için, 

Sular çağlar akar kuru göl için, 

Kurak toprak gibi bir gönül için; 

Duysam “geliyorum” diyen su sesi. 

Ahmet ÖZDEMİR', 'Yüzünden yansıyan acı gülüştü,  Dinlerken “elveda” diyen bu sesi. Sana kalmak, bana ayrılık düştü;  İstemedim senden veda busesi. Şimdi anla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/su-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim Güzel', 'sevdigim-guzel-hakki-teke-cp8df', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim sevdiğim güzel, 

Güzel değil, güzellerin şahıdır.

Kara göze siyah sürme, 

Ceylan değil, ceylanların ahıdır.

Sazdır, sözdür, semahdır, 

Zülfikardır, erenlerin eyvahıdır...', 'Benim sevdiğim güzel,  Güzel değil, güzellerin şahıdır. Kara göze siyah sürme,  Ceylan değil, ceylanların ahıdır. Sazdır, sözdür, semahdır, ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevdigim-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrım', 'tanrim-huseyin-balim-0xp1e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin adın söyler dururum, 

toprağında mahsül bulurum.

Yaradanımsın, canda canımsın

Bana hayat veren tanrımsın.', 'Senin adın söyler dururum,  toprağında mahsül bulurum. Yaradanımsın, canda canımsın Bana hayat veren tanrımsın....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Balım']::text[], 8.5, '{"poet":"Hüseyin Balım","poet_slug":"huseyin-balim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tanrim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bellemesinler', 'bellemesinler-huseyin-balim-97tyv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ezanlar okunur müminler için

şükürler olsun derler niçin.

Yetimi ağlatırlar için, için

bizi de ağlatan bellemesinler.

Allah şahit hatası yok, 

Balım hem sever, seveni çok

yalana, riyaya karnı tok

Bizi de yalancı bellemesinler.', 'ezanlar okunur müminler için şükürler olsun derler niçin. Yetimi ağlatırlar için, için bizi de ağlatan bellemesinler. Allah şahit hatası yok...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Balım']::text[], 8.5, '{"poet":"Hüseyin Balım","poet_slug":"huseyin-balim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bellemesinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-huseyin-balim-io940', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Telefonda sesin duydum, 

diyorsun ki, kanadı kırık kuş gibiyim.

Çok uzak değilim birtanem

gittiğim yer Kastamonu.

Hasretin gelir elbet sonu, 

sevgi ağırlığın geçti inan ki tonu, 

mevla vermesin yeter ki 

ölüm ile sonu, 

bekle geliyorum birtanem 

bu hafta sonu', 'Telefonda sesin duydum,  diyorsun ki, kanadı kırık kuş gibiyim. Çok uzak değilim birtanem gittiğim yer Kastamonu. Hasretin gelir elbet sonu,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Balım']::text[], 8.5, '{"poet":"Hüseyin Balım","poet_slug":"huseyin-balim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-tanem-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanesi', 'kar-tanesi-huseyin-balim-08epn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kar da beyaz, sen de beyaz, 

sen geldin ettik niyaz.

bazen bora, bazen ayaz, 

kar tanesi, kar tanesi, 

gönlümün bir tanesi.

sen geldin bahçe bostan güldü.

İnan kıymetin herkes bildi.

ırmak olup kötülükleri sildi, 

kar tanesi, kar tanesi, 

gönlümün bir tanesi. 

Bazen lapa lapa yağarsın

görünüşte hafif pahada ağırsın

gözyaşı değil sevgi de baharsın

kar tanesi, kar tanesi 

gönlümün bir tanesi.

Dağlar üzerine ne de kurulursun

akarsu olup durulursun, 

Balım''ın gönlünde daim bulunursun

kar tanesi, kar tanesi, 

gönlümün bir tanesi.', 'Kar da beyaz, sen de beyaz,  sen geldin ettik niyaz. bazen bora, bazen ayaz,  kar tanesi, kar tanesi,  gönlümün bir tanesi. sen geldin bahçe...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Balım']::text[], 8.5, '{"poet":"Hüseyin Balım","poet_slug":"huseyin-balim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kar-tanesi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Çeşit İnsan Varmış', 'uc-cesit-i-nsan-varmis-ali-osman-yilmaz-ikpl9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç çeşit insan var demiş Hayyam, 

Üç çeşit erkek, üç çeşit kadın, 

Önceliği yalancılar alırmış, 

Her zaman aldatan, kalpleri kıran, 

Arkanızı dönünce ihanet eden, 

Sevdanızı yalan kuşunun kanatlarına bağlayıp, 

Bilinmeyen geleceğe yollayan, 

En çok bunlarmış aramızda yaşayan, 

Hoşumuza da gidermiş böyleleri, 

Hadi anlat, yalanda olsa, hoşuma gidiyor, 

Dedirten cinstendir bunlar.

En kötüleri korkak olanlar, 

Hani, şiirlerimde anlattığım, 

O kızıl saçlı, uzun boylu güzel gibi

Sevdanız için tarih boyu 

Dans eder, şarkılar söylersiniz

Ama yüreği yoktur sevmeye, 

Adam gibi sevdiğini söylemeye, 

Sever gibi sokulup, Tam sarılacakken, 

Kavuştuğunuzu sandığınız anda kaçan, 

Yalan bile olsa, sevda masalı anlatamayan, 

Yüreksiz, tavşan gibi kaçacak, 

Saklanacak delik arayan, 

En kötüsü bunlarmış, sevgi nedir bilmeyen.

Birde gerçek segililer, gerçek aşıklar, 

Öylesini bulmak büyük mutluluk, 

Gerçek aşk, onlarla yaşanabilir ancak, 

Sevdi mi adam gibi seven, 

Sevdası için koca dağlar delen, 

Bulunsa böylesi, kimse elinden kaçırmayacak.

Ama düşünülmez hiçbir zaman, 

Gerçek seven olmak için ne yaptık biz, 

Gerçek insan olmak için, çaba harcayacak, 

Sevdiysek, adam gibi sevecek, 

Koca adam gibi şiirlerinde, 

Kırmızı gülleri derip, her gün gönderecek, 

İşte böyle dostlar, gerçek insan

Leyla’sını/ yada mecnun’unu, 

Sabırla, özlemle, arzuyla bekleyecek. 

Siz hangi sınıfa giriyorsunuz dostlar? 

Var mı yüreğiniz bana söyleyecek? 

 Bursa 09.Kasım.2003 O Biliyor.', 'Üç çeşit insan var demiş Hayyam,  Üç çeşit erkek, üç çeşit kadın,  Önceliği yalancılar alırmış,  Her zaman aldatan, kalpleri kıran,  Arkanız...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/uc-cesit-insan-varmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşksın Artık', 'bir-asksin-artik-mehmet-caner-sumengen-hvdju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül denizimden giden gemiye

Biletini alan, bir aşksın artık.

Bu zamansız veda, bilmem ne diye!

Seni, benden çalan, bir aşksın artık.

Gece, gözlerinsiz, zindan karası

Gündüz, yokluğunda, ömür yarası

Seven, ayrılığa, gelir mi razı? 

Hülyalara salan, bir aşksın artık.

Zoru başarmaktı, hani gayemiz

Leyla ile Mecnun, bizim payemiz

Kirletildik ama kalbimiz temiz!

Yağmalanmış, talan, bir aşksın artık.

Kader böyle dedim, çocuk kandırdım

Kısmet değilmişmiş bile sandırdım

Oysa farkındayım, affet! Çok kırdım! 

Yaşam kadar yalan, bir aşksın artık.

Vuslat bahçesine umutlar ektik

Gelin, damat olup evlenecektik

Rüzgar gibi geçti, hep acı çektik!

Şiirlerde kalan, bir aşksın artık...', 'Gönül denizimden giden gemiye Biletini alan, bir aşksın artık. Bu zamansız veda, bilmem ne diye! Seni, benden çalan, bir aşksın artık. Gece,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-asksin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Edepsiz Vay', 'vay-edepsiz-vay-mehmet-tutar-temjn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen rol yaparmışsın adamlığın sıfırmış

Adaletin ne olduğunu anlamamışsın aslın küfürmüş

Senin kulağına dünyan ile şeytan üfürmüş

Melek göstermeye çalıştığın yüzün şeytan gönlün katırmış

Ulan ayarsız sana ne yapmadık ki vefasızlıkla suçladın? 

Yaradan damı haya etmedin o gönülü kaynar suda haşladın

Bak iyi dinle eğer söz vermiş olsa idim dostuma

Ya kıçından asardım çalıya, yada dokuz delik postuna

Sen şerefsizdin halada şerefsizsin bunu böyle bil

Akıllımı sanıyorsun kendini olmaz oğlum kılda akıl

Kendin gibi nesebsizlere geberene kadar takıl

Riyakarsın edepsiz hiç riyada olurmu akıl

Vay be ulan hiç dost dosta atarmı kazık? 

On batman bok çuvalıymışsın kalıbına yazık

Yok yok doğrusu senin aslın bozuk

Bak sana son ihtardır akıllı ol! Yoksa çakarım kazık? ! 

Aman yarab bu ne utanmaz malamat imiş

Koca gönülü kaynar sularda haşladı

Daha da yetmedi şaşırdı nimetlerini taşladı

Yıktı gönül kalelerini de ne üzüldü nede kıvışladı

Eh… unutma dünyada ömür çok kısa

Unutma nasip olursa mezar! yaptır oraya kasa

Doldur o kasaya kırdığın gönülleri basa basa

Yazdır mezar taşına “ŞEREFSİZDİ BU EŞŞEK DEYMEZ YAS’A”

Sana söyleyeceğim bukadar daha bir kelime kullanmam

Yeteneksizsin okusan da sen bu şiiri anlaman

Boydan boya fitil taksalar mum olsan da damlaman

Hasislikle geçti ömrün mümkünmü dostluğu kavraman.? 



					

					24/09/2003    02:40', 'Sen rol yaparmışsın adamlığın sıfırmış Adaletin ne olduğunu anlamamışsın aslın küfürmüş Senin kulağına dünyan ile şeytan üfürmüş Melek göste...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tutar']::text[], 8.5, '{"poet":"Mehmet Tutar","poet_slug":"mehmet-tutar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/vay-edepsiz-vay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefsini Sorgulamak', 'nefsini-sorgulamak-mehmet-tutar-l87zj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşarken; nefsini kabire gömmeyi bilir misin? 

 Anlatsam dinlemek istermisin? 

 Göz ufkunun gördüğü herşey toprak desem anlar mısın? 

 Yoksa bıyık altından gülüp delinin zoruna bak mı dersin

 Sende biliyorsun yaşamak büyük imtihan

 Ölüm çok uzak değil hemen yanında ahan

 Nefsin seni uyutuyor, uyuma artık uyan..! 

 Bedenin ruhundan ayrılmadan..

 Dünyanın ne oldugunu gör ayan beyan....

                                    

                                           21:40 06.08.2003', 'Yaşarken; nefsini kabire gömmeyi bilir misin?   Anlatsam dinlemek istermisin?   Göz ufkunun gördüğü herşey toprak desem anlar mısın?   Yoksa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tutar']::text[], 8.5, '{"poet":"Mehmet Tutar","poet_slug":"mehmet-tutar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nefsini-sorgulamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-deli-hasanzan-r3s1t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni yalnız Ankara’ nın bu soğuğu değil, 

İnsanların bakışları da üşütüyor.

O kadar üşüyorum ki, 

İçimden geçen, 

Aklıma gelen o kadar anı

Ve mutluluk hikayeleri bile

Isınmama yetmiyor.

Bir gün bir buzula dönüşüp, 

Duygularımı hissedemeyeceğimden

Korkuyorum! 

Şu an azıcığını hissettiğim, 

Soğuk duygular.

Gittikçe soğuyor içim.

Eskiden olsa, 

Hayat ışığım içimi ısıtırdı.

Ama artık, 

O ışığı da kaybediyorum.

Sanki bir güneş tutulması.

Hergün içimi daha da karartan! 

Üşüyorum.

Beni yalnız Ankara’ nın bu soğu değil.

İçimdeki fırtınalar üşütüyor!', 'Beni yalnız Ankara’ nın bu soğuğu değil,  İnsanların bakışları da üşütüyor. O kadar üşüyorum ki,  İçimden geçen,  Aklıma gelen o kadar anı V...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/usuyorum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu', 'avuntu-deli-hasanzan-kq9pz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnız kaldığıda

Ve düşünmeye başladığıda, 

Hayatı ve kendisi hakkında, 

Kızıyordu.

Sitem etmekteydi ki, 

Bu kendine olan inancını, 

Gittikçe azaltıyordu.

Saçma sevdalar, 

Yalan aşklar, 

Terkedilişler, 

Bütün bunların

Sadece kaderinin oyunları

Olduğuna inandırıp kendine

Başkaldırabilseydi eğer

Bir avuntusunun olduğunu hatırlardı.

Onu sevenler.', 'Yalnız kaldığıda Ve düşünmeye başladığıda,  Hayatı ve kendisi hakkında,  Kızıyordu. Sitem etmekteydi ki,  Bu kendine olan inancını,  Gittikç...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/avuntu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur, Daha Fazla Gitme', 'dur-daha-fazla-gitme-okan-savci-vsbg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ayrılığın, ayrılık olması için

bu kadar gitmek yeterli... 

sana dön demiyorum. 

ama artık dur...

dur! daha fazla gitme, 

sonra şiir olur, 

düşersin dile...', 'ayrılığın, ayrılık olması için bu kadar gitmek yeterli...  sana dön demiyorum.  ama artık dur... dur! daha fazla gitme,  sonra şiir olur,  d...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dur-daha-fazla-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karıştığın Yokluğa Beni de Götür', 'karistigin-yokluga-beni-de-gotur-okan-savci-pu47c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu ayrılık yakar içimi.

gitme...

zaten uzuyor günden güne geceler

güneş de yok piyasada...

bir de sen yitme. 

hem bilirsin

iyi durmaz bende hüzün

bütün dertler art arda sıralanır, 

kalkamam altından bu yalnızlığın

şehir devrilir üstüme

ve sensizliğe alkol mü dayanır...

ama kararlıysan sevdiğim...

yani hazırsan anlamsızlığa...

o zaman beni de at gitsin, 

karıştığın yokluğa....', 'bu ayrılık yakar içimi. gitme... zaten uzuyor günden güne geceler güneş de yok piyasada... bir de sen yitme.  hem bilirsin iyi durmaz bende ...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karistigin-yokluga-beni-de-gotur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Üzerine', 'hak-uzerine-ahmet-aksoy-4l72r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ah bir izin versen Rabbim

makberinde dökebilse ölüler göz yaşlarını

ki o göz yaşlarıyla gitse tüm günahları

yer altı nehirleri bentlerine esir olmazdı

ah bir izin versen Rabbim

ruh ruh terk ettiğinde fani devranı

ibadetinde kusur etmeseydi mahşere dek

firidevsin insanlarla dolup taşardı

sen ki bağışlayan sonsuz İrade

Vahiy ettiğin gibi affedersin elbet

lakin söylediğin kesin bir söz vardır

bir tek kul hakkı kuldan sorulur

ah Rabbim eğer bilebilseydi insanlar

haktan öte dünyevi borç yoktur

işte o vakit dünya cennetin

ahir cennetine bahçe olurdu.', 'ah bir izin versen Rabbim makberinde dökebilse ölüler göz yaşlarını ki o göz yaşlarıyla gitse tüm günahları yer altı nehirleri bentlerine es...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hak-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terazide Ki Denge', 'terazide-ki-denge-cemal-karsavran-fq4kb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömür 

Çok basamaklı merdiven

Asansörsüz

Her basamakta aklı zorlayan

Yarın

Ne oldum değil ne olacağım diye

Düşünülen

Terazide ki denge', 'Ömür  Çok basamaklı merdiven Asansörsüz Her basamakta aklı zorlayan Yarın Ne oldum değil ne olacağım diye Düşünülen Terazide ki denge...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/terazide-ki-denge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derinlik Olmalı', 'derinlik-olmali-halim-yazici-osyt2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zeytin ağaçları zeytin ağaçları

ben niye döndüm zeytin ağaçları

sorar mısınız babama zeytindağ''lı babama

zeytin ağaçları zeytin ağaçları

ellerimden tutun zeytin ağaçları

yağmur yağıyordu yalan dolu rahmine günün

derinlik olmalıydı zeytin ağaçları 

bin yıllık hasretinde yeşil

derinlik açmalıydı ayrılığın

aydınlattığı yolda

gözlerinden öperim zeytin ağaçları

kendine iyi bak

ona da.', 'zeytin ağaçları zeytin ağaçları ben niye döndüm zeytin ağaçları sorar mısınız babama zeytindağ''lı babama zeytin ağaçları zeytin ağaçları ell...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/derinlik-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdeki Sen!', 'yuregimdeki-sen-hayri-aydin-6jcvf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dışarıda yağmur yağıyordu

Penceremden tatlı bir esinti 

Bir bahar havası

İçimde garip bir mutluluk 

Neden anlamadım

Herhangi bir gün işte

Bir ara rüzgar hiddetlendi 

Pencerem hızla açılıp, kapandı

Sen! minicik bir kuş odama süzüldün

Bir serçe sandım seni

Üşümüştün koynuma giriverdin 

Korkmuştun sana sarıldım

Nereden bilirdim 

O gün

Ben yeniden doğdum

Gökyüzünden bana ellerinle

Bir avuç sevgi

Bir tutam mutluluk uzattın

Yüreğimdesin

Istanbul,9 Kasım 2003', 'Dışarıda yağmur yağıyordu Penceremden tatlı bir esinti  Bir bahar havası İçimde garip bir mutluluk  Neden anlamadım Herhangi bir gün işte Bi...', ARRAY['Türk Edebiyatı','Şiir','Hayri Aydın']::text[], 8.5, '{"poet":"Hayri Aydın","poet_slug":"hayri-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuregimdeki-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-ufuk-nazim-1sxu8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar altında, 

Bembeyaz bir; 

Kar tanesi gibiydim.

Kara karışıp, 

Büyük bir çığ olacağım sanırdım.

Öyle büyüyüp gidecektim.

Bembeyaz olurdu; 

Ardahan da kar yağınca.

Sanırdım ki bütün dünyada; 

Kar yağıyor.

Memur un tayin hüznüyle, 

Yollara dökerek hasretimizi; 

Yol almaya başladık yalnızlığa.

Digor dan Karasuya giderken; 

Birden bire, 

Yükselirdi dünya.

Bende boy atarım sanırdım.

Sonradan öğrendim; 

O bir dağmış, 

Adı Ağrıymış.

O günden sonra; 

Hep o dağı özledim.

O dağ gibi insanlar gördüm; 

Heybetlerinden; 

Dağların gözükmediği insanlar.

Artık Ağrı Dağının; 

Yamaçlarından indim.

Büyük fikirlerin; 

Yamaçlarına tırmanıyorum

Bembeyaz bir kar tanesiyken; 

Eridim.

Denizime doğru akıyorum..', 'Kar altında,  Bembeyaz bir;  Kar tanesi gibiydim. Kara karışıp,  Büyük bir çığ olacağım sanırdım. Öyle büyüyüp gidecektim. Bembeyaz olurdu; ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kar-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı Kıyı', 'karsi-kiyi-ufuk-nazim-nzz57', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşı kıyının insanlarını; 

Hiç görmedim.

Onların görünen yüzleri; 

Dağları ve geceyi aydınlatan, 

Işıklarıydı.

Bütün sefilliğimle; 

Denizin kıyısına çöktüğüm de.

Karun kadar zengin oldum.

Dalgaların sesiyle dolardı; 

Bütün kıyı.

Balıkların bile uyuduğu; 

Bu saatler de, 

Bu kıyıda seninle olabilmek.

Güzel.

Belki umudunu; 

Denizde yitirenlere.

Umutsuzluğu anlatmanın; 

En iyi yolu.

Karanlıkta kaybettiğin; 

Bir sevgiliyle.

Dalgalardan dinlemektir; 

Ayrılığın, 

Acı dolu haykırışlarını.

Oturmuşuz denizin kıyısına, 

Karanlığın gözü üzerimizde; 

Devinimler de boğulmaktan, 

Acı denizinin; 

Dalga kıranı olmaktan bıktım.

Yanımdasın gene de; 

Gözlerim karşı kıyıda, 

Altınova’nın, 

Parıltılı yalnızlığın da; 

Arıyor seni.

Gülkurum dön geri.', 'Karşı kıyının insanlarını;  Hiç görmedim. Onların görünen yüzleri;  Dağları ve geceyi aydınlatan,  Işıklarıydı. Bütün sefilliğimle;  Denizin...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/karsi-kiyi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senki', 'senki-ufuk-nazim-bmiy5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim kapalı; 

Seni düşünerek.

Seni hayal ederek, 

Yazıyorum şiirimi.

Sen ki

Dünyamda ki; 

En büyük kavgamsın, 

İyileşmez yaramsın.

Sen ki 

Yarınımsın geleceğimsin, 

Gözlerinde boğulduğum; 

Gülkurusu denizimsin.

Sen ki

Unutmanın unutulduğu, 

Tanrıların yaratıldığı; 

Kadınımsın.

Sen ki

Benim çelişkili dünyamın, 

En tutarlı ve gerçek anlamasın, 

Ve eylemisin dünyamın.

Sen ki

Vazgeçilmez; 

Devinimisin evrenin.

Sen beni ben yapansın.

Sen ki

En saf unusun; 

Ekmeğimin

Halkların onurusun.

Sen ki

Sevensin, paylaşansın, 

Sevgiyi; 

Sonsuza taşıyansın.

Sen ki

Anlamısın yıllardır, 

Anlayamadığım, dolduramadığım, 

Yaşamın ve insanlığın', 'Gözlerim kapalı;  Seni düşünerek. Seni hayal ederek,  Yazıyorum şiirimi. Sen ki Dünyamda ki;  En büyük kavgamsın,  İyileşmez yaramsın. Sen k...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/senki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-ufuk-nazim-uwm2r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün ölürsem; 

Sevgi olup, 

Dolarım gözlerine, 

Ağlama anne.

Umut olup, 

Dönersem yüreğine; 

Her şeyde kendi parçanı, 

Beni görürsün anne

Umudumu ararken öldüm; 

Aydınlık yollardaydım, 

Pusularla kestiler yolumu, 

Umudum şimdi sende anne.

Beni nasıl yarattıysan, 

Umutlarımı da yarat anne.

Çükü umutsuz bizler.

Ölü bedenleriz.

Bulursan umutlarımı, 

Bulut olup yağarım, 

Kurak topraklara.

Güneş olup doğarım, 

Gülkurusu ufuklara.

İşte o zaman, 

Her şeyimle dönerim sana.

Ben sen, 

Biz siz oluruz, 

Kurtuluruz bu ayrılıktan.', 'Bir gün ölürsem;  Sevgi olup,  Dolarım gözlerine,  Ağlama anne. Umut olup,  Dönersem yüreğine;  Her şeyde kendi parçanı,  Beni görürsün anne...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anne-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliklerin Kaynağı', 'guzelliklerin-kaynagi-ufuk-nazim-mvf5u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tohumun; 

Düştüğü gibi, 

Düştün ömrüme.

Ömrüm ömründür, 

Bedenim bedenindir.

Büyü alabildiğine, 

Canlı ve diri.

Ve gözlerinle; 

Tara gülkurusu ufukları.

Kalbinde sıkıntı olmasın hiç.

Dağlara çıkarsın seni ayakların, 

Denizler aşırtsın seni kolların, 

Yüreklerden; 

Taşırsın seni sevgin.

İnsanca yaşatsın seni emeğin.

Ey sevgilim; 

Sevginin bahçesinden, 

Eksik olmasın güneşin, 

Küs kalmasın; 

Dünyaya yüreğin.

Ve bil ki, 

Doğan gün, 

Yeşeren doğa, 

Yaşayan her şey; 

Senin gücündür.

Yaşam kardeşin olsun, 

Çürüyen bedenim aşın olsun.

En büyük yanın, 

Hiçbir zaman eğilmeyen; 

Başın olsun.', 'Bir tohumun;  Düştüğü gibi,  Düştün ömrüme. Ömrüm ömründür,  Bedenim bedenindir. Büyü alabildiğine,  Canlı ve diri. Ve gözlerinle;  Tara gül...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/guzelliklerin-kaynagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınır', 'sinir-ufuk-nazim-5h5fg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son ülkede yıkılınca, 

Son sınırdan, 

Son insanda geçince, 

Sınırsızların yanında, 

Umudun adına, 

Güneşe taşınacaklar.

Belki başka zamanda, 

Dalgalarda yansıyacaklar.

Belki Dicle de kırılıp, 

Yüzünüzü aydınlatan, 

Işık olacaklar.', 'Son ülkede yıkılınca,  Son sınırdan,  Son insanda geçince,  Sınırsızların yanında,  Umudun adına,  Güneşe taşınacaklar. Belki başka zamanda,...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sinir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara Hasret', 'bahara-hasret-ufuk-nazim-3o7sl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kar yağdı, 

Gene hasretin gölümde.

Büyük şehirlerde yaşadım, 

Büyük okullarda okudum.

Büyük aşklar yaşayıp, 

Seni tanıdım.

Ve şimdi, 

Bir dağ başında, 

Yaşamı tanıyorum.

Dünyanın en zor okulunu, 

Halkımın okulunu okuyorum.

Kar yağdı, 

Yine hasretin gönlümde.

Umutlar sevgiler, 

Ve bahara dair her şey, 

Nakışlarında, 

Emek kokan ellerin.

Ah onların sabrı, 

Peygamberlerle eştir.

Onların yüreği konuşur, 

Gözleri, elleri konuşur onların.

Yaşamı öğreniyorum, 

Bir şeyleri almadan, 

Ve satmadan.

Hasreti nakışlara gömdüm.

Öğrendim baharı beklemeyi, 

Seni baharmışsın gibi; 

Bekliyorum.', 'Kar yağdı,  Gene hasretin gölümde. Büyük şehirlerde yaşadım,  Büyük okullarda okudum. Büyük aşklar yaşayıp,  Seni tanıdım. Ve şimdi,  Bir da...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bahara-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyoruz', 'gidiyoruz-ufuk-nazim-u9cs4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalk gidiyoruz, 

Sefaletle örülmüş duvarlardan, 

Yıkılmış umutlardan, 

Sahtelikler sunan tanrılardan, 

Bıktım artık.

Gidiyorum; 

Avuçlarım da dünyam.

Emeğim ve sevgimle, 

Baştan kuracağım hayatımı.

Hayatımız satılık olmayacak.

Siz gelmezseniz de, 

Biz gidiyoruz.', 'Kalk gidiyoruz,  Sefaletle örülmüş duvarlardan,  Yıkılmış umutlardan,  Sahtelikler sunan tanrılardan,  Bıktım artık. Gidiyorum;  Avuçlarım d...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidiyoruz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar ve Ben', 'ruzgar-ve-ben-oguzkan-bolukbasi-qxe49', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgar esince

Ben

Nedendir bilmem

Yaşadığımı hatırlarım..............', 'Rüzgar esince Ben Nedendir bilmem Yaşadığımı hatırlarım.................', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ruzgar-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzeli Şiir', 'gamzeli-siir-orhun-basat-0519u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

Zıbınına bir nazarlık gibi takılı düşlerini, 

Günahlarını ve ay çukuru gamzesini, 

                         - para üstü bırakır gibi  -

masada bıraktı kadın.

Peşinden sürükleyip bulutları, yürüyüp gitti.

Yağmurlara gebe gökyüzünde, bıraktığı tadın, 

				     farkına varmaksızın..

		2

Bir martının beyazı eridi rakının buzunda, 

ve geri kaldı zaman..

Gamzelerinden kanayan

bir gece daha örtüldü,  gecenin üstüne, 

yüreksiz bakınca anlaşılmayan..

		3

Gamzene ve sana yazılacak, iki borç şiirdi istediğin..

İki şiir demeseydin, 

Kaç şiir yazılırdı, kim bilir.? 

Kabahat senin..', '1 Zıbınına bir nazarlık gibi takılı düşlerini,  Günahlarını ve ay çukuru gamzesini,                           - para üstü bırakır gibi  - ma...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gamzeli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Şiir Biter, Ne Aşk', 'ne-siir-biter-ne-ask-melih-coskun-h3m0e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O aşk ki 

Sonucunu düşünmeden bağlanmak bir imkansıza, 

Görmezden gelmek eksik olanı 

Ya da sevmek en az kendin kadar 

Hiç bir zaman olmayanı

Ne aşk biterdi yazdıkça 

Ne de şiir biterdi 

Bu dünyada aşk oldukça 

O aşk ki 

Bağlanmaktı bir hiçe

Yalan da olsa bilincine çizdiğin o resim 

Aradığın o bakış 

Çok uzaklarda kaldı şimdi 

Bir sabah daha uyanışına anlam katan 

O alev kırmızısı çiçek 

Açmayacak belki bir daha 

Kim çözer şimdi sımsıkı bağlanmış ellerimi 

Kim soğutur yangınlar arasında kalmış yüreğimi 

Kuşansam da artık bütün cesaretimi 

Faydasız artık 

Seni seviyorum demek bile 

Seni seviyorum 

Hem de hiçbir şey beklemeden diyebilmek 

Yani en basitinden sevilmeyi bile beklemeden 

Yeşil bahçelere sevdalanmış bir kuş gibi

O aşk ki 

Hiç düşünmemek 

Nerede ve nasıl son bulacağını 

İnanmak bir gün gerçek olacağına

O en güzel düşün 

Ne aşk biter yazdıkça 

Ne şiir biter dünyada aşk oldukça...', 'O aşk ki  Sonucunu düşünmeden bağlanmak bir imkansıza,  Görmezden gelmek eksik olanı  Ya da sevmek en az kendin kadar  Hiç bir zaman olmayan...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ne-siir-biter-ne-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Soru', 'zor-soru-oguzkan-bolukbasi-qotw0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'farkında mısın

bilincinde misin

ne için olursa olsun

bu sorunun içinde misin', 'farkında mısın bilincinde misin ne için olursa olsun bu sorunun içinde misin...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zor-soru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yüzüne Aşk Bulaşmış Çocuk', 'ey-yuzune-ask-bulasmis-cocuk-melih-coskun-5mnge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey yüzüne aşk bulaşmış güzel çocuk 

Cılız bir ateşle 

Kül olursa bir gün orman yüreğin 

Dönüpte bak bir gerilere 

Göz göre göre kayarken ellerinin arasından 

Kum taneleri gibi zaman 

Nerelerde bıraktığına kaybettiklerini 

Parça parça ederken dünya 

Bütün inançlarını 

Yine kendine küstün sadece

Kendi yüreğineydi sadece o sürgün 

Çevirdin başını 

Bir zamanlar bakışlarında 

Dünyanın sırrını sakladığını sandığın 

O rüzgar saçlı sevgiliye 

Ve küstüğünden beri 

O aşk denen tek taraflı yalana 

Şiirler yazdın sadece hayatın sıradanlığına 

Sen yüzüne aşk bulaşmış çocuk 

Sönerse bir gün içinde o yangın 

Bekle tekrar yeşerene dek yüreğinin ormanı

Herşeyini kaybedenin 

Neyi kalır kazanmaktan başka 

Bil ki 

Sevilenin değil 

Sevenindir sadece o aşk...', 'Ey yüzüne aşk bulaşmış güzel çocuk  Cılız bir ateşle  Kül olursa bir gün orman yüreğin  Dönüpte bak bir gerilere  Göz göre göre kayarken ell...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ey-yuzune-ask-bulasmis-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med/Cezir', 'med-cezir-halim-yazici-7ifsm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1. kalan ne

    giden kim

    konuşan neden

   büyüyen ay

   çürüyen aşk

   yarın sen değil

   gün değil ki ölen.

2. durudu su

   yürürdü gün

   dar bir an

   aralığından.', '1. kalan ne     giden kim     konuşan neden    büyüyen ay    çürüyen aşk    yarın sen değil    gün değil ki ölen. 2. durudu su    yürürdü gü...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/med-cezir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rivayet Ki', 'rivayet-ki-halim-yazici-49rk5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yirmi on vapurunda saçlarını tarayan zaman

bağdaş kurmuş da akıp giden sessiz su sesine

dünyanın kum saatlerini ters çeviren zaman

düş kurmuş da denizin teleğinden düşen

mor tuvalin sır perdesine

bunu gören cambazı düşmüş mahallenin

boşlukta sallanan ince ipten.', 'yirmi on vapurunda saçlarını tarayan zaman bağdaş kurmuş da akıp giden sessiz su sesine dünyanın kum saatlerini ters çeviren zaman düş kurmu...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/rivayet-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günümüz Destanı', 'gunumuz-destani-ahmet-kurt-d4vzi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne derlerse kabul, kul karşı durmaz, 

Hiçbir emrin sonu, ayıp; sorulmaz, 

Tafrasından yanlarına varılmaz, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Nezaket diz boyu hayayı aşmış, 

Necaset paçadan dışarı taşmış, 

Beyinler kilitli, akıllar şaşmış, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

En zelil zamandan daha aşağı, 

Sırtlarına değen gümüş kaşağı, 

Hilalin tüccarı, haçın uşağı, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Adı senden benden, aslı karışık, 

Birkaç yerden belki daha bulaşık, 

Bal küpü, pekmeze, çanağa aşık, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Demokratız güya, bizden olana, 

Geçit yok demiştik, hortum talana, 

Bir de bizler taktık kuyruk yalana, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Her köşe başında yalanır itler, 

Olanı gördükçe inler şehitler, 

Görenden vaz geçtik, körler şahitler, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Mazluma zulmedip, aslan kesilir, 

Beyine el açar, döner kasılır, 

Bir eğri bakışta sesi kısılır, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

İkizler doğurdu hala yetmedi, 

Sırada neler var daha bitmedi, 

Beşyüz elli güruh, bir tek etmedi, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Oyunlar ki kıvrak, müzik aheste, 

Kulaklar alışık, bilinen beste, 

Keramet kalmamış beklenen seste, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Şatafat, saltanat, vuruldunuz mu

Erkeklik kayboldu, buruldunuz mu, 

Yoksa saat gibi kuruldunuz mu, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Gık diyene çaktı haşin şimşekler, 

Envai türünden icat kötekler, 

Tilkiler, yılanlar ve köstebekler, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Ey sessiz bekleyen büyük çoğunluk, 

Aşınız, suyunuz birkaç öğünlük, 

Varlığında kitli bütün yoğunluk, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Şöyle bir düşünün, Çin’den beriye, 

Söyleyin ne kaldı şimdi geriye, 

Ümidin bağlama cinle, periye, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Büyük geldi bakın bir avuç vatan, 

Boşa mı savaştı deden ve atan, 

Bedeli bilmeden, bedava satan, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

İşletmeler gitti, sıra ormanda, 

Tarihler silindi, müze talanda, 

Bin bir umut yüklü, her tür yalanda, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Tarihte talan var dedim ya demin, 

Kullanılır oldu, her türlü zemin, 

Sormadan bu tezgah, nerden ve kimin, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Devletten köylere modası yeni, 

Hapseder evinde, düşünce seni, 

Ufkunda hesapla boy ile eni, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Avrupa Birliği kurulmuş madem, 

Harfleri az bulduk, ilave gündem, 

Yenilenen şartlar sürülür her dem, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Elin oğlu sana verir mi boşa, 

Gazlara oturmuş, geliyor coşa, 

Bir gün bu kafalar çarpacak taşa, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Ruhban okulu var, yine gündemde, 

Hatırası saklı, yaşar dedemde, 

Sancılar başlıyor artık midemde, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Adresi batılı standart çifte, 

Şartlar ekleniyor, sürülen şarta, 

Her gün çiziliyor yeni harita, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Kıbrıs sıradaki satış noktası, 

Bu resmen ihanet yok ki ortası, 

Sizlere de düşsün, bunun tasası, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Bir yerden başlarsa çözülme bilin, 

Kapatılır ağzın, kesilir dilin, 

Sonra duramazsın önünde selin, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Kırmızı çizgiler vardı Irak’ta, 

Şimdi hayalleri bile uzakta, 

Gözlerim dolaşır başka tuzakta, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Özgürlük vaadi vardı uzaktan, 

Bizlere değilmiş, gördüm yasaktan, 

Gemiler iniyor artık kızaktan, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.

Bölücü revaçta, hain başa taç, 

Zehirler verilir, sanırsın ilaç, 

Kurdoğlu tek sana, Türklüğe muhtaç, 

Kalk yiğidim davran uyuma artık, 

Kaç yıldır üstünde kefen mi örtük.', 'Ne derlerse kabul, kul karşı durmaz,  Hiçbir emrin sonu, ayıp; sorulmaz,  Tafrasından yanlarına varılmaz,  Kalk yiğidim davran uyuma artık, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/gunumuz-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenimin Çiçekli Senfonisisin Sen', 'tenimin-cicekli-senfonisisin-sen-goktu-kara-kof5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'teninden vazgeçtim

çiçekler aldım bedeninden

oğuşturdum gözlerimi seni daha berrak sevmek için

aslında seni kuşdili deresinde sevdim

Kars''ın soğuk kaldırımlarında devirirken seni içki şişelerinde

auralar havada betimliyorlardı seni

bir senfoniye benziyordu işittiklerim', 'teninden vazgeçtim çiçekler aldım bedeninden oğuşturdum gözlerimi seni daha berrak sevmek için aslında seni kuşdili deresinde sevdim Kars''ın...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tenimin-cicekli-senfonisisin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koloni', 'koloni-halim-yazici-c39rr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mavi bir bozkırdan gelirim

dağlardan ve ormanlardan

günlerin, ırmakların

ayın ve ülkesinden aşkın

elim kum, kil ve renk

kalbim ışık çocuk

bir elimle alır

bir elimle dağıtırım

bir ülkeden gelir

bir ülkeye giderim

gelir renk retirir

gider renk götürürüm

ben pegasus

kanatlarım aşk

bir aşktan gelir

bir aşka giderim.', 'mavi bir bozkırdan gelirim dağlardan ve ormanlardan günlerin, ırmakların ayın ve ülkesinden aşkın elim kum, kil ve renk kalbim ışık çocuk bi...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/koloni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Çeri ve Kazan Mevzu', 'yeni-ceri-ve-kazan-mevzu-ahmet-aksoy-jsuff', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kazan kaldırdı

................yeni çeri

demek ki o vakit

.................kazan hafifti

o zaman ne yapmalı

................kazanı ağır tutmalı

yoksa mağzallah 

................dolu tutmaz da

kazan bir havalandı mı

kim bilir kimin başına geçer

........................belli olmaz', 'Kazan kaldırdı ................yeni çeri demek ki o vakit .................kazan hafifti o zaman ne yapmalı ................kazanı ağır tutm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeni-ceri-ve-kazan-mevzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıklar ve Ağlar', 'baliklar-ve-aglar-ahmet-aksoy-ermct', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'balıklar ve ''ağlar'' 

ağlar her denizde

balıklar ağlara

ağlar balıklara

ağlar her denizde

balıklar bir cinayete

ağlar bir zulme 

alet olduğundan

balıklar ağlara

ağlar balıklara

ağlar her denizde', 'balıklar ve ''ağlar''  ağlar her denizde balıklar ağlara ağlar balıklara ağlar her denizde balıklar bir cinayete ağlar bir zulme  alet olduğun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/baliklar-ve-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik ağadı', 'sensizlik-agadi-yildiz-bilgin-ol347', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine ağlıyorum köşemde sessizce, 

Hıçkırıklarımı kimse duyamıyor.

Göz yaşlarımı kimse göremiyor.

Yürekten ağladığımı kimse bilmiyor.

Yenildiğimi, boyun eğdiğimi kimse görmesin.

Kadere isyan ediyorum, yine ağlıyorum.

Yalvarıyorum Tanrı''ya seni diliyorum, 

Senle beraber olmak, sana sevdiğimi söylemek, 

Son bir kez olsun sana sarılmak ve öpmek isterdim.

Yine ağlıyorum sensizliğime ve kaderime, 

Benim bu son gecem olduğunu bilmeden, 

Rahat bir uykudasın birtanem, 

Oysa ben sensizlik içinde sessizce ağlıyorum.

Ohhh neden yoksun yanımda neden....!', 'Yine ağlıyorum köşemde sessizce,  Hıçkırıklarımı kimse duyamıyor. Göz yaşlarımı kimse göremiyor. Yürekten ağladığımı kimse bilmiyor. Yenildi...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Bilgin']::text[], 8.5, '{"poet":"Yıldız Bilgin","poet_slug":"yildiz-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensizlik-agadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin', 'guvercin-hakki-teke-hgh8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gördün mü hiç güvercinler de ağlar, 

Hazana erince, bahçeler bağlar, 

Duyar bu çığlığı, ovalar dağlar, 

Gidişine güvercinler bile ağlar.

Takla atar, fır döner semalarda, 

Yuva yapar, yem toplar meralarda, 

Haykırır bir ses, DURMA buralarda, 

Gidişine güvercinler bile ağlar.

Kuşbakışı izler, çağlar pınarlar, 

Konmak için arar, çamlar çınarlar, 

Kötülüklere göz kapar yumarlar, 

Gidişine güvercinler bile ağlar...', 'Gördün mü hiç güvercinler de ağlar,  Hazana erince, bahçeler bağlar,  Duyar bu çığlığı, ovalar dağlar,  Gidişine güvercinler bile ağlar. Tak...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guvercin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yörük Kızı', 'yoruk-kizi-hakki-teke-pncgk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüne söyleyemem, bakamam hiç gözüne, 

Sevmek arzular, oturmak isterim dizine, 

Kul olsun bütün alem ayağının tozuna, 

Selam olsun benden, YÖRÜK KIZINA.', 'Yüzüne söyleyemem, bakamam hiç gözüne,  Sevmek arzular, oturmak isterim dizine,  Kul olsun bütün alem ayağının tozuna,  Selam olsun benden, ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Teke']::text[], 8.5, '{"poet":"Hakkı Teke","poet_slug":"hakki-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoruk-kizi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Siz Koyun', 'adini-siz-koyun-burhan-gumus-rhzqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş bugün terketti gitti bizi

Olsun; ay var kapımızda yıldızlar eşliğinde

Ya zaman dursaydı  ne yapardık? 

Ona da şükür

Ah ahlanmaya bir fırsat daha bulduk.', 'Güneş bugün terketti gitti bizi Olsun; ay var kapımızda yıldızlar eşliğinde Ya zaman dursaydı  ne yapardık?  Ona da şükür Ah ahlanmaya bir f...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/adini-siz-koyun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
