INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşk', 'bu-ask-kader-budur-y4tij', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu aşk kalbimin efsanesidir.

Ne kayıtlıdır tarih sayfalarında

Nede bilinir eski yazıtlarda

Aklımın oyunudur aslında

Düş parçasıdır akar kanımda

Destansıdır matem tutulur arkasında

Huzursuzdur durmaz dudaklarımda

Hayaldir yanlız yaşadım aslında', 'Bu aşk kalbimin efsanesidir. Ne kayıtlıdır tarih sayfalarında Nede bilinir eski yazıtlarda Aklımın oyunudur aslında Düş parçasıdır akar kanı...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Ne', 'kime-ne-turgut-baki-ftvdl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'korkunun ecele faydası yokmuş

inkar etmek boşuna

kaçmak boşuna

karar verdim 

ve kırdım belleğimin bütün sırrı dökük aynalarını 

yüzleştim kendimle

hep seni seviyorum dedim ya 

doğru

sen vazgeçemediğim sevgili

yanlış

sen hiç olmadın ki

ama ben hep varmışçasına yazdım sana

olsun

ben sevmeyi seviyorum 

kime ne

(bir gün var olabilmen umudu ile yazıyorum yine de)', 'korkunun ecele faydası yokmuş inkar etmek boşuna kaçmak boşuna karar verdim  ve kırdım belleğimin bütün sırrı dökük aynalarını  yüzleştim ke...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kime-ne-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular ağlıyor', 'duygular-agliyor-hicabi-ceylan-qp5u7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben hüzünler bozkırında açan gamlı papatya

Hiç düşünmeden bastın üstüme ezdin beni

Seni bu kadar çok severken

Küçücük yüreğimde yalnız seni taşırken

Terbiyesiz dedin, uzaklaştın yıktın beni

Karşılık beklemeden büyüttüm bu sevdayı 

Öyle büyümüştü ki aşmıştı beni

Yinede hamalıydım sevdamın

Söyleyemiyordum, bulamadım yazacak kalemi

Terbiyesiz dedin, gittin yaktın ciğer paremi 

Sınırsızdı, coşkundu çağlayanlar gibi

Dertliydi, kederliydi ağlayanlar gibi

Her nesneden kıskanıyordu seni, deliler gibi

Aha bu deli gönül cananı böyle sevdi

Terbiyesiz dedin, terk ettin viran eyledin hanemi

Şimdi ben hak etmediğim yalnızlıktayım

Tanımadığım, el alem için kırdın kalbimi

Bu benim kaderim mi yoksa çektiğim çilemi

Yapacakların yaptıklarına bilmem değer mi

Terbiyesiz dedin, yok ettin bendeki beni

Duygularımın tutsağı, esiri olmuşum

Gazele dönmüş, bahara ermeden solmuşum

Hayatın gizeminde, hayallerle yorulmuşum

Yalnızca canana erişmek içindi var oluşum

Terbiyesiz dedin, kurşun sözlerinle öldürdün beni

10,12,2003', 'Ben hüzünler bozkırında açan gamlı papatya Hiç düşünmeden bastın üstüme ezdin beni Seni bu kadar çok severken Küçücük yüreğimde yalnız seni ...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/duygular-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öz', 'oz-murat-tali-yb16b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bende

Ben sende

Ben sende

Sen bende

İkimiz birbirimizde

Tekiz öyleyse', 'Sen bende Ben sende Ben sende Sen bende İkimiz birbirimizde Tekiz öyleyse...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Öleceğim Bu Şehirde', 'sensiz-olecegim-bu-sehirde-kader-budur-vuhll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şehir boğuyor beni sensiz

İnsanlar bir başka görünüyor gözüme

Sanki kötülükleri işlemiş yüzlerine

Korkuyorum bu şehirde sensiz

Bu şehir ağlatıyor beni sensiz

Kimsesizlik çökmüş sokaklarına

Yanlızlık kol geziyor köşe başlarında

Korkuyorum bu şehirde sensiz

Bu şehir hüzünlendiriyor beni sensiz

Baktığım gölgeler görünüp kayboluyor

Sessizlik meclisi bende toplanıyor

Korkuyorum bu şehirde sensiz

Bu şehir öldürüyor beni sensiz

Mezarlar kazıyorum yüreğimde

Fatihalar okuyorum gidenlere

Ama korkuyorum sensiz öleceğim bu şehirde', 'Bu şehir boğuyor beni sensiz İnsanlar bir başka görünüyor gözüme Sanki kötülükleri işlemiş yüzlerine Korkuyorum bu şehirde sensiz Bu şehir a...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-olecegim-bu-sehirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Tımarhane', 'gonul-timarhane-abdulkadir-karaman-erkri', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül tımarhâne, deli duygular

Üst tutmuş, bak bayrak açan açana. 

Gözlerin, sebep ne; sorar, sorgular

Tehdidinden korkup kaçan kaçana. 

Mânidar mânidar süzme, sor hele

Zahmet olmazsa, yanına var hele

Deliliği var mı? bak da, gör hele

İnsaf et, çılgınsa, kendin saçana.

Sana ne bundan, ben etmedikçe ses

Oraydı sevdâna altın bir kafes

Sızlanmayı bırak, şikayeti kes

Ben bir şey edemem, mekan seçene. 

Acıma hâline, merhamet etme

Sabrı son dorukta, dikkat, tüketme

Deli duyguların varsa bekletme

Tek sığınak gönül, iksir içene. 

22 – 04 – 2001', 'Gönül tımarhâne, deli duygular Üst tutmuş, bak bayrak açan açana.  Gözlerin, sebep ne; sorar, sorgular Tehdidinden korkup kaçan kaçana.  Mân...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-timarhane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Yabancı', 'gece-ve-yabanci-mecit-ulusoy-nk66f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Delinmiş gök kubbe bin bir yerinden

Akşamın geceye yaklaştığı yerde,

Bir adam sokakta sırılsıklam 

Yıldırımın köşeye ulaştığı yerde.

Bir parçası olmuş yaşamının yürümek

Bazen şimşeklerin aydınlattığı yerde,

Bir sessizlik peşinde umutsuz adımlarla

Giderken bir şeylerini bıraktığı yerde.

Islanmış bedeninde duyduğu ağırlık,

Ayaklarına ikinci bir yağmur gibi inmekte.

Yönelirken bir parka gecenin koynunda,

Yağmur hızlanırken belli ki dertleri dinmekte.

Demir kapıdan süzülürken parka,

Şimdi o karanlıkta hayalet gibi kimsesiz.

Oturmuş düşünceleriyle baş başa banka,

Yağmur kadar ıslak, park kadar sessiz.

Belki de uzaklarda bir çok parklarda,

Bir çok adam sessizce ağlamakta,

Bir çok giden sevgililer peşinden,

Bir çok kalpler sızlamakta yanmakta.', 'Delinmiş gök kubbe bin bir yerinden Akşamın geceye yaklaştığı yerde, Bir adam sokakta sırılsıklam  Yıldırımın köşeye ulaştığı yerde. Bir par...', ARRAY['Türk Edebiyatı','Şiir','Mecit Ulusoy']::text[], 8.5, '{"poet":"Mecit Ulusoy","poet_slug":"mecit-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gece-ve-yabanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
