INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedin', 'bilemedin-mustafa-evci-x2y24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu koskoca dünyayı gözlerine sığdırıp

Savaşlara orada siperler kazdığımı

Yaşamın kapılarını sensizliğe kapayıp

Aşksız bir geleceği yokoluş saydığımı

Bilemedin...

Bakışını tekneme şaşmaz bir rota sayıp

O kopan fırtınaya hiç tutulmadığımı

Sevdanı yüreğime çoğaltan ırmak sayıp

Tekrar tekrar kalbimi orda yıkadığımı

Göremedin...', 'Şu koskoca dünyayı gözlerine sığdırıp Savaşlara orada siperler kazdığımı Yaşamın kapılarını sensizliğe kapayıp Aşksız bir geleceği yokoluş s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Evci']::text[], 8.5, '{"poet":"Mustafa Evci","poet_slug":"mustafa-evci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilemedin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Göz Altındayım', 'gozlerinde-goz-altindayim-orhun-basat-ajzui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskimiş ışıklarında yıldızların, 

En sancılı doğumunda şiir.

Canımı sıkan 

Ve sürekli küfreden şehir, 

uzaklarda şimdi..

Ben, baharat kokulu akşamlarında Sakızlıkoy ’ un, 

Bir yıldız yırtığı / bir yürek artığı..

Sensiz böyleyim işte, söyledimdi.

Acıların yol kavşakları kadehim, 

Baharlar uzaklarda kaldı, elbet..

Koptu mısralar en sancılı yerinden, 

Bu yüzden, bir sonbaharın saçlarını okşuyor elim..

Gözlerinde gözaltındayım, 

Yalnızlığa müebbet...

26.09.03 Ankara', 'Eskimiş ışıklarında yıldızların,  En sancılı doğumunda şiir. Canımı sıkan  Ve sürekli küfreden şehir,  uzaklarda şimdi.. Ben, baharat kokulu...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerinde-goz-altindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezinti', 'gezinti-vedat-selcuk-fibe2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri,sokak sokak gezerdim

Ellerim ceplerimde,yıldızları sayarak

Bata-çıka sendelerdim,çamurlu yollarda

Gözlerim nemli,bitirirdim bu şehri arşınlayarak...

Gündüzleri cadde cadde gezerdim

Ellerim ceplerimde,insanları sayarak

Binlerce şekil ve tip görürdüm yollarda

Kaşlarım çatık,kurtulurdum kendimi eve atarak

Akşamları,mahalle mahalle gezerdim

Elimin biri cebimde,ötekiyle sigara tutarak

Kendimi sürekli zehirlerdim

Hem sigaramı,hemde bu şehrin pis havasını soluyarak...

                                                                    01-02-2002

                                                                          Kütahya...', 'Geceleri,sokak sokak gezerdim Ellerim ceplerimde,yıldızları sayarak Bata-çıka sendelerdim,çamurlu yollarda Gözlerim nemli,bitirirdim bu şehr...', ARRAY['Türk Edebiyatı','Şiir','Vedat Selçuk']::text[], 8.5, '{"poet":"Vedat Selçuk","poet_slug":"vedat-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gezinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokuzuncu Ayrılık', 'dokuzuncu-ayrilik-orhan-dal-jfbgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutsuz bir yağmur bekliyorum

Gözlerim gözlerine değdiği gün

Ağır nemli gözlerimden alıp götürdüğün

Hangi ellerinle kimbilir

Hangi yüreğimden kaçırarak

Hırsızlama alıp götürdüğün

O bulutsuz yağmuru bekliyorum

Biraz mutsuz

        Biraz umutsuz

Senin avuçlarına dökülüyor 

                                 biliyorum

Alev alev çığlıklar getiriyor

Seni kaybedip bulamamak

Sahile vuran dalgalar yazdıklarımı götürüyor

Kahrolası dalgalar şiirlerimi  götürüyor

Yorgun bir bulut diye yüreğimi

Yağmurlara karıştırmak

Senin olduğun heryerde bir bulut olmak

Dağılmıl karanfil kokulu saçlarına

Bir kelebek hafifliğiyle dökülüp saçılmak

Ne yapsam ne etsem

  Yetişemiyorum arkandan

       Rüzgar beni alıp götürüyor.', 'Bulutsuz bir yağmur bekliyorum Gözlerim gözlerine değdiği gün Ağır nemli gözlerimden alıp götürdüğün Hangi ellerinle kimbilir Hangi yüreğimd...', ARRAY['Türk Edebiyatı','Şiir','Orhan Dal']::text[], 8.5, '{"poet":"Orhan Dal","poet_slug":"orhan-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dokuzuncu-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Aşk', 'buyuk-ask-ahmet-agdere-u9l07', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha büyük aşk; 

Erişilmez değildir.

Razı olursan eğer,

Benliğini yükseltmeye.

Elbet gelecektir,

Doğunun aydınından,

Elinde bir buket gül,

Razı olursan eğer..', 'Daha büyük aşk;  Erişilmez değildir. Razı olursan eğer, Benliğini yükseltmeye. Elbet gelecektir, Doğunun aydınından, Elinde bir buket gül, R...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyuk-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel de Unut', 'gel-de-unut-osman-velioglu-w9cwz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgun düşüncelerimde sakladım 

Bûselerin uçuşan buğusunu. 

Yalnızlığı gecelerde yokladım 

Ürküttüm zamanın son kuğusunu... 

Beceriksiz sevilerde boğuldum, 

Sınırsız düşlerde buldum kendimi, 

Saadetten yoksun, acılardan fuldum, 

Kabuğum çatladı, yıktım bendimi. 

Yazınlar yetersiz kaldı bir tanem, 

Türkülere vurdum mazlum sevdamı. 

Yokları oynuyor bu gönül hanem 

Eridi buzlardan kurulu damı. 

Acemice tutup o ellerini 

Yüzüne bakıştan asırlar geçti. 

Sararken titrerdim, o bellerini 

Gözlerim gözünden zamanı içti... 

Uğraştım, çalıştım, didindim durdum 

Gayriye elimi uzatamadım... 

Hep seni yaşadım, hep seni sordum, 

Can çiçeğim seni UNUTAMADIM....', 'Yorgun düşüncelerimde sakladım  Bûselerin uçuşan buğusunu.  Yalnızlığı gecelerde yokladım  Ürküttüm zamanın son kuğusunu...  Beceriksiz sevi...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-de-unut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir garip ölüm', 'bir-garip-olum-orhan-dal-k43gz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben senin kim olduğunu biliyorum

İstinyede bir gemide unutulan

Serseri bir çocuğun eski oyuncağısın

Hiç bitmedi yolculuğun

Bir kayboldun birdaha bulunamıyorsun

Ellerin yok ki dokunmuyor kimselere

Ya gözlerin kimler kirletti öyle

Kimler çiğnedi ayaklarını

Gözler görmüyor seni

Gönüller hissetmiyor

Eline basıyorlar ayağına

Gözlerini kirletiyorlar

Diline ne oldu öyle 

Balı çekilmiş

Ses vermiyo kimseye

Duymuyor kimse

Ben seni tanıyorum

Batan geminin içindeki son yolcusun

Serseri bir çocuğun son çocukluğusun', 'Ben senin kim olduğunu biliyorum İstinyede bir gemide unutulan Serseri bir çocuğun eski oyuncağısın Hiç bitmedi yolculuğun Bir kayboldun bir...', ARRAY['Türk Edebiyatı','Şiir','Orhan Dal']::text[], 8.5, '{"poet":"Orhan Dal","poet_slug":"orhan-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-garip-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Koğuşu', 'oluler-kogusu-orhan-dal-tejy2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adanalı Ahmet''tir üç yıl önce ölmesi gerekirdi

Hiç bilmedi gökkuşağı nedir

Tanımıyor toprak kokusunu

O da biliyordu ölmesi gerektiğini

Kuşçu hasan dağları görüyor rüyalarında

Güvercinleri akbabalara kaptırdığından bu yana

Gözleri uçurtmaları seçmiyor

Demirler batıyor göğsüne, hasan ölmüyor

Yılmaz, eşkiyaymış babası

Barut kokusu duyuyor geceleri, yılmaz çıldırıyor

Ellerini kesiyor, gözleri kanıyor

Yılmaz barut kokusuna ne yapsa alışamıyor

Adı yusuf, kaptan diyorlar ona

Rüyalarında gemiler yakıyor

Oyuncak gemilerini gardiyanlar aldı

Yusuf ağlıyor, denizler kabarıyor', 'Adanalı Ahmet''tir üç yıl önce ölmesi gerekirdi Hiç bilmedi gökkuşağı nedir Tanımıyor toprak kokusunu O da biliyordu ölmesi gerektiğini Kuşçu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Dal']::text[], 8.5, '{"poet":"Orhan Dal","poet_slug":"orhan-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oluler-kogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyde Seni Görüyorum', 'her-seyde-seni-goruyorum-ali-osman-yilmaz-cm1hw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çimenlerin üstüne yatmışım,

Düşünürken günlerimi,yarınlarımı,

Açtım gözlerimi,akşam olmakta,

Kıpkızıl bir renk kaplamış ortalığı,

Kızıl bir akşam ışığı sarmış her yanı,

Havada tek bir bulut bile yok,

Pırıl pırıl bir akşam havası,

Böyle güzellikler içinde batmakta,

Muhteşem ışık oyunlarıyla akşam güneşi.

Gökte uçuşmakta göçmen kuşlar,

İnanılmaz sesler çıkarmaktalar,

Belliki göç zamanı gelmiş,

Mevsim kışlamakta,

Toplan borusu çalar gibi,

Arkadaşlarını çağırmaktalar.

Hayranlıkla bakınırken kuşlara,

Ve güneşin batmakta oluşuna,

Çevreyi kaplayan o kıp kızıllığı,

Yaratan güneşin içinden belirdin,

Hayalimdeki o muhteşem halinle,

Ve anladımki bir tanecik sevgilim,

Ben seni unutmak istedikçe,

Unutamayacağım,anladım bir daha,

Uçuşan göçmen kuşun kanadında,

Tarladan dönen,o at arabasındaki,

Kadınların arasında yine sen varsın,

Yoldan geçen otobüsün camından,

Bana bakmakta olan ‘o’ sensin,

Gece yatağımda,en derin uykularımda,

İnadına rüyalar gördüren,

Rüyalarımda bana gülümseyerek,

Yanıma usulca sokulup fingirdeyen,

Hep sensin güzelim,hep sen.

Hangi yönetmenin senaryosudur ki bu,

Ne yana dönsem,ne yana baksam,

Hangi çiçeği elime alıp koklasam,

Sen varsın ve sen kokuyorsun.

Senin gerçek yüzünü,

O muhteşem boşnak endamını,

Balkanlardan gelen o inadını,

Gri-mavi gözlerini,ve cadılığını,

Şiirlerindeki o güzel dizelerinden başka,

Hiçbir şeyini de bilmem senin,

Görmedim yüzünü,tutmadım elini,

Hiç öpmedim kiraz dudaklarını,

Ama her yanda,baktığım her şeyde,

Tüm çiçek bahçelerindeki çiçeklerde,

Hep  sen varsın,hep seni görürüm,

Bugün İznik gölünün kıyısında,

Dalmışken suyun derinliklerine,

Seni görmek,sana ulaşmak için,

Belki bir balık olarak da olsa,seni,

Bulur görürüm umuduyla,ve 

Böyle seyrederken suyu,

Bir kadın belirdi su yüzünde,

Su kadar çıplak,su kadar berrak,

Uludağın tertemiz kar suyu,

Sanki doyasıya iç beni der gibi,

Suyun içinde yüzmekte,bir turna balığı,

Ellerini karnına sarmış,bakar bana,

Düşlerini anlatmak ister gibi,

Hızlanır birden,dalar sazların arasına,

Kıyıda belirir,üç etek giymiş bir güzel,

Salına salına bu yana doğru gelmekte,

Makedonya dan gelen gelin gibi,

Başında rengarenk bir yazma,

Yazmanın üstünde bir sıra altın,

Burnunda mavi taşlı bir hızma,

Yaylı araba gibi raksedercesine,

Sokulur tatlı bir işveyle yanıma,

Böyle anlatıyorum diye de sakın kızma,

Dedim ya ne yana baksam sen,

Hangi çiçeği koklasam yine sen,

Buhurdan yayılan mis esansı sanki,

Hoşuma gitmiyor da değil hani,

Sen yoksun yanımda amma,

Her yerde,her şeyde seninle birlikteyim,

Ben seni,güzelliğini,hayalimdeki aşkını,

Senin haberin bile olmadan doyasıya,

Yaşıyorum,yaşıyorum sensizde olsa,

İşte şimdi satırlarla da dile getirdim,

Seninde haberin oldu artık,

SevdiğiM.SevgiliM,AşkıM.', 'Çimenlerin üstüne yatmışım, Düşünürken günlerimi,yarınlarımı, Açtım gözlerimi,akşam olmakta, Kıpkızıl bir renk kaplamış ortalığı, Kızıl bir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/her-seyde-seni-goruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilmek diye yakarmak', 'sevilmek-diye-yakarmak-i-brahim-ethem-bingul-mbch3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyada yanlız kalmış bir yürek idim,

Takıldı gözlerim gök yüzüne,

Bilirim yıldızlardan birini kendime yar seçmeliydim

Ne zormuş, sonu belirsiz bir bekleyişte olmak,

Sanki çöl''ün ortasında bir yudum suya hasret kalmak,

El açıp Allah''a sadece sevmek için değil, sevilmek diye yakarmak,

Gün olur devran döner,

Elbet birgün bir yürekte beni sever,

İçindeyken ardı arkası kesilmez hayallerin,

Birden karşıma çıktı, o manalı gözlerin,

Önceleri ürküten, sonraları birer bilmece sözlerin,

Uzanıp dokunsam tutacağım gibi,

Belkide tutup okşasam kırılacak gibi,

Ne bir eşi daha vardır, ne de benzeri,

Sendeki o kocaman yüreği,

Tek bir sözdür, ilk kez düşünmemi sağlayan,

Hala o gün gibi kulağımda çınlayan,

Aşkımı sen büyüttün, sonra oldu çağlayan,

Lakin en büyük sır oldun, köşe bucak saklanan,

Duyanlar inanmıyor, benim gizli sevdama,

Kimse cesaret edemiyor, aşkım gibi bir aşkı yaşamaya,

Ölümüme kadar andım olsun,

Her zaman savaşacağım sana layık olmaya....', 'Dünyada yanlız kalmış bir yürek idim, Takıldı gözlerim gök yüzüne, Bilirim yıldızlardan birini kendime yar seçmeliydim Ne zormuş, sonu belir...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevilmek-diye-yakarmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaret Sınavından Geçtim', 'cesaret-sinavindan-gectim-sedef-unal-a7gff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin nöbetindeyim yine 

Şehir suskun duvarlar suskun 

Zamanın durduğu yerdeyim yine 

Davetsizce odama dalan hilalli ay ışığı 

Usul usul okşuyordu saçlarımı 

Uzaklara,uzaklara daldı bakışlarım 

Gecenin en derin noktasında 

Sahipsiz fırsatları gördüm 

Sonsuzluğa akan katran karası gecede 

Yerlere savrulmuş sevdalar vardı, 

Seslerini duyurmak isteyen 

Ista tam o anda 

Hayalin beliriverdi karşımda 

Işıl ışıl gözlerimde doğdun 

Gözlerimde biriktirdim kare kare resimlerini 

Tekrar tekrar basa sararak seyrettim 

İçlerinde bir resmin var ki 

Dudağında taşıdığın gülüşün 

Yazdan kalma keyfinle 

Kutsal sayılan ikonalar gibi 

Gözbebeğimde asılıp kaldı...! 

Mevsimler bu kadar uzun muydu? 

Yoksa, biz mi yavaş yaşıyoruz zamana inat. 

İçimde kor gibi yanan özlemini 

Bölüştürdüm zaman dilimlerine 

En incesinden, en büyüğüne 

Durdukça değerlenen şarap misali 

Duygularım kullanmadıkça değerlenirken 

Hasretinle yanan yüreğim 

Cesaret sınavından geçti 

Duygularım ağır bedeller ödemeye hazır 

Yeter ki gel...

22.11.2003', 'Gecenin nöbetindeyim yine  Şehir suskun duvarlar suskun  Zamanın durduğu yerdeyim yine  Davetsizce odama dalan hilalli ay ışığı  Usul usul o...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cesaret-sinavindan-gectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'The World which is Created for Us', 'the-world-which-is-created-for-us-ahmet-agdere-gnezp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Maybe, you love me as I love you,

Uvula is gulped when you see me.

Zealous senses are formed for saying,

Encore, create me the world for you! 

You don''t know, anyway It has been created; 

Your eyes create it when they smile at me.

Ever more, it will even exist,

Nor I neither you will die in it..', 'Maybe, you love me as I love you, Uvula is gulped when you see me. Zealous senses are formed for saying, Encore, create me the world for you...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/the-world-which-is-created-for-us-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber Değeri Olan Kadın', 'haber-degeri-olan-kadin-oguzkan-bolukbasi-i1p00', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam haberlerinde söylediler

Hissiyatsız bir suratla

Bir çok yerlerinden bıçaklanmış bir cesettin sadece

Bir kadın

Haber değeri olan

Değerin neydi,

Yaşarken hiç anlamaya çalışan oldu mu

Yüzünü taramışlar ekranda görünmesin diye

Niye

Seni hiç gören olmadı ki

Yüzün gösterilse tanıyanın yok

Seni ayakta tutan neydi

Hayat buysa 

Yaşamak niyeydi

Umut işte

En derinlerden en yükseklere kadar

Bir ağ gibi ördüğünde 

Ve umut bir umut gibi göründüğünde

Son bıçak darbesine kadar tutunursun hayata

Kayarken 

Kandan izler kalır sana dair

İzlendiğinde bulunur mu sana ait bir kabir

Kaç gün kalırsın beyaz cama üfler gibi konuşan o kadının ağzında

Kim merak eder de sürer yolunu yaşamının

Kim günlerce durur kapısında bir gecekondunun

Sonu bu oyunun

Perde kapanmadan biten bir oyunun 

Sen çağrılmadan sahneye çıkan oyuncusu

Güle güle

Güle güle

Yaşamadın bile……………………………..', 'Akşam haberlerinde söylediler Hissiyatsız bir suratla Bir çok yerlerinden bıçaklanmış bir cesettin sadece Bir kadın Haber değeri olan Değeri...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/haber-degeri-olan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sansür ve Aspiratör', 'sansur-ve-aspirator-ensar-aktas-jps8e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sansür bir aspiratöre benzer

Bazan nahoş kokuları süzer

Bazan da hoş kokuları emer

Kurunun yanında yaş da yanıp gider...

Peki sansürün ömrü ne kadar sürer? 

- Aspiratörün süzgeci pislik bağlayıncaya dek.

Öyleyse sansürü bir tek sansüre koymak gerek! 

Rotterdam, 10-12-2003', 'Sansür bir aspiratöre benzer Bazan nahoş kokuları süzer Bazan da hoş kokuları emer Kurunun yanında yaş da yanıp gider... Peki sansürün ömrü ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sansur-ve-aspirator-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An(ı) larım…', 'an-i-larim-muammer-celik-idgw7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...seni… 

bir tek ben anlarım

Yerinde ve doğru anlarım

Anlarım, anlarım ki, 

O anlarımda görünür anılarım

Anılarımda anlarım

Anlarımdaki anılarım

Yokluğunu gördüğüm anlarım/da

Yokluğunu gördüğümü anlarım

Anlarımda anılarım

Anılarımda  anlarım

İşte o zaman durur, akmaz kanlarım...! 

BirDeli

12.12.2003', '...seni…  bir tek ben anlarım Yerinde ve doğru anlarım Anlarım, anlarım ki,  O anlarımda görünür anılarım Anılarımda anlarım Anlarımdaki anı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/an-i-larim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berlin-Istanbul Arasi', 'berlin-istanbul-arasi-sores-welat-demir-txthu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Berlin-Istanbul arasinda gidip geliyorum

Yanlis anlamayin 

Yolculugum düslerimledir ancak

Berlinde Spree''nin kiyisinda oturuyorum

Bir Balikci Botu-Restaranti var, ismi Iskele

Calisanlari Türk

Ve birileri sohbet ediyor yan masada 

Hepsinde kilik kiyafet o bicim

Bayanlar seker mi seker

Türkce konusuyorlar; Berlin''de.

Aleviyim ve kadinlarimizi el üstünde tutariz, diyor

kiyafetiyle asci sandigim biri,

Kadinlar mini etekli sarisin müslüman

Biz de herkesi severiz, herkes esittir, diyor

ve konuyu yeni elbisesinin sikligina ceviriyor.

Pencere kenarindayim ve ada cayimda var masamda.

Bot aldi ve sanki beni Istanbul bogazina götürdü

Ilk defa ve son defa kokladigim

deniz kokusuna kavusturdu beni

Ilk defa ve son defa gördügüm

isıltili resmi getirdi gösterdi bana

ve bırde bogaz sularında yansiyan yüzümü

Radyoda söyleyen Haric ve bir de Sezen Aksu

Nostaljileriyle eglendirdiler beni

Tutamazsin, diyor Haric

harbi ama birazda cekingen bir dille

Sanki bana sesleniyor

Tutamam belki de istesemde Istanbulu.

Gercek, tutamaz miyim ben Istanbulu? ! ! 

Ama Sezen hakliydi

Unutamazsin, diyordu

Dogru

Gercekten unutamamisim ben Istanbul''u...

(Berlin-Istnabul Arasi adli Siir Kitabindan, 2002-Almanya)', 'Berlin-Istanbul arasinda gidip geliyorum Yanlis anlamayin  Yolculugum düslerimledir ancak Berlinde Spree''nin kiyisinda oturuyorum Bir Balikc...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/berlin-istanbul-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabanci Dile Sevgimi Anlatabilmek', 'yabanci-dile-sevgimi-anlatabilmek-sores-welat-demir-rctdu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soruyorum

Yabanci bir dille

Cocuklugumda biraktigim yildizlari

Bayramlasirken ellerini öptügüm 

sevgili büyüklerimin resimlerini

kardeslerimin dostlarimin gülüslerini

Ayaklarindan tuttugum kurbagayi

Besleyip ucurdugum güvercinleri

Durmak istiyorum sevgiyle

Yabanci dilin önünde

Bütün dilbilgisi anlamsizliklarina ragmen

Alip onu dilimde anlamlastirmak istiyorum

Düslerimi, özlemlerimi, üzüntülerimi

anlasin istiyorum

Yabanci dile 

sevgimi anlatabilmek istiyorum...

(Berlin-Istanbul Arasi adli Siir Kitabindan, 2002-Almanya)', 'Soruyorum Yabanci bir dille Cocuklugumda biraktigim yildizlari Bayramlasirken ellerini öptügüm  sevgili büyüklerimin resimlerini kardeslerim...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yabanci-dile-sevgimi-anlatabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK ve ATEŞ', 'ask-ve-ates-erdem-ozarslan-788sf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AŞK ve ATEŞ

  S ararmış yapraklar bir bir dökülüyor...

  U tanmış bedenler yapraklara sarılıyor

  D uvarlara çığlıklar adını kazıyor

  E llerim yapraklarda bedenini arıyor..', 'AŞK ve ATEŞ   S ararmış yapraklar bir bir dökülüyor...   U tanmış bedenler yapraklara sarılıyor   D uvarlara çığlıklar adını kazıyor   E lle...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özarslan']::text[], 8.5, '{"poet":"Erdem Özarslan","poet_slug":"erdem-ozarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-ve-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VurguN', 'vurgun-erdem-ozarslan-gmtsm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'C evapsız kalan sorular yüreğimde

E kranda bir melek beyazlar içinde

Y a aslında hiç yok; bir rüya belkide bedenimde

L akin içimi sardı bir gülüşüyle

A teş gibi düştü gözlerime

N asıl diye sormayın dostlar ben vurgun yedim bir güzele', 'C evapsız kalan sorular yüreğimde E kranda bir melek beyazlar içinde Y a aslında hiç yok; bir rüya belkide bedenimde L akin içimi sardı bir ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özarslan']::text[], 8.5, '{"poet":"Erdem Özarslan","poet_slug":"erdem-ozarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vurgun-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NedeN', 'neden-erdem-ozarslan-d4s3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'C igaramdan bir nefes cektim yine

E llerim tütün yüreğim zift

Y alan yok arkadas tutuldum size

L aflarken bağlandım bir bütün olarak güzelliğinize

A nlamak istemiyorum  hislerimi artık bu saatte 

N edensiz bir acı içimde belkide nedeniyle..', 'C igaramdan bir nefes cektim yine E llerim tütün yüreğim zift Y alan yok arkadas tutuldum size L aflarken bağlandım bir bütün olarak güzelli...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özarslan']::text[], 8.5, '{"poet":"Erdem Özarslan","poet_slug":"erdem-ozarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CeylaN', 'ceylan-erdem-ozarslan-d56ac', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'C anlandiğı zaman; susan, közlenmiş alevler

E llerin terlemeye başlar önce hebersizce

Y astığına başını koyduğunda 

L aflarsın kendi kendine

A ğlamak gelir belkide yasanan tüm acılar, ask ile birleştiğinde

N eden dersin bu his yüreğimde,neden önce değilde....', 'C anlandiğı zaman; susan, közlenmiş alevler E llerin terlemeye başlar önce hebersizce Y astığına başını koyduğunda  L aflarsın kendi kendine...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özarslan']::text[], 8.5, '{"poet":"Erdem Özarslan","poet_slug":"erdem-ozarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ceylan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim', 'bilirim-sores-welat-demir-q54gt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Basmaktan cekinirim topraga

Artik aglamaktan cekinir oldum

Cünkü ne yigitlerdir yatar toprakta

Icim sizlar

Bilirim,..

Uzanirim gecelere

Ardi sira yildizlardan sorarim

Dolasip arar dururum izlerini

Ya onlar beni

Ya ben onlari bulurum bir sokakta, bulmak zorundayimdir cünkü. 

Icim bir hos olur buldugumda

Her birinde seni görür

Onurlanirim,.. 

(Besinci Mevsim & Bir Sevgi Dünyasi adli siir kitabindan, 2001)', 'Basmaktan cekinirim topraga Artik aglamaktan cekinir oldum Cünkü ne yigitlerdir yatar toprakta Icim sizlar Bilirim,.. Uzanirim gecelere Ardi...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bilirim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-gulden-karabudak-dmt7c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehir kan kırmızı

Kanayan yüreklerden artan

Bu şehir kan kırmızı

Gözlerimden arta kalan...

Bu şehir bir duman

Bu şehir bir yalan

Bir kale çizmiş şimdi

Gökteki  mor bir buluttan..

Bu şehir sevdalı

Bu şehir tarih kokan

Elleri değmiş ellerin

Yine de 

Kopamaz yarınlarından...

Gülden

23.11.2003

01:30', 'Bu şehir kan kırmızı Kanayan yüreklerden artan Bu şehir kan kırmızı Gözlerimden arta kalan... Bu şehir bir duman Bu şehir bir yalan Bir kale...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-i-brahim-i-spir-j42z2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'görüyorum; yalnızlığını

soğuk günlerin telaşındasın

görüyorum; dağın yandığını

suçlusu yakalandı; 

ateşböcekleri denmiş

görüyorum; paylaşımını sarının

kir ve mavzer korkusu çökmüş üstüne

yolunu kaybeden kuş', 'görüyorum; yalnızlığını soğuk günlerin telaşındasın görüyorum; dağın yandığını suçlusu yakalandı;  ateşböcekleri denmiş görüyorum; paylaşımı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim İspir']::text[], 8.5, '{"poet":"İbrahim İspir","poet_slug":"i-brahim-i-spir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerede-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken Kokunu Al', 'giderken-kokunu-al-okan-savci-yturt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana ayrılığın komaz

  Ama bırakma kokunu yastıkta.

Onu da al...

Almazsan eğer 

Görenler seni sevdiğimi sanır...

Anlatamam meramımı,

Ne dersem diyeyim

  Herkes tersine inanır...

Bardaktaki ruj izini silebilirim

Paspası ters çevirip, 

    Yok edebilirim ayak izini...

Ya kokun? 

Onu nereye atabilirim...

Her gece uyandırırken beni uykumdan

   Kabuslara sararken gecemi,

Kokunu almazsan bu evden 

Ben seni nasıl unutabilirim? 

Fazla ağladın ya o gece? 

Gamzen düşmüş yastığıma...

Bir yanda gülüşün,

Bir yanda gözyaşın,

Bir olup aksediyor duvarıma. 

Bunların hepsi kalsın....

Sadece kokunu al giderken

Sinmesin yokluğuna...', 'Bana ayrılığın komaz   Ama bırakma kokunu yastıkta. Onu da al... Almazsan eğer  Görenler seni sevdiğimi sanır... Anlatamam meramımı, Ne ders...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/giderken-kokunu-al-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soylu Çingene', 'soylu-cingene-sair-klaus-o1wt3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soylu bir çingene. Sabaha kadar uyumayan sabahtan sonra uyanamayan bir sahte dünya. Bir muhabbet almış başını gidiyor. Evde unuttuğu cümleler onu arıyor. Bir yağız at. Kırlarda,kayalıklarda koşuyor. Gitarın büyüsüyle bir bana bir ona gidiyor. Çingene çalıyor. Herkes yok. Yokluğun yokluğunda biz yokuz. atın yeleleri bizi var ediyor. Gitar susmuyor. Çingene kaptırıyor. Şehir yerine kırlıya dönüyor akşam. Yıldızlar bulutsuz. Çıplak bedenim aşk istiyor. Melodilerle at bana geliyor. Felaket yerine beni alıyor. Çılgınca yol alıyoruz. Saçma sözleri bırakıyoruz ateşin başında. Biz yok oluyoruz. kasıyor bir şair. Ne yazacağını şaşırıyor. Biz gidiyoruz. Umurumuzda değil cümleler. Şair değil macerayız biz. Şair kızıyor. Biz hızlanıyoruz. Çingene çalıyor. Dostum çingene hep çalıyor. At, aşkı buluyor. Mağaraya giriyor. Sarımsaklı mağarada aşkı arıyoruz. Anlamsızlıkların peşinde mutluluğu buluyoruz. Geri geliyoruz. Uyumayan ama uyanmayan akşamı uyuyarak geçiriyoruz.', 'Soylu bir çingene. Sabaha kadar uyumayan sabahtan sonra uyanamayan bir sahte dünya. Bir muhabbet almış başını gidiyor. Evde unuttuğu cümlele...', ARRAY['Türk Edebiyatı','Şiir','Şair Klaus']::text[], 8.5, '{"poet":"Şair Klaus","poet_slug":"sair-klaus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/soylu-cingene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkçem', 'turkcem-sair-klaus-x2y3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Süslenmiş ağzıyla beynimi doldurdu sabaha kadar. Sonra uyudu fütursuzca. Türkçe’nin öneminden bahsetti. Koruyalım, sahip çıkalım, onsuz olmaz dedi. Tabiki dedim bende. Ama Türkçe’yi çok bilmiyorum ki. Almışlar Türkçe’mi koymuşlar bir koca sahana. Bir sürü saçmalık ekmişler üstüne. Altını’da iyice yakmışlar.pişmiş, bambaşka bir şey olmuş. Yazmakta zorlanıyorum. Okumakta zorlanıyorum. Tanıyamıyorum. Bir gören olursa gerçek dilimi, bana haber versin. Yada birisi bana iyice öğretsin olurmu?', 'Süslenmiş ağzıyla beynimi doldurdu sabaha kadar. Sonra uyudu fütursuzca. Türkçe’nin öneminden bahsetti. Koruyalım, sahip çıkalım, onsuz olma...', ARRAY['Türk Edebiyatı','Şiir','Şair Klaus']::text[], 8.5, '{"poet":"Şair Klaus","poet_slug":"sair-klaus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/turkcem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmak İçin Aydınlığa', 'cikmak-i-cin-aydinliga-ali-osman-yilmaz-tbgub', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkmak için aydınlığa,

Umudun ve sevdanın beyazlığına,

Evet yırtmalı geceleri,

Yıkmalı zindan geceleri.

Gün ışığına salmalı,

Tüm seven yürekleri,

Sevdasına ulaşmalı yürekler,

Yeniden büyük bir imanla,

Alsın  eline ne bulursa,

Ne dağ desin,ne tepe,

Sevdası için devirsin,

Önünde ne dağ kalsın,ne bayır.

Sevdalısına kavuşmak,

Delicesine sarılmak ister,

Yıllanmış şarap şişesindeki,

Yıllanmış aşk şarabını,

Kana kana içmek ister,

İçtiği kendi sevdasıdır,

Yılların imbiğinden süzülmüş,

Sevdasında sarhoş olmak ister,

Ram olup ellerini ve yüreğini,

Sevdiğine sunmak ister.

Yürekler konmalı aslında,

Gerdek odasına öncelikle,

Yürekleri ile sevişmeyen,

Sevişse ne olur teniyle? 

Öfke ve kin yaşamaz sevgide,

Sevgi çiçekleri,kırmızı güller,

Her gün yeniden tomurcuklanır,

Yeniden sevmek,tazelenmek sevgide,

Düşünmez dün olanları,

Yaşar her sabah yeni sevdaları,

Her sabah güneşin altında yaşar,

Yeniden aşkını,sevdasını,

Al eline bir çiçek,

İstersen kırmızı bir gül olsun,

Bağla yanına da yüreğini,

Birde sevdan olsun yanında,

Gönder öylece sevdiğine,

Sevgide yaşanır umutlar,

Sevgide yaşanır yarınlar,

Delicesine,ya da huzur içinde,

Dolu dolu yaşamak için,

Haydi bağla yüreğini gül’e,

Yanına sevdanı da koyuver,

Gönder özel ulakla hemen,

Seni ve sevdanı bekleyen,

Aslan yürekli sevdiğine.', 'Çıkmak için aydınlığa, Umudun ve sevdanın beyazlığına, Evet yırtmalı geceleri, Yıkmalı zindan geceleri. Gün ışığına salmalı, Tüm seven yürek...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/cikmak-icin-aydinliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık*', 'ayrilik-bayram-tunca-jed2r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılık kalpleri yakan akkor 

Ayrılanları kim koynuna kor 

Ah hasretle yaşamak çok zor 

Ayrılık acısını yaşayanlara sor 

Ayrılıkların kimi kısa kimi uzun 

Her ayrılık akabinde var hüzün 

Ayrılık deyince dolar iki gözüm 

Ayrılıktan dolayı yanıktır özüm 

Kiminin gözü kiminin yüreği yaslı 

Ayrılıktır çoğu mutsuzlukların aslı 

Ayrılık deyince içime hasret bastı 

Gelse de sona erse şu ayrılık faslı 

Ah, şu âlemde ayrılıklar çeşit çeşit 

Her birisinin acısı sanki ölüme eşit 

Vuslata verilmiş, tek sırattan geçit 

O geçit sanki de iğne deliğine eşit 

Sordum nicesine var mı ayrılığa çare 

Dediler bulamadı Lokman Hekim bile 

Olsaydı hiç gezer miydik avare avare 

Ah olsaydı, hiç gitmez miydik o yare 

Hep derlerdi, ayrılık ölümden de beter 

Öyle olmasaydı hiç olur muyduk heder 

Nice kul, benim gibi ayrılık acısı çeker 

Vuslat için gece gündüz hep dua eder

Biz ne ayrılıklar gördük ciğer dağlatan 

Biz ne ayrılıklar gördük ulusça ağlatan 

Hak olmasa, ayrılırlar mıydı aramızdan 

Hikmetinden sual edemeyiz ki Hak’tan 

Kulak verdim feryatların çoğu ayrılıktan 

Ayrılmış ekser, anadan/babadan/yardan 

Her birisi vuslat dilemekte Yaradan’dan 

Hepsi diyorlar; ya Rab vuslat ne zaman 

10.12.2003-12.10 

NOT:

Bil ki; ayrılık günü mezarım kazılır benim

Yokluğunda toprak olur şu nazenin tenim', 'Ayrılık kalpleri yakan akkor  Ayrılanları kim koynuna kor  Ah hasretle yaşamak çok zor  Ayrılık acısını yaşayanlara sor  Ayrılıkların kimi k...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ayrilik-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Desinler', 'desinler-sule-aydemir-merl8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben gidiyorken yolum üzeri

yolundan saptı çıktı desinler

seviyorken deli divane yari

başka sevdalara baktı desinler

bir güzel uğruna kendimden geçtim

gülmek yerine ağlamayı seçtim

kendime acılardan kefen biçtim

sevmeyi unuttu bıktı desinler

sen gidince ölüm sandım

geceleri yastığımla ağladım

sen diye şiirlere sarıldım

acımı bilmeyip aktı desinler

bakarken gözünden gözün içine

aydan paha biçerken saçın teline

kendimden vermişken aşkım eline

sevmeyi bilmedi bıraktı desinler', 'ben gidiyorken yolum üzeri yolundan saptı çıktı desinler seviyorken deli divane yari başka sevdalara baktı desinler bir güzel uğruna kendimd...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/desinler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer İznin Olsaydı', 'eger-i-znin-olsaydi-abdulkadir-karaman-mu0kw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer iznin olsaydı, seni,

bulutların gökyüzünü

sardığı gibi sarardım; 

kaçsan bile, rüzgarlarla bir olur, 

uzak/yakın

diyar diyar arardım.

Eğer iznin olsaydı! ? 

sana gelebilmek için

gökyüzünü şimşeklerin 

yardığı gibi yarardım.

Aldırmazdım senin için

edilseydim her suçtan sanık.

Aldırmazdım yeryüzü, gökyüzü

olsa bile tıkanık.

Eğer iznin olsaydı yağmur gibi

çisil çisil yüreğine yağardım.

İsterse kararsın ufuklar..

isterse sararsın, küllensin umutlar...

bana ne, sana ne...! 

eğer iznin olsaydı! ? 

Tek sen sevin, mutlu ol diye güneşin olur 

hep istediğin ufuktan doğardım.

Engel olamazdı bir bahâne.

Eğer iznin olsaydı? 

sevgi ışıklarıyla

gönlüne çökelen

kesif karanlıkları boğardım

ve yüreğine yüreğimden hep sevgi sağardım.

29/09/83', 'Eğer iznin olsaydı, seni, bulutların gökyüzünü sardığı gibi sarardım;  kaçsan bile, rüzgarlarla bir olur,  uzak/yakın diyar diyar arardım. E...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eger-iznin-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçemedim', 'gecemedim-sule-aydemir-9q3og', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sabahın deli saati

Kadıköy sahili

oturuyorum

bir bankın üstünde

elimde fi tarihinde

sarılmış bir sigara

gülümseyerek düşünüyorum 

dumanı 

fi tarihinden 

ben

şu an ciğerimde iradem

hayır diyemedim

sigaradır diyerek geçemedim', 'sabahın deli saati Kadıköy sahili oturuyorum bir bankın üstünde elimde fi tarihinde sarılmış bir sigara gülümseyerek düşünüyorum  dumanı  fi...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklı Gazete', 'ayakli-gazete-nurhan-gokturk-o5yui', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önsözü, başlığı, baskısı,

Magazini, ekonomisi, sporu  yok,

Nedense müptelası pek çok,

Ne olup biter mahallede,

İki ayaklı gazetede.

Son baskısı dün gece tükendi.

Öksüz kaldı sıcak haberler,

Munise teyze dün öldü dediler.

Nurhan Göktürk

(8 Aralık2003/Antalya)', 'Önsözü, başlığı, baskısı, Magazini, ekonomisi, sporu  yok, Nedense müptelası pek çok, Ne olup biter mahallede, İki ayaklı gazetede. Son bask...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayakli-gazete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini İstiyorum', 'ellerini-i-stiyorum-galip-karabatak-or2vz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerini istiyorum, ellerini! 

Tutmam lazım saçlarından umudu,

Ve o sevdayı eteklerinden salkımsaçak! 

Hadi çabuk ol bekleyemem artık

Sonunda kalemim bile kurudu,

Ellerin yokken yazamayorum işte bak! 

Çalmalıyım geceden tüm yıldızları bir bir

Kendin gelme sakın, istemem sendeki seni

Bilirim,

Kapkara bedeninde yalnız ellerin temizdir

Ellerini istiyorum, “benim” ellerini!', 'Ellerini istiyorum, ellerini!  Tutmam lazım saçlarından umudu, Ve o sevdayı eteklerinden salkımsaçak!  Hadi çabuk ol bekleyemem artık Sonund...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ellerini-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim gördüğüm şehirsin/Dön artık!', 'benim-gordugum-sehirsin-don-artik-hicabi-ceylan-9odcw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kâlesizce bulutlardan kopup gelen 

Ve ağacın yaprağına  sığınan damlayım

Belki güneşte buharlaşıp kaybolacağım

Belki de deli bir rüzgara kapılıp

Yerlerde dağılacağım

Bir tek sen, sen kurtarırısın beni

Güneş eritmeden

Rüzgar toprağa düşürmeden

Tut avuçlarında ne olur bırakma 

Sakın ağlama, ağlarsan düşerim belki

Sakla deniz gözlerinde sakla beni

Korkar oldum gecelerden

Korkar oldum zifiri karanlıktan,

Gözlerimin önünde dolaşan hayallerden

Düşüncelerimle cihat halindeyim

Dipsiz bir kuyunun içinde 

Azat edilmeyi bekleyen duygularım

Biçare, çaresizce aydınlığı arayan

Mahzende şarap şişesinde tutsak

Sarhoş duygularım.

Gel artık! sen kokuyor buraları

Gel artık! Sensiz ıssız bu şehir

Herkes seni soruyor

Sensiz soğuk, üşüyor bu şehir

Gel gör ki deniz gözlüm

Arkana bile bakmadan, 

Bırakıp gittiğin, bu yürek

Hala yangın,hala sevdalı

Seni bekliyor.

12,12,2003', 'Kâlesizce bulutlardan kopup gelen  Ve ağacın yaprağına  sığınan damlayım Belki güneşte buharlaşıp kaybolacağım Belki de deli bir rüzgara kap...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/benim-gordugum-sehirsin-don-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk Diyarından', 'sonsuzluk-diyarindan-metehan-gokturk-yj75f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk Diyarından bir davet aldım

cennet kuşları getirdi..

Gülkokulu yarin selamını...

Ayrılıkların olmadığı....

haretlerin tükendiği....

ve güneşin hiç batmadığı...

mekenlara çağırıyor beni..

Geleceğim...

Bir rüzgar misali

Dağ bayır aşıp...

Bir bulut misali...

Göklerde uçup...

Bir ışık misali...

Yıldızlar geçip...

Hasretimi..Enderin uçurumlara atıp..

Sana geleceğim.', 'Sonsuzluk Diyarından bir davet aldım cennet kuşları getirdi.. Gülkokulu yarin selamını... Ayrılıkların olmadığı.... haretlerin tükendiği.......', ARRAY['Türk Edebiyatı','Şiir','Metehan Göktürk']::text[], 8.5, '{"poet":"Metehan Göktürk","poet_slug":"metehan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonsuzluk-diyarindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözü Kör, Kulağı Sağırlara', 'gozu-kor-kulagi-sagirlara-i-brahim-bayraktar-743b8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Minderi serip altıma bağdaş kurup oturdum,

Keyfe keder vermeden çok vakitler bitirdim,

Değmeyin hiç keyfime, ağa da benim, bey de,

Bir yanım har vurup harman savururken,

Bir yanım kavurga kavururmuş kime ne.

Ciğer alıp beslerken sokak kedisini,

Hayvan sever sanır ukalalar kendisini,

Her canlıyı sever, hem çok sever de,

İnsanlar aç bilaç sokakta yatarken,

Kimileri karnı tok uyurmuş kime ne.

Bende severim her canlıyı onlardan çok,

Rahat uyuyamam yatağımda karnım tok,

Belli ki; orada yer, içer, orada yatarlar,

Elimden bir şey gelmez, yanarım hallerine, 

Havadarmış, gece-gündüz esermiş kime ne.

Köprü altında yatarmış kimsiz kimsesizler,

Bakıp bakıp geçermiş benim gibi densizler,

Kovuktan mı çıktı bunlar, insan değil mi? 

Bu duyarsızlık; ne vicdana sığar, ne dine,

Sözlerim birilerine dokunurmuş kime ne.

Saç sakal karışmış, baldır çıplak, ayak yalın,

Suya hasret kalmış narin ten, kalın mı kalın,

Yuvasız doğmadı ki, garibin de vardı yuvası,

Tuh! Söylemez olsaydım, kopsaydı dilim,

Sokakta bir insan donuyormuş kime ne.

Mihnetim yoktur, Tanrıdan ziyadesine,

Kolumu yastık yapar, yan gelir yatarım,

Böylesi de gelebilir herkesin hanesine,

Onlar dışarıda titreyerek volta atarken,

Bazıları da boşa konuşurmuş kime ne.

12.12.2003', 'Minderi serip altıma bağdaş kurup oturdum, Keyfe keder vermeden çok vakitler bitirdim, Değmeyin hiç keyfime, ağa da benim, bey de, Bir yanım...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gozu-kor-kulagi-sagirlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni İstiyorum', 'seni-i-stiyorum-burcu-arda-yjcm2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni istiyorum

Gün doğarken kal yanımda

İçim ısınırken yavaşça

Gün batımı gibi bırakma...

Sanrılı karanlıklara değil; apaçık,gün gibi,ışıl ışıl

...zamanlara bırak beni

; ama sensiz değil! 

Sonra fırtına çıksın; en korktuğum kum fırtınası; 

Sen hep kal yanımda..

ölmekten çok korkarım; bilirsin...', 'Seni istiyorum Gün doğarken kal yanımda İçim ısınırken yavaşça Gün batımı gibi bırakma... Sanrılı karanlıklara değil; apaçık,gün gibi,ışıl ı...', ARRAY['Türk Edebiyatı','Şiir','Burcu Arda']::text[], 8.5, '{"poet":"Burcu Arda","poet_slug":"burcu-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-istiyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-ayse-tural-no1b4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir avuç oluşturmak için

Bitiştirdiğim ellerime

Alıyorum seni...

Parmaklarımın arasından

Dünyalar dökülüyor

Bir hayat istiyorum

Senden gelen

Seninle çoğalan', 'Bir avuç oluşturmak için Bitiştirdiğim ellerime Alıyorum seni... Parmaklarımın arasından Dünyalar dökülüyor Bir hayat istiyorum Senden gelen...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Tural']::text[], 8.5, '{"poet":"Ayşe Tural","poet_slug":"ayse-tural","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istiyorum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-satilmis-turgay-karabacak-f8xlt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yorgunum..

dünya benden kaçar,bende dünyadan

gülüyormuyum

siz öyle sanın

yaşıyormuyum

siz öyle sanın

benim kisi tiyatro

kendi kendimi kandırıyorum

kendi kendime oynuyorum

yolun yarısına geldim

belki de sonuna

ne var elde 

bomboş bir hiç

arkadaş eş ana baba

çoluk çocuk akraba

hey dünya aldat bakalım

koştur bakalım

sahte oyuncaklar peşinde

üç gün sonra onları benden

benide onlardan alırsın

koştur bakalım

para mal mülk peşinde

üç gün sonra onları benden

beni de onlardan alırsın

ya sonra......

([email protected])', 'yorgunum.. dünya benden kaçar,bende dünyadan gülüyormuyum siz öyle sanın yaşıyormuyum siz öyle sanın benim kisi tiyatro kendi kendimi kandır...', ARRAY['Türk Edebiyatı','Şiir','Satılmış Turgay Karabacak']::text[], 8.5, '{"poet":"Satılmış Turgay Karabacak","poet_slug":"satilmis-turgay-karabacak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sonra-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Islatan', 'asik-islatan-yaren-gurler-tapqb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur insana 

Hızlı yürümeyi öğretir,

Ve bir de gizlemeyi gözyaşlarını.

Ama sen hala 

Öğrenemediysen hızlı yürümeyi,

Ve gözyaşların bastırıyorsa yağmuru,

Yağmurun adı artık aşık ıslatan olur,

Ve sen;

Ahmakların en büyüğü.', 'Yağmur insana  Hızlı yürümeyi öğretir, Ve bir de gizlemeyi gözyaşlarını. Ama sen hala  Öğrenemediysen hızlı yürümeyi, Ve gözyaşların bastırı...', ARRAY['Türk Edebiyatı','Şiir','Yaren Gürler']::text[], 8.5, '{"poet":"Yaren Gürler","poet_slug":"yaren-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asik-islatandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feride', 'feride-hakki-hakan-kaya-u1c3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siyah zülüfleri düşmüş alnına,

Rüzgar teline vuruyor Feride,

Ömrüm boyunca özlemle bekledim,

Ayrılık kapımda duruyor Feride.

Yürek dertlerime çare arama,

Acıları merhem yaptım yarama,

Aşkımın ağacı büyüyor ama,

Her düşen yaprak kuruyor Feride.

Leylası için Mecnun deliriyor,

Yar uğruna tüm sırlar seriliyor,

Her sorunun cevabı veriliyor,

Aşka soru sorulmuyor Feride.

Sevdan bedenimde benle yaşıyor,

Ser hayrına ne engeller aşıyor,

Kah seni arıyorken, senden şaşıyor,

Aşkta yürek yorulmuyor Feride.', 'Siyah zülüfleri düşmüş alnına, Rüzgar teline vuruyor Feride, Ömrüm boyunca özlemle bekledim, Ayrılık kapımda duruyor Feride. Yürek dertlerim...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/feride-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Biletim', 'cehennem-biletim-yaren-gurler-pvfgm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni gördüm; 

Cehennem biletimdi o halin.

Çünkü ben

Seni Allah yarattığı için değil,

Allah''ı seni yarattığı için sevdim..', 'Seni gördüm;  Cehennem biletimdi o halin. Çünkü ben Seni Allah yarattığı için değil, Allah''ı seni yarattığı için sevdim.....', ARRAY['Türk Edebiyatı','Şiir','Yaren Gürler']::text[], 8.5, '{"poet":"Yaren Gürler","poet_slug":"yaren-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cehennem-biletim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'be-adam', 'be-adam-murat-demir-6lu7p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açıkta değildin,açta değildin

İşin gücün vardı,boşta değildin

Tarlandan alırdın,evinde yerdin

Neden battın,bu batağa be adam

Ocağın yanarken,bacan tüterken

Sulak toprağında,herşey biterken

Bağında bahçende,kuşlar öterken

Neden battın,bu batağa be adam

Başında ne patron,nede bey vardı

Büyük sever idi,küçük sayardı

Orda da bayramlar,seyranlar vardı

Neden battın,bu batağa be adam

Evin vardı,villa gibi ahşaptan

Derdin yoktu,hırsız ile kapkaçtan

Her şey belli,başındaki ak saçtan

Neden battın,bu batağa be adam

Ya bir işçi,ya da patron olmaya

Çokmu meraklıydın,garip kalmaya

Adamın varmıydı,mezar bulmaya

Neden battın bu batağa be adam

Bazısına,iyi gelmiştir belki

Öyle bir illet ki,parada,yetki

Altın dökmüştüler,yoluna sanki

Neden battın,bu batağa be adam

Mektup mu almıştın,ya da bir davet

Sürgün mu etmişti,yoksa bu devlet

Vasiyetin varmı,ölürsen şayet

Neden battın,bu batağa be adam

Bazen güldün,bazen derde boğuldun

Yavaş yavaş,acılarla yoğruldun

Evinde ne süt var,nede yoğurdun

Neden battın,bu batağa be adam

Murat der sorum çok,fakat sormadım

Darılırsın diye,seni yormadım

Bir cümleyle söyle,sen adım adım

Neden çıktın,gurbet ele be adam', 'Açıkta değildin,açta değildin İşin gücün vardı,boşta değildin Tarlandan alırdın,evinde yerdin Neden battın,bu batağa be adam Ocağın yanarken...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/be-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masada', 'masada-bekir-necati-q6tad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gör işte Abbas

  Yine tek

          Yine tek

                   Yine tek

Toplasan 

   tek 

       tek

40 gün eder

305 gün

     tek geçer

         bir kalemde,

Bu da eder

         305 şişe

Çok görme be Abbas

Bu daha ilk şişe

Abbas! 

        Çok görme be 

Bırak şimdi,

     hesaplama

Eksik ise 20 gün

Tutsaklığımdır o da,

Kendim olan kendime

İster yaşamışlığı de,

İster görüş günü

20 si de geçer

           Uykuda düş gibi

İşte böyle Abbas

Hatırlatma kerize

Hatırlanması gerekenleri

Şimdi dalmış, şişede 

              kum çıkarmada,

                    yosun toplamada

                          kederlerde

Başa bela sevdalısına

Bilmezmisin be Abbas! 

Bu masa nasıl aratır insana,

İnsanı nasıl aratır.

Şişede sevdalar', 'Gör işte Abbas   Yine tek           Yine tek                    Yine tek Toplasan     tek         tek 40 gün eder 305 gün      tek geçer    ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/masada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengin adı', 'rengin-adi-bekir-necati-pix6f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çökmüşse dizlerine,

hasret penceremden geçen gemilerin

bacasından çıkan kara duman gibi yorgunluk

ve

kalmamışsa dermanım adım atacak,

serin yağmurlara, ıslak dağlara

ve 

düşmüşse yüreğime,

kurşun yarası, ağır acı bir sancı

ve

inmişse gözlerime,

yutkunan çığlıksız zifiri karanlık gece

Ne fark eder ki ölümün rengi

Gri, puslu çocuksu sevdalar

veya

Mor, buz kesmiş çıplak bedenler

veya

Kor ateş kızılı, ölüm ağıtları

veya

.......

Ne fark eder ki ölümün rengi

Ölümün

Bela olası adını ben verdim

Sıkıysa 

Rengin adını sen ver', 'Çökmüşse dizlerine, hasret penceremden geçen gemilerin bacasından çıkan kara duman gibi yorgunluk ve kalmamışsa dermanım adım atacak, serin ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/rengin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Takdimimdir 2', 'kendimi-takdimimdir-2-oguzkan-bolukbasi-sr4em', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.......................................özel amaçsız bir sohbet

Hayat önümden geçer

Her şekil

Ve her biçimde

İstediğim ne ise ben seçerim

En parlak elbiseler vardır

Ben uygun bir renk biçerim

 Hep aynı adamım özünde

Başkalarını ciddiye alırım

Kendimi tiiiiiiii  ye

Sorularım hiç bitmez

Neden

Nasıl

Niye 

Hayat adaletsiz diye diye

Adil bir yaratılışı keşfettim

İçimin huzurunu

Kendimi tanıdığımda resmettim 

Doğal ve sosyal çevreyi kirletmeden

İnsan hakkı yemeden

Yaşamayı belledim

İçimden gelenlere karşılık beklemeden

Sevdim

Sevdim 

Sevdim 

Sözüm iğne de olsa

Çuvaldız etimdedir

Aşkı bile çözmüşüm

Aşk benim kendimdedir

Hem tekilim

Hem çoğul

Sebebim benim………………', '.......................................özel amaçsız bir sohbet Hayat önümden geçer Her şekil Ve her biçimde İstediğim ne ise ben seçerim En ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kendimi-takdimimdir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tören', 'toren-yasemin-kaplan-bu6s7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ay yarımdı; dört kadın, 

samimiyetsiz kullanıcısıydı soluduğu havanın

ateş böcekleri topladılar eteklerinde.

havva’nın kızlarıydı.

ecele aceleleri vardı,

konya ereğli civarında; bir yazıda.

kuytularını sundular vahşi doğaya

arsızca! 

biri yeni gelindi, elleri kınalı.

bin yıllık bir sırrı kustu kengerin biri.

suriye sınırında nefeslerine kıyılmıştı yiğitlerin.

az ileride kırk tane cin; 

tören vardı masalarında

rüzgarın çığlığıyla inlettiler yeri göğü

kabardı kuru toprak

suyu görse çamur olurdu ortalık.

kaybedilmiş zamanlara kop liman düşlerin töreni.

bu bir ölüler töreni

anılar geçiyor atlılarla dört nala anılar

bu bir yaşanmışlıklar töreni 

dört nala geçiyor mevsimler, 

ömrün bilinmeyen devirlerinden.

üç ayaklı sınırlarda; koruyan, güvenen, tutsak eden

üç noktalı masalların rengi soluyor

sesin kadar yumuşak, 

nefesin kadar ıslak devinimler töreni bu.

atlılar geçiyor yırtarak iniltisini rüzgarın

sesler geçiyor dört nala. 

fırtınalara taşlar fırlatan haşin, hırçın...

yaşanmışlıkların sesleri geçiyor dört nala! 

evler geçiyor  evler.

pencereler geçiyor dört nala! 

kapılar geçiyor, kapanmış ardına kadar

vurgunlar töreni bu

vurgunlar geçiyor dört nala

bu sahnede yok eller, yok gözler, yok  ayaklar

yok sevişenlerin teni 

kurgular dünyasında olmazdı masalların yeri.', 'ay yarımdı; dört kadın,  samimiyetsiz kullanıcısıydı soluduğu havanın ateş böcekleri topladılar eteklerinde. havva’nın kızlarıydı. ecele ace...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Kaplan']::text[], 8.5, '{"poet":"Yasemin Kaplan","poet_slug":"yasemin-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/toren-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılırmak', 'kizilirmak-mustafa-dinler-2zipo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Serin sularınla

	akmadın

		yanıp tutuşan gönlümüze,

derin sularınla

	bırakmadın

		bizi bize…

Ah Kızılırmak! 

	Kara kaderimiz misin sen? 

Kızılırmak

	Suyun niye bulanık? 

Birazcık

	ama birazcık

		merhametliysen,

bırak inadı artık

		kavuştur bizi.

Senin inadın yüzünden kırık

		Kalbimizi

Tekrar eski yerine tak.

Bırak,

bırak inadı artık Kızılırmak,

bırak bulanık akmayı

	ve düşün sevenleri birbirine bırakmayı.', 'Serin sularınla 	akmadın 		yanıp tutuşan gönlümüze, derin sularınla 	bırakmadın 		bizi bize… Ah Kızılırmak!  	Kara kaderimiz misin sen?  Kız...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dinler']::text[], 8.5, '{"poet":"Mustafa Dinler","poet_slug":"mustafa-dinler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kizilirmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Lethe''den Kaçış! ...', 'lethe-den-kacis-naime-erlacin-09tu7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey kaçak yolcu! 

yepyeni bir güne sıfırdan başlarken

nereye gizledin 

sesine sindirdiğin ağır yükü 

rüzgâr çanları sakladın gözbebeklerine

esintiyle doldu, kabardı ruhun 

bezgin bir hayat mahkûmusun

düşmüşsün taze çileler peşine 

avuntuyla yaşamıştın

armağandın bir dağ gelinciğinden

yaşamsal iç kıpırtıların şimdi

isyankâr bir vedaa benzer

tanıdık adreslere gönderilen

cesurca döşemek gibi raylara 

bilinmedik kentleri

bakir sularda yıkamak 

tutunmaya çalıştığın ölü simgeleri

böylesi bir çığlık duyduğum işte! 

trenin sesinde akıyor zaman

yağmurunda ıslanıyor bedenin

görüyorum

sonuncu vagon geçiyor üzerinden

nefesine iri bir kuş süzülmüş

yanıyor 

tutuşuyor göğüs kafesin

Lethe’den* kaçış bu besbelli 

uçman lazım yolcu 

bulutlara tırman

umudu oraya sakladılar

Lethe’yi unutma 

bulutlar Lethe’den kaçtılar 

.......

(*)     Lete (Lethe) : Suyundan içen ölülere, acıları ve yeryüzü zevklerini unutturan (cehennemdeki)    ırmak.

(12 Aralık 2003)', 'ey kaçak yolcu!  yepyeni bir güne sıfırdan başlarken nereye gizledin  sesine sindirdiğin ağır yükü  rüzgâr çanları sakladın gözbebeklerine e...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/lethe-den-kacis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahanlıkta', 'sahanlikta-ozer-turan-yl5bn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüzünü saklıyor ben giderken

acemice utanıyor kent başları

kokona bir kadının 

ölü balıklar yüzüyor göğsünde

göğsünde eskil duyarlıklar

sözlerini yüreğine banıp banıp konuşuyor

sevda vurgunu yorgun karınca

kendi içine aktıkça çoğalıyor yüreğim

papaz efendi

bir öpücüğün günahını soruyor en çok

vivaldi dinliyorum ellerim üşüyor

bir çocuğun mışıl mışıl uykularından geçiyorum

patiska örtülerde büyüyor düşler

ellerim ayaklarım yarabere avuçlarım

nefesim karadeniz kokuyor bileklerim sızlarken

ve bas bas bağırıyor gelene geçene

fırtınaya yakalanmış cırcır böceği

ne zamandı

bilemiyorum

bir ceylanı yüreğinden

öpmüştüm', 'yüzünü saklıyor ben giderken acemice utanıyor kent başları kokona bir kadının  ölü balıklar yüzüyor göğsünde göğsünde eskil duyarlıklar sözl...', ARRAY['Türk Edebiyatı','Şiir','Özer Turan']::text[], 8.5, '{"poet":"Özer Turan","poet_slug":"ozer-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sahanlikta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Gidişin', 'zamansiz-gidisin-safure-yildirim-absgs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ateş yumağı içimde

zamansız gidişin,

kor ayaz dışarda

ben alev alevim,

dayanılmaz yokluğun

deli divane gezerim,

çabuk kanarken herşeye

buna inanamıyor yüreğim,

çıkmazlara dalıyor,

bir umut aranıyor

cama yapıştı gözlerim..

8.12.03 ilkim', 'ateş yumağı içimde zamansız gidişin, kor ayaz dışarda ben alev alevim, dayanılmaz yokluğun deli divane gezerim, çabuk kanarken herşeye buna ...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zamansiz-gidisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-emin-baydil-3z4cb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak, yine sabah oldu! .. Güneş doğmak üzere,

O sakin ve o durgun, masmavi gökle yere.

Kucak kucağa sanki, mutluluk vermiş Tanrı''m...

Belki de kuş sesleri, bir musikî rüyası,

Aşka gönül verenin, böyle başlar dünyası.

Hele, bir hoş sabaha, bülbüller vermiş Tanrı''m...

Lâle, sümbül, menekşe; güller açılır şimdi,

O, geceyle başlayan, gözyaşlarımız dindi.

Kullarına sabahı, hediye vermiş Tanrı''m...', 'Bak, yine sabah oldu! .. Güneş doğmak üzere, O sakin ve o durgun, masmavi gökle yere. Kucak kucağa sanki, mutluluk vermiş Tanrı''m... Belki d...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sabah-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayrı', 'sayri-halit-balcioglu-ylk6s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak devletin eski komşusu,

artık yollar uzun,

hediye kervanları niye? 

Nerede deve sırtı eğri yolculuklar; 

zaman geçer ve perdeler değişir,

toprak olur ellerimin sancısı.

Üzüntülere bedellenen çokluğumda

esen rüzgar içimi doldurur.

Zaman kum ve sel; 

benden önce ve benden sonra 

bu çöle düşenlere selam olsun.

yazıklamalar boşa,

sözler sahipsiz.

Senler,

sizler

ve diğerleri; 

anlamsız boşluğun 

anlamsız adımları.', 'Uzak devletin eski komşusu, artık yollar uzun, hediye kervanları niye?  Nerede deve sırtı eğri yolculuklar;  zaman geçer ve perdeler değişir...', ARRAY['Türk Edebiyatı','Şiir','Halit Balcıoğlu']::text[], 8.5, '{"poet":"Halit Balcıoğlu","poet_slug":"halit-balcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sayri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okullar eylule aciliyordu....', 'okullar-eylule-aciliyordu-mustafa-lita-m88lm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugun okullar aciliyor ulkemde, 

sari kirmizi cantam elimde 

nufus cuzdanim yok cebimde 

bugun...............! 

okullar aciyor bilmeye basliyorum A harfinden! 

a''dan z''ye unutmuslugumu hatirliyorum, bugun? 

yeni yuzler yok bir koy cocugunun hafizasinda bugun 

sonra kulagimin cekilecegini nasil bilebilirim? 

cumlesini kurmayi sonra ogreniyorum hayatimin. 

gormeye basliyorum bugun duymaya devam ediyorum 

fisler kesiyorum,yumurta soyuyorum,yildizlara bakiyorum 

odevimi yapiyorum cok seviniyorum bugun bir harf ogrendigime 

saymayi ise daha onceden biliyorum gulmelerimin. 

ne anlama geldigini hatirlatiyor yeni yuzler, anliyorum! 

silgi kokuyorum bugun kalem kokuyorum,annem kokuyorum! 

yika beni top oynadim bugun! en cok top oynamayi seviyorum! 

bugun yanlislari ogretiliyorum,yarin anlayacagimi bilmiyorum bugun. 

sonra herkesin bildigi hayat bilgisi ezberlemesi olmuyor sabah okulu ertelemesi! 

sonra ilk istiklal marsi soyler gibi yapisim, utanc oldugunu ne bileyim bugun. 

sarisin bir cocuk nasil gelir okula ustunu kirletmeden eylulde? 

yagmur seli cikisi sanilan duvar deliginden,kestirmeyi seviyorum ta o gunlerden! 

benden baska ogretmenimizin piliclerini yerken yakalanan tek o kopek cikiyor o delikten! 

sonra delik bana dar geliyor dolasmaksa hic hos gelmiyor, alisiyorum haylazliga.......... 

sonra ne bileyim hani toplara pis vurmayi ogreniyorum dedimya yanlis seyler ogrendiklerimi bakin bak! 

muzik dersinde beste yapmaya kalkisim dort uncu sinifa rastlar oysa sekiz unlu harfi coktan biliyorum b! 

resimlerde kovboy yapisimda o yillarda cizilir buradan anlasiliyorku! bir kizildereli hikaseyidir yasatilan bize, 

bazilari ucak yapiyor benimse cowboy yanlizligim ta o gunlerden basliyor,kimse kovboy ne demek bilmiyor. 

yil doksan kusur komsumuzada faydasi olacak kiraz agacimiz cicek aciyor. 

istahimizi aciyor kucucuk kirazlar kahretsin olmadi hala! 

babam izinde vermiyor>diyor ki gok gormedigin kirazi olmus erken yedirmisler komsuya! 

sonra biz kirazin agacini bir kaziga bagliyoruz yaklasmasin komusya diye yil doksan kusur. 

benim ilk okulumla aramda bir tek yok var okumakla gecen. 

evimizin onundeki cam agaci buyukdukce buyuyorum ben sonra,ilk okulu goremiyor camdan bakanlar. 

geliyorlar cagla yemeye okulumun bahcesine gelecek yil acacak budaklar ellerinde. 

okulun bahcesinde zeytin agaci yil doksan kusur buyuyorum yeni ekilmis selviler gibi. 

ayip laflar ogreniyor yanliz fis kesmiyoruz artik aspirin aldigimiz eczaneden, bizde buluyoruz dogru cevabi. 

sonra evimize televizyon geliyor izlemesi bitiyor TRT ''nin ilk okulumun cAMI gibi buyudukce ozel kanallariniz! 

bir kayanin dibinde geciyor ilk okulu hikayeleri erken batiyor gunes aksam ustuleri,ezan vakti anlasiliyor simdi 

simdi carptikca sayilari buyuyor sonuclar benim gibi! 

bolundukce buyuyor sayisi cocuklugumun hep tek sayilar boluyor okul numarami 9 kalanli bolmeleri gormedik sormayin amca, dur bakalim raftaki bali bulabilecek misin diyorlar... 

sonra dislerim curuyor nedense tatliyi cok seviyorum. 

asicilar geliyor ilk asimdi tutan tatli diye yedigim sekerden sonra kolumda kaldi simdi sacabacagi! denir buna 

biz daha geometriyi yeni goruyoruz acildikca aciliyor zihnimiz cay iciyoruz sabahlari findik dagitiyorlardi parasiz nedense bizim baris findik yemezdi parasiz namuslu cocuktu ogretmenin ogluydu kokusundan belliydi kendisi, kahretsin beni gecmisti yine! ne de olsa benden bir gun once dogmus abim sayilirdi sakir sakir yuze kadar okula gitmeden  bir seksen iki marti nin sabahi bizde sanciliydik nerden bilirsin 82 ana yasasi bu iste sonra ogrenirsin gel gel yakmayacak deyip koluma asiyi vuran adama halen kiziyorum! 

sonra cocuk bayramimiz olurdu ben yumurta tasima yarisini bir kasikta kazanmistim derin kasiklarda yemek yemedik halen ama yanlis odul vermisler benim odulu kiz kardesime verdik aglamasin diye bayramda cekilecegimiz fotograf ani geldiginde halen oyle o fotograf duruyor elimde tufek oyuncak olsada cocukluk! 

sonra ilk defa bir kiza sariliyorum bir hafta ici sicak bir gun eylul! 

evet cok iyi hatirliyorum kapatsamda iyi kapanmiyordu hayat bilgisi defterim kiristirmistim kiyilarini omrumun! 

bugun okullar aciliyor silgi kokuyorum artik cam bizim evin onunu kapatmis kocaman bir cocuk olmusum. 

ama halen nasil silgi kokuyorsun hatirliyorum, daglarin arkasindan dogan gunesler yapardi sinifin birinci ogrencileri.silsen kufur etmis bir cocuk yuzu gibi kirisirdi defterin cografyasi anlasildigi gibi! 

sonra geldi catti hic sucumuzda yoktu okul bitisinde kac kez haber yazmadim kac kez sopa yedim oysa kimse benim kadar haber seyretmiyormus ama demir elli insanlarin toplanti yaptigini soylerlermis haber olsun hocam!  evet olsun benim inonun sesinden haber yazamadigim olsunda.namussuz bilo deyisime bes verin ne olur bak benim kadar kimse guzel turku soyleyemiyor........... 

allahim affetsin din dersinden kopya cektigimi.okulda af yasasida cimarkiyordu bir keresinde beni yakaladi hocam sifiri basti..hocam ne bu sifirlar dedi babam turk liramiza donmus hayat bilgisi,cografya,tarih. 

bugun okullar aciliyor sifiirlari atiliyor turk liramizin sukurler olsun gelecekte iyi birisi olacagimi anlastiran hocama selam ediyorum, hocam hatirliyor musun her gelen gecen ucaga selam et dayima diye bagirirdik. 

doksanli yillardi dayisi askerde olmayanlar turku soylemezlerdi dinlerdi.sonra ogrendim sukut kelimesinin dinlemek oldugunu elektrkli sozlugumden cikarip aklima islemistim hayat oyununun sahnesini aklimca! 

sonra en iyi dostum olacagini nerden bilirim ilk okulu kus kapattigimiz arkadasim sutlunun.duyunca hatirlar isminide kus oldugumuzu bilmezdi hani,insan kendi kendine kusermi adli kompozizyondan nasilda gecer not almistim...........nasil geldi gecti ilk okul sonra okul kutlamasi mi yoksa yerli mallari haftasi mi bilmiyorum biz lambada dansina kalkmisiz sinif halinde benim lAMbada terligim YOK! HALEN AMA OLAN ARKASLARIM OLDU! evet yerli mallari haftasiydi benim holiday cokolata yedigim o gun ben size demedim mi yanlis ogretiyorsunuz diye. azin yalin ayak kosmasi bir hos olurdu bunu bir kenera yazin herkes kosmustur yalin ve kendi ayaklariyla..... 

sonra ben okulu bitirdim tessekur belgesi verceklermis ama belge yokmus en azindan bir teseekur edildigini babama soyledigimde afreni yemistim.karnimiz tok bunlara dediler sonra oysa karinlari acti bu yil gecen yil kopardiklari icin dallarini caglamizin, koparmasalardi cagla beyaza acilip badem olacakti tatlimiza... 

benim hic the end yazan roman okudugum olmazdi... 

insn bir hikayeyi ezbere bilme derdine ne zaman duser simdi anliyor bir hikayeyi yaziyorum cocuklugumdaki cocuklarin bakislarini gorebiliyorum bugun okullar acildi memleketimde caglalar gibi! 

sinif yoklamsi bizzat yapiliyor sessiz musatafa lita no 9 burdami? burdamisin oglum cevap versene! 

cevabim dusunuyorum.................... 

simdi okular aciliyor memleketimde! 

korkma sonmez bu safaklarda yuzen al sancak diye.............', 'Bugun okullar aciliyor ulkemde,  sari kirmizi cantam elimde  nufus cuzdanim yok cebimde  bugun...............!  okullar aciyor bilmeye basli...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Lita']::text[], 8.5, '{"poet":"Mustafa Lita","poet_slug":"mustafa-lita","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/okullar-eylule-aciliyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapilar acik pencereler kuslar icin,', 'kapilar-acik-pencereler-kuslar-icin-mustafa-lita-c1vsg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni dusunuyorum kapilar acik

pencereler kuslar icin,

gerlisen diye belli,belki o iki sessizliginde

seni dusunuyorum aksam sabah....

seni dusunuyorum sabah aksam.....

yani yirmi dort saat seni dusunuyorum....

anliyor musun? duyuyor musun? 

dusunurken kendini veriyor musun? .....

seni dusunuyorum salata yerken 

yabanci memleketlerde bir domates kokusunda.....

seni dusunuyorum sogan yoklugunda acima! 

biliyor musun butun sarkilar beni titretiyor.

sanki elin deyiyor tenime ve elin deydigi yerlerde.....

ben seni bekliyorum kapilar acik,

pencereler kuslar icin, seni dusunuyorum! 

gelirsin diye belki oda mi temiz tutuyorum.

her gun sakal trasi oluyorum, kitap okuyorum ve seni seviyorum....! 

gelirsin diye belki o adami biraktigin gibi tasiyorum! 

seni dusunuyorum kapilar acik! 

pencereler kuslar icin ve mevsim ilk bahar diyor takvimdeki yaprak...

ve ben yaprak yaprak sana icimi aciyorum goncam! 

seni dusunuyorum bir sair gibi ilk bahar havasinda 

unutma ki sairler hep ilk bahar havasinda kalabilenlerdir! 

seni bekliyorum hic bir cicegi dalindan koparmadan vazolar bos! 

kitaplar acik kapilar acik pencereler belki bahar girsindiye odama bekliyorum sanki hic bir is yapmamislik hissi ustumde kolay deyil be...

onca uzun sene onca bahar yapragi bir cok saire eser olur ve oluyor...

seni bekliyorum bak bahcemde ilk cicek acti,icimde bizbiz kusu ucuyor! 

tutmayin beni diyorum tutmayin pencereler acik komsularin kulagi bizde.

delilik ki tam ustumuzde alnimizda bir siliv c ilk acan cicek gibi.....ben......

seni bekliyorum gelir konarsin diye paylasmak icin vakit erken sayilmaz..

unutma ki yalniz sayilmaz insan tekse yalniz sayar kendini! 

kapilar acik pencereler kuslar icin bardaktaki su tasik masa ortusu islak,

masanin kabugu kalkacak kimin umrumda aclik sevmek varsa kalbinde....

sanmaki o bardagi koparacagim guller icin doldurdum sadece sen gelene kadar 

ne kadar buharlasacak onu merak ediyorum.......belki pencereler bir hile icin acik usutuyorum ilk bahar tozlarinda cicekler gelecekler bir daha ki bahara bekliyorum kapilar acik pencereler serceler icin unutmaki sevgili hic bir kirlangic saltanati bir serceye kalmaz! seni bekledim simdi sana geliyorum....

not>eger buraya geldiginde bu siiri okursan anlarsan seni geldigin veya cok onceleri gittigin yerde bekliyorum hadi gel kolarim acik gurbet donusu bekleyen anneler gibi kollarim acik ve sicak hadi gel geldigin evde pencereler acik kuslar icin kapilar acik usuyorsan seviyorsan seni bekliyorum hadi gel! 

seni seviyorum mevsim deyismeden bekliyorum bir soz senden oyle sicak ve icten biz yasamayi seviyoruz.

hos geldin biliyordum gelecegini mevsimini bekliyor korkuyordun erken olmekten erken acilmaktan bahara hos geldin ilk acan cicegim hos geldin! 

erken olecegimizi biz biliyorduk!', 'seni dusunuyorum kapilar acik pencereler kuslar icin, gerlisen diye belli,belki o iki sessizliginde seni dusunuyorum aksam sabah.... seni du...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Lita']::text[], 8.5, '{"poet":"Mustafa Lita","poet_slug":"mustafa-lita","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kapilar-acik-pencereler-kuslar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berivan', 'berivan-sair-ysl-878q5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evet hayat yürüyor

Bir çözüp bir bağlıyor zamanın ellerini

Ve diyalektiği 

En iyi o biliyor berivan

Sen çoktan yatmış uyumuşsundur belki

Belki ayaktasın

Oysa ben seni bulabilmek için düşünde

Öylece bekliyorum

Daracık bir valensiya sokağında 

Bir elektrik direğinin dibinde 

Ayakta

Sanki bu dağın taşı eksikmiş de bulmuşum

Sanki bu ırmağın akışı berivan

Sanki her ağacın başka bir adı varmış

Her çiçeğin bir anlamı daha kalmış

Sanki dudaklarım gülümsemeye mahkum yeniden

Ağaçlardan, arabalardan ve binalardan geçiyorum

Hiçbirine değmeden

-Biliyorum bu da güldürecek seni

Romantik adam diyeceksin

Utanmaz olduğumu da bileceksin

Koca çocuk

Neler yazmış yine

Ve ben de güleceğim

Hem sana

Hem diyalektiği hiç bilmemişliğime-

De

De hadi söyle bana

Küba’ya gider miyiz seninle

Ya da munzur’a parmaklarımızı sokup

-Şimdi munzur üşüyordur-

Çocukları sayar mıyız 

-Oniki tane olacaktı, bak eksik var mı? -

Ve işte tam burada açmıştım telefonu

Kulağımdaydı sesin 

Biliyordum kulağımdaydı

Ama tabanlarımda duyuyordum 

-hala yatmadın mı sen? 

-alışkanlıklarımı değiştirecek değilim! 

-bu şiir senin ama şımarmış gibi geldi sesin

 o yüzden hatırlatmak istedim:BENİM OLACAKSIN! Biliyorsun değil    mi? 

-belli olmaz! şımart beni! 

Telefonu kapattım

Pencereleri ve kapıları kapattım

Gözlerimi kapattım

Ellerimi ve kendimi kapattım

Düşün berivan

Hangi şairi şımartmaz

İkibin kilometrelik bir şiir

Düşün ki butün ilham perileri

Ve perilerin bütün masalları

Sırça köşkler

Divitler

Mürekkep hokkaları

Emrimde

Hadi şımar berivan

Bütün şiirler gibi

Bu şiirin de bir şairi var

Yani herkesin bildiği bir sırrın 

Hadi gülümse berivan

                              Uysal Himmet', 'Evet hayat yürüyor Bir çözüp bir bağlıyor zamanın ellerini Ve diyalektiği  En iyi o biliyor berivan Sen çoktan yatmış uyumuşsundur belki Bel...', ARRAY['Türk Edebiyatı','Şiir','Şair Ysl']::text[], 8.5, '{"poet":"Şair Ysl","poet_slug":"sair-ysl","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/berivan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilit', 'kilit-i-hsan-uncuoglu-yg2h5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kilit 

Açılmaz 

Bu Kilit 

Dili yok 

Düz git, 

KILIT NERDE 

Göz üstünde kaşını gör ince Yay gibi 

Ay oturmuş ayna denizde göğe bakarken 

Meleklerin var defter tutar iki taraf omuzda 

Yakın dostun onlar uzaklardan daha uzakta, 

*** 

Akılda bilgi çok ağızlarda beş vakit niyaz 

Hayatta vallahi payandasız ayakta kalınmaz 

Çevre'' de dolu dolu kalemler tüketmiş melekler 

Günahı sevabı bir dilden seçer İnsandan haber bekler, 

*** 

Herbirinin yazdığı gizli dilleriyse kilitli Farisi Arabi 

Tanrının melekleri aklıma yakın Türk''çe bilmezler 

Zararları günah fayda''ları sevap derler es geçerler 

Günahı sevabı bir dilden seçer İnsandan haber bekler,', 'Kilit  Açılmaz  Bu Kilit  Dili yok  Düz git,  KILIT NERDE  Göz üstünde kaşını gör ince Yay gibi  Ay oturmuş ayna denizde göğe bakarken  Mele...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kilit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-umit-polat-1sbbr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kara gözlerin sıcak bakışlarında

bana bir hayat sunar

ben onu yaşayamam

mecalsizim...

yüreğimi gönlünde unuttum diye kızma! 

iradesizim...

olur ki

birgün omuzunda ağlarken

seni sevdiğimi, sensiz edemediğimi söylersem şaşırma! 

çünkü

kimsesizim...', 'kara gözlerin sıcak bakışlarında bana bir hayat sunar ben onu yaşayamam mecalsizim... yüreğimi gönlünde unuttum diye kızma!  iradesizim... o...', ARRAY['Türk Edebiyatı','Şiir','Ümit Polat']::text[], 8.5, '{"poet":"Ümit Polat","poet_slug":"umit-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzay Çağı', 'uzay-cagi-i-hsan-uncuoglu-9bltb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzay Çağı 

Nerden nere çıktı yeni yol açıldı adı uzay 

Tavandan gökten düşer gibi bir de çağı 

O Doğru bu doğru derken 

Düz yerde takılmış doğruyu bulamamış 

İnsanoğlu zamanda mekanda 

Kıblede kendini yerini bile şaşırmış, 

*** 

Beraber uzaya gel be hoca 

Neylen çıkarız o yukarlara 

Kaç Tarihten bu yana belli 

Özde sözde yazılan kelamda 

Sen önde oldun ben arkanda, 

*** 

Neler duyduk çeşit neler andık 

Haşa gerçekleri saptırdık çarpıttık 

Binçeşit zamanda doğru''yu anlamadık 

Sağduyudan yoksun peşin talkınınla 

Her zaman seni örnek aldık en başta, 

*** 

Fakirin fikri sözü bir anla hoca 

Davran kalk ayağa canla başla 

Milletine çalış ki lafta kalma 

Göster görelim faydalı ne olursa 

Bir ürünün olsun uyar gitsin uzaya, 

*** 

Değişmez aradığım hesap fizik kimyada 

İnan imanım şaşmaz Tanrı yolunda 

Cebimden çıkartırım iste benden on hoca 

Pek üstün mubarekler her mahalde evvel Allah! , 

*** 

Çok dünyada yok eşi 

Doğrusu binlerden biri 

Bana çoğ alemi öğretti 

Göğe yakın olan bir kişi 

Tek Veli O Dedem Bektaşi, 

** 

Hahamı papası hepsi hacısı hocası 

Dur otur kim var bu dünyada namlı 

Cennet rüyalı cehennem ateş yanlı 

Sırat köprüsüne gitmeden uzaktan 

Tutup turistik Mekke Kudüs yollarını 

Gün be gün kime anlatır satır satır 

Çook Musa'' İsa'' Adem ile Havva''yı, 

** 

Evreni hesapla fizikten kimyadan 

Anca belki bellenir O yüce yaratan 

Yer göğ alemler görünse yakından 

Siyasette çık her vakit huzurdasın 

Hizmetler lafta yürür gider yolunda 

Konyalı durmaz partici büyük hoca 

Bir külahla geçer Molekülden Atoma, 

*** 

Gide gide geldik bu genom çağında 

Okuyup üfleyip Füze atılıyor havaya 

İnsanoğlu nasıl çıktı gökteki uzaya 

Bilimi uyguladı biri git gel yol yaptı 

Papaz kalktı bu yola pas pas attı 

Bizim Hoca hala nerde yaya kaldı 

Aklı gökte fikri yerde zikri hep yeraltı, 

*** 

Oy! be ermişim Arif''im diyen 

Dara düşünce aklına Allah gelen 

Yaradana içimden yanan benim ben! 

Beni kınamayın göz ucu sözinen 

Allah yoluna budur bağım bilimden 

Yaratan o dilimden anlar o bilir 

Bilgimi gönül kalbimi derininden, 

*** 

Bilim hep önde şaha kalkmış alemde 

Yücelerin yücesi inandığım O Allahımı 

Ne bir kimse anlattı yahut nede bir Hacı 

Gidiyor akan zaman artık geldi uzay çağı 

Evrensel bilimden bilgilerle bilinir Tanrı 

Tanrı ile aramızda peygamberler baş tacı 

Arada ne varsa gayrı hepsi bana yabancı,', 'Uzay Çağı  Nerden nere çıktı yeni yol açıldı adı uzay  Tavandan gökten düşer gibi bir de çağı  O Doğru bu doğru derken  Düz yerde takılmış d...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/uzay-cagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Gülüm Nah Gülüm', 'al-gulum-nah-gulum-i-hsan-uncuoglu-nhx8h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Al Gülüm Nah Gülüm 

Al Gülüm Nah Gülüm 

Euro aldatır püsküllüm 

Karışıkpulos yuhalos 

Poyrazos Lodos 

Yunan los Turka los 

* 

Akdeniz egede Yunan yanlı ol 

Türk''ün hakkından Papaz gelir 

Sakın ona göz açtırma hep asıl 

Gel Euro bu çözüme sende katıl, 

** 

Kör aynada yüzünü görse açıkça 

Kargalar''bile güler böyle adama 

İyi İnsan olmaya yetmez bir akılla 

Atalarıymış hain Yunan yanında 

Amerika Avrupa yeralınca uçtan uca 

Politika hızla dönüyor katıksız hoşafa. 

*** 

Batı Trakya Adalar Girit eskidi Yani''ye gitti 

Doğu ile savaşıyor şimdi Taze Papa hazretleri, 

*** 

Hazanda kazan sivri sinekten yağ işte moda 

Hizmet aşkı kimlerden hangi elden bum''ola 

Avrupa Helenika ağzından ne azgın yazgılarla 

Politika hızla dönüyor tatsız tuzsuz bir hoşafa. 

*** 

Verheugen hödük zaten 

Diyor ki zır deli aklınca 

Zafer ne saçta ne ağızda 

Çocuk kandır boş kağıtla 

Koş Annan''da dolu harita 

Sıra bu euro''yla Yunan''lıda 

Son el! , 

al Kıbrısı ver Papaza, 

Has...ulan sen kim oluyorsun 

Elimde Ful As üstüne basa basa,', 'Al Gülüm Nah Gülüm  Al Gülüm Nah Gülüm  Euro aldatır püsküllüm  Karışıkpulos yuhalos  Poyrazos Lodos  Yunan los Turka los  *  Akdeniz egede ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/al-gulum-nah-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pençagon', 'pencagon-i-hsan-uncuoglu-8n3ap', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pençagon 

Pençagon 

Sırtıma kon, 

Şak şak şak eski yeni sana ne 

Haydi konuşma bana fazla git işine 

Burda harfe tarif boş Hasan 

Dert etme üzülme iyi bak kendine 

Var''a yok''a inan ne gelirse önüne 

Hasan okumuş okumamış çok kabak 

Böylesi hayat rahat yaşamana bak, 

*** 

Her Allahın günü bir sebep 

Bak bak nerden neden bu şiddet 

Felek şimdi sende gelme üstüme 

Dünya değişirmiş sana ne 

Sana giren çıkan mı var 

Yoksa bana da mı bir kısmet şak şaak 

Havadan şaak yerden yere seril yat 

Sırtımda şaklıyor cehaletten bir kırbaç,', 'Pençagon  Pençagon  Sırtıma kon,  Şak şak şak eski yeni sana ne  Haydi konuşma bana fazla git işine  Burda harfe tarif boş Hasan  Dert etme ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/pencagon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-gulay-yildiz-0t790', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Limoni bir yaşamdayım

Ekşi bir tat var hayatımda

Zamansız kayıpların üzüntüsü

Apansız gelişlerin sevinci

Mevsim değişimlerindeki yabanilik gibi

Tuhaf gel-gitlerde, hüzünlü bir bekleyişteyim', 'Limoni bir yaşamdayım Ekşi bir tat var hayatımda Zamansız kayıpların üzüntüsü Apansız gelişlerin sevinci Mevsim değişimlerindeki yabanilik g...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bekleyis-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muzuruma', 'muzuruma-i-brahim-saritas-fbl5c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sana karışan sellerin damlaları peşinde koşarken

Ey deniz uzatma yolumu benim

günahıma bakma kusuruma bakma

aç bana fedakarlık pencereni

ve bekleme benden içimden gelmeyeni

dalgalarında boğ

kumlarında savur

ama..

hasret koyma suyuna, tuzuna, sıcağına..

hasret koyma CANIM...

(İBOMCAN)', 'Ben sana karışan sellerin damlaları peşinde koşarken Ey deniz uzatma yolumu benim günahıma bakma kusuruma bakma aç bana fedakarlık pencereni...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıtaş']::text[], 8.5, '{"poet":"İbrahim Sarıtaş","poet_slug":"i-brahim-saritas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/muzuruma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyom ki', 'diyom-ki-i-hsan-uncuoglu-ldjbn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diyom ki 

Poligami monogami 

Çatlatma şimdi beni 

Kırarım dişimi 

Neyle olur bir sevgi 

Allahın bildiği 

Gerçeğin kendisi, 

Hiiç aldırış etme sakın 

Ya aşağı ya yukardasın 

Keyf bum! mu nasılsın 

Taş Plakta sözlere 

Kanmayın erkeklere, 

Göbekler yaşlar artar 

Farkına varmadan ileriye 

Kafalar değişir her sene 

Kimi 00 da çıkar sefere 

Ya tatsız tuzsuz olurlar 

Ya bay endişe, 

Yaşlının unutkanı çekilmez 

Taşa çal peşpeşe yaramaz 

Yarayan olursa döner 

Döner el öper öper de 

Olur olmaz yerde o ne 

Döper Senyor Ömer,', 'Diyom ki  Poligami monogami  Çatlatma şimdi beni  Kırarım dişimi  Neyle olur bir sevgi  Allahın bildiği  Gerçeğin kendisi,  Hiiç aldırış etm...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/diyom-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdikut', 'i-dikut-i-hsan-uncuoglu-am0sk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İdikut 

Tanrı''dan 

Hediye 

Alem bize 

Biz aleme 

Kalan Yadigar 

Ölünceye kadar, 

Sevilenle tarifsiz tatlı sohbetler 

Hoş beş gözlerde muhabbetler 

Akar suda salla pupa yelkenli 

Görüşümüz güzellerle güllenir 

Kıymetli kelam ile diller dökeriz 

Deniz Derya''da Gök''te uçar gezer 

Bulutları gözleriz yağmur bekleriz,', 'İdikut  Tanrı''dan  Hediye  Alem bize  Biz aleme  Kalan Yadigar  Ölünceye kadar,  Sevilenle tarifsiz tatlı sohbetler  Hoş beş gözlerde muhabb...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/idikut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Külaha Rağbet,', 'eski-kulaha-ragbet-i-hsan-uncuoglu-d6ase', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski Külaha Rağbet, 

Çok hörgüçlü''ye rağbet 

Devenin uzun boynu tek 

Yeni eskiliğe gizli rekabet, 

Rüyada memleketin birinde 

Havadan sudan haksız yoldan 

Bazen boğazdan mideye akar 

Altın para başa kadar dolar taşar, 

** 

Birisi sırada başı kaymış şaşmış 

Aklınca boyun atkısın kıravat sanmış 

Kimi derin okur sinekle kelebek arar 

Dolaşır boş ayağ havluyla takla atar, 

** 

Nerde vefa fedakarlık şefkat sadakat merhamet 

Köyde ahırla tarladan geçim fakirlikte keramet 

İnsaf vicdan erdem ar haya bir ayar birde onur 

Yoksa öküzbaş resmine boyun koysak Deve mi olur. 

** 

Önce akılsız başla yolun Selamet 

Sonra yerli Fazilet Servet Saadet 

Yüce Allahtan ilahi emanet bu inayet 

Fazla ağır sağıra düdük öttürmek gerek, 

** 

Okuyup üfleme ekmek teknesi desek 

İşler kolay yürür ondan bundan destek 

Sırma saçlar bele kadar bir gizli dilek 

Sebep çirkinliği örter güzelliğe işaret, 

** 

Yağlı yemekli salonda hanımlar uçar 

İki renk ümitle dolu balonlar patlar 

Kimine rozetli davet kimine pas geç 

Sırada şanı adı büyük kim bu Mehmet, 

** 

Selamet inanç merkezinden kumandalı 

Bekle köşede çıkar mucize bir siyaset 

Emanete bir hazır Nazır! işte bereket 

N''olur ya Saadete selam et ya etme! rezalet,', 'Eski Külaha Rağbet,  Çok hörgüçlü''ye rağbet  Devenin uzun boynu tek  Yeni eskiliğe gizli rekabet,  Rüyada memleketin birinde  Havadan sudan ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/eski-kulaha-ragbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ritimsiz Kalp', 'ritimsiz-kalp-gulay-yildiz-31axr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakıştırma doğaya, düşünme olmaz diye

Kalbimin ritmi yok artık

Ani gidiş gelişlerde sadece aşkımız gibi

Bir yürek hayal et,  ürkek bir kuş olsun

Bedeninin en hassas noktasından

Yüreğinden asılmış bir kuş gibi asın

Yaşamım sona erecekse...

Ve yıldızların türküsünü susturun

Hayata küsüceksem', 'Yakıştırma doğaya, düşünme olmaz diye Kalbimin ritmi yok artık Ani gidiş gelişlerde sadece aşkımız gibi Bir yürek hayal et,  ürkek bir kuş o...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ritimsiz-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıral Midas''ın Kulakları', 'kiral-midas-in-kulaklari-i-hsan-uncuoglu-s4yse', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıral Midas''ın Kulakları 

Kulakların çınlasın 

Ne derdin Kıral Midas 

Huzurunda Türban Tas, 

Korunma için nedir seçilen 

Bir cins araçtır başa örtülen 

Türban olursa hep bir örnek 

Bu yol halin içyüzü ne demek, 

*** 

Ağır doğa şartlarına karşı haklı 

Güven içgüdüsü ile bizim Hacı 

Bacı''mız kendini korumağa çalışır 

Ne üstüne neyi örteceğini karıştırır, 

*** 

Saçın üstü bir örnek türban kanatlı 

Kafanın içi güzel değil dıştan havalı 

Her kadının herbiri kendince Sultan 

Milletine nasıl katkı olur akıl dışından, 

*** 

İçi şeytan dışı destan hayal kadın 

Kendini güvenle korumağa çalışır 

Erkeklere karşın duyarlı o her zaman 

Bulduğu en kolay ucuz araçtır türban, 

*** 

Her hanım süslenir bir takı takar 

Eski yeni tarih geçer bizden çıkar 

Sultan Süleymanla Türban''lı İktidar 

Haremden tut Hürrem Sultan''a kadar, 

*** 

Paraları bas yeterse ayarlı tarafa 

Gönülden sarıl şal türbanlı kadına 

İpekten kelebek o sanki gül gonca 

O mubarek destektir her yaşta başta, 

*** 

Meslek lise mektepli o kadar kıymetli ki 

Baştan başa türbanlı din yolunda herbiri 

Kız erkek eşsiz meslek ayni inancın elçileri 

Şu Cumhuriyet Demokrasi korur temiz yürekleri, 

*** 

Milli görüşleri onca ünlü hele fikirleri dilleri 

Atatürk''e sonsuz saygıyla Aziz Vatan sevgisi 

İlahi Allahüekber azizler yolunda savaş neyki 

Ön safta sıra sıra birlikleri bildik melek cephesi, 

*** 

Çeşit halde çıplak oymuşlar ak mermer taşı 

Üstte yedi katlı gökten inmiş çeşit ay parçası 

Güzel baş saç kıvrım kıvrım kaşı gözü hayal 

Taş bedene akıl konmaz ki altı şiş üstü kaval, 

*** 

Eteğ başın saçına zilli çanlı küpe takılsa 

Başta türbana azgelir kaç düzine renk varsa 

Anya manya oynanır ya bir arkadaş arkadaşla 

İnanca kimse karışamaz şu türban bir konuşsa, 

*** 

Vız gelir süsüne o tiz düdüğe aldırma! 

Onlar değişmemiş eskiden beri et kafa 

Sen değiştin hizmetin tam olsun türbana 

Kurban olduğum aynalar diyor kal iktidarda, 

*** 

Kaç inanç dünyada azmı başkan dense ona 

Türbanlı kahramanlar rüya sanki yanlarında 

Canlı hayal ilham bizde halvet ol en başta 

Tasavvur düşünce çok fikirler doğar sonunda, 

*** 

Kimin inancı hakları nere dayanır ayarlanır 

Kurallar kim elinde okunur neye savsaklanır 

Herşeyin sonu doğruysa gün gibi açık ortada 

İnanç parayla düzmece ayarlı sözde hepal burda, 

*** 

Din sömürgeni çeşit çeşit uyutur uyuşturur 

Uyarlı kişileri tam zamanda fırsatta koşturur 

Her kartta bir numara inançlar çıkartır pazara 

Tüccar alkışlar coşar türban satış çarşısında, 

*** 

Namus böyle korunur türban ört başına 

Tv''ler de meydanlarda her fırsat oldukça 

Dinle halk çoşkulu kolay bu yarış ortalıkta 

Dolanbaçlı hayal konuş alkış topla kal orda, 

*** 

Aydınlıkta bakar görmezlere palavra at her nutukta 

Nedenir arkadan adı güzel olsun şey çıkarsa bahtına 

Doğrusu bu haktır diye bir umut karışık şey değerli 

Uçar marka turbanlı bu kumpanya yeminli dönmez geri! ,', 'Kıral Midas''ın Kulakları  Kulakların çınlasın  Ne derdin Kıral Midas  Huzurunda Türban Tas,  Korunma için nedir seçilen  Bir cins araçtır ba...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/kiral-midas-in-kulaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Yollardayım', 'yarim-kalan-yollardayim-gulay-yildiz-vdqq9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dipsiz kuyuların karanlığında

Yürek acı çeker, gözler hep yolda

Güneşim olup doğ yeni günüme

Yolları bitir gel, sevineyim diye

Ansızın, ansızın açılan kapıdayım

Cevapsız, cevapsız çağrılardayım

Aklım bir sende bir bende

Yarım, yarım kalan yollardayım.', 'Dipsiz kuyuların karanlığında Yürek acı çeker, gözler hep yolda Güneşim olup doğ yeni günüme Yolları bitir gel, sevineyim diye Ansızın, ansı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-kalan-yollardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Siyaset', 'ben-siyaset-i-hsan-uncuoglu-4vwhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben Siyaset 

Öperim seni 

Satır satır 

Sözde durmam 

Oyun satarım 

Göbek atarım, 

Uykudan uyanmazsan 

Oyuna katılmazsan 

Vaz geçilmez asla 

Kıvırcık postundan, 

İçimizden binde biri 

Sevgi dokur temelli 

Sevgilim bunu unutma 

Dar zamanda beni hatırla, 

Beni iyi dinleyin bana çok iyi bakıM yapın 

Yolumdan asla gitmeyin dediğimden sapmayın 

Şimdi Siyasettir adım çoğunuzdan akıllıyım 

Bu siyaset meydanında gözlerimi dört açtım 

Yaş gelsede yüz doksana gidiyorum adım adım, 

*** 

Yoluna baş koydum aziz taraftara hayranım 

Böyledir siyaset alnın karışlarım aslanım 

Usanmadan birer ikişer her ferdine anlatın 

Açıkça şunu ifade etmek istiyorum kiii,neyi 

Siyasettir açık adım bana inanmayın dememki, 

*** 

Siyasette birinci adım hizmetim baş tacım 

Gece gündüz etraf görmez koşanlara yanarım 

Lugatta sorumluluk yok görev kalsın ortada 

Küçük bir kıymık istedim gel dendi sofraya 

Ebediyyen minnettarım verenin tatlı parasına, 

*** 

Eğrileri doğru yapamazsan siyasete soyunma 

Al eline kağıt kalem ne var ne yok sonuçta 

Kim sana ne verdi ne aldı ince ince hesapla 

Bugün git yarın gel kolay bir tezgah adamına 

Canım feda vatanıma kim nasıl niçin meydanda, 

*** 

Çivi çakamaz işçisile sendika çıkar çarşılara 

Aklın yolu hep bir imiş zengin yaşar nasıl olsa 

Fakir çoğu yüksek tahsil aylak işte şurda burda 

Köyde erkeklere kahve bolca kadınlara ahır tarla 

Çok çalışkan bu ülkede millet gece gündüz ayakta, 

*** 

Çarşaf çarşaf gazetede yaz kim önde kim sonda 

Siyaset yutulurmu olmuş armut gibi çarşı sokakta 

Ne gam çok acı kazık yedik taşlı hayat yollarında 

Günüme gün demem boşa gümlemeden meydanlarda 

Bana kurbandır Kırk Haramiler uyur yüzüme baka baka, 

*** 

Açıl susam açıl açıldım gül diken oldum düşe kalka 

Din iman imamda ileri dokunma sende bende yok fazla 

Siyaset-ül-vaziyet çal çalpara gülüm sensin en başta 

Garibandan trilyonla zengin ol Ahh! Allah gözün doyura 

Üstüne iste herşey yakışıyor yasana! ,''hani ya! kime Fatiha,', 'Ben Siyaset  Öperim seni  Satır satır  Sözde durmam  Oyun satarım  Göbek atarım,  Uykudan uyanmazsan  Oyuna katılmazsan  Vaz geçilmez asla  ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ben-siyaset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetmek', 'kaybetmek-kader-budur-fyigw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybetmek bazen kanun gibidir

Yazılmış sanırsın

Bu karamsar oyundan kurtulamazsın

Kaybetmek bazen ümit gibidir

İnişler çıkışlar gibi yüreğinde taşırsın

Ve kazanmak için bir adım gibidir

Her an onun için çabalarsın', 'Kaybetmek bazen kanun gibidir Yazılmış sanırsın Bu karamsar oyundan kurtulamazsın Kaybetmek bazen ümit gibidir İnişler çıkışlar gibi yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kaybetmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-gulay-yildiz-jfzi5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ince çizgi gibi yaşam

Ucu yok, başınıysa hatırlamıyorum

Bir an gibi mutluluk, gerisi hüzün

Bir çiçek gibi incecik bir dalda

Kendine bile ağır, her rüzgarda eğilir

Gönlümde bir ışık var derinlerde

Uzansan ulaşacağım seninle...', 'Bir ince çizgi gibi yaşam Ucu yok, başınıysa hatırlamıyorum Bir an gibi mutluluk, gerisi hüzün Bir çiçek gibi incecik bir dalda Kendine bile...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasam-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık', 'yanlizlik-kader-budur-2bu3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanlızlık kendinle arkadaş olmaktır

Dertlerinle tek başına savaşmaktır

Belki bir dost gibi değil aşağılıktır

Çünkü gerçek insanı acıtır

Çünkü insanın kendine hatalarını hatırlatmasıdır

Yanlızlık

Yüreğinin bunları inkar edip savaşmasıdır', 'Yanlızlık kendinle arkadaş olmaktır Dertlerinle tek başına savaşmaktır Belki bir dost gibi değil aşağılıktır Çünkü gerçek insanı acıtır Çünk...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yanlizlik-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-kader-budur-xeqcr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırak bu gece

Diller sussun

Dudaklar konuşmasın

Gözler ise

Bu gece hiç

Utanmasın', 'Bırak bu gece Diller sussun Dudaklar konuşmasın Gözler ise Bu gece hiç Utanmasın...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/birak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk 2', 'ask-2-kader-budur-46i9r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir uçurum bu

Dipsiz sinsi karanlık

Zamansız kavramsız

Ölümde ve ölümsüzlükte

Düşlerde ve kabuslarda

Ağıtlarda dolu anıtlarla süslü

Hüzünlerle evli acılarla sonu

Bin cevap beklersin

Alamazsın birinin cevabını

Bu öyle bir şeyki

Yoktur tarifi nede izahı

Sadece yakar içine yer edeni', 'Bir uçurum bu Dipsiz sinsi karanlık Zamansız kavramsız Ölümde ve ölümsüzlükte Düşlerde ve kabuslarda Ağıtlarda dolu anıtlarla süslü Hüzünler...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-kader-budur-mxe5r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizliktir benim anlamsızlığım

Bilirmisin nasıl olur günlerim gecelerim

Sensizlik bazen bir volkandır

İçimde patlar ve dökülür kinim

Sensizlik boş evde yankılan sesimdir

Bağırırım avazım çıktığı kadar sana

Çarpar durur bu tis sesim duvarlara

Derken yansır bir ayanadan tekrar bana

Sensizlik bomboş bir tualdir

Çizemem ne kadar kötü olduğunu insanlara

Yarınlarım yoktur  hayal kuramam

Düşünüp taşınsamda sensizliğin resmini yapamam

Sensizlik bir kanyondur

Bakarsın tepesinden boşluğa

Okadar yüksektirki atlayamazsın

Ne içine düşer

Nede kendini kurtarırsın', 'Sensizliktir benim anlamsızlığım Bilirmisin nasıl olur günlerim gecelerim Sensizlik bazen bir volkandır İçimde patlar ve dökülür kinim Sensi...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizlik-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermanım', 'dermanim-kader-budur-4x95t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek derdim seb oldun yüreğime

Ağrısı yok acısı var içimde

Sevgisi var seveni yok üzülsemde

Dermanında sensin bu kederli gecelerime

Karanlık bastımı umutlarım silinir seninle

Bir gece daha boğuşacağım hasretinle

Ve bir sabah cesedim bulunacak pencerenin önünde

Dermanımda sen olacaksın ecelime bile

Bir gün silineceğim bu anlamsız sevgiyle

Düşünüp bilemeyeceksin bu kadar sevgi niye

Hani yazdım seni kaderime

Olmadın çözümüm olmadın dermanım bile

Merak etme gerçeklerde düşler gibi yok olur bilinmezde

Hatıralar kalmaz bir içimlik çay sohbetine

Acımaz yüreğin benim elemlerime

Boş ver dermanlar olsun senin üstüne

İhtiyacın olacak beddualarım senin yüreğine', 'Tek derdim seb oldun yüreğime Ağrısı yok acısı var içimde Sevgisi var seveni yok üzülsemde Dermanında sensin bu kederli gecelerime Karanlık ...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dermanim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her gece birisiyle belki', 'her-gece-birisiyle-belki-kader-budur-18ayv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece yanlızım boş odamda aslında

Belki görünen birisi var yanımda

Gülüyor yüzüme öpüyor dudaklarımdam

Ama o değil izleriyle kalbimdeki

Yatağımda uyuyan o ama o değil gözlerimdeki

Sen diye sevişiyorum

Her gece birisiyle belki

İşte aslında yanlızım herkezle

Yanlızım bu boş gecelerde

Sadece tatmin ediyorum duygularımı

Kendimi kandırıyorum belki

Sen diye sarılıyorum yüreklere

Belki her canlıya seni anlatıyorum

Seni yaşıyorum gecelerimde

Sen diye sevişiyorum

Her gece birisiyle belki

Tadını almak istiyorum ellerden

Selamsız sabahsız gönüllerden

Ne adları benziyor ne saltanatları

Sen yoksun yok olan bir düşşün belki

Yada senler gizlidir bende

Bilemezler gecelerimdeki şiirleri

Ama sen diye sevişeceğim

Her gece birisiyle belki', 'Bu gece yanlızım boş odamda aslında Belki görünen birisi var yanımda Gülüyor yüzüme öpüyor dudaklarımdam Ama o değil izleriyle kalbimdeki Ya...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/her-gece-birisiyle-belki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köprüye dair - I - II', 'kopruye-dair-i-ii-bekir-necati-drqav', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Köprüye dair - I

Bu köprü

      durdukça böyle

Deniz bu

       ayıp dinler mi

Kayar gider 

       bacakları arasından

Köprüye dair - II

Söylediğim gibi

Deniz bu

Ayıp dinler mi

Bir de

Kuma getirdi

İlkinin üzerine', 'Köprüye dair - I Bu köprü       durdukça böyle Deniz bu        ayıp dinler mi Kayar gider         bacakları arasından Köprüye dair - II Söyl...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kopruye-dair-i-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımıza Esirim', 'askimiza-esirim-erhan-saka-lfbg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz bir gün gülmedim,

Acılara esirim,

Eller gibi sevmedim,

Yalnızlığa esirim.

Neden girdin dünyama,

Renkler kattın rüyama,

Sakın beni kınama,

Kabuslara esirim.

Sanki dünya dört duvar,

Benim gönlüm sonbahar,

Aşkımıza yağdı kar,

Yokluğuna esirim.

Tükendi bak umutlar,

Yağmur yüklü bulutlar,

Bir, bir söndü ışıklar,

Gecelere esirim.

Sözüm geçmez kalbime,

Bu gidişin, naz kime,

Beni sevmedi deme,

Aşkımıza esirim.

25-10-2003', 'Sensiz bir gün gülmedim, Acılara esirim, Eller gibi sevmedim, Yalnızlığa esirim. Neden girdin dünyama, Renkler kattın rüyama, Sakın beni kın...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askimiza-esirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller Gibiyim', 'eller-gibiyim-erhan-saka-ghc80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yangın sarmışken dört bir yanımı,

Yağmura susamış çöller gibiyim,

Kalpsizin birisi sıkar canımı,

Duygudan çağlayan seller gibiyim.

İstemem yanıma kimse gelmesin,

İstemem yoluma halı sermesin,

O zalim kalbini bana vermesin,

Kendimi unuttum eller gibiyim.

Bari inkar etme yaşananları,

Rüzgarla savurdun son umutları,

Bu kalbim unutmaz unutanları,

İhanet hançeri yemiş gibiyim.

Bir gün gideceğim sessiz sedasız,

Sırlara mekanım aşksız sevdasız,

Sözünde durmadın gittin zamansız,

Baharda kuruyan güller gibiyim.

21-10-2003', 'Bir yangın sarmışken dört bir yanımı, Yağmura susamış çöller gibiyim, Kalpsizin birisi sıkar canımı, Duygudan çağlayan seller gibiyim. İstem...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eller-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öl Desem', 'ol-desem-erhan-saka-colgr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı aldanışım

Aşktan yana bilir misin,

Bu kaçıncı yalvarışım,

Gel desem gelir misin.

Adın çıkmaz aklımdan,

Ümidim yok yarından,

Benim için canından,

Ver desem verir misin.

“Etme bulma dünyası”

Aşkımızın rüyası,

Bana son hatırası,

Ol desem olur musun.

Kaybetmişken kendimi,

Kırmışken kalemimi,

Şu virane halimi,

Gör desem görür müsün.

Sevin demiş yaradan,

Vazgeçemem sevdadan,

Aşkım için aşkından,

Öl desem ölür müsün.

25-10-2003', 'Bu kaçıncı aldanışım Aşktan yana bilir misin, Bu kaçıncı yalvarışım, Gel desem gelir misin. Adın çıkmaz aklımdan, Ümidim yok yarından, Benim...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ol-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlüm', 'yagmur-gozlum-erhan-saka-u5stj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninleyim sana geldim,

Aç kapını yağmur gözlüm,

Seni sevdim seni bildim,

İnan bana yağmur gözlüm.

Zaman bizi ayırmadan,

Dost düşmanı kayırmadan,

Kalan günler sayılmadan,

Kavuşalım yağmur gözlüm.

Karlar yağar kapımıza,

Bakmayalım ardımıza,

Engel koyma yolumuza,

Yürüyelim yağmur gözlüm.

Güneş bizim ay bizim,

Gece bizim gün bizim,

Şiir bizim söz bizim,

Söyleyelim yağmur gözlüm.

Ömür kısa bir heves,

Sensiz dünya bir kafes,

Bir bedende bir nefes,

Yaşayalım yağmur gözlüm.

27-10-2003', 'Seninleyim sana geldim, Aç kapını yağmur gözlüm, Seni sevdim seni bildim, İnan bana yağmur gözlüm. Zaman bizi ayırmadan, Dost düşmanı kayırm...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yagmur-gozlum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-erhan-saka-negiv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sahildeyim bu akşam, sensiz ve yalnızım,

Bir hüzün bulutu çöktü üstüme,

Sevmedin beni, yaşıyorum ve sensizim,

Ben yine mutsuz, yine umutsuzum.

Sana inat dalgalar, mutluluktan coşuyor,

Sevgisini haykırıp sahille paylaşıyor,

Anlatması imkansız dertlerim yarışıyor,

Soruyorum kendime neden sensiz olmuyor.

Kaçıyorum ben senden, kaçıyorum kendimden,

Belki de korkuyorum, seviyorum demekten,

Denizlerde usandı, arkadaşlık etmekten,

Her şey yalanmış, yalnızım ben gerçekten.

Ayrılık şarkıları söyleniyor kumsalda,

Dermansız bir yara bırakıyor insanda,

Görülmemiş yalanlar söyleniyor dünyada,

Mutluluk hayal oldu, yalnızım ben şu anda...', 'Sahildeyim bu akşam, sensiz ve yalnızım, Bir hüzün bulutu çöktü üstüme, Sevmedin beni, yaşıyorum ve sensizim, Ben yine mutsuz, yine umutsuzu...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizim-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-erhan-saka-5ttvz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerime bakıp mutlu sanmayın,

Sanki yıllar omuzum da yorgunum,

Gülen yüze tatlı söze kanmayın,

Dertlerimi gizlemekten yorgunum.

Neler çektim hayat denilen yolda,

Koşuyorum amaçsız bir kulvarda,

Kendimi ararım meçhul diyarda,

Yaşadığım sevdalardan yorgunum

Geçmişi anarken yüreğim yanar,

Bir yaram var iyileşmez hep kanar,

Bende sevmek bende gülmek ne arar,

İsyanımdan susuyorum yorgunum.

Aşktan yana bir gün yüzüm gülmedi,

Yüreğimde fırtınalar dinmedi,

Hayat bana bir şans daha vermedi,

Gidiyorum buralardan yorgunum.', 'Gözlerime bakıp mutlu sanmayın, Sanki yıllar omuzum da yorgunum, Gülen yüze tatlı söze kanmayın, Dertlerimi gizlemekten yorgunum. Neler çekt...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yorgunum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Caddeler', 'bu-caddeler-yasin-kandemir-4pbz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün bu caddelerden

Taksiler,dolmuşlar geçecek

Belki bir otobüs,bir kamyon

Ve o gün bekleyeceğim,sen geçmeyeceksin

Her bahar yürüdüğümüz yollara bakacağım; 

Öğrenciler geçecek,memurlar geçecek,

Belki eski bir tanıdık

Ve yine sen geçmeyeceksin

Yıllar sonra belki birgün

Sen geçeceksin bu caddelerden

İnsanlar pencerelerde sesler kesilecek

Ve korkuyorum,o gün gelmeyecek

Adını yazmayı deneyeceğim

Saçların gelecek,gözlerin gelecek aklıma

Hatırlar gibi olacağım dilimin ucunda

Ve korkuyorum adın aklıma gelmeyecek', 'Birgün bu caddelerden Taksiler,dolmuşlar geçecek Belki bir otobüs,bir kamyon Ve o gün bekleyeceğim,sen geçmeyeceksin Her bahar yürüdüğümüz y...', ARRAY['Türk Edebiyatı','Şiir','Yasin Kandemir']::text[], 8.5, '{"poet":"Yasin Kandemir","poet_slug":"yasin-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-caddeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğilirken Dudaklarının Hakimiyetine', 'egilirken-dudaklarinin-hakimiyetine-umut-ulbegi-0ssrp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah

ve 

her gece

deniz üstü geçişlerde

seni düşünürüm.

Sadece sevenlerin görebileceği

düşünce balonu çakılmış enseme

takılır köprü ışıklarına

üşürüm.

Her sabah

İki ay ve binbir gece

Hayallerim gözlerinin içinde

adın gibi iki hece

ayları sayalım

Ekim

Kasım

Aralım

içe içe

İç içe geçen halkalar gibi uyuyalım sessizce

kışa inat sonbaharım

gelirsen

en kilitli zamanlarımda bile böyle birden çözülürüm

seninle açtığım kapının eşiğinde

eğilirken dudaklarının hakimiyetine 

büyürüm.

Sensizlikten midir bilmem

Her aklıma gelişinde

deli gömleğimi giyer,

İstanbul''u ağır ağır yürürüm

sadece ölenlerin görebileceği

sonsuzluk yapışır yakama

gerekirse 

ölürüm...', 'Her sabah ve  her gece deniz üstü geçişlerde seni düşünürüm. Sadece sevenlerin görebileceği düşünce balonu çakılmış enseme takılır köprü ışı...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/egilirken-dudaklarinin-hakimiyetine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku Arası', 'uyku-arasi-umut-ulbegi-naf6n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyu bebeğim

sen uyu

gece yanımdan geçiyor

bak

getiriyor sana kokumu

sabahları benimle uyanman için

koklaman için

doya doya 

Seni benim için saklarken

bir gece sonraya.', 'Uyu bebeğim sen uyu gece yanımdan geçiyor bak getiriyor sana kokumu sabahları benimle uyanman için koklaman için doya doya  Seni benim için ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uyku-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne mumkun..', 'ne-mumkun-huseyin-umit-cetin-o58rt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kelimeler aksada altin kalemden

Siirler peyda olsa hattat neviinden

Dokulur mü mısralar kendiliginden

Suzulmese murekkebi yuregimden', 'Kelimeler aksada altin kalemden Siirler peyda olsa hattat neviinden Dokulur mü mısralar kendiliginden Suzulmese murekkebi yuregimden...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-mumkun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korakos Moteli', 'korakos-moteli-sores-welat-demir-tj8lx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi tahta penceremizde bir agir kis

Gecelerden bir gece yorgunuz

Ve tenha sokaklarin soguk kaldirimlari kokuyor odamiz

Sarhosuz

Sevisiyoruz delicesine.

Korakos Motelinde bir kadin

Perdenin arkasinda cilginca dans ediyor

Halinden anlasiliyor üzgün kadin

Agliyor yetmiyor haykiriyor düsünmekli

Camasiri incecik vücudu belli dudaklari neden yasakli

Sesi mezar kaziyor kulaklarimizda

Kadin, yikilmis kadin.

Bir bir isiklar, saat bir, saat iki 

Isiklar sönüyor adamakilli, sokak bos, motel bos

Yürekler kahir dolu, gözlerimiz kavgaci.

Ölüm varsa bize, burasi

Iste burasidir mekanimiz

Korakos motelinde penbe odada

Hemen mavi tahta pencerenin yaninda olsun

Vur simdi kendini aska ve kedere

Vur be bedenli, vur sineye.

Haydi simdi gel

Durma bana gel

Gel, gel gel

Hey ölüm bana bana gel.

Korakos motelinde bir kadin

Tahta penceremizde bir gece

Her gördügümde soyundugum tek ceset

Seninle, seninle sevisiyoruz delicesine.

Ölelim, ölelim, ölelim ve tekrar tekrar ölelim.

Ölümü güzellestirmek icin ölelim.

Sus! 

Söyleme

Kimseler duymasin

Duymasin Korakos''ta öldügümüzü.

Sss! 

Saatler

Saatler geciyor önümüzden habersiz

Tik tak tik tak böyle sahipsiz

Paramparca olmussak eger

Paramparca sözler söyleyelim öyleyse bu vakit.

Durma! 

Kapat kapilari pencereleri

Kimseler girmesin kimseler duymasin

Biz bize bu gece 

Ölelim seviserek Korakos''ta

Dinsin artik bu belirsizligin agrisi. 

Vur simdi kendini aska ve kedere

Vur be fani bedenli vur, vur

Haydi simdi gel

Durma gel bana gel

Gel, gel gel

Hey ismi sende kalsin, sen ölüm bana gel.

Ve sende tat bu sevismenin belirsizligini

Neden sonra anlarsin ölüm ne tatli gelirmis sana

Ve ölümle anlarsin ne hosmus yasamak

Bir gece bir kadinla Korakos Motelinde. 

(Sana Ezgiler adli ezgi günlügünden- 2001)', 'Mavi tahta penceremizde bir agir kis Gecelerden bir gece yorgunuz Ve tenha sokaklarin soguk kaldirimlari kokuyor odamiz Sarhosuz Sevisiyoruz...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/korakos-moteli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesut ile Mesude', 'mesut-ile-mesude-burhan-gumus-svzei', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mesut ile Mesude

Ahh! Mesude

Sen ne iyi bir oyuncusun

Değme artistlere taş çıkartırsın vallahi

Şu polyanacılık oynayışın var ya

Kendimi adam yerine koyup sana kızışımda 

Karşımda asude duruşun var ya 

Hele o müşfik bakışın 

Aydınlık gülüşün 

Hasta olduğumda gizli gizli ağlayışın 

Geceleri sessiz çığlıklar atışın 

Kış boyu battaniyelere sarılıp

Yokluk kokan mutfağımızda gezişin var ya

Kederli resimleri bir bir indirip 

Mutluluk tabloları asışın

Hele “...samanlık seyran  olur” değişin var ya 

Beni haramdan koruyan tenin

Başımı dik gezdirişin var ya 

Eskilere püskülere yeniden can verip

Çocuklarımızı aklayıp paklayıp gezdirişin 

Oturmasını kalkmasını bilişin

Hele hele o zengin duruşun var ya

Mesudem

Can çiçeğim

Garibim

Latif, didar  kadınım

Üzgünüm 

Hakkını helal et 

Ben iyi bir oyuncu değilim.', 'Mesut ile Mesude Ahh! Mesude Sen ne iyi bir oyuncusun Değme artistlere taş çıkartırsın vallahi Şu polyanacılık oynayışın var ya Kendimi adam...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mesut-ile-mesude-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mıh ve Nal', 'mih-ve-nal-i-hsan-uncuoglu-sct44', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mıh ve Nal

Güneş ufuktan yükseliyor şimdi doğar

Gecenin sabahı aydınlık çıkar gün ağar

Zaman durmaz ileri hızla akar yol gider

İhtiyar geri kalır yavaş adımlı kör topal

Duran saat çalmaz ama olursa bir kaval 

Okumaz üretmezden ne mıh olur nede nal, 

***

Recep Şaban Ramazan sonra Bayram

Üretende sofra dolu zengin her akşam 

Alt alta üst üstte olanları toplasan güne

Görünen şu zamanda muhtaç aç tok iç içe

İşte bu alet saat bu akrep ile koşan yelkovan 

Ölüm olmasaydı kim oruç tutardı İnanan arasından,

***

Ne bu bir curcuna mı ortaya çıkan

Evrende eğitimdir sonsuza uzanan

Sayısız göz ardı dil altında saklanan

Önemliden akıllıya kazanç ya aptala ziyan

Tarihte şanıyla anılır Haremde nice Sultan

Doğruda noktayı ileriye noktalardır bağlayan, 

***

Hayat acı tatlı her zaman neye nelere gebe

Bilinmezden yenilik fayda sağlarsa değerlenir 

Bitmez bir savaş verir yaşanan zamanda insan! ,', 'Mıh ve Nal Güneş ufuktan yükseliyor şimdi doğar Gecenin sabahı aydınlık çıkar gün ağar Zaman durmaz ileri hızla akar yol gider İhtiyar geri ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mih-ve-nal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güne Doğmayan Aşklar', 'gune-dogmayan-asklar-muammer-celik-1745m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne aşklar yaşanıyor köşelerde bucaklarda

ne aşklar ölüyor belki de ifade bulmadan

Yada yıldızlara yazılıyor gecelerde

Belki de sevilmeyenin koynunda boğuluyor

Ne aşklar yaşanıyor ıssız duvarlar içinde

Yada güneşlerle yakılıyor gündüzlerde

Belki de sevenin koynunda  ölüyor yaşamadan 

Kürtajla alınıyor belki de

Doğup da adı konmayan aşklar...! 

BirDeli

12.12.2003', 'Ne aşklar yaşanıyor köşelerde bucaklarda ne aşklar ölüyor belki de ifade bulmadan Yada yıldızlara yazılıyor gecelerde Belki de sevilmeyenin ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gune-dogmayan-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostalji Meyhanesi ya da Hayat Güzel Sevince', 'nostalji-meyhanesi-ya-da-hayat-guzel-sevince-sores-welat-demir-opejy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nostalji meyhanesindeyim bu gece

Alkol icmiyorum ne isim var sence

Efkarliyim cal be kemanci etme iskence

Sevecegim elbet bu gece

Meyhaneci meyhaneci koy bir plak 

Askima yaniyorum gönlümün bagi kurak

Kemanci calmiyorsa hersey banami kabak

Öyleyse gidecegim ne isim var benim bu kentte.

Gidiyorum gidiyorum bu gece

Sirlari ardima birakiyorum bu kentte

Ne sirri be arkadas sanki hepsi kara iskence

Gidiyorum yine bu gece.

Gidiyorum her gece

Her gece baska bir kente

Diliyorum gönlümce

Hasretlikten yana kendimce

Hayat güzel sevince,..

(Sana Ezgiler adli ezgi günlügünden, 2001)', 'Nostalji meyhanesindeyim bu gece Alkol icmiyorum ne isim var sence Efkarliyim cal be kemanci etme iskence Sevecegim elbet bu gece Meyhaneci ...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nostalji-meyhanesi-ya-da-hayat-guzel-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-emin-baydil-7r5dy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgilim, ey sevgilim! ..Sakın örtme perdeyi,

Pencereni seyr için bekliyorum geceyi.

Mehtâb olacak diye dudaklar ilk heceyi

Esen yele kaptırıp inledi aşk aşk diye...

Gülme diyor el-âlem, ağlama demekte yâr,

Bülbül hep yas tutsun da böyle mi geçsin bahar? ! ..

Bitmesin mi şu çile, içimdeki ah-u zâr,

Sende mi inanmazsın, sevdaya aşk maşk diye? ..

Sabah oldu yine bak! ..Gün doğmakta içime,

Aldı beni cemâlin soktu başka biçime.

Sendeki bu hal nedir? Sorsam kendi kendime,

Haykırır sanki gönlüm, söyler ki aşk aşk diye...', 'Sevgilim, ey sevgilim! ..Sakın örtme perdeyi, Pencereni seyr için bekliyorum geceyi. Mehtâb olacak diye dudaklar ilk heceyi Esen yele kaptır...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgilim-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta ve Cirak -(11)', 'usta-ve-cirak-11-sores-welat-demir-1dzvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecemde büyük bir yalnizlik

Ve penceremde büyük bir gürültü,

Göcebelerin sesi esrarina gizlenmis rüzgarin icinde

Beni titretiyor bu Haziran rüzgari alelacele,

Kisa bir sürede cocuklugumun berisine birakiyor beni.

Cabuk büyüydü bunun anlami, iyi beslendin mi? 

Gün ve gün, ay ve ay yillar gecmis 

Yasam, bir bilmece ve bir siir

Her  tatli sey kendi özüne öylece dönüsecek; 

Her  yasamin ilk varolusumundaki aciligina yani.

Eger bir ara,

Ama fiziki varolmayan yaranin kabugunu kaldirmak istersen,

Iste o an ögrenecegin bir seyi bulacaksin,

Ki bu yarayi asil sen kendine acmissin.

Ve o an anliyacaksin ki,

Aci, bir usta ve sende onun ciragisin,..

Sonra aglarsin hic kimseye caktirmadan dudaklarinin arkasina sakladigin buruklukla,

O dudaklar ki, ayni anda hem gülüyor hem de konusuyorlarken,

Yalanci! ..

(Sessizligimden Bir Siir Yazdim Senin Icin adli siir kitabindan, 2001)', 'Gecemde büyük bir yalnizlik Ve penceremde büyük bir gürültü, Göcebelerin sesi esrarina gizlenmis rüzgarin icinde Beni titretiyor bu Haziran ...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/usta-ve-cirak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki sen...', 'bendeki-sen-i-brahim-ethem-bingul-28thz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dakika bile,zamanın mı yok

Yoksa,yüreginde beni bitirdın mi,aşkın yok

İşler güçler hepsi bahane,senin kalbinde sevgi yok

Hakkım varmı, ben kim oluyorum

Bir zaman aşkına çıldırdığın adam,şimdi sildin,ben kim oluyorum

Git gitte,dönüşünde olacak mıyım acaba,çok ararsın beni

İyi bilirsin,sensizlik degil,sevgisizlik öldürür beni

Son otuz günden beş eksik günde,bir kere dedinmi bana,EY SEVGİLİ

Diyemezsin,aramadın çünki,ey vicdansız sevgili

Hadi git,gitte,beni bendeki senle,yalnız bırak

O bendeki sen,senden cok farklı seviyor,beni onla başbaşa bırak

Ümit ile ümitsizlik arasında kaldım

Ben kalbimi,bendeki sana bıraktım

Yarınlardan çok şey beklemem,yarının bu gunden farkı yok', 'Bir dakika bile,zamanın mı yok Yoksa,yüreginde beni bitirdın mi,aşkın yok İşler güçler hepsi bahane,senin kalbinde sevgi yok Hakkım varmı, b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bendeki-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Güzel Sokak', 'hayat-guzel-sokak-bekir-mutlu-gokcesu-154wj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yorgun

Gün yorgun

Sabahtan akşama

Çalışmaca, koşmaca

Çoğu zaman

Manasız bir kovalamaca

Değişir senaryo

Saat başında

Büyük gelir bazen

Dünya iki numara 

Ama akşam olup da 

Ben, ben olunca

Sen de sen olunca

Hoşgörü Bayırından aşıp

Hayat Güzel Sokak

Saadet Apartmanı

No:6’da buluşunca

Umurumuzda mı

Dünya kaç numara', 'Ben yorgun Gün yorgun Sabahtan akşama Çalışmaca, koşmaca Çoğu zaman Manasız bir kovalamaca Değişir senaryo Saat başında Büyük gelir bazen Dü...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayat-guzel-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünecekse de Ölmek Ölümü', 'olunecekse-de-olmek-olumu-sores-welat-demir-a9bg3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saclari dal kalin / gözleri kuru yaprak

bir ölümün yolunu soruyordu kadin

beyninde cinnetini

yüreginde demiri közlüyor

		aciyla bogusuyordu

			kömüre dönüsmüs 

				canini yakarak.

sagir yapilarin kör talihsiz / ismi gibi agir

yasli kentin yorgunlugu dizlerinde 

yalnizligina dokansan 

ezgiler yükseliyordu

	sözsüz

		bakireler dergahinda

mevlana serif türbani 

bir daha görmedi avuclarinda 

yüreginde hakki tasiyan sinemleri

ama ben diyordu

yilanin efendisi ejder

görenlere en büyük kizgin demirleri hazirlayan zebaniler:

dolu dolu gölgesiz yalanlari

salyalari yerlerde gezinen ama 

hesap verecegi gün gelince en igrenc korkaklara

dönüsen itleri besledim ellerimde 

susmayin söyleyin

biliyorum

asil güüzel olan

gülün güne acan gülüsünü

bebegin uyanirkenki yumusakligini

bir cocugun seker dolu dünyasini

gencin en büyük hayal kirikliklarini

iscilerin büyük kavgalarini

sütleri ak cumartesi analarini ve 

evlatlarini yalniz birakmayan tüm analari

alinteri emeginin elinden zorla ve sorumsuzca alinan haklarini

...

...

ve savdasina doyamadigim kadini

tanimak gerek 

bir inancta 

ölünecekse de 

	ölmek ölümü,..

swd

(Son Tango & Bir Daha Susma Yüregim adli siir kitabindan, 1999-2002)', 'saclari dal kalin / gözleri kuru yaprak bir ölümün yolunu soruyordu kadin beyninde cinnetini yüreginde demiri közlüyor 		aciyla bogusuyordu ...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/olunecekse-de-olmek-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Dilegim', 'en-buyuk-dilegim-sores-welat-demir-ieywu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyayi ciceklerle donatacagim

Siz tohum olmalisiniz

Büyümeli ve daha büyümelisiniz

Vakti gelip ölürsenizde

Ötekilere gübre olacaksiniz... 

swd

(Son Tango & Bir Daha Susma Yüregim adli siir kitabindan, 1999-2002)', 'Dünyayi ciceklerle donatacagim Siz tohum olmalisiniz Büyümeli ve daha büyümelisiniz Vakti gelip ölürsenizde Ötekilere gübre olacaksiniz...  ...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-buyuk-dilegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüregim Daha Ileri', 'yuregim-daha-ileri-sores-welat-demir-299qd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sirasidir elbet

Sevdayi icinde asi tutmanin

Askina dizgin degmemesi bir daha

Heyecandir 

Coskudur

Emektir

Mücadeledir

Ama daha cok direnis meselesidir

Özgürlüge dogru zafer yürüyüsüdür. 

Yüreklerde besinci mevsim eylüldür

Dinginliktir

Cevherdir

Ama seninle

Sirasiyla dost sirasiyla kardesliktir.

Siir tadinda

Meyva olgunlugunda

Agac gibi tek ve hür 

Orman gibi büyük birlik

Paylasilmis

Lokma lokma ekmek 

Yudum yudum su.

Kimliktir 

Ertelenmis hak

Cekilmis hasret

Günes isiginda 

Bölüsülmüs

Bir ezgili yürek.

Daglardir

Özlemin tadindadir

Verilmis can

Gün ile merhabalasan umut

Bitmeyen kavga

Sevgilidir

Sevgiliye hasret

Sicakliginda mektubun 

Seher aydinliginda

Karninda umutla 

Yollarda gözü

Anadir

Topraginda kökü

Suyunda serinligi

Günün son isiklariyla 

Hatiri yüreklerde

Özgürlük 

Aril

Siir gibi

Umut gibi

Sevgi gibi

Sesimize gelecek

Cocuktur belki...

swd

(Son Tango & Bir Daha Susma Yüregim adli siir kitabindan, 1999-2002)', 'Sirasidir elbet Sevdayi icinde asi tutmanin Askina dizgin degmemesi bir daha Heyecandir  Coskudur Emektir Mücadeledir Ama daha cok direnis m...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yuregim-daha-ileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-yolcu-toprak-xnwe5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum son sözüm bu 

Elimde bir karanfil birde ben ayakta 

yolumuz uzun 

heybeti kalmamış sevdaların ortasında yolum

son durakta bekliyorum seni 

acelem yok sonsuza kadar tutarım yerini

    

          soluksuzca  geçirmişler  ipini sevdanın

           ölmeyi haketmek buymuş demek ki

        

                                     Yolcu Toprak', 'Gidiyorum son sözüm bu  Elimde bir karanfil birde ben ayakta  yolumuz uzun  heybeti kalmamış sevdaların ortasında yolum son durakta bekliyor...', ARRAY['Türk Edebiyatı','Şiir','Yolcu Toprak']::text[], 8.5, '{"poet":"Yolcu Toprak","poet_slug":"yolcu-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gidiyorum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardınca/Akabinde', 'ardinca-akabinde-sule-aydemir-dgbiv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kanun saldım bir bakışla benden içeri

tövbesi olmaz yolların girişindeyim

zebaniler bekler ellerinde oraklar

ben hamım olgunlaşmanın peşindeyim

uyku arası günahlar çağırır beni

ne hikmetse tam köşelerden dönmekteyim

ağıdır ağzımda biriken acıdan su

göz görmez mide almaz hazım derdindeyim

yürürüm yol ayaklarımın altı diken

ellediğim yar yalan yakar bilmekteyim

şeklini gömüp gülmek de var hakikatten

elveda diyenin ardı su dökmekteyim

ayıkır beynim diyerek  beklemedeyim

giden dönmez gelenlerde beğenmedeyim

kim kime yazılıp bayılır görmekteyim

aşkı var diyene de gülüp geçmekteyim', 'kanun saldım bir bakışla benden içeri tövbesi olmaz yolların girişindeyim zebaniler bekler ellerinde oraklar ben hamım olgunlaşmanın peşinde...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ardinca-akabinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Bana', 'anlat-bana-yolcu-toprak-pf7d6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gel yanıma 

ellerim üşüyor buz kesti ayaklarım 

gözlerimde yanan ateş 

kül oldu sen yüzünden

ölmek ölmek yetmiyor artık 

sonunu göre göre gitmek

gelmiyor içimden                                                            

anlat bana ne yapmalı                                                            

 nasıl etmelide kurtulmalı bu senden 

kendimde yokum artık kendimde gitti elden', 'Bir gel yanıma  ellerim üşüyor buz kesti ayaklarım  gözlerimde yanan ateş  kül oldu sen yüzünden ölmek ölmek yetmiyor artık  sonunu göre gör...', ARRAY['Türk Edebiyatı','Şiir','Yolcu Toprak']::text[], 8.5, '{"poet":"Yolcu Toprak","poet_slug":"yolcu-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlat-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Acısını Öğrenmek', 'ask-acisini-ogrenmek-ali-osman-yilmaz-dgcjx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Darda kaldığımızda bize,

Aklımızı kullanmamız söylenir,

Her şeyi mantığımızla çözeceğimizi,

Öğretirler bize,öyle değilmi? 

Ama duygunun olmadığı yerde,

Yakıtsız kalmış motor gibidir mantık,

Ne kadar zorlarsanız zorlayın,artık,

Mantık motorunu çalıştıramazsınız,

Her şeye duygularınızla dalarsanız,

O zamanda duvara toslarsınız,

Canınız acır,yüreğiniz kanar,

Perişan olur,divane dolanırsınız,

Sizi görenler bakarlar şaşkın,

Ne olmuş buna,neden böyle diye? 

Hatta adınızı bile,çıkarırlar deliye.

İşte böyledir mantıksız duygu,

Yada böyledir,duygusuz mantık,

İkisi birden  yanınızda değilse,

Bilesiniz ki siz de yanmışsınız.

Ve bir gün mutlaka,ama mutlaka,

Bir güzelin acımasızlığına toslarsınız,

Acının etrafında dolananlar,

Canları yanmadan asla,

Acının ne olduğunu anlayamazlar,

On’çün; aşkın etrafında dolanan,

Aşkı arayan bayanlar,baylar,

Aşk acısını tatmadınız hiç biriniz,

Aşk acısının ne olduğunu? 

Yürek yangınının nasıl yaktığını

Bu satırları dikkatle okursanız,

Bir güzele toslamanın acısını,

Aşk acısının yaktığı,yürek yangınını,

Çok zor ama,belki anlayabilirsiniz.', 'Darda kaldığımızda bize, Aklımızı kullanmamız söylenir, Her şeyi mantığımızla çözeceğimizi, Öğretirler bize,öyle değilmi?  Ama duygunun olma...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ask-acisini-ogrenmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemalpaşa', 'kemalpasa-fahrettin-selcik-6tsb8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İzmir ‘Kemalpaşa İlçesi,

Belkahve  ardı ve ötesi,

 Heykeli, Kurtuluşun simgesi,

Arkasında Kemalpaşa sanayi sitesi,

Sıralamada büyük ve örnektir,

Ekonomiye kaynak üretir,

Kuruluşu hayli eskidir,

Ankara yolu sitede eksendir.

Dirsek temasındadır ziraatla,

Ünlenmiştir yetişen kirazla,

Ovası hayat bulur NİF çayıyla,

Etrafı çevrilidir çam ormanıyla.

Kurulmuştur sanayi, Kemalpaşa ulucak da,

Üretilir birçok ürün kirazlı ovasında,

Anılır bölge, ELKİMA marka trafosuyla,

Üçyüz kişi karın doyurur aş ocağıyla,

Elacan 3/3/2003', 'İzmir ‘Kemalpaşa İlçesi, Belkahve  ardı ve ötesi,  Heykeli, Kurtuluşun simgesi, Arkasında Kemalpaşa sanayi sitesi, Sıralamada büyük ve örnek...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kemalpasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgıç', 'dalgic-fahrettin-selcik-l20l0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep dalıp giderim,

Boş,dolu hayal ederim,

Uzak menzillere erişirim,

Rüyada ise sevişirim.

Bu olgu sadece bende değil,

Dünyada fertler buna meyil,

Sözde, karşımdakine bakarım,

Ben dalar, hayali sünger ararım..', 'Hep dalıp giderim, Boş,dolu hayal ederim, Uzak menzillere erişirim, Rüyada ise sevişirim. Bu olgu sadece bende değil, Dünyada fertler buna m...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dalgic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevginin Ölümü', 'bir-sevginin-olumu-nurettin-ay-5qwaq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm güzel şeyleri koydum içine

Tüm güzelliklerle gömüyorum sevgimi gene

Gülle yolluyorum O’ nu sana yine

Gülsün artık, gülsün yüzüm diye...

Bak gene akıyor gözyaşlarım

Bak gene bırakıyorum bir ömrü

Bitmedi mi çilem bitmedi mi derdim

Bak gene bırakıyorum acılı kalbimi...

Ey Kızkulesi yapma, etme artık

Ey Allah’ ım bırakta güleyim artık

Söyle ne yapmadım, yalvarmadım mı? 

Ay hayat mutlu et yeter artık...

Bende topraktan bir canım

Gücüm yetmez bunca acıya

Bırak artık beni, BIRAK! ! ! 

Bırak ki bende yaşayayım! ..', 'Tüm güzel şeyleri koydum içine Tüm güzelliklerle gömüyorum sevgimi gene Gülle yolluyorum O’ nu sana yine Gülsün artık, gülsün yüzüm diye... ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sevginin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli', 'deli-nurettin-ay-95nu9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özledim Tanrıçam özledim seni

Bir dinsiz oldum sensiz hayatta

Bilirsin benim dinim aşk ve sevgi

Sensiz oldum dinsiz bir deli...

Nerde o zümrüt yeşili gözleri

Bedenimi yakan alev nefesi

Kalbimi dolduran büyük sevgisi

Sensiz oldum biçare bir deli...

Dön artık Tanrıçam dön geri

Bak kalp mabedim yıkılıyor

Ölüm üstüme üstüme geliyor

Sensiz oldum ölen bir deli...

Gelmiyorsan ben geliyorum sana, yanına

Sevgin için candan geçerek bir anda

Dünyada sensiz Tanrıçasız kalacağıma

Kavuşurum ölümle dinime, Tanrıçama

Sensiz oldum MELEKTEN bir deli...', 'Özledim Tanrıçam özledim seni Bir dinsiz oldum sensiz hayatta Bilirsin benim dinim aşk ve sevgi Sensiz oldum dinsiz bir deli... Nerde o zümr...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deli-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Bilebilirdin', 'nerden-bilebilirdin-nurettin-ay-2xzw1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel galiba demiştim arkadan gördüğümde seni

Yanınıza gelipte, yavaşça bana döndüğünde

Anlamadın ışığından gözlerimin kamaştığını

Nerden bilebilirdin ki “Afrodit” kadar güzel olduğunu! 

Sonra masumca elimi uzattım tanışmak için

Sende uzatıp elinle elimi tutunca

Anlamadın biranda bedenimin yanıp tutuştuğunu

Nerden bilebilirdin ki teninin “Ateşten” olduğunu! 

Konuşurken seninle gözlerine takıldım birden

Hele sende bunu anlayıp gözlerime bakınca

Anlamadın heyecandan boğulurmuşcasına nefesimin kesildiğini

Nerden bilebilirdin ki gözlerinin “Büyülü” olduğunu! 

Sonunda birbirimize verdik O muhteşem sevgimizi

Sevginle çarpan kalbim bedenime tekrar hayat verince

Anlamadın sana sevmekten daha çok tapındığımı

Nerden bilebilirdin ki senin “TANRIÇAM”  olduğunu!', 'Güzel galiba demiştim arkadan gördüğümde seni Yanınıza gelipte, yavaşça bana döndüğünde Anlamadın ışığından gözlerimin kamaştığını Nerden bi...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerden-bilebilirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-nurettin-ay-p9w5z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah bir anlayabilsen duygularımı

Hiçbir söze gerek kalmadan

Yanındayken ki heyecanımı ve mutluluğumu

Bilmiyorum ne desem ne söylesem? 

Ben kayboldum gözlerinin yeşilinde

Her gülüşünde ışık doldu yüreğime

Ah bir tutabilsem elini sıkıca

Bilmiyorum ne dersin ne söylersin? 

İnan ki güzel kız var bir şeyler içimde

Sayende tekrar akar oldu sevgi pınarları

İster misin beraber içelim aşkı pınardan

Bilmiyorum ne dersin ne söylersin?', 'Ah bir anlayabilsen duygularımı Hiçbir söze gerek kalmadan Yanındayken ki heyecanımı ve mutluluğumu Bilmiyorum ne desem ne söylesem?  Ben ka...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmiyorum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mesaj', 'bir-mesaj-nurettin-ay-3m69f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki uyuyorsun

Belki özellikle kapattın telefonunu

Ama ben sen aklımda

Simgemizle dertleşip ağlaşıyorum! ..

O’ da soruyor bir sene oldu nasılsınız diye? 

Söyleyemiyorum suskun olduğunu

Bana küskün olduğunu

Bekliyorum diyor cumaya sizi

Diyemiyorum geleceğimiz belli değil

Dertli yalvarıyor gel prensesimle

Asırlar süren özlemimi gider! ..

Bende diyorum ki

Sende asırların özlemi

Bende her günü asırlık özlemi! ..

Geleceğiz yanına! 

Ama öyle bir hal ki

Gel desem gelir mi,suskunluğu gider mi? 

Bilmiyorum beni anlar mı yada anlamak ister mi? 

Ama bilsin yeter! 

Mecnun olur çöller gezerim,

Ferhat olur dağlar delerim,

Pir Sultan olur dar ağacını boylarım,

Sen beni belki anlarsın belki anlamazsın

Ama ben ne senden

Ne sevginden vazgeçerim! ! !', 'Belki uyuyorsun Belki özellikle kapattın telefonunu Ama ben sen aklımda Simgemizle dertleşip ağlaşıyorum! .. O’ da soruyor bir sene oldu nas...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-mesaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak Nedir?', 'aglamak-nedir-nurhan-gokturk-a177y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gözlerimi ağlarken görmedin,

Çiçeğim! ! 

Ağlamak nedir? 

Bu kan ağlayan kalbime sor.

Sen beni yalnızlıktan,

Boğulurken görmedin.

Çiçeğim! 

Karanlık gecelere,

Geçmek bilmeyen dakikalara,

Ve başımı koyduğum,

Taş yastıklara sor.

Nurhan Göktürk

(27 Ocak 1982/Niğde)', 'Sen gözlerimi ağlarken görmedin, Çiçeğim! !  Ağlamak nedir?  Bu kan ağlayan kalbime sor. Sen beni yalnızlıktan, Boğulurken görmedin. Çiçeğim...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglamak-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğurtu', 'sogurtu-osman-velioglu-8sz7e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her sabah cebimden alıp güneşi, 

Şehrin üzerine savuruyorum. 

Anlamam, kim verdi bana bu işi, 

Kendimi kendimle kavuruyorum. 

Altında tüneyip yaşlı çınarın, 

Mahmur bakışlara nanik yaparım. 

Sarın bedenimi rüzgarlar, sarın, 

Elbet birgün, ben de burdan koparım... 

O''nu arıyorum, buram be buram, 

İşve kaldırımlar şehvet satıyor. 

Kan değil, geceyi akıtır yaram, 

Ay mızrak saldıkça tene batıyor... 

Her gece bir celse kurup gurbette 

Yargıladım onu, suçluydu bence... 

Sinsi tabiatlı yalın hasrette 

Eridi vuslatım, bak, ince ince... 

Çatla kahrolası ayrılık vakti, 

Visale gün saydım. savuşacağım... 

Göresi, içime bin umut ekti, 

Ha bugün, ha yarın... Kavuşacağım....', 'Her sabah cebimden alıp güneşi,  Şehrin üzerine savuruyorum.  Anlamam, kim verdi bana bu işi,  Kendimi kendimle kavuruyorum.  Altında tüneyi...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sogurtu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-nurhan-gokturk-ciy26', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kerpiçten evler, toprak damlar,

Tandırlar boyu is kokan duvarlar,

İnsanlarla, hayvanların,

Nefeslerinin birleştiği tek göz odalar,

Şeytanın çok gördüğü, koca bir ovada,

Yapraklarına kan taşıyan,

Damarları bile kurumuş,

Gölgesinde bir dilim ekmeğin,

Yüreklerdeki sevinçlerin paylaşıldığı,

Tek ağaç kalmış.

Yalın ayak teptiği kıraç toprak,

Nasırlı elleriyle okşarcasına yoğurduğu,

Alın terini, emeğini,

Tek damla göz yaşını ayırdığı,

Aşkla, şevkle, sevgiyle bağrına bastığı toprak,

İnsan kanına susamışçasına,

Bir bir yarıldı! ! 

Atlar şaha kalktı ağıllarda,

Hayvanlar bağırdı.

Çaresizlik  insanları gafil avladı.

Toz duman kastı, kavurdu ovaları,

Şeytan kan püskürdü,

Hüküm gecesinde! ! 

Felaket kara bir bulut gibi,

Ufkumuzu kapladı, çöktü üstümüze,

Bir bir damlar çöktü, insanlar öldü,

Bir zamanlar bu ova benim köyümdü.

Bir inilti, bir uğultu kalmış şimdi.

Bir buradan oraya,

Rüzgarla savrulan.

Birde ben, yarım adam.

Nurhan Göktürk

(11 Ekim 1982/Muradiye/Van)', 'Kerpiçten evler, toprak damlar, Tandırlar boyu is kokan duvarlar, İnsanlarla, hayvanların, Nefeslerinin birleştiği tek göz odalar, Şeytanın ...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/deprem-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sigara İçimlik Şiir', 'bir-sigara-i-cimlik-siir-osman-velioglu-wxyoo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerden bileceksin benim şu anda 

Seni düşünerek ağladığımı. 

Şiirler bir yanda, resmin bir yanda 

Bakışlarımızı bağladığımı. 

''seni seviyorum'' diyebilmenin 

Erişilmez hazzı dudaklarımda. 

Ruhumu yıkayan tatlı sesinin 

Nazlı aksi yaşar kulaklarımda 

Gecenin dördünde çalar kapımı 

''buyur, gel'' demeden gelir hasretin 

Sana bağışladım gönül tapumu 

Ödülü, gelmendir; bunca zahmetin... 

Dişi uzaklığım, mesafelere 

düşmanlığım; sana ulaşmamaktan. 

Gonca yanaklara, güzel ellere 

Bir toz kadar olup bulaşmamaktan. 

''gel'' tesbihindeyim sana kadınım 

Mazini karanlık adresindeyim 

Kimsesizlik yoldaş bana kadınım 

Sigaramla seni içmelerdeyim 

Nerden bileceksin benim şu anda 

Resmini öpüpte kokladığımı. 

Geceler beynimi böyle yaranda

Hatıralarımı yokladığımı', 'Nerden bileceksin benim şu anda  Seni düşünerek ağladığımı.  Şiirler bir yanda, resmin bir yanda  Bakışlarımızı bağladığımı.  ''seni seviyoru...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sigara-icimlik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk yerinde ağırdır..', 'ask-yerinde-agirdir-huseyin-umit-cetin-rtixn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mahşer değil belki varisi muhabbetin aşkın falan

Yar Dünyada gerek, vuslata yok belki de başka mekan', 'Mahşer değil belki varisi muhabbetin aşkın falan Yar Dünyada gerek, vuslata yok belki de başka mekan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ask-yerinde-agirdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıyordu Aşk', 'kaniyordu-ask-gulsen-senderin-iugln', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül goncasında sarı kızıl yanıyordu aşk 

Al yaprağıyla diken diken kanıyordu aşk 

Buzul çiğ damlaları kalplerde çözülürken 

Zevklerin doruklarını tırmanıyordu aşk! 

Yapağına dert açan yakan sanıyordu aşk 

Kimi gönülde sevk kimi utanıyordu aşk 

Sarım sarım arzular can tende gülleşirken 

Sevgi harmanında izleri siniyordu aşk! 

Mutluluk gezegenini sakınıyordu aşk 

Köpüklü umutsuz denizi kınıyordu aşk 

Yelkenli gölgelerde zaman ağırlaşırken 

O özgürlük rıhtımında uyanıyordu aşk! 

Cağlar boyu efsaneleri anıyordu aşk 

Özünde ne engel ne hüzün tanıyordu aşk 

Tutkular otağında ömür akıp geçerken 

Yaban kokuşlu cazibeye KANIYORDU AŞK! 

              Eylül – 2001 – Ataköy-', 'Gül goncasında sarı kızıl yanıyordu aşk  Al yaprağıyla diken diken kanıyordu aşk  Buzul çiğ damlaları kalplerde çözülürken  Zevklerin dorukl...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaniyordu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçsel Kırıklık', 'i-csel-kiriklik-ahmet-aksoy-kohtt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..........''Gözlerini çevir göreceksin''

tütsülenmiş maksadlarda

.....................bit yeniği,

kutsanmış sularda boğulmak,

ki herkesin derdi,

.....umduğu, umduğu olmamak.', '..........''Gözlerini çevir göreceksin'' tütsülenmiş maksadlarda .....................bit yeniği, kutsanmış sularda boğulmak, ki herkesin derd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icsel-kiriklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Olan', 'sende-olan-huseyin-cayikli-yfcbc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artık yanımda tasıyorum seni

kimliğim oluyorsun 

kimliksiz bir sıfatta dolasırken.

içimde nedensiz cumlelerde dusunceler

ben heraksam sen diye dua ediyorum.

şimdi bu geceyide seninle kapatıyorum...

bir şey var kelimlerde 

tarifi mechul

bir şey var sende olan 

bu sefer seninle olsun...', 'artık yanımda tasıyorum seni kimliğim oluyorsun  kimliksiz bir sıfatta dolasırken. içimde nedensiz cumlelerde dusunceler ben heraksam sen di...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sende-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadakat gerek', 'sadakat-gerek-huseyin-umit-cetin-p62t0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül''de menekşe bulunmaz

Benzerinden aslı olmaz

Belki değildir tek damlaya layık,olsa da GÜL! 

Sen su ol da yine, bildiğin MENEKŞEYE dökül', 'Gül''de menekşe bulunmaz Benzerinden aslı olmaz Belki değildir tek damlaya layık,olsa da GÜL!  Sen su ol da yine, bildiğin MENEKŞEYE dökül...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sadakat-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda arama', 'uzaklarda-arama-huseyin-umit-cetin-kjefr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dikeni bas bağrına,sakla teninde kanatmaz! 

Güldür açan yarayı,düşman-hançer aratmaz

Kötülük ehlinden değiliz,içimizde yatmaz

Yatsa belin ağrıtır,kovmasam da kendi kalamaz', 'Dikeni bas bağrına,sakla teninde kanatmaz!  Güldür açan yarayı,düşman-hançer aratmaz Kötülük ehlinden değiliz,içimizde yatmaz Yatsa belin ağ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzaklarda-arama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En zoru', 'en-zoru-huseyin-umit-cetin-jr7bx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dost bulmak   ''zor''   iştir

Dost olmak     ''Zor''   iştir

Dost kalmak '' ZOR''  iştir', 'Dost bulmak   ''zor''   iştir Dost olmak     ''Zor''   iştir Dost kalmak '' ZOR''  iştir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/en-zoru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazsam Barışın Sessizliğini', 'yazsam-barisin-sessizligini-gulsen-senderin-gq4m8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazsam sayfalarca yazsam hiç durduran olmasa 

Şafak vakti gölgeler savaşı hiç kuşanmasa 

Gizli hainlikler tek tek atılsa bir kenara 

Sevgiyle aşkla doğan insanlar kurşunlanmasa 

Ümitler zincirini koparan kiran olmasa... 

Korkuyorum neşeli çocuk yine ağlayacak 

Korkuyorum hizmete giden asker dönmeyecek 

Korkuyorum sayısız canlar ocaklar sönecek 

Ve korkuyorum yaralanan, eksilen bedeni 

Kimsesizleri kimseler, sevgiler sarmayacak... 

Dağlarda ovalarda çöllerde okyanuslarda 

Batik ülkelerde açmayan sevgileri yazsam 

Anlatsam kardeşliği, yazsam savaşın zehrini 

Ve yazsam Müslüman’ı Musevi’yi Ermeni’yi

Arabi Yahudi’ yi...Sarsam dünyaya sevgiyi... 

Keşke yazsam sayfalarca kalemim kırılmasa 

Korkuyorum özgürlük için korkulan olmasa 

Sitelere girip BARISI cetlerle aktarsam 

Cesaretim yok sığıştıramam acıyı kanı

Anlatsam bilgi çağını füzeleri sustursam... 

Kayıplarla bas edilmez masrafı hesaplasam 

Masraflarla ac-karin insanları ağırlasam 

Gülüşlerin bedende duygulardan açtırdığı 

Savaşsız yaşamın çiçek çiçek taçlandırdığı 

Mutluluk bahçelerini size yazsam anlatsam... 

Kumsalda çakılla, elmasla oynayan çocuğu 

Esmer beyaz irk gözetmeden evliliği yazsam 

Duygular harmanındaki Mutluluk Öpücüğü 

Savaşsız günler doğsa, size hep sevgi yazsam 

Ve sizlere tek BARIŞIN SESSİZLİĞİNİ yazsam...', 'Yazsam sayfalarca yazsam hiç durduran olmasa  Şafak vakti gölgeler savaşı hiç kuşanmasa  Gizli hainlikler tek tek atılsa bir kenara  Sevgiyl...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yazsam-barisin-sessizligini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım..', 'unutmadim-huseyin-umit-cetin-7t7l0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unuttum demek de hatırlamaktır derler...

   Akıl elbet unutmaz,iş ki gönül silmesin

    Akla gelirsin lakin,bir daha gönle giremezsin', 'Unuttum demek de hatırlamaktır derler...    Akıl elbet unutmaz,iş ki gönül silmesin     Akla gelirsin lakin,bir daha gönle giremezsin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/unutmadim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Seni Bitiren Bir Sen Olmuşsun', 'sen-seni-bitiren-bir-sen-olmussun-gulsen-senderin-5bhak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgiyi ertele aşkı ertele 

Her bahar mevsimi hazan olmuşsun 

Gündemi yaşamı şansı ertele 

Kalbine borçlanan düzen olmuşsun! 

Sen seni bitiren bir sen olmuşsun 

Kalbindeki aşka küsen olmuşsun 

Sevda pazarında gezen olmuşsun 

Artıyı eksiye yazan olmuşsun! 

Zannettin ki gençlik sende duracak 

Harcadığın gönül hesap soracak 

Kırmadığın gurur seni vuracak 

Yanlış felsefeyi güden olmuşsun! 

Sevgi eken sevgi biçecek elbet 

Sebatın mahsulü kalbe ziyafet 

Hüsran eken toplar dert ilelebet 

Hasret çektirmeyi bilen olmuşsun! 

Sevgi bebeğimdin seven kalbimde 

kurgulu utkuydun özlü çevremde 

Tutulmaz bir kustun ''GÜLŞEN'' bahçemde 

Bilmeden özünü yıkan olmuşsun! 

Sen beni yitiren bir sen olmuşsun 

İnsafa gelmeyen diken olmuşsun 

Yanlış kapılara mahzen olmuşsun 

Karanlığa mahkum insan olmuşsun!', 'Sevgiyi ertele aşkı ertele  Her bahar mevsimi hazan olmuşsun  Gündemi yaşamı şansı ertele  Kalbine borçlanan düzen olmuşsun!  Sen seni bitir...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-seni-bitiren-bir-sen-olmussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkutan vuslat', 'korkutan-vuslat-huseyin-umit-cetin-kkio4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söner mi vuslat ile? sönüyorsa aşk değil! 

Aşk ise? Umman bile söndürecek güç değil

Söner mi ateş,ateş ile? iki yürekte meşale

Ne söner derya ile ne de Dünya olsa pervane

Lokman da alim idi,O bulmuş mu ki bir çare? 

Aşk illet degil ki,O da ondan divane,

                           O da ondan biçare', 'Söner mi vuslat ile? sönüyorsa aşk değil!  Aşk ise? Umman bile söndürecek güç değil Söner mi ateş,ateş ile? iki yürekte meşale Ne söner dery...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkutan-vuslat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaten Ay Bile Gitmişti', 'zaten-ay-bile-gitmisti-ahmet-kose-wkja6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaten ay bile gelmiyordu

gece sohbetlerime

gül mü açardı bu yürekte.

Sözcüklerim hece olmadan

yutkunurdum geriye

sayfalarım taşar

okunmaz haldeydi hayatım.

Yazamazdım pencere önü kaynaşmaları

kuşların sesi duyulmaz

yürümez bu hayat

gözlerim sana kalkmaz oldu.

Estim hatırına bu yaşam halayının

yüreğim aynı ritimde diz vurdu sürüngenlerin üstüne.

Ne yılan bıraktım

Ne çıyan

Ne de solucan ezilmedik.

Kedi ve köpeğimle

zeybek oynuyorum şimdi

yaseminler dikerken hayatıma

Ay koynumda uyudu.', 'Zaten ay bile gelmiyordu gece sohbetlerime gül mü açardı bu yürekte. Sözcüklerim hece olmadan yutkunurdum geriye sayfalarım taşar okunmaz ha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaten-ay-bile-gitmisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ney', 'ney-oguzkan-bolukbasi-1iee7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gökten alıp

ver toprağa

can sitemdir bir yaprağa

bedenimdir sefinem

ruhumdadır hazinem

her şey döner

ışık döner

dünya döner

evren döner

bir gün ışıklar söner

veren alır

sen olursun

tam olursun

sevgiliye kavuşursun

yandık şükürler olsun', 'gökten alıp ver toprağa can sitemdir bir yaprağa bedenimdir sefinem ruhumdadır hazinem her şey döner ışık döner dünya döner evren döner bir ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ney-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim döndü aynaya...', 'kalbim-dondu-aynaya-i-brahim-ethem-bingul-k6ip9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını ana ana, ismini söyleye söyleye,

Her şeyi unuttum, tek bildiğim senin adın, 

Onu''da kalbim söyleye..

Dilim senin adını her söylediğinde, bir parçamı kopardılar,

Her anılışında, tuğla tuğla temizlemeye aldılar,

Adının her harfi, her noktası kalbimi temizledi, çevirdi cenneti alaya,

Kalbimi ayna yaptım, temizledim bir çizik bile olmasın suretin,

Benim sana aşkım, senin aynadaki suretin,

Benim sana aşkım, gecenin gündüze aşkı gibi,

Benim sana sevdam, denizlerin suya sevdası gibi,

Gel artık, mekanın hazır,sahibisin benim yüreğimin,

BEKLİYORUM.....', 'Adını ana ana, ismini söyleye söyleye, Her şeyi unuttum, tek bildiğim senin adın,  Onu''da kalbim söyleye.. Dilim senin adını her söylediğind...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbim-dondu-aynaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Rüzgar', 'adin-ruzgar-jale-demirdogen-rqtzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dümdüz gitme bu sefer

Yolu değiştir

Sağa dön,

Dar sokağa gir

Sokağın sonunda bir çocuk bahçesi var

Hayret! 

Daha önce hiç gitmedin mi? 

Salıncaklara küskün

Minik bir kız çocuğunun bal gözleri ağlıyor

Gayret! 

Ha ittin ha iteceksin...

Gözbebeklerimin ta içindesin

Yoksa henüz görmedin mi? 

Seyret! 

Ama çok dikkatli bak

Ha gördün ha göreceksin...

Sağ avucunu aç

Bir yeni çizgi eklenmiş diğerlerinin yanıına

Daha farketmedin mi? 

Kimse bilemez o çizgilerin dilini

Sabret! 

Ha çözdün ha çözeceksin...', 'Dümdüz gitme bu sefer Yolu değiştir Sağa dön, Dar sokağa gir Sokağın sonunda bir çocuk bahçesi var Hayret!  Daha önce hiç gitmedin mi?  Salı...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adin-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kan', 'mavi-kan-jale-demirdogen-1lxng', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yumuşacık öpücüklerinin okşadığı tenimden

Kan damlıyor şimdi

Battıkça kanatıyor çünkü

Kırılan umutlarımın en sivri köşeleri

Yaşadığıma dair son hatırladığım

Ege''de bir sahildi

Dalgaların boyu seninkinden biraz uzun,

Kıyıya bırakıyordu bembeyaz köpükleri

Tıpkı o köpükler gibi yüzlerce,beyaz

Hatırayı bırakıp avucuma

Bir gidişin vardı ki,

Kırmızı diye bilirdim,

Kanımın rengi değişti! 

Artık o kırık umut parçalarının her bir sivri köşesi

Saplandıkça tenime,

Gözlerin damlıyor benden

Masmavi!', 'Yumuşacık öpücüklerinin okşadığı tenimden Kan damlıyor şimdi Battıkça kanatıyor çünkü Kırılan umutlarımın en sivri köşeleri Yaşadığıma dair ...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mavi-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşik', 'besik-jale-demirdogen-qip0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarım su yeşili ipek kurdele

Ben onlarla saçlarımın örgüsünü bağladım

Sen benden gittiğinden beri

Gece değil,gündüz değil

Ben her vakit ağladım...

Zaman her derdin ilacı,dayan dediler

Dayandım dayanmasına da

Yetmedi işte anne,parmaklarım yetmedi

Kaç yıl olmuş saymadım

Bir de bu şiirler yok mu? 

Ah bu şiirler...

Bu şiirler aşk için ölmemi söylediler

Kalınca kapatılan kapıların önünde

Ben sen olup,beşikteki beni salladım!', 'Gözyaşlarım su yeşili ipek kurdele Ben onlarla saçlarımın örgüsünü bağladım Sen benden gittiğinden beri Gece değil,gündüz değil Ben her vaki...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/besik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semada-32', 'semada-32-ahmet-kose-g79px', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoksun

Dokunmasızım yaprakların içinde

Ağaçsızım.

Yoksun

Bakışsızım insanların içinde

İnsansızım.

Yoksun bir yerdeyim

İzlerinde sevginin dişleri

Yanıyorum.

10/02/93', 'Yoksun Dokunmasızım yaprakların içinde Ağaçsızım. Yoksun Bakışsızım insanların içinde İnsansızım. Yoksun bir yerdeyim İzlerinde sevginin diş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/semada-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havasız Gecelerden biri', 'havasiz-gecelerden-biri-ahmet-kose-f1wxg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecede şiir yok

sıkıntısı var tümcelerin

istemiyor yazılmak.

Göz yok yazıya bakacak

el yok  uzanacak  ellere

su yok ıslanacak

değilmi ki bundan kuru yüreğim.

Sevgi usanmasız

uzanılmaz sevgiliye

yaşanılan bunca an

anılmadan hep uçup gitmede.

sıkıntılı şiirler yazılırken.', 'Gecede şiir yok sıkıntısı var tümcelerin istemiyor yazılmak. Göz yok yazıya bakacak el yok  uzanacak  ellere su yok ıslanacak değilmi ki bun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/havasiz-gecelerden-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Sabıkalıydım*', 'sanki-sabikaliydim-bayram-tunca-fs89v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ekserin uykuya yenik düştüğü bir anda 

Görenler dediler hey ne arıyorsun orda 

Diyemedim ki Leylâ’yı arıyorum burada 

Sanki de bir suçlu gibi donakaldım orda 

Ah dostlar ah, sanki sabıkalıydım sabıkalı 

Bileklerimden ziyade, dilim kelepçelenirdi 

Her gördüğümde ela gözlerim büyülenirdi 

Nutkum tutulur, boğazım da düğümlenirdi 

12.12.2003-12.12', 'Ekserin uykuya yenik düştüğü bir anda  Görenler dediler hey ne arıyorsun orda  Diyemedim ki Leylâ’yı arıyorum burada  Sanki de bir suçlu gib...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sanki-sabikaliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahzuni', 'mahzuni-nevzat-bayramoglu-hurdemi-nlt7x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır yılmadan halkı savundu

Hakkı halk içinde gören Mahzuni

Zalimlere çattı zulme direndi

Halk için bir ömür veren Mahzuni

Elinde sazıyla il il dolaştı

Engel tanımadı sınırlar aştı

Riyakâr olmadan mertçe savaştı

Tehditlere göğüs geren Mahzuni

İnsan bildikleri hep bir ayardı

Halkı için vardı saygı duyardı

Mısralarla milyonları uyardı

Acılardan türkü deren Mahzuni

Mazlumu kayırdı namerde çattı

Gerçeği söyledi zindanda yattı

Hem kültüre nice eserler kattı

Özünü meydana seren Mahzuni

Halkıyla ağladı halkıyla coştu

Güleç yüzü ile sohbeti hoştu

Muhabbet nerdeyse oraya koştu

Hakikat cemine giren Mahzuni

Hayata küsmedi çekse de çile

Şeref oldu yolu bilmedi hile

Memleket halini getirip dile

Hırsızlardan hesap soran Mahzuni

Kalmamış Hürdemi dünyanın tadı

Haklı sanık olmuş haksızlar kadı

Hak için savaşan böyle üstadı

Andık anacağız her an Mahzuni

18 Mayıs 2002 - Ankara', 'Yıllardır yılmadan halkı savundu Hakkı halk içinde gören Mahzuni Zalimlere çattı zulme direndi Halk için bir ömür veren Mahzuni Elinde sazıy...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/her-an-mahzuni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kasım Sabahı', '10-kasim-sabahi-gulsen-senderin-g88c4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sirenler çaldı saat tam dokuzu beş geçe

Yüreklerde yankılar geçmişi bağlıyordu

Ata''mızın yokluğu kalpleri dağlıyordu

Altmış beş yıl sonunda ne ektik ki ne biçe

Bu On Kasım sabakı ATATÜRK ağlıyordu... 

Her çocuk okulunda andımızı okudu

Türküm doğruyum...yasam! İlkelerle dokudu

Atam Cumhuriyetin zafer tacını koydu

Devralınan umuda verilen söz bu muydu

Bu On Kasım sabahı ATATÜRK ağlıyordu...

Ata''nın devrimleri sanki önem yitirdi

Bu gaflet uykuları neler aldı götürdü

Dünde atılan çarsaf bugün türban getirdi

Cehaletin paydası huzuru da bitirdi

Bu On kasım sabahı ATATÜRK ağlıyordu...

Cumhuriyet kutlandı coşkularla elele

Nerde eski balolar, resepsiyonlar söyle

Bu içte huzursuzluk sorgulansın bir hele

Tek soluk olamadık seksen yıl geçti böyle

Bu On kasım sabahı ATATÜRK ağlıyordu...

Artık bazı şeylere azimle dur diyelim

Bizi yıkan güçlere ihtimal vermeyelim

Medeniyet yolunda mücadele edelim

Her karış toprağımız kıymetini bilelim

Yarınlar bizi bekler hep beraber GÜLELİM', 'Sirenler çaldı saat tam dokuzu beş geçe Yüreklerde yankılar geçmişi bağlıyordu Ata''mızın yokluğu kalpleri dağlıyordu Altmış beş yıl sonunda ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/10-kasim-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-gulsen-senderin-7u5x8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bu özel günde değil, ışıyan bir güneş gibi 

Issız siyah dağlarında her zaman beklerim seni 

Senden öte aşılmaza, tıpkı bir tüm bir eş gibi 

Bağlarında gizli açar, aşkla çiçeklerim seni! 

''On dört Şubat'' bugün demem, aksın göz yaşlarım silmem 

Gamlı sevdam hep hoş gibi hasreti şikayet bilmem 

Özlemin özlemimde ağ, seni dokur sevgin dilmem

Ağlarında motif motif, aşkla ipeklerim seni! 

''Sevgililer Günü ''değil yaşanmaz çağlar emsali 

Her kederde her sevgide sonsuz hoş görü timsali 

Utkulu bir aşk uğruna, ürkek bir ceylan misali 

Dağlarında hep gezinir, aşkla eteklerim seni! 

Ben bende açan sevgiye coşarım ömürler boyu 

Irmak deniz umman bilmem taşarım dalgalar boyu 

Ova bayır tanımam koşarım sınırlar boyu 

Sürgün atar izleyişle, AŞK’ LA emeklerim seni!', 'Ben bu özel günde değil, ışıyan bir güneş gibi  Issız siyah dağlarında her zaman beklerim seni  Senden öte aşılmaza, tıpkı bir tüm bir eş gi...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgililer-gunu-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeklerim, Hıyartolarım Ve Siz! ...(Dümdüz Yazı)', 'gerceklerim-hiyartolarim-ve-siz-dumduz-yazi-naime-erlacin-w8fzs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bunaldı kadın! ...

Eski yatılı okulun teknik yöneticisi, müzmin bekar, hayata illallah, Tacittin Zübük Efendi gibi çok yakında “YETERİNG LAN! ! ! ! ” diye bağırmak üzeredir…

Aman yanlış anlaşılmasın. Ürktü falan sanmayasınız sakın. Sadece konuşamadığı için dili şişti, o kadar. Dostları tenzih ederek, kendini dünyanın kralı sayan aerodinamik makinelerden; “aman efendim, sepet efendim, saygıdeğer hanımefendi üstadım” diye çığıran müsvedde-i baklava ve asit oranı yüksek yağ efendilerinden; ortaya çıkma cesareti bulamayıp da karanlık gölgelerde yalancı rumuzlar altında dönerci bıçağı ile ahkam kesenlerden; sosyal terapi salonlarında mastürbasyona son hızla devam edenlerden resmen ve ilanen bıktı artık. Bıktı, bıktı, bıktı.… 

Uyarıdır:Rahat bırakın, sıkmayın, ellemeyin kadının özgürlüğünü! ! ! 

Daha nelerden bıkmadı ki? Hatun kılığına girmiş, insan benzeri had safhada ukala bir “homo sapien” (“neanderthal” bile olabilir pekala)    soruyor kadına; neden yalnız yaşıyormuş efendim? İnsan içine çıkmalı, hayata karışmalıymış, falanmış feşmekanmış; camekanmış! ...Sana ne oluyor zilli teneke? Kaşındığın her halinden belli de sana batan nedir, onu anlamak zor işte.Yalnız yaşadığını nereden çıkardın hem? Ayrıca kadının unuttuğu hayatı öğrenmeye senin ömrün yetmez sanal dünyanın dandik üretimi; çabuk tüketilmeye müstahak,  aynaya sureti düşmez “homo erectus” ey! ... O sana hiç soruyor mu, bastıramadığın kompleksler altında paspaslanmış ne biçim bir cahil hıyarto olduğunu, ha? ...

Uyarıdır: Herkes kendi işine baksın! ! ! 

Sahneye “pembe oyunlar” koymalıymışız efendim! ..İnsanları mutlu etmek içinmiş. Yahu sipariş ayakkabı mı bu? Sanatta mutluluğun alakart ısmarlandığını da ilk kez duyuyor kadın. Tepesi göçük vaziyette. Anlayacağınız dam akıyor. Daha iyi bir fikri var. Diyalogu beceremediğimize göre, “Sağır Monologları’nı koymalıyız” diyor sahneye. Sonra da köşedeki fırında iyice altüst kızartır ve münasip yerlerine papatyalar takarak servis ederiz sofraya. Gül fazla ağır kaçar hani! ...Ne hoş bir fikir, değil mi :)   Açınız kulaklarınızı ve dinleyiniz efendiler. Sanat, başkaldırıyı en güçlü şekilde ifade eden estetik ve devingen yöntemlerin bütünüdür. Sanat, uyumu içinde gizleyen yaratıcı bir tür isyandır! .. Sanat özgürlüktür! ...Naif bir mutluluk reçetesi değil…

Uyarıdır: Sanata müdahale etmeyiniz. Aksi takdirde elleriniz fena halde “cısss” olur! ...

Bunaldı kadın! ..

Ruhunu öpeyim Aziz Nesin, nerelerdesin? Ve Serdario Can, hıyartolar hakkında söylediğin her şeyde haklıymışsın dostum…(Kim olduğunu sormayın sakın kadına. Bu alemden biri değil O. Allah’ıma bin şükür ki değil, yoksa telef olurdu vallahi! ...Belki de telef ederdi. Hiç belli olmaz! …)   “Hıyaran’ı dinliyorsam, demek ki ben de bir hıyarım! ..” diyen “Hıyaran” yazarı dost, sen de yerden göğe kadar haklıymışsın…

Uyarı: Dost sözü dinlenmeli….

Daha çoook uyarısı var kadının. Bu günlük bu kadarı yeter. İdare edin artık. 

“Bilmem anlatabiliyor muyum? ....”

 :))))))))))))))

……..

Uyarı Notu: Haşırttt eleştiri sevmiyorsanız ve  hayatınızda hiç Bukowski okumadıysanız eğer, sakın ola bu yazının yanından bile geçmeyin. Düş sağlığınız bozulabilir! ....

(13 Aralık 2003)', 'Bunaldı kadın! ... Eski yatılı okulun teknik yöneticisi, müzmin bekar, hayata illallah, Tacittin Zübük Efendi gibi çok yakında “YETERİNG LAN...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gerceklerim-hiyartolarim-ve-siz-dumduz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarnıç', 'sarnic-ali-capan-c7yaz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarnıçta biriken yağmur suları

yosun  tutmaz.

Çiğdemlerin çiçek açmasını bekler.

Her sarnıcın yanıbaşında

bir incir ağacı vardır

dalında sararan incirler

susamış yolcular

ve bir iklimden

bir başka iklime

göçen kuşlar

soluklansın/dinlensin diye bekler.

Sarnıçlarda kalaylı bakır tas olmaz

avuç avuç içilen suda

biraz kışın

biraz baharın

biraz da yazın kokusu vardır.

Ölen her şairin arkasından

mutlaka ağlayan

bir sevgilisi vardır

gözyaşlarını

içindeki sarnıca akıtan.', 'Sarnıçta biriken yağmur suları yosun  tutmaz. Çiğdemlerin çiçek açmasını bekler. Her sarnıcın yanıbaşında bir incir ağacı vardır dalında sar...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sarnic-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-ali-capan-01k1e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duydum ki; 

gözlerinin  rengine uygun

kafiye arıyorum diye

beni sana  ihbar etmişler.

Aşkı anlatan dilinle

söyle bana.

Anılar dünde kalan 

yaşananlar mı? 

Geriye dönüp baktığımda

beni beklemeyen.

Kurumuş

dallardan havalanan kuş-

-lar mı yoksa

geri gelmeyen.

Her şairin en az bir şiirinde

anlatmak istediği bilmecenin

bilinen cevabı

ölüm mü / ayrılık mı

dalından koparılan

gül mü yoksa?', 'Duydum ki;  gözlerinin  rengine uygun kafiye arıyorum diye beni sana  ihbar etmişler. Aşkı anlatan dilinle söyle bana. Anılar dünde kalan  y...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilmece-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güler Oldum Hayata', 'guler-oldum-hayata-baris-guc-swd49', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden bu israr bilmiyorum

Bir güç beni sana çekiyor

Artik güler oldum hayata

Öyle bir rüyadayimki bu ara

Hiç kimse uyandirmasin beni asla

Bir bakismi bu esaretin sebebi? 

Yoksa sans,kadermi demeli? 

Artik oynamak istemiyorum ask oyununu

Yasamak istiyorum sadece seninle

Temiz ve saf kalbini doldur benimle

 13/12/2003 sda ozlt  MSN: [email protected]', 'Neden bu israr bilmiyorum Bir güç beni sana çekiyor Artik güler oldum hayata Öyle bir rüyadayimki bu ara Hiç kimse uyandirmasin beni asla Bi...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/guler-oldum-hayata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gÜL diYoRuM', 'gul-diyorum-hasan-yasar-xgyy6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevcan’a

gül diyorum ya; 

insanın 

parasıyla bile

gülemediği bir zamanda

gülenin

ayıplandığı

geniş 

ve çoğul 

acılarla

çevrili

bir yerde doğdum ben

öğrenemedim bu yüzden 

tasasızca

tek başıma gülmeyi

ama

sen

aldırma

hiçbir şeye 

gül  de

odalar aydınlansın

aldırma

bırak dağınık kalsın saçların

bulaşıklar da kirli

sen

sadece 

gül

bir eve

fazla

iki ülserli...', 'sevcan’a gül diyorum ya;  insanın  parasıyla bile gülemediği bir zamanda gülenin ayıplandığı geniş  ve çoğul  acılarla çevrili bir yerde doğ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gul-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsaydı', 'olsaydi-murat-demir-kcwh1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Değişmeyen yetkim

Bitmeyen gücüm olsaydı,

Nufüsunun nereye ineceğini bilmiyorum,amma...

Düzenini,öyle yerle bir ederdimki

Kalıntılarından,eser bile kalmazdı.

Senden bahsediyorum,

Senden,

Adaletinden,

Yarattıklarının,yarattıklarına

Yaptıklarından,

Senin adına hizmet verdiğini sanan,

Seninde izin verdiğin,infaz çetelerinden.

Sağcı,solcu demiyorum

Dinli,dinsiz hiç demiyorum

Yarattıklarından rahatsızım,ben dahil

Yarattığın,yaratıklardan,

Adına en üstün canlı koyduğun,

Adı insan olan,insanların

Alçaklarından rahatsızım.

Elimde olsaydı,

Hak dediğin,dört dini de eleğe eleğe

Öyle bir hale getirirdimki,

Ne İsa’nın karşısında dua eden,

Ne papaza günah çıkarttıran,

Ne başını secdeye götüren,

Ne insanları,hayal ürünleriğle kandıran,

Nede diğerleri kalırdı.

Kalanlarsa,insan gibi insan olanlar,olurdu,

İşte o zaman,

İnsan gibi görünüp,insan olmayanların,

Olmadığı dünyada,yaşanırdı,

Barbarlığımdan değil,yapmak istediklerim

Barbarlardan kurtulmak içindir,dilediklerim,barbarlığım.

Kimsenin,kimseye karışmadığı,güçlünün güçsüzü soymadığı,

İnsanın insanı öldürmediği,İnancı için,sorgulanmadığı

Bir dünya ver vereceksen,

Yoksa sana mihnetim yok

Al canımı alacaksan,

Varsa eyer,o dünyada,

At nereye atacaksan', 'Değişmeyen yetkim Bitmeyen gücüm olsaydı, Nufüsunun nereye ineceğini bilmiyorum,amma... Düzenini,öyle yerle bir ederdimki Kalıntılarından,es...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/olsaydi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Duygular', 'i-cimdeki-duygular-koksal-akar-gahah', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah içimde bütün duygular,

Aşkın denizine, dal gitsin diyor.

Bir hayalet gibi bütün korkular,

Saklandığın yerde, kal gitsin diyor.

Karanfile benzer inan, gülüşün

Solmak mı hep güzel, varlık mı düşün.

Beynimde var olan, bin bir cümbüşün,

Gönül bu, içine dal gitsin diyor.', 'Bu sabah içimde bütün duygular, Aşkın denizine, dal gitsin diyor. Bir hayalet gibi bütün korkular, Saklandığın yerde, kal gitsin diyor. Kara...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/icimdeki-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paradoks II', 'paradoks-ii-ahmet-aksoy-u836x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaşarken şaşkın olmak

......vuslatnda korkak bir sevdalı gibi

bir kayıp değildir de nedir

..............varlık içinde.', 'yaşarken şaşkın olmak ......vuslatnda korkak bir sevdalı gibi bir kayıp değildir de nedir ..............varlık içinde....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/paradoks-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Umut Ediyorum', 'oyle-umut-ediyorum-turgut-baki-juqtz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gün gelecek 

sonbaharım kışa

saçlarımdaki kırçıllar 

ben beyaza dönecek

ve artık yalnızlığımla boğuşmayacak hiçbir düş hiçbir umut 

ve bana sensizliği anlatan hiçbir sözcük 

şiirde bir silah gibi patlamayacak namlusu bana yönelmiş

gün gelecek 

unutacağım seni

(yani öyle umut ediyorum)', 'gün gelecek  sonbaharım kışa saçlarımdaki kırçıllar  ben beyaza dönecek ve artık yalnızlığımla boğuşmayacak hiçbir düş hiçbir umut  ve bana ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oyle-umut-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlmek', 'i-lmek-turgut-baki-drgd2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensizlik

senli düşlerimden boğazıma atılmış bir kement

içimde özlemin büyür

kement ilmek, ilmek küçülür', 'sensizlik senli düşlerimden boğazıma atılmış bir kement içimde özlemin büyür kement ilmek, ilmek küçülür...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-turgut-baki-bpb8z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sensizlik

kimsesizliktir

ve kimsesizlik var ya kimsesizlik

ayaza durup buz kesmek gibi bir şey

güneşi kucaklasam ne fark eder 

sensizim

kimsesizim

anlıyor musun', 'sensizlik kimsesizliktir ve kimsesizlik var ya kimsesizlik ayaza durup buz kesmek gibi bir şey güneşi kucaklasam ne fark eder  sensizim kims...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizlik-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gidişle', 'bu-gidisle-turgut-baki-x1aoz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu gidişle 

ne sen bana yar olabilirsin

ne de ben sana

bu ikimizin de sonu olmaz üstelik

olmaz olmasına da

sensiz ben nasıl var olurum

onu bilemem', 'bu gidişle  ne sen bana yar olabilirsin ne de ben sana bu ikimizin de sonu olmaz üstelik olmaz olmasına da sensiz ben nasıl var olurum onu b...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-gidisle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-fatih-konuk-7o984', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bıçak gibi saplanan,

Bir kurşun gibi sıkılan sözlerin

O gün dünyamın yıkılmasına,

Dünyamın kararmasına sebep oldu

Karşımda beni unut dediğin günden beri

Ben sensiz mutluğum dediğin günden beri

Bitsin artık bu aşkımız dediğin günden beri

Yaralandım o gün hala da yaralıyım 

Gözlerimin on senelik geçmişim geçti

Benim sevgilim nasıl olduda benden vazgeçti

Beni değil başkasını nasıl oldu da seçti

Anlamadım o gün hala da anlayamadım

Kalbimizde can gibi taşıdığımız aşkımız

İçimizde on yıl boyunca yaşattığımız aşkımız

Nasıl oldu da bitti bu bizim sevdamız

İnanamadım o gün ve hala inanamadım', 'Bir bıçak gibi saplanan, Bir kurşun gibi sıkılan sözlerin O gün dünyamın yıkılmasına, Dünyamın kararmasına sebep oldu Karşımda beni unut ded...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-gun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimden Kendime', 'kendimden-kendime-rafet-maden-g7acy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Issız bir vaktin yeldeğirmeninde,

Vaktimi döndürüyorum.

Kaybolan geçmişim

Şu zamana bağlı.

Ve yarınlarım ise

Meçhule.

Gidiyorum,meçhulun gittiği

Ve beni beklediği

Eylül akşamlarına.

Bir gözlük camı hatırlıyorum

Ve bir ibret dersi.

Güldürmeyen gülümsemeleri

Kendime trajedi diye yutturuyorum.

Ve,

Issız bir vaktin değirmeninde

Ben geçmişimi döndürüyorum.

İleriye dönüp yeniden

Şahlansın diye.

Kendimden kendime.', 'Issız bir vaktin yeldeğirmeninde, Vaktimi döndürüyorum. Kaybolan geçmişim Şu zamana bağlı. Ve yarınlarım ise Meçhule. Gidiyorum,meçhulun git...', ARRAY['Türk Edebiyatı','Şiir','Rafet Maden']::text[], 8.5, '{"poet":"Rafet Maden","poet_slug":"rafet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kendimden-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gözlerim', 'bu-gozlerim-fatih-konuk-opkga', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu üç günlük dünyada

Neler neler gördü bu gözlerim

Ne ölümlerin ardından

Toprağa gömüldü bu gözlerim

Dünyanın düzenine,

Dağların manzarasına,

Yarin güzelliğine

Hayran kaldı bu gözlerim

Gün oldu kelimelerin yerini tuttu

Gün oldu sevdiğine sevdiğini anlattı

En sonunda ihanetide gördü bu gözlerim

Kardeşin kardeşine sırtından vurmasına

Komşunun komşusunun ardından konuşmasına

İnsanların birbirleriyle düşman gibi savaşmasına

Hayret etti bu gözlerim', 'Şu üç günlük dünyada Neler neler gördü bu gözlerim Ne ölümlerin ardından Toprağa gömüldü bu gözlerim Dünyanın düzenine, Dağların manzarasına...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nedeni Vardır', 'bir-nedeni-vardir-fatih-konuk-pa6ep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni böyle bırakmasının,

Beni unut demesinin,

Benden ayrılılmasının,

Elbette bir nedeni vardır

Böyle suskunca bakışlarının,

Telefonlarıma yanıt vermemesinin,

Yanlış numara deyişlerinin,

Elbette bir nedeni vardır

Beni sessizce terketmesinin,

Beni böyle bırakmasının,

Bir başkasıyla evlenmesinin,

Elbette bir nedeni vardır

Beni düğününe davet edişinin,

Beni severek bırakıp gidişinin,

Bakışlarını saklayışlarının,

Elbette bir nedeni vardır', 'Beni böyle bırakmasının, Beni unut demesinin, Benden ayrılılmasının, Elbette bir nedeni vardır Böyle suskunca bakışlarının, Telefonlarıma ya...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-nedeni-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlığım vurgun yedi', 'cigligim-vurgun-yedi-murat-tali-mtubu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çığlığım vurgun yedi

bu yüzden ağlar camlar 

bu yüzden sarınırım kendime bir akşam üstü

yüzümde kederli bulutlar

ama siz göremezsiniz ceketimde gizledim onu

ceketim

bir eski bez parçası 

çoraplarım ıslak

üşümüyor ayaklarım

en son yıllar önce yitirdim

hislerimi

camlar niye ağlar

yoksa yağmur mu yağar

ıslanır heryer

açım

başımda 

binlerce para ama benim değil

kirliyim

yağmur yağıyor ama bana değil

yerlerde yün döşek yok ama 

alıştım taşlarla dostluğa

ben sert değilim

o yüzden sevdiler beni

kırmadım onları

ben kıramamki

üşüyorum

neredesin anne

baba

hangi kapıdan gireceksin içeri

hangi kapı sana açılıyor,

mutluluk

cığlığım vurgun yedi 

duyuyor musunuz? 

bu yüzden sessizim', 'çığlığım vurgun yedi bu yüzden ağlar camlar  bu yüzden sarınırım kendime bir akşam üstü yüzümde kederli bulutlar ama siz göremezsiniz ceketi...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cigligim-vurgun-yedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin? Bilebilirmisin?', 'bilirmisin-bilebilirmisin-kader-budur-p47l8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar kendimle savş verdiğimi bilir misin? 

Bu kadar umursamaz görünmek

Ne kadar zor bilebilir misin? 

İçindeki sancıları gizleyebilir misin? 

Akmak ister düşünceler

Ben yollarına setler döşerim

Gözlerim seni arar her an

Ben kendimi sanki kör ederim

Bilir misin? böyle yaşamanın zorluğunu

İçten içe kahrolmayı

Hissetmenin dayanılmaz ağırlığını

Gizlice seni seyrettiğimi gözlediği 

Senin adımını bile ezberlediğimi

Söyle sen bilebilir misin? 

Ne kadar kaçmak istesemde hapsolduğumu

Kokunun hasretini dileklerdeki dualarımı

Sen benim yaşadıklarımı bilir misin? 

Özlemlerimi derin yaralarımı bilebilir misin? 

Tabiki bilemezsin

Sen hiç ben olabilir misin?', 'Ne kadar kendimle savş verdiğimi bilir misin?  Bu kadar umursamaz görünmek Ne kadar zor bilebilir misin?  İçindeki sancıları gizleyebilir mi...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilirmisin-bilebilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ey Yeşim Gözlüm! ..', 'gel-ey-yesim-gozlum-i-brahim-ozcan-v6f98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşılaşsak iki yabancı gibi dar bir sokakta 

Önce gözlerimiz tanışsa karanlıkta 

Sonra ellerimiz.. kalmasa bu sevgi hiç muallakta 

Hissetmeli yüreğim sıcaklığını daima 

Ve hissetmek onca kara günü alaca şafakta 

Yeniden umutlanmak unutulmuş yarınlara 

Ve içip içip seni geçmek kendimden  kana kana 

Sonunu bılmeden el ele yurek yurege cıkmak yola 

Kanımla adını yazmak damla damla sonsuzluğa 

Sevdanı bölüşerek dalıp dalıp gitmek uzaklara 

Kâh denizlerde dalgalara Kâh dumanlı dağlara 

Sadece senın ıcın, sana yar olmak bu dunyada 

Ve senin için alışmak yaşamaya tutunarak acılara 

Guç verıyor her saniyem yadigar senden bana 

Aramızda bitmez tükenmez cılga yollar olsada 

Yüzüm yüzüne kalbım kalbıne dönük sakın unutma... 

Yokluğun sırtımda saplı kör bir hançer olsa 

Yinede mutluluk her daim yanımızda 

Gidişin ecelim oldu sevişin unutulmaz hatıra 

Yine de beklerım dönersin diye bitmez umutla 

Gel ey Yeşim Gözlüm sensiz  cennetimde! .. 

Ne melekler kaldı  ne de zümrüdü Anka 

Kalan bir yudum hatıran olasada 

Dön eyy! yeşim gözlüm, hasretin: cepkenimde 

Ne pul bıraktı ne de beş para...

2 Ocak 2003 /Adana', 'Karşılaşsak iki yabancı gibi dar bir sokakta  Önce gözlerimiz tanışsa karanlıkta  Sonra ellerimiz.. kalmasa bu sevgi hiç muallakta  Hissetme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gel-ey-yesim-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silmek', 'silmek-kader-budur-56ccn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşeyi silmek

Bu kadar basit olsa

Ömrümün her gününü

Seninle geçirdiğim için silerdim

Ama mümkün değil

Seni silmek

Hayatımı silmek

Aşkımı silmek

Ve zamanı silmek', 'Herşeyi silmek Bu kadar basit olsa Ömrümün her gününü Seninle geçirdiğim için silerdim Ama mümkün değil Seni silmek Hayatımı silmek Aşkımı s...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/silmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitsen de yine bende kalırsın', 'gitsen-de-yine-bende-kalirsin-muammer-celik-jyvao', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elveda eyy sevgili

saçlarının yağmurda  ıslanan

burcu burcu kokusuna

elveda eyy sevgili 

sahilde tenime ıslak ıslak dokunuşuna

Elveda eyy sevgili 

mehtapla ışıl ışıl beni sevişine, elveda…! 

Hoş geldin eyyy sevgili 

hayalimdeki  tospembe köşküne

bulutlardan sarayına hoşgeldin…! 

Yatırdım cismini çamaşır suyuna 

Ruhumdaki resmine merhaba…! 

BirDeli

13.12.2003

(Mükerrem Suna Varol dostumun, beni çok etkileyen ”Veda Şiiri”den esinti ile!)', 'Elveda eyy sevgili saçlarının yağmurda  ıslanan burcu burcu kokusuna elveda eyy sevgili  sahilde tenime ıslak ıslak dokunuşuna Elveda eyy se...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitsen-de-yine-bende-kalirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsay ki Sevdim! ..', 'varsay-ki-sevdim-i-brahim-ozcan-dggxy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varsay ki ''sevdim'' dedim! .. 

''Hiç görmedin ki'' diyeceksin... 

Tanrımı da hiç görmedim; 

En çok da O''nu sevdim 

Nerden bileceksin ki? ..

2 Ocak 2003/Adana', 'Varsay ki ''sevdim'' dedim! ..  ''Hiç görmedin ki'' diyeceksin...  Tanrımı da hiç görmedim;  En çok da O''nu sevdim  Nerden bileceksin ki? .. 2 O...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varsay-ki-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar', 'karanliklar-kader-budur-r6uzu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu ışığı çabuk söndür

Gözlerim karanlıklara gömülsün

Bana acı veren uğursuzluklar

Kalbimin derinliklerine gömülsün

Karanlıklar olsun ışığım

Gecelerim gündüzüm olsun

Rüyalarım aşım

Umutlarım ibadetim olsun

Karanlıklar siz olamasanız ne yaparım

Nasıl saklanırım ışıktan

Gözlerim artık karanlığa alışmış

Bırakmayın doğmasın güneş

Karanlıklar beni yanlız bırakmayın

Tek sığınağım sizsiniz

Doğdurmayın güneşi siz beni güneşimsiniz', 'Şu ışığı çabuk söndür Gözlerim karanlıklara gömülsün Bana acı veren uğursuzluklar Kalbimin derinliklerine gömülsün Karanlıklar olsun ışığım ...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karanliklar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Anladım', 'ben-seni-anladim-oguzkan-bolukbasi-j4ke4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'doğdum

kirlendim

aşkı bulup temizlendim

ey gönüllerin görünmeyen sevgilisi

beni yanına

tertemiz al

ben seni gördüm

ben seni anladım', 'doğdum kirlendim aşkı bulup temizlendim ey gönüllerin görünmeyen sevgilisi beni yanına tertemiz al ben seni gördüm ben seni anladım...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-seni-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz yaşları', 'goz-yaslari-kader-budur-7nmoz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz yaşları bazen umutların sevinci

Acıların hüznü ve sevgilerin bütünüdür

Kimi zaman akan yaşlar

Herşeyi gizler içinde

Kimi zaman akan yaşlar

Kavuşturur sevenleri

Kimileride ayrılığın ilk işaretleri

Bazen dışa çıkan bir kahkadır içimizde

Bazende çıldırtan kötü duygular

Göz yaşlarıyla bastırırız bunları

Yaşam için hayat için mutlu olmak için

Bazen sevgiliye duyulan özlemdir 

İnsanın içini kavurur

Bazende özlemi içinden akıtır

Gözyaşı bazen kindir 

Nefrettir karşındakine

Ona duyduğun histir içinde

Sevgi için nefret için kader için

Ah gözyaşları

Siz olmasanız nasıl rahatlar

İçimizi nasıl dökeriz

Acı çektirmeden acı çekmeden

Özlemi bitirmeden nasıl bir oh çekeriz

Akan yaşlar sakın kurumayın

Ne acı çektirin nede çekmemize fırsat verin', 'Göz yaşları bazen umutların sevinci Acıların hüznü ve sevgilerin bütünüdür Kimi zaman akan yaşlar Herşeyi gizler içinde Kimi zaman akan yaşl...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/goz-yaslari-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılma yar', 'ayrilma-yar-diler-kasap-8mpr3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılma yar,

Sen yoksun her günüm geçiyor ak''tan

Seni aramaktan düştüm ayaktan

Gözlerimde kör oldu kan ağlamaktan 

Senin gibi bir yar nerde bulum ben 

Çok zahmetir sensiz daha gülüm ben 

Sensiz görseydin yar halim ne oldu 

Seven yüreyğime gam keder doldu

Bahar mevsimin''de güllerim soldu 

Senin gibi bir yar nerde bulum ben 

Çok zahmetir sensiz daha gülüm ben 

Seninle oturduk ay yar diz dize

Ant ettik söz verdik birbirimize 

Kader acımadı yar ikimize 

Senin gibi bir yar nerde bulum ben 

Çok zahmetir sensiz daha gülüm ben', 'Ayrılma yar, Sen yoksun her günüm geçiyor ak''tan Seni aramaktan düştüm ayaktan Gözlerimde kör oldu kan ağlamaktan  Senin gibi bir yar nerde ...', ARRAY['Türk Edebiyatı','Şiir','Diler Kasap']::text[], 8.5, '{"poet":"Diler Kasap","poet_slug":"diler-kasap","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilma-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Hiç Olmamıştık', 'biz-hic-olmamistik-turgut-baki-6mr6m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'özlem türkülerinin tuzu ile kavrulmuş dilim lal olmuş

sensiz sabahlara sensiz düşlerle uyanmak zor

bağlandı kalemin elleri

kelimeler öksüz

imgeler küs

sustu sevinci yüreğimin sen düşlerimi terk edeli

bugün değilse yarınlar yok artık

sen yoksun

ben yok

biz hiç olamamıştık zaten.', 'özlem türkülerinin tuzu ile kavrulmuş dilim lal olmuş sensiz sabahlara sensiz düşlerle uyanmak zor bağlandı kalemin elleri kelimeler öksüz i...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/biz-hic-olmamistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin kadehinde', 'senin-kadehinde-kader-budur-wozd0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin kadehinde ben

Benim kadehimde sen

İçtiğim her damlada yine sen

Kanında dolaşan alkol

Bütün bedeninde yine ben', 'Senin kadehinde ben Benim kadehimde sen İçtiğim her damlada yine sen Kanında dolaşan alkol Bütün bedeninde yine ben...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senin-kadehinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odur', 'odur-kader-budur-tuvjz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Odur bilinmezlik

Gözlerindeki pırıltı

Ellerinde sıcaklık

Onun dokunuşu titretir benliğini

Sıcaktır sevgisi

Senindir herşeyi', 'Odur bilinmezlik Gözlerindeki pırıltı Ellerinde sıcaklık Onun dokunuşu titretir benliğini Sıcaktır sevgisi Senindir herşeyi...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/odur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-bekir-necati-3o9sz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne o öyle 

Sevda fakiri gibi 

mutsuz, umutsuz 

İndirmişsin tüm yelkenleri 

Açıl, bir isyan bayrağı gibi 

Sal kendini günün, kaçak sularına 

Çık artık, 

sandık odasında 

sakladığın geçmişinden 

Bırak şimdi tarihçeni yazmayı 

Dediğin gibiyse şayet –den beri 

en güzel başlangıç ise–merhaba 

en güzel dilek ise –görüşürüz 

en güzel beklenti ise –ara beni 

en güzel korku ise –eyvah 

en güzel duygu ise –aşk 

Sen daha bekleye dur, 

Ardı arkası kesik 

düşsel gecelerde 

ha gelir 

ha gelecek 

ha geldi 

-Kapı çalıyor, bakarmısın', 'Ne o öyle  Sevda fakiri gibi  mutsuz, umutsuz  İndirmişsin tüm yelkenleri  Açıl, bir isyan bayrağı gibi  Sal kendini günün, kaçak sularına  ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beklenen-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim', 'o-benim-kader-budur-r9m62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resimler dizilmiş duvarlara

Hepsisinde bir şeyler yaşanıyor

Belki gizli farklı hayatlarda

Sadece belki birinde ben yazıyor

Karşı duvarda bir savaş

Kanlı kırmızı çizgisiyle

Onun yanındakinde gizli bir aşk

Sanki o ben ellerimde kırmızı güllerle

En ötede bir deniz

Parlak mavi dalgalarıyla

Tam karşısında kumsalda sevişen çiftler gölgede

Sanki o benim erkeğinin gövdesinde

Sağ duvarın köşesinde bir ağıt

Çizilmiş en derin duygularıyla

Onun solunda bir anıt

Sanki o benim dikilmiş ağlıyorum başında

Gizli bir odaya giriyorum yine içinde resimler

Birinde bir cenaze var ölüsü gömülmekte

Dizilmiş insanlar sırayla gözleri matemlerde

Sanki o ben kefenler birlikte toprakla örtülmekte

Resimlerden biri düşüyor yere

Kırılıyor çerçevesiyle tuali birlikte

Alıyorum elime birleştirip düzeltmek için

Ama bakıyorum o benim 

Hayatım sanki parçalanan ellerimde

Bir daha düzeltilip tekrardan asılmayan resimlerde', 'Resimler dizilmiş duvarlara Hepsisinde bir şeyler yaşanıyor Belki gizli farklı hayatlarda Sadece belki birinde ben yazıyor Karşı duvarda bir...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/o-benim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-kader-budur-dr3o9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beddua deyip geçme dilimdeki kinime

Bu kin herşeyi incitebilir

Dünya kuruldu kurulalı bu sevgi

Ahirette cehennemi gösterir', 'Beddua deyip geçme dilimdeki kinime Bu kin herşeyi incitebilir Dünya kuruldu kurulalı bu sevgi Ahirette cehennemi gösterir...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beddua-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-refik-recep-pelit-cbfzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çekip  gitsen ırağa  dostluğumuz bakidir 

Dostun sana  gül dedi Gül''e gülmek yakışır 

Gülmeyi  bilmeyenin  yüzü çabuk  kırışır 

Arayanlar arasın  dostluğumuz  başkadır 

Yüzüne yaşlar değil tebessümler erişsin 

Bil ki küskünüm  diyen  yalnız sen de değilsin. 

Dostluğumuz  önünde cümle  alem eğilsin. 

Muhabbet den almayan bakıp erkan öğrensin. 

Görmekten bi-haberin  yitik us''un da gıda 

İçine ne gerek baksınlar birkez aynaya 

Yaşamasın dünyayı beyhude ve bedava 

Arayan elbet bulur Mevla gibi belada 

Dostun  buruk  sözleri  muteberdir  biliriz 

Dost yürekli  yüzleri  gözlerinden  seçeriz

Cismen  uzak olsak da aslında beraberiz. 

Şiirler de  değil  lakin gönüller de salihiz. 

Neşeni  bozamasın  ömrünce  fesat yüzler 

Gidiyorsun ya artık yürek  elemle sızlar 

Belki  gelmeyeceksin  dostun  beyhude gözler 

Yüze  gülen  yüzleri  gönül ömrünce bekler 

Bize  neşe  kattın  vakıf olduk  sözlerine 

Ay kadar  pırıltılı  selam olsun yüzüne 

Kıskanç  ahmakların  dursun gözüne  dizine 

Arada  bir ara hasret bırakma sesine 

Olmaz olurmu? gülmek yakışmış da dostuma 

Çıkamaz  cahil olan muhabbetin üstüne 

Vasfı  cahil cümle alem ömür boyu dövüne 

Kurbanız  dost''luğunun kuzusuna  postuna

Dostum Hakkı Hakan Kaya''ya İthaftır.', 'Çekip  gitsen ırağa  dostluğumuz bakidir  Dostun sana  gül dedi Gül''e gülmek yakışır  Gülmeyi  bilmeyenin  yüzü çabuk  kırışır  Arayanlar ar...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dostuma-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismarlama Künefe', 'ismarlama-kunefe-refik-recep-pelit-ya8uh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaybettim sanma sakın kazanan aslında benim, 

Ruhum güler aslında, dans ederken bedenim, 

Künefeyi ısmarlayan mutlak ki dost olmalı 

Sen ağzına atar iken sararırken solmalı. 

Hakkı ile yenecekse içine fıstık koymalı, 

Seyreden gafilden önce,muhatabı doymalı. 

Künefe dediğin nedir? olsun sana tepsi feda, 

Dost yüzünü göreyim, çıkarmamki ses seda 

Elbet sende ısmarlarsın,Künefe olmazsa samsa 

Tatlı olsun gönlümüz,kimseye kalmaz bu dünya. 

Künefenin lezzetlisi,ahbaplarla iken yenir, 

Künefeyi söyleyene,geçmiş olsun mirim denir. 

Zevkin kadim olsun,durup seni seyrederim. 

Sende kaybedersin elbet,o günde ben sendenim.

Kadim Dostum, Değerli Şahsiyet Hakkı Hakan Kaya Kardeşime İthafır.

Tarihinde Bir kere''de olsa oynadığımız bilardo karşılaşması neticesinde kazandığı Künefe Tatlısının şerefine kendisine ithaf edilmiştir.En azından artık Künefenin tadının neye benzediğini bilmesi açısından güzel bir gelişme.', 'Kaybettim sanma sakın kazanan aslında benim,  Ruhum güler aslında, dans ederken bedenim,  Künefeyi ısmarlayan mutlak ki dost olmalı  Sen ağz...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ismarlama-kunefe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Sofrası*', 'sair-sofrasi-ensar-aktas-yfvit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sofra kuruldu onsekizbinbirinci alemde**

Tam bir Halil İbrahim sofrası bereketinde

Buraya dostlar yemeye değil ikram etmeye oturur

Ağlatmaya değil mahzun yüzleri güldürmeye koşulur

Herkese yer var, Tanrı misafiri nasibiyle gelir

Yunus''un sevgi seli, Mevlana''nın dergahı gibidir

Sanki zemheri ayazında toplanıyor dostlar tandır başına

Kucaklanıyor herkes bakılmaksızın dil, din, ırk, yaşına

Mürşitler bağdaş kurup dizeleri dem dem tespih çekiyorlar

Kıbleye dönüp hoşgörü şerbetini zemzem gibi içiyorlar

Sevgiyle kaynıyor kazanlar, aşk ateşinde gündüz gece

Acılar da paylaşılıyor, sevinçler de. Şekil tam bir imece

Mürit Ensar da diler ki birazcık tuzu olsun bu çorbada

Baş köşede gözü yok, diz çöküp otursun kapı kenarında

-------

* Şair Sofrası = Antoloji.com''da şiirleri bulunan yüzü aşkın şairin üyesi olduğu, ismini Fatih Karataş dostun aynı başlıklı bir şiirinden almış bir Yahoo mail grubudur. Geniş bilgi için http://sairsofrasi.sitemynet.com/siir/  linkini ziyaret edebilirsiniz.

Doğrudan üye olmak için moderatör İsmail Cem Doğru dostumuza bir email yazabilirsiniz. Email adresi: [email protected] Tüm şair/şaireh dostlarımızı soframıza bekliyoruz.

** Onsekizbinbirinci alem = Sanal alem

Rotterdam, 09-12-2003', 'Bir sofra kuruldu onsekizbinbirinci alemde** Tam bir Halil İbrahim sofrası bereketinde Buraya dostlar yemeye değil ikram etmeye oturur Ağlat...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sair-sofrasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenti', 'beklenti-gulsen-senderin-2k34m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önceleri bir bebek gül bebekti beklenti

Gül memede aksüttü tek emmekti beklenti

Sicacik bir sinede sevilmekle uyumak

Acildikca kundaklar sariyordu eklenti

Ciglik ciglik solurken büyüyordu beklenti.

Bahar cicek yaz meyve hasatlarda söylenti

Aza cogu ekleyip topluyordu beklenti

Kah firtinada sevinc kah özünde büyümek

Sacildikca bolluklar ariyordu eklenti

Daglik daglik yükselis pariltiydi beklenti.

Cobanin kavalinda yanik türkü beklenti

Dillerin kilicinda dilden ürktü beklenti

Yollara düsürdünse toz dumani solumak

Kisa kalmak istemez tez zamana eklenti

Baglik baglik acarken yasiyordu beklenti.

Bazan dar vakitlerde aciyordu beklenti

Ufukta gölgeleri terkedisti beklenti

Silinen o renkleri acisiyla boyamak

Yarali gönüllere sevgi kalbe eklenti

Soluk soluk yüzlerde ölümdeydi beklenti.', 'önceleri bir bebek gül bebekti beklenti Gül memede aksüttü tek emmekti beklenti Sicacik bir sinede sevilmekle uyumak Acildikca kundaklar sar...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beklenti-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim İstanbul''dan', 'giderim-i-stanbul-dan-gulsen-senderin-0io69', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgisi unutulmuş, bu kalbin sitemiyle

Gel desen de gelemem giderim İstanbul''dan

Müsveddesi tutulmus; aşkımın matemiyle

Kal desen de kalamam giderim İstanbul''dan! 

Sahilde martıların çığlıkları sevgimiz

Boğazda köprülerin ışıltısı sanki biz

Mehtapta yakamozlar aşkımızdan birer iz

İstesen de kalamam giderin İstanbul''dan! 

Adına çiçek açan bulutlar şimdi siyah

Alaca karanlıklar ağarır olur sabah

Aşkı sevgi büyütür yüreğin dolsa da ah

Kal desen de kalamam giderim İstanbul''dan! 

Yaralayan gururla seni her dem bekledim

Çaresiz özleminle derdime dert ekledim

İçimdeki hisleri, anılarla denkledim

İstesen de kalamam giderim İstanbul''dan! 

Sinemdeki ateşin kalmaya zorlasa da

Eriten o gülüşün tenimi korlasa da

Ruhumu oksayisin kalbimde turlasa da

Kal desen de kalamam giderim Istanbul''dan! 

Nerden çıktın karşıma sen kestin hep yolumu

Gelişin düğüm düğüm bil bağladı kolumu

Sensiz cana kıymadan yaşamadan ölümü

İstesen de kalamam giderim Istanbul''dan! 

DuygularIm karışık peşinden koşmak niye

Sevgilerim yaralar, sana vurgunum diye

Düşünceler sorgular ''aşkını bilmez niye''

Kal desen de kalamam giderim İstanbul''dan! 

Anılarla dopdolu sevdalar verdim sana

Mehtap olmak istedim gecelerken sen bana

Gerçek aşkla sevseydin gerek var mıydı buna

İstesen de kalamam giderim İstanbul''dan! 

İki dudak arası gizlenen o kelime

Hevesimi kırarken dolandı hep dilime

Zor muydu kavuşmamız nar''ı verdin elime

Kal desen de kalamam giderim İstanbul''dan! 

Ağlayışın boşuna düşünme artık beni

Senle bir hiç uğruna kuramadık düzeni

Şimdi pişman değilim anmam asla bil seni

İstesen de kalamam giderim İstanbul''dan! 

Bakırköy kalabalık sokaklarda yürünmez

Baş edilmez düzende ufuk sisli görünmez

''Mektup Kuşları'' bize aşkı taşır yerinmez

Kal desen de kalamam giderim İstanbul''dan! 

Hani en güzel kadın en derin aşktı Gülşen

Zekice tuzaklardan bir fırtınaydı esen

Şimdi büyü bozuldu sensizliğe mahkum ben

İstesen de kalamam giderim İstanbul''dan! 

İstanbul yedi tepe; aşk döngüsü karmaşa

Kader ağını örer bakmaz gözdeki yaşa

Ne armağan ne sevgin, kalbim boş yol Kıbrıs''a

Kal desen de kalamam giderim Istanbul''dan! 

Bir gidişin ardından sevgi kat kat çoğalır

Gidene yeni dünya, kalana kor yığılır

Aşkın hası vurunca; baş bükülür eğilir

İstesen de kalamam...Giderim Istanbul''dan! ! !', 'Sevgisi unutulmuş, bu kalbin sitemiyle Gel desen de gelemem giderim İstanbul''dan Müsveddesi tutulmus; aşkımın matemiyle Kal desen de kalamam...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/giderim-istanbul-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yanımı Sana Sakladım', 'bir-yanimi-sana-sakladim-yasar-pullu-2wcp5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne ağıtlar yaktım sana

Ne türküler ezberledim

Hayatımın en uzun çizgisiydin oysa.

Ben seni ülkem gibi sevdim

Aras gibi coşkulu, Aras gibi deli sevdim.

Taştan taşa vurdum kendimi

Parçalanmadı başım

Ben seni halkımın çalınmış buğdayından

Ekmek gibi sevdim

At sırtında değirmene giden nasırlı elleri sevdim

Karlı dağları sevdim

Kurt girmemiş bağrına 

Çakal görmemiş

Eridim.

Volkan oldu yüreğim

Ağrı’dan yuvarlandım

Diyadin’e doğru

Parçalanmadım.

Fırat tuttu ellerimden

Kanlı derler ya fırat için katil derler

Tümden yalan.

Köpüklere karıştım

Çekirdekle savaştım

Tohumlarla barıştım

Acıdıkça yüreğim

İnsan oldum

Kanımı pazarladım şişelerde

En diri yanımı sattım

Hastayım

Yağmur yağdı kaçtım

Ayaz kesti

Tipiye yakalandım

Ben en amansız gecelerde sana sarıldım.

Pişmemiş cümleler yuttum

Çiğ duruşlar

Ağladım

Isllattım 

Yumuşattım

En sivri uçları

Bir yanımı bıçaklara verdim

Kanattım

Bir yanımı sana sakladım.

12/12/2003', 'Ne ağıtlar yaktım sana Ne türküler ezberledim Hayatımın en uzun çizgisiydin oysa. Ben seni ülkem gibi sevdim Aras gibi coşkulu, Aras gibi de...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bir-yanimi-sana-sakladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
