INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyden Var Biraz', 'her-seyden-var-biraz-turgut-baki-mh2o7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aklıma sen düştün ya

yine sahile indim bu gece

gecenin bir yarısı

kız kulesi

dalgalar

martılar

ben 

ve birde sarhoş balıkçılar

ama ille de aklımda sen

gerisi umurumda da değil zaten

hep merak ederim 

şu sarhoş balıkçıların 

gamları yok mu ki hiç

altlarında kayık

ellerinde şarap

uyup dalgaların ritmine

içip sallanıyorlar

benim kayığım yok

kayık alacak param da

şarap bulabiliyoruz şükür

gamsa üstümde paralanmış bir urba

sen aklıma düşeli

denize gelince 

zaten bütün denizler benim

yani demem o ki

demediğim de dahil

her şeyden var biraz 

var da

bir tek sen yoksun

gerçi hiç olmadın ki

niye dertleniyorsam', 'aklıma sen düştün ya yine sahile indim bu gece gecenin bir yarısı kız kulesi dalgalar martılar ben  ve birde sarhoş balıkçılar ama ille de a...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/her-seyden-var-biraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adım da', 'bir-adim-da-kamil-aydemir-9dduz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benim pokimonlarım olmadı bilyelerim de

sığınacak yer ararım akşam karanlığında

gizli gizli ağlarım özlemlerim saklıdır gözyaşlarımda

gözyaşlarım ki diken gibi durur yanaklarımda

annemi görürüm çocuğunu okşuyan her kadında

sevinçlerim uçup gitti

   ipini yaşama kaptırdığım uçurtmanın kanatlarında

sokak çocuğudur benim bir adım da

istreim ki hüzün değil sevgi koksun sözlerim

akşam karanlığında

   camlarında sarı çiçekler açan evleri özlerim

kimsesizliği paylaştığım arkadaşlarımın bekçisi olur gözlerim

bir duvarın dibinde kıvrılır yatarım

karanlık gökyüzünü de yorganlığa üzerime atarım

yine de sabahlara umut dağıtırım

sokak çocuğuyum ben bir hiç yerine koysan da sen

sen sıcak yuvanda anan baban yoknunda

bense acımasız sokakların kanlı dişlerinde

oyuncağı olmamak için ölümün kefili olurum ömrümün

ateş böceğini tanırken

  ve suçlusu olmadığım halimden utanırken

yarasaya özendiğimi sanmayın

üzmemek için sizleri mutluluk rolüme kanmayın

benim yaram sevgiler büyüttüğüm yüreğimde

kokrmayın kirlenmez elleriniz tutun ellerimizi

bana bir günlüğüne ödünç verir misiniz gülücüklerinizi

açlık mı doldurur sizin de ruyalarınızı

yağmura yıkatmayı hiç ister miyiz uykularımızı

niçin aşağılarsınız gördüğünüz yerde bizi

kirleten biz değiliz ki dünyamızı', 'benim pokimonlarım olmadı bilyelerim de sığınacak yer ararım akşam karanlığında gizli gizli ağlarım özlemlerim saklıdır gözyaşlarımda gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-adim-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim Yeşilim', 'dort-mevsim-yesilim-burcu-karakaya-c00mk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül kondu dalına

Konmadan önce sordu yarına

Beklenen ''aşk'' ben miydim...

Kesin cevaplardan, keskin düşlere

Geçmişteki cehennemden,

Gelecek cennetine,

Evet dedin erkekçe...

Beklenen cevap buydu,

Beydağları civarında ki yalnızlıklarda...

Ben de ne buldun diye sordun,

Geldi cevap 

İnceden bir fısıltı oldu sesim,

Ağacımsın sen benim,

Dört mevsim yeşilim,

Her yaprağında kazınmış ismim,

Dökülsen de 

Toprağım oldun...

22/12/2003

C.Burcu Karakaya

Antalya', 'Gönül kondu dalına Konmadan önce sordu yarına Beklenen ''aşk'' ben miydim... Kesin cevaplardan, keskin düşlere Geçmişteki cehennemden, Gelecek...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dort-mevsim-yesilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonk Vurdu', 'gonk-vurdu-vedat-koparan-nxthl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üşüyorum, Üşüyorum 

Düşüyorum 

Gecenin koynundan 

Gün açımı güneşe 

Düşüyorum 

Zindan karası gözlerine 

Zindandayım 

Hüzünüm benim, hüznüm 

İki gözüm can özüm 

Ateşi körükleyin çocuklar 

Ocakta/yım 

Yanan aşım 

Aşkım 

Tenim

Sızım

Yangınım 

İç kanamada 

Ah yaram

Sol yanım 

Ateşi körükleyin çocuklar 

Daha, daha da /dağ,dağla/ çağ,çağla

Sahradan geçtim 

Ağustosta buz kestim 

Üşüyorum 

Ateşi körükleyin çocuklar 

Bir bulut yağmur kaçağı 

Dört mevsim 

Ağlıyor 

Zaman geldi geçti bile 

Işık, ışık daha 

Yetmiyor 

Renklerde üşüyor 

Kelebek can havlinde kanatları titriyor

Karanlık, karalığın içinde

Mavi bir bulut 

Kuşlarla kanat çırpıyor 

Güneş mavi bulutu öpüyor 

Gözlerin geliyor üşümelerime

Gonk vurdu 

Saati veriyorum 

Kaldırın başlarınızı 

Yırtın gecenin karanlığını 

Anılara gözlerimi kapar kapamaz 

Ölüyorum

Bitmedi…

Vedat Koparan 16.12.2003', 'Üşüyorum, Üşüyorum  Düşüyorum  Gecenin koynundan  Gün açımı güneşe  Düşüyorum  Zindan karası gözlerine  Zindandayım  Hüzünüm benim, hüznüm  ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gonk-vurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağdanlık', 'yagdanlik-vedat-koparan-14bo4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Yaşamın içinde bir argo) 

Usta dedik dimi yani 

“Olur mu kırk yıllık kani”

Bak şu velede 

Oradan nasılda sırıtıyor 

Güz üşümelerinde yalancı güneş 

Ellerini ovuşturan 

daha fazla kar diyen burjuva sanki

hadi ordan sümüklü sömürülen 

Ne sırıtıyon ulen dıngıl davran

Pas tutanları ver gaza 

Bitmez ki; 

Bak yağlanacaklar var 

Yağdanlığı getir dedi usta…

Ohh be misler gibi koktu da

Ah be köfte kebap 

Yede yanında birde piyaz iste

Piyazlanacaklar adına

Aman be kestane de kebap 

Gel de ye olsun sebap

Dumanı kokusu bedava..

Hadi aç mantarı basma sakın yaşa

Ne mantarı ulen kaldı mı ki 

Her şey oldu naylon her şey madara

Dalgamı geçiyon adam mı seçiyon

At bıçağı kes şunun kafasını da 

Dikelim tepemize bakalım keyfimize

Dostlar alış verişte

Görsünler 

İşler ayna çal,çal oyna 

ülke hallerinden binbir manzara..

''İki oyuna bir biletti 

Şimdi dördü beşi bir yerde

Alınca eve gelince 

Açarsın paketi 

Girince ayak içine 

Parmaklar dışarı fora ''

Sırıtma len sırıt/ma işte fos

Aklıma getirme aptallığımı

Ne susak ne kapçık ağızlısın

Olmayacak dimi açmasan şom ağzını 

Kısadan hisse dürelim sözü başka şiire..

Sevgiler her dem maviye..

Vedat.K 18.12.2003 (05.13)', '(Yaşamın içinde bir argo)  Usta dedik dimi yani  “Olur mu kırk yıllık kani” Bak şu velede  Oradan nasılda sırıtıyor  Güz üşümelerinde yalanc...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yagdanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babamın Anlattıkları', 'babamin-anlattiklari-gokhan-oflazoglu-dyzfd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babam, yapayalnız bir adamdı hiç çıkmazdı evden; 

yalnız işe giderdi, akşam eve dönerdi hemen.

Hoşlanmazdı insanlardan, şüpheyle bakardı çokca.

Bizse bir şey anlamazdık babamın anlattıklarından.

Erkence yaşta öldü, bizim içinde onun içinde.

Sonra araya hayat girdi; pek de haksız sayılmazmış,

insanlar bunu bize öğretti. Selam, baba, her nerede

yer alıyorsan ötede ya da yoklukta. İnsanlar kırıp, 

dökmede aynı umursamazlıkta ve hep böyle olacak

galiba. Boşver, baba, hayatta güzel şeyler de var daha.

                                                          09/12/2003', 'Babam, yapayalnız bir adamdı hiç çıkmazdı evden;  yalnız işe giderdi, akşam eve dönerdi hemen. Hoşlanmazdı insanlardan, şüpheyle bakardı çok...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/babamin-anlattiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilgilenme', 'bilgilenme-gokhan-oflazoglu-oxka5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çığlığın nice katmanlarından oluşur

içindeki ürperti; ışığın sağılmasıdır

kopkoyu karanlıklardan. Tükenir yüzünün

bir yanı, diğer yanını çevirirsin günün

hoyratlıklarında ve isteğin yalçın kayalardır

dönülmeyen ufuklarda. Hayatı en derinde

kavrarsın; gündüz bir armağan gibi açılır

önünde, sen yiterken yalnızlık uçurumlarında.

Bütün bilgilerin yoğunlaşır; bir titreme süresince

yeni bilgilere gebedir hala, insanların çoktandır

türkülediği ve sınırlı imkanlarla. Arınır duyguların

sıkça yinelenen bu dile gelmez masalda. Daha

ötesi kapalı bildik duyarlıklara.

22/12/2003', 'Bir çığlığın nice katmanlarından oluşur içindeki ürperti; ışığın sağılmasıdır kopkoyu karanlıklardan. Tükenir yüzünün bir yanı, diğer yanını...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bilgilenme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul’da Hava*', 'i-stanbul-da-hava-bayram-tunca-ibsip', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün burada sanki, yazdan kalma bir hava 

Her kim olsaydı o da gelirdi benim gibi tava 

Gerdan olmuş gökkuşağı İstanbul Boğazına 

Hayranıyım onun taşı toprağı havası suyuna 

Yankılanıyor martıların sevinç çığlıkları kıyıda 

Cazip olmasaydı, çekebilir miydi bizleri bunca

Bak gerdan olmuş köprüler İstanbul Boğazına 

Hayranıyım onun taşı, toprağı, havası, suyuna 

Fırsat buldukça, yedi tepesinden temaşa ettim 

Her bir tepesinden ayrı ayrı güzellikler gördüm 

Gördüğüm o güzellikler karşısında, büyülendim 

Onunla olan göbek bağımı, sımsıkı düğümledim 

Gezdim cihanı, bulamadım ondan daha güzelini 

İstanbul medeniyet beşiği/Anadolu’nun mozayiği 

Neyleyim elin güzelini, bana yeter onun güzelliği 

Beyhude aramayın bulamazsınız İstanbul gibisini 

20.12.2003-12.20', 'Bugün burada sanki, yazdan kalma bir hava  Her kim olsaydı o da gelirdi benim gibi tava  Gerdan olmuş gökkuşağı İstanbul Boğazına  Hayranıyı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-da-hava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakınamadım', 'sakinamadim-murat-onat-3d2y7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep vitrinlerdeydi oyuncaklarım

dokunamadım

Sıkıntılar içimden geliyordu,

yakınamadım

Bakışları serseri bir kurşundu,

sakınamadım

Vuruldum, düştüm bir  acı sondu,

kaçınamadım', 'Hep vitrinlerdeydi oyuncaklarım dokunamadım Sıkıntılar içimden geliyordu, yakınamadım Bakışları serseri bir kurşundu, sakınamadım Vuruldum, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Onat']::text[], 8.5, '{"poet":"Murat Onat","poet_slug":"murat-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sakinamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin İzleri', 'gidisin-i-zleri-gulay-yildiz-llzr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yere serdim bebeklerimi

Oyun bitti farkındayım

Zaman bırakıp gitme zamanı

Acı; 

Tarifi imkansız olanlarından yüreğimdeki

Hüzün; bebeklerimden adımlarca uzakta,

Özlem; oyunsuz kalışların tekleyen atışlarında...

Esaretse, hüznün esareti dağılan damarlarıma

Takip ettiğin gölgem  ve izleri karanlıktaki

Gidişim, kalanların acısının esaretine düşmüş

Umudum, ucsuz bucaksızın sonunda,

Bebeklerimle bekleyen ışıkta...', 'Yere serdim bebeklerimi Oyun bitti farkındayım Zaman bırakıp gitme zamanı Acı;  Tarifi imkansız olanlarından yüreğimdeki Hüzün; bebeklerimde...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidisin-izleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazi Derinde Yara', 'mazi-derinde-yara-abdulkadir-karaman-f7xlp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani, hatırlar mısın, elele gezdiğimiz 

Gelincik tarlaları aşkımızı saklıyor? 

İsimlerimizin ilk harfini yazdığımız 

O ağacın dibinde kâlbim hâlâ bekliyor. 

Unutulmaz ânların büyüsüne dalarak 

Gidip de gelmeyişine mâzeretler bularak 

Hayâller kura kura, heyecanla dolarak 

Özlemini rüzgarın şarkısına yüklüyor… 

Bu ayrılık bu aşkı körükler de yıkamaz 

Yüzün sinmiş kalbime, ölsem bile çıkamaz 

Canımı hiçbir ateş, aşkın kadar yakamaz 

Kül etse de, yanmaya gözlerini bekliyor…. 

Kelebekleri bile kıskandıran süzülmen 

Gitmiyor hayâlimden, nazlanman, küsmen, gülmen… 

İmkânsız olsa bile sonsuza kadar gelmen 

Yüreğim usanmadan umutları yokluyor. 

Bütün kabâhat senin, diyorum yüreğime 

Suçlu aramak boşa, kızıyorum kendime 

Solan resmini alıp kanla dolan elime 

Sensizlik zehri her an yüreğimi okluyor… 

02.07.03', 'Hani, hatırlar mısın, elele gezdiğimiz  Gelincik tarlaları aşkımızı saklıyor?  İsimlerimizin ilk harfini yazdığımız  O ağacın dibinde kâlbim...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mazi-derinde-yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Asla', 'sensiz-asla-murat-demir-rrji3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diyorsun acıma bana

Dayanamam ağlamana

Bu dert benim kaderimdir

Bakma bana yana yana 

Senin için ölmek varken

Yana yana bakarmıyım

Yüreğim böyle kanarken

Senden fazla yaşarmıyım

Bir elmanın yarısı ben

Yarısı sen kadersizim

Ne kendime nede sana

Acıyorsam şerefsizim

Bunu bil ki ben seninle

Gülersen gülmeye varım

Kaderinle,kederinle

Yanarsan bende yanarım

Benim sana senin bana

Gereği yok acımanın

Beden benim can senindir

İmkanı yok ayrılmamın', 'Diyorsun acıma bana Dayanamam ağlamana Bu dert benim kaderimdir Bakma bana yana yana  Senin için ölmek varken Yana yana bakarmıyım Yüreğim b...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensiz-asla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın Gibi', 'sen-varsin-gibi-oguzkan-bolukbasi-cc9nz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hal böyleyken şekerim

Baştan başlamaya gerek yok 

Yeniden yaşamak zor aynı hayatı

Rolleri değişmek mümkün olsaydı

Ve hatta yerleri

Silseydik bellekleri

Aynı hayalde bana rastlasaydın

Günleri 

Beyaz nevresimlere sarıp 

Serer miydik ak çarşafları

Yatılmamış yataklara

Dalıp 

Gidiyorsun 

Uzun yolculuklardan dön artık

Bayraklar astım geçeceğin sokaklara

Fakat sevgilim

Şaraplar eskidi mahzenlerde

İlk günkü gibi değil 

Damaklarımızda  kalan tadı

Yüzümüzdeki çizgilerde

Yaşanmışlıklar

Yaşanmamışlıklar 

Asılı kaldı

Yarım bırakılmış bir hikayenin sonunu

Merak etmiyorum

Ayrılıklardır bu yarım bırakılmışlıklar

Ben kendi istediğim gibi anlatacağım

Olmasını istediğim gibi

Tüketilmemiş özlemleri

Renklere boyayacağım

Oyalanacağım

Çünkü sensizlik

Öylesine bir sessizlik ki

Öylesine bir hevessizlik ki

Güneş ufukta hep batıyormuş

Gibi geliyor bana

Saygısızlık olmasın diye hatırana

Odamın ışıklarını yanık tutuyorum

Karanlıktan korkardın

Işık gördüğüm her yerde sen vardın

Beni bilmediğim kentlerde

Kör bıraktın

Hal böyleyken şekerim

Baştan başlamaya gerek yok', 'Hal böyleyken şekerim Baştan başlamaya gerek yok  Yeniden yaşamak zor aynı hayatı Rolleri değişmek mümkün olsaydı Ve hatta yerleri Silseydik...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sen-varsin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşte Gör', 'duste-gor-hifzi-ozbekmez-ip48b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyi günde herkes sana dost olur

Kötü günde kara toprak  post olur

Sakın düşme dost bildiğin mest olur

Hayalde gör rüyada gör düşte gör

Baharda gör yazda gör kışta gör 

Gerçek dostu dostum sende düşte gör 

Düştüğünde kötü gözle bakılır

Can olsanda nice lakap takılır

Bal olsanda yine senden bıkılır

Hayalde gör rüyada gör düşte gör

Baharda gör yazda gör kışta gör 

Gerçek dostu dostum sende düşte gör 

Defterinden silip seni atarlar

Hatırını beş paraya satarlar

Bir derdine bin dert daha katarlar

Hayalde gör rüyada gör düşte gör

Baharda gör yazda gör kışta gör 

Gerçek dostu dostum sende düşte gör 

Hıfzıyım göz yaşlarım sel olur

Nice dost bildiklerin hep el olur

Geride bir can bir canan kalır

Hayalde gör rüyada gör düşte gör

Baharda gör yazda gör kışta gör 

Gerçek dostu dostum sende düşte gör 

2002', 'İyi günde herkes sana dost olur Kötü günde kara toprak  post olur Sakın düşme dost bildiğin mest olur Hayalde gör rüyada gör düşte gör Bahar...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duste-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ettiklerin', 'ettiklerin-hifzi-ozbekmez-u9bfw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarım seller etti

Gurbet eli yollar etti

Artık canımada yetti

Senin bana ettiklerin

Güldürmedi hep ağlattı

Ciğerlerimi dağlattı

Sevincime zehir kattı

Senin bana ettiklerin

Dertler verdi hep başıma

Su kattı pişen aşıma

Bakmadı gözüm yaşına

Senin bana ettiklerin

Latifiyim böyle kader

Verdi bana elem keder

Koca ömrüm etti heder

Senin bana ettiklerin

2002', 'Göz yaşlarım seller etti Gurbet eli yollar etti Artık canımada yetti Senin bana ettiklerin Güldürmedi hep ağlattı Ciğerlerimi dağlattı Sevin...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ettiklerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Ha', 'sakin-ha-murat-demir-54zeh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oyun içinde oyun

Oynama kız başıma

Acıyı ben hiç sevmem

Biber katma aşıma

Yakacaksan kalpten yak

Dilimden ne istersin

Dil yüzünden yanarsan

Kahrolsun dilim dersin

Durma karşımda durma

Yorulursan düşersin

Kız sevda ateşine

Sakın düşme pişersin

Akıllı ol uslu dur

Alma sevdadan yara

İçinden çıkamazsın

Yara düşürür dara

Kalp ağrısı fenadır

Benim gibi olursun

Demedin deme bana

Düşme ki kahrolursun

Becerirsen uzaktan

Platonik aşk yaşa

Ona buna bakıpta

Dert alma dertsiz başa', 'Oyun içinde oyun Oynama kız başıma Acıyı ben hiç sevmem Biber katma aşıma Yakacaksan kalpten yak Dilimden ne istersin Dil yüzünden yanarsan ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sakin-ha-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-hifzi-ozbekmez-r5x2o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ömür boyunca çektiğim çile 

Bir gün biter diye kandım ağladım

Allah dertler vermiş bülbüle bile 

Benim dertlerim çok sandım ağladım

Bir güzel sevmiştim kaşları kara

Açmıştı bağrımda kapanmaz yara

Yolum düştüğünde ah o diyara

Maziyi yad ettim yandım ağladım

Koca bir ömür çektim hep cefa

O nazlı yardanda görmedim sefa

Umudum yok artık gülmem bir defa

Sonunda divane oldum ağladım

Latifi söylerde yanıyor özüm

Kış oldu daima baharım yazım

Garibim mezarım derince kazın

Kimsesiz ortada kaldım ağladım

2003', 'Bir ömür boyunca çektiğim çile  Bir gün biter diye kandım ağladım Allah dertler vermiş bülbüle bile  Benim dertlerim çok sandım ağladım Bir ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/agladim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara, Bul, Şem''anı Yak Da', 'ara-bul-sem-ani-yak-da-seyrani-d5sfh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ara, bul, şem''anı yak da

Su gibi engine ak da

Ne tırnak idim ayakta

Ne taç gibi serde idim

Ne martıyım bahre daldım

Ne dili ummana daldım

Ne er gibi avret aldım

Ne zen gibi erde idim

Mahremiyim hak razının

Makesiyim âvazının

Âlem-i ervâh sazının

Kolunda bir perde idim

Seyrânî kader göçünde

Ne bir iki ne üçünde

Âlem-i ervâh içinde

Himmetli bir pîrde idim', 'Ara, bul, şem''anı yak da Su gibi engine ak da Ne tırnak idim ayakta Ne taç gibi serde idim Ne martıyım bahre daldım Ne dili ummana daldım Ne...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ara-bul-sem-ani-yak-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostumdur Benim', 'dostumdur-benim-hifzi-ozbekmez-da9un', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Menfaat hiç beklemeyen

Derdime dert eklemeyen 

Benden sırrın saklamayan

İnsanlar dostumdur benim

Doğruluktur daim özü

Baldan tatlıdır hep sözü

Bağrında dostluğun közü

Yananlar dostumdur benim

Sevdiğinde tam sevecek

Dostun yoluna ölecek 

Benimle ağlayıp gülecek

Olanlar dostumdur benim

Latifiyim ahu zarda

Hem zararda hem de karda

Hem gurbette hem diyarda

Sevenler dostumdur benim

2003', 'Menfaat hiç beklemeyen Derdime dert eklemeyen  Benden sırrın saklamayan İnsanlar dostumdur benim Doğruluktur daim özü Baldan tatlıdır hep sö...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostumdur-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardır', 'vardir-hifzi-ozbekmez-dy7ik', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapılmam deme hiç güzel gözlere

Güzel göz uğruna yananlar vardır

İnanmam deme hiç tatlı sözlere 

Bir çift söz uğruna kananlar vardır

Bir ömür boyunca çekse de çile

Hasret gurbet ile dönse de  küle

Sevdiği vefasız olsa da bile

Yolunu bekleyip ölenler vardır

Bahtındaki yazı kara olsa da

Yalan ömrü boştan yere dolsa da

Sevda gülü daha baştan solsa da 

Bir gün elbet açar sananlar vardır

Latifi de söyler gözü dolarak 

Hasret çeke çeke benzi solarak

Vefasız birine köle olarak

Sevda yollarında kalanlar vardır

2003', 'Kapılmam deme hiç güzel gözlere Güzel göz uğruna yananlar vardır İnanmam deme hiç tatlı sözlere  Bir çift söz uğruna kananlar vardır Bir ömü...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vardir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Vapurunu İcat Edenler', 'ates-vapurunu-i-cat-edenler-seyrani-8dckw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateş vapurunu icat edenler

Yelken açıp yel kadrini ne bilsin

Süleyman''dır kuş dilini söyleyen

Her Süleyman dil kadrini ne bilsin

Hayvanlarda bir kaç çeşit fırkalar

Kimi düzden aşar kimi yorgalar

Necasete müştak olan kargalar

Has bahçede gül kadrini ne bilsin

Seyrani Baba''nın beli büküldü

Ağzının içinde dişi söküldü

Davut Nebi sadasından çekildi

Saz çalmayan tel kadrini ne bilsin', 'Ateş vapurunu icat edenler Yelken açıp yel kadrini ne bilsin Süleyman''dır kuş dilini söyleyen Her Süleyman dil kadrini ne bilsin Hayvanlarda...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ates-vapurunu-icat-edenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Güzel', 'esmer-guzel-hifzi-ozbekmez-sum7o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyle  senin yollarına 

Öleyim mi  esmer güzel

Sen çağırmadan sana 

Geleyim mi esmer güzel

Gel öyle eğme başını

Omzuma yasla başını

Akan inci göz yaşını

Sileyim mi esmer güzel

Kurban olam bitsin nazın

Bahar olsun kışım yazım

Dertli nağme çalan sazın 

Olayım mı esmer güzel

Hıfzı derki yok mu çare

Aşkından oldum divane

Gurbet elde ben avare

Kalayım mı esmer güzel

2003', 'Söyle  senin yollarına  Öleyim mi  esmer güzel Sen çağırmadan sana  Geleyim mi esmer güzel Gel öyle eğme başını Omzuma yasla başını Akan inc...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/esmer-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aynaya Kılsam Nazar', 'bir-aynaya-kilsam-nazar-seyrani-dfc58', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir aynaya kılsam nazar

Sağ tarafım sol görünür

Padişahlar ferman yazar

Tatarlara yol görünür

Her ölüye olmaz tabut

Atlas eskir olur çaput

Olsa ak çuhadan kaput

Eskiyince çul görünür

Eğer Seyrânî''nin yâri

Olsa huri melek, peri

Gönül sevmedikten geri

Kız olsa da dul görünür', 'Bir aynaya kılsam nazar Sağ tarafım sol görünür Padişahlar ferman yazar Tatarlara yol görünür Her ölüye olmaz tabut Atlas eskir olur çaput O...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-aynaya-kilsam-nazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Tapıyorum', 'sana-tapiyorum-hifzi-ozbekmez-5i066', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni seviyor musun diye hiç sorma 

Sana tapıyorum sevmek ne demek

Böyle sorularla kafanı yorma 

Sana tapıyorum sevmek ne demek

Gözlerinden aldım aşkı ilhamı

Seven bilir ancak anlar o anı

Senin sorduğunda sorumu  yani

Sana tapıyorum sevmek ne demek

Aşkınla yanmışım oldum divane

Sensin benim dertlerime tek çare

Manalı manalı bakma sen öyle 

Sana tapıyorum sevmek ne demek

Latifiyim aşkın ciğerde yanar 

Gözlerim etrafta hep seni arar

Sevdiğim vefasız sevmiyor sanar

ona tapıyorum sevmek ne demek

2003', 'Beni seviyor musun diye hiç sorma  Sana tapıyorum sevmek ne demek Böyle sorularla kafanı yorma  Sana tapıyorum sevmek ne demek Gözlerinden a...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-tapiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Canımı Veririm', 'ben-canimi-veririm-hifzi-ozbekmez-bollm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzelim gözlerine 

Ben canımı veririm

O tatlı sözlerine

Ben canımı veririm

Salınıp gelişine 

Güzelim gülüşüne

Sevdiğim deyişine

Ben canımı veririm

Baharına yazına

Duvarda ki sazına 

Latifiyim nazına 

Ben canımı veririm

2003', 'Güzelim gözlerine  Ben canımı veririm O tatlı sözlerine Ben canımı veririm Salınıp gelişine  Güzelim gülüşüne Sevdiğim deyişine Ben canımı v...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-canimi-veririm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destgirlik Ummam Senden Bir Zaman', 'destgirlik-ummam-senden-bir-zaman-seyrani-j8z5q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Destgirlik ummam senden bir zaman

Göster ağacında sağlam dal bana

Pervazıma dardır yedi kat gökler

Daima açıktır istikbâl bana

Mesnedim yok azlim kaygu çekeyim

Usta başı gibi ölçüp dökeyim

Evvel ahır bir kurbanlık tekeyim

Vakti gelsin bıçağını çal bana

Seyrânî''yim boş küp gibi inlemem

Üç sıfırla bir rakamın binlemem

Elimde çaldığım sazı dinlemem

Aşkım sazı verir türlü hal bana', 'Destgirlik ummam senden bir zaman Göster ağacında sağlam dal bana Pervazıma dardır yedi kat gökler Daima açıktır istikbâl bana Mesnedim yok ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/destgirlik-ummam-senden-bir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımdan Çıkmayacaksın', 'aklimdan-cikmayacaksin-hifzi-ozbekmez-kcrfc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahpe felek bu dünyayı dar etse

Sevdanın uğruna yaksa nar etse

Kötü kader seni ele yar etse

Yinede aklımdan çıkmayacaksın

Gözlerime kanlı yaşlar dolsa da 

Hayatım bitip gençliğim solsa da 

Gurbet eller hep diyarım olsa da

Yinede aklımdan çıkmayacaksın

Hiç halimi hatırımı sormasan 

Yanımda bir gün bile kalmasan

Selam salsam  selamımı almasan

Yinede aklımdan çıkmayacaksın

Azrail gelip de canım alsa da

Gözlerime kara toprak dolsa da

Bedenim çürüyüp kemik kalsa da

Yinede aklımdan çıkmayacaksın

Derdin ağlatsa da garip gönlümü

Sevdan bitirse de benim ömrümü

Can çekişsem bile Allahın günü

Yinede aklımdan çıkmayacaksın

İstersen anlama benim aşkımı

İstersen sende sev bir başkasını

İstersen lanet et çat kaşlarını

Yinede aklımdan çıkmayacaksın

Latifinin hayalini bilmesen

Çağırsa çağırsa  yine gelmesen

Benimle ağlayıp bir gün gülmesen

Yinede aklımdan çıkmayacaksın

2003', 'Kahpe felek bu dünyayı dar etse Sevdanın uğruna yaksa nar etse Kötü kader seni ele yar etse Yinede aklımdan çıkmayacaksın Gözlerime kanlı ya...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aklimdan-cikmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim Almış Züğürtlük', 'efendim-almis-zugurtluk-seyrani-p4adk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Efendim almış züğürtlük

Kaşa beni göze beni

Sürükler yıl cepte dörtlük

Yaz bahar kış güze beni

Dedim: Züğürtlük çelebi

Nedir ezdiğin sebebi

Ben değilim yoğurt gibi

Yağım çıkar öze beni

Ateş belli yakışından

Günlük belli kokuşundan

Müflüslüğün yokuşundan

Kurtar çıkar düze beni

Dedi: Dinlemem ben çene

Bakalım beş yüze bine

Al da nişangahı dene

Çeşmin süze süze beni

Değil şimdi sırayıla

Padişahlık parayıla

Sikke ile turayıla

Muhtaç sanma söze beni

Seyrani ye şöyle böyle

Ne suçu var ise söyle

Şanına düşeni eyle

Ayna etme yüze beni', 'Efendim almış züğürtlük Kaşa beni göze beni Sürükler yıl cepte dörtlük Yaz bahar kış güze beni Dedim: Züğürtlük çelebi Nedir ezdiğin sebebi ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/efendim-almis-zugurtluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretim Yok', 'cesaretim-yok-hifzi-ozbekmez-jjxcv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar istesem görmek yüzünü

Yüzüne bakmaya cesaretim yok

Dinlemek istesem tatlı sözünü

Sesini duymaya cesaretim yok

Korkarım aşkımız bir gün bitecek

Hayalin gözümden akıp gidecek

Gönlümü bıraksam koşup gelecek

Yanına gelmeye cesaretim yok

Benim tek arzumdur gönlünde olmak

Aradığım aşkı hep sende bulmak 

Ne kadar istesem sineme sarmak

Belini sarmaya cesaretim yok

Latifi olur mu aşktan hiç kaçmak

Varsa kaderinde sevdadan uçmak

Seninle isterim el ele  koşmak

Elini tutmaya cesaretim yok

2003', 'Ne kadar istesem görmek yüzünü Yüzüne bakmaya cesaretim yok Dinlemek istesem tatlı sözünü Sesini duymaya cesaretim yok Korkarım aşkımız bir ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cesaretim-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşkın', 'bu-askin-hifzi-ozbekmez-enicx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık uyku girmez oldu gözüme

Beni uykulardan aldı bu aşkın

Kastın mı var baharıma yazıma

Beni sevdalara saldı bu aşkın

Bana unutturdu inan gülmeyi

Sazım çalıyor bak dertli nağmeyi

Gönül ister hep seninle olmayı

Ne çabuk kalbimi çaldı bu aşkın

Gözlerim uzaklarda seni arar

Uçan kuşlarda da haberin sorar

Sevda ateşinden ciğerim yanar

Beni ateşlerde koydu bu aşkın

Latifi kapıldı tatlı sözüne

Henüz bakmasa da o gül yüzüne

Aşk ateşi düşürdün garip özüme

Şu garip sinemi deldi bu aşkın

2003', 'Artık uyku girmez oldu gözüme Beni uykulardan aldı bu aşkın Kastın mı var baharıma yazıma Beni sevdalara saldı bu aşkın Bana unutturdu inan ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykularım Kaçıyor', 'uykularim-kaciyor-hifzi-ozbekmez-lbhc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep seni düşünmekten 

Uykularım kaçıyor

Hayalini görmekten

Uykularım kaçıyor

Özlemin karşısında 

Geceler yarısında 

Her saatin başında 

Uykularım kaçıyor

Aşığınım ben senin

Cananımsın sen benim

Yarısında gecenin

Uykularım kaçıyor

Yollarını gözlerken

Canım seni özlerken

Sabahları erkenden

Uykularım kaçıyor

Latifi derki niye 

Döndüm aşktan deliye

İnan ki her saniye

Uykularım kaçıyor

2003', 'Hep seni düşünmekten  Uykularım kaçıyor Hayalini görmekten Uykularım kaçıyor Özlemin karşısında  Geceler yarısında  Her saatin başında  Uyku...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uykularim-kaciyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefes', 'son-nefes-hifzi-ozbekmez-xrouf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatım gün gelip sona ererken

Aldığım son nefes sen olacaksın

Çileli ömrümde bir gün dolarken

Aldığım son nefes sen olacaksın

Azrail almaya gelirse canım

Damarlarımdan çekilirse kanım

Tutmaz olduğunda dört bir yanım

Aldığım son nefes sen olacaksın

Latifiyim aşkın kalbimi yaksa

Beni de hallerden hallere soksa

Canım bedenden bir gün çıkacaksa

Aldığım son nefes sen olacaksın

2003', 'Hayatım gün gelip sona ererken Aldığım son nefes sen olacaksın Çileli ömrümde bir gün dolarken Aldığım son nefes sen olacaksın Azrail almaya...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-nefes-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğlen Hocam Eğlen Bir Sualim Var', 'eglen-hocam-eglen-bir-sualim-var-seyrani-wpk8z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğlen hocam eğlen bir sualim var

İz''an nedir erkan nedir yol nedir

Seni bana gayet fazıl dediler

İçerimde bir yaram var bil nedir

Cennetin kapısın Sallallah açar

Şeriat işini Muhammed seçer

Seksen bin evliya yurdundan göçer

Onları bekleten mutlu kul nedir

Muhammed dinidir yaptığım tapı

Bozulmaz Mevla''nın yaptığı yapı

On iki bahçede kırk sekiz kapı

Eşiği bekleyen iki kul nedir

Kıldan ince derler Sırat''ın yolu

Önünde Devletlu ardında Ali

Üçyüz altmış birdir selvinin dalı

Dalında açılan iki gül nedir

Başına bağlamış al yeşil çember

Kokuyor ağzında misk ile amber

Seksen bin evliya yüzbin peygamber

Önünde gidiyor iki kul nedir

Seyrani der diyar diyar gezmedim

Kalem alıp kaşın gözün yazmadım

Elim ile bir gemicik düzmedim

Gemi nedir derya nedir yol nedir', 'Eğlen hocam eğlen bir sualim var İz''an nedir erkan nedir yol nedir Seni bana gayet fazıl dediler İçerimde bir yaram var bil nedir Cennetin k...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eglen-hocam-eglen-bir-sualim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber Vermeden', 'haber-vermeden-hifzi-ozbekmez-962pj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzelim aklımı başımdan aldın

Bana kastın mı  var bilmem ki neden

Beni hülyalara ne çabuk saldın

Kalbim esir aldın haber vermeden

Deli gönül artık lafta dinlemez

Senden başkasını inan istemez

Hayalin gözümden bir anda gitmez

Rüyalara saldın haber vermeden

Aşkından olacak benim ölümüm

Hem tek sevdiğimsin hem gonca gülüm

Sevdanın kölesi garip gönlümün

Tapusunu aldın haber vermeden

Latifi ne söylesem de kar etmez

Gönlümü satsam da beş para etmez

Sevenin halini sevmeyen bilmez

Sen kalbimi çaldın haber vermeden

2003', 'Güzelim aklımı başımdan aldın Bana kastın mı  var bilmem ki neden Beni hülyalara ne çabuk saldın Kalbim esir aldın haber vermeden Deli gönül...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haber-vermeden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evvel Giymez İken İpek Mintanı', 'evvel-giymez-i-ken-i-pek-mintani-seyrani-mjofn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evvel giymez iken ipek mintanı

Geyersin eğnine çul yavaş yavaş

Feragat kıl bırak aşk ü sevdayı

Olma bir dilbere kul yavaş yavaş

Heder olsa bir pul için her demin

Muhannet babına basma kademin

Emsaliyle konuşmayan ademin

Altun ismi olur pul yavaş yavaş

Soyundum libasım oldum uryanı

Seyrettim köşeyi çarhı devranı

Bu dünyanın işi bitti Seyrani

Başına bir çare bul yavaş yavaş', 'Evvel giymez iken ipek mintanı Geyersin eğnine çul yavaş yavaş Feragat kıl bırak aşk ü sevdayı Olma bir dilbere kul yavaş yavaş Heder olsa b...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/evvel-giymez-iken-ipek-mintani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-hifzi-ozbekmez-k8xg6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baharımda yazımda 

Hep seni arıyorum

Dertli çalan sazımda

Hep seni arıyorum

Gurbetin yollarında

Gönlümün güllerinde

Bülbülün dillerinde 

Hep seni arıyorum

Neşede ve hüzünde

Ağlayan bu gözümde

Sevgin dolu  özümde 

Hep seni arıyorum

Baharın kokusunda 

Sevdanın yokuşunda

Hücremin dokusunda

Hep seni arıyorum

Ağlayan gözlerimde

O tatlı sözlerinde

Ömrümün güzlerinde

Hep seni arıyorum

Latifi ahu zarda

Gel koyma beni darda

Gurbet elde diyarda 

Hep seni arıyorum

2003', 'Baharımda yazımda  Hep seni arıyorum Dertli çalan sazımda Hep seni arıyorum Gurbetin yollarında Gönlümün güllerinde Bülbülün dillerinde  Hep...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-ariyorum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevdiğim, Artık Yeter', 'ey-sevdigim-artik-yeter-seyrani-zuyhl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey sevdiğim, artık yeter

Bana yosma bakışın var

Ateşlerden daha beter

Âşıkları yakışın var

Erdin güzellik çağına

Bağladın zülfün bağına

Bizi hüsnün ayağına

Nal, mıh gibi çakışın var

Sağlıktır her işin başı

Sabırdır ekmeği aşı

Aferin ey çeşmim yaşı

Yâr yoluna akışın var

Güzel, senin hüsnün sebep

Olup gören eyler talep

Cennetten mi çıktın acep

Tavus gibi nakışın var

Güzellerin çok gencisin

Seyrânî''ye birincisin

Aşk ipine zevk incisin

Güzel delip takışın var', 'Ey sevdiğim, artık yeter Bana yosma bakışın var Ateşlerden daha beter Âşıkları yakışın var Erdin güzellik çağına Bağladın zülfün bağına Bizi...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-sevdigim-artik-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın İnanma', 'sakin-i-nanma-hifzi-ozbekmez-wyd9v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçların beyazlayıp düşünce aklar

Deli gönül nice sırları saklar

Kırktan sonra azma teneşir paklar

Derlerse de gülüm sakın inanma

Yine gönlüm coştu hesap sorulmaz

Ne kadar koşsa da yare varılmaz

Gördüğün rüyalar hayra yorulmaz

Derlerse de gülüm sakın inanma

Gönül pare pare dertlere dalmış

Şu garip başımı sevdaya salmış

Sen ona inanma muradın almış

Derlerse de gülüm sakın inanma

Kırktan sonra azma paklar teneşir

Günahım yazmaya yetmez tebeşir

Sevenlerin yolu bir gün birleşir

Derlerse de gülüm sakın inanma

Herkeste biliyor bu dünya fani

Demek istediğim sev sevil yani

Karşılıksız sevmez hiçbir enayi

Derlerse de gülüm sakın inanma

Koşa koşa gidiyorsun nereye 

Yüce Allah sana kolaylık vere

Her gördüğün sakallıyı bir dede

Derlerse de gülüm sakın inanma

Latifi söylüyor bitmiyor sözü

Bağrında yanıyor hasretin közü

Mutluluk çalamaz kırıktır sazı

Derlerse de gülüm sakın inanma

2003', 'Saçların beyazlayıp düşünce aklar Deli gönül nice sırları saklar Kırktan sonra azma teneşir paklar Derlerse de gülüm sakın inanma Yine gönlü...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sakin-inanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah Fukaranın Beli Büküldü', 'eyvah-fukaranin-beli-bukuldu-seyrani-spnsa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eyvah fukaranın beli büküldü

Medet ticaretin gücüne kaldık

Eyiler alemden göçtü çekildi

Bizler zamanenin piçine kaldık

Rüşvet ile yarar hakim hücceti

Hüccet ile alır kadı rüşveti

Halk bilmiyor dini şer''i sünneti

Bozuldu sikkenin tuncuna kaldık

Sene bin iki yüz altmış beş tamam

Okunur ezanlar boş bekler imam

Seyrani bu nutkun sonu vesselam

İnanın dünyanın ucuna kaldık', 'Eyvah fukaranın beli büküldü Medet ticaretin gücüne kaldık Eyiler alemden göçtü çekildi Bizler zamanenin piçine kaldık Rüşvet ile yarar haki...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eyvah-fukaranin-beli-bukuldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemem', 'vazgecemem-hifzi-ozbekmez-293e6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başımdan da kızgın yağlar dökseler

Otuz iki dişim birden sökseler

Cehennemde beni her gün yaksalar

Gülüm yine senden vazgeçemem ben

Bağlasalar benim elim kolumu

Her gün kesseler de inan yolumu 

Perişan etse de sevdan halimi 

Gülüm yine senden vazgeçemem ben

Artık çarmıha da gerseler beni

Kızgın mille dağlasalar sinemi

Ağzıma vursalar demirden gemi

Gülüm yine senden vazgeçemem ben

Latifinin bahtı zaten karanlık

Unutmak mümkün mü  seni bir anlık

Olsam eğer ömür boyu zindanlık

Gülüm yine senden vazgeçemem ben

2003', 'Başımdan da kızgın yağlar dökseler Otuz iki dişim birden sökseler Cehennemde beni her gün yaksalar Gülüm yine senden vazgeçemem ben Bağlasal...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vazgecemem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzersin', 'benzersin-hifzi-ozbekmez-qyiup', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk kış gününde yaza benzersin

Güzel nağme çalan saza benzersin

Hayata tat veren tuza benzersin

Canımsın sen benim canım sevgilim

Dünyada en güzel huya benzersin

Fırtına kurtaran koya benzersin

Sıcakta içtiğim suya benzersin

Canımsın sen benim canım sevgilim

Hıfzının sazında tele benzersin

Gönlümdeki gonca güle benzersin

Şifalar dağıtan ele benzersin

Canımsın sen benim canım sevgilim

2003', 'Soğuk kış gününde yaza benzersin Güzel nağme çalan saza benzersin Hayata tat veren tuza benzersin Canımsın sen benim canım sevgilim Dünyada ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/benzersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Serden Geçer Yardan Geçemez', 'gonul-serden-gecer-yardan-gecemez-seyrani-du9x3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül serden geçer yardan geçemez

Bağlanmış ikrara kavi özlüyüm

Her sözüm dinleyen özüm seçemez

Sırat köprüsünden ince sözlüyüm

Benim sözüm çürük değil sağ gibi

Çürük sözler erir akar yağ gibi

Üzerinden kervan geçer dağ gibi

Yokuşluyum sanma beni düzlüyüm

Yolcu ateş yanmak ile yol yanmaz

Erenlerin dokuduğu çul yanmaz

Cehennemde günah yanar kul yanmaz

Ben günahtan sürmelenmiş gözlüyüm

Seyrani aradım onu her yerde

Aşk-ı hakikatle düştüm bu derde

Tuttum günahımdan yüzüme perde

Rabbim divanında kara yüzlüyüm', 'Gönül serden geçer yardan geçemez Bağlanmış ikrara kavi özlüyüm Her sözüm dinleyen özüm seçemez Sırat köprüsünden ince sözlüyüm Benim sözüm ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-serden-gecer-yardan-gecemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıramazlar', 'ayiramazlar-hifzi-ozbekmez-1sz65', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kollarıma kelepçeler vursalar

İster her gün kemiklerim kırsalar

Ölmeden de mezarıma koysalar

Yine senden gülüm ayıramazlar

Bedenimi çarmıha bağlasalar

Gözlerimi millerle dağlasalar

Gurbetten bir gün bile salmasalar

Yine senden gülüm ayıramazlar

Hayatım olsa zifiri karanlık

Zehir içsem de unutamam bir anlık

Hepside el ele verse insanlık

Yine senden gülüm ayıramazlar

Latifiyim derki geldi zamanı

Garip gönlüm senden diler amanı

Şimdi yazsalar da ölüm fermanı

Yine senden gülüm ayıramazlar

2003', 'Kollarıma kelepçeler vursalar İster her gün kemiklerim kırsalar Ölmeden de mezarıma koysalar Yine senden gülüm ayıramazlar Bedenimi çarmıha ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayiramazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-hifzi-ozbekmez-i3tar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz aldığım nefesin

Çıkardığım her sesin

Olsa da altın kafesim

Kıymeti yok bir tanem 

2003', 'Sensiz aldığım nefesin Çıkardığım her sesin Olsa da altın kafesim Kıymeti yok bir tanem  2003...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/birtanem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Dostlarım', 'benim-dostlarim-hifzi-ozbekmez-si7bv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Halimi de hatırımı sorsalar

Gördüğüm rüyayı hayra yorsalar

İsterlerse kafamı da kırsalar

Yine de canımdır benim dostlarım

Arada bir yanıma da gelseler

Akan göz yaşımı bir gün silseler

Hem benimle ağlayıp da gülseler 

Damarda kanımdır benim dostlarım

Benim yanımdalar her gün her yerde

Çağırsam gelirler hatta seherde

Bilmem ne kadar zarar etsem de

İnsanlık karımdır benim dostlarım

Latifinin baharında yazında

Darda koymadılar kış ayazında

Ömür boyu dertli çalan sazımda

Vuran mızrabımdır benim dostlarım

2003', 'Halimi de hatırımı sorsalar Gördüğüm rüyayı hayra yorsalar İsterlerse kafamı da kırsalar Yine de canımdır benim dostlarım Arada bir yanıma d...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpe Felek Benim Nerde', 'kahpe-felek-benim-nerde-seyrani-42qdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kahpe felek benim nerde

Kara bahtım ak eyledi

Pervaneler gibi nârde

Vücudumu yak eyledi

Bir yâr bana dolap kurdu

Hicabımdan dilim durdu

Fincan gibi yere vurdu

Göğsüm'' iki şak eyledi

Sikke olmaz bu turada

Ermedim ben hiç murada

Âşık Seyrânî burada

Ne söylerse hak eyledi', 'Kahpe felek benim nerde Kara bahtım ak eyledi Pervaneler gibi nârde Vücudumu yak eyledi Bir yâr bana dolap kurdu Hicabımdan dilim durdu Finc...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahpe-felek-benim-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkeme Meclisi İcat Olduğu', 'mahkeme-meclisi-i-cat-oldugu-seyrani-tbd8v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mahkeme meclisi icat olduğu

Çeşme-i rüşvetin akmaklığından

Kaza bela ile alem dolduğu

Kazların kadıya uçmaklığından

Selefin rüşvetle hüccet yazması

Halefin anlayıp hükmün bozması

Yıkılan binanın birden tozması

Asıl sermayenin topraklığından

Asıl sermaye-i niyabetleri

Emval-i eytamdır ticaretleri

Davet-i rüşvete icabetleri

Sıdk ile gönlünün alçaklığından

Bülbülün aşkıdır dalda öttüğü

Çobanın südedir koyun güttüğü

Toprağın Habil''i kabul ettiği

Şüphesiz yüzünün yumşaklığından

Dünyadan ahrete gidip gelmemek

Olmasa iktiza eder ölmemek

Balık baştan kokar bunu bilmemek

Seyrani gafilin ahmaklığından', 'Mahkeme meclisi icat olduğu Çeşme-i rüşvetin akmaklığından Kaza bela ile alem dolduğu Kazların kadıya uçmaklığından Selefin rüşvetle hüccet ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mahkeme-meclisi-icat-oldugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-hifzi-ozbekmez-u2hnx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey gönül seninle ben nere gidem

Azığın bitmeden yemek istersin

Kendin yan gelip de yatarsın amma

Herkeslerden çaba emek istersin

Güzelin istersin daim hasını

Doldurur durursun aşkla tasını

Beladan alamaz oldun başını

Çeşit çeşit güzel sevmek istersin

Gönül böyle şeyler seni yaralar

Doktor mu var yaraların saralar

Bu gün sevdiğini yarın karalar

Seni terk edince sövmek istersin

Latifi gönülle dertte mi başın 

Sayesinde zehir mi ekmeğin  aşın 

Ne çabuk yaşlandın kırk oldu yaşın

Ecel şerbetini içmek istersin

2003', 'Ey gönül seninle ben nere gidem Azığın bitmeden yemek istersin Kendin yan gelip de yatarsın amma Herkeslerden çaba emek istersin Güzelin ist...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-vedat-sarapci-56w0e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemle doluyorum yokluğunda.

Susuz toprağın yağmura,

uçuşan kelebeğin çiçeklere,

savrulan bulutların rüzgara

duyduğu özlem kadar ağır,

ezgiler söylenen dağlar kadar durgun.

Sen geldiğinde kayboluyor 

dünyamdaki kara bulutlar,

güneş gibi doğarken günüme,

gökkuşağından bir yol oluyor

senden bana akan, içimi ısıtan

gönlünden gönlüme..

(İstanbul, 20 Ekim 2000)', 'Özlemle doluyorum yokluğunda. Susuz toprağın yağmura, uçuşan kelebeğin çiçeklere, savrulan bulutların rüzgara duyduğu özlem kadar ağır, ezgi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şarapcı']::text[], 8.5, '{"poet":"Vedat Şarapcı","poet_slug":"vedat-sarapci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-hifzi-ozbekmez-ig35s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine hayal ettim mah cemalini

Düşündüm düşündüm bitiremedim

Gözümün önüne gül hayalini

Ne kadar uğraşsam getiremedim

Boyun kısamıdır yoksa uzun mu

Yüzün mü güzeldir yoksa nazın mı

Dertli nağme çalan senin nazın mı

Onu da koluma yatıramadım

Gözlerin ateşler gibi yakar mı

Yoksa dertli dertli melül bakar mı 

Gül bakışlarda kalbime akar mı

Ona da aklımı yetiremedim

Latifi hayaller yetmez oldular

Çektiğin çileler bitmez oldular

Çirkinlerde mutlu etmez oldular

Gönlümü güzele götüremedim 

2003', 'Yine hayal ettim mah cemalini Düşündüm düşündüm bitiremedim Gözümün önüne gül hayalini Ne kadar uğraşsam getiremedim Boyun kısamıdır yoksa u...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayalin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet Küpünün Olsam Şarabı', 'muhabbet-kupunun-olsam-sarabi-seyrani-juflq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Muhabbet küpünün olsam şarabı

Yar beni doldurup içer mi bilmem

Mamur olmak için gönül harabı

Bir mimar eline geçer mi bilmem

Aşıkın olmaz mı çile çekmezi

Çilenin olmaz mı boyun bükmezi

Helal süde katan haram pekmezi

Seçmek murad etse seçer mi bilmem

Bübüle gül yarar deveye diken

Çiledir aşıkın boynunu büken

Tarlasına haram tohumu eken

Helal mahsulünü biçer mi bilmem

Kimi mevtasına kefen biçmiyor

Kimi helal rızık yiyip içmiyor

Yavrusundan köpek bile geçmiyor

Hak Seyrani''sinden geçer mi bilmem', 'Muhabbet küpünün olsam şarabı Yar beni doldurup içer mi bilmem Mamur olmak için gönül harabı Bir mimar eline geçer mi bilmem Aşıkın olmaz mı...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muhabbet-kupunun-olsam-sarabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-hifzi-ozbekmez-9k63j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin güzelliğin dünyayı değer

Sanki bulunmaz kumaşsın sevdiğim

Seni görmeden de ölürsem eğer

Aşkım mezarımdan taşsın sevdiğim

Canım sevdiğimsin ciğer paremsin

Gönlümde kanayan yeni yaremsin

Benim bütün dertlerime çaremsin

Fakir soframdaki aşsın sevdiğim

Sensiz olmuyor bu hayat olmuyor

Çilelerim gurbet elde dolmuyor

Bin dilek dilesem biri olmuyor

Sen gözümden akan yaşsın sevdiğim

Latifiyim bende sana yanarım

Mutluluk beni bulacak sanarım

Gece gündüz hep adını anarım

Gözümün üstünde kaşsın sevdiğim

2003', 'Senin güzelliğin dünyayı değer Sanki bulunmaz kumaşsın sevdiğim Seni görmeden de ölürsem eğer Aşkım mezarımdan taşsın sevdiğim Canım sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdigim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hikmettir, Şu Dünyada', 'ne-hikmettir-su-dunyada-seyrani-bvfx4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne hikmettir, şu dünyaya

Gelen ağlar giden ağlar

Soralım yoksula, baya

Aslı nedir neden ağlar

Ömrümün defterin dürdüm

Hâkipâye yüzüm sürdüm

Bir acayip kale gördüm

Burç ve baru, beden ağlar

Bir deveci yider deve

Yularından seve seve

Birbirinden ive ive

Deve ağlar, yiden ağlar

Seyrânî''ye acap n''olmuş

Deruni dert ile dolmuş

Kimi etmiş kimi bulmuş

Bulan ağlar, eden ağlar', 'Ne hikmettir, şu dünyaya Gelen ağlar giden ağlar Soralım yoksula, baya Aslı nedir neden ağlar Ömrümün defterin dürdüm Hâkipâye yüzüm sürdüm ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-hikmettir-su-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Ben Değilim ki', 'i-lk-ben-degilim-ki-engin-namli-h0gpj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbetin soğuk kaldırımlarına

Uzanıp yatan ilk ben değilim ki

Ayak koyduğum tüm adımlarına

Beden sürüyen ilk ben değilim ki

Yalnız kaldığım her bir köşesinde,

Sen dert çekerken herkes neşesinde,

Derim adalet bunun neresinde

Yıllarca soran ilk ben değilim ki

Hıçkıran gönlüm halimi sorarda

Bitmez derdime çareler ararda

Bir nebze olsun merhemi olurda

Lakin gam gören ilk ben değilim ki

16:20 20.12.2003', 'Gurbetin soğuk kaldırımlarına Uzanıp yatan ilk ben değilim ki Ayak koyduğum tüm adımlarına Beden sürüyen ilk ben değilim ki Yalnız kaldığım ...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ilk-ben-degilim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pintinin Dik Kulaklısı', 'pintinin-dik-kulaklisi-seyrani-ekmqx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pintinin dik kulaklısı

Boynu yoğun eşek olur

Pek mülayim yolaklısı

Sanma tunçtan gevşek olur

Yolda koşar ive ive

Çarığını geve geve

Top vaktinde olur deve

Yük vaktinde köşek olur

Dök Seyrani gözden yaşı

Sağlıktır her işin başı

Merdin eşiğinin taşı

Kuş tüyünden döşek olur', 'Pintinin dik kulaklısı Boynu yoğun eşek olur Pek mülayim yolaklısı Sanma tunçtan gevşek olur Yolda koşar ive ive Çarığını geve geve Top vakt...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pintinin-dik-kulaklisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakınsın', 'yakinsin-hifzi-ozbekmez-5r7ep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle kendini sen uzakta sanma

Şah damarımdan daha yakınsın

Yolların uzaktır bilirim amma

Damarda kanımdan daha yakınsın

Esen rüzgarlardan alırım kokun

Kalbimde saklıdır aşk denen okun

Hikmetinden sual olunmaz hakkın

Benim dört yanımdan daha yakınsın

Ger an kulağımda o güzel sesin

Yanımdan bir anda gitmez nefesin

Sakın gülüm sen hiç üzülmeyesin

Bedende canımdan daha yakınsın

Latifiyim beni ettin perişan

Bir garibim artık yollarda şaşan

Hayalin peşinde durmadan koşan

Şu aşık halimden daha yakınsın

2003', 'Öyle kendini sen uzakta sanma Şah damarımdan daha yakınsın Yolların uzaktır bilirim amma Damarda kanımdan daha yakınsın Esen rüzgarlardan al...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yakinsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sene Bin İki Yüz Altmış Sekizde', 'sene-bin-i-ki-yuz-altmis-sekizde-seyrani-hfrq9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sene bin iki yüz altmış sekizde

Alamet dumanı çöktü çökecek

Dikilecek kudret kalmadı dizde

Ecel belimizi büktü bükecek

Bitmez oldu harmanların eyisi

Hurma tadı verir erik kayısı

Sadrazam etsen eğer seyisi

Ölmüş eşek arar nalın sökecek

Hiç çoban koyunu güder mi dağda

Olmasa gözleri süt yoğurt yağda

Meyvası bitmedik ağacı bağda

Sökerler Seyrani daldan kökecek', 'Sene bin iki yüz altmış sekizde Alamet dumanı çöktü çökecek Dikilecek kudret kalmadı dizde Ecel belimizi büktü bükecek Bitmez oldu harmanlar...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sene-bin-iki-yuz-altmis-sekizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyrimde Bir Şehre Eyledim Nazar', 'seyrimde-bir-sehre-eyledim-nazar-seyrani-97xi7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seyrimde bir şehre eyledim nazar

Gördüm elvan türlü meyhaneler var

Teşne var mı diye sakiler gezer

Ellerinde dolu peymaneler var

Bir takım doldurur bir takım sunar

Bir takım susamış bir takım kanar

Bir takım söğünmüş bir takım yanar

Bir takım çevrilir pervaneler var

Bir eli kaseli bir eli taslı

Bir takım keyifli bir takım yaslı

Bir takım deli var bir takım uslu

Bir takım aşk içre mestaneler var

Aşık olan mürşidine yan verir

Bu Seyrani dilden dile şan verir

Hast''olmadan pir önünde can verir

Nice bizim gibi divaneler var', 'Seyrimde bir şehre eyledim nazar Gördüm elvan türlü meyhaneler var Teşne var mı diye sakiler gezer Ellerinde dolu peymaneler var Bir takım d...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seyrimde-bir-sehre-eyledim-nazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofu Olmaz Bizim Ham Demirimiz', 'sofu-olmaz-bizim-ham-demirimiz-seyrani-wo2o2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sofu olmaz bizim ham demirimiz

Haddeden çekilmiş teli biliriz

Yürütmüştür cansız dıvar pirimiz

Temiz zevki temiz dili biliriz

Sofu bilmiş olsa hakkı rızayı

Sazdan sözden kaçıp vermez riyayı

Ay gün yıldız gibi vermez ziyayı

Kuru arktan akan seli biliriz

Bizde bu dünyanın bina temelin

Cismi canla bildik ilm-i amelin

Sanma bizi arap taze kız gelin

Öpüp tükürecek eli biliriz

Vakıfız bu aşkın biz manasına

Talip ol Seyrani dal deryasına

Hazret-i Mevla''nın ehibbasına

Aşina olmayan eli biliriz', 'Sofu olmaz bizim ham demirimiz Haddeden çekilmiş teli biliriz Yürütmüştür cansız dıvar pirimiz Temiz zevki temiz dili biliriz Sofu bilmiş ol...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sofu-olmaz-bizim-ham-demirimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Kimsesiz Sahralara', 'su-kimsesiz-sahralara-seyrani-n7hn2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu kimsesiz sahralara

Diken oldu gülüm benim

Gizli gizli tenhalarda

Ağlamaktır halim benim

Gülü dikene katalı

Diken elime batalı

Yâr beni yardan atalı

Bükülmüştür belim benim

Arı geçmez çiçeğinden

Çiçek geçmez peteğinden

Pîr erenler eteğinden

Kesme rabbim elim benim

Yedim acı teresinden

İçtim kanlı şırasından

Seyrânî gam deresinden

Çûş eyledi selim benim', 'Şu kimsesiz sahralara Diken oldu gülüm benim Gizli gizli tenhalarda Ağlamaktır halim benim Gülü dikene katalı Diken elime batalı Yâr beni ya...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-kimsesiz-sahralara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumurtasın Kokutmağa', 'yumurtasin-kokutmaga-seyrani-cceem', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yumurtasın kokutmağa

Yatar sanma gürke beni

Aşkın dersin okutmağa

Sanma korkup ürke beni

Ben aşıkın birisiyim

Ölü değil dirisiyim

Siyah tilki derisiyim

Kapla samur kürke beni

Canbazım ben aşk ipinde

Büyür meyve hep çöpünde

Temiz aşkın zevk küpünde

Sanma sulu sirke beni

Seyrani bir arı beyi

Çiçeği aşkın göbeği

Nazlıyım gözüm bebeği

Düşüremen çirke beni', 'Yumurtasın kokutmağa Yatar sanma gürke beni Aşkın dersin okutmağa Sanma korkup ürke beni Ben aşıkın birisiyim Ölü değil dirisiyim Siyah tilk...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yumurtasin-kokutmaga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarif Edemem', 'tarif-edemem-hifzi-ozbekmez-hbeaj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vitesten atmışım inan boştayım

Kara sevdada mı yoksa aşktayım

Bilmiyorum bende hangi yaştayım

Halimi ben bile tarif edemem

Pek duygusal oldum ağlar gezerim

Derman yok ki yürümüyor dizlerim

Bir tanem ben seni çok özlerim

Halimi ben bile tarif edemem

İnan azı çoğu çoktan unuttum

Aklımda yalnızca adını tuttum

Sevdayın bağrına ne yaman battım  

Halimi ben bile tarif edemem

Aşkın yoluna da dağlar aşırdım

Kara sevdanı gönlümde pişirdim

Ne yapayım gülüm bende şaşırdım

Halimi ben bile tarif edemem

Hayatın kalmadı hiç tadı tuzu

Ben çoktan unuttum baharı yazı

Duvarda bıraktım asılı sazı

Halimi ben bile tarif edemem

Deli gönül hep baharda azıyor

Kaderim hep kara yazı yazıyor

Gözlerimden kanlı yaşlar sızıyor 

Halimi ben bile tarif edemem

Hıfzıyım ne yapsam bilemiyorum

Akan göz yaşımı silemiyorum

Sen uzaklardasın gelemiyorum

Halimi ben bile tarif edemem

2003', 'Vitesten atmışım inan boştayım Kara sevdada mı yoksa aşktayım Bilmiyorum bende hangi yaştayım Halimi ben bile tarif edemem Pek duygusal oldu...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tarif-edemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Varmı', 'haberin-varmi-hifzi-ozbekmez-ik1ff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine efkarlandım bir hüzün çöktü

Gözümün yaşını bu aşkın döktü

Kara sevdan benim bağrımı söktü

Halden hale düştüm haberin var mı

Ellerin yüzüne bakamaz oldum 

Oturdum yerimden kalkamaz oldum

Gonca bir gül iken ne çabuk soldum

Dilden dile düştüm haberin var mı

Gelsen de  bu sevda mutlu eylemez

Bak lal oldu dilim kelam söylemez

Akan göz yaşımı kimse silemez

Daldan dala  düştüm haberin var mı

Latifi söylüyor yanıyor özü

Gül yüzün hasreti bağrında közü

Arada bir görsem senide bazı

İlden ile  düştüm haberin var mı

2003', 'Yine efkarlandım bir hüzün çöktü Gözümün yaşını bu aşkın döktü Kara sevdan benim bağrımı söktü Halden hale düştüm haberin var mı Ellerin yüz...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haberin-varmi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayırsan Yeter', 'ayirsan-yeter-hifzi-ozbekmez-t0kzx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyanın vakitleri senin olsun

Sen bana dakika ayırsan yeter

İstersen bu ömrüm yanında dolsun

Sen bana dakika ayırsan yeter

Gönül bahçemde gülleri soldurmam

Yüreğime acı keder doldurmam

Günlerim hep senin olsun aldırmam

Sen bana dakika ayırsan yeter

Sen kafana takma hiç olayları

Aşk  gevşetti gönlümdeki yayları

Sana verdim ben haftaları ayları

Sen bana dakika ayırsan yeter

Latifiyim aşındırdım yolları

Geze geze gördüm nice halleri

Bağışladım gülüm sana yılları

Sen bana dakika ayırsan yeter

2003', 'Dünyanın vakitleri senin olsun Sen bana dakika ayırsan yeter İstersen bu ömrüm yanında dolsun Sen bana dakika ayırsan yeter Gönül bahçemde g...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayirsan-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbüle Gül Yarar, Deveye Diken', 'bulbule-gul-yarar-deveye-diken-seyrani-lt3ws', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bülbüle gül yarar, deveye diken 

Çiledir aşıkın boynunu büken 

Tarlasına haram tohumu eken 

Helal mahsulunu biçer mi bilmem. 

Kimi mevtasına kefen biçmiyor 

Kimi helal rızık yiyip içmiyor 

Yavrusundan köpek bile geçmiyor 

Halk Seyrani senden geçer mi bilmem', 'Bülbüle gül yarar, deveye diken  Çiledir aşıkın boynunu büken  Tarlasına haram tohumu eken  Helal mahsulunu biçer mi bilmem.  Kimi mevtasına...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bulbule-gul-yarar-deveye-diken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırın İçin', 'hatirin-i-cin-hifzi-ozbekmez-mvooe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Has bahçede güller gibi açarım

Ben sensiz bir hayatı ne yaparım

Yeter ki sen iste zehir içerim 

Güzelim gül yüzlüm hatırın için

Aşkından da düz yollarda şaşarım

İstersen dağları yayan aşarım

Yedi kat yeraltında da yaşarım 

Güzelim gül yüzlüm hatırın için

Sensin benim canım aşkım gururum

Ben senin yoluna toprak olurum

Gülüm emret hemen şimdi ölürüm

Güzelim gül yüzlüm hatırın için

Latifiyim aşkın yakıyor beni

Uçan kuşlardan da sorarım seni

Allah senin için alsın bu canı 

Güzelim gül yüzlüm hatırın için

2003', 'Has bahçede güller gibi açarım Ben sensiz bir hayatı ne yaparım Yeter ki sen iste zehir içerim  Güzelim gül yüzlüm hatırın için Aşkından da ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatirin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanamadım', 'i-nanamadim-hifzi-ozbekmez-9bqmy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni çok sevmiştim gülüm inan ki

Aldığım nefestin sen benim sanki

Birde o habersiz gidişin var ki

Kalbim durdu sanki inanamadım

Sevdiğim canımsın diyordun hani

Bende canımdan çok sevmiştim seni

Yüreğimden vurdu gidişin beni

Kalbim durdu sanki inanamadım

Hani diyordun sen gitmem imkansız

Sözünden döndün sen gittin apansız

Beni de bıraktın dermansız kansız

Kalbim durdu sanki inanamadım

Latifiyi niye sen böyle yaktın

Aşkıyın ipini  boynuma taktın

Yarı yolda beni yalnız bıraktın

Kalbim durdu sanki inanamadım

2003', 'Seni çok sevmiştim gülüm inan ki Aldığım nefestin sen benim sanki Birde o habersiz gidişin var ki Kalbim durdu sanki inanamadım Sevdiğim can...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/inanamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-hifzi-ozbekmez-5obvl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dünya malına sakın güvenme 

Azrail gelecek cananım bir gün

Ağayım paşayım diye övünme

Azrail gelecek cananım bir gün

Bu dünya fanidir bunu iyi bil

Unut kötülükleri aklından sil

Etrafına bak kimse baki değil

Azrail gelecek cananım bir gün

Günah çemberinde ısrarla durma

Hakkın yolundanda sakın ayrılma

Yaptıklarım yanıma kalır sanma

Azrail gelecek cananım bir gün

Gönülleri hoş tut sakınha kırma

Yere düşmüşe birde sen vurma

Sev sevil dostuna uzakta durma

Azrail gelecek cananım bir gün

Olsa da dünyada katların yatın

Ömür dolar gülüm dolar miadın

Bir gün unutulur seninde adın 

Azrail gelecek cananım bir gün

Latifi söylüyor sözüne inan

Yandı bu dünyanın haline kanan

Var mı bu alemde ebedi kalan 

Azrail gelecek cananım bir gün

2003', 'Bu dünya malına sakın güvenme  Azrail gelecek cananım bir gün Ağayım paşayım diye övünme Azrail gelecek cananım bir gün Bu dünya fanidir bun...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-gun-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanem', 'kar-tanem-vedat-sarapci-x934p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen sevdiğim, kar tanem,

Gözlerimde aşk pırıltısı,

Kirpiklerimde sevgi damlacığı,

Dudaklarımda sevda şarkısı,

Kalbimde hasretim oldun.

(İstanbul, 8 Kasım 2000)', 'Sen sevdiğim, kar tanem, Gözlerimde aşk pırıltısı, Kirpiklerimde sevgi damlacığı, Dudaklarımda sevda şarkısı, Kalbimde hasretim oldun. (İsta...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şarapcı']::text[], 8.5, '{"poet":"Vedat Şarapcı","poet_slug":"vedat-sarapci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kar-tanem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyâmet Sahneleri (1. Perde)', 'kiy-met-sahneleri-1-perde-ali-tosmer-ka0vk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bedenin; 

kefene sarıldığı

mezara varıldığı

toprakla karıldığı

..............zaman..

dağların savrulduğu

yüreğin kavrulduğu

dünyanın kıvrıldığı

................zaman..

göklerin yarıldığı

mahşere varıldığı

hısımın darıldığı

.............zaman..

mîzanın kurulduğu

amelin sorulduğu

canların yorulduğu

.................zaman..

ateşin yakıldığı

geriden bakıldığı

korkunun takıldığı

................zaman..

hesâbın görüldüğü

defterin dürüldüğü

ateşe sürüldüğü

..............zaman..

..............hâlimiz yaman...

(eskidünya’03)', 'Bedenin;  kefene sarıldığı mezara varıldığı toprakla karıldığı ..............zaman.. dağların savrulduğu yüreğin kavrulduğu dünyanın kıvrıld...', ARRAY['Türk Edebiyatı','Şiir','Ali Tosmer']::text[], 8.5, '{"poet":"Ali Tosmer","poet_slug":"ali-tosmer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kiyamet-sahneleri-1-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sipariş', 'siparis-bekir-necati-voie8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A be

küçüğüm! 

    bilir-mi-ki

          Şarkı söylemesini

Bilseydi

    söylerdi

          her hal

                    en incesinden

Bağıra

         bağıra

                  seni çağıra

          tüm

                haylazlığıyla

Diyene kadar

‘Yak gözlerinin fenerini’        

Desene!           

Ne zaman

          Nasıl                     

Işıldar 

          gözlerinin   sesi

Hani  kolay değildir 

Günde üç öğün

elde-avuçta olmadan

çalmadan

       dilenmeden

ama kandırarak kendini

      Umudu

          Beslemek

  Zor iş be-Zor iş

                                Benimkisi

     Diyeceğim odur ki

             yine-yeniden

                   yeni-yineden

                          hemi

                    daha

              niceden  ince hisseden,

  Nazım’sa hisseden

  ‘Saman sarısı’nı  yürekten,

Almış yarasını en derinden

ve daha

          düşmeden

ve daha

          duymadan

ve daha daha

          sarılmadan

                     düşteki bakır saçlısına

Eksiğimdir,

                    olursa

                          eğer bir gün

Elma

 alacağım-yarım-

             en yarısından,

                   en iri-yarısından-

Ayva

    Nar

Bir de

çok sevdiğim Kirazdan

Ama  

Ne

 onun mevsimi

      ne benim

      mevsim dönmekte

      kısala

        kısala

           kısala     

                kara kışa

        

Siparişini 

           Verdim

                     meyhanedeki arkadaşlara  dedim 

       Hastalık

             Riyalık

                     Kahpelik   olmayacakmış

Başladı

           peş

              peşe

                      dökülmeye

inci çiçeklerim  

okudukça karıştı 

gözüm sesine sesin gözlerime

Ayıp değil ya, Dedim ya

KÜÇÜĞÜM!', 'A be küçüğüm!      bilir-mi-ki           Şarkı söylemesini Bilseydi     söylerdi           her hal                     en incesinden Bağıra ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/siparis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz Kalpler', 'caresiz-kalpler-sahin-yenilmez-rdv8m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi bittiği zaman

Çaresiz kaldığı zaman

Gözleri dolduğu zaman

Ağlamak ister çaresiz kalpler.

Terk edildiğini anlayınca

Yapayalnız tek başına kalınca

Her kapı çalışında o gelmeyince

Haykırmak ister çaresiz kalpler.

İşte yine akşam oldu

Kalpler sevgi yerine hüzünle doldu

Onlar için yine zaman durdu

Ölmek ister çaresiz kalpler.

Hep beklerler gideni

Belki döner geri

Umutludurlar her zaman ki gibi

Bilmezki çaresiz kalpler; 

Giden dönmez ki geri.', 'Sevgi bittiği zaman Çaresiz kaldığı zaman Gözleri dolduğu zaman Ağlamak ister çaresiz kalpler. Terk edildiğini anlayınca Yapayalnız tek başı...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caresiz-kalpler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Bir Sızı', 'gurbet-bir-sizi-i-brahim-ugur-toprak-an99w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ooof be ana

Bir gece daha başladı

Uzun, soğuk ve yağmurlu

Hava karamsar, hava puslu

Ben de dayanacak takat kalmadı

Bir uğultu var ana

Bir uğultu, kulaklarımda

Gözlerimde yaş var

Kalbimde kapanmayan bir yara

Bu dinmeyen hasret,

Çekilmeyen gurbet 

Hiç de yabancı değil bana

Ne kadar hasretse

Çöller yağmura,

Ne kadar uzaksa

Yollar güneşe,

O kadar gurbette

O kadar uzaktasın bana

Uzakta be ana

Çok uzakta

Tükenmiyor ki dertler

Geçmeyen gecelerde

Boğuluyor tüm ümitler

Hasret denizinde

Ne kadar basmak istesem de

Taşlar bağrıma

Ne kadar basmak istesem de

Tuzlar yarama

Olmuyor be ana

Çekilmiyor bu çile

Kapanmıyor bu yara

Hasret çok acı

Hayat desen yalancı

Gurbet Kalbimde Bir Sızı

Çekilmiyor be ana

Geçmiyor günler 

Sen olmayınca yanımda

Sevgimi gönderiyorum sana

Esen rüzgarlarla

Gözyaşlarımı gönderiyorum

Yağan yağmurlarla

Özlemimi belirtiyorum

Gurbet şiirleriyle, hasret şarkılarıyla

Sana sarılıyorum ana

Dalgaların kumsala sarıldığı gibi

Seni seviyorum ana

Yağmurun bulutu

Gecenin yıldızları sevdiği gibi

İnsanların umudu

Ceylanların dağları sevdiği gibi

Seviyorum

Seni çok seviyorum be ana

Hem de çok

14.01.99/Perşembe

    23:22/Tekirdağ', 'Ooof be ana Bir gece daha başladı Uzun, soğuk ve yağmurlu Hava karamsar, hava puslu Ben de dayanacak takat kalmadı Bir uğultu var ana Bir uğ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/gurbet-bir-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Hayır Deme', 'aska-hayir-deme-ali-coskun-hirik-64jlw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay her zamanki gibi senin yüzün

Şiir senin duruşun nette her sabah

Kayıtsız kalma bana, yüreğini boğar hüzün

Açık bırak kapını, seni de sevsin Allah…

Hayırsız bulutlara kapılıp gitme sakın

Artık bu aşkın dönülmez bir yerindeyiz

Yaşamak ve paylaşmak ikimize daha yakın

Issızlığı yüreğine ferman diye yazma

Rahat ol ki, ikimizde Leyla ile Mecnun değerindeyiz…

Düşüncelerin seni bana yaklaştırsın her sabah 

Emeğimizin karşılığını aşk olarak alalım gel

Muhayyilemize kazdığımız bu mutluluğumuzu ah

Ellerimizle büyütelim ki geniş açılsın içimizdeki pergel….', 'Ay her zamanki gibi senin yüzün Şiir senin duruşun nette her sabah Kayıtsız kalma bana, yüreğini boğar hüzün Açık bırak kapını, seni de sevs...', ARRAY['Türk Edebiyatı','Şiir','Ali Coşkun Hirik']::text[], 8.5, '{"poet":"Ali Coşkun Hirik","poet_slug":"ali-coskun-hirik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aska-hayir-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardesim..!', 'kardesim-mehmet-kalay-5bqpq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kardesim....! ! ! ! ! 

Ruhuma hicran oldu dizelerin aska geldim.

Diledim, yüregine, ruhuna sağlık.

Beni bana anlatırken ruhun, gözlerim buğulandı, yüreğim sıkıstı.

Buldum kendimi dizelerinde. 

Keşfettim aşkı, 

Keşfettim sevgiyi, 

Keşfettim mutluluğu, 

Keşfettim özlemi. 

Yine, yeniden.

22.12.2003 - İstanbul

UMUT''a', 'Kardesim....! ! ! ! !  Ruhuma hicran oldu dizelerin aska geldim. Diledim, yüregine, ruhuna sağlık. Beni bana anlatırken ruhun, gözlerim buğu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kardesim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelin', 'pelin-selami-selok-5ve7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gidi Pelin seni.

Bilmezdim kış günleri,

gökyüzünde parlayan güneşi,

sen çağırırmışsın.

Seni gidi Pelin seni.', 'Seni gidi Pelin seni. Bilmezdim kış günleri, gökyüzünde parlayan güneşi, sen çağırırmışsın. Seni gidi Pelin seni....', ARRAY['Türk Edebiyatı','Şiir','Selami Selok']::text[], 8.5, '{"poet":"Selami Selok","poet_slug":"selami-selok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/pelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Âlemde Bir Devir Dönüyor Amma', 'lemde-bir-devir-donuyor-amma-seyrani-atas3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Âlemde bir devir dönüyor amma

Devr-i İngiliz mi Frenk mi bilmem

Halli kolay değil, pek güç muamma

Zâlim zulmü göğe direk mi bilmem

Üzerimden güneş doğup aşıyor

Eriyip kar gibi bahtım üşüyor

Gönül tandırında bir aş pişiyor

Yanan ciğer midir, yürek mi bilmem

Aşkımın sönmüyor, eyvah közleri

Ne gecesi belli, ne gündüzleri

Dinleyene Seyranî''nin sözleri

Gerek değil midir, gerek mi bilmem', 'Âlemde bir devir dönüyor amma Devr-i İngiliz mi Frenk mi bilmem Halli kolay değil, pek güç muamma Zâlim zulmü göğe direk mi bilmem Üzerimden...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alemde-bir-devir-donuyor-amma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ın Emrine Mutiim Dersen', 'allah-in-emrine-mutiim-dersen-seyrani-3dnxq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allah''ın emrine mutiim dersen

Resûl''ün emrine itaat eyle

Helâl haram demez bulduğun yersen

Mü''minlik sözünden feragat eyle

Zahm-ı aşka gelip merhem sarmağa

Ferhâd olup bir gün bağrın yarmağa

Kudretin yoğise Beyt''e varmağa

Gönül Beytullah''tır ziyaret eyle

Kulun rızkın verir hazret-i Bâri

Açılan gülleri incitmez hârı

Kötülük değildir er kişi kârı

Kemlik edenlere inâyet eyle

Kalbini geniş tut sıkma Seyranî

Rıza-yi Bâri''den çıkma Seyranî

Gönül beytullahtır yıkma Seyranî

Elinden gelirse imâret eyle', 'Allah''ın emrine mutiim dersen Resûl''ün emrine itaat eyle Helâl haram demez bulduğun yersen Mü''minlik sözünden feragat eyle Zahm-ı aşka gelip...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-in-emrine-mutiim-dersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esinti', 'esinti-gurbuz-vural-360tq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin kokunu taşıyor,

tüm rüzgarlar bana.

acımadan esiyorlar bana

Seni çalıyorum tüm rüzgarlardan,

katıyorum,

içimdeki tufana.', 'Senin kokunu taşıyor, tüm rüzgarlar bana. acımadan esiyorlar bana Seni çalıyorum tüm rüzgarlardan, katıyorum, içimdeki tufana....', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esinti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2 Kendimi Yazıyorum', '2-kendimi-yaziyorum-arzu-bagriacik-cuxiy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizliğimi,

Karanlıkları,

Yalnızlığımı,

Direnişlerimi,

Özleyişlerimi,

Kararımı,

Hayatımın akışını.

Seni; 

Bekleyişlerimi…

12.12.2003 Ankara', 'Sessizliğimi, Karanlıkları, Yalnızlığımı, Direnişlerimi, Özleyişlerimi, Kararımı, Hayatımın akışını. Seni;  Bekleyişlerimi… 12.12.2003 Ankar...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/2-kendimi-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Arısına Düşürme Telaş', 'askin-arisina-dusurme-telas-seyrani-qxngc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın arısına düşürme telaş

İster isen benden bal, kara gözlüm

Muhabbet dilersen semtinde dolaş

Dilemezsen gamda kal, kara gözlüm

Er gerektir erin kadrin bilmeğe

Âşık gerek mâşuk gülün dermeye

Mevlâ kul keyfince meyva vermeye

Kaadir yaratmağa dal, kara gözlüm

İnsan dedikleri hep bir soy imiş

Kudret ölçüsünde hep bir boy imiş

Gönül kimi sever güzel o imiş

Sen haktan dileğin al, kara gözlüm

Yükseklerde taşkın esne, yel gibi

Bulandırma Seyranî''yi, sel gibi

Haddeden çekilmiş demir tel gibi

Çek beni bağrına çal, kara gözlüm', 'Aşkın arısına düşürme telaş İster isen benden bal, kara gözlüm Muhabbet dilersen semtinde dolaş Dilemezsen gamda kal, kara gözlüm Er gerekti...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-arisina-dusurme-telas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılmamış Şiir', 'yazilmamis-siir-refik-recep-pelit-gaxhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğduk işte yazılmamış şiir''dik

Bu aleme ısmarlama gelmedik

Manzumeler yazıldı biz seyrettik

Arz''ın rahminde, Arz''la ahretlik

Şiir gibi geçen zamanı resmettik

Ömür geçti seneleri  devrettik

Bir yel esti geç''de olsa farkettik

Maksud koynunda baht''la devrildik.

Bir yok için gönülleri terkettik 

Destanları hiç uğruna  mahvettik

Sevdaları riyalarla zikrettik 

Aşk''ı yurdunda şehvet ile kirlettik

Zehredip ömrü yudumlamadan içtik

Zevk-i sefa ile kendimizden geçtik

Zamana kanıp gayb''a doğru seğirttik

Hakikatin içinde taklitlerle sevindik.', 'Doğduk işte yazılmamış şiir''dik Bu aleme ısmarlama gelmedik Manzumeler yazıldı biz seyrettik Arz''ın rahminde, Arz''la ahretlik Şiir gibi geçe...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazilmamis-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Eleğini Aldım Elime', 'askin-elegini-aldim-elime-seyrani-o4qbq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın eleğini aldım elime

Çalkamadan unu eler eleğim

Dil ağlar avunmaz pîr-i velime

Beşiğine niyaz edip belerim

Beşik bulunmazsa pîrin evinde

Salıncak çok şah''ı Merdan Ali''mde

Demir asâ aşındırıp elimde

Ayağıma demir çarık delerim

Terk eyledi gönül kuşu yuvasın

Bulamadım ben bir yayla havasın

Buluncaya kadar derdim devasın

Elbette ağlarım sanma gülerim

Ey Seyranî sağmal ile yozumu

Sınamışım taşlı değil düzümü

Arzularım ben bulamam kuzumu

Dertli dertli koyun gibi melerim', 'Aşkın eleğini aldım elime Çalkamadan unu eler eleğim Dil ağlar avunmaz pîr-i velime Beşiğine niyaz edip belerim Beşik bulunmazsa pîrin evind...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-elegini-aldim-elime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Çıkarma Gönlünden', 'beni-cikarma-gonlunden-seyrani-ifmhp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni çıkarma gönlünden

Kulun kurbanın olayım

Karanlıkta cân ü dilden

Şem''i sûzanın olayım

Eser ise seher yeli

Irgalanır zülfü teli

Dudu gibi açıp dili

Oku fermanın olayım

Aldı aklım kaşın yayı

Divâneden gedâ bayı

Ak döşüne bu ednâyı

Takın gerdanın olayım

Zülfünün telleri tûba

Seyranî canım merhaba

Dokunursa bâd-ı sabâ

Örtün yorganın olayım', 'Beni çıkarma gönlünden Kulun kurbanın olayım Karanlıkta cân ü dilden Şem''i sûzanın olayım Eser ise seher yeli Irgalanır zülfü teli Dudu gibi...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-cikarma-gonlunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmediğin Nâsa Olursan Kefil', 'bilmedigin-n-sa-olursan-kefil-seyrani-lvppk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmediğin nâsa olursan kefil

Acını kesemez tarçın zencefil

Düşer itibardan olursun sefil

Cürümlerin süt kardeşi kefalet

Misafir bulursan hanene getür

Bir içim su ile keyfini yetür

Bir mümkün hâceti olsa bitür

Sen tig-i emrine eyle itaat

Örtülmüşü açma, açığı örtme

Er isen Seyranî bir can ürkütme

Hasisin, bahılın gayretin gütme

Sonradan görmüşten alma emanet', 'Bilmediğin nâsa olursan kefil Acını kesemez tarçın zencefil Düşer itibardan olursun sefil Cürümlerin süt kardeşi kefalet Misafir bulursan ha...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmedigin-nasa-olursan-kefil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler Yaratılmışların En Güzelidir', 'anneler-yaratilmislarin-en-guzelidir-tahsin-ozmen-8563k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anneler yaratılmışların en güzelidir.

.

-Bir insanı,

en çok annesi sever gerisi yalan.

Bir insanın adını,

en güzel annesi söyler gerisi yavan.-

.

-Bütün sevgileri topladım, bir anne sevgisi etmedi.-

.

Annem...!

Dört mevsim yediveren mor çiçekli bir daldı.

Tüm anneler gibi onun da binlerce karatlık bir yüreği vardı.

Balkondaki ipe çamaşır sermek yerine,

mahallemizin serçeleri okuyup kültürlensin diye şiirler asar,

Kuşlara edebiyat öğretmenliği yapardı.

.

-Yüreği güzel olanın dili de güzeldir.

Annemin gülüşünü,

merhem diye yıllarca sürdüm yüzümdeki acılara.-

.

Teri gül, teni gül Annem…!

Bir bilsen seni ne çooook severim…!

Bir gülüşüne güneşi kurban ederim…!

.

Karnını yurt bildiğim

Memesinde rızık bulduğum

Kucağında mutlu olduğum

Tek bir damla gözyaşına kıyamadığımı

Hiçbir şeyine doyamadığım

Yerine hiç kimseyi koyamadığım

Karşılıksız sevgim, Cennetteki elçim

Nefesi deva, her kelâmı dua

Teri gül, teni gül annem…!

.

-Hiçbir yokluk, anne yokluğuyla boy ölçüşemez.-', 'Anneler yaratılmışların en güzelidir. . -Bir insanı, en çok annesi sever gerisi yalan. Bir insanın adını, en güzel annesi söyler gerisi yava...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özmen']::text[], 8.5, '{"poet":"Tahsin Özmen","poet_slug":"tahsin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/siki-siki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Çağrı', 'sevgiliye-cagri-vedat-sarapci-rhaw6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel güzelim, gel Aşkım,

Senin için yarattığım,

Sevda çiçekleriyle donattığım,

Özleminle çağlayan,

Buram buram aşk kokan,

Gönül bahçeme gel.

Seni ister bahçedeki güller,

Mor zambaklar,

Beyaz leylaklar.

Şarkını söyler

Çağlayan dereler,

Şakıyan bülbüller.

Aşkınla parlar,

Gökkuşağındaki renkler,

Uçuşan kelebekler.

Ve hepsi bir ağızdan,

Seni özler seni bekler,

Gönül bahçeme gel Aşkım der.

Gel güzelim, gel Aşkım,

Gel ki sevdalar buluşsun,

Ayrılıklar biterken,

Arzulu fırtınalar durulsun,

Gel ki dünyam seninle, 

Aşkınla  dolsun.

(İstanbul, 12 Temmuz 2000)', 'Gel güzelim, gel Aşkım, Senin için yarattığım, Sevda çiçekleriyle donattığım, Özleminle çağlayan, Buram buram aşk kokan, Gönül bahçeme gel. ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şarapcı']::text[], 8.5, '{"poet":"Vedat Şarapcı","poet_slug":"vedat-sarapci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgiliye-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sulu Çeşmenin Başına Vardım', 'bir-sulu-cesmenin-basina-vardim-seyrani-zgqpg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sulu çeşmenin başına vardım

Testime bir damla suyu akmadı

Arzuhalim şaha uzatıp verdim

Merhametle nazar edip bakmadı

Çeşme boğazına halkasın takar

Benden gayrısının kabına akar

Cümle tiryakiye kav çakmak çakar

Bir çakım kavcık da bana çakmadı

Kerbelâ halinden olmuşuz âgâh

Susuz şehit etti Yezid-i gümrâh

Fırat ırmağında bir damla eyvâh

Merhamet tesbihin delip takmadı

Seyranî var her bir işin sebebi

Dolaşıktır ikbalinin kelebi

Fakrın uykusuna yatmış Arab''ı

Yâ kıyamet demiş yatıp kalkmadı', 'Bir sulu çeşmenin başına vardım Testime bir damla suyu akmadı Arzuhalim şaha uzatıp verdim Merhametle nazar edip bakmadı Çeşme boğazına halk...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sulu-cesmenin-basina-vardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Bi Rüya', 'nasil-bi-ruya-sirma-mersin-04v75', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir rüya gördüm; 

Mutluluğun adını yazmıştım,

Mavi beyaz bulutların üstüne.

Sevginin renklerini gökkuşağından çalıp,yüreğime taç yaptım...

Birden; yıldızları gökyüzünden tek tek kaydırıp,

Karanlığa bıraktım, ruhumu.

Şimşeklerin gürültüsü ile irkildim,

O an; rüyamı gözyaşlarımla bitirdim.

17.12.03', 'Bir rüya gördüm;  Mutluluğun adını yazmıştım, Mavi beyaz bulutların üstüne. Sevginin renklerini gökkuşağından çalıp,yüreğime taç yaptım... B...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nasil-bi-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can İpini Ten Yününden', 'can-i-pini-ten-yununden-seyrani-3fckv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Can ipini ten yününden

Saran kirmen ular bir gün

Sulu yalçınlar önünden

Açılan gül solar bir gün

Gül dalında diken yarar

Diken güle vermez zarar

Toprak bir gün başın tarar

Yolar saçlarını bir gün

Dünya olur bir gün harab

Ne bülbül kalır ne gurab

Rızka sebep olan türab

Gözlerine dolar bir gün

Kudret koçunu koyuna

Katmış seyreder oyuna

Ecel kolların boynuna

Habersizce dolar bir gün

Acı tatlı yenmez olur

Yalan gerçek denmez olur

Taş çarhıla dönmez olur

Hep kesilir sular bir gün

Çal Seyranî durma sazın

Hakka eyle sen niyazın

Sana secdesiz namazın

Kısmet olan kılar bir gün', 'Can ipini ten yününden Saran kirmen ular bir gün Sulu yalçınlar önünden Açılan gül solar bir gün Gül dalında diken yarar Diken güle vermez z...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/can-ipini-ten-yununden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Olur Bir Gün Harab', 'dunya-olur-bir-gun-harab-seyrani-hpjll', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya olur bir gün harab

Ne bülbül kalır ne gurab

Rızka sebep olan türab

Gözlerine dolar bir gün

Kudret koçunu koyuna

Katmış seyreder oyuna

Ecel kolların boynuna

Habersizce dolar bir gün

Acı tatlı yenmez olur

Yalan gerçek denmez olur

Taş çarhıla dönmez olur

Hep kesilir sular bir gün

Çal Seyranî durma sazın

Hakka eyle sen niyazın

Sana secdesiz namazın

Kısmet olan kılar bir gün', 'Dünya olur bir gün harab Ne bülbül kalır ne gurab Rızka sebep olan türab Gözlerine dolar bir gün Kudret koçunu koyuna Katmış seyreder oyuna ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-olur-bir-gun-harab-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ali-gencay-rzsj8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaman

kimi zaman

yıpratır eşyayı çürütür

eti kemik den ayırır öldürür

yaprağı düşürür dalından süründürür

zaman 

kimi zaman

rahme döl düşürür

el kadar sabiyi gün olur süründürür

geceyi güne katar yürütür

kah yalnız bırakır hüzünlüdür

kah eşin olur güldürür

zaman

kimi zaman

unutulursun 

düşündürür...... a.gencay', 'zaman kimi zaman yıpratır eşyayı çürütür eti kemik den ayırır öldürür yaprağı düşürür dalından süründürür zaman  kimi zaman rahme döl düşürü...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Nağmeleri -1', 'huzun-nagmeleri-1-sirma-mersin-gnwso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün nağmeleri çalınır; 

Her gece, aynı saatte,

Cama vuran yağmur tanecikleri ile

Geceyi saran; sessizlikle çoğalır, hayaller...

Düşündükce süzülür, damlacıklar...

Hüzün nağmeleri ile,

Kopup giden zaman,

Bırakamadığım yalnızlık canlanır, içinde...

Bir sevdanın esintisi kaplar, yüreğini.

Yeniden dönen anılar; 

Avutamazken benliğini,

Korkudan kaçar gibi; 

Ayrılıktan kaçmıştın...

Sonsuzluğun içine bıraktığın; 

Küçük sevinçler bile seni kurtaramamıştı,

Hüzün nağmelerinden! 

18.12.03', 'Hüzün nağmeleri çalınır;  Her gece, aynı saatte, Cama vuran yağmur tanecikleri ile Geceyi saran; sessizlikle çoğalır, hayaller... Düşündükce...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-nagmeleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Yağıyor', 'yagmur-yagiyor-ali-gencay-lrccg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmur yağıyor

ama toprak kokusu yok

şehrin beton duvarları buz gibi

oysa

bir kır bahçesinde yağmurla ıslanıp

kokusunu duymak vardı damlaların

toprakla kavuşmasının

balkonlarda

bir kaç begonya var

renkleri solmuş

güneşi arıyorlar

daracık sokaklarda

bir karanfil

ilişiyor gözlerime

kıpkırmızı

öle mağrur ki

öle güzel

sen gibi

kokusunu içime çekmek istiyorum

dokunmak kadife tenine

uzun uzun seyretmek istiyorum

çöküp dizlerim üzerine

konuşmak istiyorum

sen gibi

hakkın değil diyorum

bu balkonlar

ben yağmurun toprakla seviştiği

bir kır bahçesinde

görmüştüm

düşümde seni

sonra

ellerim titriyor

uzatıyorum sana

avuçlarım yanıyor sen gibi', 'yağmur yağıyor ama toprak kokusu yok şehrin beton duvarları buz gibi oysa bir kır bahçesinde yağmurla ıslanıp kokusunu duymak vardı damlalar...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yagmur-yagiyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurgular Penceresi', 'kurgular-penceresi-hakki-hakan-kaya-gd8pm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üniversitedeyim,

bakıyorum, 

kollarım dışarda

kurgular penceresinden,

koparmışken zincirini

sahipsiz düşünceler,

bir öğrencinin 

gözlerine vuruyorum

kurgular neşterini,

diğeri,

aşığıyla kavga ediyor,

sebebi ne diye

kurgular değişiyor,

sonra,

güneş vuruyor pencereye,

görüyorum aksimi,

ve kurgusuz 

anlamsız 

kendimi...', 'Üniversitedeyim, bakıyorum,  kollarım dışarda kurgular penceresinden, koparmışken zincirini sahipsiz düşünceler, bir öğrencinin  gözlerine v...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kurgular-penceresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlarda Nergis Sanırdım', 'daglarda-nergis-sanirdim-seyrani-wpbyy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlarda nergis sanırdım

Ala gözlü mestim seni

Sözünden özün tanırdım

Fehmederdim dostum seni

Lokma oldum hamurlardan

Ben soyundum samurlardan

Olur olmaz çamurlardan

Sakınmazdım üstüm seni

Varsam kırklar meclisine

Tuğra olsam sikkesine

Bir gerçeğin tekkesine

Seremedim postum seni

Dersin aldım ''İsm-i Hû''dan

Kara toprak kanlar yudan

Seyranî keyfimce sudan

Doldurmadım testim seni', 'Dağlarda nergis sanırdım Ala gözlü mestim seni Sözünden özün tanırdım Fehmederdim dostum seni Lokma oldum hamurlardan Ben soyundum samurlard...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daglarda-nergis-sanirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğindeyim', 'yuregindeyim-ali-gencay-xryo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bırak öle kala kalayım	

yüreğinde

ellerim üşüdüğünde

gözlerimi kapayıp

ellerini ellerime vermeliyim

ve gece düşlerime

girmelisin

seni seyretmeliyim

saçlarının düştüğü yerleri kıskanıp

gözlerinin

daldığı yerde olmalıyım

hani

oturup

pencerenin kenarına

nefesinle buğulanan

o pencerende

dokunup

çizdiğin resimim ben

bir gölge

belirdiğinde

o lambanın altında

çırpınıp duran yüreğinim

kalbinin

sesini duyuyorum

çok uzaklarda olsan da

yüreğinin

yandığı yerdeyim ben

güldüğünde

dudaklarında açan karanfilim

yumduğunda gözlerini

hayalinim

işte bu

benim sende olanım

sen

bende büyüyor

ben sen oluyorum

ellerin titrediğinde

götür dudaklarına

parmaklarını

parmak uçlarındayım ben

sen rahat ol

sevdiğim

senin yüreğindeyim ben', 'bırak öle kala kalayım	 yüreğinde ellerim üşüdüğünde gözlerimi kapayıp ellerini ellerime vermeliyim ve gece düşlerime girmelisin seni seyret...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yuregindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''a', 'istanbul-a-ali-gencay-f8t6a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün doğarken

bir sızı var yüreğinde istanbul''un

pare pare har yanı

heryanı kızıl ateş kan kırmızı

bir kadın gibi sevdiğim

o yedi tepeli heybetli şehir

acı çekiyor görüyorum

hissediyorum seni

ey sevdiğim şehir

ey ıstanbul

ellerimi uzattım ama dokunamadım sana

kandillerle aydınlanmış gecenden

sıyrıldın uyandın kanla kızılla

ey sevdiğim şehir

ey ıstanbul

yüreğine ektiğim sevda tahumlarım var

her tepene gömdüğüm masallarım

sevdiğim var

sen yıkılma sen ayakta dur

ey kadın gibi sevdiğim ıstanbul

sana ihtiyacım var.....

20.11.2003          a.gencay', 'gün doğarken bir sızı var yüreğinde istanbul''un pare pare har yanı heryanı kızıl ateş kan kırmızı bir kadın gibi sevdiğim o yedi tepeli heyb...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/istanbul-a-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Nağmeleri -2', 'huzun-nagmeleri-2-sirma-mersin-j0vq4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmeyen bir sevginin,

Yarım kalmış  şarkısı idi; 

Hüzün nağmeleri...

Dudaklarda dillenip,

Yüreklerde söylendi,

Bir ömür boyunca! 

Özleme sarılmış; 

Ayrılıkların acısını seslendirmiş,

Çaresizliğin tesellisi gecelerde yaşanmış! 

Hüzün nağmeleri...

20.12.03', 'Bitmeyen bir sevginin, Yarım kalmış  şarkısı idi;  Hüzün nağmeleri... Dudaklarda dillenip, Yüreklerde söylendi, Bir ömür boyunca!  Özleme sa...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/huzun-nagmeleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadeh', 'kadeh-sirma-mersin-lb0no', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doldurup duruyorum; kadehime, seni.

Yudum yudum içiyorum; sensizliği...

Hep efkarlı bir anıma; 

Rastlıyor, kahır dolu saatler,

Kadehleri birbir kırıp,

Naralar atıyorum,

Ne yapsam da; 

Değişmiyor sensizlik! 

Sevgi sarhoşu olmadan; 

Sensizliğe alışkın,

Bir alkollik oldum...

Hep efkarlı, hep kederli 

Ve yalnız bir alkollik! 

Beni bu hale koydun; 

Daha ne diyeyim? sana...

18.12.03', 'Doldurup duruyorum; kadehime, seni. Yudum yudum içiyorum; sensizliği... Hep efkarlı bir anıma;  Rastlıyor, kahır dolu saatler, Kadehleri bir...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kadeh-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dini Bütün Müslümanın Gözleri', 'dini-butun-muslumanin-gozleri-seyrani-e0ze8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dini bütün Müslümanın gözleri

Merhamet bahrine dalmada olur

Ârif söylemeden duyar sözleri

Kıssadan hisseyi almada olur

Bulunca ârifi can kurban verem

Ayağı altına yüzlerim sürem

Eyi gün dostuna eylesem kerem

Bir gözü kusura kalmada olur

Ârif kalkan edip sabr ü hilmini

Onunla def''eder zâlim zulmünü

Anlayan avcı avın ilmini

Kuşunu dumana salmada olur

Tabiplerin ilmin ehl-i dert okur

Derd-i Seyranî''ye derman mert okur

Ham sofular tesbih çeker vird okur

Gözü hayvan yemin çalmada olur', 'Dini bütün Müslümanın gözleri Merhamet bahrine dalmada olur Ârif söylemeden duyar sözleri Kıssadan hisseyi almada olur Bulunca ârifi can kur...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dini-butun-muslumanin-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmetse Gelecek Yaz Ölürüm', 'kismetse-gelecek-yaz-olurum-omer-faruk-karaman-6w98f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman,

İmkansız olan tek şey,

Ve sen,

Seni hatırlatır bana içtiğim her mey...

Ne çabuk geldik geçmişten bu güne değil mi,

Ne hızlı geçti zaman,

Peki sen bu süre içinde beni sevmeyi denedin mi,

Hiç beni düşündün mü ışıkları kapatıp,

Odanda bir an...

Ben mi? 

Beni ne yapacaksın,

Ama çok ısrar ediyorsan,

Ve yeniden duymak istiyorsan,

Sana ilk defa ne söylediysem,

Hala geçerli,

Bak yine söylüyorum,

Sana delicesine aşığım,

Bak yine haykırıyorum,

Seni çok seviyorum...

Ölmek mi? 

Bilmem ki,

Ama sen yaşarken öğrettin bana ölmeyi,

Çok mu istiyorsun ölmemi,

Çok mu istiyorsun benden kurtulmayı,

Bir seven yürek bu kadar ağır mı geliyor sana,

Sen niye anlamıyorsun, niçin denemiyorsun sevmeyi...

Kısmetse gelecek yaz ölürüm sevgilim,

Kısmetse kurtulursun seni seven bu Mecnundan,

Ve cennet bahçelerinin arasından,

Kısmetse sana bir gül koparır, gönderirim,

Sen rahat ol yeter ki,

Ben çekeyim acıları, sana yakışır mı ki,

Senden bir tebessüm istedim sadece,

Senden merhamet istedim,

Ve sırf o gözlerin için,

Kendimi parçalarcasına ağladım gecelerce,

Ama gönül kapını kapatmışsın bir kere,

Taşlaşmış yüreğin,

O gönlün anahtarı meçhul bir alemde,

O gizli şifreyi bulmandır tek dileğim...

Kısmetse gelecek yaz ölürüm sevgilim,

Kısmetse kurtulursun seni seven bu aşıktan,

Ve cennet bahçelerinin arasından,

Nasip olursa sana bir gül koparır gönderirim...

Sen mutlu ol üzülme,

Senin için en kısa zamanda ölürüm,

Ve ebedi istirahat edeceğim kabrime,

Ardımda bir gözyaşı döken olmadan gömülürüm...

Yine de yıkılmam korkma,

Yüzüm dökük, ellerim semada,

Sararlar kefeni bedenime,

En fazla yalnız kalırım,

Bana bir şey olmaz korkma,

Kabrimdeki kara toprak sulanır göz yaşımla,

Ağaçlar daha da yeşerir,

Belki senin o asık duran güzel yüzün de,

Ben öldüğüm için gülümseyiverir...

Sen gül yeter ki sevdiğim,

Ben seni düşünürüm,

Ve gelecek yaz senin için,

Bir daha dirilmemek üzere ölürüm...', 'Zaman, İmkansız olan tek şey, Ve sen, Seni hatırlatır bana içtiğim her mey... Ne çabuk geldik geçmişten bu güne değil mi, Ne hızlı geçti zam...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Karaman']::text[], 8.5, '{"poet":"Ömer Faruk Karaman","poet_slug":"omer-faruk-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/kismetse-gelecek-yaz-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Arkadaşım', 'cocukluk-arkadasim-omer-faruk-karaman-7b0jj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beraber geçti senle çocukluk günlerimiz,

Beraber göğüs gerdik seninle çilelere,

Mutluluktu seninle tek dileğimiz,

Çocukluk arkadaşım ne oldu bize...

Beraber yazardık en güzel aşk şiirlerini,

Sen bana ilham olurdun o zamanlar,

Senle birleştirmiştik kalplerimizi,

Çocukluk arkadaşım,sensiz olmuyor sabahlar.

Her sabah sen gelir çalardın zilimizi,

Senin geldiğini zil çalışından anlardım,

Hani kimseler ayıramazdı bizi,

Çocukluk arkadaşım, şimdi yokluğuna ağlarım.

Artık sensiz bomboş bizim sokaklar,

Senin neşen olmadan çekilmiyor burası,

Şimdi ağlıyor bize gülen akşamlar,

Çocukluk arkadaşım, döküldü üzüm asması...

Bizim çardak boş bekliyor senin yokluğunda,

Bahçedeki güller sen gelmeden açmıyor,

Gönlüm sevdanın yüksek uçurumunda,

Sensiz düşüp ölmekten korkuyor.

Ne zaman geleceksin aşkımızın yuvasına,

Ne zaman güleceksin bir daha yüzüme,

Ne zaman seni göreceğim karşımda,

Çocukluk arkadaşım geri dön beni üzme...', 'Beraber geçti senle çocukluk günlerimiz, Beraber göğüs gerdik seninle çilelere, Mutluluktu seninle tek dileğimiz, Çocukluk arkadaşım ne oldu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Karaman']::text[], 8.5, '{"poet":"Ömer Faruk Karaman","poet_slug":"omer-faruk-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocukluk-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Dair', 'yasama-dair-sirma-mersin-3mjx9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşama dair; 

Küçük sevinçlerle avunup, durmuşuz.

Kısa mutluluklarla beraber; özlemimizi yaşamışız,

Yaşama dair; 

Ayrlıklarsa, gözyaşlarına teslim olmuş,

Acılarla büyümüş, tüm yalnızlığımız birlikte.

Yaşama dair; 

Herşey birden bire değişiyorken,

Hayaller, hep umuda sarılıyor,

Kaybolan sevdaları arıyorken...

22.12.03', 'Yaşama dair;  Küçük sevinçlerle avunup, durmuşuz. Kısa mutluluklarla beraber; özlemimizi yaşamışız, Yaşama dair;  Ayrlıklarsa, gözyaşlarına ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasama-dair-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık ve Sessizlik', 'karanlik-ve-sessizlik-sirma-mersin-66pzc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlığın içine sığınmış,

Siyah beyaz hayaller! 

Hatırladıkca; 

Geçmişe dönen, küçük sevinçler canlanıverir.

Odanın sessizliğinde...

Ürkütmez! 

Sessizliğin sesi,

Sevdasız kalmış yüreği.

Karanlık ve sessizlik; 

Dağıtır, hayalleri...

Kırık dökük bir kalbim,

Tam ortasına.

22.12.03', 'Karanlığın içine sığınmış, Siyah beyaz hayaller!  Hatırladıkca;  Geçmişe dönen, küçük sevinçler canlanıverir. Odanın sessizliğinde... Ürkütm...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanlik-ve-sessizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öznel Savruluş', 'oznel-savrulus-ahmet-aksoy-weq8t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne zaman sen gelsen aklıma

küçükken küstüğüm çocukları hatırlıyoum

nasılda solgun bakarlardı

............................haksız olduklarında

çocuklardı solarlardı

ki bende dargınlığından beri

...öylesine suskun öylesine sessiz

öylesine garip oldum ki

içimdeki çocuk ölüm döşeğinde

bırak ölsün diyeceksin belki

............ama

ben hiç büyümedim ki! 

ne zaman sen gelsen aklıma

...beni terk ettiğin sıra çalan

...........müzik çalmaya başlıyor

ve gözlerimin önünde

......yine tekrarlar halinde

geleceğim kaldırılıyor katafalktan

ki şunu bilki sevgini sökmek için

........yüreğime döktüğün asit işledi

ve ellerini çektin giderken

.............kurduğumuz hayallerden

....bana yalnız haylar kaldı.', 'ne zaman sen gelsen aklıma küçükken küstüğüm çocukları hatırlıyoum nasılda solgun bakarlardı ............................haksız olduklarında...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oznel-savrulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emr-i Hak Bizi Deli Dolandırır', 'emr-i-hak-bizi-deli-dolandirir-seyrani-i7iku', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Emr-i Hak bizi deli dolandırır

Feleğin işine hile olur mu

İnsanı gafletten aşk uyandırır

Bize bundan özge çile olur mu

Okuyup hıfzettik biz yârın adın

Sundu ağzımıza lezzetli tadın

Biz şahlar şahının yedik tokadın

Bize bundan özge çile olur mu

Seyranî, seyrettim bir pîran demi

Ne devlet ki bulur ekser âdemi

Kabtan kaba koyar takdir âdemi

Öyle olmayınca böyle olur mu', 'Emr-i Hak bizi deli dolandırır Feleğin işine hile olur mu İnsanı gafletten aşk uyandırır Bize bundan özge çile olur mu Okuyup hıfzettik biz ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/emr-i-hak-bizi-deli-dolandirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şansa Rağmen', 'sansa-ragmen-ahmet-aksoy-6wl2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zarlar atıldığında

gelen sayıları toplandığında

şans dersin

........şans eseridir gelen

on iki de olsa iki de

...şans dersin

ama iki gelince kızar

..........on iki gelince gülersin.', 'zarlar atıldığında gelen sayıları toplandığında şans dersin ........şans eseridir gelen on iki de olsa iki de ...şans dersin ama iki gelince...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sansa-ragmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erenler Üstadlar Ettiler Himmet', 'erenler-ustadlar-ettiler-himmet-seyrani-7lst4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erenler üstadlar ettiler himmet

Bize Yaradan''ın kuludur diye

Anınçün onlara eyleriz minnet

Bu yolda bizlerden uludur diye

Ferhad gibi dağ bağrını delmedim

Mecnun gibi Leylâ deyip yelmedim

Ben destime su doldurup gelmedim

Erenler çeşmesi suludur diye

Seyranî seyrimden geri durmadım

İnişe yokuşa atım yormadım

Güzelin çirkinin telin kırmadım

İsm-i Hak dilinde doludur diye', 'Erenler üstadlar ettiler himmet Bize Yaradan''ın kuludur diye Anınçün onlara eyleriz minnet Bu yolda bizlerden uludur diye Ferhad gibi dağ ba...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/erenler-ustadlar-ettiler-himmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Everek Şehrinde Bir Güzel Gördüm', 'everek-sehrinde-bir-guzel-gordum-seyrani-sjdtx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Everek şehrinde bir güzel gördüm

O da düşmüş bir kötününün eline

Ol hâk-i payine yüzümü sürdüm

Salınıp giderken kendi iline

Yüz yüze geldim günlerden bir gün

Cennetten etmişler dünyaya sürgün

Kötüye düşmüş de gönülü kırgın

Hayran oldum tatlı güzel diline

Selâmı verince eğlendi biraz

Atardı ağzına uğrunca çerez

Dudağının rengi sultanî kiraz

Hiç bir gül benzemez kendi gülüne

Karşıma geçmiş de gözünü süzer

Sanki Seyranî''nin bağrını ezer

Saçının bir teli bir cana değer

Bin kız kurban olsun böyle geline', 'Everek şehrinde bir güzel gördüm O da düşmüş bir kötününün eline Ol hâk-i payine yüzümü sürdüm Salınıp giderken kendi iline Yüz yüze geldim ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/everek-sehrinde-bir-guzel-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezelden Her Kısmet Verilir İken', 'ezelden-her-kismet-verilir-i-ken-seyrani-pe6s5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ezelden her kısmet verilir iken

Aşık olsun dedi canan bizlere

Ruhlar bir araya derilir iken

Aşk nasip eyledi Sübhan bizlere

Dergah-ı Mevla''nın mihmanesiyiz

Cam-ı ilahinin mestanesiyiz

Mahbub-ı Hüda''nın divanesiyiz

Ehl-i diller olur hayran bizlere

Seyrani ednayız türab aslımız

Seyrani yektayız türab aslımız

Seyrani danayız türab aslımız

Niye yerimizdir mihman bizlere', 'Ezelden her kısmet verilir iken Aşık olsun dedi canan bizlere Ruhlar bir araya derilir iken Aşk nasip eyledi Sübhan bizlere Dergah-ı Mevla''n...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ezelden-her-kismet-verilir-iken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Dedem Senden Himmet Beklerim', 'yesil-dedem-senden-himmet-beklerim-i-brahim-saritas-dnp2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seher vakti elim açtım açtım semaya

Selamlar gönderdim canım canana

Koklayıp ta onu bastım bağrıma

Yeşil Dedem senden himmet beklerim

Gökyüzü aydınlık içim karanlık

Nasip eyle Dedem yare yarenlik

Unutulsun artık zalim ayrılık

Yeşil Dedem senden himmet beklerim

Güneş artık bugün umutla doğar

Canım bugün beni aşkla kucaklar

Herkes kendisine bir himmet arar

Yeşil Dedem senden himmet beklerim

Sen iyi bilirsin bende olanı

Nasip eyle Dedem seni seveni

Yolundan isterim halden bileni

Yeşil Dedem senden himmet beklerim

Sakın beni yollarından ayırma

Sevgiliye beni sen hasret koyma

Günahıma bakıp ayrıyız sanma

Yeşil Dedem senden himmet beklerim

Günahım fazladır bende bilirim

Naçarım düşmüşüm kötüdür halim

Yaram çok derindir gel arz edeyim

Yeşil Dedem senden himmet beklerim

KADİR DEDEM beni SEN yalnız koyma

ZEHRA SULTAN sevdiğimden ayırma

HAK HALİLİM derman senden yarama

Ey erenler sizden medet beklerim…

17,10,2003    03:15', 'Seher vakti elim açtım açtım semaya Selamlar gönderdim canım canana Koklayıp ta onu bastım bağrıma Yeşil Dedem senden himmet beklerim Gökyüz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıtaş']::text[], 8.5, '{"poet":"İbrahim Sarıtaş","poet_slug":"i-brahim-saritas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yesil-dedem-senden-himmet-beklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek Bir Gün Bize Bir Yol Gülmedi', 'felek-bir-gun-bize-bir-yol-gulmedi-seyrani-qnjyh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Felek bir gün bize bir yol gülmedi

Tuğlar taktı elin Seyranîsine

Yirmi dokuz harften al mahlâs deyi

Teklif eder durur Seyranî''sine

Er isen sözünü yürüt, bin ata

Söz ona değildir, bencedir ata

Olur olmaz adam söz ata ata

Pâre pâre oldu Seyranî''sine

Her âşık içtiğin hayat sanırlar

Her meclisi avlu, hayat sanırlar

Ben memat olsam da hayat sanırlar

Sağlığında girdi Seyranî''sine

Belki bu şeb bizde o yâr bulunur

Başı yastıktayken duyar bulunur

Sanma bu dünyada uyar bulunur

Everek''in ednâ Seyranî''sine', 'Felek bir gün bize bir yol gülmedi Tuğlar taktı elin Seyranîsine Yirmi dokuz harften al mahlâs deyi Teklif eder durur Seyranî''sine Er isen s...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/felek-bir-gun-bize-bir-yol-gulmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bir Boyadan Rengin Almadı', 'gonul-bir-boyadan-rengin-almadi-seyrani-6hy8y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül bir boyadan rengin almadı

Her boyaya tavus gibi dalıyor

Cehennem nârına hâcet kalmadı

Aşk odu içimde dâim yanıyor

Gam suyuyla mayam böyle karılmış

Ki levh üzre kalem böyle yazılmış

Ciğerimin memesinden sarılmış

Gam yılanı kanım emip duruyor

Seyranî''nin iki gözü yaş oldu

Aşk-ı Mevlâ cümle derde baş oldu

Kadı mutfağında pişmiş aş oldu

İçerimde fıkır fıkır kaynıyor', 'Gönül bir boyadan rengin almadı Her boyaya tavus gibi dalıyor Cehennem nârına hâcet kalmadı Aşk odu içimde dâim yanıyor Gam suyuyla mayam bö...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-bir-boyadan-rengin-almadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Irmağa Bir Yol vermiş Akıyor', 'her-irmaga-bir-yol-vermis-akiyor-seyrani-sh2su', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her ırmağa bir yol vermiş akıyor

Cümlesini bir deryaya döküyor

Her kumaşı bir tarakta dokuyor

Şeridini pazarlara çözüyor

Bülbülün aşkına sebep gül oldu

Ona kafes ağzındaki dil oldu

Cânım ateşlere attı kül oldu

Ne taraftan bir yel değse tozuyor

Kimi dikenini gülünden seçer

Herkes ettiğinin mahsulün biçer

Gam yeme Seyranî bu gün de geçer

Yüce dağ başında duman geziyor', 'Her ırmağa bir yol vermiş akıyor Cümlesini bir deryaya döküyor Her kumaşı bir tarakta dokuyor Şeridini pazarlara çözüyor Bülbülün aşkına seb...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-irmaga-bir-yol-vermis-akiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdris Terziliği İcat Etmeden', 'i-dris-terziligi-i-cat-etmeden-seyrani-hb7jo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İdris terziliği icat etmeden

Endazeden geçti boynumuz bizim

Anka yaratılıp Kaaf''a gitmeden

Bin Kaaf''ı beklerdi toyumuz bizim

Kalıbını değiştirse birimiz

Zâhit bin yıl yusa çıkmaz kirimiz

Hayatta pâk eder bizi pîrimiz

Murdar ölmek değil bizim huyumuz

Bir Seyranî vardır başı feslimiz

Cümlemiz çarıklı, yoktur meslimiz

Münkire karışmaz bizim neslimiz

Mehdi''den ayrılmaz soyumuz bizim', 'İdris terziliği icat etmeden Endazeden geçti boynumuz bizim Anka yaratılıp Kaaf''a gitmeden Bin Kaaf''ı beklerdi toyumuz bizim Kalıbını değişt...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/idris-terziligi-icat-etmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kulağım Var Hiçbiri Duymaz', 'i-ki-kulagim-var-hicbiri-duymaz-seyrani-ctmrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki kulağım var hiçbiri duymaz

Erenler izini izler ağlarım

Yüküm ağır yolum menzile uzak

Deve gibi ben de dizler ağlarım

Bir münasip tacım yoktur giyecek

Bir helâl ekmeğim yoktur yeyecek

Bir tabip bulmadım derdim deyecek

Derdi içerimde gizler ağlarım

Ulu bezirgânlar metaın satar

Üzümünü yeyip çöpünü atar

Kötü olan sözü soysuzlar tutar

Efendimden izin gözler ağlarım

Doğması farz ama ölmesi sünnet

Seyranî ecele eylemez minnet

Kimi hûri ister kimisi cennet

Ben Hakkın rızasın gözler ağlarım', 'İki kulağım var hiçbiri duymaz Erenler izini izler ağlarım Yüküm ağır yolum menzile uzak Deve gibi ben de dizler ağlarım Bir münasip tacım y...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-kulagim-var-hicbiri-duymaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmdâde Erişsin Ol Üftâdeler', 'i-md-de-erissin-ol-uft-deler-seyrani-b63nu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İmdâde erişsin ol üftâdeler

Pervâneleri yakan şem''ayiz biz

Aşkı uşşâka ver ki mutâdeler

Mest olan mestâne meyhâneyiz biz

Takdir-i ezelden yazılan gelir

Arayan âşıklar mâşukun bulur

Bu derdime vâkıf olanlar bilir

Olmayan ne bilir dürdâneyiz biz

Seyranî''yim aşka düştüm ezelî

Severler cihanda elbet güzeli

Kevser şarabından bâde süzeli

Arsa-i aşk içre merdâneyiz biz', 'İmdâde erişsin ol üftâdeler Pervâneleri yakan şem''ayiz biz Aşkı uşşâka ver ki mutâdeler Mest olan mestâne meyhâneyiz biz Takdir-i ezelden ya...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imdade-erissin-ol-uftadeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İptida Vücudun Yapan Üstada', 'i-ptida-vucudun-yapan-ustada-seyrani-ytb96', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İptida vücudun yapan üstada

Bes eylerim daim besten içeri

Sununca o pîrim bir kâse bâde

Aşk-ı Mevlâ girdi resten içeri

Hep böyle devreder felekler burçlar

Kendi kendim bildim affoldu suçlar

Aşkın kitabından yediler üçler

Ders verdiler bana dersten içeri

Seyranî''yim ben de Hakka dayandım

Gaflet uykusundan şükür uyandım

Gönül iklimini gezdim dolandım

Tunus Tırabulus Fas''tan içeri', 'İptida vücudun yapan üstada Bes eylerim daim besten içeri Sununca o pîrim bir kâse bâde Aşk-ı Mevlâ girdi resten içeri Hep böyle devreder fe...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iptida-vucudun-yapan-ustada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçan Validemi Rüyamda Görsem', 'kacan-validemi-ruyamda-gorsem-seyrani-2c42h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçan validemi rüyamda görsem

Kan ağlar gözleri yaşlı görünür

Bize edenlerin defterin dürsem

Ejder olmuş yedi başlı görünür

Haktan bulsun bize eden muzular

İki bacım kardeş der de bozular

Sılada bağrışır körpe kuzular

Mor sümbülüm siyah saçlı görünür

Seyranî''yim kaldı dostlar yasımda

İçtiğim su zehir oldu tasımda

Eşim dostum yolum bekler kasımda

Düz ovalar bize taşlı görünür', 'Kaçan validemi rüyamda görsem Kan ağlar gözleri yaşlı görünür Bize edenlerin defterin dürsem Ejder olmuş yedi başlı görünür Haktan bulsun bi...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacan-validemi-ruyamda-gorsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahır Çeken Ehl-i Dilin', 'kahir-ceken-ehl-i-dilin-seyrani-1xxsm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kahır çeken ehl-i dilin

Gör ne çeker can-ı tende

Erir akar böyle bilin

Tükenir tâb o bedende

Sen bir zalim neccar isen

Baltan bende dener isen

Ben ednâyı kınar isen

Benim gibi olun sen de

Kişi uğrar melânete

Güvenilmez kad kamete

Çıkarır bir selâmete

Hakk''ın kulu isem ben de

Hüzn ü elemden yatamaz

Zulüm alıp hak satamaz

Âşık Seyranî atamaz

Kimse ile hiç perende', 'Kahır çeken ehl-i dilin Gör ne çeker can-ı tende Erir akar böyle bilin Tükenir tâb o bedende Sen bir zalim neccar isen Baltan bende dener is...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kahir-ceken-ehl-i-dilin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-emin-baydil-18mjg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Heyyy gönül! ..

Sen ne uslanmaz bir şeymişsin! ..

En son hangi bir yerlerde? ..  hangi dalıydı / en son konduğun? 

Peki ya  tekme-tokat kovulduğun,

hangi kapıydı senin? ! ..

Kâh okşandın,

yumuk gözlerle bakıp ellerinden öpmedin mi? 

Etek uçlarından girip, bir parça sessiz sâkin,

alnından kakılıp da terslenmedin mi? ...

Bizler mi? ..  gerilerde bıraktık / demedin mi? 

demedin mi be hey gönül, bu son artık? ! ..

Yine de dağları deler aşarsın,

dünyayı, diz vurunca titretirsin yerinden.

Sen ve ben bilirdik huyumuzu; 

 bir vapur, nasıl ağlarsa öyle,

hani, nâraların her gece, bölerdi uykumuzu...

Ben bilmez miyim gönül, deli-divâne olduğunu; 

güllere dert yandığını...onlarla konuştuğunu...

Kelebekler kadar hafif,  incitmeden yormadan 

O kır çiçekleriyle dansını ilkbaharda / birkaç günlük

hani eğlenmiştik ve gülmüştük orda

bembeyaz gelinlikler giyinmiştin telli duvaklı / şahidin olmuştum...

İlk o zaman yapmıştık yağmurlarla kavgamızı,

Yapraklarını koparmıştık çiçeklerin / kim haklı, diye...

Görmez miyim,

gelip geçen her trene el salladığını,

her vagona her çeşit çiçekler bıraktığını...

Var mı acep bir selâm getiren yardan,

ve yine dolu-dizgin koştuğunu ardından

bilmez miyim? ! ...

Gönül sen,

sen yine yaparsın, biliyorum.

Hani, derler ya “alışmış, kudurmuştan beterdir” diye,

hani derler ya gönül! ferman dinlemediğini... dağları deldiğini...

Umurumda mı, bırak! diyorsun

çizen çizsin durmadan, duvarlara yazan yazsın...

Hani tiki olsa kızcağızın, sol gözü kırpsa bilmeden / kanarsın yine.

Yüzüne çarpılsa da kirli çamaşırlardan kalma sular, 

uslanmazsın...

Hiçbir şeye aldırmazsın / bakmazsın...

Sen ahmaksın, vesselâm...

                               KASTAMONU - 22.12.2003', 'Heyyy gönül! .. Sen ne uslanmaz bir şeymişsin! .. En son hangi bir yerlerde? ..  hangi dalıydı / en son konduğun?  Peki ya  tekme-tokat kovu...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/gonul-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Nefsim', 'ey-nefsim-i-brahim-saritas-60dd4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç düşünme nedir nerden gelmiştir

Eyvallah de at sineye ey nefsim

Dertleri verenler sevip vermiştir

Eyvallah de at sineye ey nefsim

Sanma ki yaşarsın burda ebedi

Kim hakkını aldı kim hakkın yedi

Karanlıkta bile Yusuf sabretti

Eyvallah de at sineye ey nefsim

Mecnun Leyla için çöllere düştü

Leyla’sını buldu Leyla’ya küstü

Kepek bitene dek yolda yürüdü

Eyvallah de at sineye ey nefsim

Bu dert deyip dertlerinden hiç kaçma

Dermanım yok deyip isyana kalkma

Dermanlar derttedir her dem unutma

Eyvallah de at sineye ey nefsim

Ondan gelen kötü iyiden iyi

O bilmiyor mu ki zaten her şeyi

Dar gününde bile kesme ümidi

Eyvallah de at sineye ey nefsim

Gördüm gönül dağın karla örtülmüş

Üzerini karabulut bürümüş

Aciz halin şikayete yürümüş

Eyvallah de at sineye ey nefsim

21,10,2003   02:55', 'Hiç düşünme nedir nerden gelmiştir Eyvallah de at sineye ey nefsim Dertleri verenler sevip vermiştir Eyvallah de at sineye ey nefsim Sanma k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıtaş']::text[], 8.5, '{"poet":"İbrahim Sarıtaş","poet_slug":"i-brahim-saritas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ey-nefsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılsın Kanunun Telleri Felek', 'kirilsin-kanunun-telleri-felek-seyrani-33l9y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırılsın kanunun telleri felek

Aksi murad üzre çaldığın yeter

Hakka, hakikata oldun büvelek

Zulmü adalete saldığın yeter

İskender deryanın almış haracın

Âb-ı hayat çeşmesinin taracın

Yememiş söndürmüştür sıracın

Sen benim ahımı aldığın yeter

İsrâfil''in Sûr''un alacak mısın

Kanununa koyup çalacak mısın

Sen cihanda bâkî kalacak mısın

Bu zamana kadar kaldığın yeter

Seyranî feleğin olsa edebi

Düşünür katmazdı şekere şebi

Sen de Nuh Nebî''nin gemisi gibi

Azap tûfanına daldığın yeter', 'Kırılsın kanunun telleri felek Aksi murad üzre çaldığın yeter Hakka, hakikata oldun büvelek Zulmü adalete saldığın yeter İskender deryanın a...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirilsin-kanunun-telleri-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Birinde Her Hevesim Yitirdim', 'kirk-birinde-her-hevesim-yitirdim-seyrani-xz8ez', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırk birinde her hevesim yitirdim

Kırk beşinde bağdaş kurup oturdum

Ellisinde göçüm çeküp götürdüm

Vâdesi yetmişe döndürdün felek

Elli beşte senetlerim yazdırdım

Altmışımda her düzenin bozdurdum

Altmışbeşte kemiklerim ezdirdim

Beni sübyanlara döndürdün felek

Âşık Seyranî''yi yakıp yandırıp

Hakkın rahmetinden verip kandırıp

En sonunda Azraili gönderip

Beni doğmamışa döndürdün felek', 'Kırk birinde her hevesim yitirdim Kırk beşinde bağdaş kurup oturdum Ellisinde göçüm çeküp götürdüm Vâdesi yetmişe döndürdün felek Elli beşte...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirk-birinde-her-hevesim-yitirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhemlerin Telef Etme Tabibim', 'merhemlerin-telef-etme-tabibim-seyrani-5jmxr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhemlerin telef etme tabibim

Yaralarım kabul etmez em benim

Tecelliden böyle imiş nasibim

İşim gücüm oldu derd ü gam benim

Can havfından geçit yere varılmaz

Selâmet geçmeye köprü kurulmaz

Kızılırmak gibi asla durulmaz

Hasret ile akan gözden nem benim

Seyranî geçmiş gün geçmez destine

Rabbim kavuştura çeşm-i mestime

Gam keder gurbette bindi üstüme

At gibi ağzıma taktı gem benim', 'Merhemlerin telef etme tabibim Yaralarım kabul etmez em benim Tecelliden böyle imiş nasibim İşim gücüm oldu derd ü gam benim Can havfından g...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merhemlerin-telef-etme-tabibim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Defterlerden İsmim Sildirdim', 'nice-defterlerden-i-smim-sildirdim-seyrani-dh34d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice defterlerden ismim sildirdim

Gelmedi hiç senden ses kara bahtım

Bahtın gemisinde yelken yok, bildin

Durma lodos gibi es kara bahtım

Ahdettim bir gonca yolmamasına

Bulmadım bir çare solmamasına

Bu derdinden iflah olmamasına

Kat''iyyen umudun kes kara bahtım

Dünya yıkılmakta yoktur yapıcı

Kimi cellât olmuş, kimi kapıcı

Evvel giymez iken mesti pabucu

Verdirdin çarığa mes kara bahtım

Ağır meclislerde sıkılmaz iken

Mengeneye versen bükülmez iken

Seyranî aslana yıkılmaz iken

Dedirdin tilkiye pes kara bahtım', 'Nice defterlerden ismim sildirdim Gelmedi hiç senden ses kara bahtım Bahtın gemisinde yelken yok, bildin Durma lodos gibi es kara bahtım Ahd...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nice-defterlerden-ismim-sildirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim Seninle Ettiğim Ahdi', 'rabbim-seninle-ettigim-ahdi-seyrani-mhosb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rabbim seninle ettiğim ahdi

Bulayım kal''a-yi iman içinde

Ahır zaman olup geçince vakti

Kalmasın imanım güman içinde

Kimin ayağına gelse bir oyun

Cellât satırına uzata boyun

Kendi rızasiyle kurda bir koyun

Veren var mı göster çoban içinde

Yumurtanın iki olsa sarısı

Beyazına çıkar onun yarısı

Cahil adam misli yaban arısı

Geç yapsa bal yapmaz orman içinde

Aşkın çıkrığını eğirse iği

Seyranî ateşsiz pişirir çiği

Okkanın dirhemin artık eksiği

Belli olur mizân irfan içinde', 'Rabbim seninle ettiğim ahdi Bulayım kal''a-yi iman içinde Ahır zaman olup geçince vakti Kalmasın imanım güman içinde Kimin ayağına gelse bir ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rabbim-seninle-ettigim-ahdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yeli Sen Mevlayı Seversen', 'seher-yeli-sen-mevlayi-seversen-seyrani-ih2xm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seher yeli sen mevlayı seversen

Sılada bir yârim var, seher yeli

Bu kâğıt içine üç beyit yazdım

Bul sen tenhada ver, seher yeli

Ezel ikrar verdi, n''oldu sözüne

Kul olayım, şifa bele nazına

Uyku arasında dokun yüzüne

Mübarek hatırın sor, seher yeli

Bakmaz mısın şu feleğin işine

Yaktı ciğerimi aşk ateşine

Pervaneler gibi dolan başına

Mübarek cemalin gör, seher yeli

Girmedim odaya baktı Seyranî

Mevlâya emanet verdi yârini

Benim sevdiğimin zülüflerini

Gerdânına dolayver, seher yeli', 'Seher yeli sen mevlayı seversen Sılada bir yârim var, seher yeli Bu kâğıt içine üç beyit yazdım Bul sen tenhada ver, seher yeli Ezel ikrar v...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seher-yeli-sen-mevlayi-seversen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takatim Kalmadı, Aşkın Yayının', 'takatim-kalmadi-askin-yayinin-seyrani-qt8z2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Takatim kalmadı, aşkın yayının

Çekip kirişinden kuramıyorum

Her gece düşümde bir hercaînin

Âteşi aşkından duramıyorum

Aşk u sevdâ hayal midir, zan mıdır

Mekânları can mı, bilmem ten midir

Cezbe dilden midir, dilberden midir

Dil bilmez dilberden soramıyorum

Seyf-i aşkım çarh-ı canda bileşir

Her binalar temelinden döleşir

Çoktanberi bu aşk ile güleşir

Gönül pehlivanın yoramıyorum

Lâle bağrın aşk oduna dağlamış

Bülbül güle âşık olup ağlamış

Seyranî''yi bir kıl ile bağlamış

Muhabbet bendidir, kıramıyorum', 'Takatim kalmadı, aşkın yayının Çekip kirişinden kuramıyorum Her gece düşümde bir hercaînin Âteşi aşkından duramıyorum Aşk u sevdâ hayal midi...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/takatim-kalmadi-askin-yayinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telgraf Dediğin Ebced Hesabı', 'telgraf-dedigin-ebced-hesabi-seyrani-0e6b6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Telgraf dediğin ebced hesabı

Bu rebap şeytanı cinden çıkarır

Ateş şöyle dursun tütün azâbı

Tilkiyi çakalı inden çıkarır

İplik gömlek olmaz dokutmayınca

Oğlan âlim olmaz okutmayınca

Ayı var et yemez kokutmayınca

Tilki var ölüyü sinden çıkarır

Seyranî der var mı bunun ötesi

Seğirden tazı evine yetesi

Ermeninin pastırması, ketesi

Kaypak Müslümanı dinden çıkarır', 'Telgraf dediğin ebced hesabı Bu rebap şeytanı cinden çıkarır Ateş şöyle dursun tütün azâbı Tilkiyi çakalı inden çıkarır İplik gömlek olmaz d...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/telgraf-dedigin-ebced-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerin Göğün İsmi Cismi Yoğiken', 'yerin-gogun-i-smi-cismi-yogiken-seyrani-bhgf8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yerin göğün ismi cismi yoğiken

Bir ezan okunur sedâsı nerde

El ermedik göz görmedik bir nesne

Yapılmış kubbesi, Hudâ''sı nerde

Bazı âşıklar da kendisin över

Kâmilin cevabın biri bin değer

Cümle kitap gökten inmezden evvel

Bir Kur''an okunur sadâsı nerde

Gözlerimden akan kanlı yaşlarda

Katrancasına dert bulunur başlarda

İlham derler bir kuş vardır kuşlarda

Gökten yere inmez yuvası nerde

Çok ahdettim konamadım bu dala

Yok imiş ikramın Hayyalesselâ

Ucu bulunmadık böyle bir mâna

Söyle kul Seyranî ustası nerde', 'Yerin göğün ismi cismi yoğiken Bir ezan okunur sedâsı nerde El ermedik göz görmedik bir nesne Yapılmış kubbesi, Hudâ''sı nerde Bazı âşıklar d...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yerin-gogun-ismi-cismi-yogiken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolunu Bekledim Böyle Kaç Zaman', 'yolunu-bekledim-boyle-kac-zaman-seyrani-gqf3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolunu bekledim böyle kaç zaman

Aç göğsünü düğmelerin der güzel

İnandım hakikat kalmadı güman

Uğrun uğrun bana meylin var güzel

Suubet değil mi sonu uzletin

Tanırsın bilirsin kadr ü kıymetin

Lezzetin mi bilmem acep vusletin

Niçin yaklaşmaya eylen ar güzel

Uzak giden memul belki vatandan

Çoğaldı noksanım damarda kandan

Eğer Seyranî''yi seversen candan

Yarasına durma merhem sar güzel', 'Yolunu bekledim böyle kaç zaman Aç göğsünü düğmelerin der güzel İnandım hakikat kalmadı güman Uğrun uğrun bana meylin var güzel Suubet değil...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yolunu-bekledim-boyle-kac-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam sancısı', 'aksam-sancisi-hakki-hakan-kaya-6hb2n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir akşam vakti çaresiz

gündüzün karanlığa yenilişi gibi

yine kafamda netleşmemiş 

benin bensiz hali

serseri bir yaprak

savruluyor fütursuzca 

kavrıyor rüzgar belinden

dansediyor havada 

sonra değişiyor müzik

çalıveriyor yere

yaprak mı ben mi

yerdeki...', 'bir akşam vakti çaresiz gündüzün karanlığa yenilişi gibi yine kafamda netleşmemiş  benin bensiz hali serseri bir yaprak savruluyor fütursuzc...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksam-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zelhâ Gibi Aşk Ateşi İçinde', 'zelh-gibi-ask-atesi-i-cinde-seyrani-m8kjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zelhâ gibi aşk ateşi içinde

Yusuf gibi düşün yorduğum güzel

Muhabbet menzili iki üçünde

Huzurunda divân kurduğum güzel

Sevda bizim beynimizde var oldu

Kırmızı gül etrafını hâr aldı

Gönül bu sevdana giriftar oldu

Yoluna bin tuzak kurduğum güzel

Seyranî der, sadık dosta yâr olsam

Dost gibi düşmana soğuk kar olsam

Kasvetin bilmem, haberdar olsam

Perişan hatırın sorduğum güzel', 'Zelhâ gibi aşk ateşi içinde Yusuf gibi düşün yorduğum güzel Muhabbet menzili iki üçünde Huzurunda divân kurduğum güzel Sevda bizim beynimizd...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zelha-gibi-ask-atesi-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulmünden Vekil-i Âl-i Resûl''ün', 'zulmunden-vekil-i-l-i-res-l-un-seyrani-wz8ja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zulmünden Vekil-i Âl-i Resûl''ün

Hicaptan sikkenin kızılı çıktı

Şer''in ahkâmında zevil-ukulün

Reylerinden âlem usandı bıktı

Varsa söyle zulmün boyun bükmezin

Bul ehl-i irfânın çile çekmezin

Adalet küpünün döküp pekmezin

Bu zulüm sirkesi küpünü sıktı

Seyranî mazlumun malın yiyenin

Mertebem Tanrıdan yüce diyenin

Dünyada Tanrılık tacın geyenin

Hak derya çamurun ağzına tıktı', 'Zulmünden Vekil-i Âl-i Resûl''ün Hicaptan sikkenin kızılı çıktı Şer''in ahkâmında zevil-ukulün Reylerinden âlem usandı bıktı Varsa söyle zulmü...', ARRAY['Türk Edebiyatı','Şiir','Seyrani']::text[], 8.5, '{"poet":"Seyrani","poet_slug":"seyrani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zulmunden-vekil-i-al-i-resul-un-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivrisinek İle Halimiz Yaman', 'sivrisinek-i-le-halimiz-yaman-dervis-halil-trmdy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sivrisinek ile halimiz yaman

Sor nice başım yorgana koydurur

Burnumla kulağım yerler her zaman

Kaşınmaktan derimizi soydurur

Katar katar olmuş gelir vız deyü

Çok kanımı içmişlerdir az deyü

Usul ile böyle çal''nur saz deyü

Nefeslerin birbirine uydurur

Akrep gibi sokar burnu kurusun

Acep nazik çalar Firenk borusun

Yanınca uydurmuş eşek arusun

Hesap edip alayların saydurur

Birbirin kovalayup yatarlar

Döşeğe girmeğe yanup tüterler

Böyle kaide-yle usul tutarlar

Sanasın kim nefesleri nay-durur

Kalkup mum yakup arayım derim

Başını gözünü yarayım derim

Dal satır cümlesin kırayım derim

Korkarım ki büyüklere duydurur

Geceyle derdimi kimise bilmez

Her birin kurşunla urursan ölmez

Söyleşmek kabildi yalınız gelmez

Hep eşkıyasın bile ivdirir

Sanursun cenkçidir alayın dizer

Avazın işinden canından bezer

Ellerin evinde beş on gün gezer

Bizim hanemizde altı ay durur

Gece herkese fikr etmede yarını

Meterisden dinler ah u zarını

Cümle alem çeker onun zorunu

Gerek geda gerek ise bay-durur

Derviş Halil eydür ayık yatamam

Sözlerim sahihdür yalan katamam

Üş dururum hiç birini tutamam

Cinne benzer bir acaip soy-durur', 'Sivrisinek ile halimiz yaman Sor nice başım yorgana koydurur Burnumla kulağım yerler her zaman Kaşınmaktan derimizi soydurur Katar katar olm...', ARRAY['Türk Edebiyatı','Şiir','Derviş Halil']::text[], 8.5, '{"poet":"Derviş Halil","poet_slug":"dervis-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sivrisinek-ile-halimiz-yaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fellahın Haline Akıllar Ermez', 'fellahin-haline-akillar-ermez-dervis-halil-sx36z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fellahın haline akıllar ermez

Aş yererler birbirinin leşine

Nil taştığı zaman gözleri görmez

Biri nobut salar yetmiş beşine

Babasına kıyar bu ne yürektir

Son miracı kazıktır ya kürektir

Gerdanları sanki mermer direktir

Beş kantar yük kaldırır kor başına

Hakkın emriyle işleri zardır

Güneşte yanmadan vücudu nardır

Yüz elli yaşında pirleri vardır

Kurşun vursan kıramazsın dişine

Kin kovarlar ömürleri gidince

Kuduz kelbe döner kanı tadınca

Gafir ''hit mal'' deyüp nida edince

Kırbaç girer cümlesinin düşüne

Orak elde kılıç gibi salarken

Tilki gibi ot içinde dalarken

Vardım seyreyledim birsim yolarken

Gidiler pek pehlivandır işinde

Sureta bir boynuz koyundur

Fursatın gözedir amma hayındır

Kırk yıl hizmet etse gene hayındır

Sakın anlar ile olma aşina

Bin kan eder bir paraya erince

Çalışırlar ta ki serin verince

Fursat ile hasmı ele girince

Mızrağ ile urur deler gûşuna

Acayiptir böyle bir kavim yoktur

Kiminin elinde kemandır oktur

Ol gani Sübhan''ın takdiri çoktur

Akıl isen fikr eyleyüp düşün e

Derviş Halil eydür işler ederler

Firavunun tarihini güderler

Beş yüz kırbacı kahvaltı ederler

Hiç bakmazlar ayaklar''nın şişine', 'Fellahın haline akıllar ermez Aş yererler birbirinin leşine Nil taştığı zaman gözleri görmez Biri nobut salar yetmiş beşine Babasına kıyar b...', ARRAY['Türk Edebiyatı','Şiir','Derviş Halil']::text[], 8.5, '{"poet":"Derviş Halil","poet_slug":"dervis-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/fellahin-haline-akillar-ermez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sanatım Yoktur Elümde Deyü', 'bir-sanatim-yoktur-elumde-deyu-dervis-halil-71p4g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sanatım yoktur elümde deyü

Gece gündüz kasavetten yatamam

Belki hata çıkar dilimde deyü

Tövbe edem derim bil ki tutamam

Bilmem hoca tutsam Farsi m''okusam

Yohsa kazzaz olsam kuşak dokusam

Hanend''olsam bülbül gibi şakısam

Cündi olsam doğru kurşun atamam

Kuyumc''olsam körüğü var çekmeğe

Akıl ister nazik düğme dökmeğe

Çiftçi olsam bari tohum ekmeğe

Bazarc''olsam alma armut satamam

Hallac olsam tokmağı var salmağa

Tabbağ olsam pöstekisin yolmağa

Gönül ister ummanlara dalmağa

Dalguç olsam on kulaç yer batamam

Babuçç''olsam maryol olur adımız

Muhzır olsam rüşvet ister kadımız

Reis olsam doğru esmez badımız

Furtunayla derdime derd katamam

Üstad saraç olup kalayım derim

Kın kesmenin yolunu bulayım derim

Boyum kısa şatır olayım derim

Yoldaşım çevik olursa yetemem

Derzi olsam işi çoktur bezdirir

Günde üç kez ütüsünü kızdırır

İğne ucu barmağımı azdırır

Yüsük ile bir hoşçaca itemem

Ehl-i marifetin hali bilinmez

Akar gözlerimin yaşı silinmez

Binde bir hakiki dost da bulunmuz

Halim arz eyleyüp yanup tütemem

Derviş Halil seyrangahın bağ olsun

Altı yanı mor sünbüllü dağ olsun

Gani mevlanın lütfu çoğ olsun

Arsız olup her kişiye çatamam', 'Bir sanatım yoktur elümde deyü Gece gündüz kasavetten yatamam Belki hata çıkar dilimde deyü Tövbe edem derim bil ki tutamam Bilmem hoca tuts...', ARRAY['Türk Edebiyatı','Şiir','Derviş Halil']::text[], 8.5, '{"poet":"Derviş Halil","poet_slug":"dervis-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-sanatim-yoktur-elumde-deyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Nasihatim Tutsan Yeğ İdi', 'gonul-nasihatim-tutsan-yeg-i-di-dervis-halil-truve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül nasihatim tutsan yeğ idi

Eli zemmeyleme özünden sakın

Tuz ekmek hakkını bilen yiğidi

Kadir isen iki gözünden sakın

İbadetten hali etme dizini

Tövbe edüp yerlere sür yüzünü

Kal eyle bişürüp söyle sözünü

Mat olursun kendi sözünden sakın

Gitmeğe sa''y eyle doğru yoluna

Müşkilin var ise danış uluna

Mihnet ile kondurmuşken koluna

Aldırırsın yavrı bazından sakın

Hakikat aşkını serden ayırma

Gün bu gündür yarınkini kayırma

Usul ile gezüp kendin duyurma

Arifler var sezer izinden sakın

Merd kuşağın esik etme belinden

Dürr-i meknün çıkar daim dilinden

Bülbül gibi ayırırlar gülünden

Kışa uğradırlar yazından sakın

Sitem narıyla bağrın bişürme

Kendü kendün endişeye düşürme

Erbab-ı meclisinde elin şaşırma

Perdeni hoş gözle sazından sakın

Rah-ı hakikatta kendünü eğle

Hakk''ın bin ismin vird edüp söyle

Kısmetin ne ise kanaat eyle

Çoğa heves etme azından sakın

Yoğ iken var etti ol yüce Gani

Dört terkib üzere bend etti seni

Şeytana uyup da talgetme dini

Mezarda yanmaya bezinden sakın

Derviş Halil sen de geldin asırda

Bir zaman da abdal oldun Kasır''da

Muhalif rüzigar eser Mısır''da

Gubarı çok olur tozundan sakın', 'Gönül nasihatim tutsan yeğ idi Eli zemmeyleme özünden sakın Tuz ekmek hakkını bilen yiğidi Kadir isen iki gözünden sakın İbadetten hali etme...', ARRAY['Türk Edebiyatı','Şiir','Derviş Halil']::text[], 8.5, '{"poet":"Derviş Halil","poet_slug":"dervis-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gonul-nasihatim-tutsan-yeg-idi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekliğim sökmüyor sensizliğe', 'erkekligim-sokmuyor-sensizlige-ali-osman-yilmaz-rx0lw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi gözlerini sevdiğim güzel,

Dün gece seni gördüm düşümde,

Güllü sarı yazma vardı başında,

Altın işlemeli üç etekte belinde,

Beni uykudan uyandıran sesin,

Bir güzel türkü idi dilinde.

Uyandım heyecanla,kalktım,

Bakmadayım camdan şafağa,

Tan ağarmada,ağır ağır,

Ortalık aydınlanıyor artık,

Caminin müezzini minarede,

Saba makamından muhteşem sesiyle,

Sabah sal’a sını okumakta.

Bense ne olduğunu anlamadan,

Biteviye ağlamaktayım,şimdi,

Gözlerim odayı tarıyor yavaşça,

Sen yoksun,düş görmüşüm belli,

Sensizlik canımı acıtıyor,

Erkekliğimde sökmüyor sensizliğe,

Sen yoksun,odam boş,

Aynanın önüne geçip oturmuş,

Miareden gelen sesi dinliyorum,

Müezzin sal’a yı okumakta hala,

Aynadaki bana bakıyorum öylece,

Sensizliğe ve yalnızlığıma,

Hıçkırarak ağlıyorum.', 'Mavi gözlerini sevdiğim güzel, Dün gece seni gördüm düşümde, Güllü sarı yazma vardı başında, Altın işlemeli üç etekte belinde, Beni uykudan ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/erkekligim-sokmuyor-sensizlige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küp', 'kup-ahmet-aksoy-q4s63', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılığın eleğinden geçtikten sonra,

elde kalan anlamsız acılar yalnızca,

ki döneceğim demiştin giderken,

bu yüzden kıpırdanmadığım yerimden,

kanmak gibi bir şey olmalı

içine düştüğüm keder sarmalı

ayrılığın tek kapılı  bir küp belki de

kapağı dışardan belli, çevrilmiş

keşke şöyle demiş olsaydın,

bir filmde duyduğum gibi

''beni hiç bir zaman

......unutma diye gidiyorum''

hiç değilse inanırdım

gittiğin halde beni sevdiğine,

oysa neden gülüm, neden

öyle demek yerine,

''seni seviyorum diye

..........dönerim sanma dedin''

çaresizlikten mi yoksa her 

ne kadar dilim varmasa da, bana 

sonsuz acılar vermek istediğinden mi,

ki döneceğim demiştin intihar 

eşiğindeki bir telefon konuşmasında,

bende öylece kandırmıştım kendimi,

ve içine hapis olmuştum

''cehennemden kurtuluş bileti,

.....................çıkışsız bir küpün''', 'Ayrılığın eleğinden geçtikten sonra, elde kalan anlamsız acılar yalnızca, ki döneceğim demiştin giderken, bu yüzden kıpırdanmadığım yerimden...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz-Siyah/Siyah-Beyaz', 'beyaz-siyah-siyah-beyaz-sule-aydemir-ypzog', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dağılırım

duman duman 

duman

düşünmediğim

incitmek

narince bir

siyah/beyaz 

karınca

karınca ki 

doldurmuş 

kum altı yaşamı

yarım 

karınca kararınca

yıkılırım 

yaralarsa dillerim

düşer de tutamazsam

kırılır ellerim

nehirle

ilerliyor denize

bir ceviz kabuğu

düşlerim

beyazım 

üzüyorsa siyahımı 

takarım kancamı 

ayağımın altında 

kabuğumu 

kendim ezerim 



__________________üzülürüm.......

____________________ak-kara çıkar 

__________________________sevinirim......

_____________________________kara-ak ''ı kapar...........', 'dağılırım duman duman  duman düşünmediğim incitmek narince bir siyah/beyaz  karınca karınca ki  doldurmuş  kum altı yaşamı yarım  karınca ka...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beyaz-siyah-siyah-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorulan', 'sorulan-omer-faruk-cakir-h7pxp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Gece

Kahpe gece! 

Geldim yine karanlığına

işte seninim gene

çırılçıplak

ve acıyan yanlarımla”

Sözlerim var

fikrimden sıyrılıp dudaklarımdan çıksalar

çıkamazlar

düşünceler set olur sözlerimin önüne

gözlerim donuk konuşamazlar

Sözlerim soğuk

sözlerimde serin bahar ruzgarlari da yok

bi konuşsam

konuşmasam

bildiğin sözler bunlar

Gönlümde

''sebep belirtmeyen'' huzursuzluklar

sarıyor günümü öylesi umarsız,

yüreğim avuçlarında

birleştir ellerini

can perişan, can biçare

Nefesimi salsam

ruhumda beraber çıkacak bedenimden

hep bir kaygı,

yaşanmamış ama yaşanması olası hüzünlerim var

burukluğu şimdiden hissediliyor yürekte

Oysa yürekte umutlarım vardı kaygılardan çok,

iyimserlik vardı karamsarlıktan çok

belki bu yüzden anlamlandıramıyordum huzursuzluğumu..

Bilmiyormuşum gibi davrandım hayatı,

sanki daha önce hiç karşılaşmamışçasına

bir  saflık içerisinde..

ama yutmadı işte hayat bu tavrımı! 

Ben! dedi, ben seni tanıyorum..

biliyorum! dedi sen şairsin,

şairin yüreğinden gam eksik olur mu? 

sen! dedi, sen mutluluk istiyorsun

mutlu şair olur mu? 

İçimde iyimserlik ölüyor ve hayat

cesetleri tepeleyerek ilerliyor kalbimin içlerine..

ağır kayıplarla direniş sürüyor,

galibiyet çok uzak biliyorum.

biliyorum hayat,

şairliği koyacak birkez daha yüreğime

ve soracak birkez daha aynı soruyu

mutlu şair olur mu?', '“Gece Kahpe gece!  Geldim yine karanlığına işte seninim gene çırılçıplak ve acıyan yanlarımla” Sözlerim var fikrimden sıyrılıp dudaklarımdan...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sorulan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelkit', 'kelkit-koksal-akar-m0pic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl desem bilmem şu özlemimi,

Burnumun ucunda tüter şu Kelkit.

Kapatsam da dostlar ben gözlerimi,

Ansızın karşımda biter şu Kelkit.

Soğuktur suları Çimen Dağı''nda

Bin çeşit nevale biter bağında.

Golotlar pişer de kül ocağında,

Ekmeğe başka tat katar şu Kelkit.

Yemyeşil yemişli sümbül bağların.

Şerefli tarihin,geçmiş çağların.

Yayılmış eteğine ulu dağların,

Uykuya dalmış da,yatar şu Kelkit.

Yiğidi mert olur,kızları nazlı.

Yazları serindir,kışı ayazlı.

Şenlenir yaylalar,davullu sazlı,

Bir başka havalar atar şu Kelkit.', 'Nasıl desem bilmem şu özlemimi, Burnumun ucunda tüter şu Kelkit. Kapatsam da dostlar ben gözlerimi, Ansızın karşımda biter şu Kelkit. Soğukt...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kelkit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-omer-faruk-cakir-lpk2b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biraz sonra batacak olan gün

gözlerimin gördüğü son gündür

ve sonsuz gecemdir yaklaşmakta olan,

karanlığım ebedi olacak

Onca zorlukla yeşerttiğim umutlar

yine bir sonbahara tutsak oldu,

sonbaharın rengine çaldı yüzüm,

çıplak ayaklarım kızgın toprağı özledi..

yaşama kızgınlığım çoktan aştı benliğimi,

kırgınlığımın başı dumanlı, karlı,

kırgınlığım heybetli dağlar gibi..

çok az zamanım kaldı ebede biliyorum,

biliyorum beni ateş kadar kimse sıcak sarmadı

sarmayacak!', 'Biraz sonra batacak olan gün gözlerimin gördüğü son gündür ve sonsuz gecemdir yaklaşmakta olan, karanlığım ebedi olacak Onca zorlukla yeşert...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonbahar-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-i-srafil-yildizkan-fky0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farkımız kalmamıştı

Etiler’in gençleriyle.

Sırtımızda blue jeanslar,

Saçlarımız jöleliydi.

Kıçımızda yafta gibi meşhur markalar,

Görülebilir nitelikteydi.

Bazılarımız top sakal,

Ya da dudak altında birkaç kıl

Her şey uygundu çağa.

Hâlâ anlayamamıştık,

Neden badigartlara takıldığımızı

Neden geri çevrildiğimizi! 

Neremizden anlamışlardı

Cebimizdeki paranın,

Etiler’in barlarında eğlenmeye yetmeyeceğini.

Tabi ya! 

Belki de damsız olduğumuzdandı.

Kafamıza takmıştık bir kere

Girecektik içeri.

Yürüyün dedim arkadaşlar

''Mahallemizin kızları da

entel takılıyorlar artık''

Arayın cepten gelsinler.

Damsa dam

Eğlenmekse onların da hakkı.

Çağırdık.

Kırıtık Necla, sosyete Arzu, manken Suna’yı.

Buluştuk  Köfteci Hamdi’nin orda.

Birer ekmek arası atıştırdık

Burgerlerinden, iyidir.

Hem, aç karnına da tepinilmez ki.

Ve dayandık kapısına diskobarın.

Başlarımız dik ve mağrur,

Damlarımız kolumuzda,

Onlar gibi yürüyor ve şakalaşıyoruz da; 

Ama takıldık gene badigardlara.

Bir türlü anlayamıyorduk

Eksiğimiz neydi? 

Bizlerde biliyorduk paramızın

Böyle lüks yerlere yetmeyeceğini.

Peki, badigartlar nereden anlamışlardı! 

Farkımız neydi? 

Görüntümüz dersen farksızdı.

Döndük çaresiz

Kızlara da ayıp oldu,

Heveslendirdik onları da.

Anlamış olmalı ki mahçup olduğumuzu,

Necla:

Üzülmeyin çocuklar,

Siz kendi farkınızı göremedikten sonra

Oralarda işiniz ne? 

Takmayın kafanıza, zaten yakışmaz bize.

Neymiş farkımız diye çıkıştık Necla’ya,

Ve Necla kızgın, bağırarak; 

-Ayaklarınıza bakın ulan! 

Damgalanmış varoşların çamuruyla...', 'Farkımız kalmamıştı Etiler’in gençleriyle. Sırtımızda blue jeanslar, Saçlarımız jöleliydi. Kıçımızda yafta gibi meşhur markalar, Görülebilir...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Yıldızkan']::text[], 8.5, '{"poet":"İsrafil Yıldızkan","poet_slug":"i-srafil-yildizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/fark-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de...', 'yine-de-gulay-yildiz-1is49', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizlik acı versede bana

Zamanla yarışmak zorunda olsamda,

Bir tek kelime yeter senin dudaklarından

Gülmem için, olabilmem için senin yanında

Herşeye rağmen, yine de ''Seni Seviyorum''', 'Sensizlik acı versede bana Zamanla yarışmak zorunda olsamda, Bir tek kelime yeter senin dudaklarından Gülmem için, olabilmem için senin yanı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yine-de-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-alaettin-isik-7lxth', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günü güne ekleriz,

Umud eder bekleriz

Umutlar solduğunda

Umutsuzca bekleriz.

Beklenen gün gelince

Umutlar yeşerince

Yeni umutlar kuyrukta

Demek ki hep bekleriz (!) 

22/12/2003', 'Günü güne ekleriz, Umud eder bekleriz Umutlar solduğunda Umutsuzca bekleriz. Beklenen gün gelince Umutlar yeşerince Yeni umutlar kuyrukta De...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beklemek-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy Sevgilim', 'duy-sevgilim-gulay-yildiz-9pwhk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerim denizdeyken isterim ki

Sende uzat ellerini denize

Uzat ki sıcaklığını hissedeyim

Çığlık çığlık sesini yolla dalgalarla

Bileyim yanımdasın o an

Hissedebiliyor musun sevgilim? 

Gözyaşlarımı yolluyorum sana akıntılarla

Biriktir onları ve gel artık

Karışsın mutluluk damlalarıma

Geceler boyunca ağlamak bitsin yar

Anlıyor musun beni sana ihtiyacım var.

Cerbe Denizaltısına Gönderilen Anılara...', 'Ellerim denizdeyken isterim ki Sende uzat ellerini denize Uzat ki sıcaklığını hissedeyim Çığlık çığlık sesini yolla dalgalarla Bileyim yanım...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duy-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez', 'bilinmez-gulay-yildiz-7tqtv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güvenilir ya da güvenilmez duygularım

Bir adımda biten ama asla tükenmeyen

Bir kor, bin ateş gibi devam eden

Ama asla anlam verilmeyen

Özlemse son raddede, O uzak mı uzak bana,

Doğrusuzluk deryasında boğuluyorsam bugün

Yılanları gizlediği, hançerleri sapladığı yolda

Onu ararken verilen yanlış kararlarda hata

Yaşam sıkıcı ve bitik

Bir kaç mum ışık tutan

Ve birgün o acımasız rüzgar

Bitirecek o son umudu inan...', 'Güvenilir ya da güvenilmez duygularım Bir adımda biten ama asla tükenmeyen Bir kor, bin ateş gibi devam eden Ama asla anlam verilmeyen Özlem...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilinmez-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-gulay-yildiz-mvmih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşama arzumsun sen bunu biliyorsun

Geceler boyunca gözyaşımda dolusun

Gözyaşım aktıkça kanıma işliyorsun

Sesin kulağımda fısıltı gibi şimdi

Karanlık bir ufka yolluyorsun beni

Gidiyorum sırf sen istiyorsun diye

Anla beni ''SEN'' diye haykırmak istiyorum

Duy beni, ''SENİ SEVİYORUM''

(Eylül 1996)', 'Yaşama arzumsun sen bunu biliyorsun Geceler boyunca gözyaşımda dolusun Gözyaşım aktıkça kanıma işliyorsun Sesin kulağımda fısıltı gibi şimdi...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Beni', 'affet-beni-gulay-yildiz-ypihi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlatmak günahtır, ağlatma beni

Bağışlamak erdemdir, bağışla beni

Yanına gelip birazcık özlem gidereyim

Gerisi umrumda değil, yeter ki affet beni

(Haziran, 1996)', 'Ağlatmak günahtır, ağlatma beni Bağışlamak erdemdir, bağışla beni Yanına gelip birazcık özlem gidereyim Gerisi umrumda değil, yeter ki affet...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/affet-beni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-gulay-yildiz-6gj7s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık günleri aydınlatan ışık

Mutlu anları seninle paylaştık

Ömür boyu yüzüme gülsene hadi

Nerdesin, çıksana ortaya

Parlasa ya ışıkların yüzümde

Mutluluk gözyaşım olup aksan ya

Yapamazsın...

Sen iyi gün dostu, sen insafsız

Hadi çıkda esirgeme bir kaç pırıltıyı yüzümden

Birkaç gözyaşını yüreğimden, gözümden

Gel, gel ki gülebileyim tekrar içten

(29/03/1997 Cumartesi)', 'Karanlık günleri aydınlatan ışık Mutlu anları seninle paylaştık Ömür boyu yüzüme gülsene hadi Nerdesin, çıksana ortaya Parlasa ya ışıkların ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-gulay-yildiz-jgq9x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufukta belli belirsiz  bir gemi silüeti

Sanki düşecekmiş gibi diğer yana

Uçsuz bucaksız mavi satenin öbür ucunda

Yok olup gidecek silik bir gölge sanki

Kısa yaşamımın belli belirsiz anıları gibi gözümde

Yok olmakla olmamak arasında kalmış, bitmiş bir gölge

Uzaklara gitmek ister belki kendi derinlerinde

Ama izin vermiyor göz ufkum gitmesine...', 'Ufukta belli belirsiz  bir gemi silüeti Sanki düşecekmiş gibi diğer yana Uçsuz bucaksız mavi satenin öbür ucunda Yok olup gidecek silik bir ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/golge-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Ne kadar)', 'dortlukler-ne-kadar-ahmet-aksoy-2wd5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne Kadar

Ne kadar güzeldin ne kadar çirkin oldun

Ne kadar gençtin ne kadar yaşlı oldun

Ne kadar gururluydun ne kadar gurursuz oldun

Ne kadar aptaldın ne kadar akıllı oldun.

Venüs

Denizciler bilirim nice dalgalardan kaçan

Havacılar bilirim nice rüzgarlardan kaçan

Karacılar bilirim nice topraktan korkan

Bir seni bilirim aşktan kaçan Venüs.

Doyan Var Mı? 

Aşk ile de yaşasan

Ömür az gelir aşkı yaşamaya

Ne aşk yeter yaşamaya ne de ömür

Doyar mı insan doyulmayana.

Kötü

Köpekler bile kaçar

Karanlık gecelerde ondan

O değil midir iyiliğe meydan okuyan

O değil midir içi canavar insan.

Eşitlik

Eşitlik dedigin kör bir delik

İçine giren çıkamaz bir daha

İyilikte de eşitlik, kötülükte de

İşte sana gerçek eşitlik.', 'Ne Kadar Ne kadar güzeldin ne kadar çirkin oldun Ne kadar gençtin ne kadar yaşlı oldun Ne kadar gururluydun ne kadar gurursuz oldun Ne kadar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-ne-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karalama', 'karalama-yuksel-onacan-yaye1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir inilti oldu adın dudaklarımda,

Bak, akasyalar çiçek dökmüş sokaklarında,

Hüzün dolu kırışıklık yanaklarımda,

Bir sıcak el, bir ılık nefes aramaktayım,

Bir sevda yaşamak isterim alın yazında...

Yalnızlığın sevdası yazılı, ayaklarımda,

Sevmek, hasret, tutku nedir, bazında? 

Bu yaz gecesinin anlamsız ayazında

Bir sıcak el, bir ılık nefes aramaktayım,

Teselli değil, hüzün bulmaktayım, ozanların sazında...

Zaman kısırlaştı suların akışında,

Bir anlam mı aramalıyım, anlamsız bakışında,

Kanım donar damarımda her saat takışında,

Bir sıcak el, bir ılık nefes aramaktayım,

Elele gezen sevenlerin, her adım atışında...

Bir sevda yaşamak isterim alın yazında,

Sevmek, hasret, tutku nedir, bazında? 

Bu yaz gecesinin anlamsız ayazında

Bir sıcak el, bir ılık nefes aramaktayım,

Teselli değil, hüzün bulmaktayım, ozanların sazında...

Zaman kısırlaştı suların akışında,

Bir anlam mı aramalıyım, anlamsız bakışında,

Kanım donar damarımda her saat takışında,

Bir sıcak el, bir ılık nefes aramaktayım,

Elele gezen sevenlerin, her adım atışında...', 'Bir inilti oldu adın dudaklarımda, Bak, akasyalar çiçek dökmüş sokaklarında, Hüzün dolu kırışıklık yanaklarımda, Bir sıcak el, bir ılık nefe...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Önaçan']::text[], 8.5, '{"poet":"Yüksel Önaçan","poet_slug":"yuksel-onacan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karalama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgi! Kaçmayacağım', 'ey-sevgi-kacmayacagim-gulay-yildiz-zh9fm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey Sevgi; 

Ne garip birşeysin sen! 

Her seferinde, her kapanan kapının ardından

Tekrar çıkıveriyorsun şu köşe başından

Gayriihtiyari kapılıyorum bakışlarına

Etkiliyor beni çağırışların

Katılıyorum senin eksininde dönenlere

Gün geçtikçe daha da mutlu oluyorum

Zevk duyuyorum seninle yaşamaktan

Ve sen en mutlu günümde

Fırlatıyorsun beni, uzaklaştırıyorsun kendinden

Sonra sessizce geri dönüyorsun o köşebaşından

Kayboluyorsun karanlıkta

Uzunca bir süre özlüyorum, bekliyorum seni

Ama sen direniyorsun, gelmiyorsun

Şimdi yine parıltıların gözüktü ufukta

Yakındır şu köşe başından bize bakman

Yine seçersin kurbanlarını birer birer 

Sana inat, yine olacağım onların arasında

Yine seveceğim sonuna kadar

Ve yine izin vereceğim beni üzmene, terketmene

Ey Sevgi! 

Ben seninle büyüyeceğim...', 'Ey Sevgi;  Ne garip birşeysin sen!  Her seferinde, her kapanan kapının ardından Tekrar çıkıveriyorsun şu köşe başından Gayriihtiyari kapılıy...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ey-sevgi-kacmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidipte Dönsem', 'gidipte-donsem-gulay-yildiz-ei04i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçiversem şu sınırı

Görüversem oralarıda

Gezip tanısam enginlikleri

Şu bitmek bilmeyen vadileri, hurileri

Sonra uzunca kalsam oralarda

Özlese burdakiler sonuna dek beni

O kadar çok özleseler ki; 

Hissetsem, tekrar dönüversem buralara

Ve döndüğümde bulamasam karşımda

Hüznü, kederi, gözyaşını

Tek karşılayanım mutluluk olsa

Sonsuza dek gülümsememe yetecek

Sınırsız bir haz bulsam.

Adı '' sevdam '' olsa...

Ona sarılıp uyusam geceleri

Mutlu olsam, mutlu kalsam

Çekmem işte o zaman o yangınları

Çektiremezsin tüm bu sızıları...', 'Geçiversem şu sınırı Görüversem oralarıda Gezip tanısam enginlikleri Şu bitmek bilmeyen vadileri, hurileri Sonra uzunca kalsam oralarda Özle...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidipte-donsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Seviyorum', 'sevmeyi-seviyorum-turgut-baki-vr3az', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yangınlar içinde kavruk

ben böyle sana aşk methiyeleri dizip

çıkardıkça seni göklere

alemi ben yarattım diyen

kibirli bir küstahlıkla

''aşk anlamı değildir yaşamın'' demişsin

aslında anlamsız yaşama 

anlam diye seni katmakla

anlamsız şeyler yapmışım

şimdi anladım

daha evvel de demiştim

şimdi de diyorum

böbürlenme güzelim

ben seni değil

sevmeyi seviyorum', 'yangınlar içinde kavruk ben böyle sana aşk methiyeleri dizip çıkardıkça seni göklere alemi ben yarattım diyen kibirli bir küstahlıkla ''aşk a...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevmeyi-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kütükten Bozma Adam', 'kutukten-bozma-adam-ali-osman-yilmaz-zkdj2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendimi kusurlarımla,hatalarımla,

Sevmeyi öğrendim amma,

Yinede kütükten bozma,

Bir koca adamım işte.

Usulü erkanınca ele alınmazsam eğer,

Uygun kerestede çıkmaz benden,

Beni tanımalı,anlamalısınız önce,

Sonra ne yapmak istiyorsanız,

O şekilde doğramalısınız beni,

Aynı heykel çamurundan,

Yapacağınız heykel gibi,

Sabırla işlemelisiniz bu kütüğü,

Belki bir fırına atmalısınız önce,

Aşk ateşinde iyice bir yakıp,

Özlerimi,budaklarımı dağlamalısınız,

Sonrası kolay gelecektir size,

İstediğiniz gibi şekil verecek,

Gönlünüze göre kullanacaksınız.

Aslında bundan sonra,

Benden Pinokyolarda yapabilirsiniz,

Beni yontarken eğer,

Tutkalıma yalan suyu kattıysanız,

En iyi yalanları söyleyebilirim,size

Ama yinede kusurum olacak benim,

Pinokyo olarak yalan söylerken,

Burnum uzayı verecek,göreceksiniz.', 'Kendimi kusurlarımla,hatalarımla, Sevmeyi öğrendim amma, Yinede kütükten bozma, Bir koca adamım işte. Usulü erkanınca ele alınmazsam eğer, U...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kutukten-bozma-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Sen Değildin....', 'o-sen-degildin-adem-tetik-3lq2f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Telefonda sesini duyunca senin

Gözlerim doldu ağladım sevgilim

İnanmadım senin son sözlerine

Bir zamanlar sevdiğim o sen değildin

Hayır doğru değildi bu sen değildin

Ağladı gözlerim titrerken bedenim

Düşündümde inan sanki delirdim

Bir zamanlar sevdiğim o sen değildin

Çıktım yollara koşarcasına

Aklım karıştı ne oldu sana

Düşündüm biraz yalnızlığımda

Bir zamanlar sevdiğim o sen değildin

Düşerken ahize öyle elimden

Güzel gözlerin geçti birden önümden

Düşündüm şimdi yeniden

Bir zamanlar sevdiğim o sen değildin', 'Telefonda sesini duyunca senin Gözlerim doldu ağladım sevgilim İnanmadım senin son sözlerine Bir zamanlar sevdiğim o sen değildin Hayır doğr...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-sen-degildin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Şairin Kadını)', 'dortlukler-sairin-kadini-ahmet-aksoy-d0kqh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şairin Kadını

İlhami erkekse

İlham kadındır

Şiirlerin annesi

Şairin kadınıdır.

Çiftçi

Hep bir çiftçi olmak isterdin

Sonunda oldun da

Ama tek bir farkla

Sözcükler toprağın.

Hırs

Olduğundan çok

Olmadığın olmak isterdin

Sonunda oldun da

Vardın yok oldun.

Kuzu

Bir kuzuydun sen

Etli butlu

Her gelenin bir diş attigi

Bir kuzu.

Sancak Sancak

Sancak sancak

Tuttun yüreğini

Rüzgarlara dost

Durgunluğa düşman.

Not:Şairin kadını özellikle öznel bir esin sonucu yazılmıştır bayan şairler sonucundan ayrı tutulmalıdır.', 'Şairin Kadını İlhami erkekse İlham kadındır Şiirlerin annesi Şairin kadınıdır. Çiftçi Hep bir çiftçi olmak isterdin Sonunda oldun da Ama tek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dortlukler-sairin-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Son Kumarbaz)', 'dortlukler-son-kumarbaz-ahmet-aksoy-oc960', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son Kumarbaz

Ölülerle kağıt oynardın da

Yine ben kazandım derdin

Ve sonunda, ölülere inat

Katıla katıla gülerdin.

Bir Sözcüktün

Harfleri heceleri,

Kökü ve ekleri,

Belli bir sözcüktün, fakat 

Zamanla anlamın değişti.

Yine de

Yine de, batan bir güneşin 

Güzelliği vardı gidişinde,

İnsan hayran hayran bakmaktan 

Alamıyordu kendini, giderken ardından.

Kalan

Gitmez dediklerin gitti

Geçer dediklerin kaldı

Bir sen varsın artık

Geçer dediklerinle.

Ölüm Yazıyor

Bu kalem kırmızı yazıyor

Kandan mürekkebi

Ölüm yazıyor

Ayrılığımızı yazıyor.', 'Son Kumarbaz Ölülerle kağıt oynardın da Yine ben kazandım derdin Ve sonunda, ölülere inat Katıla katıla gülerdin. Bir Sözcüktün Harfleri hec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-son-kumarbaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
