INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakındır sevdıgim', 'yakindir-sevdigim-servet-koroglu-ykgoe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duydum kusermissin gelmedi diye

Selami sabahi kesmistir diye

Nerede, arayip sormuyor diye

Yakindır gelirim kusme sevdigim

Bir gun gelirsem dertlesiriz yine

Bilmem kac gun oldu, belki kac sene

Yalniz kalmissin uzgunsun sen yine

Yakindir gelirim kusme sevdigim

Bende bu dunyayay geldim geleli

Seni ilk goruste sevdim seveli

Cilveni nazini bildim bileli

Yakindir gelirim kusme sevdigim

Bir gun olur cayir cimen yeserir

Keklik tavsan bayirlarda gezisir

Guzeller goc eyler yollar tozusur

Yakindir gelirim kusme sevdigim

Sanmayasin Servet unuttu bizi

Koyma sakın yuregine bir sızı

Benzemezki sana gavurun kızı

Yakındır gelirim kusme sevdigim

  Servet Koroglu/25.12.2003/London', 'Duydum kusermissin gelmedi diye Selami sabahi kesmistir diye Nerede, arayip sormuyor diye Yakindır gelirim kusme sevdigim Bir gun gelirsem d...', ARRAY['Türk Edebiyatı','Şiir','Servet Koroglu']::text[], 8.5, '{"poet":"Servet Koroglu","poet_slug":"servet-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yakindir-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği Hiç Sevmedim', 'sensizligi-hic-sevmedim-bekir-mutlu-gokcesu-jxgdx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykusuz geceler boyunca

Denedim sensizliği

Saklandığım yalnızlığımda 

Uyutacaktım, kaybedecektim

Kendimi ve seni

Hatta soğutacaktım dizeleri

Boşluğumda aklım sıra

Çabaladım kendim girdim ama

Sevincim, şiirimdin vazgeçemediğim

Sığdıramadım seni kabuğuma

Denedim sensizliği, beceremedim

Üstelik sensizliği ben hiç sevmedim', 'Uykusuz geceler boyunca Denedim sensizliği Saklandığım yalnızlığımda  Uyutacaktım, kaybedecektim Kendimi ve seni Hatta soğutacaktım dizeleri...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizligi-hic-sevmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilimsin', 'sevgilimsin-i-smail-ozabaci-htrta', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevgilimsin,

bir günün yorgun akşamında,

uzaklarda sevgilimsin,

bir anda aklıma gelen bir şiirin dizesinde sevgilimsin,

sesimde ve kalp atışımda,

sevgilimsin konuşmadan beni duyduğunda,

sevgilimsin bir çiçeğin ilk tomurcuğunda,

sevgilimsin her yolda,

her yolculuğumda,

sevgilimsin bir otobüs koltuğunda,

acılarımda ve sevinçlerimde

gülümsememde ve gözyaşımda sevgilimsin,

sevgilimsin,

hadi anımsa,

ama unutma her acıya bir sevinç filizlenir,

her özlem bir kavuşma anına bilenir,

sevgilimsin,

güzel yüzüne yakışmıyor hüzün,

sevgilimsin,

ben ölsem bile,

sevgilimsin,

unutma', 'sevgilimsin, bir günün yorgun akşamında, uzaklarda sevgilimsin, bir anda aklıma gelen bir şiirin dizesinde sevgilimsin, sesimde ve kalp atış...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgilimsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanışmalar..', 'tanismalar-huseyin-umit-cetin-1la7i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tek başına nedir,neye yarar hafıza

Yüreğini katmadığın neyi tuttun ki hatırında

Ekseriyetle unutulur isimler,tutulamaz akılda

Demedikçe yüreğin; "-yaz kenara ve de sakın unutma!"', 'Tek başına nedir,neye yarar hafıza Yüreğini katmadığın neyi tuttun ki hatırında Ekseriyetle unutulur isimler,tutulamaz akılda Demedikçe yüre...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tanismalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak kuş..', 'ak-kus-huseyin-umit-cetin-iub2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey güvercin! nasıl hala bunca aksın

Nasıl siyahın zerresinden, tek kanadın dahi yoksun

Sen bize acep ders misin, yoksa nasihat mısın? 

karasından seçilmeyen, bakıp sana da utansın', 'Ey güvercin! nasıl hala bunca aksın Nasıl siyahın zerresinden, tek kanadın dahi yoksun Sen bize acep ders misin, yoksa nasihat mısın?  karas...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ak-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuluk', 'korkuluk-askin-gungor-3oixm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçlarıma yalnızlık dolanmıştır, kasım,

    hüznüyle hatırını sorarken yüzümün.

Farkında değildir mutlak

    düşen yaprakların ardından

        küçük çocuklar gibi üzüldüğümün.

Kadınların saçlarıyla ne uğraşır ki rüzgar? 

Daha önemli işlerinin olduğu

    cam arkalarından bile anlaşılıyor.

Ağaçların saçları yaprak mesela; 

    rüzgar onlara daha çok yakışıyor.

Herkesin varlığını tanımladığı özgürlük

    dudaklarda tutsak kalmış olmaktan da yakınır; 

        ki zaten, var olmadığına dair bir his,

            kasımlarda özellikle,

                yapraklar kaldırım kıyılarına hapsedilince

                    benliğimde yapılanır.

Ve yalan da değildir

    her yağmur yağışında daha efkarlı olduğum.

Böyle vakitlerde sanki

    yanlış tarlaya dikilmiş bir korkuluğum.

(06.11.1993-23.12.2003)', 'Saçlarıma yalnızlık dolanmıştır, kasım,     hüznüyle hatırını sorarken yüzümün. Farkında değildir mutlak     düşen yaprakların ardından     ...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korkuluk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-askin-gungor-ayqq6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En

    kalabalık

        olduğunda

            bu

                şehir,

                    ben

                        en

                            yalnız

                                kişiyim.

(31.08.1994)', 'En     kalabalık         olduğunda             bu                 şehir,                     ben                         en                 ...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalniz-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar Durağı', 'yalnizlar-duragi-askin-gungor-q76v9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlar durağında

    akşamüstü suları,

        ekim başı, eylül sonu arası,

            içine yapraklar dökülür

                yalnızlıkların.

Kolay unutulmaz

    sonbahar sevdaları.

Hayallerini bekler yolcu en önce

    geceyle kucaklaşırken

        köşe başları.

(21.05.1994)', 'Yalnızlar durağında     akşamüstü suları,         ekim başı, eylül sonu arası,             içine yapraklar dökülür                 yalnızlık...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizlar-duragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarin adı itfaiye', 'yarin-adi-itfaiye-huseyin-umit-cetin-ndssc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ateş ekti içime..

Su istemez KORÇİÇEĞİ

Suya hasret kalmıyor

Ziya''sı kendinden muhteva

Lakin büyüyor içimde,sarıyor çepeçevre

Gıdası müstesna imiş 

Ben yandıkça doyuyor

Doydukça büyüyor

Tek çare

İTFAİYE....', 'Ateş ekti içime.. Su istemez KORÇİÇEĞİ Suya hasret kalmıyor Ziya''sı kendinden muhteva Lakin büyüyor içimde,sarıyor çepeçevre Gıdası müstesna...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yar-in-adi-itfaiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakt-i veda', 'vakt-i-veda-huseyin-umit-cetin-itcf0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıkılacak bir gün o son sefere

Bir sefer ki; dönüşü yok hiçbir gidene

Sarayın tahtın nerede,düştü mü servetin peşine

Artık sahipsin nihayet 

Cürümünce malikhaneye', 'Çıkılacak bir gün o son sefere Bir sefer ki; dönüşü yok hiçbir gidene Sarayın tahtın nerede,düştü mü servetin peşine Artık sahipsin nihayet ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/vakt-i-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı', 'marti-ozkan-ozdogan-6wvzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyot sarhoşu

bir martı geldi pencereme...

Seni sordum ben de..

Ne konuşulur ki bir martıyla

şiir ve şehirden başka? 

Sen ki,

şiirisin bu şehrin...', 'İyot sarhoşu bir martı geldi pencereme... Seni sordum ben de.. Ne konuşulur ki bir martıyla şiir ve şehirden başka?  Sen ki, şiirisin bu şeh...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/marti-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berline Giderken', 'berline-giderken-agah-ozbek-6jy4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerim,düşüncelerim

Düşündükce yanlızlığımla

Akan gözyaşlarımı döktüm çiçeğime...

Haftaya yeni yıl öyle yakınki

Dicle Çepnide

Ankarada Serap o kadar uzak

Ve ben bugün Wupertal yarın Berlindeyim

Kuşmuyum,uçakmıyım yoksa araba.

Bedenimle dolaşıyorum

Beynim dağanık.İstemediğim yönlere gidiyor elimde değil

Ben düşündükce düşündüklerimi

Düşündüklerim düşünürmü beni.

Oysa kızım,karım ve ben olmalıyım.

Parçalıyorum bütün benliğimi

Yeri geliyor koparıyorum tırnaklarımı

Gömüyorum acılarımı kalbime 

Elbette bilemez  mevsimleri yaşamayan

Sonbahardan yaza atlamak kolay olur.

Ben gözyaşlarımla sulayayım çiçekleri

Sen göz yaşlarınla yıkayacaksın kirli ellerini...

25-12-2003', 'Düşlerim,düşüncelerim Düşündükce yanlızlığımla Akan gözyaşlarımı döktüm çiçeğime... Haftaya yeni yıl öyle yakınki Dicle Çepnide Ankarada Ser...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/berline-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum Üşüdün mü?', 'bilmiyorum-usudun-mu-hikmet-karakus-4vngl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şafak sökmeden,

Bir alaca karanlığa sardılar seni,

Üşüdü bütün yıldızlar

                  ölecekmiş gibi biri...

Oysa sen şafak türküsüyle

   uğurlandın baharın doğurgan kucağında

                                   bir başka zamana...

(İst.1975)', 'Şafak sökmeden, Bir alaca karanlığa sardılar seni, Üşüdü bütün yıldızlar                   ölecekmiş gibi biri... Oysa sen şafak türküsüyle ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmiyorum-usudun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Dünya', 'eksik-dunya-oguzkan-bolukbasi-wsq3h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen olmasaydın

sana rastlamasaydım ya da

bir şeyler eksik yaşanacaktı dünyada', 'sen olmasaydın sana rastlamasaydım ya da bir şeyler eksik yaşanacaktı dünyada...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/eksik-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1.1.9.Uzaklarda Sen', '1-1-9-uzaklarda-sen-his-kaybi-mk-9dhbe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzeldin evet, evet oldukça güzel

Çılgındın güzelliğin kadar 

Layık görmemişlerdi seni bana belkide kıskanmışlardı

Gözlerinde bir umut benden, birde hüzün saklı 

Ne zaman sarılsam Duygularını anlamaya çalışsam

Keskinleşirdi gözlerin, burnunu kaşırdın 

Karşında duran Beni ilk kez gördüğün bir sima sanırdın 

Susardın, sustukça kendine küserdin

Susardın bendeki tüm umudu yok ederdin 

Güzeldin evet, evet güzeldin, oldukça da haylaz

Ne zaman elini tutsam dalardın uzaklara 

Çok yabancı, el olurdun bana

Bu duyguyu, yabancılığı, sevmeyen birini sevmeyide; 

Sadece sen yaşattın aslında ruhuma

DALARDIN; 

Benden uzaklara! 

Benim asla sahip olmadığım ufuklara, sen dalardın,

Bense farkında değildin,

Ağlardım çaresizliğe! 

Güzeldin evet SEN ÖZELDİN, uzaklarda  (12/08/2002 saat: 24.00)', 'Güzeldin evet, evet oldukça güzel Çılgındın güzelliğin kadar  Layık görmemişlerdi seni bana belkide kıskanmışlardı Gözlerinde bir umut bende...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/1-1-9-uzaklarda-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Artık Yürekli Olmalı', 'ask-artik-yurekli-olmali-his-kaybi-mk-pabn2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vaktinde sevmeli insan 

Ne geç kalmali ne de erken davranmali 

Hiçbir mutluluk sebepsiz olmamali 

Yasanan her ani hatirlandiginda ayri bir anlam tasimali 

Eller ürkek olmamali, duygular utanmamali 

Düsünmeli ve insan o ani yasamali, yasatmali 

Ask dedigin vakitlice olmali sevgili anlamali 

Ne geç kalmali ne de erken davranmali 

Çilginca yasanmali asklar, hatta hesapsiz sevmeli insan 

Sevgi o kadar degerli olmali ki, Seni bedeninden çalip; 

Ruhunu insafsizca soguk bir kis sabahi bir kadina satmali, kadin onu haketmeli 

Ask pervasiz yasanmali Ask çilgin ve tutarsiz olmali 

Bir kadinin yaninda için kipir kipirken dilin susmamali 

Onu çok seviyorsan bu kelimelerle dile gelmeli, dudaklarla anlatilmali 

Askta insan utanmamali, en gizli duygular anlatilabilmeli, yasanmali 

En çilgin geceler ask varsa yasanmali, ASKTA INSAN YÜREKLI OLMALI', 'Vaktinde sevmeli insan  Ne geç kalmali ne de erken davranmali  Hiçbir mutluluk sebepsiz olmamali  Yasanan her ani hatirlandiginda ayri bir a...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-artik-yurekli-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği Yaşayacağım', 'sensizligi-yasayacagim-ali-osman-yilmaz-3001g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dudaklarımı mühürledim,

Konuşmayacağım artık,

Uludağ’ın eteklerindeki,

Kestanelerin altına,

Kalbimi gömüyorum,

Kalemimin ucunu da kırıyorum,

Çamlıcadaki güzelim,

Seninle mahşerde buluşmaya,

Karar verdim haberin ola.

Sen şimdi Çamlıcadasın,

Ve benim için yoksun artık,

Oralarda öldün biliyormusun? 

Bendeki sen ise benimle,

Mahşere kadar yaşayacak.

Çamlıcanın en tepelik yerine,

Bir mezar kazılacak,

Seni koyacaklar içine,

Ben kırmızı güllerle geleceğim,

Mezarında dualar edeceğim,

Mezarını aşkımın mabedi olarak,

Taç mahal misali yeniden,

Bendeki sen için yaptıracağım.

Herkes görecek aşk mabedimi,

Seni ve sana olan aşkımı konuşacak,

Dillerde gezinirken aşkım,

Ölümü bekleyeceğim burada,

Hapsedilmiş bütün çelişkilerimle,

Çaresizliğimle bir başıma,yalnız,

Bende yaşayan sen ile,

Sensizliği yaşayacağım.', 'Dudaklarımı mühürledim, Konuşmayacağım artık, Uludağ’ın eteklerindeki, Kestanelerin altına, Kalbimi gömüyorum, Kalemimin ucunu da kırıyorum,...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sensizligi-yasayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Dolu Saatler', 'seninle-dolu-saatler-deli-hasanzan-k9o40', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENİNLE DOLU SAATLER

O kadar güzel ki,

Seninle dolu saatler...

O kadar huzurlu,

Bi o kadar da aşk dolu...

Zamanın su gibi akıp gittiğini,

Senin yanında öğrenirken; 

Tek düşündüğüm ise,

Ve arzuladığım,

Zamanı durdurabilmek.

Seninle bir dakika daha olabilmek,

Bir kaç dakika daha bakabilmek,

O ela gözlere...

Belki de hiç ayrılmamak...

Hep hissetmek için,

Ellerinin soğuk terlerini.

Sonra da düşünerek,

Ve anlayarak,

Zamanı durduramayacağımı,

Teselli buluyorum düşünerek,

İleride geçireceğimiz,

Coşkulu anları...

İkimizin,

Birlikte yaratcağımız,

O güzel anları...

Seninle geçirdiğim bir dakika,

Benim için hazineyken,

Tahmin edebilirmisin,

Saatlerce beraberliğimizin,

Bana ne ifade ettiğini? 

Cevabı bulabilirsin,

Kalp atışlarımda...

Senin yanındayken delice atan,

Yerinden çıkacakcasına çıldıran,

Kalp atışlarım...

Senin dinlemeyi çok sevdiğin.

O kadar anlam katıyorsun ki bana,

Yanındayken hepim, yoksan hiç.

Umutluyken gelecekten,

Ve ilk kez şanslı hissederken kendimi,

Gülerken,

Hayat doluyken,

Kollarımın arasında ki,

Elini tuttuğum,

O güzel insan,

Deli gibi aşık olduğum,

Sensin yavrum..

Seninle dolu saatlerde,

Büründüğüm bu farklı kişilik,

Senin güzelliğin,

Ve bana karşı hislerin sayesinde şekillenirken,

Sonra benim aşkımla birleşip,

Sana doğru akıyor.

Gözlerini içine...

Ve sen bunun farkındayken,

Utanman hoşuma gidiyor.

Seninle dolu saatler,

Sensiz olmuyor yavrum.

Ve anlamamı sağlıyor,

Yanımdayken bile,

Seni niye özlediğimi.', 'SENİNLE DOLU SAATLER O kadar güzel ki, Seninle dolu saatler... O kadar huzurlu, Bi o kadar da aşk dolu... Zamanın su gibi akıp gittiğini, Se...', ARRAY['Türk Edebiyatı','Şiir','Deli Hasanzan']::text[], 8.5, '{"poet":"Deli Hasanzan","poet_slug":"deli-hasanzan","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/seninle-dolu-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünün Yaşları Ve Yavrucak', 'gokyuzunun-yaslari-ve-yavrucak-nurullah-zafer-okur-rxc4z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Islaktı gozyaşları

Yumuşak geçişlere gebe gökyüzünün

Geceyi delen her bir damla 

Hızla ilerlerken toprağa

Kimbilir Bir çatı bulamamış 

Sığınacak bir yavrucağa

Çarpardı hızla vardığı yerde

Yumuşak geçişlerle

Gözyaşları gökyüzünün

Bazende zihinlerdeki hayallere

Yada düşlere düşerdi

Olanca ıslaklığı ile

Hani Gökyüzüne doğru uzanmış

İki minik avuca

Dedim ya o yavrucağa

Bazende ümitlere çarpardı hızla

Islak ama yumuşak geçişlerle

Düşerdi umarsızca 

Gözyaşları Gökyüzünün 

Geceleri.

Umutlara rahmet bazen

Düşlerindeki kuraklığa umut olurdu bide

kimi zaman kandırmacalarında

Minik yavrucağın oyununda

Geceyle saklambaç.

Ve ebelerdi her bi damlacık 

Islak..

Sımsıkı sardıkca göğün gözyaşları

Daha bir gülen minik yüzü

Hafiften titreyen dudağı

Sımsıkı sarardı göğün gözyaşlarını

O kooocaman yüreği ile

Belkide hepimizinkinden büyük..

Göğün Gözyaşları ile dansı

Geceye yorgun düşene kadar sürerdi 

Minik bedeni..

Ve sığınmadan umarsızca bırakırdı

Kendini Göğe gece kadar rahat

Gözyaşı kadar süzülen

Gözlerindeki damlalar kadar tuzlu

....

Minik adamın yüreği

Daha küçücük elleri

Üşümüş yavrucağın bedeni

Ve ıslaktı

Gökyüzününün gözyaşları

Hepimizin evinden sıcaktı

Miniciğin Hayalleri..! !', 'Islaktı gozyaşları Yumuşak geçişlere gebe gökyüzünün Geceyi delen her bir damla  Hızla ilerlerken toprağa Kimbilir Bir çatı bulamamış  Sığın...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Zafer Okur']::text[], 8.5, '{"poet":"Nurullah Zafer Okur","poet_slug":"nurullah-zafer-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gokyuzunun-yaslari-ve-yavrucak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha İcazet Ha Diploma', 'ha-i-cazet-ha-diploma-i-hsan-uncuoglu-om8of', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ha İcazet Ha Diploma 

Ha İcazet Ha Diploma

Bildiklerini saklama 

Faydan olsun Halkına,

Özenle giyim kuşam model dipçik gibi 

Bir resim yıldıza benzer mubarek tasdikli

Cici cici yazılar usta kalem elinden 

Çeşit çerçeveler içinde çakılı asılmış

Boş yer kalmamış duvarlarda kağıtlar 

Onca zaman uğraşla kazanılmış diplomalar

Millete fayda sağlamazsa ne işe yarar,', 'Ha İcazet Ha Diploma  Ha İcazet Ha Diploma Bildiklerini saklama  Faydan olsun Halkına, Özenle giyim kuşam model dipçik gibi  Bir resim yıldı...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ha-icazet-ha-diploma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Yalandan Sevdiysem Eger', 'ben-seni-yalandan-sevdiysem-eger-guner-kaymak-lzick', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni yalandan sevdiysem eger

Bu gencligin bir hayrini gormeyim

Sana cicegim birtanem dediysem eger

Ne olur ikimizden baska duyan olmasin

Anlamasin kimseler bilmesin sevgimizi

Duymasin yadeller gormesin halimizi

Nazar deger soldurur sarartir benzimizi

Kalbimi senden baska bilen olmasin

Ruya gormus gibi birtanem senin huyun

Hayalin benim kalbimi yaliyor inan

Bu askim bu sevginle soldugu zaman

Askimizi senden baska bilen olmasin

Amsterdam', 'Ben seni yalandan sevdiysem eger Bu gencligin bir hayrini gormeyim Sana cicegim birtanem dediysem eger Ne olur ikimizden baska duyan olmasin...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-seni-yalandan-sevdiysem-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Kavuşma Diyalogları', 'ayrilik-kavusma-diyaloglari-umut-ulbegi-rqau1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tut ellerimden bütün gece

(Ne zaman bıraktım) 

Parmaklarımızın aşkı doludizgin yaşansın

(Deli düşüşlerini bir kenara koyalım) 

Hiç böyle deli uçtuğunu gördün mü kuşların

(Her gün denizlerle sevişiyor binlercesi) 

Gördün mü hiç geçilmediğini beklenen,özlenen yokuşların.

(Geçilmiyor özlemin iki hecesi) 

Hiç beklerken büyülü sıcaklarda 

buhar olmayı seçtin mi? 

(Sıcak, ıslak gecelerin görünmez mucizesi) 

-Sessizlik-

-Bakışmalar-

Tut ellerimden bütün gece

(Dur biraz) 

Yanacaksak

(Sönmeliyiz) 

Yok olacaksak.

(Doğmalıyız) 

Dönüş yolunu unutmadan

(Dönmeden) 

Ve gün doğmadan yanalım duman duman

-Birlikte-

Yüreklerimizi yakan son (bahar)  kuşları 

gibi kanatlanmadan

(Uyuyalım) 

Uyanalım.', 'Tut ellerimden bütün gece (Ne zaman bıraktım)  Parmaklarımızın aşkı doludizgin yaşansın (Deli düşüşlerini bir kenara koyalım)  Hiç böyle del...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ayrilik-kavusma-diyaloglari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay mı Sanıyorsun?', 'kolay-mi-saniyorsun-hulya-topcuoglu-ybdrb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz bir günle yaşamaya başlamak 

Kırık bir kalbin ağırlığını taşımak 

Bin bir kere sorulmuş ve hep sorulacak, 

Senli başlayan sorulara yanıt bulamamak 

Kolay mı sanıyorsun? 

Mutsuzken gülümsemeye çalışmak

Ölümü sayıklarken yaşamaya alışmak 

Bin bir kere sorulmuş ve hep sorulacak,

Neden? diye başlayan sorulara cevapsız kalmak

Kolay mı sanıyorsun? 

                 

Kurşuni akşamlarda yalnızlığı solumak 

Mavi dileklerimizde umutsuzluğu bulmak

Bin bir  kere yaşanmış ve hep yaşanacak, 

Ayrılık  illetliyle   baş etmeye çalışmak 

Kolay mı sanıyorsun?', 'Sensiz bir günle yaşamaya başlamak  Kırık bir kalbin ağırlığını taşımak  Bin bir kere sorulmuş ve hep sorulacak,  Senli başlayan sorulara ya...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kolay-mi-saniyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-bekir-yuzer-1f3o5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaklardasınya

Sessiz hıçkırıklarım el sallamıştı sana

Hatırladınmı? 

Hani bir gün mutlaka döneceğim demiştinya

Döneceğin zaman unutma emi

Hani sana emanet etmiştimya

Sen yoksan bana lazım olmaz demiştimya hani

Ruhuma sarıp hediye paketi yapmıştımya

Hah işte o kalbimide al yanına...', 'Şimdi uzaklardasınya Sessiz hıçkırıklarım el sallamıştı sana Hatırladınmı?  Hani bir gün mutlaka döneceğim demiştinya Döneceğin zaman unutma...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/emanet-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmalık mı Diyorsun?', 'sacmalik-mi-diyorsun-hasan-esat-isik-z8fnb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç gülmeyip hep ağladığıma,

Aldığım her mendilin yaşla dolduğuna,

Beni güldürmeyen kara bahtıma,

Saçmalık mı diyorsun gerçek hayatıma? 

Ulaşamadığım için mutluluğa,

İnanmadığım için vefasız aşklara,

Sarıldığım için yalnızlığa,

Yoksa, sende mi gülüyorsun bana? 

Bize yer yokmuş fani dünyada,

Hiç ölmeyecekmiş gibi sen yaşa,

Umarım doyarsın attığın kahkahalara,

Anlamasan da, gülme feryatlarımıza.

Anlamadın! Beni dostum, anlamasanda,

Ben ne söyleyeyim, başka sana,

Mutluluk dolu güzel yaşamında,

Gülüyorsun diye bizi yadırgama.', 'Hiç gülmeyip hep ağladığıma, Aldığım her mendilin yaşla dolduğuna, Beni güldürmeyen kara bahtıma, Saçmalık mı diyorsun gerçek hayatıma?  Ula...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Işık']::text[], 8.5, '{"poet":"Hasan Esat Işık","poet_slug":"hasan-esat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sacmalik-mi-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-bekir-yuzer-t1r2g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dışarda rüzgar var bu gün

Nasılda salınıyordur şimdi

O ipeksi saçların

Dışarda yağmur var bu gün

Nasılda süzülüyordur

O pamuksu yanaklarından

Yağmurlu havalarda sen varsın hep aklımda

Öyle bir günde bulup

Yine öyle bir günde kaybetmiştim seni

Sanki her yağmur damlasında 

Tekrar bana dönecekmişsin gibi

Dışarda rüzgar var bu gün

Nasılda sarılıyordur

O incecik beline

Dışarda yağmur var bu gün

Nasılda öpüyordur

O eşsiz dudaklarından

Bilirim yağmuru seversin sen

Şemsiyeyi sevmediğin kadar

Bilmezsin ama yağmurun hüzünlü gelişini

Her seferinde beni sana getirdiğini

Sen sen rüzgarda saklı ellerimide bilmezsin

Nasıl düşünmezsin bunca yıl sensiz nasıl geçti

Bilmezsinki her karabulutta sana geldiğimi

Yağmuru,rüzgarı sevdiğini zannedersin her seferinde

Yağmurun,rüzgarın sevdasını bilemezsinki......', 'Dışarda rüzgar var bu gün Nasılda salınıyordur şimdi O ipeksi saçların Dışarda yağmur var bu gün Nasılda süzülüyordur O pamuksu yanaklarında...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilemezsin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıssadan Hisse Almayanlar', 'kissadan-hisse-almayanlar-bayram-tunca-3en07', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmişlerini miras malı gibi bitirenler

Bugününü, pişmanlıkla geçirmeyenler

Yarınlarından hiç endişe duymayanlar

Bunlar; kıssadan hiç hisse almayanlar

B. Tunca/25.12.2003-12.25', 'Geçmişlerini miras malı gibi bitirenler Bugününü, pişmanlıkla geçirmeyenler Yarınlarından hiç endişe duymayanlar Bunlar; kıssadan hiç hisse ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kissadan-hisse-almayanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Çekti Yürek', 'yar-cekti-yurek-burcu-karakaya-7ck7l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Uslanmaz'' yine, öyle bir özledim ki seni,

Hasretim bir deli uçtu,

Yeşilim geldi gözüme,

Yüreğime dolandı.

Öyle bir esti ki, ateşim oldu,

Sevdan bütün organlarımı dağladı.

Bir ucu Ege''de, bir ucu Akdeniz''de

Arada kalmış benim gibi,

En güzel aşkım, Fethiye! 

İnceden bir keman ağladı,

Duygular yakıldı sevgiliye...

Aguş''un yerinde! 

Yarim yangın oldu, beynim firarda,

Öyle bir koktu ki, burnum ayakta,

Kollarım üşüdü, gözler tabakta,

Sevgili öyle bir özledim ki seni! 

Bilirim olmaz bir sen daha artık,

İstemez ruhum canına,

Senden başka katık...

Bir duble rakıda,

Herşeyim sen oluyorsun yaşadık,

Ah! Yar öyle bir özledim ki seni.

Güzel gözlerinden sel geçmesin,

Yeşilin en güzel tonuna karanlık düşmesin,

Yumuşacık teninde ki ateş hiç sönmesin,

Yar öyle seviyorum ki seni...

16/12/2003

C.Burcu Karakaya

Fethiye', '''Uslanmaz'' yine, öyle bir özledim ki seni, Hasretim bir deli uçtu, Yeşilim geldi gözüme, Yüreğime dolandı. Öyle bir esti ki, ateşim oldu, Se...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yar-cekti-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmez Biri', 'degmez-biri-abdulkadir-karaman-5mlny', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazık…dökme gözyaşını 

Değmeyecek biri için.

Eğilme, aşka başını

Eğmeyecek biri için! 

Sevgin bayatlamış azık

Harcanma canına yazık

Kurak kaldın yorgun, ezik

Yağmayacak biri için! 

Gözyaşlarını sakladın

Canına kahrı yükledin

Hayalde düşte bekledin

Gelmeyecek biri için! 

Yaşantın acıklı öykü

Tutmadı gözlerin uyku

Bekledin ömrünce ufku 

Doğmayacak biri için! 

Canı gizli aşka yaktın

Alev oldun yangın aktın

Kalbini rehin bıraktın

Sığmayacak biri için.

24.06.03', 'Yazık…dökme gözyaşını  Değmeyecek biri için. Eğilme, aşka başını Eğmeyecek biri için!  Sevgin bayatlamış azık Harcanma canına yazık Kurak ka...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/degmez-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suikast!', 'suikast-abdulkadir-karaman-ktolc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gölge gibi yanıma girdin

Bir şey demedim..! 

Sessiz sessiz canıma girdin

Bir şey demedim…

Habersizken varlığından

her gün, her ânıma girdin…

Bir şey demedim…! 

Ne kadar engellemeye çalıştımsa olmadı…

Sensiz ve seni düşünmediğim

bir ânım kalmadı! 

Sevincime, heyecanıma girdin! 

Bir şey demedim..! 

Neyim kaldıysa serdim yollarına

vazgeçtim her şeyden ve herkesten…

Köle, esir gibi düştüm kollarına…

ibâretim bir nefesten! ..

Gasbettin hayallerimi, 

sâdece sana mekân düşlerim.

Teklifsiz, yasaklı limanıma girdin

Bir şey demedim..! 

Sözlerin iksir gibi, 

gözlerin büyü…

Sanki yeniden

yaşamaya başladım

unuttuğum bir öyküyü…

Acımadın hiç

insaf etmedin vicdansız...

kanıma girdin! ..

Gitmez oldu artık hiçbir işim rast! 

Sen…evet sen! 

Teşhis ettim, tanıdım! 

Suikastsın, suikast! ..

02 – 03 – 1997', 'Gölge gibi yanıma girdin Bir şey demedim..!  Sessiz sessiz canıma girdin Bir şey demedim… Habersizken varlığından her gün, her ânıma girdin…...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/suikast-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bundan Sonra Bu Sevda Yeter', 'bana-bundan-sonra-bu-sevda-yeter-murat-demir-uupqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyleyin güneşe,artık doğmasın

Bulutlar çarpmasın,yağmur yağmasın

İsterse dünyada,kimse kalmasın

Bana bundan sonra bu sevda yater

Goncalar açmasın,güller kokmasın

Kurusun pınarlar,sular akmasın

Farketmez,yüzüme kimse bakmasın

Bana bundan sonra bu sevda yeter

Ne şehvet isterim,nede saltanat

Ne uçmak dilerim,nede bir kanat

Damarımda kanım,içimde hayat

Bana bundan sonra bu sevda yeter

Gönlümde bir sultan,başımda tacım

Yüzümü güldüren,hayat ilacım

Gözümün bebeği,neşem inancım

Bana bundan sonra bu sevda yeter

Emsali bulunmaz,kainatta tek

Onunla yaşarım,içimde yürek

Temelimin taşı,evimde direk

Bana bundan sonra bu sevda yeter

Birtanem,her şeyim,yarının,soyum

Güneşim,yıldızım,havamla suyum

Kim ne derse desin,işte ben buyum

Bana bundan sonra bu sevda yeter', 'Söyleyin güneşe,artık doğmasın Bulutlar çarpmasın,yağmur yağmasın İsterse dünyada,kimse kalmasın Bana bundan sonra bu sevda yater Goncalar a...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bana-bundan-sonra-bu-sevda-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ankara', 'sensiz-ankara-abdulkadir-karaman-rsaen', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimde acılar

yanaklarımda gözyaşları

gözlerimde hayâlin

ilk defa sensiz dolaştım

bu akşam Ankara''yı

sanki senmişsin gibi

çekerek içime

unuttuğun pakette kalan 

son sigarayı.

Her hatırlayışımda seni

yeniden depreşiyor

vazoda solan çiçekler gibi

başlıyor canım solmaya 

niçin böyle ansızın 

ayrılmaya 

ve gitmeye karar verdin

boyayarak içimi acılara.

Biliyorum

sende iyi biliyorsun

mümkün değil

sen olmadan tedâvi etmem

ve sarabilmem

kalbimde açılan yarayı.

Anladım bundan sonra 

Hep sensiz

Ama içim hep seninle

Yaşayarak sensizliği zerrelerimde 

Dolaşacağım Ankara’ yı…

11.04.03', 'İçimde acılar yanaklarımda gözyaşları gözlerimde hayâlin ilk defa sensiz dolaştım bu akşam Ankara''yı sanki senmişsin gibi çekerek içime unut...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sensiz-ankara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelenler Delisi', 'kardelenler-delisi-abdulkadir-karaman-2g2zk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıka çıka usandım içimdeki dağlara...

Harcadım tüm gücümü, menzile eremedim! 

Kaptırdım benliğimi hülyamdaki çığlara...

Kardelenleri rüzgar derdi ben deremedim! 

Atıldım değersiz bir pul misali sığlara.

Ne sebepse, yaz günü tutuldum tipilere? 

Karıncalandı ruhum, yüreğimse paslandı...

Ne kadar çok istedim, çıkamadım göklere! 

Gökkuşağım boş yere duygulara yaslandı...

Ağladım teselliye duygusuz şimşeklere.

05-07-1999', 'Çıka çıka usandım içimdeki dağlara... Harcadım tüm gücümü, menzile eremedim!  Kaptırdım benliğimi hülyamdaki çığlara... Kardelenleri rüzgar ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kardelenler-delisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemiler', 'gemiler-muharrem-koray-kfv6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gemiler

soğuk kış günlerinde

midye ve buhar sesi

motorun üzerinde

kuytuda limanda değil

dalgada denizde

demir atmasını bilmez

yolcu seçmekten anlamaz

martılar

konsa da durmaz

pusula sabit yerinde

gemiler

ne sancak ne iskele

dökülür gibi artık

eski ama beyaz boyası

rüzgara direnen 

o yaşlı bayrağı

karinası aşık denize

gemiler

uzaktan el salla görünce

ışık diye yakamoza inanır

iskandilsiz karaya yanaşır

ardında

sessiz bir köpük bırakır

rotası falda kahvede

gemiler

yalnızlık dümende

gemiler

kıyıya küskün

okyanusa hasret

derine kayıtsız

suyun içinde

tek başına bir deli

bir de 

herkesten sakladığı

kazan dairesi

küpeşteye dayanıp da dinlediğin

yangın yeri', 'gemiler soğuk kış günlerinde midye ve buhar sesi motorun üzerinde kuytuda limanda değil dalgada denizde demir atmasını bilmez yolcu seçmekte...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Koray']::text[], 8.5, '{"poet":"Muharrem Koray","poet_slug":"muharrem-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gemiler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nede güzel olurdu', 'nede-guzel-olurdu-bekir-yuzer-7savv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hırçın dalgaların maviliğini seyretmek gözlerinde 

Bütün dertleri silmek bir nefeste

Ellerinde bulmak sonsuz huzuru

Teninde koklamak bahar çiçeklerini

Ve dudaklarında vermek son nefesi

Nede güzel olurdu be Mavilim....', 'Hırçın dalgaların maviliğini seyretmek gözlerinde  Bütün dertleri silmek bir nefeste Ellerinde bulmak sonsuz huzuru Teninde koklamak bahar ç...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nede-guzel-olurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik', 'evlilik-rahim-tas-98x88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evlilik

Evlilik fedakârlıkmış 

Anlayışmış hoşgörüymüş 

Karşılıklı sevgiymiş, saygıymış, müştereklikmiş 

Fedakârlığın ikiye bölünmesiymiş 

Feda hanım, Karlık bey

23.2.2003', 'Evlilik Evlilik fedakârlıkmış  Anlayışmış hoşgörüymüş  Karşılıklı sevgiymiş, saygıymış, müştereklikmiş  Fedakârlığın ikiye bölünmesiymiş  Fe...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/evlilik-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direniş', 'direnis-bekir-yuzer-gd5x7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Lüzumsuzca nefes almak değilmiydi

Bu dünyada yaptığım tek şey

Sana bir gitme demeyi bile beceremedim

Fütursuzca sevmek seni

Hataların belkide en büyüğü değilmiydi sencede

Kalbime bir sevme lan bile diyemedim

Halbuki başlarken ikimizde biliyorduk

Bir gün biteceğini

Sen gerçeğe biraz daha çabuk uyandın

Bense hala seni karabasanlarımda yaşıyorum

Ne yapayım uyanamıyorum

Sen kimbilir kaçıncı sefere yelken açıyorken

Umarsızca

Bense ıskartaya alınmış

Ve hergün bir bölümü daha su alan 

Takalar gibiyim

Sen yoksunya,aşk yokya ve sevilmekte yokya

Mavi okyanuslarda yelkenler fora olmasada

Güneş alnıma vurmasada

Hissetmesemde deniz kokusunu doyasıya

İnan bana

Sadece nefes alıp verişim

Bu dünyaya tek direnişim....', 'Lüzumsuzca nefes almak değilmiydi Bu dünyada yaptığım tek şey Sana bir gitme demeyi bile beceremedim Fütursuzca sevmek seni Hataların belkid...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/direnis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın', 'yarin-alptekin-biber-1kae4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutluyum doğacak güneşten

Yarından çok şeyler bekliyorum dostlar

Sabahı çekmekteyim gecenin ilk saatlerinden

Beklemekteyim doğacak güneşi

Beklemekteyim sabırla ve umutla

Dişlerimde rüzgar dolaşırken serin serin

Gözlerim şafakta

Düşüncelerim martı kanatlarında ufku taramakta

Hele bir yarın olsa dostlar

Tohum yeşerse, su yürüse fidana

Hele bir güneş doğsa dostlar

Ve vursa; 

Mavisine denizin

yeşiline bozkırın

Ve vursa; 

Çaresizliğine yüreklerin

Kokuşmuşluğuna düşüncelerin

Ve vursa; 

Karanlığına gecenin

Loşluğuna çıkmaz sokakların

Vursa da 

Çıkarsa karanlığı aydınlığa

Ve bağlayıp götürse,

Yeni umutları, yepyeni yarınlara...

13 Şubat 1991', 'Umutluyum doğacak güneşten Yarından çok şeyler bekliyorum dostlar Sabahı çekmekteyim gecenin ilk saatlerinden Beklemekteyim doğacak güneşi B...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yarin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskici', 'eskici-tevfik-mengulluoglu-3q65l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana başka birşey sorma! 

Özlemlerimin raylarını döşüyorum kaç zamandır.

her adımda bir parçasını düşürdüm hasretin.birazdan düşlerimle dolu vagonların sesleri gelmeye başlar.Bacasından tüten özlemlerimi görecek koklayacaksın,yüreğin son istasyonum olacak belkide ve ben farkında olmadığım bir hızla görmediğim güzlere gideceğim,Şu küf ve is kokulu bakışlarımı görüyor musun? yarım kalan bir ressamın resmiymiş meğer,Dona kalmış bakışları resmini çizerken,Bir karayel toplasın raylara takılan hasretimi,Ben gelirken yeni özlemler bestelerim sana yaklaştıkça çoğalır,kuş olur uçar yüreğim,sevdalarla kuşatılmış bir şehrin limanında yelkenli olurum yüreğin deniz soluğun poyrazım olur, ressam uyanır güneşi boyamaya başlar, sen baktıkça yüreğin kabarır dalgalarınla beni sonsuz mavilere taşırsın,Yüreğin okyanusa,soluğun fırtınaya dönüşür,bense alabora olup bir eskicinin rıhtımına savrulurum,benden arta kalan eski püskü anı ve hayal kırıklarıyla geçimini sağlıyan eskici,yüzüne baktığımda bana denizi gösteriyordu denize baktığımda beni bekleyen yelkenliyi! beynimin bilinmeyen coğrafyasında bilmediğim yollara çıkıyorum,çıktığım bütün yollar gök kuşağı nakşeden bir nakkaşın gözlerine gidiyordu,,Kuş olup uçuyorum yine, Özlem damlamaya başlıyor gözlerimden her damla bir kuş olup uçuyor sana; biliyorum gelen bütün kuşlar renklerini senden alacak,sonrada özlemin gölgesi düşecek göklere,sonsuz bir özlem kaplayacak içini,nehir olup akacak gözlerinden,bense sevda yüklü gemiler yapacağım hasretinden,Nice koylara gidecek sevdası olacaklar mavilerin..', 'Bana başka birşey sorma!  Özlemlerimin raylarını döşüyorum kaç zamandır. her adımda bir parçasını düşürdüm hasretin.birazdan düşlerimle dolu...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/eskici-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Şarabı', 'askin-sarabi-mehmet-kalay-2illm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağzım zehir, yüreğim gam.

Dertlerim engin deniz, umudum sensiz.

Gecelerim uzun, sabahlarım yetim.

Gönlüm mühürlü, kilidi açılmaz küflü.

Dönmeyeceksin, kilitli kalacağım biliyorum.

Büyüyecek sevgim, engin deniz misali. 

Yıllanacağım şarap gibi, gıdası sensizlik olacak.

Daha da olgunlaşacak acısıyla, berrak ve saf olacak.

Bekleyecek mahşer gününe kadar, gelip almanı.

Sen almasan da sahipsiz kalacak.

Küflü, kilitli, tozlu mahzen raflarında,

Saf, duru, berrak ve lezzetli olarak. 

26.12.2003 - İstanbul', 'Ağzım zehir, yüreğim gam. Dertlerim engin deniz, umudum sensiz. Gecelerim uzun, sabahlarım yetim. Gönlüm mühürlü, kilidi açılmaz küflü. Dönm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-sarabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şey', 'sey-alptekin-biber-zyn6l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerinde boğulurken,

Umutlarıma sarılan bir varlıktı içimdeki.

Sevgisini paylaşamadığı için; 

Daha mutsuz,

Coşkusunu yaşatamadığı için; 

Daha hüzünlü,

Kendisini anlatamadığı için; 

Daha macup.

Nesin sen? 

Söyle ne olur, anlatabil kendini.

Duymak istiyorum seni,

Yaşamak, hissetmek.

Bir hayalmisin sadece

Yoksa bir kurgu mu,

Yoksa bir isim mi,

Yoksa-yoksa bir umut mu,

Benliğimi dolduran şey,

Bilemedim, nesin

İçimi de kemiriyorsun ya

Hissediyorum,

Sen her neysen,

Güzel şeysin...

2 Şubat 1990', 'Düşlerinde boğulurken, Umutlarıma sarılan bir varlıktı içimdeki. Sevgisini paylaşamadığı için;  Daha mutsuz, Coşkusunu yaşatamadığı için;  D...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sey-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker', 'asker-alptekin-biber-1n73p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte mehmetleriz canlar,

Özgürlüğün orta yerinde mahpusuz yani.

Yani vatanı bekleriz tel örgüler içinde

Ve bir de geceyi çelik gözlerle

Gördüğüm kendimizi beklediğimizdir sadece

Peki ama

günlerce

.........aylarca

................yıllarca beklemek niye? 

Ben kendimi bekleyebilirim kendi evimde de

Beklediğimiz eğer vatan sa

Peki ya vatan nerede? 

Mehmetler vatanın içinde

Tel örgülerle çevrilmiş yerin içinde

Ve aslında kendi düşmanları kendileri içinde

Onlar bekleye dursunlar vatanı

''Kim verecek se onlara kaçan zamanı''

Dışarı da insanlar alıp götürmekte hayatı

Vatan parsellenmekte yani

Görev bittiğinde belki kaparlar artakalanı

Ve de satarlar yeni gelene...

1992', 'İşte mehmetleriz canlar, Özgürlüğün orta yerinde mahpusuz yani. Yani vatanı bekleriz tel örgüler içinde Ve bir de geceyi çelik gözlerle Görd...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/asker-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerime Gel', 'duslerime-gel-tabir-gokce-8sd70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldızlar uyusun isterdim penceremde

Ve sen ayışığını giyinmiş

Başında gökkuşağından taç

Deniz gözlerin puslu

Ellerimi unutmak isterdim avuçlarında

Ve bir sağanakta ıslanmak

Aynı rüzgarlara tutunmak isterdim seninle

Ve savrulmak bilinmeyene

Aynı gecelerde kaybolmak

Yeniden doğmak şafaklarda

Gözlerimi unutmak isterdim gözbebeklerinde

Ve martıların kanatlarında uyanmak', 'Yıldızlar uyusun isterdim penceremde Ve sen ayışığını giyinmiş Başında gökkuşağından taç Deniz gözlerin puslu Ellerimi unutmak isterdim avuç...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duslerime-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Yaşamaktır', 'umut-yasamaktir-oguzkan-bolukbasi-5z1dr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sağır bu akşamlar sağır

ağır bir sancının ızdırabını yaşıyor

sabahları bekliyorum

sabahlar umutları taşıyor

sanki 

belki

kim bilir

bitmiyor beklentiler

bitmiyor

ruhum bu dirence şaşıyor

bilmiyor

yaşamak alışmaktır

ve umut

yaşamaktır

ben yaşamaya alıştım', 'sağır bu akşamlar sağır ağır bir sancının ızdırabını yaşıyor sabahları bekliyorum sabahlar umutları taşıyor sanki  belki kim bilir bitmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-yasamaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezgim', 'ezgim-alptekin-biber-nfnqc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ezgimi düşlüyorum geceler boyu

Geceler şafak bitiriyor gündüzler kadar

Şafakla hasret katlıyor, 

Sevgi katlıyor çaresizce

Çaresizlik umutlarımı besliyor,

Umutlarım duygularımı

Duygularım duygularımı yiyor içten içe.

Duygu biterde umut sağ kalır mı? 

Umut sağ olmaz sa düşler de tad olur mu? 

E canım düşler de olmaz sa bu hayat yaşanır mı? ...

1 Ekim 1992', 'Ezgimi düşlüyorum geceler boyu Geceler şafak bitiriyor gündüzler kadar Şafakla hasret katlıyor,  Sevgi katlıyor çaresizce Çaresizlik umutlar...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ezgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Ben', 'i-ste-ben-pinar-yilmaz-ne23w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlıgın içinde,sensizligin sınırında

Sesimi duyurabilme savaşım ve yenilgim

Prangalar vurulmuş,uçmayı henüz ögrenen kanatlarıma

Sınırlar çizdirilmiş tüm dünyayı içimde bulunduran yüregime

Gecenin efsuni havasını soluyorum cigerlerime

içime verdigi kesikligi hissediyorum..yalnızlıgımla..

Ve ben kendimi yaşıyorum

Kendimsiz yaşıyanların..yalancıların arasında...', 'Yalnızlıgın içinde,sensizligin sınırında Sesimi duyurabilme savaşım ve yenilgim Prangalar vurulmuş,uçmayı henüz ögrenen kanatlarıma Sınırlar...', ARRAY['Türk Edebiyatı','Şiir','Pınar Yılmaz']::text[], 8.5, '{"poet":"Pınar Yılmaz","poet_slug":"pinar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iste-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Bir-Bir Düşünse', 'herkes-bir-bir-dusunse-alptekin-biber-clm5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herkes bir-bir düşünse

Sevgisini anlatabilse

Sevdalının yüreğinde 

Bir gün bir top gül açabilse', 'Herkes bir-bir düşünse Sevgisini anlatabilse Sevdalının yüreğinde  Bir gün bir top gül açabilse...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/herkes-bir-bir-dusunse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Hikâye...', 'hik-ye-naime-erlacin-33mhj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çok gençtiler 

ıhlamur kokusunda serpildiler aşkın 

elâ düşünüp 

elâ baktılar

iki göz bir oda hayaliyle 

sevdaya kanatlandılar 

kırk haramilerce kesildi yolları 

kinci nefretin 

hançeri düştü yüreklere 

yazgıya ayrılık 

biri bir yerde şimdi

gözyaşlarını sayıyor 

acıya müptelâ

öteki yaşamıyor! 

hoyrattır aşkın muhtevası

pişkin bir yosma umursamazlığında

yalnızca talanı resmeder 

sevdalı bedenlerde yeşerip 

ölüme kan arayan hayatta

“bir varmış

bir yokmuş…”

onlar yok''tan sayıldılar 

(26 Aralık 2003)', 'çok gençtiler  ıhlamur kokusunda serpildiler aşkın  elâ düşünüp  elâ baktılar iki göz bir oda hayaliyle  sevdaya kanatlandılar  kırk haramil...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hikaye-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-bekir-yuzer-lpecc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum

Bir nefes daha alırken hayattan

Islak dudakların geliyor aklıma

Sonra o eşsiz gözlerin

O küçücük ellerin

Vede salına salına yürüyüşün geliyor aklıma

İsyan ediyorum kendi kendime

Niye şu an yoksun diye...', 'Seni düşünüyorum Bir nefes daha alırken hayattan Islak dudakların geliyor aklıma Sonra o eşsiz gözlerin O küçücük ellerin Vede salına salına...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isyan-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Çok Yoruldum', 'ben-cok-yoruldum-alptekin-biber-1h8i4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben çok yoruldum

Hep kendimi ertelemekten

Hayat yorulmadı ama

Üstüme-üstüme gelmekten...

13 Nisan 1998', 'Ben çok yoruldum Hep kendimi ertelemekten Hayat yorulmadı ama Üstüme-üstüme gelmekten... 13 Nisan 1998...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-cok-yoruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-alptekin-biber-7on2w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkı hep kelimelerde gördüm

hayal di benim için,

ona  hayalimde büründüm

Önceleyin; 

karanlık gecelerde umudumu yüklediğim ay dı

sonrasın da seni buldum

kelimelerden çıktın; 

yüreğimi sardın,

hayalimden çıktın; 

gerçek dünya da,

gerçeklerinle benim oldun

sevdim seni aşkı buldum...

1 Nisan 1998', 'Aşkı hep kelimelerde gördüm hayal di benim için, ona  hayalimde büründüm Önceleyin;  karanlık gecelerde umudumu yüklediğim ay dı sonrasın da...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-194-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-bekir-yuzer-gklpj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk öyle olmalıdırki benim kalbimde

Doğada bir başıma kaldığımda korkmuyorsam

Başımı bir ağaca koyup huzurla yatıyorsam

Çiçeklerin kokusuda sinmişse üstüme

Birde mutluluğun resmi çizilmişse yüzüme

Ben buna aşk derim arkadaş.

Gündüzün güzelliği akşama esir düşüyorsa

Zifiri karanlıklarda uğulduyorsa baykuşlar

Herşey herkez bir deliğe kaçıp

Sessiz çığlıklara bırakıyorsa gökyüzünü

Ben buna aşkın karanlığa çöküşü derim arkadaş

Ortalık günlük güneşlikken 

Sevgi kelebeği olup

Güneş batınca bir baykuşa satılıyorsa aşk

Hele birde  o aşk çocuğundan hiçbir eser kalmıyorsa

Ben buna imkansızlıkta son bir umut arama derim

Rolünü yapma çabalarındaki

Basit bir tiyatro oyuncusuysan kalbimde

Ben sana bir hoşçakal tebessümü esirgemeden

Sadece yolun açık olsun derim 

Arkadaş....', 'Aşk öyle olmalıdırki benim kalbimde Doğada bir başıma kaldığımda korkmuyorsam Başımı bir ağaca koyup huzurla yatıyorsam Çiçeklerin kokusuda ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arkadas-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviye özlem', 'maviye-ozlem-bekir-yuzer-4rjgm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahile vuran her dalganın sessiz çığlığı

Kulaklarımda sensizlik gürültüsü

Deniz her zaman maviya

Senide özlediğimi biliyorya

Şimdi sanki daha bi mavi şerefsiz

Bilemezdimki  seni görmeden

Gözlerinde okyanuslar taşıdığını 

İçinde bin gemi batırdığını

Sanırdımki

O mavilik gökyüzü

Bilemezdimki seni görmeden

Gözlerinde semaları taşıdığını

Her gün bin güneş batırdığını

Gökyüzü inadıma hep tepemde

Denizlerse dünyayı yutacaklarmış gibi

Sürekli pürtelaşta

Bir sen yoksunya yanımda

Şimdi sanki daha bi maviler şerefsizler...', 'Sahile vuran her dalganın sessiz çığlığı Kulaklarımda sensizlik gürültüsü Deniz her zaman maviya Senide özlediğimi biliyorya Şimdi sanki dah...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/maviye-ozlem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Varsınız', 'i-yi-ki-varsiniz-mehmet-kalay-4clsr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuk zamanda, kaydırağımın üstündeyim.

Gözlerim güneşten bakıyor, uzayıp giden Kalabak ovasına.

Bekliyorum sabahtan akşama, ana mı baba mı.

Gelenler benden değil, ben onlardan değilim.

Arıyor içimdeki çocuk, anasını, babasını gözü yaşlı.

Güneşin ay la, gündüzün akşam la buluştuğu zamanda, 

Uzanıyor sevgi dolu dost eli.

Sarıyor beni, avutuyor göğsünde yetim kalbimi, çocuk sevgimi.

Ağlıyorken sessizce, koşuyorum çocukluğuma.

Koruyorlar beni, paylaşıyorlar yalnızlığımı. 

Seviyorum hepinizi, korudunuz beni tehlikelerden, koybolup gitmekten.

Tamamladınız eksiklerimi, sevginizle, sıcaklığınızla ruhumu okşadınız.

İyi ki sizler vardınız, varsınız. 

26.12.2003 - İstanbul

İzmir - Urla, Kabak''ta 1971 yazında tanıştığım, yaşamımın ayrılmaz parçası olan tüm çocuk dostlarıma.

Bizlere, ikinci ana olan, rahmetli Matmazel - Donata''ya,

İkinci babamız ve her zaman yanımızda olmaya devam eden, 

Aziz peder, Padre Julio''ya.', 'Çocuk zamanda, kaydırağımın üstündeyim. Gözlerim güneşten bakıyor, uzayıp giden Kalabak ovasına. Bekliyorum sabahtan akşama, ana mı baba mı....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/iyi-ki-varsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelgitler', 'gelgitler-bekir-yuzer-q1dp3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akdenizin ihtişamı ve kumların sessiz direnişi

Birbirlerine tutkun hırçın aşıklar gibi

Oynaşıyorlar yine birbirleriyle

Rüzgarsa şarkılarıyla eşlik ediyor bu sevdaya

Ne bilsin kumcağız denizin her gelişinin

Kendisini yavaş yavaş bitirdiğini

Sevdalıya; bedeni erimiş,küçülmüş

Yok olmuş

Sevdalıya; tek düşündüğü mavi bir buse

Ne bilsin garibim

Denizin zoraki geliş gidişlerini

Rüzgarın,ayın acımasıda değildi

Bu yalancı bu kahpe gelişler

Doğa kanunu dedikleri kalleşçe birşeydi bu

Ne bilsin saf

Sevdalıya; aşkından geldiğini zannederdi garibim....', 'Akdenizin ihtişamı ve kumların sessiz direnişi Birbirlerine tutkun hırçın aşıklar gibi Oynaşıyorlar yine birbirleriyle Rüzgarsa şarkılarıyla...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelgitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz keser zaman', 'buz-keser-zaman-murat-tali-szuga', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim acılarımla

hüzünlerim beslenir

karla karışık yağan yağmurda

kar tanelerini sayarım 

yağmuru içine çekerken saçlarım

rüzgar işler

çıplaklığıma 

tenim bir dikenli yol olur 

üşümüşlüğüyle

ha desen kopacak ya gidenler

yine ölümü solumaya başlar gün

ölümden korkmam bu kez 

ölüm ben olurum bende

rüzgara çivileri dökmüşler

batar her bir yanıma

sığındığım duvar kenarında

bacaklarımı çekerim göğsüme 

vurmasınlar bakışlarıyla beni

diye

gözlerimide kapatırım

sakallarım batar gözyaşlarıma

gözyaşlarım

buz keser sakallarımda', 'Benim acılarımla hüzünlerim beslenir karla karışık yağan yağmurda kar tanelerini sayarım  yağmuru içine çekerken saçlarım rüzgar işler çıpla...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/buz-keser-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerce', 'askerce-ahmet-aksoy-wb6pd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bedenimde eksikliklerim var

kollarımı cephede bıraktım

bir mitralyöz keskinliğinde

bedenimde eksikliklerim var

bacaklarımı çölde bıraktım

bir mayın seslenişinde

bedenimde eksikliklerim var

yüzümü sipherde düşürdüm

bir bomba dönekliğinde

lakin ruhum da artılarım var

ki söylenen artık o

..........şehitlik mertebesinde.', 'bedenimde eksikliklerim var kollarımı cephede bıraktım bir mitralyöz keskinliğinde bedenimde eksikliklerim var bacaklarımı çölde bıraktım bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askerce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyalog', 'diyalog-ahmet-aksoy-5nbgl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-ciddi olamazsın

-niye yalan söyleyeyim

-geçen hafta gördüm daha

-ne fark eder öldü işte

-öldü ha yani artık yok

-evet...', '-ciddi olamazsın -niye yalan söyleyeyim -geçen hafta gördüm daha -ne fark eder öldü işte -öldü ha yani artık yok -evet......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/diyalog-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-timur-berk-34ix1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir

Sana söylerim sandım.

Ne mümkün...

Söyledim! 

Farkına vardım

Uyandığımda.

Söyleyecektim.

Trenin arkasında

Bakakaldım.

Söyleyemdim.

Baş taşında

Ağlayıverdim

25.12.2003', 'Gün gelir Sana söylerim sandım. Ne mümkün... Söyledim!  Farkına vardım Uyandığımda. Söyleyecektim. Trenin arkasında Bakakaldım. Söyleyemdim....', ARRAY['Türk Edebiyatı','Şiir','Timur Berk']::text[], 8.5, '{"poet":"Timur Berk","poet_slug":"timur-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soz-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Düşündürdükleri', 'gecenin-dusundurdukleri-engin-ataman-2dhez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tatlı uykulardan uyanma emi

Ben seni hep böyle seyre dalayım

Yalnız gecelerin ılık meltemi,

Kimsesiz gönlüne yoldaş olayım.

Kaçamak ve gizli,tatlı bir buse

Haberin olmadan o an alayım.

Eğer dudakların beğenmez ise,

Mektupla hemence geri salayım.

                                          1985 Konya', 'Tatlı uykulardan uyanma emi Ben seni hep böyle seyre dalayım Yalnız gecelerin ılık meltemi, Kimsesiz gönlüne yoldaş olayım. Kaçamak ve gizli...', ARRAY['Türk Edebiyatı','Şiir','Engin Ataman']::text[], 8.5, '{"poet":"Engin Ataman","poet_slug":"engin-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecenin-dusundurdukleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluğa Savrulan Ses', 'bosluga-savrulan-ses-osman-velioglu-i9s87', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yılgın rüzgardı, dağıttı bizi, 

Şimdi dört bir yanda, dört bin parem oy... 

Ufuklarda kaldı mazinin izi, 

Başka bir alemde benim çarem oy... 

Yılgınım, bitkinim, gönlüm üşüyor, 

Beynimde tonlarca fikir pişiyor, 

Hayrettir; bu beden nasıl yaşıyor? 

Yoktur ab-ı hayat veren derem oy... 

Küsmüşüm sevdamın bed bahtlığına, 

Kahırlar...hayatın hoyratlığına, 

El oldum dünyanın abadlığına, 

Yüzünü çevirir gitsem yörem oy... 

Yanıktı türküler, sen tütüyordu, 

Seher bülbülleri son ötüyordu, 

Gençlik senelere can satıyordu, 

Kalmadı ki bende, sana verem oy... 

Nihayi gülüşü gömüp yıllara, 

Sensizlik yurduna büktüm yolları, 

Gider ayak kırdın bütün dalları, 

Soldurdun gülleri, nasıl derem oy... 

Kan tüten geceler çaldı sesimi, 

Karanlıkta yıldız yoldu süsümü, 

...ve yağmur yağımı, rüzgar esimi, 

Boğdu benliğimi, kime erem oy... 

Sevgili sandığım sevgisiz çıktı, 

Ben ona doymadım, o benden bıktı, 

Sevda mihrabımı dağıttı, yıktı, 

Nerelere gidip yüzüm sürem oy... 

Ağladım kadınım erkekcesine, 

Gözyaşlarım aktı gülercesine, 

Dağları dağlara örercesine, 

Kalbini kalbime nice örem oy... 

Belliki yazgıdan vuslat silinmiş, 

Hasret bıçağıyla aşkım dilinmiş, 

Sevilen bilinmiş, seven bilinmiş, 

Nasip olacak mı bir gün, görem oy...', 'Bir yılgın rüzgardı, dağıttı bizi,  Şimdi dört bir yanda, dört bin parem oy...  Ufuklarda kaldı mazinin izi,  Başka bir alemde benim çarem o...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bosluga-savrulan-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari Aşk', 'firari-ask-sadik-sahin-ba7k4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulutlar arasından sıyrıldı ellerim

Yaklaşan kıyametin

Kıyametin yaklaşan

Gözlerinde parladı çocuklar

Bir istihbarata göre açlık grevindeydi tüm sevdalara

Ve bol miktarda doküman yakalamıştı polis sevdalar üzerine

Ellerim yakalasa da saçlarımı

Gürledim

Deniz gürledi

Doğa gürledi

Gözlerin çocuk parladı

Bir faili meçhuldü sevgilim

Ellerim sevgilime değdi', 'Bulutlar arasından sıyrıldı ellerim Yaklaşan kıyametin Kıyametin yaklaşan Gözlerinde parladı çocuklar Bir istihbarata göre açlık grevindeydi...', ARRAY['Türk Edebiyatı','Şiir','Sadık Şahin']::text[], 8.5, '{"poet":"Sadık Şahin","poet_slug":"sadik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/firari-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağını Geçenlerin Dergahı', 'gokkusagini-gecenlerin-dergahi-sadik-sahin-tvt5q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elim, 

rüzgarda aşınan sevgilere gitti hep

geceyi taze sabaha gebe bırakan,

gürül gürül akan güneş,

gürül gürül akan gün,

gürledi aşka gürül gürül...

ve kangal sürüleri,

mandal gibi bir yürek

asıldım aşka... 

göz kapaklarıma inen sen,

kurşun pazarlarında sattın beni! 

Kan, 

tadı kaldı dilimde tüm aşklarımın...

açmayın gecenin ağzını

uykumu açmayın

Gece bana kalsın...', 'Elim,  rüzgarda aşınan sevgilere gitti hep geceyi taze sabaha gebe bırakan, gürül gürül akan güneş, gürül gürül akan gün, gürledi aşka gürül...', ARRAY['Türk Edebiyatı','Şiir','Sadık Şahin']::text[], 8.5, '{"poet":"Sadık Şahin","poet_slug":"sadik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gokkusagini-gecenlerin-dergahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Bende Gizli Bir Yaşam Öyküsü Anlatamadığım', 'adi-bende-gizli-bir-yasam-oykusu-anlatamadigim-serhan-ozcelik-b3tes', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gürültüler arasında kaybolan sessiz

bir çığlığım,

Sesimi duyuramayan.

Derdini anlatamayıp,

Doğru dürüst bile ağlayamayan

Bir dertli şairim.

Sevgi taşırım yüreğimde,

Sessizce

Kimse bilmez ben kimim? 

Sessizim, kimsesizim.

Bir kar tanesiyim

Kış oldu mu yağan,

Bir ateş parçasıyım

Dokundu mu yakan.

Benim sevdam öyle ki; 

Yağmurla birlikte gözyaşı olup,

Güneşle birlikte doğan

İlkbaharda açıp,

Sonbaharda solan

Ama adı olmayan bir sevda! 

Ellerim titriyor yine seni yazarken; 

Şiirlerimde hep seni anlatırken

Gerçekte olduğu gibi

Yine sana aşık oluyorum.

Şiirlerimde hep seni yazarken

Bir an olsun senden ayrılmak istemiyorum

Sessizken ve sensizken.

Dünyanın dönüşüne kızıyorum

Geceler sessiz,

Gündüzler dertli

Günler acımasız adeta.

Aydınlık olmayan bir yolda ilerliyorum

Sanki gündüz ama her yer karanlık,

Nereye gittiğimi bilmiyorum

Sessiz, ıssız ve sakin.

Yine derin bir boşluğun içinde,

Yine yapayalnızım, kimsesiz

Yine sen geliyorsun aklıma,

Yine … Bir daha …

Neden yine ağlıyorum yalnız,

Neden yine kimseler duymuyor sesimi.

Bir sevda suçlusuyum ben,

Yalnızlığa terk edilmiş,

Sevdiğini yitirmiş

ve karanlığa mahkum edilmiş.

Sanki bir kuytuda yapayalnız bırakılmış,

Sanki bir çiçek misali dalından koparılmış

Ama sevdasına hiçbir şey olmamış

Yarım bir adamım.

Korkuyorum,

Yalnız yattığım her gece

Karanlıktan değil,

Uyuyamadığımdan hiç

Sana bir şey olur diye

Korkuyorum.

Doyamadım seni sevmeye,

Kıramadım kadehleri

Yaşayamadım sensiz

Bakamadım kimsenin gözlerine.

Bir gemi kalktı gidiyor,

Gönlümün limanından

ADI BENDE SAKLI.

Nereye gittiği bilinmez,

Niye gittiği de.

Ayrılık mıdır desem

Bilmem ki nedir seni benden ayıran

Güneşin batması mı? 

Yoksa

Yıldızların kayması mı,

Bilmem ki ne? 

Ulaşamadığım bir yarim var

Kayıp kentte.

İnsanlar birbirine düşmüş

Bu şehirde.

Bir seni silemedim kalbimden,

Bir seni ezemedim içimde

Bir seni, tek seni, hep seni.

Maviyle yeşilin karıştığı yerde,

Ayaklarım yere basmıyor

Ben havadayım! 

Yapraklar sallanıyor, gece soğuk

Dalların sallanması,

Yaprakların uçuşması

Ayrılığın habercisi belki de

Başımdaki ağrılar fazlalaşıyor

Ölümüm yakın herhalde.

Zaman denilen kavram,

Ne kadar yalancı

İşte bu kavram içinde

Kendini kaybediyor insan

Ne yaptığını anlayamadan

Geçiyor yalancı zaman.

Her zaman mavi değil gökyüzü,

Her şairin aynı mı sözü

Yüreği, bileği, gözü,

Yazdığım her şiir 22 yıllık

Bir SERHAN ÖZÇELİK öyküsü! …', 'Gürültüler arasında kaybolan sessiz bir çığlığım, Sesimi duyuramayan. Derdini anlatamayıp, Doğru dürüst bile ağlayamayan Bir dertli şairim. ...', ARRAY['Türk Edebiyatı','Şiir','Serhan Özçelik']::text[], 8.5, '{"poet":"Serhan Özçelik","poet_slug":"serhan-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/adi-bende-gizli-bir-yasam-oykusu-anlatamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Başımın Belâsı', 'sen-basimin-bel-si-ahmet-turan-altunsu-iaz42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen, başımın belâsı...

 ....Sen, aklımı başımdan

    .......alan belâlı kadın! 

Duydun mu hiç ölümün

 ....kör gözlü sevdalısı; 

    .......ağu kokan soluğu,

        ..........kara sevdalı kadın? ..

Sen, her bahar mevsimi

....doyasıya kokladığım

   .......ve içlerinden bir bir 

      ..........yüreğimle seçerek

          .............içimde sakladığım

            ................onca bahar dalından

                ...................bir bahar dalı kadın! ...

O gece unutulmaz! 

Hayasız sevişmeler

 ....yaşamadık –adam gibi seviştik-...

Ay gece dolunaydı.

 ....ve gökten tek bir yıldız

    .......üzerimizden kaydı....

              22.12.2003 - Osmaniye -', 'Sen, başımın belâsı...  ....Sen, aklımı başımdan     .......alan belâlı kadın!  Duydun mu hiç ölümün  ....kör gözlü sevdalısı;      .......a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-basimin-belasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalmış Yarımlıklar', 'yarim-kalmis-yarimliklar-hakki-hakan-kaya-zusxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Salkım saçak

taşmış duygular,

alınmamış dururken

bekleyen alımlıklar

bır kalınmıs 

ama yarım,

daha ve daha eklıyelım

yarımlıklarımıza,

saklı kalınmıslıklar

suskunluklar.

suskunluğumuzda

hapsolmuş

yarımlıklar...', 'Salkım saçak taşmış duygular, alınmamış dururken bekleyen alımlıklar bır kalınmıs  ama yarım, daha ve daha eklıyelım yarımlıklarımıza, saklı...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarim-kalmis-yarimliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ali-hamdi-eray-3527j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm''ü bana,

Anlatamassın,

Anlatamassın Gönül ateşim, 

Anlatamassın.

Çünki sen,

Sensiz kalmanın acısını bilmezsinki..', 'Ölüm''ü bana, Anlatamassın, Anlatamassın Gönül ateşim,  Anlatamassın. Çünki sen, Sensiz kalmanın acısını bilmezsinki.....', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olum-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-tuncay-dudu-0f3gn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pişmanlıktan ibarettir

hayat

ne eğilen başlar

ne de yolunan saçlar

tesellidir bunlar

gelip geçen

sessiz çığlıklardır

ağlamaklı gözlerde', 'Pişmanlıktan ibarettir hayat ne eğilen başlar ne de yolunan saçlar tesellidir bunlar gelip geçen sessiz çığlıklardır ağlamaklı gözlerde...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Dudu']::text[], 8.5, '{"poet":"Tuncay Dudu","poet_slug":"tuncay-dudu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklık Geleneği (2)', 'asiklik-gelenegi-2-ahmet-kurt-kqj3x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Satrancı var hüner gizli içinde,

Deryanın içinde zerre değilim.

Hikayesi türkü, başka biçimde,

Deryanın içinde zerre değilim.

Hışımla dökülür, tınıdan sözler,

Gıptayla baktıkça meraklı gözler,

Atışmadan sonra sarılır özler,

Deryanın içinde zerre değilim.

Ustalık her demde ele veriyor,

Yanlışı olanlar dudak geriyor,

Leb değmezde usta hüner seriyor,

Deryanın içinde zerre değilim.

Sorular içinde yoğrulur beyin,

Sen de buldum diye, birazcık sevin,

Muamma gibisi, akıldan derin,

Deryanın içinde zerre değilim.

Kurdoğlu methiye gönder aşığa,

Gönüllerden bal damlasın kaşığa,

Şükür kavuşturur bizi ışığa,

Deryanın içinde zerre değilim.', 'Satrancı var hüner gizli içinde, Deryanın içinde zerre değilim. Hikayesi türkü, başka biçimde, Deryanın içinde zerre değilim. Hışımla dökülü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asiklik-gelenegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15 Yaşından Küçükler İçin', '15-yasindan-kucukler-i-cin-oguzkan-bolukbasi-wigps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.....................................................çocuğum

Sinekler

İnekler üzerinde yaşam sürer

Bit ise

İt üzerinde

Kağnı gölgesinde yürüyenlerdir onlar

Kendi gölgesi sanırlar başkasının heybetini

Ağzında geveleyerek çiğnerken çikletlerini 

Akıl

Kıl gibi durur kafalarında

Üflesen uçacak

Konuşsan 

Millet akıllı sanacak

Konuşmasan onlara kanacak

Hangi kılavuz yolu bulduracak

Kargalar gaklarken

Işığı saklarken

Bakışın

Akışında olsun hayatın

Yol içinde gizlidir

Gözler görmek

Beyin düşünmek

Kötülükler dersler içindir

Cennet sanma dünyayı

Yeter ki bil

İyiyi kötüden ayırmayı

Söylediğini yap

Yaptığını söyle

Durma öyle

Şaşkın 

Dünya böyle bir yer

Barınağıdır iyilikle kötülüğün

Nefret ile aşkın

Sen ol

Güçlü ol

İyi ol

Herkesin sevmesini bekleme

Seveni bulursan eğer

Bu sana yeter

Sevene değer ver', '.....................................................çocuğum Sinekler İnekler üzerinde yaşam sürer Bit ise İt üzerinde Kağnı gölgesinde yürü...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/15-yasindan-kucukler-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecaz', 'mecaz-ahmet-aksoy-861a2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sizler kumsal taşları, güneşlenirken

sırtımıza batan, bir zaman nefret ettiğimiz

bir zaman köpekleri kovaladığımız,nasıl

tanımlardık duygularımızı,siz olmasaydınız', 'sizler kumsal taşları, güneşlenirken sırtımıza batan, bir zaman nefret ettiğimiz bir zaman köpekleri kovaladığımız,nasıl tanımlardık duygula...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mecaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaca', 'dunyaca-ahmet-aksoy-rrswu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaman meteor hüznü

ve kitlenmiş sözcüklerde

çemkirmeye gerek yok,

ki sıkışmak sıkışmamaktır aslında,

geçmişle gelecek arasına

..................çekilen tüllerde.

bugün ve dün hatta ilalebet,

...acı tefrikaları

en çok okunanlar arasında,

zamanın usu bunu düşünmüş,

.....yani seçmiş genelini,

ki bilirnir her öznellik,

nesnelliğe ulaştıkça yoğunlaşır.

öyleyse meteor hüznünde

..........nefes almak aslında,

................yaşamak.

her tabu zamanı gelene kadar,

....................kendine tabudur.', 'zaman meteor hüznü ve kitlenmiş sözcüklerde çemkirmeye gerek yok, ki sıkışmak sıkışmamaktır aslında, geçmişle gelecek arasına .................', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunyaca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal Kız', 'bal-kiz-harun-haliboro-nw1lf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana isim koydum; Bal Kız

Baldan daha tatlı kız

İstersen bana sen çok kız

Seviyorum seni Bal Kız.

   Yüzün güzel,çiçek gibi

    Tenin sanki ipek gibi

     Dokunursam öleceğim

     Tıpkı bir kelebek gibi.

                                         Harun Haliboro     07.07.2003

                                                                         Yalova.', 'Sana isim koydum; Bal Kız Baldan daha tatlı kız İstersen bana sen çok kız Seviyorum seni Bal Kız.    Yüzün güzel,çiçek gibi     Tenin sanki ...', ARRAY['Türk Edebiyatı','Şiir','Harun Haliboro']::text[], 8.5, '{"poet":"Harun Haliboro","poet_slug":"harun-haliboro","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bal-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan', 'sen-yoksan-harun-haliboro-lsxiy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yoksan bu şehirde hem de bu yerde

  Hasret gönlüme iner hep perde perde

  Gözyaşlarım sel olur akar gider de

  Gelişin ancak çâre olur bu derde.

      Baharda güller,güllerde senin kokun

      Nur saçan gözlerinle kalbime dokun

      Günümü hem gecemi sarar yokluğun

      Gelişin ancak çâre olur bu derde.

                                        Harun Haliboro      10.07.2003

                                                                            Yalova.', 'Sen yoksan bu şehirde hem de bu yerde   Hasret gönlüme iner hep perde perde   Gözyaşlarım sel olur akar gider de   Gelişin ancak çâre olur b...', ARRAY['Türk Edebiyatı','Şiir','Harun Haliboro']::text[], 8.5, '{"poet":"Harun Haliboro","poet_slug":"harun-haliboro","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-yoksan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbiri''nin durumu', 'hicbiri-nin-durumu-elif-sebnem-akal-8jwbh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gönlüm vardı benim

Günle barışık...ayla barışık

Sen geldin tersyüz oldu...

Gün de karışık...

Ay da karışık

Seçenekler türettim

Birinci, ikinci...sen

Üçüncü kör yalnızlık

Sonraki ölümse eğer,

Hiçbiri''nin durumu karmakarışık...', 'Bir gönlüm vardı benim Günle barışık...ayla barışık Sen geldin tersyüz oldu... Gün de karışık... Ay da karışık Seçenekler türettim Birinci, ...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hicbiri-nin-durumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başıydı Gösterdiği', 'basiydi-gosterdigi-cumhur-turan-l0g9k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'samanyolunda dolaşırken 

avare

avare

rastladım ona

yorulmuş 

bağdaş kurmuş

oturmuştu

bir yıldızın üstüne

derin bir kuyu gibi bakışlarını

dikerek üzerime

parmağının ucunda

kör bir ışık gibi duran

dünya''yı göstererek

evren ne kadar küçük

dedi

gülümseyince

muzip

muzip

bu söze

bir yanardağ gibi püskürdü

her şey burada başlar ve biter

dedi

bu kez

başıydı

gösterdiği', 'samanyolunda dolaşırken  avare avare rastladım ona yorulmuş  bağdaş kurmuş oturmuştu bir yıldızın üstüne derin bir kuyu gibi bakışlarını dik...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/basiydi-gosterdigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu Yalnızlığım', 'suclu-yalnizligim-umut-ulbegi-edfca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaprak kokuyor

düş bahçelerim

gözyaşlarım

yaprak yaprak

Toprak çekiyor

neredesin? 

İlk doğum günüm

ürkek

korkak

Artık beni duyamıyor

göremiyor

sevemiyorsun.

Gülüyor musun

ilk adımıma 

yalınayak

''Solduğum yerde

yeni yürekler açacak

duyuyor musun

çıtırtılarını tomurcuğun

Hata değil

kapat kapılarımı

Yıkayıp ellerimi uyuyayım

Uyandığım yerde

kapılar kilitli

Biliyor musun

acısını bu çocuğun

yasak değil

suçlu yalnızlığım.''', 'Yaprak kokuyor düş bahçelerim gözyaşlarım yaprak yaprak Toprak çekiyor neredesin?  İlk doğum günüm ürkek korkak Artık beni duyamıyor göremiy...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/suclu-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özelsin 1', 'ozelsin-1-his-kaybi-mk-xuype', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özelsin 1

sen özelsin bende..

ayrı mutluluklar taşırsın bu gönülde

senin yerin başka güzelim taşıdığım bu kalpte

bilmesende bilmek istemesende 

Kabulenemesende bu bende böyle

tutarsız akşamlarıma emanet ettim seni 

uykusuz sabahlarımda bulayım diye 

anlamak istemesende sevmek istemesende 

maalesef tebessümlerin gönülde

bir feribot yolculuğuydu aşkımız 

bazen sallantılı bazen sarsıntılı 

dalgalara boyun eğmedik ama! 

küçük bir limana yenildik 

gözyaşlarıyla, anılarımızla....

belkide yanılmıştı kaptan

sığ bir liman ararken 

başka acılara satmıştı umutlarımızı 

ama nereden bilirdiki? 

sığ limanların azgın denizlerden daha tehlikeli olduğunu

nereden bilebilirdiki balıkların insanlardan daha vefalı olduğunu 

nereden bilebilirdi güzel kız...... NEREDEN! ! ! 

  (26/04/2000)    24.30 Üsküdar ve Hüsran M.K. Versac', 'Özelsin 1 sen özelsin bende.. ayrı mutluluklar taşırsın bu gönülde senin yerin başka güzelim taşıdığım bu kalpte bilmesende bilmek istemesen...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozelsin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İZ''in Anatomisi', 'bir-i-z-in-anatomisi-umut-ulbegi-92yzi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben

en derin

en uzak

en karanlık

en soğuk

en çirkin

izleriyim

bedeninin

Uyanışını izlerim

izlerim soyunuşunu

çıplaklığını uykuna gizlerim

Zaman izleri siler

zaman

gözlerim

şehrim

yüreğim

ellerim

bedenim.', 'Ben en derin en uzak en karanlık en soğuk en çirkin izleriyim bedeninin Uyanışını izlerim izlerim soyunuşunu çıplaklığını uykuna gizlerim Za...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-iz-in-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz gelinlik', 'beyaz-gelinlik-sefer-kurt-0h5o0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani hayalinde ki o gelinlik

Bizim aşkımızın sonu evlilik

Göz yaşlarımızı mutluluğa çevirdik

Düğünümüzde giyeceksin beyaz gelinlik

Mutluluk aşkımızın simgesi olacak

Yıldızlar bu kez bizim için parlayacak

Geceler düşman değil dostumuz olacak

Düğünümüzde giyeceksin beyaz gelinlik

Elele vereceğiz bir ömür boyu

Mutlulukla bitecek hayat yolu

Fotoğraflarımıza yansıyacak aşkın ruhu

Düğünümüzde giyeceksin beyaz gelinlik', 'Hani hayalinde ki o gelinlik Bizim aşkımızın sonu evlilik Göz yaşlarımızı mutluluğa çevirdik Düğünümüzde giyeceksin beyaz gelinlik Mutluluk ...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyaz-gelinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şafak Vakti Kapını Çalsam Ben Gelsem!', 'bir-safak-vakti-kapini-calsam-ben-gelsem-his-kaybi-mk-vbe62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüm yanlışlarına rağmen hayatın

Unutsam olanları aklımdaki ücra bir köşeye atsam 

Tüm umutsuzluklara rağmen

Elimde kalan son umutla 

Bir şafak vakti kapını çalsam ben gelsem

Gözyaşlarımı, acılarımı ve sana adadığım umutları alıp

Ansızın hiç aklından geçirmediğin bir vakit

Tüm cesaretimi toplayıp fukara umutlarım ve ben

Bir şafak vakti kapını çalsak, ben gelsem 

Ellerim titresede, gözlerim yüzüne bakmaktan utanıyor olsa bile

Senin vefasızlıklarına rağmen boyun eğmeyip  gururuma 

Alıp üç beş köhne umudu yanıma

Bir şafak vakti kapını çalsam ben gelsem 

Acaba! 

Titrer mi yüreğin 

Sefil, hüsran dolu yüreğimle

Titreyen ellerimle dokunmak istesem güzel kız sana

Bir şafak vakti ansızın kapını çalsam ben gelsem 

Nedersin Bir şafak vakti ansızın hiç beklemediğin, düşlemediğin bir anda 

Kapını çalsam ben gelsem 

O kahrolası gururumu ayaklar altına alıp

Sana ben geldim desem açarmıydın gönül kapını buyur edermiydin ki

Yine o umudunu yıktığın yüreğime umut verir içeri gel dermiydin ki? Sevgili 

Şimdi pervasızlığını yaşarken sensizliğin bedenim 

Gözlerine dalıp kaybolmak bedeninle bütünleşip seni yeniden yeniden yaşamak istiyor gözlerim 

Bedenim çaresizlikler içinde kıvranırken 

Ansızın kapını çalıp ben geldim işte karşındayım ne olur anla beni demek istiyor 

Tüm çaresizliğiyle yüreğimi bir şafak vakti hiç gocunmadan elleriyle sana sunuyor 

Kapını aç ben geldim diye sana haykırıyor 

Hayatın kararsızlıklarıyla savaşırken benliğim

Sana yenilmenin ezikliğini yaşıyor yüreğim

Korkularımdan ve tüm düşüncelerimden sıyrılıp

Bir şafak vakti ansızın kapını çalsam ben gelsem 

Sana umutlarımı hayatta en çok değer verdiğim benliğimi versem

Ayaklarına kapansam yalvarsam

Hiç olmadığım kadar senin için yaşamdan fedakarlık yapsam

Ellerimle güzelim sana ruhumu sunsam 

Bir şafak vakti ansızın kapını çalsam ben gelsem 

Sevinirmiydin yine gözlerinde o gülümsemeyi tebessümü gösterirmiydin 

Bana sarılıp canım bitanem dermiydin 

Ellerimle sunduğum yüreğime her zamanki gibi yaşama sevinci verirmiydin 

Kapını çaldıgım o sabah beni görebilirmiydin...

Ben her şafak vakti inan kapını çalıyorum 

İnan ki her şafak vakti ben tüm tutarsızlıklara rağmen sana koşuyorum 

Boşa kürek çektiğimi bile bile dönmeyecegini gelmeyecegini eskisi gibi sevmeyeceğini

Bile bile Bıkmadan usanmadan ben her sabah o kapıyı çalıyorum sen FARKINDA OLMASANDA 

Farkında olmak istemesende ben her şafak o acıyı tadıyorum 

Benim için şafaklar senin için kapını çalanlar bitmeyecek

Sen her sabah yeni sevgileri koklayacaksın 

Ben aynı kapıya gidip seni dileneceğim

Üstelik, ne garip üstelik, sen hiç farkında olmayacaksın hiç bilmeyecek anlamayacaksın ne garip 

30/09/2000 saat: 23.00 Üsküdar.... Kayıp M.K. Versac', 'Tüm yanlışlarına rağmen hayatın Unutsam olanları aklımdaki ücra bir köşeye atsam  Tüm umutsuzluklara rağmen Elimde kalan son umutla  Bir şaf...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bir-safak-vakti-kapini-calsam-ben-gelsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ışıkları', 'umut-isiklari-sefer-kurt-h0lrs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine gece yarısı

Yine sessiz bir gece

Ama bu sessizlik farklı

Fırtına öncesi sessizlik

Bu gece ki karanlık farklı

O karanlığı yırtan ışıklar var

Umut ışıkları

Bu kez bizim için parlıyor

Umut ışıkları bize doğru geliyor

İçinde mutluluk saklı

Gerçek aşklar saklı

Sevmeyi gerçekten bilenler

Evet umut ışıkları bizim için parlıyor

Sabahın ilk saatlerimde bir güneş

Bu güneş bizim için doğuyor

Yep yeni bir gün

Yep yeni bir hayat

Umut dolu

Sevgi dolu bir gün

Ağlamak yok

Gözyaşı yok

Gözlerimiz sevgi ile parlayacak

Bu kez bizim için doğdu umut ışıkları

Kollarımı açtım bekliyorum

Mutluluk gelecek biliyorum

Bak bizim için doğdu umut ışıkları

Bak bize doğru geliyor umut ışıkları', 'Yine gece yarısı Yine sessiz bir gece Ama bu sessizlik farklı Fırtına öncesi sessizlik Bu gece ki karanlık farklı O karanlığı yırtan ışıklar...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/umut-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Küçük Adam', 'giden-kucuk-adam-umut-ulbegi-8m4i1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimi hazırladım

Gözlerimi de

Sözlerimi sakladım tek

Artık yazamıyorum

yalınayak yürüyerek

Bildiklerimi hazırladım

yanıma aldım

bilmediklerimi de

dünü unutmadım tek

Big Bang

Bak

Dünya bile soğudu

Artık gidiyorum

o resimde küçülerek.', 'Ellerimi hazırladım Gözlerimi de Sözlerimi sakladım tek Artık yazamıyorum yalınayak yürüyerek Bildiklerimi hazırladım yanıma aldım bilmedikl...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/giden-kucuk-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönecek misin', 'donecek-misin-sefer-kurt-cze30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sıkıcı yine sessiz bir gece

Geceler aydınlandığında dönecek misin 

Dertler yine bağrıma yazılmış

Dertler bittiğinde dönecek misin

	

Biliyorum sende çok özlüyorsun

Seviyorsun beni çok seviyorsun

Yoksa sen yazın gelmesini mi bekliyorsun 

Çiçekler açtığında dönecek misin

Bak sensiz yine gözlerim yaşlı

Uzaktan sevmek çok ama çok acı

Dön bana dön ne olur başımın tacı 

Göz yaşlarım dindiğinde dönecek misin

Bülbüller sustu kuşlar uçmaz oldu

Günler bitmez saatler durdu

Yıldızlar parlamaz geceler karanlıklara boğuldu

Güzel günler için benim için dönecek misin

	

Sen dönmezsen hayatımın hiç anlamı kalmaz

Benim için kırmızı güllerin anlamı olmaz

Sana bu son çağrım gönlüm sensiz duramaz

Kırmızı güller açınca dönecek misin

Her şeyden vazgeçerim senden asla

Döneceksin bekliyorum seni bu yazda

Gelmezsen hayatıma koyarım son nokta

Benim için aşkımız için dönecek misin', 'Yine sıkıcı yine sessiz bir gece Geceler aydınlandığında dönecek misin  Dertler yine bağrıma yazılmış Dertler bittiğinde dönecek misin 	 Bil...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donecek-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan''ı yazacağım', 'hazan-i-yazacagim-nazife-abayli-fcl1j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şiir okuyuşumda,

Ya da yazışımda,

Alfabeyi öğrendiğim,

Gün gelir aklıma.

İlk şiirimi anımsarım.

Çocuksu şiirimi.

Öğretmenime yazmıştım,

Sevgimi anlatmıştım.

Ardından,

Anneme,babama,kardeşlerime.

İlk sevgilime yazdım sonra.

Ve dağlara,denizlere,kuşlara,böceklere.

Lise sıralarında,

Heyecanla beklerdi arkadaşlarım.

Onlar gibi düşünüp,

Onlar gibi hissedip,

Onların adına yazardım.

Sevgililerine verirlerdi.

Her yeni günde,

Yeni şiirler beklerlerdi.

Biriyle karşılaştım geçenlerde.

Saklamış,çocuklarına okutuyormuş şimdi.

Annem,hafta sonu temizliğinde,

Bıkardı,

Evin her köşesinden,

Şiirlerimi toplardı.

Kilim altından,yatak aralarından.

''Şair mi olacaksın başımıza? '' derdi.

Çoğunu alamazdım elinden,

Ağlardım...

Ara verdim sonra,

Yıllarca yazamadım.

Her kalemi elime alışımda,

Hafızamda biriktirdiğim sözcükleri,

Toparlayamadım.

Ya da başlayıp başlayıp,

Yarıda bıraktım.

Şimdi,

Yolun yarısını çoktan geçmişken,

Yüreğim HAZAN''ı yaşarken,

Nedendir bilmem,

Sözcükler dökülüyor kalemimden.

Anladım ki artık,

HAZAN''ı yazacağım.

             25.12.2003', 'Her şiir okuyuşumda, Ya da yazışımda, Alfabeyi öğrendiğim, Gün gelir aklıma. İlk şiirimi anımsarım. Çocuksu şiirimi. Öğretmenime yazmıştım, ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hazan-i-yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana beni anlattın', 'bana-beni-anlattin-nazife-abayli-3ox6q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öylesine mutlu,

Öylesine huzurluyum ki bugün.

Yıllardır ilk defa,

Evimin boş duvarları,

Sıkmadı beni.

Kör karanlığa yenilip,

Boğulmadım ağlamaktan.

İlk defa,bir sağa,bir sola,

Dönüp durmadım yatağımda.

İlk defa,

Kalkıp uyku aralarında,

Kana kana su içmedim.

Öylesine dingin uyudum ki...

İlk defa kabus görmedim.

Kapkara yaratıklardan kaçmaktan,

Koşmaktan yorulmadım.

Hatta,düşümde seni gördüm.

Bana SEN''i anlattın.

Hiç görmediğim,

Gözlerinin rengini bilmediğim SEN''i.

Bana BEN''i anlattın,

Hiç görmediğin,

Gözlerimin rengini bilmediğin BEN''i.....

                           25.12.2003', 'Öylesine mutlu, Öylesine huzurluyum ki bugün. Yıllardır ilk defa, Evimin boş duvarları, Sıkmadı beni. Kör karanlığa yenilip, Boğulmadım ağla...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bana-beni-anlattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Artık', 'sen-yoksun-artik-sefer-kurt-3nke7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliği yine

Odama gidip yatağıma uzanıyorum

Ve birden engin boşluklara dalıyorum

Sen geliyorsun aklıma

Bekliyorum seni belki gelirsin diye

Ama sen gelmiyorsun

Sabah oluyor yatağımdan kalkıyorum

Kahvaltı için hazırlanmış çayımı yudumlarken

Gözlerini hatırlıyorum

Gülüşün yanağındaki gamzelerin geliyor aklıma

Dışarıya çıkıyorum belki dışarıdasın diye

Ve yine bekliyorum seni

Ama sen yine gelmiyorsun

Bak yine yaz geldi 

Kuşlar ötüyor çiçekler açmış

Ağaçlar yemyeşil

Sahiller cıvıl cıvıl rengarenk olmuş

Sevgilileri görüyorum kol kola

Yine seni ve aşkımızı hatırlıyorum

Onlara bakıp bekliyorum seni

Belki gelirsin diye ama gelmiyorsun

Kırmızı gül görüyorum bir bahçede

Anlamlı anlamlı bakıyorum ona

Ama bir anlam veremiyorum

Dalından kopartıyorum gülü

Dikenlidir biliyorsun

Avucum da sımsıkı sıkıyorum

Dikenleri batıyor canım yanıyor

Öylece avuçlarımda soluyor

Tıpkı senin solduğun gibi

Kanlı avuçlarıma bakıyorum

Seni hatırlıyorum

Ve bekliyorum seni belki gelirsin diye

Ama sen yine gelmiyorsun

Sanki yokluğunu kabullenmeye başladım

Hayır hayır sensiz bir hayat olamaz

Çok acı bu göz yaşlarım durdurulamaz

Bu aşk bahçem sensiz olamaz

Bekliyorum seni belki gelirsin diye

Sen gelmiyorsun sen gelemiyorsun

Çünkü sen yosun artık

Sen yoksun artık...', 'Gecenin sessizliği yine Odama gidip yatağıma uzanıyorum Ve birden engin boşluklara dalıyorum Sen geliyorsun aklıma Bekliyorum seni belki gel...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-yoksun-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bay M...''e', 'bay-m-e-nazife-abayli-l61yf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğinden sök,

Sök artık beni,

Denizlere,çöllere,

Nereye istersen at beni,

İstersen ateşler içinde yak beni,

Ağlama vefasız,

Çoktan sildim ben seni.

Dönmem artık,

Yalvarma boşuna.

Son şansım,

Son aşkımsın demiştin.

Geceleri inen sessizliğim,

Yüreğime can katan,

Tek sevdiğimdin,

Baharı yaşatmadan 

Yüreğimi tükettin,

Dönmem artık,

Yalvarma boşuna.

Hazanı yaşattın,

Bana dört mevsim,

Her gece ağlardı,

Ağlardı bu yüreğim,

Yollarını bekledi,

Saatlerce gözlerim.

Beni bugün değil,

Çoktan kaybettin,

Dönmem artık,

Yalvarma boşuna.

           02.03.2003', 'Yüreğinden sök, Sök artık beni, Denizlere,çöllere, Nereye istersen at beni, İstersen ateşler içinde yak beni, Ağlama vefasız, Çoktan sildim ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bay-m-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedendir bilmem..', 'nedendir-bilmem-nazife-abayli-8al1e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedendir bilmem, 

çocuk olmak, 

çocukluğumu anımsamak, 

geldi içimden bugün. 

çocuksu duyguları, 

saflığı,samimiyeti,sevecenliğimi özledim belki. 

babamı çok severdim, 

ilk çocuğu olduğum içindi galiba, 

onun da beni kardeşlerimden, 

fazla sevdiğini hissederdim. 

kızımı okutacağım derdi, 

evimize gelen her misafire. 

sınavlardan pekiyi aldığımda, 

iki buçuk lira verirdi, 

işçi maaşından bölüpte. 

neler alırdım iki buçuk liraya neler... 

sakız alırdım örneğin, 

simit alırdım. 

simiti çok severdim,halen severim. 

ama sakızı bir türlü sevemedim, 

arkadaşlarıma verirdim. 

iki buçuk lirayı her elime alışımda, 

parayı değil, 

biraz daha fazla sevgi vermesini isterdim. 

türkü dinlemek çok hoşuma giderdi. 

Şakir Öner Gülhan, 

Bedia Akartürk, 

daha nicelerini. 

Hiç kaçırmazdım radyoda seslerini duyduğumda. 

HEKİMOĞLU nu ezberlemiştim daha 9 yaşımda. 

müzik derslerinde söylerdim, 

sınıftaki arkadaşlarıma. 

hala çok severim türkü söylemeyi. 

annemi,kardeşlerimi de çok severdim, 

hele o sabahları okula giderken, 

annemin hazırladığı kahvaltının tadını, 

halen bulamıyorum,kendi hazırladığım kahvaltılarda. 

Asi bir çocukmuşum, 

annem halen söyler. 

Bu yüzden çatışırdık çoğu kez. 

Yapmak istediklerim engelenirdi nedense. 

Yine yapardım,yine yapardım. 

onlara göre isyankardım. 

roman okumayı severdim, 

izin vermezlerdi. 

açık hava sinemasında film seyretmek isterdim mesela, 

göndermezlerdi. 

plaja gitmek,denize girmek isterdim, 

yine göndermezlerdi. 

Ben de kaçar giderdim. 

İki günde yüzmeyi öğrendim. 

Açıldımı denize,kulaç attıkça kendimi özgür hissederdim. 

Hala çok severim yüzmeyi. 

ilk kez aşık oldum, 

14 yaşımda. 

adı Tamer di. 

aynı sınıftaydık. 

bisikletiyle gezdirirdi beni, 

okul dışında. 

öyle çok severdimki onu. 

bir gün sınıfa geldiğimde,tamer i göremedim. 

babası tayin olmuş uzaklara, 

gitmişler. 

bir hafta ağlamıştım, 

mektubunu aldığımda dünyalar benim olmuştu. 

babamdan ilk tokadımı yedim, 

tamer e mektup yazarken yakalanınca. 

akşam olup,annem sofrayı hazırladığında, 

sofranın bir köşesinde duran, 

babamın rakı kadehini hiç unutmam. 

kokusuna bayılırdım. 

nedendir bilmem rakı kokusunu, 

halen çok severim. 

Şerefe dostum demek gelirdi içimden babama, 

kadeh tokuşturmak onunla. 

Bazen düşünürüm, 

babamın rakı kadehinden gelen kokular mıdır? 

beni içirten otuz dokuzumda. 

ya da, 

durup dururken anımsadığım çocukluğum mu? 

Yoksa bunların hepsine sebep, 

Sen misin? 

Sen misin ey! 

Bana şiirler yazdıran, 

Yüreğime ateş saçan, 

Güzel İnsan.

24.12.2003', 'Nedendir bilmem,  çocuk olmak,  çocukluğumu anımsamak,  geldi içimden bugün.  çocuksu duyguları,  saflığı,samimiyeti,sevecenliğimi özledim b...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/nedendir-bilmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi tohumları', 'sevgi-tohumlari-nazife-abayli-lvo27', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zoraki yaşıyormuşum,

Daha düne kadar.

Oysa bugün,

Yüreğim kıpırdıyor,

Kanım kaynıyor.

Bir başka görüyorum insanları,

Kıskançlık,

Fesatlık tohumuyla yetiştirdikleri,

Zehirli elmayı yedirip,

Gözlerimi kapatan,

İnsanları bile farklı görüyorum.

Her öğlen okuluma giderken,

Zincirini koparırcasına havlayan,

Isırmaya yeltenen,

Komşu köpeğini bile,

Farklı görüyorum.

Bir başka seviyorum bugün çocukları.

Haylazlıklarını,

Teneffüs aralarında,

Sınıfı toz duman etmelerini,

Bir başka görüyorum.

Ruhumu sıkan,nefesimi daraltan,

Bedenimi yoran,

Puslu havayı bile,

Bir başka seviyorum.

Ey! Güzel İnsan! 

Bunlara sebep SEN misin? 

Yoksa,yüreğime ektiğin,

Sevgi tohumları mı? 

             25.12.2003', 'Zoraki yaşıyormuşum, Daha düne kadar. Oysa bugün, Yüreğim kıpırdıyor, Kanım kaynıyor. Bir başka görüyorum insanları, Kıskançlık, Fesatlık to...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgi-tohumlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni buldum', 'seni-buldum-nazife-abayli-kh5gm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç bir şeyi önemsemedim,

Seni önemsediğim kadar.

Kim olursan ol,

Ne olursan ol,

Ben seni sevdim,

Seni yar bildim.

Bilmezsin,

Seni beklerken,

Ömrümün yarısını bitirdim.

Sarardım,soldum,HAZAN oldum,

Ümidimi yitirmişken,

SEN''i buldum.

           26.12.2003', 'Hiç bir şeyi önemsemedim, Seni önemsediğim kadar. Kim olursan ol, Ne olursan ol, Ben seni sevdim, Seni yar bildim. Bilmezsin, Seni beklerken...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-buldum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım çocuklarım', 'canim-cocuklarim-nazife-abayli-4t0qi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '38 çocuğum var benim,

22 erkek,16 kız.

Hepsi birbirinden şirin,

Hepsi birbirinden güzel.

Doğduklarında ellerime,

Yuvasından düşmüş,

Kuş gibi ürkektiler.

Korunmasız...

Sarıldım,

Isıttım onları önce,

Korkularından arındırdım.

Sonra birer birer,

Sevgiyle yoğurdum.

Çoğu zaman,

Onlarla birlikte çocuk oldum.

İp atladım,top oynadım.

Elleri kirlendi yıkadım,

Burunlarını temizledim.

Ağladılar,ağladım,

Güldüler güldüm.

Canım çocuklarım,

Siz olmasanız,

Ben ne yaparım.....

     06.12.2003', '38 çocuğum var benim, 22 erkek,16 kız. Hepsi birbirinden şirin, Hepsi birbirinden güzel. Doğduklarında ellerime, Yuvasından düşmüş, Kuş gibi...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canim-cocuklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanacaksın', 'yanacaksin-sefer-kurt-mtg3q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel dedim sana

Ama sen gelmedin

Sevdim seni çok sevdim 

Ama sen sevmedin

Neden ihanet ettin bana

Duydum ki oturdun nikah masasına

Bensiz mutluluk haram sana

Yanacaksın yanacaksın

Aşkımdan kavrulacaksın

Ağlayacaksın ağlayacaksın

Bensiz mutlu olamayacaksın

Kollarımı açtım sana

Ama sen dönmedin

Canımı feda ederdim uğruna

Ama sen değerimi bilmedin

Yanacaksın aşkımdan kavrulacaksın

Çaresiz kalacak pişman olacaksın

Karanlıklara gömülüp hep ağlayacaksın

Arayacaksın beni çok arayacaksın

Benim yandığım gibi sende yanacaksın', 'Gel dedim sana Ama sen gelmedin Sevdim seni çok sevdim  Ama sen sevmedin Neden ihanet ettin bana Duydum ki oturdun nikah masasına Bensiz mut...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yanacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Az Kalsın Anılarını Öldürecektim', 'dun-az-kalsin-anilarini-oldurecektim-goktu-kara-1e4g6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geç git rüzgarım anılarımdan çek git

bozma beni ağlatma

delilik yaptırtma bana

geç git rüzgarım öldürme anılarını sevdiğimin

zamana kalem salladım günlerce

seni unutmamak için

direndim kendime

dün az kalsın anılarını öldürecektim

gaz sobası vardı parçacı hasanın

döktüm sessizce anılarını sobaya

sonra kibriti çaktım gözlerine

ama yakamadım

dün az kalsın anılarını öldürecektim

vaz geçtim', 'geç git rüzgarım anılarımdan çek git bozma beni ağlatma delilik yaptırtma bana geç git rüzgarım öldürme anılarını sevdiğimin zamana kalem sa...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dun-az-kalsin-anilarini-oldurecektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-nazife-abayli-fjgfi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak yine söndü,

Şehrin tüm ışıkları.

Evim yine sessiz,

Ben yine sensiz.

Seni özledim,

Sesini özledim.

Görmediğim yüzünü,

Dokunmadığım tenini özledim.

Çık gel hadi neredeysen,

Bitsin dayanılmaz özlemim.

        26.12.2003', 'Bak yine söndü, Şehrin tüm ışıkları. Evim yine sessiz, Ben yine sensiz. Seni özledim, Sesini özledim. Görmediğim yüzünü, Dokunmadığım tenini...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozlem-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-nazife-abayli-ohoej', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özlüyorum,

Deli gibi özlüyorum bugün seni.

Özlemin,

Gittikçe büyüyor içimde.

Sana ulaşabilseydim eğer,

Gelebilseydim yanına,

Ya da,

Gelebilseydin yanıma,

Sevda ateşiyle yanan dudaklarımı,

Dudaklarında bulurdun.

               26.12.2003', 'Özlüyorum, Deli gibi özlüyorum bugün seni. Özlemin, Gittikçe büyüyor içimde. Sana ulaşabilseydim eğer, Gelebilseydim yanına, Ya da, Gelebils...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozluyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Böyle Değil', 'oyle-boyle-degil-ahmet-aksoy-9av9s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben seni öyle sevdim ki

Nazım''ın Piraye''yi sevdiği gibi

.....................ve hiç bir hususta 

Nazım'' a yakın hissetmedim kendimi,

aşk hususunda hisstettiğim gibi,

ama ben seni hiç aldatmadım,

kendimi aldattığım gibi,

ben seni öyle sevdim ki,

.........senin bile haketmediğin gibi.

hiç bir süzülüşün olmadı zihnimde

...sana olan aşkımı hissetmediğim,

ve hiç bir kumadan hiç bir zaferden

..........zevk almamıştır,

bir kez de olsa senin yüreğini

...........................fetettiğim gibi,

ben seni öyle sevdim ki, 

..........öyle böyle değil,

senin bile haketmediğin gibi.', 'ben seni öyle sevdim ki Nazım''ın Piraye''yi sevdiği gibi .....................ve hiç bir hususta  Nazım'' a yakın hissetmedim kendimi, aşk hus...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oyle-boyle-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a sağnak bir yağmur gibi yağıyorsun', 'i-stanbul-a-sagnak-bir-yagmur-gibi-yagiyorsun-fatih-arslan-si52k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sağnak bir yağmur yağıyor İstanbul''a

Kaldırımlar sırılsıklam

Kalmıyor, sevgilinin ardından 

''Görünsün'' diye dökecek yaşlar

Ve satılığa çıkıyor gözyaşları

İnsan bir kere olsun

Doya doya ağlayamıyor.

Sağnak bir yağmur yağıyor İstanbul''a

İşte o vakitler,

Bir terkediliş vuruyor kalbe

Hüzün bulutları çöküyor yüreğime

Sigaramın eşgali belirsiz

Sigaram sönük,

Umudum sönük,

Boşuna çekiyorum hayatı,

İşlevini kaybetmiş bir sevda çekiyorum

Anla artık İstanbul, anla! 

Seviyorum.

Sağnak bir yağmur yağıyor İstanbul''a

Kimseler kalmıyor sokaklarda

Bir bir ışıkları sönüyor şehrin

Zifiri karanlık oluyor sevdalar

Patlıyor gökyüzü,

Yanıp sönüyor umutlarım

Yanıp sönüyor canım.

Sağnak bir yağmur yağıyor İstanbul''a

Aklıma düşüyorsun gülüm,

Konuşmuyorsun,

Ağlıyorsun,

Sen İstanbul''a sağnak bir yağmur gibi yağıyorsun...

Fatih Arslan', 'Sağnak bir yağmur yağıyor İstanbul''a Kaldırımlar sırılsıklam Kalmıyor, sevgilinin ardından  ''Görünsün'' diye dökecek yaşlar Ve satılığa çıkıy...', ARRAY['Türk Edebiyatı','Şiir','Fatih Arslan']::text[], 8.5, '{"poet":"Fatih Arslan","poet_slug":"fatih-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/istanbul-a-sagnak-bir-yagmur-gibi-yagiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut sevgilim', 'unut-sevgilim-fatih-arslan-hfggy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir insan niye sever? 

Niye bütün acıların adamıdır? 

Neden terkedilir? 

Bir gül verdiğinde sevgiliye

Neden affedilir? 

Sanki seven sevilene yüreğini vermedi mi? 

Tüm alnının terini dökmedi mi uğruna? 

Okuldan kaçıp dersi asmadı mı uğruna? 

Duy beni sevgilim 

Anla beni sevgilim

Bir gülleaffedeceksen eğer

Unut sevgilim.

Her gece senin için şiir yazıp, sabahlıyanı güller mi sandın

Hatırana dokunup mutlu olanı güller mi sandın

Sen gelmeyince gözleri yollarda kalanı güller mi sandın

Duy beni sevgilim

Anla beni sevgilim

Bir gül vermedim diye surat yapacaksan

Unut sevgilim.

Fatih arslan', 'Bir insan niye sever?  Niye bütün acıların adamıdır?  Neden terkedilir?  Bir gül verdiğinde sevgiliye Neden affedilir?  Sanki seven sevilene...', ARRAY['Türk Edebiyatı','Şiir','Fatih Arslan']::text[], 8.5, '{"poet":"Fatih Arslan","poet_slug":"fatih-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unut-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrence Aşk', 'evrence-ask-turgay-kadiroglu-sljx8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ipeksi bir yağmur sığınıyor düşlere,

 düştükçe ellerime, göğe uzanasım geliyor.

 ne hacet çıkmaya,

 gökler iniyor benim için sokaklara...

 güneş gözlerine iner kızılında sabahın

 ve süreyya kayar en ıssızında sükutun,

 ellerim kayar ellerinden,

 titremiyor ellerim sen bakma bana

 soğuk hava biraz...

 yıldızlar süzülür,

 kimi söner kimi ölür,

 yalancı ışıkları var gecenin,

 bin yıl öncesinden haber getirir.

 üzülme sen,

 gittiğin yerde de vardır yıldızlar,

 adadığım martının kanadında

 yüz bin galaksi parlaklığında ışık var...

 ey venüs! 

 nedir seni topraksız yollara vuran,

 neden görmez gözlerin güneşten başka,

 nedir uçuran seni kanatsız,

 direklerini ne vakit saldın,

 nesi var göklerin aşksız.

 nedir beni boğan bu duvarlar,

 neden mezarım topraksız,

 söyle venüs,

 neden yaşanmıyor yarsız..

 gittiğin dem buralardan,

 bir ''keşke'' dile dün için,

 bin en parlak ışığına evrenin,

 bugünü düne

 zamanı boşluğa eşitle,

 ne istediysen yap keşkende! 

 say ki dündü, say ki bugün,

 yarınlarda arama

 ben dünlerde sayıklıyorum...

 ışık renk hayatta,

 ışık can,

 ışık öz zerrede,

 elde durmaz, elden geçmez.

 aşka vurur ışık,

 yüreğim aydınlanır,

 aşk hayat,

 aşk var olmak,

 aşk yok olmak,

 akılda durmaz, sineden geçmez

 aşkın vazgeçilmez...', 'ipeksi bir yağmur sığınıyor düşlere,  düştükçe ellerime, göğe uzanasım geliyor.  ne hacet çıkmaya,  gökler iniyor benim için sokaklara...  g...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/evrence-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terket', 'terket-hakan-onal-s8qp3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bakma gözlerim yaşlı 

sen terket

bu yaşlar ayrılıktan değil

sebebi nefret

çok mu kolay sence 

sevilmeden sevmek

hani bunun neresinde 

söylediğin adalet', 'bakma gözlerim yaşlı  sen terket bu yaşlar ayrılıktan değil sebebi nefret çok mu kolay sence  sevilmeden sevmek hani bunun neresinde  söyled...', ARRAY['Türk Edebiyatı','Şiir','Hakan Önal']::text[], 8.5, '{"poet":"Hakan Önal","poet_slug":"hakan-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/terket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmekten yorulmadım.', 'sevmekten-yorulmadim-nazife-abayli-cx94c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmekten yorulmadım,

Sevdamı yazmaktan da.

Sen,sen olduktan,

Ben,ben olduktan sonra,

Kim susturabilir dili mi? 

Kim kırabilir kalemi mi? 

Kim söndürebilir? 

Yüreğimi yakıp kavuran,

Sevda ateşini? 

Sevmekten yorulmadım.

Sevdamı yazmaktan da...', 'Sevmekten yorulmadım, Sevdamı yazmaktan da. Sen,sen olduktan, Ben,ben olduktan sonra, Kim susturabilir dili mi?  Kim kırabilir kalemi mi?  K...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevmekten-yorulmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarım', 'saclarim-i-srafil-yildizkan-wyxy2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kesmeye, kestirmeye,

-Kıyamadığım saçlarım; 

- Ne oldu,

--Ne yaptım size? .

Bu küsmeler niye? 

-İlkokul çağımda,

Elimden birşeyler gelmezdi

--sıfırlandığınızda; 

İçin için yanmaz mıydım? 

-Lisede; 

Müdüre bile karşı gelmedim mi

--sizin için? 

Hiç dağınık bıraktım mı sizi? 

-Şimdi ne oldu da

Tek tek beyazlayıp

-Terk ediyorsunuz beni?', 'Kesmeye, kestirmeye, -Kıyamadığım saçlarım;  - Ne oldu, --Ne yaptım size? . Bu küsmeler niye?  -İlkokul çağımda, Elimden birşeyler gelmezdi ...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Yıldızkan']::text[], 8.5, '{"poet":"İsrafil Yıldızkan","poet_slug":"i-srafil-yildizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saclarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cocuklarla Ölsem', 'cocuklarla-olsem-sores-welat-demir-lghle', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir agac kovugundan daha kücük yuvalari

Alip cikarsam yikilmisliklardan o insanlari

Aydinlikta günes ile yikasam yüzlerini

Yaralarina bir ilac tutsam bir zaman

Kücük yürek büyük ask

Minik elleri bir fidandan daha ince

Parmaklari meyvasiz kalmis asma dallari

Rüyalarina yagmurlarla bereketler tasisam,..

Sonra alip bir ocak basinda as pisirsem

Bu senindir desem ve bu kalem bu kagit

Bu yatak anne yüregi kadar sicak

Bu lamba bir baba kadar yorgun.

Sokaklar sokaklar

Ve dönüp yüzüne, cocuk, desem

Seni bekliyor bütün oyunlar

Bütün mevsimler seninle bir ilkbahar

Yanagina bir öpücük kondursam, yumusak,..

Hic kimse agit yakmayacak artik

Hicbir türkü ve hicbir siir hüzün tasimayacak artik

Gözlerinle büyüyecek yasam

Hicbir yürekte kötülük görülmeyecek,..

Bütün gözyaslarini toplasam bulutlardan

Bütün silahlari bir meydanda gömsem

Sonra cikip kabirlerinden ölüler

Ayriliklari yeni yasamla dindirsem

Eriserek huzuruna Kadir-i Ser-i-f''in

Öperek el eteginden dilesem 

kaybolmus zamanlari bir bir

Bütün hasretleri aska cevirsem.

Olmazsa giderim

Bari o cocuklarla ölsem! ..

(Besinci Mevsim - Bir Sevgi Dünyasi adli siir kitabindan)', 'Bir agac kovugundan daha kücük yuvalari Alip cikarsam yikilmisliklardan o insanlari Aydinlikta günes ile yikasam yüzlerini Yaralarina bir il...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cocuklarla-olsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmekten yorulmayacağım demiştim', 'sevmekten-yorulmayacagim-demistim-nazife-abayli-pjxc8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmekten yorulmayacağım demiştim.

Şu an anladım ki,

Beklemekten de,

Yorulmayacağım.', 'Sevmekten yorulmayacağım demiştim. Şu an anladım ki, Beklemekten de, Yorulmayacağım....', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevmekten-yorulmayacagim-demistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğurdum Seni Şiir', 'dogurdum-seni-siir-yasar-pullu-a9u0o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğurdum seni şiir

bol sancılı kan revan

acıya ağrıya inat.

İşte büyüdün

konuşmayı öğrendin şimdi

bal da damlıyor dilinden kanda

hadı konuş

kök mü dosttur toprağa

bağrını yara yara

yaprak mı.

Anlamsız mı sevmeli

anlam bulaşınca mı güzel olur aşka.

Gökyüzü kusmaya başlarsa çektiklerini

ve ihaneti gözyaşına sararsa birileri

birileri namazda niyazdayken

birileri klan ları vuruyorsa

gökyüzü mü olmalı

yoksa

gözyaşı ihaneti affeder mi.

Hadı konuş şiir

kara kaşlı

......... endami selvi

.......................ince belli

eh biraz da cilveli

sevgiliye aşk kolay

adamsan bana uzat elini

yaramı sar.

Öpmeye kıyamadığım dudaklarını 

şimdi bir başkasına uzatıyorsan

geceyi aydınlatan tel tel saçlarını

cilvediyorsan

raki masalarında

kahpesin.

Bunda benim suçum yok

ve asıl bu yıkar beni

ama yok yıkılmam, ağlamamda

sadece oyalıyorsun beni

hepsi o kadar...', 'Doğurdum seni şiir bol sancılı kan revan acıya ağrıya inat. İşte büyüdün konuşmayı öğrendin şimdi bal da damlıyor dilinden kanda hadı konuş ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dogurdum-seni-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilide Sevgili Öldüm Ben', 'sevgilide-sevgili-oldum-ben-sores-welat-demir-8kzle', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolun geceye uzandigi ve ekmegin bölündügü yerden ayrildim ikiye

Varoslardan ögrendigim

Kahpelerden sakindigim en son yasam tanimini yüregime sakladim. 

Herkes gibiydim, insandim ve inancliydim

Ve ölecek kadar sevdaliydim yasama

Bir ölüm kadar bagliydim askima

Gözlerimde nuruyla dolastim bir sevdanin karanliginda ay isiginin

Oyunlarinda kaldi acisi yine bir sevdanin 

Yildizlardan sordum pesi sira sokaklardan

Tanrinin huzuruna eristim 

Egildim saygi olsun diye yerden 

onurum icin dimdik selam verdim huzurunda

Melekler gözlerini kacirdi benden yildizlar boyunlarini  büktü, oracikta, öldüm

Gökyüzünden kayan gözyaslarimin arasinda yeryüzünde yasam benimle agladi

Hic kimseler anlamadiysada bir sey

Hic kimse bilemesede

Bir sevgilinin yalaninda yilan hikayesi oldu hislerimiz,

keder ve isyan bizimkisi. 

Kimi tanidiysam biraz o oluyordum rüyamda; 

Biraz insan oluyordum biraz ask

Biraz rüzgar basaklarin arasinda 

ve biraz isyan kayaliklarda

Bir memleket bir inanc bir es ya da dost, ya da hepsi birden,..

Gidip vardim selamete

Ah icimi icimde

Ah bagrimi bagrimda dagladim sonra

Uzanmisim merhamete upuzun

Sevgilime varacakmis gönlüm

El etek öpecekmisim, 

O ara, afbuyrun, öldügümü unutmusum! 

(Besinci Mevsim - Bir Sevgi Dünyasi adli siir kitabindan)', 'Yolun geceye uzandigi ve ekmegin bölündügü yerden ayrildim ikiye Varoslardan ögrendigim Kahpelerden sakindigim en son yasam tanimini yüregim...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgilide-sevgili-oldum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soguk Gece', 'soguk-gece-sores-welat-demir-13k0p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SOGUK GECE

Soguk vurdu geceye

Geceler uzun geceler ayaz

Kallesligin soluguna 

Bir adim kala

Vuruldu bir sevda

Namertli dogdu geceye, namertliydi gece

Düstü oldugu yere yine emek

Bir can, bir yigit ask,..

O sessiz akan pinarlarda

Bir düs simdi

Bir irak ve bir söz

yangin gibi su gibi,..

(Besinci Mevsim - Bir Sevgi Dünyasi adli siir kitabindan)', 'SOGUK GECE Soguk vurdu geceye Geceler uzun geceler ayaz Kallesligin soluguna  Bir adim kala Vuruldu bir sevda Namertli dogdu geceye, namertl...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/soguk-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Boyunca Ögrendigim', 'yol-boyunca-ogrendigim-sores-welat-demir-sd8uk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YOL BOYUNCA ÖGRENDIGIM

Agri dagi kadar kutsal

Eufirat kadar coskun

Mesopotomya kadar eski

Tarih kadar agir

Dogu günesi kadar gizemli

Ceviz agaci kadar emekci

Ezogelin kadar nazli

Kar cicekleri kadar duygusal

Ses kadar hizli

Isik kadar aydinliktir

Benim memleketime ve insana olan sevdam,..

Asklar, belkide insanoglunun en zor denedigi

kahrolma ve kahretme bicimini gelistirir yol boyunca,..', 'YOL BOYUNCA ÖGRENDIGIM Agri dagi kadar kutsal Eufirat kadar coskun Mesopotomya kadar eski Tarih kadar agir Dogu günesi kadar gizemli Ceviz a...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yol-boyunca-ogrendigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasama Söz Verdik', 'yasama-soz-verdik-sores-welat-demir-73im3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YASAMA SÖZ VERDIK

Sana dost sana can 

Ve sana yasam vermeye 

Cikti bu yürüyüscüler  yola

Yaralarin derin 

Acin derin

Dayan ha dayan

Yarana derman olmaya söz verdik

Cünkü doga ana

Cünkü biz yasami sevdik.

(Besinci Mevsim - Bir Sevgi Dünyasi adli siri kitabindan)', 'YASAMA SÖZ VERDIK Sana dost sana can  Ve sana yasam vermeye  Cikti bu yürüyüscüler  yola Yaralarin derin  Acin derin Dayan ha dayan Yarana d...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasama-soz-verdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretler Ayrılıkla Başlar', 'hasretler-ayrilikla-baslar-seval-kemertas-7n1il', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ansızın kırılıverir

sıkı sıkı tutunduğun dallar

ayrılır birbirine kenetlenmiş yürekler

dışarda kar yağar,gözünde yağmur

deli rüzgar gibi eser ayrılık yeli

içinde yarını olmayan bir zaman ağlar...

vuslat hiç gelmez söner ışığın

gözlerine acı bir karanlık düşer

için için kaplar tüm benliğini

solar içinde filizlenen umutlar

gönlünde yarını olmayan bir mevsim

eksik bir bahar başlar...

medet umduğun kuşlar

çoktan kaybolur gider ufuktan

akşam kızıllığından silinir yüzün

hüzünle kucaklar seni kederli rüzgar

aldığını vermez olur

bir zamanlar dost bildiğin dalgalar...

gidenler bilmez kalanın içindekini

bilmez çekmeye razı olduğunu tüm kaprisleri

boyun eğersin zincire vursada seni

zamansız küllenr yanan ateşin

vazgeçersin düşlerinden yüreğin susar

artık gücün yoktur dünlere dönecek kadar...

21/12/2003', 'ansızın kırılıverir sıkı sıkı tutunduğun dallar ayrılır birbirine kenetlenmiş yürekler dışarda kar yağar,gözünde yağmur deli rüzgar gibi ese...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hasretler-ayrilikla-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mi’nin Ölüm Haberi', 'mi-nin-olum-haberi-ali-osman-yilmaz-75uac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin  elem dolu,

Ölüm haberini bildiren,

O mail bana ulaştığında,

Yıkıldım birden.

O adamın dedikodularının,

Enkazı altında kalmışsın,

Seni sağ çıkaramamışlar,

Ölüm haberin tüm acımasızlığıyla,

Geldi yaktı yüreğimi.

Şimdi beni  anacak,

Anılarımızı konuşacak,

Kimse kalmadığı için,

Unutulmuşluğun acısıyla,

Yaşamaya çalışacağım.

Artık mezarına gelerek,

Seni ziyaret edeceğim,

Ellerimde bir demet,

Kırmızı gül olacak,

Her zaman olduğu gibi,

Seninle konuşacağım,

Sen yalnız dinleyeceksin,

Ve yaşlı gözlerle güzelim,

Allahaısmarladık diyerek,

Mezarlıktan kendi yalnızlığıma,

Unutulmuş insanların arasına,

Sensiz, döneceğim.

22  Aralık.2003 Bursa', 'Senin  elem dolu, Ölüm haberini bildiren, O mail bana ulaştığında, Yıkıldım birden. O adamın dedikodularının, Enkazı altında kalmışsın, Seni...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mi-nin-olum-haberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakalın dostlar', 'hoscakalin-dostlar-nazife-abayli-xhnib', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne oldu sizlere? 

Ne oldu dostlar? 

Daha dün döktürmediniz mi? 

Gözyaşlarımı.

Ağlatmadınız mı? 

Neden bugün bu telaş? 

Neden bu kaygı? 

Dostluk derken,

Kardeşlik derken,

Onurumu hiçe sayan,

Ağlatan sizler,

Şimdi ne yitirdiniz? 

Yitirmeyi mi? 

Kabul edemediniz? 

Hoşçakalın dostlar,

Hoşçakalın.

Bensiz,

Yeni dostluklara açılın....', 'Ne oldu sizlere?  Ne oldu dostlar?  Daha dün döktürmediniz mi?  Gözyaşlarımı. Ağlatmadınız mı?  Neden bugün bu telaş?  Neden bu kaygı?  Dost...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hoscakalin-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unutma', 'beni-unutma-gul-can-kpkww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-UNUTMA-

Sabah gün doğuşunda,masum bir gülümsemeyle uyan dudaginda,

Ve beni hatırla,unutma…

Her gülümsediğinde halim gelsin aklına

Ve beni hatırla,unutma…

Eger birgün,uykun kaçıp çıkarsan balkona

Gecenin tenhasında ve karanlıklarda

Üşürse bedenin,bakarken yıldızlara,

Sen beni hatırla,unutma…

Çünkü ben; her gece yıldızlı semanın gölgesinde,

Bakmaktayım o uzaktaki yıldızlara,

Doğmayan birtek yıldızı bekliyorum tüm umudumla,

Ve hep aynı dileği tutuyorum,kayan yıldızlarda.

Şimdi son bir söz söylüyorum sana 

Lütfen beni hatırla,unutma…

Ve aklına geldiğim anda

Birileri de seni düşünüyor unutma…

                                  18/12/2003', '-UNUTMA- Sabah gün doğuşunda,masum bir gülümsemeyle uyan dudaginda, Ve beni hatırla,unutma… Her gülümsediğinde halim gelsin aklına Ve beni h...', ARRAY['Türk Edebiyatı','Şiir','Gül Can']::text[], 8.5, '{"poet":"Gül Can","poet_slug":"gul-can","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-unutma-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-ferit-teksoy-ozg4i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Silah gibi şakağıma dayadın

İstermisin diye sormadın gönül

Hiç bahar yokmuydu yaşatacağın? 

Kıştan başka mevsim vermedin gönül.

***

Sana ne yaptım ki; hep zoru seçtin? 

Aşılmaz dağ koydun önüme gönül.

Karanlıkta kaybettikçe yolumu,

Yardımcı olmadın yönüme gönül.

***

Tırmandıkça uzattın merdiveni,

Tırmandım tırmandım bitmedi gönül.

Her uzandığım dal elimde kaldı,

Meyveye hiç elim yetmedi gönül.

***

Denizleri aştım derede boğdun

Sakin bir kıyıya varmadın gönül.

Ben yoruldum,ben yıkıldım,ben bittim

Elimden tutmadın,sormadın gönül.

***

Hani candık..canandık biz seninle! ..

Başıma işleri sen açtın gönül.

Sonuna dek seninleyim demiştin,

Zoru gördüğünde hep kaçtın gönül.

17 Nisan 2001', 'Silah gibi şakağıma dayadın İstermisin diye sormadın gönül Hiç bahar yokmuydu yaşatacağın?  Kıştan başka mevsim vermedin gönül. *** Sana ne ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemediğim...', 'vazgecemedigim-i-brahim-ethem-bingul-0i7h1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tuzağımsın, tuzağına yakalandım,

Avcıydım... avın oldum,

Sülün edalım, sürmelim, ceylan gözlüm,

Kara sevda saçlım, ben sana vuruldum,

Serbest, hür, özgürdüm ben,

Nasıl kıydın, yaraladın sen,

Ciğerimden, kalbimden vurdun,

Soluk bile alamıyorum, sen beni öldürdün,

Atmayan kalbinle, beni sensiz bırakma,

Zevkimi aldın, ne yapayım seni diye sorma....

Duvara, şöminenin üzerine asarsın,

Torunlarına gösterir, gurur duyarsın,

İşte bunu ben vurdum dersin,

Eğer bir gün yüreğin titrerse, sevdiğim,

Hakkımı helal ettim, vazgeçemediğim....', 'Tuzağımsın, tuzağına yakalandım, Avcıydım... avın oldum, Sülün edalım, sürmelim, ceylan gözlüm, Kara sevda saçlım, ben sana vuruldum, Serbes...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vazgecemedigim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-tabir-gokce-7k0j4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlıyorsun, göz bebeklerime bakarken

Okşarken saçlarımı ellerin titremede

Yatağımın başucunda tedirgin gülümsemelerin

Ve geçmişin güzelliklerini anlatmaların neden…

Aldırma,

Bak, birazdan doğacak güneş üstümüze

Griliğine rağmen bulutların… 

Soyun hüzünlerinden, yeşil gözlerin gülsün

Islak yanaklarını dudaklarımla kurutmalıyım 

Eğil biraz yorgunum…

Ağlıyorsun, göz bebeklerime bakarken hala

Dokunmalarında bir ürperti, bir heyecan

Belki içgüdüsel ama, sendeki sanki korku

Aldırma

Bak birazdan doğacak güneş, her günkü gibi

Sevdamızın ölümsüzlüğüne

Her yanım sıcak şimdi, her yanımda melekler

Her biri senin gibi çekici, senin gibi güzel

Belli ki götürecekler…

Hoşça kal…', 'Ağlıyorsun, göz bebeklerime bakarken Okşarken saçlarımı ellerin titremede Yatağımın başucunda tedirgin gülümsemelerin Ve geçmişin güzellikle...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hoscakal-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzelim...', 'gamzelim-i-brahim-ethem-bingul-o82tv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yasak değilim sana,

O gözle bakma bana,

Seviyorsun bakma aklına,

Yüreğine bak, gerisi boş sana...

Gamzenle, dudaklarınla,

Yarım bıraktığın aşk legonla,

Tam yaşayamadığımız aşkımızla,

Çıldırıyorsun sen bana...

Geleceksinde niye bekliyorsun,

Gördüğün rüyaya ne oldu? ... Baharımı bekliyorsun? 

Bizim aşkımız rüyada mı kaldı,

Merak etme senin gönlün bende kaldı...', 'Yasak değilim sana, O gözle bakma bana, Seviyorsun bakma aklına, Yüreğine bak, gerisi boş sana... Gamzenle, dudaklarınla, Yarım bıraktığın a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gamzelim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirdeki gerçek...', 'siirdeki-gercek-i-brahim-ethem-bingul-u3c50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben şiir''e şiir demem,

Sevdiğimden duymayınca,

Onun her sözü şiirdir,

Baştan sona uctan uca,

Dinleyene ilham verip,

Onu şair yapınca,

Ben şiir''e şiir demem,

Kalem şair olmayınca,

Yazarken kalb terlemeli,

Okurken yar dinlemeli,

Şiir aşkın meyvasıdır,

Kalbten kalbe yönelmeli,

Gönülleri coşturmalı,

Yare koşturan olmalı,

Benim istediğim şiir,

Aşk''a merdiven olmalı,

Şair aşkı bilen güzel,

Şiir taa.. ezelden güzel,

Beni benden alan güzel,

Senden başka şiir bilmem,

Gelip telime dokundun,

Sana yazıldım okudun,

Alıp benliğime doldun,

Sevdim, sevmeden edemem,

Her dizede yanlız sensin,

Şarkılarda, şiirdesin,

Her an gözümde tütersin,

Senden bunu gizleyemem...', 'Ben şiir''e şiir demem, Sevdiğimden duymayınca, Onun her sözü şiirdir, Baştan sona uctan uca, Dinleyene ilham verip, Onu şair yapınca, Ben şi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/siirdeki-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dunya Kirlendi', 'dunya-kirlendi-guner-kaymak-v2vvf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dunyada savaslar bitmek bilmiyor

Lakin elimizden fazla birsey gelmiyor

Kadinlar cocuklar paramparca oluyor

Lakin elimizden fazla birsey gelmiyor

Silah mafyalari silahlarini satiyor

Kapitalistler servetine servet katiyor

Cok gariban evsiz sokaklarda yatiyor

Lakin elimizden fazla birsey gelmiyor

Simdi adalet tamamen gucluden yana

Zalimler hic acimadan kiyiyor cana

Melun diktatorler hukmediyor cihana

Lakin elimizden fazla birsey gelmiyor

Issizlik ordusu her yani aldi yurudu

Sulugenler siyasi kiligina burundu

Namuslu yasayan yandi surundu

Lakin elimizden fazla birsey gelmiyor

Dunya kirlendi hastaliklar cogaldi

Hersey hormonlu lezzet kalmadi

Evrensel beyanname ise yaramadi

Lakin elimizden fazla birsey gelmiyor

Zalimin zulumune seyirci kaliyoruz

Savas''tan teror''den hic kurtulmuyoruz

Dogal felakete sanmayin aldirmiyoruz

Lakin elimizden fazla birsey gelmiyor

Insanligin kuyusunu insan kaziyor

Tabiatin dengesini insan bozuyor

Gokyuzu''de  tikandi uydu yuzuyor

Lakin elimizden fazla birsey gelmiyor

Teknoloji nerdeyse zirveye vardi varacak

Kim bilir ileride ne degisecek neler olacak

Guner der masum zalimden hesap soracak

Su an elimizden fazla bir sey gelmiyor

Amsterdam / 26.12.2003', 'Dunyada savaslar bitmek bilmiyor Lakin elimizden fazla birsey gelmiyor Kadinlar cocuklar paramparca oluyor Lakin elimizden fazla birsey gelm...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dunya-kirlendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İz', 'i-z-halit-gokmen-2cm4a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'can evimin üstünde 

üç gün üç gece taşıdım

busenden kalan izi

kendime paye yaptım

bir sır gibi sakladım herkesten

bu, senden kalan izi

gizli gizli baktım aynalara

sigaralar yaktım

seni her andığımda

izin dalga dalga eksildi

kum taneleri gibi savruldu kumsallarda', 'can evimin üstünde  üç gün üç gece taşıdım busenden kalan izi kendime paye yaptım bir sır gibi sakladım herkesten bu, senden kalan izi gizli...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-halit-gokmen-9vmax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yokluğun

kanatır içimi,

varlığınsa

havalandırmada bir sigara, 

nemli koğuşumda 

demli bir çay misali

ısıtır içimi,

gel neredesin', 'yokluğun kanatır içimi, varlığınsa havalandırmada bir sigara,  nemli koğuşumda  demli bir çay misali ısıtır içimi, gel neredesin...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perihan', 'perihan-halit-gokmen-bot8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sinsi, sinsi yağar zifiri karanlık

gecenin üstüne, üstüne

gök kubbede tüm kandillere üflenmiş

sokak lambaları, hak getire

köşe başlarını tutmuş batakhaneler 

kerhanelerde yosmanın bini bir para 

içli, içkili, muhtelif bağırışlar 

şuh kahkahalar sarıp sarmalar geceyi

hır gür, hengame, gırla

aşk başlara vurmuş

kibrit çaksan tutuşur bedenler

ateş de var barut da 

ıslak kaldırımlarda başlar 

gece mesaisi Perihan’ın

sevişmeler laf ola 

sevişmeler zamansız

sabahlara kadar 

yemidir yeni yetme delikanlıların

maksat, 

aç biilaç dönmemek fakirhaneye

ömür törpüsüdür 

zevkhanelerde sarhoş kahrı,

sen kokladın mı hiç? 

ekşimiş alkol-nikotin deposu bedenleri

düşündün mü hiç? 

Perihan’ı bu yola düşüren nedenleri.

namusun namlusunu dayasan ensesine

recmden dem vursan, fayda etmez 

sözlüklerde solmuş sözcüklerden o

geceyi emzirir altıntop memelerinden

gündüzler doğurur nur topu

yitirilmez umutlar saklar koynunda

anasından kalma muska taşır 

kaç yıllardır boynunda

asıl adını sorsanız bilmez, 

adı, unutulmuş mezarların kırık taşıdır

kafakağıdını eline almayalı nicedir.

Perihan bir doğal afet

Perihan balık etli güzel yüzlüdür

saçının tek teline, canlar verir adamlar

bir çoğunun façasındaki iz ondan yadigar

çaresiz ne yaşamlar eskitir', 'sinsi, sinsi yağar zifiri karanlık gecenin üstüne, üstüne gök kubbede tüm kandillere üflenmiş sokak lambaları, hak getire köşe başlarını tut...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/perihan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-halit-gokmen-7hc54', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ki 

Kibele gibi bereketli

Sen ki 

Toroslar gibi yüce yürekli

Eteğinde topladın bizi

Koruyup kolladın 

Torunların oldu dizi dizi

Ayırmadın onları,

bizden ileri sevdin

Bizlere bütün ömrünü verdin

Nasıra durdu ellerin

ışıl ışıl yüreğin

Yemez yedirir, giymez giydirirsin

Güzel-çirkin, zengin-yoksul demezsin

Hümanistsin, tüm insanları seversin

Tanrı seni başımızdan eksik etmesin', 'Sen ki  Kibele gibi bereketli Sen ki  Toroslar gibi yüce yürekli Eteğinde topladın bizi Koruyup kolladın  Torunların oldu dizi dizi Ayırmadı...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazır değiliz', 'hazir-degiliz-halit-gokmen-7l7q1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne çok özledim seni 

bir bilsen

Ayrılık saati hiç gelmese

Zaman dursa birlikteyken

Ancak biliyorum

her şeyi paylaşmaya

Ne sen hazırsın ne de ben', 'Ne çok özledim seni  bir bilsen Ayrılık saati hiç gelmese Zaman dursa birlikteyken Ancak biliyorum her şeyi paylaşmaya Ne sen hazırsın ne de...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hazir-degiliz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-halit-gokmen-em2y2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tak,tak,tak…

kapı çalınıyor

kulağım kirişte

biliyorum gelen sen değilsindir 

ama

Pandora’nın kutusunda kalan

bir tek umut

ne yaparsın işte.', 'Tak,tak,tak… kapı çalınıyor kulağım kirişte biliyorum gelen sen değilsindir  ama Pandora’nın kutusunda kalan bir tek umut ne yaparsın işte....', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beklenen-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürperir zaman', 'urperir-zaman-halit-gokmen-af5ad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağustosu on bir geçenin

gecesini dört yüz geçe

alışılmadık bir serinlikte 

aksayan adamla oğlunu karşılar

koltuğu ekmekli kadın

yetiştirir müjdeyi 

ürperir çatılarda 

hakuran kuşları

toplaşıp tüylerini kabartır

getireceklerinden habersiz

götüreceklerinden habersiz

sevinir aksayan adamla oğlu

giderler birer, birer

tanıdık bildik birileri 

tanınmadık bilinmedik yerlere 

gecenin serinliğinde

ürperir şehir,

tüm şehirler ürperir 

bilinmeyen gecelerde, bir başşehirde

ürperir aksayan adamın oğlu

patlayan dudağında sızıntı

belinde ince bir sızı.

ürperir şehrin derinliklerinde

can evinde saklı bir maça kızı

mevsimler ürperir

utanır insan

eylül ürperir

unutkan insan

şehirler ürperir 

umutvar insan, 

zaman ürperir, ürperir zaman.', 'ağustosu on bir geçenin gecesini dört yüz geçe alışılmadık bir serinlikte  aksayan adamla oğlunu karşılar koltuğu ekmekli kadın yetiştirir m...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/urperir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüphen Olmasın', 'suphen-olmasin-aziz-pinar-fu2ir', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgimden hiç mi hiç şüphen olmasın

Gönlünü rahat tut takma aklına

Ömrümü adarım,derdin olmasın

Soruları takıp durma aklına...

Sevgilere çarpsın kalbinin sesi

Gülüşlere aksın aşkın nefesi

Dudaklara konsun umut busesi

Soruları takıp durma aklına...

Bir demet çiçeği örüp saçına

Bu aşkın tacını takıp başına

Bende severim de Allah aşkına

Soruları takıp durma aklına...', 'Sevgimden hiç mi hiç şüphen olmasın Gönlünü rahat tut takma aklına Ömrümü adarım,derdin olmasın Soruları takıp durma aklına... Sevgilere çar...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suphen-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Fırtına', 'bir-firtina-aziz-pinar-0a3el', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir fırtınaydı geldi geçti

Sen denizdin bu fırtınada

Kızdın köpürdün,azdın kudurdun

Ben kıyılar gibi inledim durdum...', 'Bir fırtınaydı geldi geçti Sen denizdin bu fırtınada Kızdın köpürdün,azdın kudurdun Ben kıyılar gibi inledim durdum......', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-firtina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın pişmanlık yasası', 'askin-pismanlik-yasasi-halit-gokmen-gai54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beklemediğin bir günde 

bir gecenin ayazında

battaniye gibi dökülsem dizlerine

sabaha kadar ağlayıp

“pişmanım, dön bana ay ışığım” desem…

yüzüme bakıp

“her şey değişti” mi dersin? 

yoksa hiç hak etmediğim halde 

beni affeder misin? 

bilirim yiğitsindir 

yüreklisin de

zaten niye sevdim sanıyorsun seni

yüreğin ve beynindir 

cezbeden beni 

çıksın artık 

aşkın pişmanlık yasası

ilk yararlananı ben olayım

olayım da ben öleyim', 'beklemediğin bir günde  bir gecenin ayazında battaniye gibi dökülsem dizlerine sabaha kadar ağlayıp “pişmanım, dön bana ay ışığım” desem… yü...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askin-pismanlik-yasasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-halit-gokmen-xmeq7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Atmışlı yılların sonu, büsbütün yetmişli yıllar 

	O günkü çocuklar ne kadar şanslıydılar.

	Her evde bir dolu çocuk, 

	her sokak bir çocuk parkıydı

	İki taş arası geçit vermezdi kaleler,

	gün boyu oynanırdı uzun eşekler,

	hoptikler, yakan toplar.

	Güneş batınca başlardı saklambaçlar.

	Neden derseniz? 

	Çocukları karanlıkta en iyi 

	evlerin çıkıntıları saklar.', 'Atmışlı yılların sonu, büsbütün yetmişli yıllar  	O günkü çocuklar ne kadar şanslıydılar. 	Her evde bir dolu çocuk,  	her sokak bir çocuk pa...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cocuklugum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-halit-gokmen-wfkvz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen

	Bir, beş, sekizin sonunda 

	bir nokta

              Sen 

	deniz dibinde

	istiridye içinde 

	Ve sen içimdesin', 'Sen 	Bir, beş, sekizin sonunda  	bir nokta               Sen  	deniz dibinde 	istiridye içinde  	Ve sen içimdesin...', ARRAY['Türk Edebiyatı','Şiir','Halit Gökmen']::text[], 8.5, '{"poet":"Halit Gökmen","poet_slug":"halit-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bilmece-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokul Aşka', 'sokul-aska-aziz-pinar-iwsl8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalgalar nasılda azgın denizde

Rüzgar soğuk ve sert esiyor

Ellerin üşüyor değilmi

Bende üşüyorum

Bir gün bu üşümeler son bulacak

Sokul aşkımıza

Kalbin ısınacak...

Elbette sıcak bir yuva hayalimiz

Elbette rüzgarlar bir gün duracak

Şimdi yokluklara bağlı ellerimiz

Sokul aşkımıza

Özgür kalacak...

Omuzlarımız var yaslanacak

Ellerimiz var tutunacak

Ve sevgimiz varki dağlarca

Sevebildiğince,sevebildiğimce

Sokul bu aşka sokul

Dünya bizim olacak...', 'Dalgalar nasılda azgın denizde Rüzgar soğuk ve sert esiyor Ellerin üşüyor değilmi Bende üşüyorum Bir gün bu üşümeler son bulacak Sokul aşkım...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sokul-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme...', 'anneme-engin-ozcan-xasft', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anne...

Biliyorum, 

Beni özlüyorsun.

Bende seni özlüyorum,

Biliyorsun.

Kendimden öyle eminimki,

Sarıp sarmalayıp bana getireceksin, 

Boğazında düğümlenip kalan, 

Halbuki o kadar çok sevdiğin içli köfteyi.

Biliyorum.

Yarı uykulu bedenini, 

Yorgun ayaklarına emanet edip yine yollara düşeceksin.

Benim için.

Geceye yakın.. saat 8 gibi geri geleceksin..

Seni sabah alıp götüren fabrika servisi,

Homurtular çıkararak ve sallayarak evin akşap duvarlarını,

Seni bana getirecek.

Çantandan bir içli köfte daha çıkarıp

Yine bana vereceksin...

Biliyorum,

Yine ben tokum diyeceksin,

Gözlerin dolarak.

Saçımı okşayıp.. uyumamı bekleyeceksin üzerimi örtmek için.

Benim için değermi,

Hiç düşünmeyeceksin....

Saniyeli bir fitil kadar kısa ömrünü,

Benim için yollara sereceksin.

Seni anlamamı bile beklemeyeceksin...

Biliyorum.

Ben seni ancak,

Seneler sonra,belkide çok sonra,

O yavru kediyi evladım sayıp,

Kendi yemediğim salamı,ekmek arası yaptırıp

Yedirince anladım...

Çok geç olmadan şunu söylemek istedim..

Üç kelimeyle,

''Seni seviyorum Anne...''

Gözlerim dolarak.

Engin ÖZCAN

27/12/2003

ISTANBUL', 'Anne... Biliyorum,  Beni özlüyorsun. Bende seni özlüyorum, Biliyorsun. Kendimden öyle eminimki, Sarıp sarmalayıp bana getireceksin,  Boğazın...', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/anneme-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-engin-ozcan-v0nqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kayboluşumun nedeni

Aldatıcı bir çöl fırtınası mıydı? 

Yoksa çoban yıldızı mı? 

Böyle yıkıcı olan bir savaş mıydı? 

Kuşatılmakmıydı böle aniden? 

Ya neydi çaresizliğimin sebebi? 

Hastalıkmıydı,üşümekmiydi,

Hiç kartopu yapamamış olmamama sebep? 

Yalancı...

Hani değişik bir havası vardı bu memleketin? 

Kömür karası topraklarına ayak bastığımdan beri,

Ciğerlerimde bir is kokusu,

Dudağımda o hiç tanımadığım yerin yanık türküsü,

içimde eski alemlerin hatırası.

Belkide bu çaresizlik tek yönlü bu yola girmemin sonucu..

Yalancı...

Dalga sesleri sahile ulaşmadan gelirim demiştin.

Seni,saat intiharı çeyrek geçeye dek,

Seni,bir başka geceye dek,

Seni,bir başka bahara dek,

Herşey bir tarafa,

Seni,bir tek...

Beklemekten vazgeçtim.

Engin ÖZCAN

24-12-2003

İSTANBUL', 'Bu kayboluşumun nedeni Aldatıcı bir çöl fırtınası mıydı?  Yoksa çoban yıldızı mı?  Böyle yıkıcı olan bir savaş mıydı?  Kuşatılmakmıydı böle ...', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalanci-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimiş Noel Ağacı Altında Romans', 'eskimis-noel-agaci-altinda-romans-nevin-kalafatoglu-357ii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarhoş duygular getirir

Kuzey yıldızları

Uzaklar fısıldar yanık aşk şarkıları

Siluetlerini seyrederken dansının doğa

Bense armonisini aşkın

Balkondayım yine gece

Dağların izleri güneşi anımsatıyor bana

Denizin sesi platin yansımalar

Dağların zirvelerindeyim kar perileriyle

Düşlüyorum seni balkondayım...üşüyorum

Soğuklarlayım şimdi, yıldızlardayım

Seneye görüşmek mi? Demiştin...

Kim bilir bir taneciğim belki..

Eskimiş Noel ağaçlarının altında

Yok olan pırıltılarda...

Yeni bir yılın romansında neden olmasın...

Sen,ben ve Noel baba...boş ver yaa..

Takma kafana...ben alıştım buna..

İyi seneler sevgilim

Mutluluklar sana...

27.12.2003

Yeni yılınız kutlu olsun...

Sevgilerimle...', 'Sarhoş duygular getirir Kuzey yıldızları Uzaklar fısıldar yanık aşk şarkıları Siluetlerini seyrederken dansının doğa Bense armonisini aşkın ...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/eskimis-noel-agaci-altinda-romans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsamda Yazdım Olmasamda', 'olsamda-yazdim-olmasamda-adnan-ferit-47tx3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oldum mu şair,yoksa ham mı kaldım.

Kopardılar mı beni dalımdan zamansız,

bir ovanın ortasında 

ağaç yalnız ova ıssız...

Kurtlar mı üredi içimde,

benden habersiz.

Kemire kemire bitirdiler mi beni,

yoksa ben mi besledim o densizleri.

Delik deşik mi bıraktılar,ovanın ıssızlığında

ağacın dibinin yalnızlığında.

Tesellimse; 

Alamadılar ya benden bir diş bile.

Böyle de teselli olur mu be..

Oldummu şair yoksa hammı kaldım bilemem ama

kurtlanıp gidiyorum işte..

için için yiyip kurutuyorlar beni.

Güneş de pis pis gülüyor,

saklayıp kendisini.

Diyelimki oldum şair

acı içinde yaşamak elzem midir? 

Diyelimki ham kaldım,

anlamam bu iğrenç kurtlar

neden böyle zevklenir.

Ama sonuçta,

OLDUYSAM DA YAZDIM

OLMADIYSAM DA...', 'Oldum mu şair,yoksa ham mı kaldım. Kopardılar mı beni dalımdan zamansız, bir ovanın ortasında  ağaç yalnız ova ıssız... Kurtlar mı üredi içi...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olsamda-yazdim-olmasamda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senin Matemini Tutmak İçin Şair Olmadım', 'ben-senin-matemini-tutmak-i-cin-sair-olmadim-adnan-ferit-84vyy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben senin matemini tutmak için şair olmadım,

eski İstanbul şarkıları dinleyip iç çekerek,

rakı içmeye de özenmedim.

seni ben, beni sen yapan

her şeyi özlemeyide

hayal etmedim.

kapının önünde 

bavulun elinde

yorgun bakışını

dolu gözlerini 

bunlarıda hayal etmedim.

Ben şair olmaktan vazgeçmedim,

ama sen gittin

beni de götürdün.

ya dön,

ya da beni geri getir 

kapının önüne bırakırken de

öyle bir bakış bak ki

gözlerini hiç özlemiyeyim,

öyle bir söz söyleki,

seni bir daha hiç affetmiyeyim.

ama ne olur

sendeki beni bırakda git.

en azından içimde bir yerlerde

senden nefret etmiyeyim.', 'Ben senin matemini tutmak için şair olmadım, eski İstanbul şarkıları dinleyip iç çekerek, rakı içmeye de özenmedim. seni ben, beni sen yapan...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-senin-matemini-tutmak-icin-sair-olmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masmavi Gözlerinin Derinliğinde', 'masmavi-gozlerinin-derinliginde-adnan-ferit-8n9qe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masmavi gözlerinin derinliğinde,

yelken açmış gidiyorsun

apayrı bir yere doğru.

Benim kıyılarıma uğramıyacaksın biliyorum,

yinede uzaklardan geçerken,

o masmavi gözlerinin

güneş ışıkları ile oynaşarak çıkardığı

güzellikler içindeki

seni

özlememe izin ver...', 'Masmavi gözlerinin derinliğinde, yelken açmış gidiyorsun apayrı bir yere doğru. Benim kıyılarıma uğramıyacaksın biliyorum, yinede uzaklardan...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masmavi-gozlerinin-derinliginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Truva Atım', 'truva-atim-adnan-ferit-7dpp8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni sever gibi yaptın

aldandım

sana yüreğimi açtım.

Beni sever gibi yaptın

aşkım benim dedim elaleme.

herşeyimdin

kısrağımdın

oysa şimdi anladımki

sen içimdeki

truva atımdın..', 'Beni sever gibi yaptın aldandım sana yüreğimi açtım. Beni sever gibi yaptın aşkım benim dedim elaleme. herşeyimdin kısrağımdın oysa şimdi an...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/truva-atim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık ben seviyorum....', 'artik-ben-seviyorum-i-brahim-ethem-bingul-ww14w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlıyorum, mesudum..

Dostlar, artık ben de seviyorum,

Hep sevildim, sevmeye hasret kaldım,

Yarab, ne güzelmiş,

Bende de layık olanı sevecek gönül varmış,

Güneşim yoktu, yıldızlar beni sevdi,

Güneşi bekliyormuşum, yıldızlar aydınlattı beni,

Birgün Çamlıca Tepesi''nin ardından,

Sahiden bir güneş doğdu,

Görüntüsüyle, ışığıyla, sıcaklığı,

Beklediğim, sevdiğimdi herkesin aşık olacağı,

Doğudan doğmuştu,

Belki Bağdat belki Şam''dı,

Ben yoktum, Doğu, Batı''da yoktu,

Yanlız o doğdu... ama bana doğdu

Çamlıcadan gördüğüm,

Doğum ve ölüm,

Bir tarafta Zeynep Kamil,

Bir tarafta Karaca Ahmet,

Ne fark ederdi ki,

Her doğum bir ölüm,

Her ölüm bir doğum değil mi? ...

Güneşin doğması, onu bulmak,

Ölüm onda yok olmak,

Demeyin bana güneş batacak,

Yıldızlar doğacak,

Ben artık aydınlık güneş oldum,

Hep şiir yazılacak değilim,

Artık ben ona şiir yazar oldum....', 'Ağlıyorum, mesudum.. Dostlar, artık ben de seviyorum, Hep sevildim, sevmeye hasret kaldım, Yarab, ne güzelmiş, Bende de layık olanı sevecek ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/artik-ben-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahı Özledim', 'sabahi-ozledim-bekir-mutlu-gokcesu-i348f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklım sende

Ruhum senin

Sensizlik benim

Sen kimlerin? 

Bekledim

Yine gelmedin

Kapanıyor gözlerim

Sabahı özledim', 'Aklım sende Ruhum senin Sensizlik benim Sen kimlerin?  Bekledim Yine gelmedin Kapanıyor gözlerim Sabahı özledim...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sabahi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serhoş', 'serhos-hayrettin-turk-75edi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıkılsın karşı dağlar karşı dağlar

Sevdiğim başına karalar bağlar

Elveda demeden giden yolcuya

El sallar dönülmeze, sevdam ağlar…

Şimdi köhne mekanlarda deliyim

Avareyim, biçare divaneyim

Bir bitmez serhoşluk içinde gönlüm

Buyurun sizde için, meyhaneyim…', 'Yıkılsın karşı dağlar karşı dağlar Sevdiğim başına karalar bağlar Elveda demeden giden yolcuya El sallar dönülmeze, sevdam ağlar… Şimdi köhn...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serhos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasızlığa Sitem+', 'vefasizliga-sitem-bayram-tunca-by7am', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ümit bağlayıp sırtımı dayadıklarım fos çıktı 

Bağrıma bastıklarım, çoğu kez vefasız çıktı 

Dost gözükenlerin tavırları canımı çok sıktı 

Ummanlar gibi olan ümitlerimi aniden yıktı 

Gözlerimde cam, yüreğimde hayal kırıklığım 

Cam kırığından daha çoktur hayal kırıklığım 

İçimdeki burukluğumun ekseri dostların eseri 

Yoktur gördüğüm vefasızlıkların haddi hesabı 

12.12.2003-12:12 

Aşk Ateşten Gömlek', 'Ümit bağlayıp sırtımı dayadıklarım fos çıktı  Bağrıma bastıklarım, çoğu kez vefasız çıktı  Dost gözükenlerin tavırları canımı çok sıktı  Umm...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vefasizliga-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl Yeni Umutlar', 'yeni-yil-yeni-umutlar-metin-usengec-d266b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat devam ediyor kaybedilenlerle

Sevmekten aldım bende nasibimi

Tanımıyor gönlüm aşkı sevgiyi

Yaşananlar bitirmiş artık birçok şeyi

Hayalimden çıkmadı hiç gül yüzü 

Hatıralar aklımda sanki dün gibi

Ne kadar sitem etsem de boşuna 

Çaresiz yüreğim kaldı o yarda

Gittiğimiz yerlerde canlanır hatırası

Kırgın yüreğimde dinmeyen sancısı

Küstüm onunla hayata dair herşeye

İhtiyaç duydum bir parça olsun ilgiye

Yeni bir yıl yeni umutlarla geliyor

Nice yazlar baharlar akıp geçiyor 

Sevenlere yeni sevgiler aşklar

Ayrılanlara kalan buruk sonbaharlar

Geçen bunca zaman alamadı bendeki seni

Benden geçti artık aldım aşktan sevgiden nasibimi..

24-Aralık-2003  16:00

Ben Bende Değilim,Ben Sendeyim..', 'Hayat devam ediyor kaybedilenlerle Sevmekten aldım bende nasibimi Tanımıyor gönlüm aşkı sevgiyi Yaşananlar bitirmiş artık birçok şeyi Hayali...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeni-yil-yeni-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve yaşamak çok güzelmiş! !', 've-yasamak-cok-guzelmis-hicabi-ceylan-f3ipc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şey seni görünce başladı

Bir bankanın kambiyo servisiydi

Üzerinde lacivert bir manto vardı

Aylardan kasımdı

Pek hatırlamıyorum

Günlerden salımıydı yoksa çarşambamı

İşte o an hayatımdaki

Her şey ama şey değişti

Senin o bahar gözlerine bakınca kaybolmuştum.

Pırtılaşmış, pas tutmuş yüreğim tomurcuklandı

Üzerimdeki kara bulutlar bir, bir kalktı

Karanlık olan dünyama

Güneş gibi doğdun sen

Soğuktan kırağı düşmüş,

Buz kesen gecelerde

Sevginle ısındım ben

Her şey seni görünce başladı

Seni ilk gördüğümde sevdim

Sevince yaşadığımı hissettim

Ve yaşamak çok güzelmiş 

Bahar gözlüm.', 'Her şey seni görünce başladı Bir bankanın kambiyo servisiydi Üzerinde lacivert bir manto vardı Aylardan kasımdı Pek hatırlamıyorum Günlerden...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ve-yasamak-cok-guzelmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Geldiler Bir Gün', 'geldiler-bir-gun-emin-baydil-htcnx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pes be artık! ...

Ne bakanlar ne vekiller gördük biz...

Millet vekil, Allah vekil, diyenleri gördük biz...

Fakatı yok... Sen boş ver dostum,  fazla söze ne gerek! ..

kul hakkını yiyeni,

millet malı mukaddes, diyeni de gördük biz...

Emmi gördük,

yeğen gördük,

meclislerde çiğ köfte, leğen gördük.

Bizde vardır, her bir işten anlayan...

Ballıbabagillerden fesleğen gördük,

çiçekleri sulayan...

Şimdi de,

hem kuklalar,

hem robotlar yaptık biz...

Ve onlar, biliyorlardı her şeyi.

Uzayan gölgelerle geldiler bir gün...

Halılar serdik, yollarına renk renk,

çiçeklerle karşıladık, bire bir her şey denk...

Kapılar açıldı....

ve kapılar örtüldü,

Gülücükler dağıtıldı bir bir...

Kırk gün ve kırk gece sürmüştü  düğün,

başımıza demirden, tokmaklar indiği gün...

Belki biraz dövündük...eyvah eyvah! ! ! 

Biraz da övündük... eğer şöyle olsaydı bak! ...

...bizler mi? ! ..

en saf iklimlerde

ve belki de en berrak, sularda yaşamıştık.

Dinleyin, 

unutmayın! 

Bu bir çölde beşiğin,

beşbin yıllık tarihe, yazdığı dağ masalı...

işte o an gömüldük, gözlerimiz kapalı...

..............................27.12.2003 / Kastamonu', 'Pes be artık! ... Ne bakanlar ne vekiller gördük biz... Millet vekil, Allah vekil, diyenleri gördük biz... Fakatı yok... Sen boş ver dostum,...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/geldiler-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Kar Yağıyor', 'yuregime-kar-yagiyor-filiz-turan-bmc8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dışarıda kar yağıyor

Tane tane düşüyor bembeyaz kar taneleri

Havanın soğuğuna inat 

Bacalardan dumanlar yükseliyor

Sıcacık evlerinde  küçücük yavrular

Annelerinin koynunda uyuyor

Dışarıda kar yağıyor

Evimin penceresinden seyrediyorum

 Düşen masum kar tanelerini

Sokağın  köşesinde titreyen bir çocuk

Gözümde canlanıyor

 Yüreğime kar yağıyor...

Üşüyor yürekler yağan her kar tanesinde

Buz kesiliyor bedenler

Gidecek evi olmayan kimsesiz çocuklar

Bir köprü altında korkuyla seyre dalıyor 

Yağan her kar tanesinde bedenleri

 biraz daha uyuşuyor

Ve dışarıda kar yağıyor

Bir küçük yürek feryat ediyor gecenin ayazında

Ne arayanı var ne de merak edeni

Anne şefkatine sevgiye hasret

Yapayalnız bir küçük yürek üşüyor

Dışarıda kar yağıyor...

Çıplak ayakları uyuşuyor önce, sonra bedeni

Düşler görüyor, belki annesini 

Belki de hiç sahip olamadığı bisikleti

Sıcacık bir yuvanın düşünde ölüme yürüyor

Bir küçük yürek üşüyor ve kar yağıyor..

Oysa çocukken ne çok severdim karın yağışını

Kar topu oynamayı

Oynarken ellerimiz ve ayaklarımız donar uyuşurdu

Koşardık sıcacık evimizde sobanın başına

Üşüyen ellerimiz ısınırdı önce 

Sonrasında yüreklerimiz..

Oysa şimdilerde pek sevmiyorum karı

Üşüyen uyuşan bedenler geliyor aklıma

Çaresizce seyrediyorum karın yağışını

Yüreğim acıyor küçücük üşüyen bedenler için

Ve bugün yine dışarıda kar yağıyor

Biliyorum bilinmez bir yerlerde

Onlarca küçücük yürekler üşüyor..

Sevgi dolu bir sıcak yuvanın düşünde

Belki de yavaşça  ölüme yürüyor..

Yüreğime kar yağıyor...

19  aralık 2003', 'Dışarıda kar yağıyor Tane tane düşüyor bembeyaz kar taneleri Havanın soğuğuna inat  Bacalardan dumanlar yükseliyor Sıcacık evlerinde  küçücü...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yuregime-kar-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah olmalı', 'sabah-olmali-yagmur-damlasi-hz03e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bendeki bu durgunluk suskunluk

Fırtına öncesi sessizlik gibi

Zoruma gidiyor bu mahpusluk

Kurtar artık kurtaracaksan beni

Dağlar tuzak kokar geceleri

Bir tıkırtı bin ürperti verir

Yatağım kurt ini gibi

Sensiz gecelerde buz kesilir

Hasretim alemi kucaklasam

Bana tükenmeyecek gibi gelir

Sana ulaşmak ise davam

Soğuk demirler alev kesilir

Zor dostum ceylana gönül vermek

Hele ben gibi kurt isen

Sabahı beklersin her gece

Tekrar gece olacağını bile bile

Kağıt tükenir kalem düşer

Düşler tükenir birer birer

Savrulur tozar özlemler

Gece kalır bize birde gazeller', 'Bendeki bu durgunluk suskunluk Fırtına öncesi sessizlik gibi Zoruma gidiyor bu mahpusluk Kurtar artık kurtaracaksan beni Dağlar tuzak kokar ...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sabah-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son söz', 'son-soz-yagmur-damlasi-0v50y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessiz karanlıklar içinde dağları özlüyorum

Yorgun yakılan ateşleri ve alevin rengini  titriyorum

Pusuda kalmış yiğitleri ay ışığında

Dört yanı yaka yıka pusuları yarıp çıksa

Anlatmak kolay mı  yüreğini eline koyup uzatmak

Tepside al sana hayat...............................................................

Ölüme bir kahkaha patlat

Ne manasız ne yalan yaşamak

Gözlerinde yıkayıp gönlümü her şey silinsin diyorum

Yepyeni bir hayata başlamak istiyorum

Umutları öldürmek

Umutları olanları öldürmek

Dağda eşkıya şehirde eşkıya yürekte eşkıya olmak

Bana göre değilmiş anladım,

Bir yürekte sevdalı ah sevdalı dolaşmak

Nafile ki yeşile bağlandım

Bana göre değil umutları öldürmek

Umutları olanları öldürmek affet

Ya sil at bu kaderi yada kahret

Her şey senin elinde sığındım sana yetmez mi bunu bilmek', 'Sessiz karanlıklar içinde dağları özlüyorum Yorgun yakılan ateşleri ve alevin rengini  titriyorum Pusuda kalmış yiğitleri ay ışığında Dört y...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-soz-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm kadar güzel', 'olum-kadar-guzel-yagmur-damlasi-9bytj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kaldı elimizde ölüm kadar diri

Nerede onun kadar güzel ve sadık bir sevgili

Her şeyi zaman alırken elimizden

Bir soğuk gülüş kadı geriye garip benliğimizden.

Hasret bekleyiştir

Suskun mahpus saralı bir tuhaf özleyiştir

Zaman zaman bulduğunu sandığın

Ta kendisidir aldanmışlığın

Evet aldatıldık her birimiz ayrı ayrı

Üç günlük dünya demişlerdi üç günlük dünya

Yaşamaya çalıştık uzadıkça uzadı

Hep bir şeyler girdi ölüm ile aramıza

Zaman nasıl olsa geçer bizimde sıramız gelir

Biter zamanla göz yaşları özlemek biter

Biri gelir tüm defteri siler.........................................

Alacağı vereceği ne varsa hesaptan düşer.

Üçü beşi yok bu hesabın artık sıramız gelmeli

Kavuşmak için güzel sevgiliye

Toprak kokmak nasıl bir duygu ah bir bilseniz

Meselesiz olmak nasıl güzel

Belki o zaman anlatabilirsiniz arzularınızı

Kardeşinize eşinize belki o zaman anlarlar sizi

Karşılarına dikilince mutlak hakikat çıplaklığı

Neden bu kadar düşündüğünüzü ölümü anlarlar

Neden bu kadar sevdiğinizi hak felsefe ile geçen zamanlar', 'Ne kaldı elimizde ölüm kadar diri Nerede onun kadar güzel ve sadık bir sevgili Her şeyi zaman alırken elimizden Bir soğuk gülüş kadı geriye ...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olum-kadar-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısaca', 'kisaca-gulay-yildiz-02l4u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin; tanrının hediyesi

Ellerin; tutunacak dalım,

Nefesin; nefesim...

Geceyi bitirir güneşin,

Sevgim; sevgin...', 'Gözlerin; tanrının hediyesi Ellerin; tutunacak dalım, Nefesin; nefesim... Geceyi bitirir güneşin, Sevgim; sevgin......', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kisaca-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak', 'oyuncak-yagmur-damlasi-y6her', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer beni anlayan biri varsa

Yalvarırım susmasın söylesin

Bu acılar denizi

Bu fırtınalar tükensin

Tutsun ellerimden

Tutsun götürsün beni

Bir parça var içimde her şeyden

Tükenmişliğin ta kendisi

Bu hastalıklı düşünce

Yıllar önce.......

Gönlüme düşünce

Nasılda mutlu olmuştum

Bir çocuktum sanki

Oyuncağımı bulmuştum

Kaybedilen benmişim meğer

Oyuncağın bulduğu

Oynuyor benimle kader

Oynuyor ya

Kıramadı bir türlü', 'Eğer beni anlayan biri varsa Yalvarırım susmasın söylesin Bu acılar denizi Bu fırtınalar tükensin Tutsun ellerimden Tutsun götürsün beni Bir...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/oyuncak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz Yarim', 'aziz-yarim-ugur-arslan-97cwh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aziz diyar El aziz

Madenin gülü kokmuyor sensiz

Hala haritanın sağ köşesindeyiz

Her defasında sensiz her defasında sana dertliyiz

Aziz yarim sanki ben hala 25 sen hala 18

Değişen hiçbir şey yok bak bizde

Telvelerin kabardığı diplerde

Eşrefin oturduğu mahalledeyiz

Öyle bir özlemişiz ki seni

Artık dönsen de olur dönmesen de 

Biz her daim yine sana sitemli yine sana hasret gideriz

Aziz yar sen bir sabah bu şehri başıma yıkıp gittin

Dağları deviriverdin üstüme hiç çekinmedin

Ben bu şehirde bir daha da sabah görmedim

Günaydınlar olmadı günler aymadı sensiz

Karalar çekildi gözümün ferine

Son soluğumun dibine çöktüm öylece

Gidişin gibi durdum şuracıkta

Her gün şu köşe başında kaç yıllar saydım

Hiç yaşamadım sensiz ama hep yaşlandım inadına

Her hazan hep hüzünle geçti bu şehirde

Ben bir El azize birde sana kıyamadım işte

Her hazan hep hüzünle geçti bu şehirde

Ben bir El azize birde sana kıyamadım işte 

Daha geçmedi benim sana ağrılarım

Salındığın sokaklar hala sızım sızım

Yıktığın duvarlarda durur yine gül adı	n

Hiç dayanmadım hiç dayanamadım

Bu enkazın altında seni düşünmeden yaşamadım yaşayamadım

Ben sana nerde yanlış yaptım aziz yar

Bir sabah gidiverdin aklımı kaçırdım

Anlamadım hatalarımı hiç söylemedin

Kafamın içinde bu sorularla ölmedim bile bak ölemedim

Ben kafamın içinde bu sorularla ölmedim ölemedim

Bana bir özlemin kaldı yadigar bu viranede

Derdimi sığdıramıyorum bedene

Yıkılıyorum her geçen gün yokluğunun üstüne

Sıkılıyorum bazen

Sakınıyorum yinede seni gönlümün her köşesinde

Yine duruyor mu toyluğunun kabri gamzelerinde

İşvenin alası savrulurdu tellerinde

Ne senden geçilirdi ne bu diyardan gidilirdi

Bir tutam saçın uğruna yaktıydım ben bu şehri

Sonra bende yandıydım içinde

Hiç gitmedim buralardan senelerce

Sensizlikten gidemedim bir adım öteye

Bir derin yara bir derinlikli sevda bıraktın ya sen bana

Paylaşamadığım tek acı hatıra en anlamlı dua yine sendin bana sendin

Aziz yarim El aziz

Madenin gülü kokmuyor sensiz

Biz hala haritanın sağ köşesindeyiz

Her defasında sensiz her defasında sana demiz

Aziz yarim ben sanki hala 25 sen sanki 18

Değişen hiçbir şey yok bak bizde

Telvelerin kabardığı diplerde

Eşrefin oturduğu mahalledeyiz

Öyle bir özlemişiz ki seni

Artık dönsen de olur dönmesen de 

Biz her daim yine sana sitemli yine sana hasret gideriz', 'Aziz diyar El aziz Madenin gülü kokmuyor sensiz Hala haritanın sağ köşesindeyiz Her defasında sensiz her defasında sana dertliyiz Aziz yarim...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/aziz-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Adına', 'mutluluk-adina-gulay-yildiz-kamgy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapkaç gecelerin karanlığında

Minik bir yıldızdan gelen ışıksan

En karanlık kısmında bile hayatın

Sorunsuz ışıldamalısın yanlızda olsan

Santimi bile sayılmayan bedenlerin,

Farkında olunmayan hayatların nefesiysen

Hayat olup dolmalı, zehir olup çıkmalısın

Yanlızlıkla bir olup ta o bedeni bile paylaşsan

En asık surattaki dudağa hükmediyorsan

İnadına tebessümü yaratmalısın zor da olsa

Ve, ihtiyacı olanlara sunulsun diye sırf

Kahkahayı tattırmalısın ona acıyla doluda olsan

Zindanları aydınlatan gözlerdeki umutsan

Her zaman, daima ve hep ile birlikte

Mutluluğu eklemesin cümlelerine yaşama inat

Herşey bittikten sonra da anılmak istiyorsan', 'Kapkaç gecelerin karanlığında Minik bir yıldızdan gelen ışıksan En karanlık kısmında bile hayatın Sorunsuz ışıldamalısın yanlızda olsan Sant...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutluluk-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber iletsin', 'haber-iletsin-tuncay-emrem-r9kqo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Taz haber iletsin, söyle de rüzgâr,

Rize''nin dağları yine karlı mı? 

Ağlara takılırdı gümüş balıklar,

Karadeniz yine öyle zorlu mu? 

Evimin orada kapısı örtük,

Ses seda kesilmiş, lâmbalar sönük,

Çiçekler kurumuş, yapraklar dökük,

Ben gidince hepsi mahzun oldu mu? 

Yeşil yaylalarda yatasım gelir,

Rizenin çayından içesim gelir,

Uşaklarla horon tepesim gelir,

Bilmiyorum dizde derman kaldı mı? 

Burada öyle deniz, öyle hava yok,

Gönül yarasına öyle deva yok. 

Belki sâde mihnet, sâde cefa çok.

Bir alsam cevâbı, çilem doldu mu? 

!', 'Taz haber iletsin, söyle de rüzgâr, Rize''nin dağları yine karlı mı?  Ağlara takılırdı gümüş balıklar, Karadeniz yine öyle zorlu mu?  Evimin ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haber-iletsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıntı Duygular Ve Bir Karmaşık Dünya', 'alinti-duygular-ve-bir-karmasik-dunya-nurullah-zafer-okur-nwmhl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Harflerim alıntı kullandığım Alfabaden çaldım onları

 Parmaklarım Alıntı Yaratan verdi

 Kalemim alıntı onuda bir yerden aldım

 Gözlerim seni inceleyen alıntı

 Yaratan verdi

  Peki ya duygularım

 Onlar cizgileri izlerken nasıl bir alıntıdırki

 Zihnime işler

 Nasıl bir rüyadırki alıntı rüya

 Geceme girer

 Pus çökmüş hayatımda sisli yollarım

 Alıntılarla süslü etrafımda güzellikler

 Ama ya hislerim

 Alıntımıki acaba bu yaşadıklarım

 Kendi yaşamım yaşadıklarım

 Alıntımıki aldanmışlıklarım

 Sen? ya sen..

 Alıntımısınki sevinçlerim yada hüzünlerim...

 Alıntı hayatlarda kendi yaşamlarımız ile kalmak dileği ile..', 'Harflerim alıntı kullandığım Alfabaden çaldım onları  Parmaklarım Alıntı Yaratan verdi  Kalemim alıntı onuda bir yerden aldım  Gözlerim seni...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Zafer Okur']::text[], 8.5, '{"poet":"Nurullah Zafer Okur","poet_slug":"nurullah-zafer-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alinti-duygular-ve-bir-karmasik-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Suç Kimin)', 'dortlukler-suc-kimin-ahmet-aksoy-pxnnw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suç Kimin? 

Attığım taş kafana mı geldi

Kusura bakma canım

Ben doğru yere attım

Sen kafanı uzatmış olmalısın.

İnsan

Ben bir makineyim

Dönüştüren

İyiyi kötüye kötüyü iyiye

İyiyi iyiye kötüyü kötüye.

Bazıları

Bazı şeyler

Yıkılır dokunduğunda

Bekler dokunmanı

Yıkılmak için.

Yergici

Makineli tüfeğin atışları gibi

Attıkları sinek savar mermileri

Bir hicivdir tutturmuş

Sanır yaptığını yergiler yergisi.

Parayla Gelen Saadet

Fakirin yalnızlığı para

Paranın yalnızlığı para

İkisi bir araya gelse

Ne fakir yalnız ne para.', 'Suç Kimin?  Attığım taş kafana mı geldi Kusura bakma canım Ben doğru yere attım Sen kafanı uzatmış olmalısın. İnsan Ben bir makineyim Dönüşt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-suc-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
