INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-cihan-uluisik-ofjjd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelmedin 

Ben de sormadım.. 

İçimde sakladığım 

Yokluğunu açığa vurmadım 

Kur yapan çiftlerin gölgesinde 

Dileğimdi bir adın. 

Üzülme! 

Cehennem olsa o diyara gidecek 

Bir kadehte benim adım. 

Ama gelmedin ve ben sormadım.. 

Ağlama sevda, 

Yükselecek bir gün inan yadın. 

Ne kadar vahşi de olsa 

Bir saf çocuktur kadın. 

Sen hey tumturaklı güzel 

Bilirim acıdır tadın. 

Hadi gelmedin 

Bu şiirden de mi korkmadın! 

.

Öyleyse al hançerini bağrımdan 

Nolur hayası korkusuz kadın! 

26 Aralık 2003', 'Gelmedin  Ben de sormadım..  İçimde sakladığım  Yokluğunu açığa vurmadım  Kur yapan çiftlerin gölgesinde  Dileğimdi bir adın.  Üzülme!  Cehe...', ARRAY['Türk Edebiyatı','Şiir','Cihan Uluışık']::text[], 8.5, '{"poet":"Cihan Uluışık","poet_slug":"cihan-uluisik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gelmedin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın En Kuvvetlisine', 'ruzgarin-en-kuvvetlisine-gulay-yildiz-h8a0y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanlızlığın dokundu seni bekleyen günüme

Gözündeki yaşların sevdası aktı kalbime

Onsuz kalışlarında sarıldın bana

Beni kattın, bilerek katıldım düşüne

Gül, suya hasret zar zor büyür

Su geldimi güneşi bekler durur

Hem güneş hem su olabilirsen

Hem gül büyür hem yüreğindeki bülbül', 'Yanlızlığın dokundu seni bekleyen günüme Gözündeki yaşların sevdası aktı kalbime Onsuz kalışlarında sarıldın bana Beni kattın, bilerek katıl...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgarin-en-kuvvetlisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nergis', 'nergis-yagmur-damlasi-0pxwo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çok yalnızlık var yüreğinde at gitsin

En güzel kızı İzmir in inan ki sensin

Rastlamadım dünyada ben senin eşine

Gizli düşlerin peşinden gidişine

İncecik ve narin yüreğine

Sensiz ve sensiz giriversem bir gece', 'Ne çok yalnızlık var yüreğinde at gitsin En güzel kızı İzmir in inan ki sensin Rastlamadım dünyada ben senin eşine Gizli düşlerin peşinden g...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nergis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu', 'avuntu-yagmur-damlasi-6gi2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gecede sabahı bulduk

Tombaladan hayat çıktı

Akvaryumda ki dört balıkla avunduk

Sarıp sarıp sigaramız da sevdayı

Dumanı tüttürdük havayı kirlettik

Külünü düşürdük halıyı pislettik

Bir türlü tüketemedik zamanı

Sabah olmuyor eskisi gibi azizim

Uyku yok uzun zamandır

Bir tek ölümün nefesinde bir tek o bizim

O da yüreğimizde yardan hatıradır

Olsun ya ne güzel işte

Onunla olmayan sabahlar bile', 'Bu gecede sabahı bulduk Tombaladan hayat çıktı Akvaryumda ki dört balıkla avunduk Sarıp sarıp sigaramız da sevdayı Dumanı tüttürdük havayı k...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/avuntu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözlerin', 'mavi-gozlerin-turker-koluman-9i4od', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selvi endamında dünya bükülür

Kurumuş ağaçtan meyve dökülür

Yüreğim dağlanır kalbim sökülür

İçimi yakınca mavi gözlerin

İkindi mevsimi bahara döner

Melekler göklerden yerlere iner

Yediveren güller busene siner

Gözüme bakınca mavi gözlerin

Bülbülüm tutuştum yanarım gülüm

Her gece adını anarım gülüm

Aşkının tadına kanarım gülüm

Mehtaba çıkınca mavi gözlerin

Engeller dayanmaz ozan karına

Eridim tükendim aşkın narına

Bu gidişle Türker çıkmaz yarına

Kurşunlar sıkınca mavi gözlerin

Leylaklar açılır hayal dağımda

İştiyak zinciri gönül bağımda

Bir evet beklerim ümit çağımda

Sabrını yıkınca mavi gözlerin', 'Selvi endamında dünya bükülür Kurumuş ağaçtan meyve dökülür Yüreğim dağlanır kalbim sökülür İçimi yakınca mavi gözlerin İkindi mevsimi bahar...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavi-gozlerin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürmeyen Zamanlar', 'oldurmeyen-zamanlar-elif-kerenciler-a38os', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bugünler sabırla işlerlik kazanıyor

güven,sabır,sevgi

üç ayaklı bir sandalyenin sendelenişi tabiki sonunda

dördüncü ayak bizdik olması gereken

sen olmadın

ben senin rolünü çalmadım

ben tek başıma kaldıramadım hayatı 

şimdi gidiyorum yalnız

ne yeni filizlenmelerim var

ne ayrılığından korkmam dediğim yeni bir ruh

yaşamın tınısını duyup

sonsuza dek içime çekmek istiyorum

eşsizliğimi yaşatıyorlar bana

kendi sadeliklerinde tutarsız çevreler

dibe batmalı deseler de 

su yüzüne daha bir çıkıyorum çoşkulu

bu zamanlar insanı

hiç öldürmeyen

yaşatan büsbütün

...

27.12.2003

Cumartesi

13.38

Biga', 'bugünler sabırla işlerlik kazanıyor güven,sabır,sevgi üç ayaklı bir sandalyenin sendelenişi tabiki sonunda dördüncü ayak bizdik olması gerek...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oldurmeyen-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yalan', 'ask-yalan-turker-koluman-exupv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmişi hatırlar bu yalnız yollar

Selama duruyor kimsesiz dallar

Yağmuru sarıyor belirsiz kollar

         Tutuşur resimler maziden kalan

         Gönül yara kader kara aşk yalan

Gözleri sarsardı beni derinden

Başımda eserdi yeller serinden

Yakardı canımı her bir yerinden

         Yatışır bakışlar hülyaya salan

         Gönül yara kader kara aşk yalan

Zalimler yanardı senin çağrında

Yiğitler çürüdü ateş bağrında

Ocaklar yıkıldı sevdan uğrunda

        Satılır dünyalar ardında kalan

        Gönül yara kader kara aşk yalan

Unuttum yüzüme güldüğün günü 

Kan tuttum bahtıma geldiğin günü

Atlattım sözüme öldüğün günü

        Yosunlu taşlarda yüreği çalan

        Gönül yara kader kara aşk yalan

Allahın sevgili tek kulu bendim

Hüzün keder yoktu her zaman şendim

Dünyada birtek ben kaderi yendim

        O deli değilim acıya dalan

        Gönül yara kader kara aşk yalan

	                                     1997', 'Geçmişi hatırlar bu yalnız yollar Selama duruyor kimsesiz dallar Yağmuru sarıyor belirsiz kollar          Tutuşur resimler maziden kalan    ...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi geçen', 'neydi-gecen-hicabi-ceylan-4vxql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen gün ışığından korkarsın

Gelmez olur gece

Biz, farkına varmadan gelecektir

Mutlaka gelecektir! 

Siyahın gizemi esir alınca dünyayı

Gelmesini istediğimiz gecede

Ay’ın ışığını ararız

İçimizde ki çocuk canlanır

Korkudan mıdır bilinmez

Yalnızlığımıza çareymiş gibi,

Bir sokak lambasının ışığına

Muhtaç hissederiz kendimizi

Ama çare değildir

Korkular, derinlerde yaşattığımız

Ne olduğunu bilmediğimiz korkular

Yalnızlık korkuları,

Karşımızdadır.

Senelere göğüs germiş

Sensizliğin hasretiyle 

İçimde büyümüşte, büyümüş olan korkular

Hesap soruyor benden

Ve ben hala öldüremedim ki

İçimdeki ürkek çocuğu

Geçen zamana yenik düştü.

Saatler tik tak, tik tak atar saniyeleri

Bir şeyler geçiyordu farkında olmadan 

Aynada görünce gerçeği

Yüzümdeki derin çizgileri 

Farkına vardım 

Geçen zaman değildi

Geçen benim ömrümdü.', 'Bazen gün ışığından korkarsın Gelmez olur gece Biz, farkına varmadan gelecektir Mutlaka gelecektir!  Siyahın gizemi esir alınca dünyayı Gelm...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/neydi-gecen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenir', 'tukenir-turker-koluman-ttopr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağlar başı duman olur

Dost ararsa yari bulur

Can bedende aciz kalır

Yol bozulur han tükenir

Kimse bilmez yaram derin

Serde esmez yeller serin

Mezar kazın derin derin

Ün çözülür şan tükenir

Akar yaşım gözüm ağlar

Kör bahtıma kara bağlar

Acılarım yürek dağlar

Ten büzülür kan tükenir

Kara kaşlı nazlı dilber

Al pazarda köle gider

Bülbül feryat figan eder

Gün dizilir tan tükenir

Gül dikensiz olmaz derler

Yar bahçede solmaz derler

Seven murad almaz derler

Gül süzülür can tükenir

                                    1999', 'Dağlar başı duman olur Dost ararsa yari bulur Can bedende aciz kalır Yol bozulur han tükenir Kimse bilmez yaram derin Serde esmez yeller ser...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tukenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dicle Türküsü', 'dicle-turkusu-turker-koluman-863sg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah Allah sesleri gelmiyor surlarından

Ey Diyarbekir artık, uyan yaslı uykudan

Bir tarafın bağ dolu diğer yanda hüzün var

Dicle’nin akışında hiç gülmeyen yüzün var

Eskiden sevdalılar seni çare bilirdi

Behey Dicle! Sevdalar sende dile gelirdi

Bahtsızlık yazılıdır ikimize ezelden

Geçmek zorundayız biz iyiden ve güzelden

İki anadan doğduk aynı yara gideriz

Canı sunduk yarana kelle koltuk gideriz

Tiryaki olur senle Bismil denilen köhne

Toprağa hayat verir dünya şanına sahne

Tekbirle karşılanır sende bayram sabahı

Zalime zulmü kalmaz çıkar mazlumun ahı

Sen kıvrılan abide tarihsin bu ovada

Önünü bağlasalar tutamazlar yuvada

En güzel çiçek sensin çiçeklere su veren

Mezopotamya’da hep acı ve kahır deren

Toprağın mı bozulmuş üstüne basanın mı? 

Ondördünde civanı dağlarda asanın mı? 

Karşılık beklemeden Bismil’e aktın Dicle

Dön de bir ardına bak neler bıraktın Dicle; 

Görünmeyen bir yerden keskin bir kurşun vınlar

Asırlık surlarında yanık bir türkü çınlar; 

“Diyarbekir çarşıda vurulmuş uzanıram

  Ben bu kurşun sesini nerde olsa tanıram”

Bismil’e ateş yağdı, mermi yağdı, kan yağdı,

Güzellik hayal oldu, mutluluk göğe ağdı

Tahammülün kalmadı çok derdimi dinledin

Yeter sana bunca yıl hep ağladın inledin

Dindir artık feryadı yoldaş olsun Sakarya

Hani ayağa kalkar hani yokuş çıkarya

Dirilt ölü toprağı kanayan bu yaradan

Kaldır öksüz davayı sıkıntıda aradan

                                                        1996', 'Allah Allah sesleri gelmiyor surlarından Ey Diyarbekir artık, uyan yaslı uykudan Bir tarafın bağ dolu diğer yanda hüzün var Dicle’nin akışın...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dicle-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran1', 'hicran1-turker-koluman-ojl80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ümit peşinde geçti bir ömür

Ardına bakmadın gözleri kömür

Kırdığın kalbimi parçala sömür

Çilenin sazıdır gönlümde yaran

Bağrıma sayısız davet gönderdin

Yol bilmez garibi köze dönderdin

Bembeyaz bahtıma birden son verdin

Yakıcı sızıdır gönlümde yaran

Bir hüzün faslında düşülen çöller

Suyunda vurgunlar yediğim göller

Gençliği götürür dikenli güller 

Silinmez yazıdır gönlümde yaran

Maskeli baloda çizdiğin resim

Tarihe vurulan zalim bir isim

Sayende öğrendim yok olur cisim

Varlığın azıdır gönlümde yaran

		               1998', 'Bir ümit peşinde geçti bir ömür Ardına bakmadın gözleri kömür Kırdığın kalbimi parçala sömür Çilenin sazıdır gönlümde yaran Bağrıma sayısız ...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hicran1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Senin', 'gozlerin-senin-turker-koluman-grzgf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülünce ömrüme leylaklar açar

Kokunu etrafa mis diye saçar

Kara kışlar bile önünden kaçar

Baharsın gelmesin güzlerin senin

Konuşurken dünya durmuştu sanki

Her hecen kalbime vuruştu sanki

Her kelimen bana soruştu sanki

Baldan daha şeker sözlerin senin

Sana doğru gelir her bir atağım

Yıldızlar yorganım toprak yatağım

Engeller vız gelir olsa batağım

Pamuktan yumuşak dizlerin senin

En tatlı hayalden çok daha güzel

En sıcak anıdan çok daha özel

Yakmıştı gönlümü derinden güzel

O yosun yeşili gözlerin senin

                                           1996', 'Gülünce ömrüme leylaklar açar Kokunu etrafa mis diye saçar Kara kışlar bile önünden kaçar Baharsın gelmesin güzlerin senin Konuşurken dünya ...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerin-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Mantar)', 'dortlukler-mantar-ahmet-aksoy-6kjvd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mantar

Kalbimde mantarsın

Ara sıra kaşınan

Kaşintisi geçse de

Aslı kalan.

Kalbimde Aşkın

Bir tek sen varsan 

Neredesin aşkim? 

Bir tek sen varsan 

Ağrımdasın ağrımdasın

Balçık Denizi

Balçık balçık bu deniz

Balçık balçık

Balçık ayrılık 

Ayrılık balçık.

Seni Yaşıyorum

Daha dün buradaydın

Şimdi dün oldugun yerdeyim

Ve seni yaşiyorum

Senin olduğun yerde.

Sancı Sancı

Sancı sancı zaman

An an sancı sancı

Geçmiyor bir türlü

Yürümeyen karıncayı.', 'Mantar Kalbimde mantarsın Ara sıra kaşınan Kaşintisi geçse de Aslı kalan. Kalbimde Aşkın Bir tek sen varsan  Neredesin aşkim?  Bir tek sen v...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-mantar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-turker-koluman-m2hno', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Olmadı hiç istediğim bir zaman

Güzel garip yollar uzun el yaman

Şu gönlümün ellerinden elaman

Bıktım yine bıkıyorum birtanem

Dağlar aşıp sana geldim bilesin

Ellerinle gözlerimi silesin

Sağlık ile bitmeyecek çilesin

Ömür boyu çekiyorum birtanem

Suçun yoktur biliyorum şansımı

Tamam değil eksik etti dansımı

Her bir yere tohum tane aşkımı

Duan ile ekiyorum birtanem

Ayrılırken ağlıyordun ardımda

Sevdiğine eksik etme yardımda

Gurbetimin acısını sardımda

Hasretinle çöküyorum birtanem

Tutam tutam aklar doldu başıma

Güvendiğim zehir kattı aşıma

Söylediğim inanmıyor yaşıma

Yaprakları döküyorum birtanem

Anlıyorum çekilmeyen çileni

Bulamadım sevdamızı bileni

Kara alın yazım kadar bil beni

Şafaklarla söküyorum birtanem

Gide gele bütün yollar aşındı

Durulmayan gözlerinde yaşındı

Dayandığım senin mezar taşındı

Taştan taşa sekiyorum birtanem

Uyanırken arkasından bir düşün

Gözlerimden kaybolmuyor gülüşün

Yüreğimin yarasını bir düşün

Saçlarınla dikiyorum birtanem

Boğazıma düğümlendi hıçkırık

Gönül gamlı mahzun kalbim hep kırık

Bahtımızın ağaçları hep çürük

Hep boynumu büküyorum birtanem

                                                 1995', 'Olmadı hiç istediğim bir zaman Güzel garip yollar uzun el yaman Şu gönlümün ellerinden elaman Bıktım yine bıkıyorum birtanem Dağlar aşıp san...', ARRAY['Türk Edebiyatı','Şiir','Türker Koluman']::text[], 8.5, '{"poet":"Türker Koluman","poet_slug":"turker-koluman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/birtanem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-anil-kiraz-vwamc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz kalsamda bu şehirded

Gidip dönmeyeceğini bilsende

Bekleyeceğim

Göz yaşlarım dinmesede

Sensizlik zor gelsede

Bekleyeceğim

Ayrılık zor olsada

Sevenler kavuşmasada

Kıyamet kopsada 

Bekleyececğim

Sonu nereye varır bilmem

Üzerime beyaz elbiseler giysem 

Sensizlikten delirip gebersem

Bekleyeceğim

Sonlar hüzünle bitse

Dünya''nın sonu gelse

Yinede Bekleyeceğim...

                                                         Anıl KİRAZ', 'Sensiz kalsamda bu şehirded Gidip dönmeyeceğini bilsende Bekleyeceğim Göz yaşlarım dinmesede Sensizlik zor gelsede Bekleyeceğim Ayrılık zor ...', ARRAY['Türk Edebiyatı','Şiir','Anıl Kiraz']::text[], 8.5, '{"poet":"Anıl Kiraz","poet_slug":"anil-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bekleyecegim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-bekir-yuzer-harbb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yağmurun ardından güneş çıkıyorda

En uzun yollar bile bitiyorda

Millet ta aya çıkıyorda

Seni görmekmi bu imkansız dedikleri? 

Günde milyonkez atıyorda bu kalp

En derin çukurların bile dibi keşfediliyorda

Bir bakışta yıldızlar bile görünüyorda

Seni görmekmi bu imkansız dedikleri

En büyük aşklar bile bitiyor bak

Ne deniz nede gök baki bu dünyada

Bir nefeste kül etmiyecekmi o melek

Sana bitmeyen özlemim,sevgimmi bu imkansız dedikleri.....', 'Her yağmurun ardından güneş çıkıyorda En uzun yollar bile bitiyorda Millet ta aya çıkıyorda Seni görmekmi bu imkansız dedikleri?  Günde mily...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imkansiz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Şiir', 'geceye-siir-engin-kurtoglu-c6kam', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazı geceler

Annemin sessizce bir köşede                                      Ağladığını görürdüm

Gözyaşları yağmur olup

Dökülürdü avuçlarına

Babam ise sigarasını tüttürür

Bütün dertlerini

Bir sigara dumanı gibi

İçine çekerdi

Ben de

Bir mum ışığının aydınlattığı

Uzak bir köşede

Tükenmeyen umutların

Resmini çizerdim', 'Bazı geceler Annemin sessizce bir köşede                                      Ağladığını görürdüm Gözyaşları yağmur olup Dökülürdü avuçların...', ARRAY['Türk Edebiyatı','Şiir','Engin Kurtoğlu']::text[], 8.5, '{"poet":"Engin Kurtoğlu","poet_slug":"engin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geceye-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Hüznü', 'gecenin-huznu-engin-kurtoglu-krxn8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam olur

Suya iner ceylanlar

Gece kuşları 

Sessizce çekilirler inlerine

Ve bir gürültü kopar

Karlı dağların ardında

Bilirim

Yine bir gelincik

Alnından vurulup

Düşmüştür kanlı toprağa', 'Akşam olur Suya iner ceylanlar Gece kuşları  Sessizce çekilirler inlerine Ve bir gürültü kopar Karlı dağların ardında Bilirim Yine bir gelin...', ARRAY['Türk Edebiyatı','Şiir','Engin Kurtoğlu']::text[], 8.5, '{"poet":"Engin Kurtoğlu","poet_slug":"engin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gecenin-huznu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-bekir-yuzer-n9trj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımın can dostu

Sigaram ellerimde yine

Sensizliği içiyorum bir daha

Ölümüne bir nefes daha

Bir kez daha geçti 

Gözlerinin hayali gözlerimden

Sonra bir nefes daha hayatı bitirmek adına

Bin soluksuz günlerin ardından

Bir soluk nikotin bağımlılığında

Gözlerin geliyor zemheri düşüncelerime

Bir göz kamaşmasında kaybedişim seni

Sonra bir nefes daha

Dumanı damarlarımda hissediyorum

Tıpkı seni hisseder gibi

Kalp kapım ardına kadar açık

Zehirlesede bu duman

Ben seni içiyorum

Bir tarafın kül,bir tarafın ateş

Hayatımın azraili olsanda

Seni düşünüyorum her düş sonrasında

Sonra son bir nefes daha

Ya kültablasında biten bir özlem

Yada ayaklarımın altında

Sensizliği eziyorum

Bir sigaradan bin medet umar gibi

Her medetin ölümü biraz daha yakınlaştırdığını bile bile.........', 'Yalnızlığımın can dostu Sigaram ellerimde yine Sensizliği içiyorum bir daha Ölümüne bir nefes daha Bir kez daha geçti  Gözlerinin hayali göz...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensizlik-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice mutlu yıllara', 'nice-mutlu-yillara-bekir-yuzer-rbs6t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani deniz vardırya

Bütün doğallığıyla

Sereserpe hayata can veren

Birde gökyüzü vardırya

Hani o özgürlüklerin mavimtırak sembolü

Ve birde dünyadaki güzellikleri

Gözlerinde barındıran

Sen de varsın ya

İyiki de doğdun masmavi çağlayan

İyiki doğdun...

Nice mutlu yıllara.', 'Hani deniz vardırya Bütün doğallığıyla Sereserpe hayata can veren Birde gökyüzü vardırya Hani o özgürlüklerin mavimtırak sembolü Ve birde dü...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nice-mutlu-yillara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan', 'sevdan-engin-kurtoglu-gon5z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaz yağmuru kokuyordu ellerin

Bakışların kaçak bir ceylandı dağlarda

Saçların                                                                        

Buğday başakları kadar hür

Gülüşün 

Bir volkan patlaması

Yüzün 

Bir bahar mevsimi gibi güzel ve sıcak 

Ve

Sevdan

Bir veba gibi ölümcül

Bir çocuk yüzü kadar masum', 'Yaz yağmuru kokuyordu ellerin Bakışların kaçak bir ceylandı dağlarda Saçların                                                               ...', ARRAY['Türk Edebiyatı','Şiir','Engin Kurtoğlu']::text[], 8.5, '{"poet":"Engin Kurtoğlu","poet_slug":"engin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmedim', 'vazgecmedim-bekir-yuzer-ni1ji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sensizlikteki karanlıklara bıraktığın

O geceden beri

Hiç vazgeçmedim seni sevmekten

Gökyüzünde yıldızlar olduğu sürece

Tuttum yüreğimin ateşini avuçlarımda

Bulutlu gecelerde

Sonsuzluğa kaysınlar diye

Haberimi sana iletsinler diye

Gözyaşlarımdan yıldız yaptım

Ama hiç bir zaman pes etmedim

Sevgimden yana

Bazen sesinle avundum 

Bazen hayalinle

Bazen gözlerin oldu akdeniz

Bazen tenin koktu kokladığım çiçekler

Ama asla senden vazgeçmedim....', 'Beni sensizlikteki karanlıklara bıraktığın O geceden beri Hiç vazgeçmedim seni sevmekten Gökyüzünde yıldızlar olduğu sürece Tuttum yüreğimin...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vazgecmedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyumak', 'uyumak-bekir-yuzer-vzf0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruhumun sıkıldığı o işkence vakitlerinde

Kağıttan bir gemi yaptım

Sonra tüm benliğimi ve umutlarımı doldurdum içine

Vede büyük bir törenle indirdim

Hayatın acımasız okyanuslarına

Kalbimin zifiri zındanları

Bomboş şimdi ne bir umut nede bir gelecek

Takvimlere bakmıyorum artık

Saatlerede ve tabiki aynalara

En iyi yaptığım şey 

Galiba uyumak

Hiç bulunmamam gereken bu hayat tarzından

Uyuyarak kaçmak

Hani bahar gelirde mis gibi açarya çiçekler

Yağmur yağarda toprak sanki pasta gibi kokarya

Nefes alıyorum ama hiç kokmuyor bana

Ne toprak nede çiçekler

Her aldığım soluk sensizlik kokuyor

Sanki cehennem burnumda tütüyor....', 'Ruhumun sıkıldığı o işkence vakitlerinde Kağıttan bir gemi yaptım Sonra tüm benliğimi ve umutlarımı doldurdum içine Vede büyük bir törenle i...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uyumak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melis', 'melis-ayse-kilic-hwsjc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adi Melis''tir,

Mis kokuludur,

O bir melekdir,

Tanrinin inciye armaganidir.

Her an gülersin,

Nede güzelsin,

Nasılda büyüdün,

Hemen yürüdün,

Neler söylüyorsun,

Bak anne diyorsun,

Her an gülüyorsun,

Anneye babaya nasıl benziyorsun,

Hemen uyuyorsun,

Ne verseler yiyorsun,

Sen bir meleksin

Bu gun senin doğum günün,

Doğum günün kutlu olsun.

Her anın bu gün gibi,

Ak pak hayatın güzelliklerle yol alsın,

Sevgili küçük Melisim.

   

      (Hafize annanen)', 'Adi Melis''tir, Mis kokuludur, O bir melekdir, Tanrinin inciye armaganidir. Her an gülersin, Nede güzelsin, Nasılda büyüdün, Hemen yürüdün, N...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Kılıç']::text[], 8.5, '{"poet":"Ayşe Kılıç","poet_slug":"ayse-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/melis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Böylesin', 'neden-boylesin-burhans-kilic-kan87', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlümle eğlenip dalga geçersin,

Dilensem bir buse ölsen vermezsin,

Yalvarıp peşinden koşsam istersin,

Söyler misin canım neden böylesin.

Aşk cimrisi derler güler geçersin,

Gündüzler bir yana gece gelirsin,

Sonrada kalbimi kırar gidersin,

Söyle canım bana neden böylesin.

Seviyorum derim dudak bükersin,

Gözlerime bakıp yüz çevirirsin,

Evlenelim desem cevap varmazsin,

Söyle bana canım neden böylesin.', 'Gönlümle eğlenip dalga geçersin, Dilensem bir buse ölsen vermezsin, Yalvarıp peşinden koşsam istersin, Söyler misin canım neden böylesin. Aş...', ARRAY['Türk Edebiyatı','Şiir','Burhans Kılıç']::text[], 8.5, '{"poet":"Burhans Kılıç","poet_slug":"burhans-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neden-boylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç yazar', 'kac-yazar-bekir-yuzer-jp0so', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını anmamışım ne yazar

Kalbimde her gün ismine feryatlarım

Her dakika içimde yankılanırken

Kemiklerimde hissettiğim

Sensizlik naralarının sızlama sancısı

Acımasızlığın bilinmeyenli denklemlerini çözmeye çalışmak

Her gün bir parça kopartmak beynimden

Söylesene kaç yazar adını anmayışım

Yüzünü görmemişim ne yazar

Açtığımmı var gözlerimi

Asla perdesini açamayan bir tiyatro gibi

Kör gezişim

Göz kapaklarımda o güzel suretin

Söylesene kaç yazar yüzünü görmeyişim....', 'Adını anmamışım ne yazar Kalbimde her gün ismine feryatlarım Her dakika içimde yankılanırken Kemiklerimde hissettiğim Sensizlik naralarının ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kac-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kes Hesabımı', 'kes-hesabimi-burhans-kilic-jvxmt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aklınca sunduğun sevgi mi senin,

Güzelim kalbine hiç yakışmıyor,

Bir anlık mutluluk yanlız verdiğin,

Onun da tadına hiç varılmıyor.

Aşkın bedeli mi bu çektirdiğin,

Öyleyse hazırım kes hesabımı,

Tutmakta zorlanıp hep unuttuğun,

Sözleri bırakıp kes hesabımı.

Hayatım seninle bir rüya gibi,

Fırtınalı yaşam sardı çehremi,

Alışkın değilim diyemem sana,

Bırakma ne olur sarıl boynuma.

Gözlerim doldu bak utanıyorum,

Fazla yalvartmadan kes hesabımı,

Gururum sevgimi ezip geçmeden,

Bir öpücük verip kes hesabımı.', 'Aklınca sunduğun sevgi mi senin, Güzelim kalbine hiç yakışmıyor, Bir anlık mutluluk yanlız verdiğin, Onun da tadına hiç varılmıyor. Aşkın be...', ARRAY['Türk Edebiyatı','Şiir','Burhans Kılıç']::text[], 8.5, '{"poet":"Burhans Kılıç","poet_slug":"burhans-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kes-hesabimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece-1', 'gece-1-sirma-mersin-z8p43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz karanlığın içine çökmüş,

hüzün. Gecelere; teslim olmuşken, gözyaşları... yalnızlığın gölgesi görünmüş duvarda.Adım adım büyüyen; çaresizlik. Yastığa düşen boz bulanık hayallerle, yatağımı kaplayan soğuk, yüreğimi de üşüttü. 

Gecelerce; imzasız satırlara taşıdım, duygularımı. Belki bir gece; kaderin ördüğü  çaresizliği, şansımı kullanarak bozacağım. Kırık dökük mutluluğumu, yarım kalmış sevgimi, yeniden yaşamak için dağıtacağım, umutsuzluğumu.

Gökyüzünden düşen yıldızlardan; taç yaptım, sahipsiz gönlüme.

Karanlıktan aydınlığa dönecek, gecelerim.Elbet bir umutla; bambaşka bi yüreği sevecek, günün birinde...

25.12.03', 'Sessiz karanlığın içine çökmüş, hüzün. Gecelere; teslim olmuşken, gözyaşları... yalnızlığın gölgesi görünmüş duvarda.Adım adım büyüyen; çare...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gece-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bahçem', 'gonul-bahcem-burhans-kilic-v0w44', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gül dikeceğim gönül bahçeme,

Aşkınla besleyip bakasın diye,

Bir eşi cennette olacak bilki,

Uğruna cennete gidesin diye.

Sevginle büyüyen gül dillenmez mi,

Beni bırakıpta gitme demez mi,

Aşkımı anlatıp hep mısra mısra,

Kalbimin adına yalvaramaz mı.

Duy artık ne olur gülüm solacak,

Belki bir hiç uğruna bu can yanacak,

Bitmez gururun neler kazanacak,

Kalbini dinlemezsen çok geç olacak.', 'Bir gül dikeceğim gönül bahçeme, Aşkınla besleyip bakasın diye, Bir eşi cennette olacak bilki, Uğruna cennete gidesin diye. Sevginle büyüyen...', ARRAY['Türk Edebiyatı','Şiir','Burhans Kılıç']::text[], 8.5, '{"poet":"Burhans Kılıç","poet_slug":"burhans-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-bahcem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-bekir-yuzer-4mryl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördükten sonra oldu

Sahillere koşmalarım

İsmini mavi sulara yazmalarım

Bir dalga alıp götürene dek bakmalarım

Seni gördükten sonra oldu

Bulutlarla kavgalarım

Yüzünü çizdiğim göklere dalmalarım

Bak görüyormusun

Yüreğimden sana doğan gökkuşağını

Milyonlarca ışık yılı uzaklıktaki

Kalbinde bittiğini görmüyormusun rengarenk

Her güneş doğduğunda çalar kapını

Duymuyormusun

Sırılsıklam gezmelerim gecenin bir yarısı

Bardaktan boşalırcasına yağan gözyaşı yağmurlarım

Bin asır sabırsızca sabretmelerim

Sesinde kurmak bin hayali

Sesinle avutmak çaresiz yürekçiği

Sessizlikte boğmak sensizliği

Ve her sabah seyretmek

Doğan yalancı güneşi

Bağırlara taş basıp beklemek sahillerde

Suları yırtarak gelecek

Masmavi bir gemiyi.........', 'Seni gördükten sonra oldu Sahillere koşmalarım İsmini mavi sulara yazmalarım Bir dalga alıp götürene dek bakmalarım Seni gördükten sonra old...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gemi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-sirma-mersin-xuilr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söz değil, yemin değil! 

Sabrım bile, izin vermedi.

Seni beklememe...

Aslında; 

Dayanılmaz bir acı idi,

Seni beklemek..

Neyi? neden? 

Beklediğini bilmeden,

Günleri geçirip, zamanı doldurmak adına,

Beklemek zor olsada,

Geleceksin! bugün olmasa da,

Bekleyeceğim seni.

Sabrım izin vermese de....

25.12.03', 'Söz değil, yemin değil!  Sabrım bile, izin vermedi. Seni beklememe... Aslında;  Dayanılmaz bir acı idi, Seni beklemek.. Neyi? neden?  Bekled...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beklemek-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-sirma-mersin-sopiy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gece; aynı pencereden,

Gökyüzüne bakıyoruz.

Sen! bir başka pencereden  baksan da, aynı gökyüzüne bakıp; aynı mutluluğu diliyoruz.

Kayıp giden yıldızlardan; hep başka başka şanslara ait, dualar edip duruyoruz... karanlık da! 

Soğuk! buğusunu bırakmış cama ; adını yazmak istdğim sevgiliyi yada kalbimi çizmek için. 

Sen ne yazarsın? kendi pencerene bilmiyorum... 

Birgün; aynı pencereden bakabileceğimizi umut ediyorum.

Soğuk ve yağmur çiseliyor, olsada...

25.12.03', 'Her gece; aynı pencereden, Gökyüzüne bakıyoruz. Sen! bir başka pencereden  baksan da, aynı gökyüzüne bakıp; aynı mutluluğu diliyoruz. Kayıp ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gokyuzu-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gök', 'gok-bekir-yuzer-vomz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökte özgürce uçan bir kuş görürsünya

Parmaklıkların arasından

Onun yerine geçmek istersinya bir çırpıda

Sormazsınki mutlumudur

O vefasız gök yüzünde bir başına

Bilmezsinki yasaktır ona yere inmek

Ya bir cahil hapseder kafese

Uçmayı unutturur

Bıkıncada atıverir havaya

Gökyüzü uzak gelir

Kanatlarda pust olurya hani

Düşüverir bir kenara

Bir bakmışsın kapıverir

Nankör bir kedi

Hiç yoktan olursun kedi pisliği

Özenme sakın o masmavi göğe

Bir anda bakmışsın kabusun olur

Satıverir seni bir parça karabuluta

Özenme sakın uçmaya

Çakılırsın yere gök kılını bile kıpırdatmaz

Gök mavi,gök zalim,gök hain

Gök çok uzaklarda

Özenme sakın

Satıverir seni bir kahpe buluta...........', 'Gökte özgürce uçan bir kuş görürsünya Parmaklıkların arasından Onun yerine geçmek istersinya bir çırpıda Sormazsınki mutlumudur O vefasız gö...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Dansı', 'ates-dansi-sirma-mersin-ui74g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tenim bedenine sarıldığında; 

Ateş dansı başlar, içimde.

Çıplak omuzuma kondurduğunda; 

O sıcak öpücüğü,

Ateş dansı başlar, içimde.

Saçlarım dağılır, rüzgara doğru...

Rüzgarsa; içimdeki ateşi alevlendirir...

Sana her dokunduğumda; 

Yayılır bedenime ateş! 

Sen bendeki kıvılcımla,

Büyüyen alevsin...

26.12.03', 'Tenim bedenine sarıldığında;  Ateş dansı başlar, içimde. Çıplak omuzuma kondurduğunda;  O sıcak öpücüğü, Ateş dansı başlar, içimde. Saçlarım...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ates-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu kış', 'bu-kis-bekir-yuzer-x6qly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün resmine baktım

Tıpkı dün gibi ve ondan önceki gün gibi

Geçenlerde gördüğüm o yabancıyı saymazsan tabi

Hani o bir bakışı esirgeyen

Hani bir selamı çok gören o yabancı işte

Aylardır görmedim seni duymadım sesini

Hani ünlü bir lafın vardı ya

Deveye diken insanı.....üzen

Ondan olsa gerek seni hala çok seviyorum

Eksiksiz her akşam yıldızlara borcummuş gibi

Sana haber gönderiyorum

Önümüzde koca bir kış ve sende yoksun

Bu kış yalnız üşümek ve ıslanmayı

Öğrenmemden daha acı

Yıldızlar çok ender görünecek

Onlara borcumu ödemeden

Nasıl başımı yastığa koyarım bir düşünsene

Seni sessizce  yürek hücresinde sevmek kadar

Zor geçecek  bu kış....', 'Bu gün resmine baktım Tıpkı dün gibi ve ondan önceki gün gibi Geçenlerde gördüğüm o yabancıyı saymazsan tabi Hani o bir bakışı esirgeyen Han...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Taşla Hasbıhâl', 'kara-tasla-hasbih-l-i-brahim-bayraktar-jlb84', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ehlinin elinde yoğrulan taşlar,

Yârin cemaline set mi oldunuz?

Uzaktan uzağa yakan bakışlar,

Seven yüreğime dert mi oldunuz?

Kara toprak yastık oldu başıma, 

Ölen bir faniydi yazın taşıma,

Dolunayı muhbir takıp peşime, 

Pusuda bekleyen kurt mu oldunuz?

Yahu siz sert değil mülâyimdiniz! 

Her daim yerinizde ağırdınız,

Başımda bekleyen müdavimdiniz, 

Bana sezdirmeden sert mi oldunuz?

Dost bildim sizleri bağrıma bastım,

Elden uzaklaştım size yaklaştım,

Kendimden bilip sırrımı paylaştım,

Siz de herkes gibi fert mi oldunuz?

Yazları kızıp elimi yaktınız,

Geceleri öcü olup çıktınız,

Kalleşlik değil mi bu yaptığınız?

Şimdi utanmadan mert mi oldunuz?

Uzun zaman beklediniz yılmadan,

Belki hayaller kurdunuz bilmeden,

Secdesiz namazımı dahi kılmadan,12

Cansız bedenime yurt mu oldunuz?

27.12.2003', 'Ehlinin elinde yoğrulan taşlar, Yârin cemaline set mi oldunuz? Uzaktan uzağa yakan bakışlar, Seven yüreğime dert mi oldunuz? Kara toprak yas...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kara-tasla-hasbihal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şizofreni', 'sizofreni-bekir-yuzer-rm8kf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bulmak yitirilmiş benliklerde

Sesini yeniden duymak

O sağır gebeliğinde geçen yıllardan sonra

Susmak bin sevinç çığlığı sessizliğinde

Seni bulmak ama sevinememek

Senin olamamayamı üzülmek

Yoksa benim olamamanamı

Uçkunların kokusunda hissetmek gibi dağları

Seni hissetmek,özlemek

Ve çaresizliğin kelepçesinden

Yalnızlık melodisini çalmak

Sensizliği katletmek ve

Hüküm giymek terkedilmişliğe bir ömür boyu

Sigaranın dumanından yüzünü çizmek

Bir nefeste bulup

Atmosferde kaybetmek

Özlemlerin okyanusunda boğulmayı beklemek

En kötüsüde gelmiyeceğini bilmek

Bile bile beklemek

Hani yaşarsınya binbir umutla

Öleceğini bile bile

İşte öyle beklemek seni bir ömür boyu

Gelmiyeceğini bile bile.....', 'Seni bulmak yitirilmiş benliklerde Sesini yeniden duymak O sağır gebeliğinde geçen yıllardan sonra Susmak bin sevinç çığlığı sessizliğinde S...', ARRAY['Türk Edebiyatı','Şiir','Bekir Yüzer']::text[], 8.5, '{"poet":"Bekir Yüzer","poet_slug":"bekir-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sizofreni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-ali-kadioglu-6i361', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutun kükrediği yerde mi konakladın,

Zehrini kalbi kırık şaire mi sakladın? 

Bu yüzden mi kuşandın o mücella süsünü,

Duymadın mı ruhumun elemli öyküsünü? 

Adım adım kalbimi deliyorsun yürürken,

Yoksa saçların mıdır kalbime zakkum eken? 

Kanımı akıtırsın çöllere ılık ılık,

Denizini arıyor hülyasız kalan balık

Ne zaman gül sunarsa nergiz kokan ellerin

Mehtabında solacak ümitsiz hayallerim

O  gün karlar eriyip dağılacak dağımdan

Bir gonca melek olup yükselecek bağımdan

İşte o gün bu gözü nem yuvası şairin

Gözünde parlayacak endamın şirin şirin

Kapkaranlık geceme,seherin ışıkları

Usul usul dolacak,aşıp sarmaşıkları

Sensiz geçen günlere kahretmeye başlarım,

Tatlı bir hatıraya dönecek gözyaşlarım! ..

Hayal ülkemde varsın,var iken yok olanım,

Narin,kırılgan,güzel; gözümde tek olanım! ..', 'Bulutun kükrediği yerde mi konakladın, Zehrini kalbi kırık şaire mi sakladın?  Bu yüzden mi kuşandın o mücella süsünü, Duymadın mı ruhumun e...', ARRAY['Türk Edebiyatı','Şiir','Ali Kadıoğlu']::text[], 8.5, '{"poet":"Ali Kadıoğlu","poet_slug":"ali-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayal-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal,ateş ve kül benim,Benim adım...', 'dal-ates-ve-kul-benim-benim-adim-sair-ahrazi-3anju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel can dostum ayrılıktan dem vurma,

Yaren desen,yaren benim içimde.

Şaşkın gibi gidip gelip gün sorma,

Mühlet desen,yarın benim içimde.

                   *  *  *

Nice sofra kurdum,nice aşım var,

Türlü canda türlü türlü işim var,

Ne bir benzeyenim nede eşim var,

Yoğum desen,varın benim içimde.

                   *  *  *

Zamansızlık ilinde bir dereyim,

Mana gözüyle bakanda hareyim,

Aslını arayan gönle çareyim,

Sözüm desen,sorun benim içimde.

                   *  *  *

Hem rehberim hem de rehbere yoldaş,

Hem diriyim hem de makbere yoldaş,

Gah haberim gahı habere yoldaş,

Tek,im desen,sürün benim içimde.

                   *  *  *

Susamış suya su veren elimdir,

Dervişin cennet dediği çulumdur,

Harın çıngısına sebep külümdür,

Dindim desen,narın benim içimde.

                   *  *  *

Mevla’m için cihan cihan gezerim,

Her gönüle ‘’GEL’’emrini yazarım,

Ruhtan ruha bakıp duran nazarım,

Körüm desen,ferin benim içimde.

                   *  *  *

Benim adım AŞK’tır ahrazi değil,

Bu kelamda bir kalem izi değil,

Akit onun diline razı değil,

Yalan desen,doğrun benim içimde.', 'Gel can dostum ayrılıktan dem vurma, Yaren desen,yaren benim içimde. Şaşkın gibi gidip gelip gün sorma, Mühlet desen,yarın benim içimde.    ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dal-ates-ve-kul-benim-benim-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susadıkça', 'susadikca-ozkan-ozdogan-ximex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece su içmeye kalkarım diye

bir bardak duruyor

yatağın başında...

Şiir yazmaya kalkışırım

diye de

resmini koyuyorum

bardağın yanına...

Susadıkça artık

seni düşünüyorum', 'Gece su içmeye kalkarım diye bir bardak duruyor yatağın başında... Şiir yazmaya kalkışırım diye de resmini koyuyorum bardağın yanına... Susa...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/susadikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada sevgi var mı?', 'dunyada-sevgi-var-mi-timur-berk-oxugg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyada sevgi var mı? 

Dünyada sevgi var mı? 

Neden karşıma çıkmıyor? 

Korkak sevgi! 

Kaçıyorsun benden

Çık karşıma hesaplaşalım! 

En büyük sevgi benim! 

İstersen senle yarışalım.

(Tatarca) 

Dünyada süygü bar mı? 

Dünyada süygü bar mı? 

Neden qarşıma çıqmay? 

Qorqaq süygü! 

Qaçasın menden

Çıq qarşıma esaplaşayıq! 

En büyük süygü menmen! 

İstersen senmen yarışayıq.

01.12.2003', 'Dünyada sevgi var mı?  Dünyada sevgi var mı?  Neden karşıma çıkmıyor?  Korkak sevgi!  Kaçıyorsun benden Çık karşıma hesaplaşalım!  En büyük ...', ARRAY['Türk Edebiyatı','Şiir','Timur Berk']::text[], 8.5, '{"poet":"Timur Berk","poet_slug":"timur-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunyada-sevgi-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Farkımız)', 'dortlukler-farkimiz-ahmet-aksoy-a3jr1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farkımız

İki penguen kadardı farkımız

Bizi bizden ayıran aklımız.

Bizi bizden ayıran yüreğimiz.

Biz penguenler, insanlarız.

Her Gece

Göz yaşlariyla gelen ölüm

Göz yaşlariyla dogan çocuk

Bekle yine gün doğuyor

Bekle ölüler ölüp diriler diriliyor.

Kaçıncı

Bu kaçıncı beni sokan yılan

Bu kaçıncı yüzüme gülen çıyan

Hep yer yılan çıyan olmamalı

Bu yeşillikte, menekşe de gül de olmali.

Macera

At ister eşek ister

Oraya buraya gitmek para ister

Maceracı olmak yetmez

Yol, yordam para ister.

Bırak Gelsin

Bırak, dökülsün yapraklar

Bırak gelsin son bahar

Gönlün çiçek değil mi

Her son baharın ilk baharı var.', 'Farkımız İki penguen kadardı farkımız Bizi bizden ayıran aklımız. Bizi bizden ayıran yüreğimiz. Biz penguenler, insanlarız. Her Gece Göz yaş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-farkimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-osman-nalbant-ej0x1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güvendim yine bir mavi gözlüye

Gördüm ki değil keramet gözlerde

Yürek gerek gerçek sevgiye

Aldandım yine o güzel gözlere

Onlara bakmadan lazım düşünmek

Ne akıl kalıyor ne mantık içimde

Önce test etmek gerek herkesi

Tanrı misali defter tutmak

Zorlanmalı haketmek için seni

Şimdi kaldı içimde bir acı

Karıştı kanıma, kapladı vücudumu

Titriyor vicudum anarken onu

Şaşarım körlüğüme,açgözlülüğüme

O gözler ki kör etti beni

O gözler ki saldı içime zehiri

Yine sadece bana kaldı acı

Neden guvendim ki tekrar uzun saçlıya

Vermiştim zamanında kararımı

Hesap etmiştim kimse hak etmiyor diye

O gözler ki zayıflattı beni

Saldı yavaşça zehiri,uyuttu,ölduru beni

Kader verdi yine dersini

Gördüm bu dünyanın tersini

Tersten bakmak acı geldi

Ölmek daha acı olsa gerek.', 'Güvendim yine bir mavi gözlüye Gördüm ki değil keramet gözlerde Yürek gerek gerçek sevgiye Aldandım yine o güzel gözlere Onlara bakmadan laz...', ARRAY['Türk Edebiyatı','Şiir','Osman Nalbant']::text[], 8.5, '{"poet":"Osman Nalbant","poet_slug":"osman-nalbant","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aci-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yıl daha', 'bir-yil-daha-sirma-mersin-xik4f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırık dökük hayallerimle, bir yıllı daha bitirmek üzereyim. Umudumu boşa tüketerek, gözyaşlarımı ziyan etmiş, bir halde bekleyip durmuşum! 

kalbime girecek; sevgimle büyüyecek özlemi unutturacak, bir başka yüreği bulamadım...

Hayat; geriye doğru saymaya başladı. Merdivenleri tersten inmeye, dibe vuran sevinçlerden soyunarak başladım.

İmzasız küçük mutluluklar; günübirlik yalnızlığımı, avuturken.

Sahte sözlerle aldanışım! Benliğimin içindeki dünyada; yalancı bakışlarla hayallere dalmışım.

Sayfalara yazmaktan; seni sensizliği yaşarken doldurduğum satırlarda, hep bitirdim umudumu.

Arka sokaklarda; karanlığın içine sinmiş, duygularımda boş yüreğimin gölgesi görünür. 

Bir yıl daha bitiyor, ve kaybolan sevgi gelmek bilmiyor.

Uykusuz geçen gece nöbetlerinde; sessizliğime sığınan anılarımla, teselli edip, dururum yüreğimi! 

Ağlanacak hale düşmeden; ağlarım, çaresizliğime. Gün doğmadan; yarım kalan bir başka sevinci görmeden, gitmek buralardan...

Dokunur; ruhumu bulamadan, dahası eşruhumu bulmadan...

Hüznü sarıp, yüreğime! Belirsiz bir adrese dönüşü olmayan bir yolculuk  yaparsam, düşünürüm.

Uçurumun kenarında iken; beni kurtaracak şansı düşünürüm.

Kader! oyun oynamazsa; gelecektir, yanıma. Bir yabancı selamı ile; kabuslardan  uyanıp, hayatta yeni doğmuş bir bebek gülümseyip, büyüyeceğim zamanla...

Sevginin şefkatli kollarında.

27.12.03', 'Kırık dökük hayallerimle, bir yıllı daha bitirmek üzereyim. Umudumu boşa tüketerek, gözyaşlarımı ziyan etmiş, bir halde bekleyip durmuşum!  ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yil-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-osman-nalbant-2dn3i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece seni gördum rüyamda

Elimde sıkıca tutuyordum seni

Sana kimse dokunmasın, bakmasın istedim

Sadece benim ol istedim

Kıskandım seni rüzgardan

Kıskandım seni tenine deyen güneşten

Kıskandım seni o muhteşem yazdan 

Kalbimi kendine hapseden

Kıskandım seni kendi gözlerimden

İşte öyle sabaha kadar 

Affet beni seni rüyamba gördüğüm için

Affet beni seni kıskandığım için 

Affet beni, uyandır uykumdan

Dokun bana, ölmemem icin', 'Dün gece seni gördum rüyamda Elimde sıkıca tutuyordum seni Sana kimse dokunmasın, bakmasın istedim Sadece benim ol istedim Kıskandım seni rü...', ARRAY['Türk Edebiyatı','Şiir','Osman Nalbant']::text[], 8.5, '{"poet":"Osman Nalbant","poet_slug":"osman-nalbant","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruya-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalıver Gönlümde', 'kaliver-gonlumde-engin-namli-6wc1r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bahara erdiren bir gül gibi,yar

Açıver gönlümde bir ömür boyu

Bir gonca sevgiyle ölene kadar

Kalıver gönlümde bir ömür boyu

Beyaz beyaz açan ey narin çiçek; 

Sığın avucuma soluncaya dek 

Bu dünya döndükçe kokun tütecek

Tütüver gönlümde bir ömür boyu

İçten fethettiğin zaten bir gerçek

Yoksam varlığını kim farkedecek

Nasılsa seninle hayat bitecek

Kalıver gönlümde bir ömür boyu

22:02 24.12.2003', 'Bahara erdiren bir gül gibi,yar Açıver gönlümde bir ömür boyu Bir gonca sevgiyle ölene kadar Kalıver gönlümde bir ömür boyu Beyaz beyaz açan...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaliver-gonlumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En', 'en-olcay-kose-yuwtb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'en çok seni ben sevdim

en çok ben seni

en çok ben 

bizi

sevdim', 'en çok seni ben sevdim en çok ben seni en çok ben  bizi sevdim...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/en-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanamam', 'i-nanamam-kader-budur-96ipm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bir geziyorum gönlümün boş sokaklarında

İzler takılıyor ayağıma ama düşmüyorum

Devam ediyorum yürümeye seni bulmaya

Çıkacaksın karşıma biliyorum

Kısa bir çıkmaz sokakta

Ben seni bulana kadar

Yorulmayacağım bu dünyada

Tek amaç sen olmuşsun

Yemin etmişim seni bulmaya

Ama bazen bir şüphe kemiriyor kalbimi

Sanki boşuna uğraşıyormuşum gibi

Bir hayalsin sen ya yaşamıyorsan

Ben ömrümü unutacağım senin uğruna

Ama yoksa böyle bir sevgili dünyada

Korkup dualar ediyorum seni bulmaya

En azından var olmanı istiyorum ki

Devam etmeliyim ömrümün sonuns kadar

Azimle seni aramaya

Bak bu gürültüler içinde yanlızım

Gözlerim ruhum seni arıyor

Görmüyor doğa ananın çoçuklarını

Korkuyorum boşuna bunları yaşamayı

Eğer varsan başaracağım seni bulmayı

Eğer yoksan küseceğim

Eğer yoksan inanamam Kader''e

Kaderimdeki alın yazısına

İnanamam hiçbir şeye', 'Bir bir geziyorum gönlümün boş sokaklarında İzler takılıyor ayağıma ama düşmüyorum Devam ediyorum yürümeye seni bulmaya Çıkacaksın karşıma b...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/inanamam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiştik Biz', 'sevmistik-biz-tabir-gokce-b0uth', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir beyaz gölge arkanda kalan

güneşin gözyaşlarıyla yıkadığın

oysa sen

saçlarında sarısını

dudaklarında kızılını

saklardın

o mavi derinliklerde yitik bahardı

iksirini hücrelerimde özümsediğim

oysa ben

uyanışını bedenimde

sevgisini can evimde

saklardım

en siyah aşklara serdik yüreğimizi

gecelerin derinliklerinden çaldığımız

oysa biz

sevgimizde saman yolunu

yüreğimizde kayan yıldızlarını

saklardık

oysa biz tanrıya inat sevmiştik

oysa biz sevdaya yemin etmiştik

oysa biz 

oysa

biz

bi

z', 'bir beyaz gölge arkanda kalan güneşin gözyaşlarıyla yıkadığın oysa sen saçlarında sarısını dudaklarında kızılını saklardın o mavi derinlikle...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevmistik-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığınız sevdaya ulaşılamıyor', 'aradiginiz-sevdaya-ulasilamiyor-olcay-kose-6f9jh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sessize aldım yalnızlığımı

gelen çağrıları yokluğuna yönlendirdim

bu uğraş beni çok yordu

sevgili

sekreter artık konuşmuyor

inat etti susuyor

yeni bir ses

küfür gibi algılayınız

aradığınız sevdaya ulaşılamıyor

lütfen birdaha aramayınız.......', 'sessize aldım yalnızlığımı gelen çağrıları yokluğuna yönlendirdim bu uğraş beni çok yordu sevgili sekreter artık konuşmuyor inat etti susuyo...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aradiginiz-sevdaya-ulasilamiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Ağlamak Geliyor İçinden', 'niye-aglamak-geliyor-i-cinden-kader-budur-wqvo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Niye ağlamak geliyor içinden 

Sen istemedinmi yaşamayı bu boş evde

Dökülen ilk damla

Yaptıklarının azabı değilmi

Dudakların titrer gözlerin takılır boşluğa

Ağlamak gelir içinden ağlayamazsın ya

İşte sensin sebep bu acılara

Şimdi çektirdiklerinin bedelini ödüyorsun

Oturmuş bu boş evi bekliyorsun

Duvarlar üstüne geliyor 

Ama sen ağlıyamıyorsun

Niye ağlamak geliyor içinden

Kötülükle bakmadımı gözlerin derinden

Nefretinle yaşamadınmı bunca zaman 

Düşünmedin iyiyi güzeli sevginden

Hep bir sindirememezlik var yüreğinde

Kabul edemiyorsun elinden başkasına uçup gitmesine

Niye ağlamak geliyor içinden

Nefretle kinle büyümedinmi bu evde

Niye ağlamak geliyor içinden

Hadi ağla ağlayabilirsen

Nefes al bu evde alabilirsen

Dokunsan duvarlara ne görecek gözlerin

Her an aklında kavgalar döğüşler

Seven insan gururunamı sarılır üzülürken

Sen sevgi dolu ellere sarılacakken

Kine nefrete sarıldın düşünmeden

Niye ağlamak geliyor içinden

Hadi ağlada görelim sevginden

Hadi ağlada bilelim 

Bu ağlamak nefretinden

Niye ağlamak geliyor içinden 

Yanlızlığa sarıldın düşünmeden

Önceden güçlüydün tutan istemedin ellerinden

Şimdi suratında çizgiler

Gözlerinde yaşlı bir kadının izleri

Hadi sarıl nefretine yeniden

Hala bu kadar güçlümü yüreğin

Hala bu kadar ateşlimi sevgin

Biliyorsun bu sevgi tükenmez yüreğinden

Bir ömür seni canlı tutar nefretinden

Bedelinde bir ömür yanlızlıktan

Çekeceksin kurtuluşun yok

Bu senin kendi Kader''in ellerinden', 'Niye ağlamak geliyor içinden  Sen istemedinmi yaşamayı bu boş evde Dökülen ilk damla Yaptıklarının azabı değilmi Dudakların titrer gözlerin ...', ARRAY['Türk Edebiyatı','Şiir','Kader Budur']::text[], 8.5, '{"poet":"Kader Budur","poet_slug":"kader-budur","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/niye-aglamak-geliyor-icinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-olcay-kose-ma9kr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gece çöktü yine

hadi git

zaten dönmemiştin geriye

hiç', 'gece çöktü yine hadi git zaten dönmemiştin geriye hiç...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hic-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kana gibi', 'kana-gibi-olcay-kose-67917', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adını kurşunlarla yazdım

kalbime

kan kokuyor buram buram

o pozitif aşkına ihtiyaç

var

gel 

kan kaybından

ölmeden sevdan', 'adını kurşunlarla yazdım kalbime kan kokuyor buram buram o pozitif aşkına ihtiyaç var gel  kan kaybından ölmeden sevdan...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kana-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafer', 'zafer-olcay-kose-yich1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kahramanca savaşıyorum 

sevdanla

o vurdukça sillesini

ben doğruluyorum

zafer yakın

sınırına yaklaştım

kazanacağım

bu aşkı

biliyorum', 'kahramanca savaşıyorum  sevdanla o vurdukça sillesini ben doğruluyorum zafer yakın sınırına yaklaştım kazanacağım bu aşkı biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zafer-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Gölgeye)', 'dortlukler-golgeye-ahmet-aksoy-zoz64', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgeye

Karanlıktaki ışık

Işiktaki gölge

Bir şeyler anlatmaksa

Dileğin, açık söyle.

Bebek

Bebeğin ağlayışındaki giz

Ağlatacak kadar acı mıdır? 

Yoksa bizim bilmediğimiz, dünyaya 

Gelmenin, mutluluk göz yaşlari midir? 

Yarım Yırtık

Olmakla olmamak arasındaydı

Her şey, olmuşta olmamışlık

Olmamışta olmuşluk

Yarım yırtık.

Umut Bahardır

Kuşlar civildiyor canim kuşlar

Kuşlar civildiyor cik cik cak cak

Kızgınlık yok seslerinde mutluluk var

Bahar sabahı bu canım bahar.

Nerede Bitecekse

Bitmesin ne olur

Bitmesin mutluluk

Bitecekse neye yarar

Bitecekse, nerede mutluluk.', 'Gölgeye Karanlıktaki ışık Işiktaki gölge Bir şeyler anlatmaksa Dileğin, açık söyle. Bebek Bebeğin ağlayışındaki giz Ağlatacak kadar acı mıdı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-golgeye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Sıran Geldi Artık)', 'dortlukler-siran-geldi-artik-ahmet-aksoy-vb6wm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıran Geldi Artık

Sıran geldi artık

Gideceksin şafakta yola koyularak

Gittiğin son gittiğin yer olacak

Gece uzun sevdiklerine iyi bak.

Hasret

Ruhun dikenli tele takılmış

Uçamaz uzaklara

Bedenin tel olmuş diken olmuş

Ruhun uçamaz uzaklara.

Korkuluklar

Korkuluklar çıkmış 

Korkutmaya kargaları

Kargalar kaçmış 

Ben kalmış.

Devletin Malı Deniz

Çatal ister yemek kaşik ister

Oraya buraya uzanacak kol ister

Hepsinden önemlisi

Yetim dul hakkı yiyecek yürek ister.

Şükür

Şükretmek ne güzel

Şükretmeye deger tek bir Allah''a

Tek olanın verdikleri için

Tek olan için, Tek olana Şükür.', 'Sıran Geldi Artık Sıran geldi artık Gideceksin şafakta yola koyularak Gittiğin son gittiğin yer olacak Gece uzun sevdiklerine iyi bak. Hasre...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-siran-geldi-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelenler Gibi', 'kardelenler-gibi-sadik-softa-heeao', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kardelenler gibi, savaştım durdum,

Ömrümde fırtına, bora ve karla.

Çırpına çırpına akan sel oldum,

Dünler bugün oldu, birden yoruldum.

Hep bağrımda derin izler açıldı.

Ömrüm baharına karlar saçıldı.

Bazen kovalandı, bazen kaçıldı,

Her sevinçte keder ile vuruldum

Kuru, gazel olmuş, güllere döndüm,

Bağrım yaralandı, yellere döndüm,

Baharlarda azan sellere döndüm,

Coskun seldim, zaman geldi duruldum

Hep zemheri, hep ayazda kışladım.

Istıraba, çileleri aşladım.

Yaz-bahar görmeden, kışa başladım,

Ömür boyu dertten derde sürüldüm.', 'Kardelenler gibi, savaştım durdum, Ömrümde fırtına, bora ve karla. Çırpına çırpına akan sel oldum, Dünler bugün oldu, birden yoruldum. Hep b...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kardelenler-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Sokaklar', 'kimsesiz-sokaklar-sair-abdulask-azcww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine kimsesiz sokaklarda..........', 'yine kimsesiz sokaklarda.............', ARRAY['Türk Edebiyatı','Şiir','Şair Abdulaşk']::text[], 8.5, '{"poet":"Şair Abdulaşk","poet_slug":"sair-abdulask","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kimsesiz-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başıboş sokaklar', 'basibos-sokaklar-sair-abdulask-9xj1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yine kimsesiz sokaklarda,

son sigaramı da yaktım yüregimle.

umutsuzluk bedenimde,

bir hıçkırık bogazımda dügümlendi.

sensizlige lanet edercesine yürüdüm,

başıboş sokaklarda.  destek', 'yine kimsesiz sokaklarda, son sigaramı da yaktım yüregimle. umutsuzluk bedenimde, bir hıçkırık bogazımda dügümlendi. sensizlige lanet ederce...', ARRAY['Türk Edebiyatı','Şiir','Şair Abdulaşk']::text[], 8.5, '{"poet":"Şair Abdulaşk","poet_slug":"sair-abdulask","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/basibos-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cankurtaran', 'cankurtaran-nazife-abayli-iyaop', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğundan kalbimin,

Titrediği bir gece yine,

Düşler yaptım gözlerinden,

Şeker pembesi,

Gülücükler koydum içine,

Sensizliğin kalemi ile,

Hayalini çizdim gökyüzüne,

Avundum.

Düşlerimin gecesine ışık saçan,

Yıldızlar yaptım,

Gözlerindeki büyüden.

Fakat....

Kalbimin katiliydi zaman,

Sevginse,

Zamana meydan okuyan,

Cankurtaran.', 'Yokluğundan kalbimin, Titrediği bir gece yine, Düşler yaptım gözlerinden, Şeker pembesi, Gülücükler koydum içine, Sensizliğin kalemi ile, Ha...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cankurtaran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkındasın ya...', 'farkindasin-ya-nazife-abayli-dnh9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musun birtanem? 

Yirmiyedi Aralık bugün.

Ve saat on yediye geliyor.

Sesini duymayalı,

Neredeyse,

Kırk sekiz saat olacak.

Olsun....

Sana olan özlemimin,

Farkındasın ya......', 'Biliyor musun birtanem?  Yirmiyedi Aralık bugün. Ve saat on yediye geliyor. Sesini duymayalı, Neredeyse, Kırk sekiz saat olacak. Olsun.... S...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/farkindasin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hAyAt kOmEdYaSı :)) Sunar: trendy diye bi şey..?', 'hayat-komedyasi-sunar-trendy-diye-bi-sey-ahmet-kose-owr4v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baktık,kaldık öylecene

bir adım önümüzü görmeyerek

uğursuz bir cin sopasının sisleri kalktığında

yeşil takımlı dimdik duranları belledik.

El kaldırdık,indirdik

baş kaldıramadık,hep eğdik.

Evet dedik budur doğrusu..! 

karşılıksız teslim ettik  beyinlerimizi.

Kutular açıldı,işte budur hayat..! 

emir kipli,susturuculu ve maskeli...! 

Dürtüldük; 

en ticaretinden

açıl kasam açıl! 

saçıl efendim saçıl! 

kaçıl enayim kaçıl! 

sen mi aldın bu toprakları! 

Coşturulduk; 

en psiko-damarından

sensin en canavar! 

sensin en ölümsüz! 

sensin en bilen! 

sensin en en! koçum! 

çekil önümüzden kuvayi milliyeli şey! 

Doldurulduk; 

en dolmuşundan bindik! 

en adaletinden kandık! 

en uygarından aldandık! 

olurmuyduk en babalarsız biz! 

bilmezsin sen onun kucağını şaşkın şey! 

Gazlandık; 

en reytinginden vizyonlara

sırt çevirirken mahallemize,

en model sapığından bakışlara

aşkı gömdük topuğumuzun altına,

en duyarsızından flash sarılmalara

yüreğin içine incir ağacı diktik.

Dondurulduk; 

en ağırından hareketlerimizde hayatımızın

ne gerek var! uzatma elini düşsün! 

en sessizinden direniş komedyasında

konuşma! yoksa sıra sana gelecek mumlarında

en veriminden düşünürken okul sıralarında

önündeki hititçe mi! cafe yapın kitapçıları..! 

İletiştik; 

en sanalından *çetir çetir! 

en desibelinden yürek baytlarında! 

dil nerede  duyan yok..! 

beden nerede bilen yok..! 

yürek nerede soran yok..! 

en kısasından dijital geyik sohbetlerinde! 

şekil yap aşkını,yorma çeneni güzelim sende..! 

en trendy gel bana,sana hayatım diyebilmem için Hande..! 

**Sıchtyk Topyekün; 

en depreminde sallanırken..? 

atlamadık hırsızlığı hazırsızlığı yakalamışken,

en bölünmez bir bütünlüğünde milli rüzgarların? 

serçe gibi düşerken sapan taşlarında memetkuşların,

en yüzer gezer iradesinde millinin? 

tombala vazgeçilmez oldu,yap-boz modelinde istikbalim,

en globalinden gardaşlık kandırmacaların? 

yoldaş bile dinlemedik  aynı kavağın suyunu içerken,

en paritesinden kara gün birikintilerinde? 

trendy çığlıklar atılırken bir lokmaya.

Soytarılaştık; 

en maskaralığında ilişkilerin

en öğürtülerinde konuşmaların

en hafifinde hayatın.

...Ve baktık kaldık öylecene

bir peri sopasının beklentisinde

ararken HAYYATIMIZI..! 

...O başka bir alemde farkında değil

değişti adı haberi yok..! 

dolaşıyor trendy...trendy...! ? 

*sanal alemde karşılıklı yazışmanın şair tarafından,ironik ve hicivsel anlamlaştırılması.

**sindirim sisteminin bozulup,görevli vücut organlarının istenilen görevi tam yapamama durumunun,şair tarafından ingilizce okunuş tekniği ile ironik bir şekile dönüştürülmesidir.

27/12/03/BİTEZ', 'Baktık,kaldık öylecene bir adım önümüzü görmeyerek uğursuz bir cin sopasının sisleri kalktığında yeşil takımlı dimdik duranları belledik. El...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/hayat-komedyasi-sunar-trendy-diye-bi-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çifte yangın', 'cifte-yangin-ferit-teksoy-cs9p3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece çok sıcaktı,uyuyamadım

Yıldızlara baktım..

İkimizin olsun diye,iki tane bulacaktım

Bulamadım..

Bazısını beğenmedim,kimine isim koyamadım

İkisi bizimdi işte,kararımı verdim

***

Sabah koşuyorken,hat boyunda

Ağaçlara seviyor-sevmiyor yaptım

Hoşuma gitti sonuç,seviyorda kaldım

Akşama doğru seni aradım,bulamadım

Tekrar aradım,buldum

İstediğim gibi konuşamadım

***

Yine mahsunlaştım

Üçüncü gündü bugün

Senden ayrı ve özlemli

Ve senden uzak

Yoksun..yangın bir

Hava sıcak..yangın iki

Söyle gülüm..

Çifte yangınla ben; 

Ne yapacağım şimdi? ..

27 Temmuz 2000', 'Dün gece çok sıcaktı,uyuyamadım Yıldızlara baktım.. İkimizin olsun diye,iki tane bulacaktım Bulamadım.. Bazısını beğenmedim,kimine isim koya...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cifte-yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Kedisinin Hayali', 'sokak-kedisinin-hayali-ali-osman-yilmaz-nqg7m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dişi kediyle,

Bir parça ciğer,

Olsaydı yanımda,

Başka bir şeyde istemem,

Diye düşünüyorken,

Sen tut ciğercinin kedisine,

Sokak kedisi olduğunu düşünmeden,

Aptalca aşık oluver.

Sokak kedisi olarak,

Ciğercinin önünde beklerken,

Soğuktan büzülmüş titreyerek,

O ise ciğercinin koltuğuna kurulmuş,

Parlayan tüylerini yalamakta,

Arada dışarı göz atıp,

Eliyle burnunu kaşımakta,

Kurum kurum kurunarak,

Utanmadan nanik yapmakta.

İçerisi sıcacık,gelen okşar,

Çıkanlar başını kaşır,

Dışarısıysa buz gibi soğuk,

Gelenler tekme atarken,

Çıkanlar kovalamakta,

Ahmak bir sokak kedisi olarak,

Çöp tenekeleri dururken,

Gel ciğercinin önüne sen,

Yetmezmiş gibi bir de,

Ciğercinin kürkler içindeki,

Dişi kedisine aşık ol,

Hemde haddini bilmeden.', 'Bir dişi kediyle, Bir parça ciğer, Olsaydı yanımda, Başka bir şeyde istemem, Diye düşünüyorken, Sen tut ciğercinin kedisine, Sokak kedisi ol...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sokak-kedisinin-hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıldın', 'yanildin-nedim-saatcioglu-nucyr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçeklerin gözü vardı gözünde

Hazan düştü dallarına kırıldın

Bu güzellik bende varken yıllarca

Unutulmam sanıyordun yanıldın

Kervan yürür izi kalmaz çöllerde

Dalgaların sözü geçmez göllerde

Leyla gibi asırlarca dillerde

Dolaşırım sanıyordun yanıldın

Hiç kimseyi beğenmedin ömründe

Sevda gülü barınmadı gönlünde

Kör aşıklar eğildiler önünde

Sevdalanmam sanıyordun yanıldın

Bahar sende miadını doldurdu

Kara kışlar gül tenini soldurdu

Göz yaşların damla değil yağmurdu

Ağlayamam sanıyordun yanıldın

Yanıldın iki gözüm

Yanıldın yosun gözlüm

Hazan düştü dalına

Kırıldın beyaz gülüm

========================================== 

Beste ; Bilge Özgen

Albüm ; Belgin Gök', 'Çiçeklerin gözü vardı gözünde Hazan düştü dallarına kırıldın Bu güzellik bende varken yıllarca Unutulmam sanıyordun yanıldın Kervan yürür iz...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yanildin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anın Öyküsü Bu ( serbest )', 'bir-anin-oykusu-bu-serbest-nedim-saatcioglu-g8i12', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir anın öyküsü bu

Aslında bir anın öyküsü bu

Bazen yan yana bazen ayrı anlamlarda

                                          ama dudaklarda

Öyle yumuşak,öyle soğuk ve öylesine ıslak

Kuralsız bir zamanda

Genç bir adam orta boylu

Adam akıllı sarhoştu

Bir düş getirdi geceme avuçlarıma bıraktı

Hayal bile etmemiştim bu anı

Ne camlarda perde vardı ne de yerde bir halı

Üstelik her yer darmadağınıktı

Oysa yüreğimi bir dizine mum ışığında yakmadan az önce

Bir darağacı kurmuştum dışarıda 

                              ve asmıştım hayallerimin suç ortağını 

                                       yasak uykularda haram düşler görmesin diye

Satenden kaygan,geceden armağan

                            ve bir nehrin akışı kadar olağan

En büyük mucizeydi bu an

                        ve yüreğime en büyük lütuftu Tanrı’dan

Yaşamak istedim doyasıya bir anın coşkusuyla

Ama içerde iki insan yerde cam kırıkları

Beyazlıklar dağıtmıştı odadaki eşyaları

Ve ben yarı çıplak bir tende kendimi buluyordum

Dışarıda ezan sesleri duyuluyordu

Bir anın öyküsü içime akıyordu

Ve elimden hiçbir şey gelmiyordu', 'Bir anın öyküsü bu Aslında bir anın öyküsü bu Bazen yan yana bazen ayrı anlamlarda                                           ama dudaklarda ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-anin-oykusu-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deh Eşeğim Deh', 'deh-esegim-deh-ali-osman-yilmaz-okw4d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi taşırdım önceleri,

Tüm insanlara birer birer,

Şimdilerde ise,

Kahır taşıyan eşeğim ben,

Yuların ucu Madam’ın elinde,

Yada puştun birinde,

Habire bağırmakta bana,

Deh eşeğim deh diyerek,

Arada sırtıma sopasını,

Acımadan indirmekte,

Ardından deh ulan deh diyerek,

Yetmezmiş gibi sırtımda ki,

Kahır dolu sevda yükleri.

Yokuş yukarı tırmanırım hep,

İçim acır yorgunluktan,

Susarım kan ter içindeyim,

Bir yudum su versin diye,

Ha bire Türkü çağırmadayım.

Anlamaz,keyf çatar sırtımda,

Ah serde eşeklik olmasa,

Yapacağımı bilirdim amma? 

Sorsan ona kendini,

İyi bir insan sanmakta,

Ama ne o bir insandır,

Nede ben bir hayvanım,

Ben bir eşeğim biliyorum,

O ne olduğunu biliyormu acaba? 

Arada sesleniyor yoruldukça bana,

Deh eşeğim deh,yürüsene diye,

Bense kahır içinde bir eşek,

Kendi kendime söylenerek,

Ah Ulan eşek ah diyerek,

Ah bir insan olaydım ben,

Nasılda iyi davranırdım,

Bütün hayvanlara ve insanlara,

Diye hayıflanırım.', 'Sevgi taşırdım önceleri, Tüm insanlara birer birer, Şimdilerde ise, Kahır taşıyan eşeğim ben, Yuların ucu Madam’ın elinde, Yada puştun birin...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/deh-esegim-deh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Perde Aralığı ( serbest )', 'beyaz-perde-araligi-serbest-nedim-saatcioglu-4qxcg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın beyaz perde aralığından seyrederdim sokağı

Karanlık ve bir o kadar kimsesizdi yapraklar

Geceler en uzun çöl sıcağı

Geceler en uzun mesafedir yaşayana

                                               ağaçlar anlamazlar

Sokaktan yüzlerce insan yürürdü

Onlarcası beni görürdü

Her adımda başka bir intihar çürürdü gözlerimde

Gözlerim gün mavisi

Bilemezdim hayallerimin ortağı acaba hangisi

En unutulmaz anlar gelirdi aklıma sonra

En mahcup dakikalar 

Unutamam…

Onsekiz yaş çığlığı düşmüştü yastığıma

Ve en bakir anlar kırmızıydı yatağımda

Sonrası…sonrası bir mutluluk yolculuğuydu dudağımda

Şimdi tüm zamanlar yitik

Dünün gerçekleri artık mutlu birer anı benim için

Olsun hayat bu

Yaşanan tebessümler hüzünleri gölgeler

Giden gider kalan kalır

İnsan nefes aldığı sürece umutlara yakındır

Mutluluğun beyaz perde aralığı

Bazen gizleyemez karanlığı

Hayallerdir o an insanı bu günlere bağlayan

Acıların kalbine tebessümü saplayan

Aslında tek adımlık yoldur yaşam

Tek kirpik darbesiyle geçip gider apansız

An gelir o an her şey zamansız 

               zamansa bir o kadar acımasız 

                              geçip gider yıllar saçlarımda 

                                                                 beyaz aklar

Yalnızlığın beyaz perde aralığından seyrederdim sokağı

Karanlık ve bir o kadar kimsesizdi yapraklar

Geceler en uzun çöl sıcağı

Geceler en uzun mesafedir yaşayana

                                       ağaçlar anlamazlar', 'Yalnızlığın beyaz perde aralığından seyrederdim sokağı Karanlık ve bir o kadar kimsesizdi yapraklar Geceler en uzun çöl sıcağı Geceler en uz...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/beyaz-perde-araligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalıydı ( serbest )', 'olmaliydi-serbest-nedim-saatcioglu-6kjsh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmemiş bir resimdi o

Çırılçıplak bir kadındı

Sevişmenin rengini bilmezdi yüzü yoktu

Çünkü henüz çizilmemişti o en derin boyutu

Bir göl olmalıydı ardında ve dalgasız hayalleri

Öyle mahzun… öyle siyah… ve öyle iri…olmalıydı gözleri

En sevdiği şarkılar dağılmalıydı raflarda

En sevdiği plaklar asılmalıydı duvarlarda

Altı gözlü bir odada 

                    üç nefeslik kırmızı mumlar yanmalıydı

                                                      beyaz muhabbetler içinde

Yüreği kanadığı zaman 

                    tebessümü rendelememeliydi üstüne 

                                                       kabuk tutmasın diye

Hayat spatulayla kazıyıp atmamalıydı onu yüreğinden

Bu laleler artık birleşmeliydi

Bu gece yaşanmalıydı geç kalınmış şarap içimi

Sessiz telefonları duymalı

Ve artık sevişmeyi vurmalıydı saatin tik-takları

Her saniye ayrı bir tel olmalı saçlarına

Her saat ayrı bir hücre damarlarına

Fırçalar dans etmeli,boyalar ahenk olmalıydı

Çırılçıplak kadın bu gece hayat bulmalıydı

Yedi ile iki’yi yan yana getiren kader adına

Yarın güneş dogmadan önce onun da gülen bir yüzü olmalıydı', 'Bitmemiş bir resimdi o Çırılçıplak bir kadındı Sevişmenin rengini bilmezdi yüzü yoktu Çünkü henüz çizilmemişti o en derin boyutu Bir göl olm...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olmaliydi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Git ( serbest )', 'hadi-git-serbest-nedim-saatcioglu-hy914', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık beni düşünme

Benim için ağlama

Hüznün bütün duraklarını geçtim

Bütün saatler artık yaz

Yüreğimi yakmıyor sensizliğin garındaki ayaz

Her gece vurmuyorum kendimi tütün ve anasona

Anladım ki senli yolculuğumda vardım artık sona

Belki bir ihtimal

Bir ihtimal en sevdiğin şarkıda düşersin aklıma

Kaparım göz kapaklarımı

Karanlıklar dağıtır efkârımı

Hadi git yolun gözlerin gibi olsun

Hadi git mutluluk son demin olsun

Ne kızgınım sana ne de dargın

Belki de buydu hayatta en doğru kararın

Hadi git ama bir tek şeyi unutma giderken

Sen yüreğimin çektiği en net fotoğrafsın

bu şiirin videosu için lütfen tıklayınız...

? id=100001052225259#! /video/video.php? v=101554649889609&ref=mf', 'Artık beni düşünme Benim için ağlama Hüznün bütün duraklarını geçtim Bütün saatler artık yaz Yüreğimi yakmıyor sensizliğin garındaki ayaz He...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hadi-git-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Ve Hazan ( Serbest )', 'huzun-ve-hazan-serbest-nedim-saatcioglu-dc5d9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hüzzam bir hüzün,nihavent bir hazansın yüreğimde

Sen çocukluk hayallerim kadar ulaşılmaz

Sen çocukluk düşlerim kadar temizsin

Geç kalmışlık veya erken yola çıkmışlık

                     buydu hayatımdaki gerçek anlamın

Sen benim en günahkâr yanım 

                      en muhteşem kadınım

                                      benim insanım

                                           benim coğrafyamdın

Ama ne yazık hayatıma çok geç kalmıştın

Ben hazan sandıklarında 

               hüzün biriktirirken sensizliği tüketmek adına

Sen bahar sabahlarında 

                umut ekiyordun yalnızlık tarlalarına

Gel gör ki zaman ne geçti ne de erken

Çünkü ben sensizliği seçmiştim doğarken

Belki de bu yüzdendi yüreğimdeki dram

Belki de bu yüzdendi dilime düşen hüzzam

Artık ne pişmanlık şarkıları söylüyorum hüzün sokaklarında

Ne de isyan bayrakları asılı hazan duraklarında

Anladım ki her yürek kendi uçurumunda intihar edermiş

Anladım ki ümit kalmayınca telaş bitermiş

Sen çocukluk hayallerim kadar ulaşılmaz

Sen çocukluk düşlerim kadar temizsin

Ama ne yazık hayatıma çok geç kalmış 

                      buna rağmen  yüreğimdeki en derin izsin', 'Hüzzam bir hüzün,nihavent bir hazansın yüreğimde Sen çocukluk hayallerim kadar ulaşılmaz Sen çocukluk düşlerim kadar temizsin Geç kalmışlık ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/huzun-ve-hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Yolumdun ( serbest )', 'tek-yolumdun-serbest-nedim-saatcioglu-i50u2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bedeli olmalı mıydı seni sevmenin

Bir bedel ödenmeli miydi…? 

Sensiz aldığım her nefes zarardı ömrüme

Ben sadece seninleyken aldığım nefesten gurur duyardım

Yanımda olmadığın an

Zaman…

         bir sabun gibi kayıp gidiyordu avuçlarımdan

Dağlarda gözlerin vardı sularda yüzün

Bileğimde kokun içimde hüzün

Yaşam adına…

              kolay adına…

                            ne varsa her şeyi bırakıp 

                                                seni sevmiştim ben

Ömrümün en dik…

           ömrümün en yeşil… yokuşuydu gözlerin

Kuşatılmıştı bütün kalelerim

Bütün duygularım zapt edilmişti

Müebbede  mahkumdum gözlerinde

Senin sevgini özgürce

                 ve sınırsızca yaşamak adınaydı 

                                           bütün çırpınışlarım

Sen anlamasan da tek gayretimde gerçeklerden kaçışlarım

Gecenin en karanlık ıssızlığıydı sensizlik

Yokluğunda uykunun büyülü düşlerine kapanırdı gözlerim

                                                                seni görmekti tek            isteğim

Çünkü sen özlenmeye layık tek değerdin

Çünkü sen her şeydin…sen sevdiğimdin

Seni milyonlara bölmüştüm

Baktığım her yerde sen vardın

Her kaldırım taşında

Her sokağın başında

Senden bir anı vardı

Baharımda kışımda

Seni tanıdığım gün yüreğimin düğünüydü

Senden gelen her şey kabulümdü

Gerçeğe dönüş yolunu kaybetmiştim okyanus gözlerinde

En yasak ve en yanlış doğrumdun

Gerçeğim yoktu artık sen aşk adına yürüdüğüm tek yolumdun', 'Bir bedeli olmalı mıydı seni sevmenin Bir bedel ödenmeli miydi…?  Sensiz aldığım her nefes zarardı ömrüme Ben sadece seninleyken aldığım nef...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/tek-yolumdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneştim ( serbest )', 'gunestim-serbest-nedim-saatcioglu-780y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman yalnız kalsam

Ne zaman şapkamı önüme koysam

Hep düşünürdüm...

Zamanın benden çaldıklarını

Benim zamandan aldıklarımı

Ben mi çok gerçekçiydim

Hayat mı hayalperest...

Yoksa hayallerim gerçeklerin ardında mı saklıydı

Ama bir doğru vardı

                yaşamın aldıkları daha fazlaydı

Bakire duygularım vardı uzak diyarlarda

Umutlarım vardı kirlenmemiş

O gündüzü yaşarken benim karanlığımda

Ben geceyi paylaştım onun aydınlığında

Yeminle söylemişti...

Bekle...bekle...bekle...

Bekle demişti

“ bir gün döneceğim ” demişti

Bekledim...

Herkes doludizgin koşarken mutluluğa

Ben hasretin yollarında emekledim

Ömür tezgahımda hep sabırdı törpülediğim

Ve sevdim...hiçbir şey beklemeden sevdim

Ve sessizce bekledim

Bir cenin ömrü sürdü bekleyişim

Meğer boşuna kürek çekmişim

Tek bir imza her şeye bedelmiş

Sonradan anladım

O beni kader defterinden

“ hoşça kal ” dediği gün silmiş

O günden sonra inanmadım aşklara

İnanmadım aşk uğruna dökülen yaşlara

Ben hep kendi doğrumu yaşadım hayatta

Bazen doğrularım yanıldı

Bazen duygularım sarsıldı

Ben herkesi kendim gibi sandım

Yanıldım

Korktum...her şeyden kaçtım

En sonunda kendimi kaderin kollarına bıraktım

Mavi boyalı yatak odamda

                       yastıklara gömdüm anılarımı

Bebekçe ninniler söyledim geceler boyu

Umutlarımı uyuttum dizlerimde

Buz gibi duvarlarda 

                   masumluğun çerçevesiydi yüzüme bakan

Ve içimde bir korku vardı artık

Aşka olan inancımı yıkan

Gördüğüm her mutluluk rüyası

                   yarım kaldı kirpiklerimde

Kimi geceler kâbuslarla uyandım

                         en derin uykularımdan

Ağladım...

Karanlıklar tek şahitti göz yaşlarıma

Ve onlarca...onlarca hayal kırıklıkları düştü

                                      gözlerimden avuçlarıma

Direndim hayatın haksızlığına direndim

Yalnızlık devleştikçe yüreğimde

Mantığımla yaşamayı öğrendim

Ve bir tek şeye inandım hayatta

Mutluluklar karanlıklarda saklıydı

Bense bir güneştim.', 'Ne zaman yalnız kalsam Ne zaman şapkamı önüme koysam Hep düşünürdüm... Zamanın benden çaldıklarını Benim zamandan aldıklarımı Ben mi çok ger...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/gunestim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olurdu 2 ( serbest )', 'ne-olurdu-2-serbest-nedim-saatcioglu-2lkpi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerini düşünmek...

Bir çölün kıyısında

 yakamozları seyretmek gibi bir şeydi...

                                   veya kutupta güneşi görmek gibi...

Bir o kadar serin ve bir o kadar sıcak 

                                     ama bana hep uzak

Her şey bu kadar yakınken ellerime 

       ve aşka dair her şey karşımda dururken

Seni kaybetmek korkusuydu aslında yüreğimin telaşı

Yitirmişliğin verdiği eziklik

                  titreyen dudaklarımda çırpınan kelimelerde saklıydı

Ben her şeyi göze almıştım

Ne güneş istiyordum dünyama 

                 ne de parlayan bir yıldız

Keşke...keşke beni aşk denen bu ıssız yolda

                                      bırakmasaydın pusulasız

Ben en koyu yalnızlığımı

Bir gece bir okyanus güvertesinde

               avuçlarına bıraktığımı sanmıştım

Şu an tonlarca hasret yüklü olarak onu geri alıyorum

Ve kadehimi vazgeçilmezime...

               yalnızlığıma kaldırıyorum...

Şimdi bütün renkler solgun 

        düşlerse bir o kadar faydasız

Çıkışı olmayan bir labirentte 

Yorgun yollar bile uzamakta kararsız

Oysa duygularım müebbedin firarisiydi

Arzularım yasakların delisi

Bana baktığın an

Asi dağların kalın eşkıyası bakışlarım 

                              bir kar tanesi gibi erirdi

Yüreğimdeki her düğüm bakışınla çözülürdü

Senin gözlerinde hayat hep yeşile bürünürdü 

                                         ve bölünürdü uykularım 

                                              seni başka kolda gördüğüm zaman

Ağlardım yatağımda gözlerimi açmadan...

Yanında buharlaşan bir suydu göz yaşlarım

Tek sözünle yıkılırdı en heybetli dağlarım

Sen varsan ben vardım...

Sen yoksan ben kardım...

Sen tamdın ben yarım...

Gittin parçalandım..

        gittin yağmalandım...

              gittin bir başıma kalakaldım

Senden...senden istediğim  çok şey değildi aslında

Ne olurdu...ne olurdu asmasaydın umutlarımı

                bir çölün ortasında ıssız bir darağacına

                                    ne olurdu...ne olurdu...ne olurdu...', 'Gözlerini düşünmek... Bir çölün kıyısında  yakamozları seyretmek gibi bir şeydi...                                    veya kutupta güneşi gö...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ne-olurdu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Düşündüm ( serbest )', 'hep-dusundum-serbest-nedim-saatcioglu-94fhj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep düşündüm...

Hayatta neyi eksik yaptım

Veya neyi abarttım

Hayal dünyamı ardına kadar aralayan kimdi

           “yalnızlığın son perdesi”

En muhteşem gösterimdi

Bu düşler bu düşünceler Tanrı’m bunlar benim miydi

Dünümde bir şey vardı

Dünümde her şey tamamdı

Ama neden olmadı

Neden tek şey yarım kaldı yaşan(a) madı

Ne hayallerim vardı oysa ne pembe düşlerim

Düşündükçe dudağımda çıldırırdı gülüşlerim

Bir bebeğim olmalıydı mesela

Gecenin yarısında

             onun çığlığı uyandırmalıydı beni 

                                          en tatlı uykumdan

Mememden canımı çekmeliydi kanatırcasına

Kızmalıydım...

Ayaklarımda sallarken sızmalıydım...

Ben...ben anne olmalıydım

Uykusuz bir gecenin sabahında

Bir kahvaltı sofrasında

Sıcak bir çayın buharında kaybolmalıydı yorgunluğum

Yanaklarıma konan 

                iki küçük öpücük olmalıydı mutluluğum

Akşamı iple çekmeliydim

Deli gibi sevişmeliydim

Gecenin bilmem kaçıncı saatinde

Sevdiğime sarılarak

                buz gibi duvarlara

                    mutluluğun resmini çizmeliydim

Oysa...oysa ben hep

                   kıraç topraklarda umut diye küreklendim

Kuyular büyüdükçe yüreklendim

Ama şimdi en dipteyim

Avuçlarımda hayal meyal gün ışığı

               sahi ben hangi mevsimde unuttum

                                               dudağımdaki ıslığı

Şimdi bir merdiven basamağı kazacak gücüm yok

Çünkü...çünkü gücümün son demindeyim

Düşlerimden uzakta...

                hayallerimin kazdığı tuzakta...

                        gündüzü olmayan bir iklimdeyim

Ben her zaman en koyu yalnızlığımı gecelerle paylaşırdım

Belki de...belki de bu yüzdendi karanlıkta korkaklığım

Her namlu üzerime doğruldu benim

Acılar zincirlere vurdu duygularımı konuşamadım

Ben resim resim aşkı kazımak isterken gökyüzüne

Her doğan güneş yeni bir geceyi serdi üstüme

Ne hayallerim var artık

Ne yarınlara gebe umutlarım

İhanet çukuruna düştü bütün aşklarım

Şimdi ağlıyorsam

Ne olur çok görmeyin

Yitirdiğim değerlerin anlamıdır göz yaşlarım', 'Hep düşündüm... Hayatta neyi eksik yaptım Veya neyi abarttım Hayal dünyamı ardına kadar aralayan kimdi            “yalnızlığın son perdesi” ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/hep-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen hiç olmadın ki...', 'sen-hic-olmadin-ki-nazife-abayli-jax5r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ortaköy''e gelmiştim,

Yıllar önce.

Bir Nisan günüydü.

Oturup sahile,

Bisikletleriyle akrobasi yapan,

Gençleri izlemiştim.

Heyecanla.

Güneşin batmasını bekliyordum ayrıca.

Balıkçı lokantalarından gelen,

Balık ve rakı kokuları,

Tanımadığım,

Beyaz atlı prensimi anımsattıkça,

Sarhoş oluyordum.

Daha o zamanlar hissetmiştim,

Yıllar sonra,

Çok uzaklardan gelip,

Aklımı başımdan alacağını,

Balığıma,rakıma,

Ortak olacağını.

Desem de inanma.

Sen hiç olmadın ki...', 'Ortaköy''e gelmiştim, Yıllar önce. Bir Nisan günüydü. Oturup sahile, Bisikletleriyle akrobasi yapan, Gençleri izlemiştim. Heyecanla. Güneşin ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-hic-olmadin-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Üşümez ( serbest )', 'oluler-usumez-serbest-nedim-saatcioglu-dtcbw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç kâbus gecesi yaşadım

Kaç dolunay yalnızlığı

Dizlerimde buz vardı ellerimde kar

Hiçbir şey dokunmamıştı bana özüm kadar

Ben yarı çıplak bir çocuk masumluğunda

                    cam pervazına dizerdim bebeklerimi

Ve her gece çığlık seslerim yırtardı gecenin sessizliğini

Henüz kapım açık değildi aşka

Hiç kimse anlamazdı dilimden

                               bebeklerimden başka

Yasaklarla dolu dünyamda

Hep yasakları yaşadım yıllarca

Birisi özümdü biri özümden parça

Ufacık bir ışıkta bedenim paramparça

Seneler sonra bir aşk buldum kendime

Gözlerinde Mayıs güneşi 

                    saçlarında Temmuz ateşi vardı

Hiçbir şey umursamazdım

Ve hiçbir şeyden korkmazdım

Ben onun yanında bendim

Kaybetme korkusunu onunla yendim

Ne yazık korkumu yenmişken onu kaybettim

Bir Mayıs akşamı gözlerinde bulduğum sıcaklığı

                       bir Temmuz sonrası odamdaki gözlerde görmek 

                                                                                     ne kadar acı

Birisi canımdı biri canımdan parça

Sırtından vurulan duygular paramparça

Bir yanım yanında

Bir yanı canımdaydı

Ölüler ağlamazdı biliyordum

Oysa ben ağlamak istiyordum

                          ölü aşklar diyarında

Çoğu geceler

          hasreti gözlerimde damla damla yaş olurdu

                           ve ellerimde kurudu hayallerimin sarı gülleri

Unutamazdım onlu dünleri

Çünkü bir tek o anlardı bakışlarımdaki özlemi

Şiirler yazardı bana

Aşkı anlatırdı her mısra

Hâlâ mutluluk şiirleri yazıyordur belki de

Belki de umut iklimlerinde yeni bir aşk arıyordur kendine

Beynindeki gerçeğe inat

Mayıs gözlü Temmuz ateşi

Gittiğin yere götüremezsin güneşi

Güneş gittiğin yere gelmez

Üzülme ve sakın korkma

Ölüler üşümez', 'Kaç kâbus gecesi yaşadım Kaç dolunay yalnızlığı Dizlerimde buz vardı ellerimde kar Hiçbir şey dokunmamıştı bana özüm kadar Ben yarı çıplak b...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/oluler-usumez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Zamandır ( serbest )', 'uzun-zamandir-serbest-nedim-saatcioglu-339t1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzun zamandır nasırlı bir el

   dalgalı saçlarımda şefkatle dolaşmamıştı

Uzun zamandır yorgun bedenim huzur içinde 

                      bir dizde yatarken gün ağarmamıştı 

Uzun zamandır yüreğim böylesine ağlamamıştı

                                                çok uzun zamandır

Hayatta her sözü söylemiştim dilimin döndüğünce

Hayatta her şeyi yaşamıştım gücümün yettiğince

Ben hep pembe panjurlu bir evin çerçevesinden 

                              seyretmiştim pamuksu bulutları

Ve yıllarca karanlığın koynunda gizlemiştim korkularımı

Ama dün gece bir adamın nasırlı avuçlarına bıraktım

 çocukluk sırlarımı

Yıllar öncesinde kaybolan bir aşkım vardı

Canımın tam yarısıydı

Yollar boyu gözleri vardı yürüdüğüm her sokakta

Yıllar boyu sözleri vardı karıştığım her savaşta

Her sabah aklımdaydı 

ve her gece rüyamdaydı 

o hep benim yanımdaydı

Yıllar öncesinde kaybolan aşkım benim Babam’dı

Gün oldu beş yaşında çocuk gibi oynadım

Gün oldu anne oldum resimlerle ağladım

Çaresiz bir çırpınıştı gerçeklerden kaçışlarım

Çaresiz bir aldanıştı sabah uyanışlarım

Söylemek istediğim her söz paramparça oldu dudaklarımda

Ve her damla gözyaşı yere düşmeden kurudu yanaklarımda

Hayallerimin yıkılışına şahit oldum gün batımlarında

Uzun zamandır hiç kimse anlamamıştı

 gözlerimdeki bakışların rengini

Uzun zamandır hiç kimse dinlememişti 

yüreğimdeki çığlıkların sesini

Ama dün gece bir adamın nasırlı avuçlarında

Bulmaya karar verdim bendeki asıl beni', 'Uzun zamandır nasırlı bir el    dalgalı saçlarımda şefkatle dolaşmamıştı Uzun zamandır yorgun bedenim huzur içinde                        bi...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/uzun-zamandir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Kalesi', 'i-ntihar-kalesi-nedim-saatcioglu-ikoa7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Henüz intihar edilmemiş uçurumlar var aramızda

Henüz tadılmamış hayaller

Ve yaşanmamış anılar

Ne tenin tende bulduğu tutsaklık var

Ne de Ağustos yangını sıcaklık

Biz her şeye daha yeni başladık

Hatıralar perdelerini aralamadı hâlâ

Hâlâ bir şeyler eksik gönül bulmacamda

Belki de yaşamın en zor yanı

Duyguyla mantığın savaşma anı

Ne umutlar düzlüktedir ne beklentiler

Her adım dik bir yokuştur

Düşünceler intihar edilmemiş boşluktur

Senden önce

         kaç intihar kalesinden attıysam yalnızlığımı 

                                                           yine bana döndü

Yine bana döndü yalınayak tutsaklığım

Şimdi sen varsın

Yalnızlığıma yeni bir intiharsın

Sen senden önceki kaleleri yıkacak kadar güçlüysen

Ve yüreğinin bilekleri 

                  yüreğimin bileklerini bükecek kadar duygu doluysa

Zaferin muhteşem olacaktır yüreğimde

Ama dedim ya 

            henüz intihar edilmemiş uçurumlar var aramızda', 'Henüz intihar edilmemiş uçurumlar var aramızda Henüz tadılmamış hayaller Ve yaşanmamış anılar Ne tenin tende bulduğu tutsaklık var Ne de Ağu...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/intihar-kalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşan(ma) mış', 'yasan-ma-mis-nedim-saatcioglu-1jtb3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“ Ölülerin sakalları uzamaz ”

Bunu daha önce hiç düşünmemiştim

Dün sabah aynanın karşısında 

         sensizde yaşayabildiğimi anladım

Yanlış zamanda

          yanlış yerde

              belki de yanlış insanda

                         aradım mutluluğu

Yıllar öncesine dayanan

Bir yaşan(ma) mışlığın tutkunluğuydu içimdeki

Hep bir umuttu anılara tutsaklığım

Ve bütün yolculuklarım senli hayaller üstüneydi

                                         uykusuz geceler boyunca

Bu yitik aklımla 

        dünyadaki yalancı cenneti senin gözlerinde sanırdım

Tütün ve rakı kokardı yalnızlığım

Küçücük bir mutluluk için

                 tam bin yıl yol kat etmeyi göze alan gözlerim

Zaman tünelinde yeni aşklar buldu kendine

Her şeyin bir sonu varmış meğerse

En büyük aşkların bile

Yalnızlığın süzgecinden geçirip anıları

                 damıtılmış hayallerimle karıştırdım

Ve bir ceket gibi çıkardım seni sırtımdan

Kara düşler sokağında

Yalnızlığın şarkıları düşmüyor artık dudaklarıma

Yaşanmamış saydım

Ne güneşi ne kumsalı ne seni

Ne senin için ağladığım geceleri

Artık yüreğim ne met ne de cezir

Ne dalga var ne de sihir

Bir umudun peşinde sürüklemiyorum artık beklentilerimi

Yastığım tanık olmuyor göz yaşlarıma

Umut hiç olmadığı kadar yakınımda

Mutluluk ise bir ıslık çığlığının ilk notasında

Yaşam üstüne ne varsa var sayılan

Her şey senin üstüne

        her şey aşkım üstüneydi 

                             benim gözümde

Oysa bir esimlik rüzgar bile yetiyormuş bazen

                                                    hüzünleri silmeye

Meğer bir görümlük rüyaymış yaşam

                                değmezmiş gama kedere

Şimdi avuçlarımda o amaçsız çırpınış yok

Senle geçen dünlerimi umarsız bir gayretle 

           bu günlere taşımaya çalışmıyorum artık

Yılların yorgunluğu düşerken omuz başlarıma

Zincirler vurdum mazinin kapısına

Kaç kadeh içersem içeyim aklıma gelen ilk sen değilsin

Medet ummuyorum artık on iki tuştan

Kalmadı yüreğimde san dair beklentim

Seni mazinin yaşan(ma) mış anlarıyla uğurladım yüreğimden

Yolun açık olsun

Belki istediğin buydu

Belki istemediğin oldu

Bir gün bir gün yeniden karşılaşırsak

Gözlerim gözlerindeki dünü yeniden yakalarsa 

Ve yüreğimdeki küllerin sıcaklığıyla

                          hatıralar adına sarılsam da

Hayallerimin kapısını örttüğün

İçimdeki aşkı öldürdüğün için

                            kırgın olacağım sana', '“ Ölülerin sakalları uzamaz ” Bunu daha önce hiç düşünmemiştim Dün sabah aynanın karşısında           sensizde yaşayabildiğimi anladım Yanlı...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/yasan-ma-mis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkent''te Gecenin Yarısında ( serbest )', 'baskent-te-gecenin-yarisinda-serbest-nedim-saatcioglu-unxdp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buğulu bu başkent gecesinin

Çiğ düşmüş caddesinde

Puslu Sokak lambasının 

Hüzünlü Işıltısı düştü gözlerime

Yalnızca seni düşündüm bitimsiz gece boyunca

Mazim yeniden can buldu hafızamda

Yanına gelirken kaldırıma emanet bıraktığım 

                           yalnızlığım  seslendi köşe başında

Ve bebekçe söylentilerin  uğultusu yankılandı kulağımda

Uçurum gibi çekti beni sensizlik duygusu

Bulamadım kendi yolumu

Düşüncem yollarca uzadı

Aslında bütün adımlar 

         sancılı bir umutsuzluğa yolculuktu

Ve bir şiir takıldı dudağıma 

                          gecenin yarısında

Başıboş bu başkent sokağında

“Sen bana yabancı

Ben bana yalancı

Elimde cehennem kılıcı

Bu sinsice ceza bilmem kaçıncı”

Acı kör bir pusuya kurulmuş haince tuzaktı

Seni bana getirecek tozlu yol ise cennet kadar uzaktı

İçimde devleşen karınca sessizliğini

gözyaşımın çığlığı uyandırmaya yetmedi 

Sabrımı ucu ucuna ekleyip

Bu cinnet geceme bir neden bir cevap aradım

Gönül bulmacamda

eksik olan sadece tek sözcük vardı

O da gül  dudağında tutsaktı

Yalnızlık acının kırbacı oldu

             buz misali soğuk bu otel odasında

Özleminle açıldı uykusuz  kirpiklerim

Usulca bir yangın sardı bedenimi

                       alevler içinde titredim

Çırılçıplak yalnızlığımla

Avucumda tek damla mutluluk umudu

Öylece  seni bekledim

Sense hep başka dünyanın papatya falında yaşadın

Kupa kızıydı uğurun

İki katlı evinin

            üst katında saklıydı unutmaya çalıştığın gönül vurgunun

Belki de kendince çok mutluydun

Başucumda teninin o çocuksu kokusu

Aklımda suya inen  ceylanın korkusu

Bunca şeye rağmen

Kalkıp sana gelmek istedi canım gecenin  yarısı

Önce ince bir telaş başladı ruhumda

Sonra umutsuz acı dolu gelgitler duygularımda

Cam kırıkları gibi paramparça oldu 

                        hayallerim  yastığımda

Yenildim gözyaşıma

Ağladım...gecenin yarısında

Başkent’te...

Bir yolcu odasında...', 'Buğulu bu başkent gecesinin Çiğ düşmüş caddesinde Puslu Sokak lambasının  Hüzünlü Işıltısı düştü gözlerime Yalnızca seni düşündüm bitimsiz g...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/baskent-te-gecenin-yarisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetme Korkusu ( serbest )', 'kaybetme-korkusu-serbest-nedim-saatcioglu-fybct', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ilık bir nefesin göğsümdeki uykusudur

                                             seni yaşamak

Bazen tülden bir pembe

Bazen bulutsu bir mavi

Bir ipek kayganlığıdır gül tenine dokunmak

Kimi gün katran karası gecelerimi aydınlatır

                                         kömür karası gözlerin

Kimi gün yol boyları sonrası döndüğüm

                 hep aynı kürkçü dükkânıdır dizlerin

Yanında buz dağlarım çözülür

Bir uçurtmanın kuyruğudur yüreğim

Umursamam hiç bir şeyi

Ve hiç bir şey için kaygılanmam

Simsiyahlar bile bana beyaz görünür

Yanımda sen olduğun zaman

Gökkuşağının yedi rengidir saçların

Her telinde başka bir iklimin sarı güneşi

Her telinde başka bir yangının kızıl ateşi saklıdır

Bir yelpazedir dudaklarındaki serinlik

Camdan odalarda

    pembe çerçeveler içinde 

                    resimlerin asılıdır

                         yüreğimim duvarlarında

Ve düşüncelerim kuralsızca yaşar seni

                                 bir kartalın kanatlarında

Ellerimde bir çırpınış

            bakışlarımda bir tavşanın ürkekliği

Adımlarım hep bir adım ardındadır

Gözlerimdeki bir ceylanın tedirgin uykusudur

Yüreğimdeki tek endişe

Seni bu kadar severken

Kaybetme korkusudur', 'Ilık bir nefesin göğsümdeki uykusudur                                              seni yaşamak Bazen tülden bir pembe Bazen bulutsu bir mav...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kaybetme-korkusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Meyhane ( serbest )', 'ayni-meyhane-serbest-nedim-saatcioglu-nshaj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde hasret yangınları devleştiği zaman

Ben hep aynı meyhaneye giderdim

Gözlerim beyaz bayrak açardı özlemlere

Özlemlerse kahpe kurşunlar yağdırırdı 

                                vurgun yemiş hayallerin üstüne

Sana olan hasretim öylesine büyüktü ki

Bazen güneşin gözyaşları

Ayın hıçkırıklarına karışırdı

Matem yağmurlarında kalırdı gözlerim

Ömrüm sonbahar kalbim karakıştı

Ve ben elimde sarı limon çiçekleri

Alaca karanlık zamanı ağlardım 

                  ortak olurdum güneşin gözyaşlarına

Yolum hep aynı yokuşa varırdı

Her adım geçmişi sürüklerdi ardımdan

Unutulmuş yolların yolcusuydum nedense

Rüzgarın dudaklarında tanımadık ıslıklar

Ve cehennem sıcağı olurdu sensiz bütün yolculuklar

Simsiyah bir karanlık

Simsiyah bir yalnızlık

Gecenin en derin saatinde bile

                    kâbuslarla savaşırdım uykular boyu

Sabah senin hasretinle ayrılırdı kirpiklerim

Sonra yine akşam olurdu

Yine yüreğimde hasret yangınları devleşirdi

Ve ben yine aynı meyhaneye giderdim', 'Yüreğimde hasret yangınları devleştiği zaman Ben hep aynı meyhaneye giderdim Gözlerim beyaz bayrak açardı özlemlere Özlemlerse kahpe kurşunl...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayni-meyhane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-nedim-saatcioglu-ygofr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllarca gönlümde tüneller kazdım

Çıktığım her ışık başka uçurum

Ne yapsam ben senden kurtulamadım

Ben sana esirim ben sana mahkum

Ay güneşe mahkum yıldızlar aya

Su yağmura mahkum nehirler suya

Dal toprağa mahkum çiçekler dala

Ben sana esirim ben sana mahkum

Ne zaman unutsam senli günleri

Firari düşlerim yakalar beni

Özgürlük boynumda ilmek misali

Ben sana esirim ben sana mahkum

Aldığım her nefes senden sorulur

Sensiz hayallerime zincir vurulur

Gözlerim sevdanla teselli bulur

Ben sana esirim ben sana mahkum', 'Yıllarca gönlümde tüneller kazdım Çıktığım her ışık başka uçurum Ne yapsam ben senden kurtulamadım Ben sana esirim ben sana mahkum Ay güneşe...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mahkum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Hata ( serbest )', 'tek-hata-serbest-nedim-saatcioglu-27wan', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybolduğum her yolda

Gözlerin vardı karşımda

Bana aşkın yolunu gösterirdi

Ve tutsağı olduğum gözlerindeki

                    kelebek bakışların vardı

                                beni hayata bağlayan

Bazen deli dolu bazen duygu dolu

Yüreğim imkansızı kovalardı

Gece yarısı güneşi beklerdi gözlerim

                                     sana kavuşmak için

Bir güneş doğar on güneş batar

Ama sen bir türlü gelmezdin

Ulaşamazdı sana yürüdüğüm yollar

Yüreğimdeki her pencere başka bir uçuruma açılırdı

Çığlık çığlık düşerdi hayallerim

Bir kristal gibi milyonlara bölünürdü

Ve acının son perdesi oynardı gözlerimdeki damlalarda

Hayaller kurardım

Çocuksu bir heyecan sarardı içimi

Bebekçe söylentiler dillenirdi dudaklarımda

Yalınayak ve çırılçıplak

Hasretine sevdalanırdım her gece

Hiç kimse anlamazdı beni

Doğru zamanda doğru insanı aradım hep

Doğru sen miydin aldanan ben miydim

Bir yanım sende tutukluydu

Bir yanım umut doluydu

Ben hep  “beni seviyor”  diye

Kendimi kandırdım

Belki de doğruydu

Belki de tek hata buydu', 'Kaybolduğum her yolda Gözlerin vardı karşımda Bana aşkın yolunu gösterirdi Ve tutsağı olduğum gözlerindeki                     kelebek bakış...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tek-hata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Yolculuk ( serbest )', 'gunese-yolculuk-serbest-nedim-saatcioglu-0snd2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben imkansızın peşindeyim oysa

Oysa ne çok isterdim “ Seni Seviyorum ” demeni...

... 	... 	...	...	...	...	...

Bir gece yarısı güneş doğacak

              silinecek gözlerimden uyku

Sisli perdeler aydınlanacak

        ve güneşe yolculuğum başlayacak yalınayak

Bir çölün ortasında kırık bir buz parçası

Belki de takılıp kumlara düşeceğim

Canım yanacak...Kanım akacak

Ama olsun, ne kadar zor olursa olsun

                                       ben sana geleceğim

Yeryüzünden sarı bulutları toplayıp

                         saçlarında bir buket yapacağım

Yüreğimin her yerinde

Hüzünlerin kanat sesleri yankılanacak

Ve kırık bir ut hüzzam makamında

                          mutluluk şarkıları çalacak

Saat yirmi beş...

      henüz akşam üzeri... 

            gün yeni başlıyor

Bir çıkmaz sokaktayım

Sana varmaya bir adım kaldı

Biraz geç kalabilirim uykun gelirse yatabilirsin

Korkma güneş doğmadan az önce yani gece yarısı

Pembe denizler üzerinden koşarak geleceğim

“ Beni Sevdiğini ” o zaman söyleyebilirsin', 'Ben imkansızın peşindeyim oysa Oysa ne çok isterdim “ Seni Seviyorum ” demeni... ... 	... 	...	...	...	...	... Bir gece yarısı güneş doğacak...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gunese-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle mi ( serbest )', 'oyle-mi-serbest-nedim-saatcioglu-4805l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bundan sonra bir gölge gibi

Anıların peşinde koşacağım öyle mi

Her yol ayrımında yollar sana giderken

Ve her köşe başında senin ayak izlerin varken

                                 görmezlikten geleceğim öyle mi? 

Bundan sonra fırtınalı gecelerde bir liman gibi

                 sığındığım gözlerini düşünmek yok öyle mi? 

Issız sokaklarda

          pembe hayallerin tutsağı olmak yok

Hüzün bir nöbetçi gibi nefesimde dolaşırken

Sabahlara dek birleşmeyen kirpiklerime

                                                ağlamak yasak öyle mi? 

Oysa tedirgin gözlerimin ışığı ilk fark edişiydi

                                                             seni görüşüm

Elini tutuşum

          ilk kıvılcımıydı yüreğimdeki yangınların

Senden önce güneşin batışını güzel sanırdım

Seni güneşin battığı an gördüğümde

Yıllarca yanıldığımı anladım

Bana seni hatırlattığı için artık sahile inmiyorum

Rüzgarlı havalarda gözlerimi kapatıyorum

Çünkü

Ben dalgalı denizleri saçlarına benzediği için severdim

Bu yüzdendi dalgalara tutkunluğum

Bu yüzdendi denizlere vurgunluğum

Şimdi umarsız ve vurdum duymaz rüyalardan

                                                         teselli bekliyorum

Oysa sen...

       düşler üstüne kurulmuş hayatımın

                                   düşlerinden bile uzaksın

Ama olsun

       her şeye rağmen

             sen benim dünyamdaki en görkemli tuzaksın', 'Bundan sonra bir gölge gibi Anıların peşinde koşacağım öyle mi Her yol ayrımında yollar sana giderken Ve her köşe başında senin ayak izlerin...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/oyle-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Yasaklarınla Sevdim ( serbest )', 'ben-seni-yasaklarinla-sevdim-serbest-nedim-saatcioglu-h8wwv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın yasını tutuyorum her gece

Sıvası dökülmüş duvarlara gömdüm hayallerimi

En hüzünlü manzaraların resimleri elimde

                                  ve bir şarkı dilimde seni anlatan

Geceye dair ne varsa

Ne varsa karanlığı hatırlatan bana

Anılarla, pişmanlıklarla, keşkelerle

Başbaşayım her gece soğuk odamda

Yalnızlığımı tenha kaldırımların 

                                    karanlığına gömdüm

Tebessümler uzak

Karanlıklar tuzaklarla dolu

Ve uzun bir yol var önümde

Bilmediğim bir yöne doğru

Sularda ağlara takılan balıklar gibi çaresiz

Ve hiç kimsesizim her gece

Patlayan bir yanardağdan

                              savrulan lavlar gibi göz yaşlarım

Her biri bir alev topu kirpiklerimi kavuran

Dalgın bakışlarım uçurtmalı tepelerde

                             pembe rüzgarların hayalini kurmakta

Gel gör ki zamansız vurmakta saat

                     yeni başlayan kapkaranlık bir geceyi

Sensizlik kara bulutlarla kaplı bir uçurum 

                           düşlerime tutunmak istiyorum düşerken

Düşlerim riyakâr çığlıklar atıyor

Düşlerim düşlerime ihanetle bakıyor

Ve ben her şeye rağmen gülüyorum

        bin yıllık bir gecenin ardından

              sabah senin kollarında uyanmak istiyorum

                                                           çocukça bir istekle

Ayaklarım ıssız sokakların aşinası

Bilmem kaç bin gece yaşadım bir başıma

Yokluğunda hayalinle kendimi tamamladım

                                                         bir bütün oldum

İçmedim,hiç sarhoş olmadım

Uzak durdum tanıdık meyhanelerden

Tanımadığım yüzlerin

Muhabbetine ortak oldu duygularım

Onların dertleriyle ağladım 

                                         ama hiç utanmadım

Gün oldu

Yalnızlık yüzüme baktı

                     ve utandı yalnızlığımdan

Gün oldu

Acılar milyonlara ayırdı bedenimi

Bölündüm parçalandım

Telefona uzandı elim

“sözüm” geldi aklıma yeniden toparlandım

                          ben sana verdiğim “söz” gibi yaşadım

Seninle konuşurken zincirler vurdum duygularıma

                                         ve o an prangalar vardı dudaklarımda

Seni çok sevdiğimi,seni çok özlediğimi

                            sensiz her şeyin anlamsız olduğunu

O günden sonra hiçbir zaman söylemedim

Ben seni senin istediğin gibi

Ben  seni “sözüm” gibi

Ben seni yasaklarınla sevmeye devam ettim

bu şiirin videosu için lütfen tıklayın...

? id=100001052225259#! /video/video.php? v=101825636529177&ref=mf', 'Yalnızlığın yasını tutuyorum her gece Sıvası dökülmüş duvarlara gömdüm hayallerimi En hüzünlü manzaraların resimleri elimde                 ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/ben-seni-yasaklarinla-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkı Kalmadı', 'farki-kalmadi-nedim-saatcioglu-pzf93', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böylesi yaşamak yaşamak değil

Düşlerin kâbustan farkı kalmadı

Gözlerim kalınca senden uzakta

Beyazın siyahtan farkı kalmadı

Tanrı’m gördüğümün hepsi rüya mı

Alevler sarıyor pembe dünyamı

Güneş mi karardı yoksa hava mı

Gündüzün geceden farkı kalmadı

Kaderim kederden duvarlar ördü

Yüzümü unutan aynalar kördü

Bu gözler kaç defa ihanet gördü

Tatlının acıdan farkı kalmadı

Bütün ümitlerim küle boyandı

Acılar göğsümden arşa dayandı

Kalbim bu yalana nasıl inandı

Sabahın akşamdan farkı kalmadı

Kader mi çiziyor bu kara yolu 

Sağım hüzünlerle solum gam dolu

Kırıldı gönlümün kanadı kolu 

Hayalin gerçekten farkı kalmadı

Ne yapsam olmuyor her şey boşuna

Çöllerin kutuptan farkı kalmadı

Çağlayan ne yapsın böyle yangına

Buzların ateşten farkı kalmadı', 'Böylesi yaşamak yaşamak değil Düşlerin kâbustan farkı kalmadı Gözlerim kalınca senden uzakta Beyazın siyahtan farkı kalmadı Tanrı’m gördüğüm...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/farki-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Flüorit Prizma', 'fluorit-prizma-ahmet-aksoy-4htpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'flüorşıl, hoyrat sevişmelerde cam kırığı

aldatmanın izleğinden geçerken

usundaki böceğin paslı duyargaları,

fark yaparken fark etmediğin

düştüğün üçgen yılan üçgeni,

sürüngen, sürünen, sürülgen,

aldatmak gerçek dışı kırılgan eylem,

ki sen şimdiden hissetmesende,

ben duyuyorum porselen yüreklerin

kırılmaya başladıklarını,

ve yeis duyuyorum dönmeyen zamanlardan,

flüorşıl, sende unutma, iş işten geçtikten sonra

hiç bir fodra dik tutamaz pişmanlığını,

ve elbet bir gün kırılır her üçgen,

nokta, çember içine alınmış eğriler

........................hepten düzelmez', 'flüorşıl, hoyrat sevişmelerde cam kırığı aldatmanın izleğinden geçerken usundaki böceğin paslı duyargaları, fark yaparken fark etmediğin düş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fluorit-prizma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıp başımı', 'alip-basimi-tuncay-emrem-08ccb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alıp başımı gideceğim bir gün.

Üstümde ne kimlik, ne de bir resim..

Belki adımı bile terk edeceğim.

Alıp başımı gideceğim bir gün.

Bir otel odasının bembeyaz yatağında

Ensemde kilitlenmiş ellerim.

Artık ne geçmişim var, ne geleceğim..

Ne de beni tanıyan, kapımı çalan..

Bir otobüsle yollarda, bir yere doğru,

Bilinmez, şimdiye kadar hiç gitmediğim..

Çıkarsa karşıma bir gülümseyen,

Teşekkür edeceğim ona gönülden.

Bir kahvehane mi olur, bir lokanta mı,

İnsanların beni fark etmediği..

Ne elimde bir yük var, ne de bir çanta,

Ya bir deniz kenarında veya bir parkta,

Canım çekmişse uzanıp yatıvereceğim..

Çekip gideceğim, -bu kesin- bir gün,

Belki de çok yakın bir gelecekte...

Zihnimde  ne hayal, ne de hatıra..

Boşuna mı bu özlem, çok uzaklara..

İçimde bir ses var beni çağıran..

Biraz bulut olmak, belki biraz su..

Bir ihtiyaç bu, derin bir arzu..

Uzayıp giden yollarda olmak..

Hep bir yere doğru, koşturup durmak..', 'Alıp başımı gideceğim bir gün. Üstümde ne kimlik, ne de bir resim.. Belki adımı bile terk edeceğim. Alıp başımı gideceğim bir gün. Bir otel ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/alip-basimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-bekir-mutlu-gokcesu-iiadg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir...

(De ki bu bir şiir

Veya çok sinir

Şiir falan değil 

Say ki içi ben de gizli

Say ki içi sende saklı

Ne farkeder 

Hissettiğindir şiir

Ben yazdım oldu

Adı şiir

Kendi şiir

Kim bu şiir değil

Diyebilir?)', 'Şiir... (De ki bu bir şiir Veya çok sinir Şiir falan değil  Say ki içi ben de gizli Say ki içi sende saklı Ne farkeder  Hissettiğindir şiir ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemime özlem kattı', 'ozlemime-ozlem-katti-nazife-abayli-tluh1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana olan özlemimi,

Unutabilmek için bugün,

Şehrin ıslak caddelerinde dolaştım,

Yağmur altında.

Saçlarım ıslandı,

Umursamadım.

Botlarım su çekti,

Aldırmadım.

Vitrinleri seyrettim bir süre.

Hatta camlardaki,

Reklamları okudum.

Yemeklik kıyma dokuz milyon,

Kredi kartına altı taksit,

Bir alana bir tane de bedava,

ÖSS kitaplarında indirim.

Derken...,

Mağazaların içinde,

Buluverdim kendimi.

Param olsaydı eğer,

Neler alırdım neler.

Ama nafile.

Aklım sendeymiş meğer.

Hiç biri unutturamadı,

Daha da fazlası,

Özlemime özlem kattı.', 'Sana olan özlemimi, Unutabilmek için bugün, Şehrin ıslak caddelerinde dolaştım, Yağmur altında. Saçlarım ıslandı, Umursamadım. Botlarım su ç...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ozlemime-ozlem-katti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-ozlem-cakir-75esx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Işıltılı sevinçler getir bana bir bir beraberinde

Yeni aşklar fısılda kulağıma en özelinden

Hedeflerim var biliyorsun uğrunda çabaladığım

Başarılar müjdele bana en ulaşılmazından

Söz ver hiç hayal kırıklığı olmasın 

Umutlarım fenerim olsun yolumda 

Acılar sadece uyarsın beni daldığımda boşluklara

Sakın yakmasınlar içimi

Bu yıl benim olsun tüm mutluluk gözyaşları 

Akıp giden uzaklara...', 'Işıltılı sevinçler getir bana bir bir beraberinde Yeni aşklar fısılda kulağıma en özelinden Hedeflerim var biliyorsun uğrunda çabaladığım Ba...', ARRAY['Türk Edebiyatı','Şiir','Özlem Çakır']::text[], 8.5, '{"poet":"Özlem Çakır","poet_slug":"ozlem-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yeni-yil-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İstanbul', 'ey-i-stanbul-ufuk-nazim-gjnas', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşlerde kaldı

Uykunun derin yanı.

Ve şehirler sakladı

O amansız düşler sağanağını

Ölümle işin ne 

Sen yaşamı düşle

Ey mavi kuşaklı gelin

Ey İstanbul.

Ürkütmesin seni

Bu bombalar.

Bükülmesin boynun

Hep Galata gibi

Kız kulesi gibi

Dimdik dur.

Ey umutların kalesi

Ey İstanbul.', 'Düşlerde kaldı Uykunun derin yanı. Ve şehirler sakladı O amansız düşler sağanağını Ölümle işin ne  Sen yaşamı düşle Ey mavi kuşaklı gelin Ey...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-istanbul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekten Halılar', 'cicekten-halilar-ufuk-nazim-3de3w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başka bir yol var elbet

Yağmurun toprağa 

Dokunduğu.

Başka iklimler var elbet.

Mesela; 

Güneşli bir sonbaharında

İstanbul un

Br de kar yağar

Üşümüş yüreklere.

Ahşap evlerinin çatısında

Alnı parlarken 

Yalnız İstanbul evlerinin.

Sen br de 

Bir apartmanın

Üst katlarından birinde

Beklersin 

Çiçekten örülü

Halıların serilmesini.

Ve kanaryaların

Şen kahkahalarıyla

Balkonuna dönmesini.', 'Başka bir yol var elbet Yağmurun toprağa  Dokunduğu. Başka iklimler var elbet. Mesela;  Güneşli bir sonbaharında İstanbul un Br de kar yağar...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cicekten-halilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savunma Mekanizmaları', 'savunma-mekanizmalari-sahin-yenilmez-q20i3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzak kalır insana bazen yaşam

Ve güneş ısıtamaz artık vücudunun hiç bir yerini,

Geceler eskisi gibi değildir

Ve ay yansıtma özelliğini çoktan kaybetmiştir zaten

Yıldızlarda.

Yollar eskisinden daha uzundu sanki

Ve artık moda oldu sonbaharda ayrılıklar,

Son bakışlarda hep aynı frekanstan

Alay edercesine içten ve soğuk.

Yıllar standart değerinin altına düştü

Ve artık dört mevsim yok

Sadece sevda ve ayrılık mevsimi var

Birde yalnızlıklar.

Ve bendeki sensizliğe henüz alışamamışken

Sendeki bensizliğe göz yumdum yıllarca.

Ve artık hiç bir şey eskisi gibi olmayacak

Kuşlara da söyledim ben artık yalnız yaşayacağım,

Ve hiç kimse hiç bir sevdanın hesabını soramayacak benden,

Aşka kapalı mekanlarda olacağım hep

Artık sevdiğim sessizlik olacak kulaklarımda,

Gözlerim yüzlercesi arasından birisini seçmek zorunda kalmayacak

Hafızadan silinecek gereksiz kişilikler 

Ve sevgi sözcükleri ezberlemek zorunda kalmayacağım saatlerce.

En önemlisi cüzdanımda sevdiğimi sandığım kişinin sureti olmayacak.

Sanki o oradayken ben daha mutluyum 

Yada daha emniyette.

Yalan

Oda milyonlarcası gibi fazladan yer kaplıyor

Yani kütlesi var belki ama

Bir damla sevgi yok içinde.

Uzak kalır insana sevgi bazen

Ve hiç bir anlam ifade etmez artık yüreğinde

Sadece kendini kandırarak yaşayacaksın hayatta

Zaten taş bağlamış kalbinde kendine yetecek kadar sevgi vardır.

Muhtaç olmadan hiç bir sevgiye 

Yaşamak en güzelidir aslında.', 'Uzak kalır insana bazen yaşam Ve güneş ısıtamaz artık vücudunun hiç bir yerini, Geceler eskisi gibi değildir Ve ay yansıtma özelliğini çokta...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/savunma-mekanizmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dördüncü Boyuttur.', 'ask-dorduncu-boyuttur-ali-osman-yilmaz-66zk8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün acıların,

Savaşların ve ölümlerin,

Hayatımızı yaşanılmaz kılan,

Dünyamıza şöyle bir bakın,

Yalnız üç boyutuyla,

Görebilirsiniz her şeyi,

Doğarsınız birinci boyutta,

İkinci boyutta yaşarsınız,

Ölüm gelir üçüncü boyutta,

Neredeyseniz bulur sizi,

Ya sevda,ya aşk nerdedir? 

Bulmak için aşkı,sevdayı,

Dördüncü boyuta,

Geçmeniz gerekecektir.

Üç boyutlu evrenin,

Dördüncü boyutu,

Aşktır,sevdadır.

Bütün duyu organlarınızı,

Bir araya toplayıpta,

Geçemiyorsanız o boyuta,

Aşk nedir,sevda nedir,

Nasıl bileceksiniz? 

Öyle zorda değildir,

Aşkı,sevdayı tanımak,

Bırakın kendinizi,

Evrenin sonsuzluğuna,

Derleyin beş duyunuzu,

Karesini alın hemen,

Çıkacaksınız o boyuta.

Tanıyacaksınız o zaman,

Aşkı da,sevdayı da.

Vermeyi öğreneceksiniz,

Almadan ve almayı beklemeden,

Sunacaksınız gönlünüzü,

Sevgiye aç herkese.

İşte öyle bir boyuttur,

Dördüncü boyut,

Aşkın ve sevdanın parametrelerini,

Arıyorsanız eğer,

Dördüncü boyuta geçin hemen,

Aşk da sizin,sevda da sizin,

Binin kanatlarına,uçun birlikte,

Evrenin çiçek bahçeleriyle dolu,

O güzel sevda bahçelerine,

Her bir çiçekte koklayacaksınız,

Aşkın muhteşem rayihasını.

Bu dünyadan bir güzeli severseniz,

Aşkı da sevdayı da unutun,

Aşk yaşamın öteki boyutudur,

Üç boyutta yaşayanlar,

Aşk nedir,sevda nedir,sevgi nedir? 

Asla,ama,asla anlayamazlar.', 'Bütün acıların, Savaşların ve ölümlerin, Hayatımızı yaşanılmaz kılan, Dünyamıza şöyle bir bakın, Yalnız üç boyutuyla, Görebilirsiniz her şey...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ask-dorduncu-boyuttur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller açiyor gözlerim', 'guller-aciyor-gozlerim-sema-gorur-jb8j9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sâkin, sessiz, huzurlu bir gecede

Yildizlar esliginde,

Yepyeni bir hayat''a yelken açiyorum.

Firtinalar dindi, 

Dalgalar sakinlesti,

Yakamoz güzellesti.

Huzurun sesini dinliyorum…

Gün oldu,

Kar tanelerinin gökyüzünden süzülmesinin izledim,

Gün oldu, firtinalarin vurdugu sert tokatlari hissettim,

Ama hep günesin içimi isitmasini bekledim.

Yillarca gökkusaginin pesinden kostum,

Ben yaklastikça, o uzaklasti,

Anladim ki,

Gökkusagini içimde tasiyormusum.

Yildizlar…

Onlara kavusamazsamda

Coskusunu yitirmez yüregim.', 'Sâkin, sessiz, huzurlu bir gecede Yildizlar esliginde, Yepyeni bir hayat''a yelken açiyorum. Firtinalar dindi,  Dalgalar sakinlesti, Yakamoz ...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guller-aciyor-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildirseydi mahali..', 'bildirseydi-mahali-huseyin-umit-cetin-bl5zk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deseki Azrail,

-Sokagını desem,vaktini söylemesem

Geçermiydin oradan, bunu da bilsen? 

Derimki,

İster önünde al,ister sonunda ruhumu

Hergün gecerim içinden,asla degiştirmem yolumu

İşte vakti bugündür deyip tuttugunda kolumu

Can vermek degil,bulmak bilirim sonumu', 'Deseki Azrail, -Sokagını desem,vaktini söylemesem Geçermiydin oradan, bunu da bilsen?  Derimki, İster önünde al,ister sonunda ruhumu Hergün ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bildirseydi-mahali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler(Düşlerin)', 'dortlukler-duslerin-ahmet-aksoy-6urb2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlerin

Bir miğferdir seni koruyan çelikten

Sindiğin derin siperdir seni gizleyen

Kurşunlar vızır vızır üstünden geçerken

Sen dalmış hayallere neyi düşlersin.

Gerçek Mutluluk

Ne kadar güzelsin ne kadar güzel

Bu hayat seninle mutlu ve huzurlu geçer

Ne kadar güzelsin ne kadar güzel

Gerçek mutluluk seni görecek yürek ister.

Yatağıma

Son kez ne zaman sarılacağım sana

Son kez ne zaman saracaksın beni

Ve ne zaman bineceğim sana

Sona giden otobüs.

Baharla Çapraşık

Sarılmak istiyor canım

Sarılmak aşkla

Ama hangi aşkla

Kime sarılmak.

Bekliyor

Başak tarlasinda sürülen, ruhu genç toprak

Aşiliyor insanliga bir umut bir umut daha

Ve bekliyor başaklarin açacagi günü

Bekliyor bitmez tükenmez umutla.', 'Düşlerin Bir miğferdir seni koruyan çelikten Sindiğin derin siperdir seni gizleyen Kurşunlar vızır vızır üstünden geçerken Sen dalmış hayall...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-duslerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdikçe', 'sevdikce-mehmet-kalay-vw97x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoyrat rüzgar, es delicesine bedenime.

Kavur yüreğimi mahşerde, cehennem ateşinde...! 

Günahkarım ben...! 

Günahkarrrr...! 

Umutsuzca sevdim, suçluyum...! 

Yaşam boyu ver cezamı, yaşadıkça...! 

Onu, onsuz sevdikçe...! 

Cehennem olsun azap yerim, aşkıma kavuşmadıkça...! 

Ya beni ona ver, Ya beni al...! 

Çaresizce.

27.12.2003 - İstanbul', 'Hoyrat rüzgar, es delicesine bedenime. Kavur yüreğimi mahşerde, cehennem ateşinde...!  Günahkarım ben...!  Günahkarrrr...!  Umutsuzca sevdim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdikce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehriban, Deniz ve Ölüm', 'sehriban-deniz-ve-olum-oguzkan-bolukbasi-qcy2z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu deliler dünyasında sıkıştım kaldım

Geceyi gündüze çevirmeye dermanım yok

Bir çiçek diktim

Bin çiçek aldım

Lakin ruhum akıllıya aç

Deliye tok

Çılgınlığa uçuyorum kanatlandım

Karanlık bir denizdeyim

Açmışım yelkenleri

Umut mudur kayalıklarda duran deniz fenerleri

Yoksa gözlerin gibi ufuk mudur varılmayan 

Bilinmez

Ağaçlar öksüz kalır mı

Gölgesinde bir aşkın yemininin verilmediği

Dalların gözyaşlarını gördün mü

Bir çınarın ağladığını

Ormanların niye yandığını bilir misin

Denizlere gel

Karası olmayan denizlere

Limansız

Uykusuz denizlere

Derinden iyot kokusu dolarken genizlere

Tayfaların şarkısını dinle

Madem ki ulaşamıyoruz bir yere

Bir deniz kızı hayal et 

Her yeri balık

Her yeri kız

Anlatacak ne varsa ona anlat

Sonra denize at

O da sulara anlatsın yalnız

Denizin ağladığını gördün mü

Bulutlara verir göz yaşlarını

Siz adına yağmur dersiniz

Biz deniz ağlaması

Zordur duygularını saklaması

Hem ağlar

Hem köpürür

Dalga dalgadır 

Hırçın saçları

Bu deliler dünyasında sıkıştım kaldım

Sular durulmuyor

Fırtına dinmiyor

Sevgilim gözlerini hangi geceye çevirmişse

Güneş doğmuyor

Kırmızı pazenden bir fistan giymiştin ayrılırken

Beli incecik lastikli

Kolları kısa

Şehriban’ dı adın manasını bilmeyiz

Sevgilim bilirlerdi

Ağlar örülürdü kıvırcık saçlarında

Nefesim kesilirdi

Senden kaçtığım yer denizlerdi

Beklemen güzeldi sahilde

Ağacımız büyürdü

Deliydik ikimiz de 

Kaçık

Açık seçik severdik

De söylemezdik doğrudan

Öldük

Bu büyük aşkın büyüsünde

Gemiler dönmedi

Karalar görünmedi

Şehriban’ın gözleri

Yakamadı fenerleri

Çarptığımız kayalarda parçalandık

Kimse inanmaz

Okyanuslar ortasında yandık

Elimizi uzattığımız köpekbalıklarını

Deniz kızları sandık

Öldük 

“ölümden bir şeyler umarak”', 'Bu deliler dünyasında sıkıştım kaldım Geceyi gündüze çevirmeye dermanım yok Bir çiçek diktim Bin çiçek aldım Lakin ruhum akıllıya aç Deliye ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/sehriban-deniz-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabusumsun', 'kabusumsun-mehmet-kalay-87gmy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soruyorum seni, eski dostlara.

Arıyorum bir telaş, bir heyecan.

Yüreğimde depremler olmus, sehir enkaz.

Soruyorum, koşuyorum umutsuzca.

Tanıdık tanımadık herkese.

Saklıyorlar seni benden telaşla, sıkışıyorlar köşeye.

''Arkadaşıylaydı, tiyatrodaydı'' diyorlar.

Koşarken sel göz yaşlarıyla, bedenini görüyorum enkazlar arasında.

Sarılıyorum cansız bedenine, kısık kısık haykırıyorum. 

Hayır...! Hayır...! Hayır...! 

Uyanıyorum ağlarken, gerçekle düş arasında.

Islanırken yüzüm hıçkırıyorum, şükrediyorum rabbıma.

Yaşananların kabus olduğuna.

27.12.2003 - İstanbul', 'Soruyorum seni, eski dostlara. Arıyorum bir telaş, bir heyecan. Yüreğimde depremler olmus, sehir enkaz. Soruyorum, koşuyorum umutsuzca. Tanı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kabusumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ders', 'ders-umut-ulbegi-chapx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanmadan

yaralanmadan

Nabzıma dayanmadan

gözlerim bağlanmadan seveceğim

Birinci ders

yüreğimle

yakın dövüş

yenilmeyeceğim.', 'Yanmadan yaralanmadan Nabzıma dayanmadan gözlerim bağlanmadan seveceğim Birinci ders yüreğimle yakın dövüş yenilmeyeceğim....', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ders-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Beni', 'affet-beni-mehmet-kalay-5zwk9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bardaklar, şişeler dönüyor etrafımda, içiyorum sensiz.

Kalkan her kadehte sen varsın.

Sensiz çekilmiyor, sensizliğin acısı.

Vuruyor hırçın dalgalar gibi yüreğime.

Bazen hafifçe, bazen şiddetle.

Pişiyorum aşkımın ateşinde, kavruluyorum yaşamın içinde.

Sensiz...! 

Yumuşatırken sevginin eşsiz sosu, lezzetli yemek oluyorum.

Diz çöküp önüne, afffet...! 

Affet beni diyerek. 

27.12.2003 - İstanbul', 'Bardaklar, şişeler dönüyor etrafımda, içiyorum sensiz. Kalkan her kadehte sen varsın. Sensiz çekilmiyor, sensizliğin acısı. Vuruyor hırçın d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/affet-beni-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Yeniden Doğuracak Kadın II', 'beni-yeniden-doguracak-kadin-ii-umut-ulbegi-nwfqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün 

sessizliğe mahkumum 

çekildim kabuğuma 

yedi deniz üstümde yorgan 

en uzak diyarlarındayım hayatın 

Bugün 

yalnızlığa mahkumum 

çekilmiş kahve gibi unufağım 

ve en tenha köşesindeyim 

kese kağıdının 

Bugün

ölüme mahkumum 

diri diri yemekteyim yüreğimi 

ve en uzun yolundayım 

kan dolaşımımın 

Dün 

yok olan bedenimi 

yeniden doğuracak 

tek kadın

düşürdü beni

bir kez olsun yeni gözlerimle 

göremeden gözlerini', 'Bugün  sessizliğe mahkumum  çekildim kabuğuma  yedi deniz üstümde yorgan  en uzak diyarlarındayım hayatın  Bugün  yalnızlığa mahkumum  çekil...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beni-yeniden-doguracak-kadin-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Senle, Bazen Sensiz', 'bazen-senle-bazen-sensiz-mehmet-kalay-u55ko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duyuyorum seni, dilinden çıkan sözler yetmiyor bana.

Nefret duygularımı uyandıramıyorlar bile.

Biliyorsun, her biri için geçerli nedenlerim var.

Cevap verilmesi bile zor nedenler.

Kazaya ugramış sevgimiz, adanmış yaşamda.

Derin yaralar, acı dertler içindeyiz.

Aşkımsın...! 

Sevdiğimsin...! 

Tutkumsun...! 

Yalnızlığımsın...! 

Sensiz olmuyor, yerin dolmuyor...! 

Yanıyorum mum alevinde...! 

Bazen senle, bazen sensiz.

27.12.2003 - İstanbul', 'Duyuyorum seni, dilinden çıkan sözler yetmiyor bana. Nefret duygularımı uyandıramıyorlar bile. Biliyorsun, her biri için geçerli nedenlerim ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bazen-senle-bazen-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisi Gibi', 'eskisi-gibi-mehmet-kalay-0opi0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuş olup uçsam, pencerene konsam...! 

İçeri alırmısın beni? 

Sevip okşarmısın? 

Sıcacık kucağına alırmısın? 

Öpermisin? 

Kuş olup uçsam, mutluluktan taklalar atsam...! 

Yine severmisin beni? 

Eskisi gibi...! 

27.12.2003 - İstanbul', 'Kuş olup uçsam, pencerene konsam...!  İçeri alırmısın beni?  Sevip okşarmısın?  Sıcacık kucağına alırmısın?  Öpermisin?  Kuş olup uçsam, mut...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eskisi-gibi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrim Gibisin', 'sehrim-gibisin-mestan-ozyer-h1etd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehrin geceleri

aydınlık gündüz gibi

gelip sarmalar beni 

pencereme yakın ay

Sen şehrim gibisin

hep devinir saçların

bir hilal

bir dolunay

Ah İzmir

Ne diyeyim ben sana

(Aralık 2003)', 'Bu şehrin geceleri aydınlık gündüz gibi gelip sarmalar beni  pencereme yakın ay Sen şehrim gibisin hep devinir saçların bir hilal bir doluna...', ARRAY['Türk Edebiyatı','Şiir','Mestan Özyer']::text[], 8.5, '{"poet":"Mestan Özyer","poet_slug":"mestan-ozyer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sehrim-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-mehmet-kalay-b195i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaptınız küçük hesaplar,ulaştınız amacınıza.

Koparttınız kahpe tuzaklarınızla, elimi kolumu.

Açtınız derin yaralar, bi çare bedenimde.

İftiralarınız zaferlerinizi taçlandırıken, karanlıklarda buluştunuz.

Zafer sarhoşluğunuzda korktunuz aniden.

Buldunuz bi çare bedenimi, elsiz bacaksız koşarken.

Umrumda değilsiniz artık...! 

Defalarca yendim, yine yeneceğim sizi...! 

Zaferiniz tektir, iyi bilin...! 

Öylesine dağladınız ki onu, mahşere kadar sızlayacak yüreğim.

Seneler senesi, 

Ağlayacak, kanayacak.

25.12.2003 -İstanbul', 'Yaptınız küçük hesaplar,ulaştınız amacınıza. Koparttınız kahpe tuzaklarınızla, elimi kolumu. Açtınız derin yaralar, bi çare bedenimde. İftir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuregim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Senin, Yokluğun Benim', 'i-stanbul-senin-yoklugun-benim-umut-ulbegi-kae7y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul

şimdi yalnız 

benim gibi

üstümden bulutlar geçiyor

unutuluyorum

kız kulesi aynadaki aksim

Hero da söndürdü son feneri bak

Ah Leandros! 

nerede efsanelerim? 

İstanbul

şimdi soğuk

benim gibi

rayları buz tutmuş

kara trenlerin

donuyor uzun yol gecelerim 

sana dair ne varsa

İstanbul''da

başlangıcı senin

sonu benim.', 'İstanbul şimdi yalnız  benim gibi üstümden bulutlar geçiyor unutuluyorum kız kulesi aynadaki aksim Hero da söndürdü son feneri bak Ah Leandr...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istanbul-senin-yoklugun-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affedermisin Beni', 'affedermisin-beni-mehmet-kalay-dgdsj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden milyonlarca defa özürler dilesem,

Kapansam ayaklarına.

Elindeki kalem, kağıt olsam.

Bardağın, içtiğin su olsam.

Tabağında yemek, elinde çatalın olsam.

Havlun olsam, seni okşasam.

Camında minik bir şakayık olsam,

Ellerimde çiçeklerle sana gelsem.

Tabularını yıkıp, inadından vazgeçsen.

Bu defa beni çöpe atmayıp, sarsan.

Kendine alsan...! 

Affedermisin beni? 

25.12.2003 - İstanbul', 'Senden milyonlarca defa özürler dilesem, Kapansam ayaklarına. Elindeki kalem, kağıt olsam. Bardağın, içtiğin su olsam. Tabağında yemek, elin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/affedermisin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Dönersen', 'bir-gun-donersen-umut-ulbegi-g6tfg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün

geri dönersen

koltuk altımdaki tavlayı al

bir gün

dönersen

on iki ekimi

kül tablandaki izmaritlerimi

şarap kadehindeki parmak izimi

evine bıraktığım son geceyi

dönüş yolundaki her kelimeyi

kapı önü öpüşmeleri

konuşmadan söylediklerimi

getir...

Dudakların kalsın

dönersen

sende nasıl kaldığımı

anlarsın', 'Bir gün geri dönersen koltuk altımdaki tavlayı al bir gün dönersen on iki ekimi kül tablandaki izmaritlerimi şarap kadehindeki parmak izimi ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gun-donersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudak Meselesi', 'dudak-meselesi-umut-ulbegi-q2nqd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duvarlar yıkılmıştı

neredeydi isimsiz duvar örücüleri

ıssız sokakların bekçi düdükleri

içimde yankılanıyordu

Camlar kırılmıştı

neredeydi isimsiz şehir camcıları

kaldırımda kırıklarından yansıyan sokak lambaları

usumu aydınlatıyordu

Duvarları 

ve 

camları 

feda ettim sana

koca şehri yıkamadım 

belki 

sen istemedin yıkıntıları

Koşa koşa geldim sana

neredeydin? 

çatlamıştı dudaklarım.', 'Duvarlar yıkılmıştı neredeydi isimsiz duvar örücüleri ıssız sokakların bekçi düdükleri içimde yankılanıyordu Camlar kırılmıştı neredeydi isi...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dudak-meselesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut Öyküsü', 'bir-umut-oykusu-nurullah-zafer-okur-4ok26', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Offff

Uzaksın ya şimdi

Böyle yüreğimden öte

İçimden gittin ya kopup

Belki kısa bir süre

Yandı içim yandı inan

Acımasızca durmaksızın

Titrek bir mum ışığıyla

Geceyi, karanlık bulutları aydınlattımda

Sensizlikden kararan içime

Tesir edemedim be gülüm

Hani birazlığına gittin ya

Öyle kopup taa derin bi yerinden içimin

Öyle bir karanlıktıki gülüm

Siyahlığıyla meşhur geceyi

Gözlerinin siyahını bide

Kıskandırdın bilmeden gittin ya..

Şimdi sen gittin ya hani cevapsız

Soruları anlamsız bakışları

Bide canı çıkasızca sensizliği

Koyuverip kucağıma hani birazlığına

Kattım ya bende mevsimi mevsimlere 

Ümitlerim gözlerimin altında çökmüş

Gözledim ya çıktığın yeşil boyalı kapıyı

Hani çarptığın çıkarken bi buruk

Yıllarca

Öyle bi bakmak geldi aklıma

Yeşil senin çıktığın kapıdan başka yere

Aynada tanıştık 

Beyaz saçlı buruşuk yüzlü adamla

Senin hikayeni anlattı

Üzüldüm acıklıydı çok.Hatta ağladım onunla 

Biraz ama çok değil biliyorum kızarsın sen

Okadar çok şey biriktirdimki

Bana verdiğin yeleğimin cebinde

sana anlatacak daha

Sen gel gülüm..

Tamammı gel sen..

Hepsini paylaşacağım seninle

Cebindeki yeleğimin

senin verdiğin..

Bekliyorum seni yeşil boyalı

Boyası dökülmüş kapının ardında

Çalmadan gir açamam çünki

Tutmuyor artık sensizlikden donmuş ellerim

Gel gülüm

Hadi gel..', 'Offff Uzaksın ya şimdi Böyle yüreğimden öte İçimden gittin ya kopup Belki kısa bir süre Yandı içim yandı inan Acımasızca durmaksızın Titrek ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Zafer Okur']::text[], 8.5, '{"poet":"Nurullah Zafer Okur","poet_slug":"nurullah-zafer-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-umut-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-ferit-teksoy-uwphj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürektedir,bakıştadır

Ne ülke ne sınır tanır

Ne rengi var ne yaşlanır

Ucube birşeydir sevgi..

***

Dil tanımaz,din tanımaz

Gelenek,anane tınmaz

Yasak koyarsın aldırmaz

Aksi ve asidir sevgi..

***

Karşılıksız hasta eder

Çok nadiren uzun sürer

Çıtkırıldım,çeker gider

Su ister,çiçektir sevgi..

***

Uzattınız alan varsa

Frekanslar da uyarsa

Verdiğince alınırsa

En güzel ikramdır sevgi

***

Güzel şeylerle beslenir

Sözle,bakışla hislenir

Her bahar açar süslenir

Biraz da mevsimdir sevgi..

***

Şanlıurfa isot''unda

Hemşin''in pasta tadında	

Acı,tatlı..damağında

Tatlar bıraktırır sevgi..

***

Hislendirir şair eder

Kıskandırır katil eder

İlgi yoksa uçar gider

Seven yürek ister sevgi..

***

Kapı açıksa çalmaya

Yürek hazırsa dolmaya

Akıl uyarsa çelmeye

Kilidi bindirir sevgi..

28 Aralık 2003', 'Yürektedir,bakıştadır Ne ülke ne sınır tanır Ne rengi var ne yaşlanır Ucube birşeydir sevgi.. *** Dil tanımaz,din tanımaz Gelenek,anane tınm...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevgi-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Armagan...', 'armagan-dilek-farhood-lkr9a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu bebek icin dedi,

ellerim titredi

acarken paketi...

Hep kendim icin isterdim

onceden hediyeleri

ama bu senin icindi

sana gelen ilk hediyeyi aciyordum

iste o zaman anladim ki 

sen once geleceksin artik,

herseyden once...', 'Bu bebek icin dedi, ellerim titredi acarken paketi... Hep kendim icin isterdim onceden hediyeleri ama bu senin icindi sana gelen ilk hediyey...', ARRAY['Türk Edebiyatı','Şiir','Dilek Farhood']::text[], 8.5, '{"poet":"Dilek Farhood","poet_slug":"dilek-farhood","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/armagan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kırıklığı-1-*', 'hayal-kirikligi-1-bayram-tunca-ng0iw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayal kırıklığım, cam kırıklarından daha çok 

Teselli edecek senden başka bir dostum yok 

Döküldü ümitlerim, sonbahar yaprakları gibi 

